# SizingAgent v2 (2026-06-01) — cheap aggregator for the kill-switch daily PnL.
# Sums today's resolved paper+live PnL across all four scanners. Cached for
# ~30s so the hot-path sizing wrap doesn't recompute on every .size() call.
# Falls back to 0.0 on any error (kill switch stays dormant rather than blocking).
import time as _t_pnl_cache_time
_PNL_CACHE = {'ts': 0.0, 'value': 0.0}
_PNL_CACHE_TTL_S = 30.0

def _sizing_agent_daily_pnl_cached() -> float:
    """Cheapest aggregator we can build without invoking api_daily_pnl()
    (which calls jsonify and only works inside a Flask request context).
    Reads each scanner's in-memory _trades list (Picks via _load_paper_log)
    and sums today's resolved pnl. Best-effort; any error -> 0.0."""
    now = _t_pnl_cache_time.time()
    if (now - _PNL_CACHE['ts']) < _PNL_CACHE_TTL_S:
        return _PNL_CACHE['value']
    total = 0.0
    try:
        from datetime import datetime as _dt, timezone as _tz
        today = _dt.now(_tz.utc).strftime('%Y-%m-%d')
        _local_tz = _dt.now().astimezone().tzinfo
        def _is_today(t):
            la = t.get('logged_at') or ''
            if not la: return False
            if la.endswith('+00:00') or la.endswith('Z'):
                return la.startswith(today)
            try:
                d = _dt.fromisoformat(la.replace('Z','+00:00'))
                if d.tzinfo is None:
                    d = d.replace(tzinfo=_local_tz)
                return d.astimezone(_tz.utc).strftime('%Y-%m-%d') == today
            except Exception:
                return la.startswith(today)
        for name in ('hft_scanner', 'btc_ml_scanner', 'eth_ml_scanner', 'claude_scanner'):
            sc = globals().get(name)
            if sc is None:
                continue
            try:
                if name == 'claude_scanner' and hasattr(sc, '_load_paper_log'):
                    trades = sc._load_paper_log() or []
                else:
                    with sc._lock:
                        trades = list(sc._trades)
            except Exception:
                continue
            for tr in trades:
                if not tr.get('resolved'): continue
                if tr.get('outcome') not in ('WIN', 'LOSS'): continue
                if not _is_today(tr): continue
                total += float(tr.get('pnl') or tr.get('paper_pnl') or 0.0)
    except Exception:
        total = 0.0
    _PNL_CACHE['ts'] = now
    _PNL_CACHE['value'] = round(total, 4)
    return _PNL_CACHE['value']

