    if not pk:
        issues.append("PRIVATE_KEY is unset")
    elif str(pk).strip().upper().startswith("ENC:"):
        issues.append(
            "PRIVATE_KEY is still encrypted (starts with ENC:). "
            "Set MASTER_PASSWORD to match grok.salt, or run in an interactive terminal to enter it."
        )
