# ──────────────────────────────────────────────────────────────────────────────
# SESSION-AWARE KELLY MULTIPLIER (per Monday journal #43 idea #2)
# US_AFT (12-19 UTC) is highest-quality session — full size.
# OVERNIGHT/ASIA periods bleed disproportionately — half size.
# US_OPEN is in between.
# ──────────────────────────────────────────────────────────────────────────────
def _session_kelly_mult() -> float:
    h = datetime.now(timezone.utc).hour
    if 12 <= h < 20:    return 1.0    # US_AFT
    if 8  <= h < 12:    return 0.7    # US_OPEN
    return 0.5                        # ASIA (0-7) + OVERNIGHT (20-23)

# ──────────────────────────────────────────────────────────────────────────────
# CROSS-SYMBOL CORRELATION GATE (per Monday journal #43 idea #5)
# BTC/ETH/SOL/BNB are 0.7-0.9 correlated on 5m moves. A same-direction live
# trade on a correlated symbol within 60s of another is effectively a 2-3x
# stake on a single binary outcome — when the underlying market moves against
# the direction, all bets lose simultaneously (e.g. tonight's 01:24 batch:
# XRP DOWN + SOL DOWN + ETH DOWN within 6 sec, all three lost).
# Track recent live entries and skip correlated same-direction trades within
# the cooldown window.
# ──────────────────────────────────────────────────────────────────────────────
import threading as _corr_threading
_correlation_lock = _corr_threading.Lock()
_recent_live_entries: dict = {}  # {symbol_upper: (direction, ts)}
_CORRELATED_GROUP = {'BTC', 'ETH', 'SOL', 'BNB', 'XRP'}  # high-correlation crypto cluster
_CORRELATION_WINDOW_SECS = 60.0

def _correlation_check(symbol: str, direction: str) -> tuple:
    """(allow: bool, reason: str). Blocks live entry if a correlated symbol had
    a same-direction live trade within the last 60s."""
    sym_u = (symbol or '').upper()
    if sym_u not in _CORRELATED_GROUP:
        return True, ''
    dir_u = (direction or '').upper()
    now = time.time()
    with _correlation_lock:
        # Drop stale entries
        for s in list(_recent_live_entries.keys()):
            if now - _recent_live_entries[s][1] > _CORRELATION_WINDOW_SECS:
                del _recent_live_entries[s]
        for s, (d, ts) in _recent_live_entries.items():
            if s == sym_u or s not in _CORRELATED_GROUP:
                continue
            if d == dir_u and (now - ts) < _CORRELATION_WINDOW_SECS:
                return False, f'corr-block: {s} {d} placed {now-ts:.0f}s ago'
    return True, ''

def _correlation_record(symbol: str, direction: str):
    """Record a successful live entry for correlation tracking."""
    sym_u = (symbol or '').upper()
    if sym_u not in _CORRELATED_GROUP:
        return
    with _correlation_lock:
        _recent_live_entries[sym_u] = ((direction or '').upper(), time.time())

# ──────────────────────────────────────────────────────────────────────────────
# WEEKEND MODE — segregates ML/RL state into weekend variants during a configured
# time window so weekend market regime doesn't pollute weekday-learned tables.
#
# Config file: weekend_mode.json
#   {"enabled": true, "start_ts": <epoch>, "end_ts": <epoch>, "note": "..."}
#
# How it works:
#   - During [start_ts, end_ts), each affected ML/RL class loads/saves to a
#     "<base>.weekend.<ext>" file instead of "<base>.<ext>".
#   - At end_ts, the watchdog thread os.execv-restarts the process; on restart
#     mode is False so classes load from weekday files again.
#   - BTCMLModel retraining is skipped during weekend mode (weekend weights
#     stay as the seeded weekday copy; only RL Q-tables adapt).
# ──────────────────────────────────────────────────────────────────────────────

_WEEKEND_MODE_FILE  = 'weekend_mode.json'
_WEEKEND_MODE_CACHE = {'mtime': 0.0, 'data': None}

def _weekend_mode_config() -> dict:
    """Read weekend_mode.json with mtime caching. Returns {} if absent/invalid."""
    path = os.path.join(os.path.dirname(os.path.abspath(__file__)), _WEEKEND_MODE_FILE)
    try:
        mtime = os.path.getmtime(path)
    except OSError:
        _WEEKEND_MODE_CACHE['mtime'] = 0.0
        _WEEKEND_MODE_CACHE['data']  = None
        return {}
    if mtime != _WEEKEND_MODE_CACHE['mtime']:
        try:
            with open(path, encoding='utf-8') as _f:
                _WEEKEND_MODE_CACHE['data']  = json.load(_f) or {}
            _WEEKEND_MODE_CACHE['mtime'] = mtime
        except Exception:
            _WEEKEND_MODE_CACHE['data'] = {}
    return _WEEKEND_MODE_CACHE['data'] or {}

_WEEK_SECONDS = 7 * 86400

def _current_weekend_window() -> tuple:
    """Return (start_ts, end_ts) of the active-or-next weekend window, or (None, None).
    For recurring configs, rolls the anchor forward by whole weeks."""
    cfg = _weekend_mode_config()
    if not cfg.get('enabled'):
        return (None, None)
    anchor_start = cfg.get('start_ts', 0) or 0
    anchor_end   = cfg.get('end_ts', 0)   or 0
    duration     = anchor_end - anchor_start
    if duration <= 0 or anchor_start <= 0:
        return (None, None)
    if not cfg.get('recurring'):
        return (anchor_start, anchor_end)
    now = time.time()
    if now < anchor_start:
        return (anchor_start, anchor_end)
    n = int((now - anchor_start) // _WEEK_SECONDS)
    cur_start = anchor_start + n * _WEEK_SECONDS
    cur_end   = cur_start + duration
    if now >= cur_end:
        cur_start += _WEEK_SECONDS
        cur_end   += _WEEK_SECONDS
    return (cur_start, cur_end)

def _is_weekend_mode_now() -> bool:
    cfg = _weekend_mode_config()
    if not cfg.get('enabled'):
        return False
    anchor_start = cfg.get('start_ts', 0) or 0
    anchor_end   = cfg.get('end_ts', 0)   or 0
    duration     = anchor_end - anchor_start
    if duration <= 0 or anchor_start <= 0:
        return False
    now = time.time()
    if not cfg.get('recurring'):
        return anchor_start <= now < anchor_end
    if now < anchor_start:
        return False
    elapsed_in_cycle = (now - anchor_start) % _WEEK_SECONDS
    return elapsed_in_cycle < duration

def _resolve_state_path(filename: str) -> str:
    """Return path to base file or .weekend variant depending on current mode.
    Always anchored to this script's directory."""
    base_dir = os.path.dirname(os.path.abspath(__file__))
    if not _is_weekend_mode_now():
        return os.path.join(base_dir, filename)
    root, ext = os.path.splitext(filename)
    return os.path.join(base_dir, f'{root}.weekend{ext}')

def _other_mode_state_path(filename: str) -> str:
    """Return path to the OPPOSITE mode's state file (used for shadow-gate
    comparisons). Inverse of _resolve_state_path: in weekend mode returns the
    base file; in weekday mode returns the .weekend variant."""
    base_dir = os.path.dirname(os.path.abspath(__file__))
    if _is_weekend_mode_now():
        return os.path.join(base_dir, filename)
    root, ext = os.path.splitext(filename)
    return os.path.join(base_dir, f'{root}.weekend{ext}')

_SHADOW_GATE_CACHE: dict = {}  # filename -> (mtime, parsed_state)

_JSON_CACHE: dict = {}  # abspath -> (mtime, parsed_data)

# 2026-05-23 PR-5: orjson swap on hot save paths. ~5-8x faster serialization
# than stdlib json.dumps on the trade-log + shadow-log files. Falls back to
# stdlib if orjson isn't installed or raises on an exotic type (e.g. a set or
# a non-stringable object the existing default=str would have stringified).
try:
    import orjson as _orjson
    _ORJSON = True
except ImportError:
    _orjson = None
    _ORJSON = False

def _atomic_write_json(path: str, obj, *, indent: bool = False, default=str,
                       replace_retries: int = 3):
    """Write `obj` as JSON to `path` atomically (write to tmp, then os.replace).
    Uses orjson when available for speed; falls back to stdlib json on any
    error. On Windows, os.replace can briefly fail if another reader has the
    file open — `replace_retries` retries up to N times with a short sleep.

    `indent=True` produces 2-space indented output (slower; for human-readable
    config files). `indent=False` is the hot-path default.
    """
    import uuid as _u, time as _time
    tmp = path + f'.tmp_{_u.uuid4().hex[:8]}'
    wrote = False
    if _ORJSON:
        try:
            opt = _orjson.OPT_INDENT_2 if indent else 0
            data = _orjson.dumps(obj, default=default, option=opt)
            with open(tmp, 'wb') as f:
                f.write(data)
            wrote = True
        except (TypeError, _orjson.JSONEncodeError):
            wrote = False
    if not wrote:
        if indent:
            with open(tmp, 'w', encoding='utf-8') as f:
                json.dump(obj, f, indent=2, default=default)
        else:
            with open(tmp, 'w', encoding='utf-8') as f:
                json.dump(obj, f, default=default)
    last_err = None
    for attempt in range(max(1, replace_retries)):
        try:
            os.replace(tmp, path)
            return
        except OSError as e:
            last_err = e
            if attempt < replace_retries - 1:
                _time.sleep(0.05)
    # All retries failed — clean up tmp and re-raise
    try: os.remove(tmp)
    except OSError: pass
    raise last_err

def _load_json_cached(path: str, default=None):
    """Mtime-cached JSON load for polled Flask endpoints.

    Cold path: full open+parse. Warm path: stat() + dict lookup.
    Safe with writers that use atomic os.replace() (mtime changes on swap).
    Returns ``default`` if the file is missing or unparseable.

    READ-ONLY contract: the returned object IS the cached object. Callers must
    not mutate it. If you need to mutate, copy first (or use the dedicated
    `_load_paper_log` which returns `list(cached)`).
    """
    try:
        mtime = os.path.getmtime(path)
    except OSError:
        return default if default is not None else None
    cached = _JSON_CACHE.get(path)
    if cached and cached[0] == mtime:
        return cached[1]
    try:
        with open(path, 'r', encoding='utf-8') as f:
            data = json.load(f)
    except Exception:
        return default if default is not None else None
    _JSON_CACHE[path] = (mtime, data)
    return data

def _load_shadow_gate_state(filename: str) -> dict:
    """Read other-mode RL state file (mtime-cached). Returns {} if absent or
    unparseable — shadow comparisons are best-effort and never crash the bot."""
    path = _other_mode_state_path(filename)
    try:
        mtime = os.path.getmtime(path)
    except OSError:
        return {}
    cached = _SHADOW_GATE_CACHE.get(filename)
    if cached and cached[0] == mtime:
        return cached[1]
    try:
        with open(path, encoding='utf-8') as f:
            data = json.load(f) or {}
    except Exception:
        return {}
    _SHADOW_GATE_CACHE[filename] = (mtime, data)
    return data

def _log_gate_compare(record: dict):
    """Append a gate-comparison record. Mode-segregated via _resolve_state_path
    so weekend shadow-tests never combine with weekday shadow-tests. Append-only,
    race-free. Analysis joins to trade outcomes by state_key + ts."""
    try:
        path = _resolve_state_path('hft_gate_compare.jsonl')
        with open(path, 'a', encoding='utf-8') as f:
            f.write(json.dumps(record, default=str) + '\n')
    except Exception as _e:
        pass  # never let logging break trading

# ──────────────────────────────────────────────────────────────────────────────
# Q-VALUE TIME DECAY
# ──────────────────────────────────────────────────────────────────────────────
# RL Q-values reflect outcomes from past trades. In a regime-shifting market
# (crypto), a state that lost consistently last week may be profitable this
# week. Without time-decay, blocked states stay blocked forever — never
# re-tested even if conditions improve.
#
# Decay applied lazily during periodic sweep (per RL class). 7-day half-life
# means a Q=-1.0 state takes ~3 weeks of inactivity to thaw above the -0.15
# block threshold. States touched recently (n>0 update) are unaffected since
# their last_ts is fresh.
# ──────────────────────────────────────────────────────────────────────────────

def _apply_q_decay(entry: dict, half_life_hours: float) -> bool:
    """Mutate entry in place — multiply Q by 0.5^(hours_since_last/half_life).
    Initializes last_ts if missing. Returns True if Q was modified materially.
    Skips entries already touched within the last few seconds (no-op)."""
    now = time.time()
    last = entry.get('last_ts')
    if last is None:
        entry['last_ts'] = now
        return False
    hours_stale = (now - last) / 3600.0
    if hours_stale <= 0.001:
        return False
    decay = 0.5 ** (hours_stale / half_life_hours)
    if decay > 0.99995:   # < 0.005% drift — not worth saving
        return False
    entry['q']       = round(entry['q'] * decay, 6)
    entry['last_ts'] = now
    return True

def _start_dirty_flush_loop(rl_instance, log_label: str, interval_s: float = 1.0):
    """Background flusher: saves rl_instance to disk every `interval_s` only when
    `_dirty` is set. Coalesces bursts of updates into a single write — turns N
    saves per outcome batch into 1 save per second worst case. Replaces per-update
    `self._save()` calls in RL update() methods."""
    def _run():
        time.sleep(2)
        while True:
            time.sleep(interval_s)
            try:
                if getattr(rl_instance, '_dirty', False):
                    rl_instance._dirty = False
                    rl_instance._save()
            except Exception as _e:
                logger.warning(f'[{log_label}] dirty flush error: {_e}')
    threading.Thread(target=_run, daemon=True,
                     name=f'{log_label.lower()}-flush').start()

def _start_q_decay_sweeper(rl_instance, log_label: str, half_life_hours: float = 168.0,
                           interval_s: int = 3600):
    """Spawn a daemon thread that hourly applies _apply_q_decay() to every
    state in rl_instance.q (or rl_instance._q for BTCMLRl). Saves on change.
    7-day half-life by default — Q halves every week of inactivity."""
    def _run():
        time.sleep(60)   # let bot init
        while True:
            time.sleep(interval_s)
            try:
                table = getattr(rl_instance, 'q', None)
                if table is None:
                    table = getattr(rl_instance, '_q', None)
                if not isinstance(table, dict) or not table:
                    continue
                n_changed = 0
                for key, entry in list(table.items()):
                    if _apply_q_decay(entry, half_life_hours):
                        n_changed += 1
                if n_changed and hasattr(rl_instance, '_save'):
                    rl_instance._save()
                    logger.info(f'[{log_label}] Q-decay applied to {n_changed} states (7-day half-life)')
            except Exception as _e:
                logger.warning(f'[{log_label}] Decay sweep error: {_e}')
    threading.Thread(target=_run, daemon=True,
                     name=f'{log_label.lower()}-decay').start()


# ── AUTO-PAUSE GATE ─────────────────────────────────────────────────────────
# Per-strategy circuit breaker: if a strategy bleeds in any rolling 30-min window
# OR strings together N consecutive losses, force-paper that strategy until the
# top of the next hour. Catches regime-shift accidents (like the 5/15 05:00 UTC
# "12 DOWN bets in 30 min" episode that lost ~$50). Self-restores at hour
# boundary so trader doesn't have to babysit.
class AutoPauseGate:
    """One-class gate that scanner code calls in two places:
       - record_resolved(strategy, pnl, ts) after each real trade resolves
       - is_paused(strategy) before each live order
    State persists to auto_pause_state.json so it survives bot restarts."""
    STATE_FILE        = 'auto_pause_state.json'
    CONSEC_LOSS_LIMIT = 3       # consecutive losses to trigger
    ROLLING_WINDOW_S  = 30 * 60 # 30-minute rolling window
    ROLLING_PNL_LIMIT = -25.0   # rolling-window PnL trigger threshold

    def __init__(self):
        self._lock = threading.Lock()
        self._paused: dict = {}   # strategy -> unpause_unix_ts (float)
        self._recent: dict = {}   # strategy -> list[(ts, pnl)]
        self._consec: dict = {}   # strategy -> int (consec losses)
        self._load()

    def _load(self):
        try:
            p = _resolve_state_path(self.STATE_FILE)
            if os.path.exists(p):
                with open(p, 'r', encoding='utf-8') as f:
                    d = json.load(f)
                self._paused = {k: float(v) for k, v in d.get('paused', {}).items()}
                # Drop expired entries on load
                now = time.time()
                self._paused = {k: v for k, v in self._paused.items() if v > now}
        except Exception as e:
            logger.warning(f'[AUTO-PAUSE] Load error: {e}')

    def _save(self):
        try:
            p = _resolve_state_path(self.STATE_FILE)
            tmp = p + f'.tmp_{os.getpid()}'
            with open(tmp, 'w', encoding='utf-8') as f:
                json.dump({'paused': self._paused, 'updated': datetime.now(timezone.utc).isoformat()}, f, indent=2)
            os.replace(tmp, p)
        except Exception as e:
            logger.warning(f'[AUTO-PAUSE] Save error: {e}')

    def unpause(self, strategy: str = None) -> list:
        """Manually clear pause for one or all strategies. Returns list of
        strategies that were actually cleared. Used by TG override commands
        so the operator can re-enable trading without waiting for the next
        hour boundary."""
        with self._lock:
            if strategy:
                if strategy in self._paused:
                    self._paused.pop(strategy, None)
                    self._consec[strategy] = 0
                    self._save()
                    return [strategy]
                return []
            cleared = list(self._paused.keys())
            self._paused.clear()
            self._consec.clear()
            self._save()
            return cleared

    def is_paused(self, strategy: str) -> bool:
        if not strategy: return False
        with self._lock:
            unpause_ts = self._paused.get(strategy, 0)
            if unpause_ts <= time.time():
                # Expired — clean up
                if strategy in self._paused:
                    self._paused.pop(strategy, None)
                    self._save()
                return False
            return True

    def pause_until_next_hour(self, strategy: str, reason: str):
        """Pause `strategy` from now until the next hour boundary (UTC)."""
        now = datetime.now(timezone.utc)
        next_hour = (now.replace(minute=0, second=0, microsecond=0)
                     + timedelta(hours=1))
        unpause_ts = next_hour.timestamp()
        with self._lock:
            already = self._paused.get(strategy, 0) > time.time()
            self._paused[strategy] = unpause_ts
            self._save()
        if not already:
            mins = int((next_hour - now).total_seconds() / 60)
            logger.warning(f'[AUTO-PAUSE] {strategy} -> PAPER until {next_hour.strftime("%H:%M UTC")} ({mins}m). Reason: {reason}')
            # Send TG alert (lazy — don't block on bot reference)
            try:
                import urllib.request, urllib.parse
                tg_token  = os.environ.get('TG_BOT_TOKEN', '')
                tg_chat   = os.environ.get('TG_CHAT_ID', '')
                text = (f'🛑 AUTO-PAUSE\n'
                        f'<b>{strategy}</b> -> PAPER until {next_hour.strftime("%H:%M UTC")} ({mins}m)\n'
                        f'Reason: {reason}\n'
                        f'Self-restores at top of next hour.')
                data = urllib.parse.urlencode({'chat_id': tg_chat, 'text': text, 'parse_mode': 'HTML'}).encode()
                urllib.request.urlopen(urllib.request.Request(
                    f'https://api.telegram.org/bot{tg_token}/sendMessage', data=data), timeout=8)
            except Exception as _e:
                logger.debug(f'[AUTO-PAUSE] TG alert failed: {_e}')

    def record_resolved(self, strategy: str, pnl: float):
        """Call after each REAL trade resolves. Triggers pause if criteria met."""
        if not strategy or pnl is None: return
        now = time.time()
        with self._lock:
            buf = self._recent.setdefault(strategy, [])
            buf.append((now, pnl))
            cutoff = now - self.ROLLING_WINDOW_S
            buf[:] = [(ts, p) for ts, p in buf if ts >= cutoff]
            window_pnl = sum(p for _, p in buf)

            # Track consecutive-loss streak
            if pnl < 0:
                self._consec[strategy] = self._consec.get(strategy, 0) + 1
            else:
                self._consec[strategy] = 0
            consec = self._consec[strategy]

            already_paused = self._paused.get(strategy, 0) > now

        # Trigger checks (outside lock to avoid TG send under lock)
        if not already_paused:
            if window_pnl <= self.ROLLING_PNL_LIMIT and len(buf) >= 3:
                self.pause_until_next_hour(
                    strategy, f'rolling 30m PnL ${window_pnl:+.2f} over {len(buf)} trades')
            elif consec >= self.CONSEC_LOSS_LIMIT:
                self.pause_until_next_hour(
                    strategy, f'{consec} consecutive losses')

        # Phase 1 consensus-failure trigger: if multiple INDEPENDENT live
        # strategies are bleeding simultaneously, the regime has shifted —
        # pause ALL live scanners (not just the strategy that just resolved).
        # Catches the 03-05 UTC pattern from 5/15 where 3 models all bled at once.
        self._check_consensus_failure()

    # Added TIME-LOCK + MOMENTUM 2026-05-19 when those flipped to real_trade=real.
    # Each gets its own per-strategy gate via record_resolved (L527); inclusion here
    # also lets them contribute to / be paused by the multi-scanner consensus check.
    LIVE_SCANNERS = ('BTC-ML', 'ETH-ML', 'MISPRICED', 'MANIP', 'TIME-LOCK', 'MOMENTUM')
    CONSENSUS_FAIL_MIN_STRATEGIES = 2   # how many bleeding scanners trigger
    CONSENSUS_FAIL_MIN_TRADES = 3       # min trades per strategy to count
    CONSENSUS_FAIL_PNL_LIMIT = -10.0    # per-strategy threshold (gentler than per-strategy gate)

    def _check_consensus_failure(self):
        """If >=2 live scanners are losing in the rolling window, pause ALL.
        Per-strategy gate uses ROLLING_PNL_LIMIT=-25; this consensus check
        uses a gentler -$10 per strategy because the SIGNAL is correlation
        not magnitude — multiple small bleeds = regime shift."""
        now = time.time()
        cutoff = now - self.ROLLING_WINDOW_S
        bleeders = []
        with self._lock:
            for s in self.LIVE_SCANNERS:
                buf = self._recent.get(s, [])
                # Refresh window trim
                buf = [(ts, p) for ts, p in buf if ts >= cutoff]
                if len(buf) < self.CONSENSUS_FAIL_MIN_TRADES: continue
                wp = sum(p for _, p in buf)
                if wp <= self.CONSENSUS_FAIL_PNL_LIMIT:
                    bleeders.append((s, wp, len(buf)))
            # Already-paused check — don't re-fire if all four already paused
            already_all_paused = all(self._paused.get(s, 0) > now for s in self.LIVE_SCANNERS)
        if len(bleeders) >= self.CONSENSUS_FAIL_MIN_STRATEGIES and not already_all_paused:
            details = ', '.join(f'{s} ${p:+.0f}/{n}t' for s,p,n in bleeders)
            for s in self.LIVE_SCANNERS:
                # pause_until_next_hour handles its own already-paused dedup
                self.pause_until_next_hour(
                    s, f'CONSENSUS FAILURE: {details}')

# Module-level singleton — instantiated lazily on first use
_AUTO_PAUSE_GATE = None
def auto_pause_gate():
    global _AUTO_PAUSE_GATE
    if _AUTO_PAUSE_GATE is None:
        _AUTO_PAUSE_GATE = AutoPauseGate()
    return _AUTO_PAUSE_GATE


# ── DAILY RL/ML SNAPSHOTS ────────────────────────────────────────────────────
# Copies every RL Q-table, ML model file, and strategy/settings file into a
# dated folder once per UTC day. Lets us roll back to "a better time" if a
# regime shift or bug poisons the live tables.
def _take_rl_ml_snapshot(retention_days: int = 30) -> tuple:
    """Snapshot once. Returns (folder_path, n_files, n_pruned). Idempotent —
    if today's snapshot already exists with the expected files, returns it
    unchanged."""
    base = os.path.dirname(os.path.abspath(__file__))
    today = datetime.now(timezone.utc).strftime('%Y-%m-%d')
    snap_root = os.path.join(base, 'rl_ml_snapshots')
    os.makedirs(snap_root, exist_ok=True)
    dest = os.path.join(snap_root, today)
    os.makedirs(dest, exist_ok=True)
    # Patterns to capture — RL Q-tables, ML model weights, slider/conviction
    # config, and per-scanner settings (live_mode, stake, tp/sl, etc.).
    patterns = (
        '*_rl_state.json', '*_rl_state.weekend.json',
        '*_ml_model.json', '*_ml_model.weekend.json',
        '*_settings.json', '*_settings.weekend.json',
        'claude_strategy_modes.json',
    )
    n_files = 0
    for pat in patterns:
        for src in glob.glob(os.path.join(base, pat)):
            # Skip files already inside snapshot folder (paranoia)
            if 'rl_ml_snapshots' in src:
                continue
            fn = os.path.basename(src)
            tgt = os.path.join(dest, fn)
            try:
                # Only copy if source is newer or target missing
                if (not os.path.exists(tgt)
                        or os.path.getmtime(src) > os.path.getmtime(tgt)):
                    shutil.copy2(src, tgt)
                    n_files += 1
            except Exception as e:
                logger.warning(f'[SNAPSHOT] copy fail {fn}: {e}')
    # Retention prune
    n_pruned = 0
    cutoff = (datetime.now(timezone.utc) - timedelta(days=retention_days)).strftime('%Y-%m-%d')
    try:
        for entry in os.listdir(snap_root):
            full = os.path.join(snap_root, entry)
            if not os.path.isdir(full):
                continue
            # Only prune folders that match YYYY-MM-DD format
            if len(entry) == 10 and entry[4] == '-' and entry[7] == '-' and entry < cutoff:
                shutil.rmtree(full, ignore_errors=True)
                n_pruned += 1
    except Exception as e:
        logger.warning(f'[SNAPSHOT] prune error: {e}')
    return dest, n_files, n_pruned


def _start_daily_snapshot_loop(retention_days: int = 30):
    """Background daemon: snapshots all RL/ML state files once per UTC day
    (~5min past midnight). Also takes a snapshot at boot so restarts always
    produce today's folder. Survives errors via try/except per iteration."""
    def _run():
        # Boot snapshot — wait briefly for state files to settle after init
        time.sleep(30)
        try:
            dest, n, pruned = _take_rl_ml_snapshot(retention_days)
            logger.info(f'[SNAPSHOT] Boot snapshot → {os.path.basename(dest)} '
                        f'({n} files copied, {pruned} old folders pruned)')
        except Exception as e:
            logger.warning(f'[SNAPSHOT] Boot snapshot error: {e}')
        # Daily loop
        while True:
            try:
                now = datetime.now(timezone.utc)
                # Next UTC midnight + 5min buffer (so any midnight-rolling jobs settle first)
                tomorrow = (now + timedelta(days=1)).replace(
                    hour=0, minute=5, second=0, microsecond=0)
                sleep_s = max(60, (tomorrow - now).total_seconds())
                time.sleep(sleep_s)
                dest, n, pruned = _take_rl_ml_snapshot(retention_days)
                logger.info(f'[SNAPSHOT] Daily snapshot → {os.path.basename(dest)} '
                            f'({n} files copied, {pruned} old folders pruned)')
            except Exception as e:
                logger.warning(f'[SNAPSHOT] Daily loop error: {e}')
                time.sleep(3600)  # back off on error
    threading.Thread(target=_run, daemon=True, name='rl-ml-snapshot').start()


def _trade_logged_in_weekend(trade: dict) -> bool:
    """True if a trade's logged_at/entered_at timestamp falls inside any past
    weekend window defined by the recurring config. Both paper and live trades
    are eligible — the field used is whatever the trade dict carries."""
    cfg = _weekend_mode_config()
    if not cfg.get('enabled'):
        return False
    a_start = cfg.get('start_ts', 0) or 0
    a_end   = cfg.get('end_ts', 0)   or 0
    duration = a_end - a_start
    if duration <= 0 or a_start <= 0:
        return False
    raw = trade.get('logged_at') or trade.get('entered_at')
    if not raw:
        return False
    try:
        if isinstance(raw, str):
            ts = datetime.fromisoformat(raw.replace('Z', '+00:00')).timestamp()
        else:
            ts = float(raw)
    except Exception:
        return False
    if not cfg.get('recurring'):
        return a_start <= ts < a_end
    if ts < a_start:
        return False
    return ((ts - a_start) % _WEEK_SECONDS) < duration

def _start_weekend_boundary_watchdog():
    """Background thread that os.execv-restarts the process whenever weekend
    mode flips (weekday→weekend at start_ts, weekend→weekday at end_ts).
    The restart is what swaps which state files each ML/RL class reads from.

    Recurring schedule is handled by _is_weekend_mode_now() modulo math —
    the watchdog just observes the boolean and reacts to transitions, so it
    works identically for one-shot and recurring configs without special cases.
    """
    def _run():
        last_mode = _is_weekend_mode_now()
        cur_start, cur_end = _current_weekend_window()
        if last_mode and cur_end:
            end_iso = datetime.fromtimestamp(cur_end, timezone.utc).isoformat()
            logger.info(f'[WEEKEND] Watchdog up — mode=WEEKEND, ends {end_iso}')
        elif cur_start:
            start_iso = datetime.fromtimestamp(cur_start, timezone.utc).isoformat()
            logger.info(f'[WEEKEND] Watchdog up — mode=WEEKDAY, next weekend at {start_iso}')
        while True:
            try:
                cur_mode = _is_weekend_mode_now()
                if cur_mode != last_mode:
                    label = 'WEEKEND' if cur_mode else 'WEEKDAY'
                    logger.info(f'[WEEKEND] Mode transition -> {label} — restarting to reload state')
                    # 2026-05-22: bumped pre-execv sleep 1s -> 8s + explicit socket cleanup.
                    # The 5/22 weekday->weekend flip hung the Flask/socketio thread for 40min
                    # after os.execv because the new process image collided with lingering
                    # TCP sockets on :5002 from the old process state (CloseWait/Established
                    # orphans). 8s gives the OS time to release the port; explicit shutdown
                    # of socketio + flask sockets reduces the residual-socket window further.
                    try:
                        from flask import current_app
                        # Best-effort: close any active socketio connections so Werkzeug
                        # finishes pending HTTP requests before we exec.
                        try:
                            socketio.stop()  # type: ignore[name-defined]
                        except Exception as _sio_e:
                            logger.debug(f'[WEEKEND] socketio.stop best-effort: {_sio_e}')
                    except Exception:
                        pass
                    time.sleep(8)  # log flush + OS socket release on :5002
                    os.execv(sys.executable, [sys.executable] + sys.argv)
                last_mode = cur_mode
            except Exception as _e:
                logger.warning(f'[WEEKEND] Watchdog error: {_e}')
            time.sleep(30)
    threading.Thread(target=_run, daemon=True, name='weekend-watchdog').start()


