class TechnicalIndicators:
    """Technical analysis indicators"""

    @staticmethod
    def calculate_rsi(prices: List[float], period: int = 14) -> float:
        """Calculate RSI using Wilder's smoothing (matches TradingView ta.rsi)"""
        if len(prices) < period + 1:
            return 50.0

        deltas = np.diff(prices)
        gains = np.where(deltas > 0, deltas, 0.0)
        losses = np.where(deltas < 0, -deltas, 0.0)

        # Wilder's smoothing: EWM with alpha=1/period (matches Pine Script ta.rsi)
        alpha = 1.0 / period
        avg_gain = gains[0]
        avg_loss = losses[0]
        for i in range(1, len(gains)):
            avg_gain = alpha * gains[i] + (1 - alpha) * avg_gain
            avg_loss = alpha * losses[i] + (1 - alpha) * avg_loss

        if avg_loss == 0:
            return 100.0

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        return rsi

    @staticmethod
    def calculate_ema(prices: List[float], period: int) -> List[float]:
        """Calculate EMA for all prices"""
        if len(prices) < period:
            return [np.mean(prices)] * len(prices)

        multiplier = 2 / (period + 1)
        ema_values = [prices[0]]

        for price in prices[1:]:
            ema = (price * multiplier) + (ema_values[-1] * (1 - multiplier))
            ema_values.append(ema)

        return ema_values

    @staticmethod
    def calculate_macd(prices: List[float]) -> Tuple[List[float], List[float], List[float]]:
        """Calculate MACD"""
        if len(prices) < 26:
            return [0] * len(prices), [0] * len(prices), [0] * len(prices)

        ema_12 = TechnicalIndicators.calculate_ema(prices, 12)
        ema_26 = TechnicalIndicators.calculate_ema(prices, 26)

        macd_line = [e12 - e26 for e12, e26 in zip(ema_12, ema_26)]
        signal_line = TechnicalIndicators.calculate_ema(macd_line, 9)
        histogram = [m - s for m, s in zip(macd_line, signal_line)]

        return macd_line, signal_line, histogram

    @staticmethod
    def calculate_bollinger_bands(prices: List[float], period: int = 20, std_mult: float = 2.0) -> Tuple[List[float], List[float], List[float]]:
        """Calculate Bollinger Bands (std_mult = number of std-devs for the bands)."""
        upper_bands = []
        middle_bands = []
        lower_bands = []

        for i in range(len(prices)):
            if i < period - 1:
                window = prices[:i+1]
            else:
                window = prices[i-period+1:i+1]

            middle = np.mean(window)
            std = np.std(window)

            upper_bands.append(middle + (std_mult * std))
            middle_bands.append(middle)
            lower_bands.append(middle - (std_mult * std))

        return upper_bands, middle_bands, lower_bands

    @staticmethod
    def calculate_stochastic(candles: List[Dict], k_period: int = 14) -> Tuple[float, float]:
        """Calculate Stochastic Oscillator %K and %D"""
        if len(candles) < k_period:
            return 50.0, 50.0

        recent_candles = candles[-k_period:]
        highest_high = max(c['high'] for c in recent_candles)
        lowest_low = min(c['low'] for c in recent_candles)
        current_close = candles[-1]['close']

        if highest_high == lowest_low:
            k = 50.0
        else:
            k = ((current_close - lowest_low) / (highest_high - lowest_low)) * 100

        return k, k  # Simplified - D equals K


class MultiSourceDataFetcher:
    """Fetch data from multiple sources with fallback and caching"""

    def __init__(self):
        self.hyperliquid_url = "https://api.hyperliquid.xyz/info"
        self.binance_url = "https://api.binance.com/api/v3/klines"
        # Candle cache: {symbol: {'candles': [...], 'last_ts': int}}
        # First call fetches full history, subsequent calls only fetch recent candles and append
        self._candle_cache = {}
        # Persistent HTTP session — reuses TCP/TLS connections.
        # Pre-fix profile showed 53% of CPU in ssl_wrap_socket from bare requests.* calls
        # in this class. Mirror HFTScanner / ClaudePicksScanner pool sizing.
        self._session = requests.Session()
        self._session.headers.update({'Accept-Encoding': 'gzip'})
        from requests.adapters import HTTPAdapter as _HTTPAdapter
        _ad = _HTTPAdapter(pool_connections=20, pool_maxsize=40, max_retries=2)
        self._session.mount('http://', _ad)
        self._session.mount('https://', _ad)
    
    def get_15min_candles_hyperliquid(self, symbol: str, num_candles: int = 50) -> Optional[List[Dict]]:
        """Get 15-minute candles from Hyperliquid"""
        try:
            end_time = int(time.time() * 1000)
            start_time = end_time - (num_candles * 15 * 60 * 1000)
            
            payload = {
                "type": "candleSnapshot",
                "req": {
                    "coin": symbol,
                    "interval": "15m",
                    "startTime": start_time,
                    "endTime": end_time
                }
            }
            
            response = self._session.post(self.hyperliquid_url, json=payload, timeout=20)

            if response.status_code == 200:
                data = response.json()

                candles = []
                for candle in data:
                    candles.append({
                        'timestamp': candle['t'],
                        'open': float(candle['o']),
                        'high': float(candle['h']),
                        'low': float(candle['l']),
                        'close': float(candle['c']),
                        'volume': float(candle['v'])
                    })

                return candles

            return None

        except Exception as e:
            logger.error(f"Hyperliquid error for {symbol}: {e}")
            return None
    
    def get_15min_candles_binance(self, symbol: str, num_candles: int = 50) -> Optional[List[Dict]]:
        """Get 15-minute candles from Binance (fallback). Supports up to 1000 per request."""
        try:
            binance_symbol_map = {
                'BTC': 'BTCUSDT',
                'ETH': 'ETHUSDT',
                'SOL': 'SOLUSDT',
                'XRP': 'XRPUSDT',
                'DOGE': 'DOGEUSDT',
                'BNB': 'BNBUSDT'
            }

            binance_symbol = binance_symbol_map.get(symbol)
            if not binance_symbol:
                return None

            params = {
                'symbol': binance_symbol,
                'interval': '15m',
                'limit': min(num_candles, 1000)  # Binance max is 1000
            }

            response = self._session.get(self.binance_url, params=params, timeout=15)

            if response.status_code == 200:
                data = response.json()

                candles = []
                for candle in data:
                    candles.append({
                        'timestamp': candle[0],
                        'open': float(candle[1]),
                        'high': float(candle[2]),
                        'low': float(candle[3]),
                        'close': float(candle[4]),
                        'volume': float(candle[5])
                    })

                return candles

            return None

        except Exception as e:
            logger.error(f"Binance error for {symbol}: {e}")
            return None
    
    def get_15min_candles(self, symbol: str, num_candles: int = 50) -> Optional[List[Dict]]:
        """Get candles with fallback logic and caching.

        First call: fetches full num_candles history.
        Subsequent calls: fetches only last 10 candles, appends new ones to cache.
        Keeps cache trimmed to num_candles.
        """
        cached = self._candle_cache.get(symbol)

        if cached and len(cached['candles']) >= 100:
            # Cache exists - only fetch recent candles to update
            fresh = self._fetch_candles(symbol, 10)
            if fresh:
                # Merge: find where new data starts
                last_cached_ts = cached['candles'][-1]['timestamp']
                new_candles = [c for c in fresh if c['timestamp'] > last_cached_ts]
                if new_candles:
                    cached['candles'].extend(new_candles)
                    # Update the last candle in case it was still forming
                    for c in fresh:
                        if c['timestamp'] == last_cached_ts:
                            cached['candles'][-len(new_candles)-1] = c
                            break
                else:
                    # No new candles yet - update the last candle (may still be forming)
                    if fresh and fresh[-1]['timestamp'] == last_cached_ts:
                        cached['candles'][-1] = fresh[-1]

                # Trim to keep only num_candles
                if len(cached['candles']) > num_candles:
                    cached['candles'] = cached['candles'][-num_candles:]

                logger.debug(f"Cache hit {symbol}: {len(cached['candles'])} candles (added {len(new_candles) if new_candles else 0} new)")
                return cached['candles']
            else:
                # Fetch failed but we have cache - return stale data
                logger.warning(f"Fetch failed for {symbol}, returning cached data ({len(cached['candles'])} candles)")
                return cached['candles']
        else:
            # No cache - full fetch
            candles = self._fetch_candles(symbol, num_candles)
            if candles:
                self._candle_cache[symbol] = {'candles': candles}
                logger.info(f"Cache initialized for {symbol}: {len(candles)} candles")
                return candles

            logger.error(f"All sources failed for {symbol}")
            return None

    def get_5min_candles_binance(self, symbol: str, num_candles: int = 100) -> Optional[List[Dict]]:
        """Get 5-minute candles from Binance."""
        try:
            binance_symbol_map = {
                'BTC': 'BTCUSDT', 'ETH': 'ETHUSDT', 'SOL': 'SOLUSDT',
                'XRP': 'XRPUSDT', 'DOGE': 'DOGEUSDT', 'HYPE': None, 'BNB': 'BNBUSDT'
            }
            binance_symbol = binance_symbol_map.get(symbol)
            if not binance_symbol:
                return None
            params = {
                'symbol': binance_symbol,
                'interval': '5m',
                'limit': min(num_candles, 1000)
            }
            response = self._session.get(self.binance_url, params=params, timeout=15)
            if response.status_code == 200:
                return [{'timestamp': c[0], 'open': float(c[1]), 'high': float(c[2]),
                         'low': float(c[3]), 'close': float(c[4]), 'volume': float(c[5])}
                        for c in response.json()]
            return None
        except Exception as e:
            logger.error(f"Binance 5m error for {symbol}: {e}")
            return None

    def get_5min_candles_hyperliquid(self, symbol: str, num_candles: int = 100) -> Optional[List[Dict]]:
        """Get 5-minute candles from Hyperliquid."""
        try:
            if symbol not in ['BTC', 'ETH', 'SOL', 'XRP', 'BNB', 'HYPE']:
                return None
            end_time = int(datetime.now().timestamp() * 1000)
            start_time = end_time - (num_candles * 5 * 60 * 1000)
            hl_symbol_map = {'BTC': 'BTC', 'ETH': 'ETH', 'SOL': 'SOL', 'XRP': 'XRP', 'BNB': 'BNB', 'HYPE': 'HYPE'}
            hl_symbol = hl_symbol_map.get(symbol)
            response = self._session.post(
                "https://api.hyperliquid.xyz/info",
                json={"type": "candleSnapshot", "req": {
                    "coin": hl_symbol, "interval": "5m",
                    "startTime": start_time, "endTime": end_time
                }},
                timeout=15
            )
            if response.status_code == 200:
                data = response.json()
                return [{'timestamp': int(c['t']), 'open': float(c['o']), 'high': float(c['h']),
                         'low': float(c['l']), 'close': float(c['c']), 'volume': float(c['v'])}
                        for c in data if isinstance(c, dict)]
            return None
        except Exception as e:
            logger.debug(f"Hyperliquid 5m error {symbol}: {e}")
            return None

    def get_5min_candles(self, symbol: str, num_candles: int = 200) -> Optional[List[Dict]]:
        """Get 5-min candles with Hyperliquid→Binance fallback and separate cache."""
        cache_key = f'5m_{symbol}'
        cached = self._candle_cache.get(cache_key)
        if cached and len(cached['candles']) >= 50:
            # Update last few candles only
            fresh = self.get_5min_candles_hyperliquid(symbol, 10) or                     self.get_5min_candles_binance(symbol, 10)
            if fresh:
                last_ts = cached['candles'][-1]['timestamp']
                new = [c for c in fresh if c['timestamp'] > last_ts]
                if new:
                    cached['candles'].extend(new)
                if fresh[-1]['timestamp'] == last_ts:
                    cached['candles'][-1] = fresh[-1]
                if len(cached['candles']) > num_candles:
                    cached['candles'] = cached['candles'][-num_candles:]
            return cached['candles']
        # Full fetch
        candles = self.get_5min_candles_hyperliquid(symbol, num_candles) or                   self.get_5min_candles_binance(symbol, num_candles)
        if candles:
            self._candle_cache[cache_key] = {'candles': candles}
            logger.info(f"5m cache initialized for {symbol}: {len(candles)} candles")
        return candles


    def _fetch_candles(self, symbol: str, num_candles: int) -> Optional[List[Dict]]:
        """Internal: fetch from Hyperliquid with Binance fallback"""
        candles = self.get_15min_candles_hyperliquid(symbol, num_candles)
        if candles:
            logger.debug(f"Got {symbol} data from Hyperliquid ({len(candles)} candles)")
            return candles

        logger.info(f"Hyperliquid failed for {symbol}, trying Binance...")
        candles = self.get_15min_candles_binance(symbol, num_candles)
        if candles:
            logger.info(f"Got {symbol} data from Binance ({len(candles)} candles)")
            return candles

        return None


