def _infer_timeframe(candles: List[Dict]) -> str:
    """Infer '5m' or '15m' from candle timestamp deltas (in ms)."""
    if len(candles) < 2:
        return '15m'
    delta_ms = candles[-1]['timestamp'] - candles[-2]['timestamp']
    return '5m' if delta_ms < 600_000 else '15m'


