# ──────────────────────────────────────────────────────────────────────────────
# RL SHADOW LOG — records blocked trades so we can measure counterfactual WR
# ──────────────────────────────────────────────────────────────────────────────

class RLShadowLog:
    """
    Records trades that were blocked by RL gates and resolves their outcomes
    post-market-close, so we can measure the shadow WR of blocked states.

    This tells us: is the RL correctly blocking losers, or is it blocking winners?
    Shadow WR >> 50% = RL may be over-blocking good states.
    Shadow WR << 50% = RL is correctly suppressing losers.
    """

    GAMMA = 'https://gamma-api.polymarket.com'

    # 2026-05-23 PR-4: dedupe at log-time. The scanner re-checks every market
    # each scan tick (~1-8s), and pre-fix log_blocked() appended a row each time
    # — bloating shadow files 7-10x (eth_ml_rl_blocked.weekend.json was 15.9MB /
    # 22k records / 3k unique). The set below is the in-memory uniqueness index
    # keyed on (rl_system, market_slug, direction). On _load we compact any
    # existing dups; on log_blocked we skip if seen.
    _DEDUP_KEY_FIELDS = ('rl_system', 'market_slug', 'direction')

    def __init__(self, log_file: str, on_resolve=None):
        """on_resolve: optional callable invoked with the resolved record dict
        after shadow_pnl is computed and written. Used by BTCMLScanner to
        feed shadow outcomes back into the RL Q-table at reduced weight."""
        self.log_file = log_file
        self._trades: list = []
        self._seen: set = set()
        self._lock = __import__('threading').Lock()
        self._session = __import__('requests').Session()
        self._on_resolve = on_resolve
        self._load()

    def _key_of(self, t: dict) -> tuple:
        return tuple(t.get(f) for f in self._DEDUP_KEY_FIELDS)

    def _load(self):
        # Weekend-aware: read from .weekend.json variant during weekend mode so
        # weekday and weekend blocked-trade records stay segregated.
        path = _resolve_state_path(self.log_file)
        try:
            if os.path.exists(path):
                with open(path, encoding='utf-8') as f:
                    raw = json.load(f)
                # Compact: keep first record per (rl_system, market_slug, direction)
                # — preserves the original logged_at and any resolved outcome that
                # was written on the dedup'd duplicate (all dups share the same
                # market and thus resolve identically).
                seen: set = set()
                compacted = []
                # First pass — prefer records that are RESOLVED (have outcome) so
                # we don't lose post-resolution writes that landed on later dups.
                by_key: dict = {}
                for t in raw:
                    k = self._key_of(t)
                    cur = by_key.get(k)
                    if cur is None:
                        by_key[k] = t
                        continue
                    # Prefer resolved over unresolved
                    if cur.get('resolved') and not t.get('resolved'):
                        continue
                    if t.get('resolved') and not cur.get('resolved'):
                        by_key[k] = t
                # Preserve original order: walk raw, take first occurrence of each key
                for t in raw:
                    k = self._key_of(t)
                    if k in seen:
                        continue
                    seen.add(k)
                    compacted.append(by_key[k])
                self._trades = compacted
                self._seen = seen
                if len(compacted) < len(raw):
                    logger.info(f'[RL-SHADOW] Loaded {len(raw)} blocked trades from {os.path.basename(path)} — compacted to {len(compacted)} unique (-{len(raw)-len(compacted)} dups)')
                    # Persist the compacted file so disk doesn't keep paying for old bloat
                    try:
                        self._save()
                    except Exception as _se:
                        logger.warning(f'[RL-SHADOW] post-compact save error: {_se}')
                else:
                    logger.info(f'[RL-SHADOW] Loaded {len(self._trades)} blocked trades from {os.path.basename(path)}')
        except Exception as e:
            logger.warning(f'[RL-SHADOW] Load error {os.path.basename(path)}: {e}')
            self._trades = []
            self._seen = set()

    def _save(self):
        # Weekend-aware: write to .weekend.json variant during weekend mode.
        # 2026-05-23 PR-5: routed through _atomic_write_json which uses orjson
        # when available (~5-8x faster than stdlib on the multi-MB shadow log).
        path = _resolve_state_path(self.log_file)
        try:
            _atomic_write_json(path, self._trades, indent=True)
        except Exception as e:
            logger.warning(f'[RL-SHADOW] Save error {os.path.basename(path)}: {e}')

    def log_blocked(self, rl_system: str, state_key: str, rl_q: float, rl_n: int,
                    rl_reason: str, symbol: str, direction: str,
                    entry_price: float, stake: float, secs_to_close: float,
                    market_end_ts: float, market_slug: str, strategy: str = '',
                    play_type: str = '', token_id: str = ''):
        """Record a trade that was blocked by RL for later counterfactual resolution."""
        import uuid as _u
        shares = round(stake / (entry_price * 1.02), 4) if entry_price > 0 else 0
        record = {
            'id':            _u.uuid4().hex[:12],
            'logged_at':     datetime.now(timezone.utc).isoformat(),
            'rl_system':     rl_system,
            'rl_state_key':  state_key,
            'rl_q':          round(rl_q, 4),
            'rl_n':          rl_n,
            'rl_reason':     rl_reason,
            'symbol':        symbol,
            'direction':     direction,
            'entry_price':   entry_price,
            'stake':         stake,
            'shares':        shares,
            'secs_to_close': round(secs_to_close, 1),
            'market_end_ts': market_end_ts,
            'market_slug':   market_slug,
            'strategy':      strategy,
            'play_type':     play_type,
            'token_id':      token_id,
            'resolved':      False,
            'outcome':       None,
            'shadow_pnl':    None,
        }
        with self._lock:
            key = (rl_system, market_slug, direction)
            if key in self._seen:
                # Already logged this market+gate — don't bloat the file. The
                # original record will resolve once and serve all subsequent
                # blocked attempts on this market for the same gate.
                return
            self._seen.add(key)
            self._trades.append(record)
            self._save()

    def _resolve_one(self, t: dict):
        """Resolve a single blocked trade. Returns 'WIN', 'LOSS', or None."""
        now_ts = time.time()
        end_ts = t.get('market_end_ts', 0)
        if end_ts and now_ts < end_ts + 30:
            return None
        slug      = t.get('market_slug', '')
        direction = t.get('direction', 'UP').upper()
        if not slug:
            return None
        try:
            r = self._session.get(f'{self.GAMMA}/events', params={'slug': slug}, timeout=5)
            if r.status_code != 200:
                return None
            events = r.json()
            event = events[0] if isinstance(events, list) and events else None
            if not event:
                return None
            mkt = (event.get('markets') or [None])[0]
            if not mkt:
                return None
            out_prices_raw = mkt.get('outcomePrices', '[]')
            outcomes_raw   = mkt.get('outcomes', '["Up","Down"]')
            closed = mkt.get('closed', False)
            if isinstance(out_prices_raw, str):
                out_prices = [float(x) for x in json.loads(out_prices_raw)]
            else:
                out_prices = [float(x) for x in (out_prices_raw or [])]
            if isinstance(outcomes_raw, str):
                outcomes = json.loads(outcomes_raw)
            else:
                outcomes = list(outcomes_raw or [])
            for i, o in enumerate(outcomes):
                if o.upper() == direction and i < len(out_prices):
                    p = out_prices[i]
                    if p >= 0.99:
                        return 'WIN'
                    elif p <= 0.01:
                        return 'LOSS'
                    elif closed:
                        return 'PUSH'
                    return None
        except Exception:
            return None

    def check_outcomes(self):
        """Resolve pending blocked trades. Call periodically."""
        with self._lock:
            pending = [t for t in self._trades if not t.get('resolved')]
        if not pending:
            return
        changed = False
        for t in pending:
            outcome = self._resolve_one(t)
            if outcome is None:
                continue
            stake  = t.get('stake', 0)
            shares = t.get('shares', 0)
            if outcome == 'WIN':
                pnl = round(shares * 1.0 - stake, 4)
            elif outcome == 'LOSS':
                pnl = round(-stake, 4)
            else:
                pnl = 0.0
            with self._lock:
                t.update({
                    'resolved':    True,
                    'outcome':     outcome,
                    'shadow_pnl':  pnl,
                    'resolved_at': datetime.now(timezone.utc).isoformat(),
                })
            changed = True
            logger.info(f'[RL-SHADOW] {t["rl_system"]} BLOCKED->{outcome} '
                        f'{t["symbol"]} {t["direction"]} PnL={pnl:+.2f} [{t["rl_state_key"]}]')
            # 2026-05-20: feed shadow outcome back to the owning RL gate at
            # reduced weight. Breaks the self-fulfilling loop where blocked
            # cells get no fresh data. Callback handles dispatch + weight.
            if self._on_resolve is not None:
                try:
                    self._on_resolve(t)
                except Exception as _cb_err:
                    logger.warning(f'[RL-SHADOW] on_resolve callback error: {_cb_err}')
        if changed:
            with self._lock:
                self._save()

    def get_stats(self) -> dict:
        """Return shadow WR stats per RL system and per state."""
        with self._lock:
            trades = list(self._trades)
        resolved = [t for t in trades if t.get('resolved')]
        wins   = [t for t in resolved if t.get('outcome') == 'WIN']
        losses = [t for t in resolved if t.get('outcome') == 'LOSS']
        total  = len(wins) + len(losses)
        shadow_wr = round(len(wins) / max(total, 1) * 100, 1) if total else None
        shadow_pnl = round(sum(t.get('shadow_pnl') or 0 for t in resolved), 2)

        # Per RL system
        by_system = {}
        for sys in ('hft', 'manip', 'picks'):
            st = [t for t in resolved if t.get('rl_system') == sys]
            sw = sum(1 for t in st if t.get('outcome') == 'WIN')
            sl = sum(1 for t in st if t.get('outcome') == 'LOSS')
            tot = sw + sl
            by_system[sys] = {
                'wins': sw, 'losses': sl, 'total': tot,
                'shadow_wr':  round(sw / max(tot, 1) * 100, 1) if tot else None,
                'shadow_pnl': round(sum(t.get('shadow_pnl') or 0 for t in st), 2),
            }

        # Per state key (for the worst/best blocked states)
        from collections import defaultdict
        by_state: dict = defaultdict(lambda: {'wins': 0, 'losses': 0, 'pnl': 0.0, 'system': ''})
        for t in resolved:
            k = t.get('rl_state_key', '')
            by_state[k]['wins']   += 1 if t.get('outcome') == 'WIN' else 0
            by_state[k]['losses'] += 1 if t.get('outcome') == 'LOSS' else 0
            by_state[k]['pnl']    += t.get('shadow_pnl') or 0
            by_state[k]['system'] = t.get('rl_system', '')

        return {
            'total_blocked':  len(trades),
            'resolved':       len(resolved),
            'pending':        len(trades) - len(resolved),
            'wins':           len(wins),
            'losses':         len(losses),
            'shadow_wr':      shadow_wr,
            'shadow_pnl':     shadow_pnl,
            'by_system':      by_system,
            'by_state':       {k: {'wins': v['wins'], 'losses': v['losses'],
                                   'pnl': round(v['pnl'], 2), 'system': v['system'],
                                   'wr': round(v['wins'] / max(v['wins']+v['losses'],1)*100,1)}
                               for k, v in by_state.items()},
        }


# ──────────────────────────────────────────────────────────────────────────────
# MANIP RL — contextual bandit that learns which MANIP states are profitable
# ──────────────────────────────────────────────────────────────────────────────

class ManipRL:
    """
    Online contextual bandit for MANIP strategy.

    State = (symbol, ask_bucket, candle_bucket, gap_bucket, direction)
    Q(s)  = running average of ROI seen in that state
    Update: Q(s) += alpha * (actual_roi - Q(s))   [exponential moving average]
    Entry gate: skip trade if Q(s) < SKIP_THRESHOLD (learned to be unprofitable)

    No external libraries — pure Python + JSON persistence.
    """

    RL_FILE       = 'manip_rl_state.json'
    ALPHA         = 0.15   # learning rate — 15% weight on each new observation
    SKIP_THRESHOLD = -0.20  # skip if expected ROI < -20% (learned loser)
    MIN_VISITS    = 3       # need at least 3 observations before gating

    def __init__(self):
        self.q: dict  = {}   # state_key -> {'q': float, 'n': int, 'last_ts': float}
        self._dirty   = False  # debounce flag — flusher saves every 1s if set
        self._load()
        self._seed_from_paper_log()
        _start_q_decay_sweeper(self, 'MANIP-RL')
        _start_dirty_flush_loop(self, 'MANIP-RL')

    # ── persistence ────────────────────────────────────────────────────────────

    def _load(self):
        try:
            path = _resolve_state_path(self.RL_FILE)
            if os.path.exists(path):
                with open(path, encoding='utf-8') as _f:
                    self.q = json.load(_f)
                logger.info(f'[MANIP-RL] Loaded {len(self.q)} states from {os.path.basename(path)}')
        except Exception as e:
            logger.warning(f'[MANIP-RL] Load error: {e}')
            self.q = {}

    def _save(self):
        try:
            import uuid
            path = _resolve_state_path(self.RL_FILE)
            tmp  = path + f'.tmp_{uuid.uuid4().hex[:8]}'
            with open(tmp, 'w') as f:
                json.dump(self.q, f, indent=2)
            os.replace(tmp, path)
        except Exception as e:
            logger.warning(f'[MANIP-RL] Save error: {e}')

    # ── state encoding ─────────────────────────────────────────────────────────

    @staticmethod
    def _state_key(symbol: str, ask: float, candle_pct: float, gap: float, direction: str) -> str:
        if ask < 0.40:
            ask_b = 'ask_low'
        elif ask < 0.50:
            ask_b = 'ask_mid'
        elif ask < 0.60:
            ask_b = 'ask_hi'
        else:
            ask_b = 'ask_top'

        if candle_pct >= 0.95:
            can_b = 'can_8'
        elif candle_pct >= 0.875:
            can_b = 'can_7'
        else:
            can_b = 'can_6'

        if gap < 0.25:
            gap_b = 'gap_sm'
        elif gap < 0.40:
            gap_b = 'gap_md'
        else:
            gap_b = 'gap_lg'

        return f'{symbol}|{ask_b}|{can_b}|{gap_b}|{direction}'

    # ── seed from existing paper trades ───────────────────────────────────────

    def _seed_from_paper_log(self):
        """Bootstrap Q-table from resolved MANIP paper trades on first run.
        Weekend-aware: reads from the active mode's trade log (weekday or weekend
        variant), and additionally filters by timestamp as a safety net."""
        try:
            path = _resolve_state_path('claude_paper_trades.json')
            if not os.path.exists(path):
                return
            with open(path, encoding='utf-8') as _f:
                trades = json.load(_f)
            _wcfg = _weekend_mode_config()
            if _wcfg.get('enabled'):
                if _is_weekend_mode_now():
                    trades = [t for t in trades if _trade_logged_in_weekend(t)]
                else:
                    trades = [t for t in trades if not _trade_logged_in_weekend(t)]
            seeded = 0
            for t in trades:
                if (t.get('play_type') != 'MANIP'
                        or not t.get('resolved')
                        or t.get('outcome') not in ('WIN', 'LOSS')
                        or t.get('paper_pnl') is None
                        or t.get('paper_stake', 0) <= 0):
                    continue
                symbol    = t.get('symbol', '')
                ask       = t.get('ask', 0.5)
                gap       = t.get('divergence') or max((t.get('prob', 75) / 100) - ask, 0)
                direction = t.get('direction', 'UP')
                # Candle pct from momentum_pct field or fall back to 0.75
                can_pct   = (t.get('momentum_pct') or 75) / 100
                key = self._state_key(symbol, ask, can_pct, gap, direction)
                roi = (t['paper_pnl'] / t['paper_stake'])
                if key not in self.q:
                    self.q[key] = {'q': roi, 'n': 1}
                    seeded += 1
                else:
                    # Only update if this trade wasn't already seeded
                    pass   # avoid double-counting on restart
            if seeded:
                self._save()
                logger.info(f'[MANIP-RL] Seeded {seeded} new states from paper log')
        except Exception as e:
            logger.warning(f'[MANIP-RL] Seed error: {e}')

    # ── public API ─────────────────────────────────────────────────────────────

    def score(self, symbol: str, ask: float, candle_pct: float, gap: float, direction: str) -> tuple:
        """Return (q_value, n_visits, state_key)."""
        key = self._state_key(symbol, ask, candle_pct, gap, direction)
        entry = self.q.get(key, {'q': 0.0, 'n': 0})
        return entry['q'], entry['n'], key

    def should_enter(self, symbol: str, ask: float, candle_pct: float, gap: float, direction: str) -> tuple:
        """
        Return (allow: bool, reason: str).
        Blocks entry only when we have enough data AND Q is below threshold.
        Gap filter: only trade gap_lg (>=0.40) — gap_md and gap_sm are net negative
        across 2091 observations (gap_md avg Q=-0.19, gap_sm avg Q=-0.07 vs gap_lg +0.36).
        """
        # Gap size filter — only large gaps are consistently profitable
        if gap < 0.40:
            gap_label = 'gap_sm' if gap < 0.25 else 'gap_md'
            return False, f'RL skip: {gap_label} gap={gap:.2f} (only gap_lg profitable)'
        q, n, key = self.score(symbol, ask, candle_pct, gap, direction)
        if n < self.MIN_VISITS:
            return True, f'RL exploring (n={n})'
        if q < self.SKIP_THRESHOLD:
            return False, f'RL skip: Q={q:.2f} n={n} [{key}]'
        return True, f'RL allow: Q={q:.2f} n={n}'

    def update(self, symbol: str, ask: float, candle_pct: float, gap: float,
               direction: str, stake: float, pnl: float):
        """Call after a MANIP trade resolves. Updates Q via EMA."""
        if stake <= 0:
            return
        roi = pnl / stake
        key = self._state_key(symbol, ask, candle_pct, gap, direction)
        now = time.time()
        if key not in self.q:
            self.q[key] = {'q': roi, 'n': 1, 'last_ts': now}
        else:
            entry = self.q[key]
            _apply_q_decay(entry, 168.0)   # decay first if stale
            old_q = entry['q']
            new_q = old_q + self.ALPHA * (roi - old_q)
            self.q[key] = {'q': round(new_q, 4), 'n': entry['n'] + 1, 'last_ts': now}
        self._dirty = True   # debounced save — flusher writes within 1s
        logger.info(f'[MANIP-RL] Updated {key}: Q={self.q[key]["q"]:.3f} n={self.q[key]["n"]}')

    def summary(self) -> str:
        """Return a short summary of learned state values."""
        if not self.q:
            return 'No data yet'
        states = sorted(self.q.items(), key=lambda x: x[1]['q'])
        worst = states[:3]
        best  = states[-3:]
        lines = ['Top states:', *[f'  {k}: Q={v["q"]:+.2f} n={v["n"]}' for k, v in reversed(best)],
                 'Worst states:', *[f'  {k}: Q={v["q"]:+.2f} n={v["n"]}' for k, v in worst]]
        return '\n'.join(lines)


# ──────────────────────────────────────────────────────────────────────────────
# HFT RL GATE
# ──────────────────────────────────────────────────────────────────────────────

class HFTRL:
    """
    Online Q-table bandit for HFT entry gating.

    State = (symbol, entry_price_bucket, secs_left_bucket, strategy)
    Q(s)  = EMA of ROI seen in that state
    Gate  : skip entry if Q(s) < SKIP_THRESHOLD after MIN_VISITS observations

    Price buckets align with the data-observed profit zones:
      p_low  <0.60  → best EV ($2.17 avg win, 69% WR)
      p_mid  0.60-0.70
      p_hi   0.70-0.80  → best overall ($1.47 avg win, 80% WR)
      p_top  0.80-0.87  → capped here; >0.87 filtered upstream

    Secs buckets:
      s_final  <20s   → very late, low time for fill
      s_late   20-40s
      s_mid    40-60s
      s_early  60-130s
    """

    RL_FILE        = 'hft_rl_state.json'
    ALPHA          = 0.15   # EMA learning rate
    SKIP_THRESHOLD = -0.30  # 2026-05-14: was -1.0 ("collecting weekend data") which left the gate
                            # effectively disabled and let MOMENTUM-BURST bleed -$1.2k live. Restored
                            # to -0.30 per daily_notes #19 (May 10 explicit recommendation:
                            # "looser than original -0.15 but tighter than current -1.0").
                            # Currently blocks the 5 worst MOM cells; lets the rest keep exploring.
    MIN_VISITS     = 5      # explore freely until 5 observations (raised from 3 — shadow WR 89.4% confirmed over-suppression at n=3)

    def __init__(self):
        self.q: dict = {}
        self._dirty  = False
        # Per-symbol overrides for gate thresholds. Class constants SKIP_THRESHOLD / MIN_VISITS
        # are the fallback. HFTScanner._load_settings populates these from symbol_overrides.<sym>.
        self.skip_threshold_by_symbol: dict = {}
        self.min_visits_by_symbol:     dict = {}
        self._load()
        self._seed_from_log()
        _start_q_decay_sweeper(self, 'HFT-RL')
        _start_dirty_flush_loop(self, 'HFT-RL')

    def _thresholds_for(self, symbol: str) -> tuple:
        """Return (skip_threshold, min_visits) for this symbol, falling back to class defaults."""
        st = self.skip_threshold_by_symbol.get(symbol, self.SKIP_THRESHOLD)
        mv = self.min_visits_by_symbol.get(symbol, self.MIN_VISITS)
        return st, mv

    def _load(self):
        try:
            path = _resolve_state_path(self.RL_FILE)
            if os.path.exists(path):
                with open(path, encoding='utf-8') as _f:
                    self.q = json.load(_f)
                logger.info(f'[HFT-RL] Loaded {len(self.q)} states from {os.path.basename(path)}')
        except Exception as e:
            logger.warning(f'[HFT-RL] Load error: {e}')
            self.q = {}

    def _save(self):
        try:
            import uuid as _u
            path = _resolve_state_path(self.RL_FILE)
            tmp  = path + f'.tmp_{_u.uuid4().hex[:8]}'
            with open(tmp, 'w') as f:
                json.dump(self.q, f, indent=2)
            os.replace(tmp, path)
        except Exception as e:
            logger.warning(f'[HFT-RL] Save error: {e}')

    @staticmethod
    def _state_key(symbol: str, entry_price: float, secs_left: float, strategy: str) -> str:
        if entry_price < 0.60:   price_b = 'p_low'
        elif entry_price < 0.70: price_b = 'p_mid'
        elif entry_price < 0.80: price_b = 'p_hi'
        else:                    price_b = 'p_top'

        if secs_left < 20:       secs_b = 's_final'
        elif secs_left < 40:     secs_b = 's_late'
        elif secs_left < 60:     secs_b = 's_mid'
        else:                    secs_b = 's_early'

        strat_b = 'MOM' if strategy == 'MOMENTUM-BURST' else 'RIDE'
        return f'{symbol}|{price_b}|{secs_b}|{strat_b}'

    def _seed_from_log(self):
        """Bootstrap Q-table from existing resolved HFT trades.
        Weekend-aware: reads from the active mode's trade log (weekday or weekend
        variant), and additionally filters by timestamp as a safety net."""
        try:
            path = _resolve_state_path('hft_paper_trades.json')
            if not os.path.exists(path):
                return
            with open(path, encoding='utf-8') as _f:
                trades = json.load(_f)
            _wcfg = _weekend_mode_config()
            if _wcfg.get('enabled'):
                if _is_weekend_mode_now():
                    trades = [t for t in trades if _trade_logged_in_weekend(t)]
                else:
                    trades = [t for t in trades if not _trade_logged_in_weekend(t)]
            seeded = 0
            for t in trades:
                if (not t.get('resolved')
                        or t.get('outcome') not in ('WIN', 'LOSS')
                        or t.get('paper_pnl') is None
                        or not t.get('stake', 0)):
                    continue
                key = self._state_key(
                    t.get('symbol', ''),
                    t.get('entry_price', 0.5),
                    t.get('secs_to_close', 30),
                    t.get('strategy', 'MOMENTUM-BURST'),
                )
                roi = t['paper_pnl'] / t['stake']
                if key not in self.q:
                    self.q[key] = {'q': roi, 'n': 1}
                    seeded += 1
                # Don't re-seed known states on restart to avoid double counting
            if seeded:
                self._save()
                logger.info(f'[HFT-RL] Seeded {seeded} new states from trade log')
        except Exception as e:
            logger.warning(f'[HFT-RL] Seed error: {e}')

    def score(self, symbol: str, entry_price: float, secs_left: float, strategy: str) -> tuple:
        """Return (q_value, n_visits, state_key)."""
        key   = self._state_key(symbol, entry_price, secs_left, strategy)
        entry = self.q.get(key, {'q': 0.0, 'n': 0})
        return entry['q'], entry['n'], key

    def should_enter(self, symbol: str, entry_price: float,
                     secs_left: float, strategy: str) -> tuple:
        """Return (allow: bool, reason: str)."""
        key   = self._state_key(symbol, entry_price, secs_left, strategy)
        entry = self.q.get(key, {'q': 0.0, 'n': 0})
        q, n  = entry['q'], entry['n']
        skip_t, min_v = self._thresholds_for(symbol)
        if n < min_v:
            return True, f'exploring n={n}'
        if q < skip_t:
            return False, f'Q={q:.2f} n={n} [{key}]'
        return True, f'Q={q:.2f} n={n}'

    def shadow_decide(self, symbol: str, entry_price: float,
                      secs_left: float, strategy: str) -> tuple:
        """Compute what the OTHER mode's gate would have decided for the same
        state. Read-only — never writes the other-mode state file. Returns
        (allow, q, n, key). Returns same thresholds (SKIP_THRESHOLD / MIN_VISITS)
        applied to the other mode's Q-table snapshot."""
        key = self._state_key(symbol, entry_price, secs_left, strategy)
        other = _load_shadow_gate_state(self.RL_FILE)
        entry = other.get(key, {'q': 0.0, 'n': 0})
        q, n  = entry.get('q', 0.0), entry.get('n', 0)
        skip_t, min_v = self._thresholds_for(symbol)
        if n < min_v:
            return True, q, n, key   # exploring in other mode → would allow
        if q < skip_t:
            return False, q, n, key
        return True, q, n, key

    def update(self, symbol: str, entry_price: float, secs_left: float,
               strategy: str, stake: float, pnl: float):
        """Call after an HFT trade resolves. Updates Q via EMA."""
        if stake <= 0:
            return
        roi = pnl / stake
        key = self._state_key(symbol, entry_price, secs_left, strategy)
        now = time.time()
        if key not in self.q:
            self.q[key] = {'q': roi, 'n': 1, 'last_ts': now}
        else:
            entry = self.q[key]
            _apply_q_decay(entry, 168.0)
            old_q = entry['q']
            self.q[key] = {'q': round(old_q + self.ALPHA * (roi - old_q), 4),
                           'n': entry['n'] + 1, 'last_ts': now}
        self._dirty = True
        logger.info(f'[HFT-RL] Updated {key}: Q={self.q[key]["q"]:.3f} n={self.q[key]["n"]}')

    def summary(self) -> dict:
        states = sorted(self.q.items(), key=lambda x: x[1]['q'])
        # Per-symbol thresholds: parse the symbol from each state key and apply that symbol's gate.
        def _is_blocked(k, v):
            sym = k.split('|', 1)[0]
            skip_t, min_v = self._thresholds_for(sym)
            return v['q'] < skip_t and v['n'] >= min_v
        blocked = [k for k, v in states if _is_blocked(k, v)]
        return {
            'total_states': len(self.q),
            'blocked_states': len(blocked),
            'avg_q': round(sum(v['q'] for v in self.q.values()) / max(len(self.q), 1), 3),
            'worst': [{'state': k, 'q': v['q'], 'n': v['n']} for k, v in states[:3]],
            'best':  [{'state': k, 'q': v['q'], 'n': v['n']} for k, v in states[-3:]],
        }


# ──────────────────────────────────────────────────────────────────────────────
# CLAUDE PICKS RL GATE
# ──────────────────────────────────────────────────────────────────────────────

def _migrate_picks_rl_to_per_type():
    """One-shot: split unified claude_picks_rl_state.json into per-play_type files.
    Runs at startup; only writes files that don't already exist. Legacy file is
    left in place for rollback. Idempotent — safe to call on every startup."""
    src = 'claude_picks_rl_state.json'
    src_path = _resolve_state_path(src) if '_resolve_state_path' in globals() else src
    if not os.path.exists(src_path):
        return
    play_types = ['TIME-LOCK','MOMENTUM','MISPRICED','NEAR-CLOSE','VOL-SURGE']
    targets = {pt: f'claude_picks_{pt.lower().replace("-","_")}_rl_state.json' for pt in play_types}
    # Skip if all per-type files already exist — migration done previously.
    if all(os.path.exists(_resolve_state_path(t) if '_resolve_state_path' in globals() else t)
           for t in targets.values()):
        return
    try:
        with open(src_path, 'r', encoding='utf-8') as f:
            q = json.load(f)
    except Exception as e:
        logger.warning(f'[PICKS-RL-MIGRATION] Cannot read {src_path}: {e}')
        return
    by_type = {pt: {} for pt in play_types}
    for k, v in q.items():
        prefix = k.split('|', 1)[0] if '|' in k else ''
        if prefix in by_type:
            by_type[prefix][k] = v
    written = []
    for pt, fname in targets.items():
        target_path = _resolve_state_path(fname) if '_resolve_state_path' in globals() else fname
        if os.path.exists(target_path):
            continue
        try:
            with open(target_path, 'w', encoding='utf-8') as f:
                json.dump(by_type[pt], f, indent=2)
            written.append(f'{pt}({len(by_type[pt])})')
        except Exception as e:
            logger.warning(f'[PICKS-RL-MIGRATION] Write error {target_path}: {e}')
    if written:
        logger.info(f'[PICKS-RL-MIGRATION] Split legacy state into per-type files: {", ".join(written)}')


class ClaudePicksRL:
    """
    Unified Q-table gate for all Claude Picks play types.
    Extends the ManipRL concept to TIME-LOCK, MISPRICED, VOL-SURGE, MOMENTUM.

    State = (play_type, symbol, ask_bucket, conviction)
    Q(s)  = EMA of ROI
    Gate  : skip if Q(s) < SKIP_THRESHOLD after MIN_VISITS
    """

    RL_FILE        = 'claude_picks_rl_state.json'
    ALPHA          = 0.15
    SKIP_THRESHOLD = -0.15
    MIN_VISITS     = 5      # higher than HFT — fewer trades per play type

    # MANIP has its own ManipRL — skip here to avoid interference
    EXCLUDED_TYPES = {'MANIP'}

    def __init__(self, play_type: str = None, state_file: str = None,
                 skip_threshold: float = None, min_visits: int = None):
        # When play_type is set, this RL instance is dedicated to one play_type
        # and uses a per-type state file (e.g. claude_picks_time_lock_rl_state.json).
        # When play_type is None, legacy unified-table behavior is preserved.
        # Per-type SKIP_THRESHOLD and MIN_VISITS overrides are optional — let each
        # category have its own gate sensitivity based on its structural profile.
        self.play_type = play_type
        if state_file:
            self.RL_FILE = state_file  # instance attr overrides class attr
        if skip_threshold is not None:
            self.SKIP_THRESHOLD = skip_threshold
        if min_visits is not None:
            self.MIN_VISITS = min_visits
        self.q: dict = {}
        self._dirty  = False
        self._load()
        # Skip auto-seed for per-type instances — migration handles initial load
        # and unwanted seeding from old paper trades can re-introduce the same
        # contamination pattern we hit on May 6.
        if play_type is None:
            self._seed_from_log()
        label = f'PICKS-RL-{play_type}' if play_type else 'PICKS-RL'
        _start_q_decay_sweeper(self, label)
        _start_dirty_flush_loop(self, label)

    def _load(self):
        try:
            path = _resolve_state_path(self.RL_FILE)
            if os.path.exists(path):
                with open(path, encoding='utf-8') as _f:
                    self.q = json.load(_f)
                logger.info(f'[PICKS-RL] Loaded {len(self.q)} states from {os.path.basename(path)}')
        except Exception as e:
            logger.warning(f'[PICKS-RL] Load error: {e}')
            self.q = {}

    def _save(self):
        try:
            import uuid as _u
            path = _resolve_state_path(self.RL_FILE)
            tmp  = path + f'.tmp_{_u.uuid4().hex[:8]}'
            with open(tmp, 'w') as f:
                json.dump(self.q, f, indent=2)
            os.replace(tmp, path)
        except Exception as e:
            logger.warning(f'[PICKS-RL] Save error: {e}')

    @staticmethod
    def _state_key(play_type: str, symbol: str, ask: float, conviction: str) -> str:
        if ask < 0.35:   ask_b = 'a_low'
        elif ask < 0.50: ask_b = 'a_mid'
        elif ask < 0.65: ask_b = 'a_hi'
        else:            ask_b = 'a_top'
        conv_b = conviction[:3].upper() if conviction else 'MED'
        return f'{play_type}|{symbol}|{ask_b}|{conv_b}'

    def _seed_from_log(self):
        """Weekend-aware: reads from the active mode's trade log (weekday or weekend
        variant), and additionally filters by timestamp as a safety net."""
        try:
            path = _resolve_state_path('claude_paper_trades.json')
            if not os.path.exists(path):
                return
            with open(path, encoding='utf-8') as _f:
                trades = json.load(_f)
            _wcfg = _weekend_mode_config()
            if _wcfg.get('enabled'):
                if _is_weekend_mode_now():
                    trades = [t for t in trades if _trade_logged_in_weekend(t)]
                else:
                    trades = [t for t in trades if not _trade_logged_in_weekend(t)]
            seeded = 0
            for t in trades:
                pt = t.get('play_type', '')
                if (pt in self.EXCLUDED_TYPES
                        or not t.get('resolved')
                        or t.get('outcome') not in ('WIN', 'LOSS')
                        or t.get('paper_pnl') is None
                        or not t.get('paper_stake', 0)):
                    continue
                key = self._state_key(pt, t.get('symbol', ''),
                                      t.get('ask', 0.5), t.get('conviction', 'HIGH'))
                roi = t['paper_pnl'] / t['paper_stake']
                if key not in self.q:
                    self.q[key] = {'q': roi, 'n': 1}
                    seeded += 1
            if seeded:
                self._save()
                logger.info(f'[PICKS-RL] Seeded {seeded} new states from paper log')
        except Exception as e:
            logger.warning(f'[PICKS-RL] Seed error: {e}')

    def score(self, play_type: str, symbol: str, ask: float, conviction: str) -> tuple:
        """Return (q_value, n_visits, state_key)."""
        key   = self._state_key(play_type, symbol, ask, conviction)
        entry = self.q.get(key, {'q': 0.0, 'n': 0})
        return entry['q'], entry['n'], key

    # Cross-state pooling — aggregate Q across all states of a play_type or
    # across all states of a (play_type, symbol) pair. Catches strategies
    # bleeding across many sparsely-visited states (VOL-SURGE, NEAR-CLOSE) and
    # symbol-wide degradation (e.g. BNB MISPRICED bad across all ask buckets).
    POOL_MIN_VISITS = 15     # need >=15 cumulative visits across all states
    POOL_THRESHOLD  = -0.10  # block if visit-weighted avg Q < -0.10

    def _pool_score(self, play_type: str) -> tuple:
        """Visit-weighted aggregate Q across every state of this play_type."""
        prefix = f'{play_type}|'
        total_n  = 0
        weighted = 0.0
        for k, v in self.q.items():
            if k.startswith(prefix):
                total_n  += v['n']
                weighted += v['q'] * v['n']
        if total_n == 0:
            return 0.0, 0
        return weighted / total_n, total_n

    def _pool_score_symbol(self, play_type: str, symbol: str) -> tuple:
        """Visit-weighted aggregate Q across every state of (play_type, symbol)."""
        prefix = f'{play_type}|{symbol}|'
        total_n  = 0
        weighted = 0.0
        for k, v in self.q.items():
            if k.startswith(prefix):
                total_n  += v['n']
                weighted += v['q'] * v['n']
        if total_n == 0:
            return 0.0, 0
        return weighted / total_n, total_n

    def _has_established_winner(self, prefix: str) -> bool:
        """Return True if any state under `prefix` has n>=MIN_VISITS and Q>=0.
        Used to spare pool-gating: if the play_type/symbol has demonstrated a
        winning slice somewhere, we don't suppress exploration of new slices."""
        for k, v in self.q.items():
            if k.startswith(prefix) and v['n'] >= self.MIN_VISITS and v['q'] >= 0:
                return True
        return False

    def should_enter(self, play_type: str, symbol: str,
                     ask: float, conviction: str) -> tuple:
        if play_type in self.EXCLUDED_TYPES:
            return True, 'MANIP uses separate RL'
        key   = self._state_key(play_type, symbol, ask, conviction)
        entry = self.q.get(key, {'q': 0.0, 'n': 0})
        q, n  = entry['q'], entry['n']
        if n >= self.MIN_VISITS and q < self.SKIP_THRESHOLD:
            return False, f'Q={q:.2f} n={n} [{key}]'
        # Pooled gate (only for exploring states n<MIN_VISITS).
        # Per-symbol pool catches symbol-wide bleed; per-play_type pool catches
        # strategies bleeding across sparse states. Both gates are SKIPPED when
        # the scope already has a demonstrated winner (any state with n>=MIN_VISITS
        # and Q>=0) — protects winning slices from "average drag" by their losers.
        if n < self.MIN_VISITS:
            sym_q, sym_n = self._pool_score_symbol(play_type, symbol)
            if (sym_n >= self.POOL_MIN_VISITS and sym_q < self.POOL_THRESHOLD
                    and not self._has_established_winner(f'{play_type}|{symbol}|')):
                return False, f'sym-pool Q={sym_q:.2f} n={sym_n} [{play_type}|{symbol}]'
            pool_q, pool_n = self._pool_score(play_type)
            if (pool_n >= self.POOL_MIN_VISITS and pool_q < self.POOL_THRESHOLD
                    and not self._has_established_winner(f'{play_type}|')):
                return False, f'pool Q={pool_q:.2f} n={pool_n} [{play_type}]'
            return True, f'exploring n={n}'
        return True, f'Q={q:.2f} n={n}'

    def update(self, play_type: str, symbol: str, ask: float,
               conviction: str, stake: float, pnl: float):
        if play_type in self.EXCLUDED_TYPES or stake <= 0:
            return
        roi = pnl / stake
        key = self._state_key(play_type, symbol, ask, conviction)
        now = time.time()
        if key not in self.q:
            self.q[key] = {'q': roi, 'n': 1, 'last_ts': now}
        else:
            entry = self.q[key]
            _apply_q_decay(entry, 168.0)
            old_q = entry['q']
            self.q[key] = {'q': round(old_q + self.ALPHA * (roi - old_q), 4),
                           'n': entry['n'] + 1, 'last_ts': now}
        self._dirty = True
        logger.info(f'[PICKS-RL] Updated {key}: Q={self.q[key]["q"]:.3f} n={self.q[key]["n"]}')

    def summary(self) -> dict:
        states = sorted(self.q.items(), key=lambda x: x[1]['q'])
        blocked = [k for k, v in states if v['q'] < self.SKIP_THRESHOLD and v['n'] >= self.MIN_VISITS]
        return {
            'total_states': len(self.q),
            'blocked_states': len(blocked),
            'avg_q': round(sum(v['q'] for v in self.q.values()) / max(len(self.q), 1), 3),
        }


# ──────────────────────────────────────────────────────────────────────────────
# HFT SCANNER — high-frequency paper trading data collection for Polymarket
# ──────────────────────────────────────────────────────────────────────────────

class CLOBWebSocketFeed:
    """
    Maintains a live price cache by subscribing to the Polymarket CLOB WebSocket.
    Streams real-time order book updates so HFTScanner doesn't need to HTTP-poll prices.

    Usage:
        feed = CLOBWebSocketFeed()
        feed.subscribe(token_id)          # call when market enters window
        feed.unsubscribe(token_id)        # call when market closes
        price = feed.get_ask(token_id)    # returns best ask or None
    """
    WS_URL = 'wss://ws-subscriptions-clob.polymarket.com/ws/market'

    def __init__(self):
        self._cache: dict  = {}          # token_id -> {'ask': float, 'bid': float, 'ts': float}
        self._subscribed: set = set()    # token_ids currently subscribed
        self._lock = threading.Lock()
        self._ws = None
        self._ws_thread = None
        self._running = False
        self._reconnect_delay = 2
        # Event-driven: callbacks fired when any tracked price changes >= threshold
        self._price_callbacks: list = []   # list of callables(token_id, ask, bid)
        self._price_change_thresh = 0.003  # 0.3¢ — only trigger on meaningful moves
        self._start()

    def register_price_callback(self, cb):
        """Register a callback(token_id, ask, bid) fired on significant price change."""
        self._price_callbacks.append(cb)

    def _start(self):
        self._running = True
        self._ws_thread = threading.Thread(target=self._run_loop, daemon=True)
        self._ws_thread.start()

    def _run_loop(self):
        import websocket as _ws_lib
        while self._running:
            try:
                ws = _ws_lib.WebSocketApp(
                    self.WS_URL,
                    on_open=self._on_open,
                    on_message=self._on_message,
                    on_error=self._on_error,
                    on_close=self._on_close,
                )
                self._ws = ws
                ws.run_forever(ping_interval=20, ping_timeout=10)
            except Exception as e:
                logger.debug(f'[WS] run_forever error: {e}')
            if self._running:
                logger.debug(f'[WS] Reconnecting in {self._reconnect_delay}s...')
                time.sleep(self._reconnect_delay)

    def _on_open(self, ws):
        logger.info('[WS] CLOB WebSocket connected')
        self._reconnect_delay = 2
        # Re-subscribe all active token_ids after reconnect
        with self._lock:
            subs = list(self._subscribed)
        if subs:
            self._send_subscribe(subs)

    def _on_message(self, ws, raw):
        try:
            events = json.loads(raw)
            if not isinstance(events, list):
                events = [events]
            now = time.time()
            changed = []
            for ev in events:
                asset_id = ev.get('asset_id') or ev.get('market')
                if not asset_id:
                    continue
                # Parse book update — bids/asks arrays of {price, size}
                asks = ev.get('asks') or []
                bids = ev.get('bids') or []
                best_ask = None
                best_bid = None
                if asks:
                    try:
                        best_ask = min(float(a['price']) for a in asks if float(a.get('size', 0)) > 0)
                    except Exception:
                        pass
                if bids:
                    try:
                        best_bid = max(float(b['price']) for b in bids if float(b.get('size', 0)) > 0)
                    except Exception:
                        pass
                if best_ask is not None or best_bid is not None:
                    changed.append((asset_id, best_ask, best_bid, now))
            if changed:
                to_notify = []
                with self._lock:
                    for asset_id, ask, bid, ts in changed:
                        prev = self._cache.get(asset_id, {})
                        prev_ask = prev.get('ask')
                        new_ask  = ask if ask is not None else prev_ask
                        new_bid  = bid if bid is not None else prev.get('bid')
                        self._cache[asset_id] = {'ask': new_ask, 'bid': new_bid, 'ts': ts}
                        # Fire callbacks only when price moved enough to matter
                        if (self._price_callbacks and new_ask is not None and prev_ask is not None
                                and abs(new_ask - prev_ask) >= self._price_change_thresh):
                            to_notify.append((asset_id, new_ask, new_bid))
                for asset_id, ask, bid in to_notify:
                    for cb in self._price_callbacks:
                        try:
                            cb(asset_id, ask, bid)
                        except Exception:
                            pass
        except Exception as e:
            logger.debug(f'[WS] message parse error: {e}')

    def _on_error(self, ws, error):
        logger.debug(f'[WS] error: {error}')

    def _on_close(self, ws, code, msg):
        logger.debug(f'[WS] closed: {code} {msg}')

    def _send_subscribe(self, token_ids: list):
        if not self._ws:
            return
        try:
            msg = json.dumps({'assets_ids': token_ids, 'type': 'market'})
            self._ws.send(msg)
            logger.debug(f'[WS] Subscribed to {len(token_ids)} token(s)')
        except Exception as e:
            logger.debug(f'[WS] subscribe send error: {e}')

    def subscribe(self, token_id: str):
        with self._lock:
            if token_id in self._subscribed:
                return
            self._subscribed.add(token_id)
        self._send_subscribe([token_id])

    def unsubscribe(self, token_id: str):
        with self._lock:
            self._subscribed.discard(token_id)
            self._cache.pop(token_id, None)

    def get_ask(self, token_id: str) -> float | None:
        with self._lock:
            entry = self._cache.get(token_id)
        if not entry:
            return None
        # Stale after 10s — fall back to HTTP
        if time.time() - entry['ts'] > 10:
            return None
        return entry.get('ask')

    def get_bid(self, token_id: str) -> float | None:
        with self._lock:
            entry = self._cache.get(token_id)
        if not entry:
            return None
        if time.time() - entry['ts'] > 10:
            return None
        return entry.get('bid')

    def stop(self):
        self._running = False
        if self._ws:
            try:
                self._ws.close()
            except Exception:
                pass


class HFTScanner:
    """
    High-frequency scanner for Polymarket 5m markets.

    Scans every 8 seconds for 5m markets in their final 20-120 seconds.
    Two paper-trading strategies (paper only — data collection phase):

    Strategy 1 — MOMENTUM-BURST
        Market is in its last 60s. YES price has moved >10¢ off midpoint.
        Enter in the direction of momentum.

    Strategy 2 — EXTREME-RIDE
        Market is in its last 90s. Price at moderate extreme (75¢–90¢ or 10¢–25¢)
        and sustained across two scans. Ride the direction — paper data showed
        0/16 wins fading extremes; inverting to ride gives meaningful profit margin.
    """

    SYMBOLS      = ['BTC', 'ETH', 'SOL', 'XRP', 'DOGE', 'HYPE', 'BNB']
    GAMMA        = "https://gamma-api.polymarket.com"
    HFT_LOG_FILE = 'hft_paper_trades.json'
    HFT_LOG_MAX_ENTRIES = 50000  # disk-write cap. ~33 MB at full count.
                                 # Async save worker keeps it off the hot path,
                                 # but if you raise above 100k, refactor to JSONL.
    PAPER_STAKE  = 5.0
    FEE_RATE     = 0.0   # 2026-05-10: confirmed 0% via Polymarket data API (fee_rate_bps null on recent fills) — was 0.02

    HFT_SETTINGS_FILE = 'hft_settings.json'

    def __init__(self, bot_ref=None):
        self.bot = bot_ref
        self._trades: list = []
        self._lock = threading.Lock()
        self._scan_count = 0
        self._last_scan_ts = 0.0
        # Event-driven scan trigger — set by CLOB WS callback (existing) AND Binance WS callback (NEW).
        # Allows scan to fire on Binance moves BEFORE Polymarket reprices, racing into the lag window.
        self._scan_event = threading.Event()
        self._binance_trigger_count: int = 0   # how many times Binance triggered a scan (for telemetry)
        self._clob_trigger_count: int = 0      # how many times CLOB triggered (for telemetry)
        self._market_cache: dict = {}    # slug -> {price, ts} for EXTREME-RIDE detection
        self._meta_cache: dict = {}      # slug -> {tokens, end_ts} — persists within 5m window
        self._entered_keys: set = set()  # slug+direction already entered this market cycle
        # Persistent HTTP session — reuses TCP connections, saves ~30ms per request.
        # CRITICAL: bump urllib3 connection pool from default (10) to 100 — at default
        # the bot froze at 23:30 May 6 with "Connection pool is full, discarding
        # connection" warnings flooding, and the scanner stopped producing trades.
        self._session = requests.Session()
        self._session.headers.update({'Accept-Encoding': 'gzip'})
        from requests.adapters import HTTPAdapter
        _adapter = HTTPAdapter(pool_connections=50, pool_maxsize=100, max_retries=2)
        self._session.mount('http://', _adapter)
        self._session.mount('https://', _adapter)
        # 2026-05-17 protection_override: when True, suppresses circuit breaker / auto-filter / auto-pause
        # auto-flips so user-set live_mode stays live. Default off (safer). Loaded from settings file.
        self.protection_override: bool = False
        # Live WebSocket price feed — sub-50ms price updates, replaces HTTP polling
        self._ws_feed = CLOBWebSocketFeed()
        # RL entry gate — learns which (symbol, price, timing, strategy) states are profitable
        self.rl = HFTRL()
        self.rl_shadow = RLShadowLog('hft_rl_blocked.json')
        # Live trading settings — loaded from file, configurable via UI
        self.live_mode: bool = False
        self.stake: float = self.PAPER_STAKE
        self.drawdown_floor: float = 0.0   # auto-switch to paper if USDC balance drops below this
        self.paper_strategies: set = set()  # strategies forced to paper (e.g. {'EXTREME-RIDE'})
        self.paper_symbols: set = set()    # symbols manually forced to paper via UI toggle
        # Directions auto-set by circuit-breaker when (UP or DOWN) side bleeds badly.
        # Catches payoff-asymmetry bleeds that high-WR-threshold checks miss. e.g. UP can be 75% WR
        # but lose money due to small avg_win vs full avg_loss. Format: {'UP', 'DOWN'} subset.
        self.paper_directions: set = set()
        # MOMENTUM-BURST R/R tuning (overrides class-level SL_THRESHOLD when set):
        self.mb_sl_threshold: float = -0.10   # 10% drop triggers SL exit (was -0.20)
        self.mb_max_entry: float = 0.65       # cap MOMENTUM-BURST entries at this price (was 0.87)
        # Sizing mode (2026-05-30, user toggle): 'kelly' = RL-Kelly sizing capped at stake;
        # 'fixed' = bet exactly self.stake on every entry (respect the user's set bet amount).
        self.sizing_mode: str = 'kelly'
        # Per-symbol gate overrides — see _load_settings for schema. Empty dict = pure backward compat.
        # Each entry: { skip_threshold?, min_visits?, directions?, strategies?, sessions?, hours? }
        # Per-symbol restrictions are applied BEFORE the RL gate at scan time.
        self.symbol_overrides: dict = {}
        # Per-cell paper/real overrides (added 2026-05-22). Keyed by "SYM|DIR|STRAT" -> 'paper'|'real'.
        # Takes precedence over paper_strategies/paper_symbols/paper_directions/auto-filter — lets
        # the operator whitelist a profitable cell inside an otherwise-papered symbol, or quarantine
        # a single bleeding cell without papering the whole strategy. Mirrors the Claude Picks
        # _cell_overrides pattern. Empty dict = no per-cell rules (pure dimension-level behavior).
        self.cell_overrides: dict = {}
        self._auto_paper_keys: set = set()  # symbol×strategy combos auto-filtered to paper
        self._auto_filter_counter: int = 0  # runs every 60 scans
        self._settings_reload_counter: int = 0  # reload settings every 60 scans
        # Cached CLOB collateral balance for drawdown floor check — populated by background poller.
        # Avoids the per-scan HTTP round-trip that was blocking ~110ms on every scan.
        self._cached_clob_balance: Optional[float] = None
        self._cached_clob_balance_ts: float = 0.0
        # Async save worker — JSON serialization (~78ms) moved off trade entry hot path.
        # _request_save() puts a marker on this queue; worker thread snapshots + writes.
        import queue as _queue
        self._save_queue: _queue.Queue = _queue.Queue(maxsize=1)  # bounded — coalesces requests
        self._save_thread: Optional[threading.Thread] = None
        # Background market metadata cache — refreshed every 3s in own thread.
        # scan_once reads from this cache instead of doing 2× ThreadPoolExecutor Gamma probes
        # per iteration (~300-500ms saved per scan). Mirrors BTC-ML's _market_refresh_loop.
        self._market_bg_cache: list = []
        self._market_bg_lock = threading.Lock()
        # CLOB market-info pre-warm dedup (2026-06-05 exec-path speed fix). Holds condition_ids
        # already warmed via clob_client.get_clob_market_info so create_order does zero network
        # on the fire path. See SPEED_AUDIT_EXECPATH_2026-06-05.md.
        self._prewarmed_conditions: set = set()
        self._load_settings()
        self._load_log()
        # Run auto-filter immediately on startup so state is correct from first scan
        self._update_auto_paper_filter()
        # Re-seed entered_keys from unresolved trades so we don't double-enter on restart
        for t in self._trades:
            if not t.get('resolved'):
                self._entered_keys.add(f"{t.get('market_slug','')}_{t.get('direction','')}")
        logger.info(f"[HFT] Scanner initialized — {len(self._trades)} trades loaded, "
                    f"{sum(1 for t in self._trades if not t.get('resolved'))} pending | "
                    f"mode={'LIVE' if self.live_mode else 'PAPER'} stake=${self.stake:.2f}")

    # ── background pollers ────────────────────────────────────────────────────

    def start_save_worker(self):
        """Start background thread that performs trade log saves off the hot path.
        Trade entry calls _request_save() which is ~1ms (queue put + lock copy);
        actual JSON serialization (~78ms for 3000-trade list) happens here."""
        import threading as _th
        if self._save_thread and self._save_thread.is_alive():
            return
        self._save_thread = _th.Thread(
            target=self._save_worker, daemon=True, name='hft-save')
        self._save_thread.start()
        logger.info('[HFT] Async save worker started')

    def _request_save(self):
        """Mark a save as needed. No-op if a save is already pending (coalesces bursts).
        Use INSTEAD of _save_log() on hot paths."""
        try:
            self._save_queue.put_nowait(True)
        except Exception:
            pass  # queue full = save already pending

    def _save_worker(self):
        """Snapshot _trades under lock, serialize and write outside lock."""
        import uuid as _uuid
        while True:
            try:
                self._save_queue.get()  # blocks until save requested
                with self._lock:
                    snapshot = list(self._trades[-self.HFT_LOG_MAX_ENTRIES:])  # match sync path's slice
                path = _resolve_state_path(self.HFT_LOG_FILE)
                # 2026-05-23 PR-5: orjson-backed atomic write
                _atomic_write_json(path, snapshot, indent=False)
            except Exception as e:
                logger.warning(f'[HFT] Async save error: {e}')

    def start_drawdown_poller(self):
        """Start background thread that polls CLOB collateral balance every 30s.
        scan_once reads the cached value instead of blocking on a CLOB HTTP call per scan."""
        import threading as _th
        if getattr(self, '_drawdown_thread', None) and self._drawdown_thread.is_alive():
            return
        self._drawdown_thread = _th.Thread(
            target=self._drawdown_poll_loop, daemon=True, name='hft-drawdown-poll')
        self._drawdown_thread.start()
        logger.info('[HFT] Drawdown balance poller started (30s interval)')

    def start_market_refresh(self):
        """Start background thread that refreshes 5m+15m active markets every 3s.
        scan_once reads from _market_bg_cache instead of doing 2× ThreadPoolExecutor
        Gamma probes per iteration. Saves ~300-500ms per scan."""
        import threading as _th
        if getattr(self, '_market_thread', None) and self._market_thread.is_alive():
            return
        self._market_thread = _th.Thread(
            target=self._market_refresh_loop, daemon=True, name='hft-market-cache')
        self._market_thread.start()
        logger.info('[HFT] Market cache refresher started (3s interval)')

    def _market_refresh_loop(self):
        """Poll Gamma for 5m+15m active markets every 3s; populate _market_bg_cache."""
        import time as _t
        _t.sleep(2)  # let init finish
        while True:
            try:
                fresh = self._fetch_active_5m_markets() + self._fetch_active_15m_markets()
                with self._market_bg_lock:
                    self._market_bg_cache = fresh
            except Exception as e:
                logger.debug(f'[HFT] Market cache refresh error: {e}')
            _t.sleep(3)

    def _drawdown_poll_loop(self):
        """Poll CLOB collateral balance every 30s. Replaces the per-scan blocking call."""
        import time as _t
        _t.sleep(15)  # let server fully init before first poll
        while True:
            try:
                if self.bot and self.bot.clob_client:
                    from py_clob_client_v2.clob_types import BalanceAllowanceParams, AssetType
                    _dd_params = BalanceAllowanceParams(
                        asset_type=AssetType.COLLATERAL, signature_type=2)
                    _dd_info = self.bot.clob_client.get_balance_allowance(_dd_params)
                    if isinstance(_dd_info, dict):
                        clob_bal = float(_dd_info.get('balance', 0))
                        self._cached_clob_balance = clob_bal
                        self._cached_clob_balance_ts = _t.time()
            except Exception as e:
                logger.debug(f'[HFT-DRAWDOWN-POLL] {e}')
            _t.sleep(30)

    # ── event-driven trigger registration ─────────────────────────────────────

    def register_binance_trigger(self, ws):
        """
        Register a BinancePriceWS (single-symbol) to wake the scan loop on Binance price moves.
        Used for BTC via BTC-ML's existing WS instance.
        """
        if ws is None:
            return
        ws.register(self._on_binance_move)
        logger.info('[HFT] Binance WS trigger registered (single-symbol) — event-driven on Binance moves')

    def register_binance_multi_trigger(self, multi_ws):
        """
        Register a BinanceMultiAggTradeWS to wake the scan loop on multi-symbol Binance moves.
        Catches per-symbol moves on SOL/XRP/BNB/ETH/DOGE that aren't predicted by BTC alone.
        """
        if multi_ws is None:
            return
        multi_ws.register(self._on_binance_multi_move)
        logger.info('[HFT] Binance multi-symbol WS trigger registered — '
                    'event-driven on per-symbol moves')

    def _on_binance_move(self, price: float, pct: float, direction: str):
        """Fired by single-symbol BinancePriceWS (BTC) on price moves >= threshold."""
        self._binance_trigger_count += 1
        self._scan_event.set()

    def _on_binance_multi_move(self, symbol: str, price: float, pct: float, direction: str):
        """Fired by BinanceMultiAggTradeWS on per-symbol moves >= threshold.
        Wakes scan immediately so we can race into the Polymarket lag window for THIS symbol."""
        self._binance_trigger_count += 1
        self._scan_event.set()

    # ── file I/O ──────────────────────────────────────────────────────────────

    def _load_log(self):
        try:
            path = _resolve_state_path(self.HFT_LOG_FILE)
            if os.path.exists(path):
                # 2026-05-23 PR-5 fix: utf-8 for orjson-written files
                with open(path, 'r', encoding='utf-8') as f:
                    self._trades = json.load(f)
                logger.info(f'[HFT] Loaded {len(self._trades)} trades from {os.path.basename(path)}')
        except Exception as e:
            logger.warning(f'[HFT] Load error: {e}')
            self._trades = []

    def _save_log(self):
        """Save trades to disk. Delegates to async worker (~1ms) when running,
        falls back to synchronous serialization (~78ms for 3000 trades) before worker starts."""
        if self._save_thread and self._save_thread.is_alive():
            self._request_save()
            return
        # Synchronous fallback — used during __init__ and before start_save_worker()
        try:
            path = _resolve_state_path(self.HFT_LOG_FILE)
            # 2026-05-23 PR-5: orjson-backed atomic write
            _atomic_write_json(path, self._trades[-self.HFT_LOG_MAX_ENTRIES:], indent=False)
        except Exception as e:
            logger.warning(f'[HFT] Save error: {e}')

    # Kelly constants — tune via /hft kelly command or hft_settings.json
    KELLY_FRACTION   = 0.25   # quarter-Kelly (conservative)
    KELLY_MIN_STAKE  = 5.0    # never bet less than $5
    KELLY_MAX_STAKE  = 20.0   # never bet more than $20
    KELLY_MIN_N      = 10     # observations needed before Kelly overrides default stake
    KELLY_ROLL_WIN   = 20     # rolling window size for hot/cold multiplier
    KELLY_ROLL_MIN_N = 8      # min resolved trades before multiplier activates

    # ── Auto profitability filter ─────────────────────────────────────────────

    AUTO_FILTER_WINDOW   = 30   # rolling window of confirmed fills to evaluate
    AUTO_FILTER_MIN_N    = 15   # min trades before filter activates
    AUTO_FILTER_BUFFER   = -2.0  # pp above breakeven needed to re-enable live trading
    AUTO_FILTER_HYSTER   = 1.0  # pp below breakeven needed to disable (avoids flapping)

    def _update_auto_paper_filter(self):
        """
        For each symbol×strategy pair with enough confirmed-fill history,
        compute rolling breakeven WR and auto-paper any combo that is losing.

        Breakeven WR = |avg_loss| / (avg_win + |avg_loss|)
        - Pair is ENABLED for live if rolling WR >= breakeven + AUTO_FILTER_BUFFER
        - Pair is DISABLED (paper only) if rolling WR < breakeven - AUTO_FILTER_HYSTER
        - Pairs with < AUTO_FILTER_MIN_N trades stay in their current state (no change)

        Always tracks paper trades regardless — auto-filter only gates live routing.
        """
        # 2026-05-17 protection_override: skip the auto-filter recompute entirely so the
        # _auto_paper_keys set doesn't change behind the user's back.
        if getattr(self, 'protection_override', False):
            return
        with self._lock:
            trades = list(self._trades)

        confirmed = [t for t in trades
                     if t.get('fill_confirmed') is True
                     and t.get('resolved')
                     and t.get('outcome') in ('WIN', 'LOSS')]

        combos = set((t.get('symbol',''), t.get('strategy','')) for t in confirmed)
        new_auto_paper = set()
        status_lines = []

        for sym, strat in combos:
            if not sym or not strat:
                continue
            ts = [t for t in confirmed
                  if t.get('symbol') == sym and t.get('strategy') == strat]
            if len(ts) < self.AUTO_FILTER_MIN_N:
                # Not enough data — keep current state, don't flip either way
                k = f'{sym}_{strat}'
                if k in self._auto_paper_keys:
                    new_auto_paper.add(k)   # stay papered until we have data
                continue

            recent = ts[-self.AUTO_FILTER_WINDOW:]
            wins   = [t for t in recent if t.get('outcome') == 'WIN']
            losses = [t for t in recent if t.get('outcome') == 'LOSS']
            if not wins or not losses:
                # All wins or all losses — can't compute proper breakeven
                if not wins:
                    new_auto_paper.add(f'{sym}_{strat}')
                continue

            roll_wr   = len(wins) / len(recent) * 100
            avg_win   = sum(t.get('paper_pnl', 0) for t in wins)  / len(wins)
            avg_loss  = abs(sum(t.get('paper_pnl', 0) for t in losses) / len(losses))
            be_wr     = avg_loss / (avg_win + avg_loss) * 100  # breakeven WR
            edge      = roll_wr - be_wr
            k         = f'{sym}_{strat}'
            currently_papered = k in self._auto_paper_keys

            if edge >= self.AUTO_FILTER_BUFFER:
                # Profitable — allow live
                if currently_papered:
                    logger.info(
                        f'[AUTO-FILTER] UNLOCKED {sym} {strat} — '
                        f'WR={roll_wr:.1f}% breakeven={be_wr:.1f}% edge={edge:+.1f}pp '
                        f'(n={len(recent)})'
                    )
                    try:
                        if self.bot:
                            self.bot._tg_notify(
                                f'✅ HFT auto-filter UNLOCKED {sym} {strat}\n'
                                f'WR {roll_wr:.0f}% / need {be_wr:.0f}% — edge {edge:+.1f}pp'
                            )
                    except Exception:
                        pass
            else:
                # Unprofitable or insufficient edge — force paper
                new_auto_paper.add(k)
                if not currently_papered:
                    logger.info(
                        f'[AUTO-FILTER] PAPERED {sym} {strat} — '
                        f'WR={roll_wr:.1f}% breakeven={be_wr:.1f}% edge={edge:+.1f}pp '
                        f'(n={len(recent)})'
                    )
                    try:
                        if self.bot:
                            self.bot._tg_notify(
                                f'⚠️ HFT auto-filter PAPERED {sym} {strat}\n'
                                f'WR {roll_wr:.0f}% / need {be_wr:.0f}% — edge {edge:+.1f}pp'
                            )
                    except Exception:
                        pass

            status_lines.append(
                f'{sym}/{strat}: WR={roll_wr:.0f}% be={be_wr:.0f}% '
                f'edge={edge:+.1f}pp n={len(recent)} '
                f'{"PAPER" if k in new_auto_paper else "LIVE"}'
            )

        self._auto_paper_keys = new_auto_paper
        if status_lines:
            logger.info('[AUTO-FILTER] ' + '  |  '.join(status_lines))

    def _hft_rolling_mult(self, symbol: str, strategy: str) -> float:
        """
        Return a stake multiplier (0.65–1.35) from recent rolling performance
        of this symbol×strategy pair in the HFT trade log.

        Uses the last KELLY_ROLL_WIN resolved (non-pending) trades.
        Baseline = all-time WR for this pair (min 5 trades), else 0.55.
        Requires KELLY_ROLL_MIN_N trades before activating (returns 1.0 otherwise).
        """
        resolved = [t for t in self._trades
                    if t.get('resolved') and t.get('outcome') in ('WIN', 'LOSS')
                    and t.get('symbol', '').upper() == symbol.upper()
                    and t.get('strategy', '') == strategy]
        if len(resolved) < self.KELLY_ROLL_MIN_N:
            return 1.0
        # Baseline = all-time WR for this pair
        baseline_wr = sum(1 for t in resolved if t.get('won')) / len(resolved) * 100
        # Rolling window WR
        recent = resolved[-self.KELLY_ROLL_WIN:]
        rolling_wr = sum(1 for t in recent if t.get('won')) / len(recent) * 100
        deviation  = rolling_wr - baseline_wr
        raw_mult   = 1.0 + 0.40 * max(-1.0, min(1.0, deviation / 15.0))
        mult       = round(max(0.65, min(1.35, raw_mult)), 3)
        logger.debug(
            f'[HFT-KELLY-ROLL] {symbol} {strategy}: '
            f'baseline={baseline_wr:.1f}% rolling={rolling_wr:.1f}% '
            f'(n={len(recent)}) dev={deviation:+.1f}pp → mult={mult:.3f}'
        )
        return mult

    def _kelly_stake(self, symbol: str, entry_price: float,
                     secs_left: float, strategy: str) -> float:
        """
        Return Kelly-sized stake using the RL Q-value as the expected ROI signal.

        Kelly fraction for a prediction market token bought at price e:
            f* = e * Q / (1 - e)
        where Q = RL expected ROI for this state.

        Applied as: stake = KELLY_FRACTION * f* * bankroll
        Clamped to [KELLY_MIN_STAKE, KELLY_MAX_STAKE].
        Falls back to self.stake if RL has < KELLY_MIN_N observations.
        Rolling multiplier (0.65–1.35) applied on top for hot/cold streaks.

        Fixed-stake mode: if sizing_mode == 'fixed', bypass Kelly entirely and bet
        exactly self.stake on every entry (2026-05-30, user — "respect my bet amount").
        """
        if getattr(self, 'sizing_mode', 'kelly') == 'fixed':
            return round(float(self.stake), 2)
        try:
            entry = self.rl.q.get(
                self.rl._state_key(symbol, entry_price, secs_left, strategy),
                {'q': None, 'n': 0}
            )
            q_val = entry.get('q')
            n     = entry.get('n', 0)

            if q_val is None or n < self.KELLY_MIN_N:
                return self.stake  # not enough data yet — use fixed stake

            # User-configured stake is the HARD CEILING for Kelly sizing
            # (2026-05-24: user reported HFT betting above the UI stake; previously
            # the hardcoded KELLY_MAX_STAKE=20 overrode the user's setting).
            _max = float(self.stake)
            _min = min(self.KELLY_MIN_STAKE, _max)

            if q_val <= 0:
                return _min  # negative/zero EV — floor (capped to user max)

            # Get live bankroll
            bankroll = self.stake * 75  # fallback: 75× current stake ≈ reasonable bankroll
            if self.bot:
                try:
                    bal = self.bot.get_usdc_balance(max_age=120)
                    if bal > 0:
                        bankroll = bal
                except Exception:
                    pass

            e = entry_price
            kelly_f   = (e * q_val) / max(1 - e, 0.01)  # core formula
            raw       = self.KELLY_FRACTION * kelly_f * bankroll
            base_stake = round(max(min(raw, _max), _min), 2)
            # Rolling hot/cold multiplier
            roll_mult = self._hft_rolling_mult(symbol, strategy)
            # Session-aware Kelly: US_AFT 1.0x, US_OPEN 0.7x, ASIA/OVERNIGHT 0.5x
            sess_mult = _session_kelly_mult()
            stake     = round(max(min(base_stake * roll_mult * sess_mult, _max), _min), 2)
            logger.debug(
                f'[HFT-KELLY] {symbol} e={e:.2f} Q={q_val:+.3f} n={n} '
                f'bankroll=${bankroll:.0f} → f*={kelly_f:.3f} raw=${raw:.2f} '
                f'base=${base_stake:.2f} × roll={roll_mult:.3f} × sess={sess_mult:.2f} → ${stake:.2f}'
            )
            return stake
        except Exception as err:
            logger.debug(f'[HFT-KELLY] Error: {err} — using fixed stake')
            return self.stake

    def _cell_filters_match(self, entry: dict, sig: dict, symbol: str) -> bool:
        """Match check for filtered cell_overrides (added 2026-05-22).

        entry is a cell_override value dict like:
            {'mode': 'real', 'hour': 'h12-16', 'timeframe': '5m', ...}
        Returns True iff ALL specified filter keys match the current signal+context.
        Missing filter keys = wildcard (always match).
        Each filter value may be a single string OR a list of allowed values.

        Supported filter keys (match the dimensions in /api/hft-backtest-max):
            hour:      h00-04 .. h20-24      (computed from current UTC hour)
            session:   ASIA / US_OPEN / US_AFT / OVERNIGHT
            timeframe: 5m or 15m              (parsed from market slug)
            price:     p60-65 .. p85-90       (from signal entry_price)
            secs:      <20s / 20-40s / 40-60s / 60s+
        """
        if not isinstance(entry, dict):
            return True
        def _in_filter(filter_val, actual):
            if isinstance(filter_val, (list, tuple, set)):
                return actual in filter_val
            return actual == filter_val

        if 'hour' in entry:
            _h = datetime.now(timezone.utc).hour
            bucket = ('h00-04' if _h < 4 else 'h04-08' if _h < 8 else 'h08-12' if _h < 12
                      else 'h12-16' if _h < 16 else 'h16-20' if _h < 20 else 'h20-24')
            if not _in_filter(entry['hour'], bucket): return False
        if 'session' in entry:
            _h = datetime.now(timezone.utc).hour
            sess = ('ASIA' if _h < 8 else 'US_OPEN' if _h < 12 else 'US_AFT' if _h < 20 else 'OVERNIGHT')
            if not _in_filter(entry['session'], sess): return False
        if 'timeframe' in entry:
            slug = sig.get('slug') or sig.get('market_slug') or ''
            tf = '15m' if '-updown-15m-' in slug else '5m'
            if not _in_filter(entry['timeframe'], tf): return False
        if 'price' in entry:
            p = float(sig.get('entry_price', 0) or 0)
            bucket = ('p60-65' if p < 0.65 else 'p65-70' if p < 0.70 else 'p70-75' if p < 0.75
                      else 'p75-80' if p < 0.80 else 'p80-85' if p < 0.85 else 'p85-90')
            if not _in_filter(entry['price'], bucket): return False
        if 'secs' in entry:
            s = float(sig.get('secs_to_close', 999) or 999)
            bucket = '<20s' if s < 20 else '20-40s' if s < 40 else '40-60s' if s < 60 else '60s+'
            if not _in_filter(entry['secs'], bucket): return False
        return True

    def _load_settings(self):
        try:
            path = _resolve_state_path(self.HFT_SETTINGS_FILE)
            if os.path.exists(path):
                with open(path, 'r') as f:
                    s = json.load(f)
                self.live_mode        = bool(s.get('live_mode', False))
                self.stake            = float(s.get('stake', self.PAPER_STAKE))
                _sm                   = str(s.get('sizing_mode', 'kelly')).lower()
                self.sizing_mode      = _sm if _sm in ('kelly', 'fixed') else 'kelly'
                self.drawdown_floor   = float(s.get('drawdown_floor', 0.0))
                self.paper_strategies = set(s.get('paper_strategies', []))
                self.paper_symbols    = set(s.get('paper_symbols', []))
                self.paper_directions = set(s.get('paper_directions', []))
                self.mb_sl_threshold  = float(s.get('mb_sl_threshold', -0.10))
                self.mb_max_entry     = float(s.get('mb_max_entry', 0.65))
                # 2026-05-17: protection_override = if True, circuit-breaker/auto-pause/auto-filter
                # are bypassed (manual paper_symbols/strategies/directions still respected).
                self.protection_override = bool(s.get('protection_override', False))
                # 2026-05-19: per-symbol gate overrides.
                # schema: symbol_overrides = { "SYM": {skip_threshold, min_visits, directions,
                #                                      strategies, sessions, hours} }
                # Each field is OPTIONAL; missing/null = no restriction. Hours overrides sessions.
                self.symbol_overrides = dict(s.get('symbol_overrides') or {})
                # 2026-05-22: per-cell paper/real overrides. Keyed "SYM|DIR|STRAT" -> str OR dict.
                # Value can be:
                #   - bare string 'paper' | 'real' (no filters, no bypass)
                #   - dict {mode: 'paper'|'real', hour?, session?, timeframe?, price?, secs?, bypass_rl?}
                #     where hour/session/timeframe/price/secs are optional filters (single or list)
                #     and bypass_rl=true skips the RL gate check for that cell.
                # Sanitize: drop entries without a valid mode.
                _raw_co = s.get('cell_overrides') or {}
                _clean_co = {}
                for k, v in _raw_co.items():
                    if v in ('paper', 'real'):
                        _clean_co[k] = v
                    elif isinstance(v, dict) and v.get('mode') in ('paper', 'real'):
                        _clean_co[k] = v
                self.cell_overrides = _clean_co
                # Push per-symbol thresholds into the RL instance. Missing fields leave the RL
                # falling back to its class defaults (HFTRL.SKIP_THRESHOLD / MIN_VISITS).
                self.rl.skip_threshold_by_symbol = {}
                self.rl.min_visits_by_symbol     = {}
                for _sym, _ovr in self.symbol_overrides.items():
                    if not isinstance(_ovr, dict): continue
                    _st = _ovr.get('skip_threshold')
                    _mv = _ovr.get('min_visits')
                    if _st is not None:
                        try: self.rl.skip_threshold_by_symbol[_sym] = float(_st)
                        except Exception: pass
                    if _mv is not None:
                        try: self.rl.min_visits_by_symbol[_sym] = int(_mv)
                        except Exception: pass
                logger.info(f'[HFT] Loaded settings from {os.path.basename(path)} protection_override={self.protection_override} symbol_overrides={len(self.symbol_overrides)} cell_overrides={len(self.cell_overrides)} per-symbol-thresh={len(self.rl.skip_threshold_by_symbol)}')
        except Exception as e:
            logger.warning(f'[HFT] Settings load error: {e}')

    def _save_settings(self):
        try:
            path = _resolve_state_path(self.HFT_SETTINGS_FILE)
            with open(path, 'w') as f:
                json.dump({
                    'live_mode':        self.live_mode,
                    'stake':            self.stake,
                    'sizing_mode':      getattr(self, 'sizing_mode', 'kelly'),
                    'drawdown_floor':   self.drawdown_floor,
                    'paper_strategies': sorted(self.paper_strategies),
                    'paper_symbols':    sorted(self.paper_symbols),
                    'paper_directions': sorted(self.paper_directions),
                    'mb_sl_threshold':  self.mb_sl_threshold,
                    'mb_max_entry':     self.mb_max_entry,
                    'protection_override': bool(getattr(self, 'protection_override', False)),
                    'symbol_overrides': self.symbol_overrides,
                    'cell_overrides':   self.cell_overrides,  # 2026-05-22
                }, f, indent=2)
        except Exception as e:
            logger.warning(f'[HFT] Settings save error: {e}')

    # ── market fetching ───────────────────────────────────────────────────────

    @staticmethod
    def _current_5m_ts() -> int:
        """Current 5-minute boundary timestamp (UTC)."""
        from datetime import timezone as _tz
        now = datetime.now(_tz.utc)
        return int(now.replace(minute=(now.minute // 5) * 5, second=0, microsecond=0).timestamp())

    @staticmethod
    def _current_15m_ts() -> int:
        """Current 15-minute boundary timestamp (UTC)."""
        from datetime import timezone as _tz
        now = datetime.now(_tz.utc)
        return int(now.replace(minute=(now.minute // 15) * 15, second=0, microsecond=0).timestamp())

    def _probe_slug(self, symbol: str, slug: str, end_ts: float) -> Optional[dict]:
        """
        Probe one slug against Gamma. Returns market dict or None.
        Token IDs are cached in _meta_cache — Gamma is only hit once per slug per window.
        """
        # Cache hit — token IDs don't change within a 5m window
        if slug in self._meta_cache:
            return self._meta_cache[slug]
        try:
            r = self._session.get(
                f"{self.GAMMA}/events",
                params={'slug': slug}, timeout=4
            )
            if r.status_code != 200:
                return None
            data = r.json()
            if not isinstance(data, list) or not data:
                return None
            event = data[0]
            mkt = event.get('markets', [{}])[0] if event.get('markets') else {}
            if not mkt:
                return None
            token_ids = mkt.get('clobTokenIds', [])
            if isinstance(token_ids, str):
                token_ids = json.loads(token_ids)
            entry = {
                'slug': slug,
                '_symbol': symbol,
                'end_ts': end_ts,
                'tokens': token_ids,
                # conditionId carried so scan_once can pre-warm the CLOB tick/neg_risk/fee
                # cache off the hot path — removes ~340-420ms of inline GETs from _live_enter.
                'conditionId': mkt.get('conditionId', ''),
                'outcomePrices': mkt.get('outcomePrices', []),
                'active': mkt.get('active', True),
                'closed': mkt.get('closed', False),
            }
            self._meta_cache[slug] = entry
            return entry
        except Exception as e:
            logger.debug(f'[HFT] Probe {slug}: {e}')
            return None

    def _fetch_active_5m_markets(self) -> list:
        """
        Build list of active 5m markets by probing slug patterns in parallel.
        Token IDs are cached — Gamma is only hit once per slug per 5m window.
        """
        from concurrent.futures import ThreadPoolExecutor, as_completed
        base_ts = self._current_5m_ts()
        now_ts  = time.time()
        # Purge stale meta cache entries (slugs whose window has passed)
        stale = [s for s, m in self._meta_cache.items() if m['end_ts'] < now_ts - 60]
        for s in stale:
            del self._meta_cache[s]

        # Build candidate (symbol, slug, end_ts) pairs that are in the time window
        candidates = []
        for symbol in self.SYMBOLS:
            for ts in (base_ts, base_ts + 300, base_ts + 600):
                end_ts = ts + 300
                secs_left = end_ts - now_ts
                if secs_left < 5 or secs_left > 310:
                    continue
                candidates.append((symbol, f"{symbol.lower()}-updown-5m-{ts}", end_ts))

        if not candidates:
            return []

        # Separate known (cached) from unknown (need Gamma probe)
        result = []
        to_probe = []
        for symbol, slug, end_ts in candidates:
            if slug in self._meta_cache:
                result.append(self._meta_cache[slug])
            else:
                to_probe.append((symbol, slug, end_ts))

        # Probe unknown slugs in parallel
        if to_probe:
            with ThreadPoolExecutor(max_workers=len(to_probe)) as ex:
                futures = {ex.submit(self._probe_slug, sym, slug, ets): slug
                           for sym, slug, ets in to_probe}
                for fut in as_completed(futures):
                    m = fut.result()
                    if m:
                        result.append(m)

        return result

    def _fetch_active_15m_markets(self) -> list:
        """
        Build list of active 15m markets by probing slug patterns in parallel.
        Same caching / probe logic as _fetch_active_5m_markets but for 15m bars.
        """
        from concurrent.futures import ThreadPoolExecutor, as_completed
        base_ts = self._current_15m_ts()
        now_ts  = time.time()

        # Build candidate (symbol, slug, end_ts) pairs within the 15m time window
        candidates = []
        for symbol in self.SYMBOLS:
            for ts in (base_ts, base_ts + 900, base_ts + 1800):
                end_ts = ts + 900
                secs_left = end_ts - now_ts
                if secs_left < 5 or secs_left > 910:
                    continue
                candidates.append((symbol, f"{symbol.lower()}-updown-15m-{ts}", end_ts))

        if not candidates:
            return []

        # Separate known (cached) from unknown (need Gamma probe)
        result = []
        to_probe = []
        for symbol, slug, end_ts in candidates:
            if slug in self._meta_cache:
                result.append(self._meta_cache[slug])
            else:
                to_probe.append((symbol, slug, end_ts))

        # Probe unknown slugs in parallel
        if to_probe:
            with ThreadPoolExecutor(max_workers=len(to_probe)) as ex:
                futures = {ex.submit(self._probe_slug, sym, slug, ets): slug
                           for sym, slug, ets in to_probe}
                for fut in as_completed(futures):
                    m = fut.result()
                    if m:
                        result.append(m)

        return result

    def _get_yes_price(self, market: dict) -> tuple:
        """
        Get the YES token ask price + both token IDs from CLOB order book.
        Returns (yes_price, yes_token_id, no_token_id).
        Falls back to Gamma outcomePrices if CLOB unavailable.
        Stores live prices back into market dict so _live_enter can reuse them.
        """
        tokens = market.get('tokens') or market.get('clobTokenIds') or []
        yes_token_id = no_token_id = None
        if tokens:
            if isinstance(tokens[0], dict):
                for tok in tokens:
                    outcome = tok.get('outcome', '').lower()
                    tid = tok.get('tokenId') or tok.get('token_id')
                    if outcome in ('yes', 'up'):
                        yes_token_id = tid
                    elif outcome in ('no', 'down'):
                        no_token_id = tid
                if not yes_token_id and tokens:
                    yes_token_id = tokens[0].get('tokenId') or tokens[0].get('token_id')
            else:
                yes_token_id = str(tokens[0]) if len(tokens) > 0 else None
                no_token_id  = str(tokens[1]) if len(tokens) > 1 else None

        # Store token IDs back into market for reuse by _live_enter
        market['_yes_token_id'] = yes_token_id
        market['_no_token_id']  = no_token_id

        if yes_token_id:
            # Ensure this token is subscribed to the WS feed for future scans
            self._ws_feed.subscribe(yes_token_id)

            # 1. Try WebSocket cache first — sub-50ms, no HTTP round-trip
            ws_ask = self._ws_feed.get_ask(yes_token_id)
            if ws_ask is not None:
                market['_live_yes_ask'] = ws_ask
                market['_price_source'] = 'ws'
                return ws_ask, yes_token_id, no_token_id

            # 2. Fall back to HTTP CLOB book
            try:
                resp = self._session.get(
                    'https://clob.polymarket.com/book',
                    params={'token_id': yes_token_id},
                    timeout=3
                )
                if resp.status_code == 200:
                    book = resp.json()
                    asks = book.get('asks', [])
                    if asks:
                        price = float(sorted(asks, key=lambda x: float(x.get('price', 999)))[0]['price'])
                        market['_live_yes_ask'] = price
                        market['_price_source'] = 'http'
                        return price, yes_token_id, no_token_id
            except Exception:
                pass

        # 3. Last resort: outcomePrices from Gamma
        prices = market.get('outcomePrices', [])
        if prices:
            try:
                price = float(prices[0])
                market['_live_yes_ask'] = price
                market['_price_source'] = 'gamma'
                return price, yes_token_id, no_token_id
            except Exception:
                pass
        return 0.0, yes_token_id, no_token_id

    def _get_end_ts(self, market: dict) -> float:
        """Get market end timestamp — prefer pre-computed end_ts field."""
        if market.get('end_ts'):
            return float(market['end_ts'])
        for key in ('endDate', 'end_date_iso', 'end_date'):
            val = market.get(key)
            if val:
                try:
                    if isinstance(val, (int, float)):
                        return float(val)
                    val_str = str(val).replace('Z', '+00:00')
                    return datetime.fromisoformat(val_str).timestamp()
                except Exception:
                    pass
        return 0.0

    # ── strategies ────────────────────────────────────────────────────────────

    def _strategy_momentum_burst(self, symbol: str, slug: str, price: float,
                                  secs_left: float) -> Optional[dict]:
        """MOMENTUM-BURST: strong directional move in last 60s — ride it.
        Entry capped at 0.87: data shows 0.9+ entries have avg win of $0.25 which
        can't absorb losses — 96 trades at 93% WR still lost $11.30 in that bucket."""
        if not (5 < secs_left < 60):
            return None
        move = price - 0.50
        if abs(move) < 0.10:
            return None  # not enough conviction
        direction = 'UP' if move > 0 else 'DOWN'
        entry_price = price if direction == 'UP' else (1.0 - price)
        # Configurable max entry — defaults to 0.65 to push avg_win up vs old 0.87.
        if entry_price < 0.03 or entry_price > self.mb_max_entry:
            return None
        return {
            'strategy': 'MOMENTUM-BURST',
            'direction': direction,
            'entry_price': round(entry_price, 4),
            'reason': f"Mom {'+' if move>0 else ''}{move*100:.1f}¢ off mid, {secs_left:.0f}s left",
        }

    def _strategy_fade_extend(self, symbol: str, slug: str, price: float,
                               secs_left: float) -> Optional[dict]:
        """
        EXTREME-RIDE (was FADE-EXTEND): price sustained in moderate extreme zone —
        ride WITH the direction. Paper data: 0/16 fading extremes → inverted.
        Entry capped at 0.75–0.90 range so profit margin is meaningful (≥10¢/share).
        Very extreme (>0.90) skipped — almost zero upside buying at 90¢+.

        2026-05-14: Re-enabled on SOL only after audit revealed the May 3 disable
        was based on shadow-PnL-bug-poisoned data. Per-symbol breakdown post-fix:
          SOL  174 trades  85.6% WR  +$87  ← clear positive edge above breakeven
          BNB  145 trades  69.0% WR  +$41  (BNB/HYPE/DOGE/XRP marginal — paper-only for now)
          BTC/ETH genuinely negative — stay disabled
        Letting SOL trade live tests whether the corrected backtest holds up forward.
        """
        # Per-symbol gate — SOL is the only proven cell as of 2026-05-14.
        # Other symbols can be added once we verify post-fix performance.
        if symbol != 'SOL':
            return None
        if not (20 < secs_left < 90):
            return None
        now_ts = time.time()
        cache_key = f"{slug}_fade"
        prev = self._market_cache.get(cache_key)
        self._market_cache[cache_key] = {'price': price, 'ts': now_ts}
        if not prev or (now_ts - prev.get('ts', now_ts)) < 6:
            return None  # need two observations ≥6s apart
        prev_price = prev.get('price', price)
        # Moderate extreme HIGH: 0.75–0.90 sustained → ride UP (buy YES)
        if (0.75 < price <= 0.90 and 0.75 < prev_price):
            direction   = 'UP'
            entry_price = round(price, 4)
            reason = f"Extreme-ride YES={price:.2f} sustained, {secs_left:.0f}s left"
        # Moderate extreme LOW: 0.10–0.25 sustained → ride DOWN (buy NO)
        elif (0.10 <= price < 0.25 and prev_price < 0.25):
            direction   = 'DOWN'
            entry_price = round(1.0 - price, 4)  # cost of NO token
            reason = f"Extreme-ride YES={price:.2f} sustained, {secs_left:.0f}s left"
        else:
            return None
        if entry_price < 0.10 or entry_price > 0.90:
            return None  # ensure meaningful margin both ways
        return {
            'strategy': 'EXTREME-RIDE',
            'direction': direction,
            'entry_price': entry_price,
            'reason': reason,
        }

    # ── paper entry & resolution ──────────────────────────────────────────────

    def _paper_enter(self, symbol: str, slug: str, signal: dict,
                     secs_left: float, end_ts: float):
        """Record a new paper trade entry."""
        import uuid as _uuid
        # Cross-bot conflict guard
        _xb_ok, _xb_reason = _xbot_check(slug, signal['direction'], 'HFT')
        if not _xb_ok:
            logger.warning(f'[HFT] SKIPPED {symbol} {signal["direction"]} — {_xb_reason}')
            return
        ep = signal['entry_price']
        stake = self._kelly_stake(symbol, ep, secs_left, signal['strategy'])
        _now_h = datetime.now(timezone.utc).hour
        _session = ('ASIA' if 0 <= _now_h < 8 else 'US_OPEN' if 8 <= _now_h < 12 else 'US_AFT' if 12 <= _now_h < 20 else 'OVERNIGHT')
        trade = {
            'id': _uuid.uuid4().hex[:12],
            'logged_at': datetime.now(timezone.utc).isoformat(),
            'fill_hour': _now_h,
            'fill_session': _session,
            'symbol': symbol,
            'market_slug': slug,
            'strategy': signal['strategy'],
            'direction': signal['direction'],
            'entry_price': ep,
            'stake': stake,
            'shares': round(stake / (ep * (1 + self.FEE_RATE)), 4),  # fee-adjusted like Claude Picks
            'secs_to_close': round(secs_left, 1),
            'market_end_ts': end_ts,
            'reason': signal.get('reason', ''),
            'resolved': False,
            'outcome': None,
            'exit_price': None,
            'paper_pnl': None,
        }
        with self._lock:
            self._trades.append(trade)
            self._save_log()
            self._entered_keys.add(f"{slug}_{signal['direction']}")
        _tf = '15m' if '-updown-15m-' in slug else '5m'
        logger.info(f"[HFT] PAPER {signal['strategy']} {symbol} ({_tf}) {signal['direction']} "
                    f"@ {ep:.3f} ({secs_left:.0f}s left) | {signal['reason']}")

    def _live_enter(self, symbol: str, slug: str, signal: dict,
                    secs_left: float, end_ts: float, market: dict):
        """
        Place a real Polymarket GTC order for an HFT signal.
        Falls back to paper on any order failure so the signal is still tracked.
        UP direction → buy YES token (tokens[0])
        DOWN direction → buy NO token (tokens[1])
        """
        from py_clob_client_v2.clob_types import OrderType
        import uuid as _uuid

        # Cross-bot conflict guard (paper_enter also checks, but check here too before order attempt)
        _xb_ok, _xb_reason = _xbot_check(slug, signal['direction'], 'HFT')
        if not _xb_ok:
            logger.warning(f'[HFT-LIVE] SKIPPED {symbol} {signal["direction"]} — {_xb_reason}')
            return

        # Correlation gate (Monday journal #43 idea #5): block correlated same-direction
        # bets within 60s — fall back to paper rather than skip entirely so we still log.
        # 2026-05-17 protection_override: user can disable this gate.
        if not getattr(self, 'protection_override', False):
            _corr_ok, _corr_reason = _correlation_check(symbol, signal['direction'])
            if not _corr_ok:
                logger.warning(f'[HFT-LIVE] CORR-GATE {symbol} {signal["direction"]} — {_corr_reason}, paper instead')
                self._paper_enter(symbol, slug, signal, secs_left, end_ts)
                return

        bot = self.bot
        if not bot or not bot.wallet_live or not bot.clob_client:
            logger.warning('[HFT-LIVE] No live wallet — falling back to paper')
            self._paper_enter(symbol, slug, signal, secs_left, end_ts)
            return

        direction = signal['direction']
        ep        = signal['entry_price']
        stake     = self._kelly_stake(symbol, ep, secs_left, signal['strategy'])

        # Resolve token_id — prefer pre-resolved IDs stored by _get_yes_price
        token_id = market.get('_yes_token_id') if direction == 'UP' else market.get('_no_token_id')
        if not token_id:
            tokens = market.get('tokens', [])
            if not tokens or len(tokens) < 2:
                logger.warning(f'[HFT-LIVE] No token_ids for {slug} — falling back to paper')
                self._paper_enter(symbol, slug, signal, secs_left, end_ts)
                return
            token_id = str(tokens[0]) if direction == 'UP' else str(tokens[1])

        # Reuse price already fetched by _get_yes_price — no second CLOB round-trip
        # For DOWN we need the NO token price = 1 - yes_price
        yes_ask = market.get('_live_yes_ask', ep)
        live_ask = yes_ask if direction == 'UP' else (1.0 - yes_ask)
        if live_ask <= 0:
            live_ask = ep

        if live_ask >= 0.99:
            logger.warning(f'[HFT-LIVE] Price {live_ask:.4f} >= 0.99, skipping {symbol}')
            return

        # Price floor — skip near-zero markets (almost certainly lost already)
        if live_ask < 0.05:
            logger.info(f'[HFT-LIVE] {symbol} ask={live_ask:.3f} below floor 0.05 — skipping')
            self._paper_enter(symbol, slug, signal, secs_left, end_ts)
            return

        # Size — enforce $5 minimum in dollar terms, not just share count
        # PRICE-AGGRESSION: cross the spread by 1 tick on entry so BUY orders fill as
        # takers instead of sitting unfilled. Pre-aggression fill rate was ~19%.
        # Cost: $0.01 per share (~$0.07 on a $5 stake at 0.75); benefit: instant fills.
        AGGRESSION_TICKS = 0.01
        target_price = min(0.99, live_ask + AGGRESSION_TICKS)
        rounded_price = bot.round_price(target_price)
        if rounded_price <= 0:
            return
        size = stake / rounded_price
        size = bot.round_maker_size(rounded_price, size)
        size = bot._validate_size(size, rounded_price, symbol)
        # Ensure the dollar value of the order is at least kelly_min_bet ($5)
        min_shares_for_min_bet = bot.kelly_min_bet / rounded_price
        if size * rounded_price < bot.kelly_min_bet:
            import math
            size = math.ceil(min_shares_for_min_bet)
        stake_actual = round(size * rounded_price, 4)

        # Place FAK (Fill-And-Kill) order. Combined with the +1 tick aggression
        # above, the BUY crosses the spread and takes all liquidity at <=ask+1tick
        # immediately, then KILLS any unfilled remainder so nothing rests on the
        # book. Resting GTC remainders were the residual adverse-selection trap:
        # leftover bids fill later on reversals (the losing half) while the winning
        # continuations run away unfilled. FAK = no resting remainder. Insta-cancel
        # of a no-liquidity order is safe — status CANCELLED -> fill_confirmed=False
        # -> no real_pnl written (resolution gates on filled_size>0, ~line 10616).
        ok, result, order_id = False, None, None
        try:
            ok, result, order_id = bot._safe_create_and_post(
                token_id=token_id,
                price=rounded_price,
                size=size,
                side='BUY',
                order_type=OrderType.FAK,
                symbol=symbol,
            )
        except Exception as e:
            logger.error(f'[HFT-LIVE] _safe_create_and_post exception for {symbol}: {e}')

        _now_h = datetime.now(timezone.utc).hour
        _session = ('ASIA' if 0 <= _now_h < 8 else 'US_OPEN' if 8 <= _now_h < 12 else 'US_AFT' if 12 <= _now_h < 20 else 'OVERNIGHT')
        trade = {
            'id':            _uuid.uuid4().hex[:12],
            'logged_at':     datetime.now(timezone.utc).isoformat(),
            'fill_hour':     _now_h,
            'fill_session':  _session,
            'entry_ts':      time.time(),
            'symbol':        symbol,
            'market_slug':   slug,
            'strategy':      signal['strategy'],
            'direction':     direction,
            'entry_price':   rounded_price,
            'token_id':      token_id,
            'stake':         stake_actual,
            'shares':        size,
            'secs_to_close': round(secs_left, 1),
            'market_end_ts': end_ts,
            'reason':        signal.get('reason', ''),
            'resolved':      False,
            'outcome':       None,
            'exit_price':    None,
            'paper_pnl':     None,
            # 2026-05-25 no-fund / order-fail handling: if the broker order didn't
            # land (ok=False — typically "insufficient USDC"), log as a paper trade
            # so resolution still computes paper_pnl from market outcome. Without
            # this, the PHANTOM-PNL GUARD short-circuits at line ~10425 and we
            # lose the shadow signal entirely (rows show "LOSS +$0.00"). Parallel
            # to the 2026-05-25 Claude Picks paper_stake_intent fix. attempted_live
            # preserves the original intent for forensics.
            'real_trade':    bool(ok),
            'attempted_live': True,
            'order_id':      order_id,
            'order_ok':      ok,
            # stop-loss data gathering
            'price_at_15s':  None,
            'price_at_30s':  None,
            'price_at_45s':  None,
        }
        with self._lock:
            self._trades.append(trade)
            self._save_log()
            self._entered_keys.add(f"{slug}_{direction}")

        _tf_live = '15m' if '-updown-15m-' in slug else '5m'
        if ok:
            logger.info(f'[HFT-LIVE] ORDER OK {signal["strategy"]} {symbol} ({_tf_live}) {direction} '
                        f'@ {rounded_price:.3f} x {size:.2f} | order={order_id} | ${stake_actual:.2f}')
            _correlation_record(symbol, direction)
        else:
            logger.warning(f'[HFT-LIVE] ORDER FAILED {signal["strategy"]} {symbol} ({_tf_live}) {direction} — logged for tracking')

        # TG notification for live HFT entries
        if self.bot:
            try:
                strat_short = 'MB' if signal['strategy'] == 'MOMENTUM-BURST' else 'ER'
                dir_arrow   = '▲' if direction == 'UP' else '▼'
                status_icon = '✅' if ok else '⚠️'
                msg = (
                    f'{status_icon} HFT {strat_short} {dir_arrow} <b>{symbol}</b>  ${stake_actual:.2f}\n'
                    f'@ {rounded_price:.3f} · {secs_left:.0f}s left\n'
                    f'{signal.get("reason", "")}'
                )
                self.bot._tg_notify(msg)
            except Exception:
                pass

    def _resolve_one(self, t: dict) -> Optional[str]:
        """
        Mirror of ClaudePicksScanner._resolve_paper_trade_outcome.
        Returns 'WIN', 'LOSS', or None (still pending).
        Uses /events?slug= for updown markets (same as Claude Picks).
        """
        now_ts = time.time()
        end_ts = t.get('market_end_ts', 0)
        if end_ts and now_ts < end_ts + 30:
            return None  # market hasn't closed yet

        slug      = t.get('market_slug', '')
        direction = t.get('direction', 'UP').upper()
        if not slug:
            return None

        try:
            # Use /events endpoint — same as Claude Picks for updown slugs
            r = self._session.get(f"{self.GAMMA}/events", params={'slug': slug}, timeout=4)
            if r.status_code != 200:
                return None
            events = r.json()
            event  = events[0] if isinstance(events, list) and events else None
            if not event:
                return None
            mkt = (event.get('markets') or [None])[0]
            if not mkt:
                return None

            closed = mkt.get('closed', False)
            out_prices_raw = mkt.get('outcomePrices', '[]')
            outcomes_raw   = mkt.get('outcomes', '["Up","Down"]')

            if isinstance(out_prices_raw, str):
                try:
                    out_prices = [float(x) for x in json.loads(out_prices_raw)]
                except Exception:
                    out_prices = []
            else:
                out_prices = [float(x) for x in (out_prices_raw or [])]

            if isinstance(outcomes_raw, str):
                try:
                    outcomes = json.loads(outcomes_raw)
                except Exception:
                    outcomes = []
            else:
                outcomes = list(outcomes_raw or [])

            # Match direction to outcome name (UP→Up, DOWN→Down)
            for i, o in enumerate(outcomes):
                if o.upper() == direction and i < len(out_prices):
                    p = out_prices[i]
                    if p >= 0.99:
                        return 'WIN'
                    elif p <= 0.01:
                        return 'LOSS'
                    elif closed:
                        return 'PUSH'
                    return None  # still live / resolving
        except Exception as e:
            logger.debug(f'[HFT] Resolve error {slug}: {e}')
        return None

    # ── MANIP signal awareness ────────────────────────────────────────────────

    def _get_active_manip_blocked_keys(self):
        """
        Return a set of '{slug}_{direction}' keys that HFT should NOT enter
        because an active (unresolved) MANIP signal exists in the opposite direction.

        If MANIP fired UP on slug X  → block HFT from entering X_DOWN
        If MANIP fired DOWN on slug X → block HFT from entering X_UP

        Result is cached for 30 s to avoid reading the file every 4 s.
        """
        now = time.time()
        cache = getattr(self, '_manip_block_cache', None)
        if cache and now - cache['ts'] < 30:
            return cache['keys']

        blocked = set()
        try:
            picks_path = os.path.join(os.path.dirname(__file__), 'claude_paper_trades.json')
            if os.path.exists(picks_path):
                with open(picks_path, 'r') as f:
                    picks = json.load(f)
                for p in picks:
                    if p.get('play_type') != 'MANIP':
                        continue
                    if p.get('resolved'):
                        continue          # already settled — no longer active
                    slug = p.get('slug', '')
                    direction = p.get('direction', '')
                    if not slug or not direction:
                        continue
                    opp = 'DOWN' if direction == 'UP' else 'UP'
                    blocked.add(f"{slug}_{opp}")
        except Exception as e:
            logger.debug(f'[HFT] MANIP block read error: {e}')

        self._manip_block_cache = {'ts': now, 'keys': blocked}
        return blocked

    def _repost_stale_orders(self):
        """
        Cancel unfilled real orders older than 20s and repost 1 tick cheaper.
        Max 2 reposts per trade to avoid chasing a dead market.
        Only reposts while the market is still open (>5s remaining).
        """
        from py_clob_client_v2.clob_types import OrderType
        bot = self.bot
        if not bot or not bot.clob_client or not bot.wallet_live:
            return

        now = time.time()
        with self._lock:
            stale = [
                t for t in self._trades
                if t.get('real_trade')
                and not t.get('resolved')
                and t.get('fill_confirmed') is None
                and t.get('order_id') and t['order_id'] != 'N/A'
                and t.get('entry_ts') and (now - t['entry_ts']) > 20
                and t.get('repost_count', 0) < 2
                and t.get('market_end_ts', 0) - now > 5  # market still open
                and t.get('strategy') != 'EXTREME-RIDE'   # skip — market too close to close
            ]

        for t in stale:
            old_oid = t['order_id']
            old_price = t['entry_price']
            # Chase the ask UP, not down — paying 1 cent more per repost gets the fill
            # instead of moving away from a moving market. Capped at 0.95 to avoid
            # overpaying near the top.
            new_price = round(min(old_price + 0.01, 0.95), 2)

            if new_price > 0.95:
                logger.debug(f'[HFT-REPOST] {t["symbol"]} new_price {new_price:.2f} > 0.95 ceiling, skipping')
                continue

            # Step 1: cancel old order
            try:
                from py_clob_client_v2.clob_types import OrderPayload as _OrderPayload
                bot.clob_client.cancel_order(_OrderPayload(orderID=old_oid))
                logger.info(f'[HFT-REPOST] Cancelled {t["symbol"]} order={old_oid[:16]}.. @ {old_price:.2f}')
            except Exception as e:
                logger.debug(f'[HFT-REPOST] Cancel error {old_oid[:16]}: {e}')
                continue

            # Step 2: repost at new price
            token_id = t.get('token_id')
            if not token_id:
                continue
            try:
                new_price_r = bot.round_price(new_price)
                size = t['shares']  # same share count
                ok, result, new_oid = bot._safe_create_and_post(
                    token_id=token_id,
                    price=new_price_r,
                    size=size,
                    side='BUY',
                    order_type=OrderType.GTC,
                    symbol=t['symbol'],
                )
                if ok:
                    t['order_id']     = new_oid
                    t['entry_price']  = new_price_r
                    t['entry_ts']     = now
                    t['fill_confirmed'] = None
                    t['repost_count'] = t.get('repost_count', 0) + 1
                    logger.info(
                        f'[HFT-REPOST] Reposted {t["symbol"]} {t["direction"]} '
                        f'{old_price:.2f}->{new_price_r:.2f} order={new_oid[:16]}.. '
                        f'(repost #{t["repost_count"]})'
                    )
                else:
                    logger.warning(f'[HFT-REPOST] Repost failed for {t["symbol"]}')
            except Exception as e:
                logger.warning(f'[HFT-REPOST] Repost error {t["symbol"]}: {e}')

        with self._lock:
            self._save_log()

    # Stop-loss threshold: exit at 15s if token price has moved -20% from entry
    SL_THRESHOLD   = -0.20   # -20% move triggers exit
    SL_CHECK_SECS  = 15      # check at 15s post-fill

    def _track_price_path(self):
        """
        Snapshot mid-price at 15/30/45s after entry for data gathering.
        At 15s: fire a stop-loss sell if the trade has moved -20%+ against us.
        Only acts on confirmed-filled real trades to avoid selling unfilled positions.
        """
        now = time.time()
        with self._lock:
            tracking = [
                t for t in self._trades
                if t.get('real_trade') and not t.get('resolved')
                and t.get('token_id') and t.get('entry_ts')
            ]

        changed = False
        for t in tracking:
            elapsed = now - t['entry_ts']
            snapshots = [
                (15, 'price_at_15s'),
                (30, 'price_at_30s'),
                (45, 'price_at_45s'),
            ]
            for target_s, field in snapshots:
                # Capture within a 4s window around the target (one scan tick)
                if t.get(field) is None and target_s <= elapsed < target_s + 10:
                    try:
                        resp = self._session.get(
                            f'https://clob.polymarket.com/midpoint?token_id={t["token_id"]}',
                            timeout=3
                        )
                        mid = resp.json().get('mid')
                        if mid is not None:
                            token_mid = round(float(mid), 4)
                            t[field] = token_mid
                            changed = True
                            ep = t.get('entry_price', 0)
                            # For DOWN trades the bot holds the NO token; mid is YES price
                            # so NO mid = 1 - YES mid
                            if t.get('direction') == 'DOWN':
                                token_mid = round(1.0 - float(mid), 4)
                                t[field] = token_mid
                            logger.debug(
                                f'[HFT-PATH] {t["symbol"]} {t["direction"]} '
                                f'{field}={t[field]} (entry={ep})'
                            )
                            # ── Stop-Loss check at every snapshot (15s / 30s / 45s) ──
                            if (t.get('fill_confirmed') is True
                                    and not t.get('sl_triggered')
                                    and t.get('strategy') != 'EXTREME-RIDE'
                                    and ep > 0):
                                move_pct = (token_mid - ep) / ep
                                # Skip SL if price is near zero — market likely
                                # already resolved; no meaningful exit possible
                                if token_mid < 0.05:
                                    logger.debug(
                                        f'[HFT-SL] Skipping SL {t["symbol"]} — price {token_mid:.4f} near zero (market resolved)'
                                    )
                                elif move_pct <= self.mb_sl_threshold:
                                    logger.info(
                                        f'[HFT-SL] STOP-LOSS {t["symbol"]} {t["direction"]} '
                                        f'entry={ep:.3f} {field}={token_mid:.3f} '
                                        f'move={move_pct*100:+.1f}% — exiting (threshold {self.mb_sl_threshold*100:.0f}%)'
                                    )
                                    t['sl_triggered'] = True
                                    changed = True
                                    self._execute_sl_exit(t)
                    except Exception as e:
                        logger.debug(f'[HFT-PATH] fetch error: {e}')

        if changed:
            with self._lock:
                self._save_log()

    def _execute_sl_exit(self, trade: dict):
        """
        Sell the held token at best available bid to exit a stop-loss.
        Uses the same allowance + sell flow as the prediction bot's stop-loss.
        """
        bot = self.bot
        if not bot or not bot.clob_client or not bot.wallet_live:
            logger.warning('[HFT-SL] No live wallet — cannot execute stop-loss')
            return

        token_id = trade.get('token_id')
        symbol   = trade.get('symbol', '?')
        # Use actual filled size if available — order may have partially filled.
        # Defensive cast: filled_size has historically been written as a string from
        # the CLOB API; the bare `<= 0` comparison would raise TypeError silently.
        try:
            shares = float(trade.get('filled_size') or trade.get('shares', 0) or 0)
        except (TypeError, ValueError):
            shares = 0.0
        if not token_id or shares <= 0:
            return

        try:
            # Approve conditional token transfer (required before selling outcome tokens)
            try:
                params = BalanceAllowanceParams(
                    asset_type=AssetType.CONDITIONAL,
                    token_id=token_id,
                    signature_type=2
                )
                bot.clob_client.update_balance_allowance(params)
                logger.info(f'[HFT-SL] Allowance updated for {symbol}')
            except Exception as e:
                logger.debug(f'[HFT-SL] Allowance update (may already be set): {e}')

            # Get best bid
            book = bot.clob_client.get_order_book(token_id)
            if not book or not hasattr(book, 'bids') or not book.bids:
                logger.warning(f'[HFT-SL] No bids for {symbol} — cannot exit')
                return
            best_bid = max(float(b.price) for b in book.bids)
            rounded_price = bot.round_price(best_bid)
            rounded_size  = bot._validate_size(bot.round_maker_size(rounded_price, shares), rounded_price, symbol)

            ok, result, order_id = bot._safe_create_and_post(
                token_id=token_id,
                price=rounded_price,
                size=rounded_size,
                side='SELL',
                order_type=OrderType.GTC,
                symbol=symbol,
            )
            if ok:
                trade['sl_order_id']    = order_id
                trade['sl_exit_price']  = rounded_price
                logger.info(
                    f'[HFT-SL] EXIT OK {symbol} {trade.get("direction")} '
                    f'SELL {rounded_size:.2f} @ {rounded_price:.3f} | order={order_id}'
                )
            else:
                logger.warning(f'[HFT-SL] EXIT FAILED {symbol}: {result}')
        except Exception as e:
            logger.error(f'[HFT-SL] Exit error for {symbol}: {e}')

    def _place_resting_sl(self, trade: dict):
        """Post a resting GTC SELL at entry_price * (1 + mb_sl_threshold) right
        after BUY fill confirmation. Caps the loss without waiting for the
        scan-loop SL detection. Skips EXTREME-RIDE (markets resolve in seconds,
        SL is disabled by design)."""
        if trade.get('strategy') == 'EXTREME-RIDE':
            return
        if trade.get('sl_triggered'):
            return  # already exiting via _check_sl_on_fill
        bot = self.bot
        if not bot or not getattr(bot, 'clob_client', None) or not getattr(bot, 'wallet_live', False):
            return
        token_id = trade.get('token_id')
        try:
            filled = float(trade.get('filled_size') or 0)
        except (TypeError, ValueError):
            filled = 0.0
        if not token_id or filled <= 0:
            return
        ep = float(trade.get('entry_price') or 0)
        if ep <= 0:
            return
        sl_target = ep * (1 + float(self.mb_sl_threshold))
        if sl_target <= 0.01:
            return
        try:
            try:
                params = BalanceAllowanceParams(
                    asset_type=AssetType.CONDITIONAL,
                    token_id=token_id, signature_type=2,
                )
                bot.clob_client.update_balance_allowance(params)
            except Exception as _ae:
                logger.debug(f'[HFT-RESTING-SL] allowance: {_ae}')
            rounded_price = bot.round_price(sl_target)
            rounded_size = bot._validate_size(
                bot.round_maker_size(rounded_price, filled),
                rounded_price, trade.get('symbol', '?'),
            )
            if rounded_size <= 0:
                return
            ok, result, order_id = bot._safe_create_and_post(
                token_id=token_id,
                price=rounded_price,
                size=rounded_size,
                side='SELL',
                order_type=OrderType.GTC,
                symbol=trade.get('symbol', '?'),
            )
            if ok:
                trade['sl_resting_order_id'] = order_id
                trade['sl_resting_price']    = rounded_price
                trade['sl_resting_size']     = rounded_size
                logger.info(
                    f'[HFT-RESTING-SL] {trade.get("symbol")} {trade.get("direction")} '
                    f'placed @ {rounded_price:.3f} x {rounded_size:.2f} '
                    f'(entry={ep:.3f} sl_pct={self.mb_sl_threshold:+.0%}) order={order_id}'
                )
            else:
                logger.warning(f'[HFT-RESTING-SL] place failed: {result}')
        except Exception as e:
            logger.error(f'[HFT-RESTING-SL] error: {e}')

    def _check_fill_status(self):
        """Poll CLOB for fill status on pending real trades with valid order_ids.

        2026-05-23 PR-7: age-cap polling. Polymarket CLOB acks fills within
        30-60s under normal conditions. Audit on 2026-05-23 showed all 64 HFT
        weekend orphans were >16h old — they would never resolve no matter
        how often we polled. Cap at 5 min: poll young orders normally, mark
        older orphans `fill_status='poll_timed_out'` and skip forever after.
        Saves ~5% bot CPU (was 4.6% get_order + 4.3% _check_fill_status pre-PR).
        """
        bot = self.bot
        if not bot or not bot.clob_client:
            return
        import time as _t
        FILL_POLL_MAX_AGE = 300  # 5 minutes
        now = _t.time()
        with self._lock:
            young_pending = []
            stale_orphans = []
            for t in self._trades:
                # Strict None check: explicit False (cancelled / poll_timed_out)
                # is terminal — don't re-poll or re-mark.
                if not (t.get('real_trade') and t.get('fill_confirmed') is None
                        and t.get('order_id') and t['order_id'] != 'N/A'):
                    continue
                # Prefer entry_ts (numeric epoch — set at order placement);
                # fall back to logged_at ISO parse if missing.
                ts = t.get('entry_ts')
                if not isinstance(ts, (int, float)):
                    try:
                        ts = datetime.fromisoformat(
                            (t.get('logged_at') or '').replace('Z','+00:00')
                        ).timestamp()
                    except Exception:
                        ts = 0
                age = now - ts if ts else 0
                if age <= FILL_POLL_MAX_AGE:
                    young_pending.append(t)
                else:
                    stale_orphans.append(t)
        # Mark stale orphans (one-time write, never polled again)
        if stale_orphans:
            with self._lock:
                for t in stale_orphans:
                    t['fill_confirmed'] = False
                    t['fill_status']    = 'poll_timed_out'
                logger.info(f'[HFT-FILL] Aged out {len(stale_orphans)} orphan(s) past {FILL_POLL_MAX_AGE}s — marked poll_timed_out')
                self._save_log()
        pending_real = young_pending
        if not pending_real:
            return
        changed = False
        newly_filled = []
        for t in pending_real:
            try:
                order = bot.clob_client.get_order(t['order_id'])
                status = getattr(order, 'status', None)
                if status is None and isinstance(order, dict):
                    status = order.get('status')
                filled = getattr(order, 'size_matched', None)
                if filled is None and isinstance(order, dict):
                    filled = order.get('size_matched', 0)
                if status in ('FILLED', 'MATCHED'):
                    t['fill_confirmed'] = True
                    # CLOB returns size_matched as a string — coerce so consumers can do numeric compares.
                    # Without this, _execute_sl_exit's `shares <= 0` raises TypeError, caught silently by
                    # the outer logger.debug — every SL exit on a filled live trade was a no-op (2026-05-16).
                    try:
                        t['filled_size'] = float(filled) if filled is not None else None
                    except (TypeError, ValueError):
                        t['filled_size'] = None
                    changed = True
                    logger.info(f"[HFT-FILL] Confirmed fill order_id={t['order_id']} size={filled}")
                    # Immediate SL check on fill confirmation using stored price snapshot
                    # Handles case where fill is confirmed after the 15s scan window passed
                    self._check_sl_on_fill(t)
                    newly_filled.append(t)
                elif status in ('CANCELLED', 'EXPIRED'):
                    t['fill_confirmed'] = False
                    t['fill_status'] = status
                    changed = True
                    logger.info(f"[HFT-FILL] Order {status} order_id={t['order_id']}")
            except Exception as e:
                logger.debug(f'[HFT-FILL] Check error order_id={t.get("order_id")}: {e}')
        if changed:
            with self._lock:
                self._save_log()
        # Post-fill BUY VWAP lookup — capture actual_fill_price + actual_filled_size
        # from CLOB trade history (mirror of ML scanner pattern). Polymarket settles
        # at the maker's price, which can be a few cents better than our BUY limit.
        if newly_filled and bot and getattr(bot, 'clob_client', None):
            try:
                from py_clob_client_v2.clob_types import TradeParams
                proxy = (getattr(bot, 'proxy_address', None)
                         or getattr(bot, 'wallet_address', None))
                if proxy:
                    recent = bot.clob_client.get_trades(
                        TradeParams(maker_address=proxy), only_first_page=True
                    )
                    by_order = {}
                    for tr in recent or []:
                        if not isinstance(tr, dict):
                            continue
                        toi = (tr.get('taker_order_id') or tr.get('takerOrderID')
                               or tr.get('takerOrderId'))
                        if toi:
                            by_order.setdefault(toi, []).append(('taker', None, tr))
                        for mo in (tr.get('maker_orders') or tr.get('makerOrders') or []):
                            if not isinstance(mo, dict):
                                continue
                            k = (mo.get('order_id') or mo.get('orderID')
                                 or mo.get('orderId') or mo.get('maker_order_id'))
                            if k:
                                by_order.setdefault(k, []).append(('maker', mo, tr))
                    for t in newly_filled:
                        oid = t.get('order_id')
                        if not oid or oid == 'N/A':
                            continue
                        matches = by_order.get(oid, [])
                        if not matches:
                            continue
                        tsz, tcost = 0.0, 0.0
                        for role, mo, tr in matches:
                            try:
                                if role == 'maker' and mo:
                                    sz = float(mo.get('matched_amount')
                                               or mo.get('matchedAmount')
                                               or mo.get('size') or 0)
                                    pr = float(mo.get('price') or tr.get('price') or 0)
                                else:
                                    sz = float(tr.get('size') or 0)
                                    pr = float(tr.get('price') or 0)
                            except (TypeError, ValueError):
                                continue
                            if sz > 0 and pr > 0:
                                tsz += sz
                                tcost += sz * pr
                        if tsz > 0:
                            vwap = tcost / tsz
                            with self._lock:
                                t['actual_fill_price']  = round(vwap, 6)
                                t['actual_filled_size'] = round(tsz, 4)
                            slip_bps = ((vwap - float(t.get('entry_price') or 0)) * 10000
                                        if t.get('entry_price') else 0)
                            logger.info(
                                f'[HFT-BUY-VWAP] {t.get("symbol")} {t.get("direction")} '
                                f'limit={t.get("entry_price")} vwap={vwap:.4f} '
                                f'size={tsz:.2f} slip={slip_bps:+.0f}bps'
                            )
            except Exception as _be:
                logger.debug(f'[HFT-BUY-VWAP] err: {_be}')

        # Place resting SL on newly-confirmed fills (outside the lock — does its own I/O).
        # _check_sl_on_fill above may have already fired SL on a stale-snapshot breach;
        # _place_resting_sl skips those (sl_triggered=True).
        for t in newly_filled:
            try:
                self._place_resting_sl(t)
            except Exception as _re:
                logger.warning(f'[HFT-RESTING-SL] hook error: {_re}')
        if newly_filled:
            with self._lock:
                self._save_log()

    def _check_sl_on_fill(self, trade: dict):
        """
        Called immediately when a fill is confirmed. If a price snapshot already
        exists and breaches the SL threshold, fire the exit right away.
        This handles the common case where fill confirmation arrives after
        the 15s scan window has already passed.
        Falls back to a live price fetch if no snapshots are available (e.g. after restart).
        """
        if trade.get('sl_triggered'):
            return
        # EXTREME-RIDE markets resolve within seconds — skip SL entirely
        if trade.get('strategy') == 'EXTREME-RIDE':
            return
        ep = trade.get('entry_price', 0)
        if ep <= 0:
            return

        # Use whichever snapshot is available (prefer 15s, fall back to 30s/45s)
        token_price = None
        snap_field = None
        for field in ('price_at_15s', 'price_at_30s', 'price_at_45s'):
            snap = trade.get(field)
            if snap is not None:
                token_price = snap
                snap_field = field
                break

        # No snapshots (e.g. bot restarted between entry and snapshot windows) — fetch live
        if token_price is None:
            token_id = trade.get('token_id')
            if token_id:
                try:
                    resp = self._session.get(
                        f'https://clob.polymarket.com/midpoint?token_id={token_id}',
                        timeout=3
                    )
                    mid = resp.json().get('mid')
                    if mid is not None:
                        token_price = round(float(mid), 4)
                        if trade.get('direction') == 'DOWN':
                            token_price = round(1.0 - float(mid), 4)
                        snap_field = 'live_at_fill'
                except Exception:
                    pass

        if token_price is None:
            return

        # Skip SL if price is near zero — market likely already resolved;
        # no meaningful exit possible at that price
        if token_price < 0.05:
            logger.debug(
                f'[HFT-SL] Skipping post-fill SL {trade.get("symbol")} — '
                f'price {token_price:.4f} near zero (market resolved)'
            )
            return

        move_pct = (token_price - ep) / ep
        if move_pct <= self.SL_THRESHOLD:
            logger.info(
                f'[HFT-SL] POST-FILL STOP-LOSS {trade.get("symbol")} {trade.get("direction")} '
                f'entry={ep:.3f} {snap_field}={token_price:.3f} '
                f'move={move_pct*100:+.1f}% — exiting'
            )
            trade['sl_triggered'] = True
            self._execute_sl_exit(trade)

    def check_outcomes(self):
        """Resolve pending trades in parallel — no lock held during HTTP calls."""
        from concurrent.futures import ThreadPoolExecutor, as_completed

        # Snapshot pending trades outside the lock
        with self._lock:
            pending = [t for t in self._trades if not t.get('resolved')]

        if not pending:
            return

        # Unfilled real orders (order_ok=False or fill_confirmed=False) flow through
        # normal resolution so paper_pnl reflects the actual market outcome.
        # The wallet side stays untouched — the real_pnl/natural_close_pnl block
        # below already requires filled_size > 0, and auto-pause + TG are gated on
        # fill_confirmed=True.

        # Resolve all pending trades concurrently
        def _resolve(t):
            return t, self._resolve_one(t)

        with ThreadPoolExecutor(max_workers=min(len(pending), 8)) as ex:
            results = [f.result() for f in as_completed(ex.submit(_resolve, t) for t in pending)]

        # Apply resolved outcomes under the lock (fast — no I/O)
        changed = False
        with self._lock:
            for t, outcome in results:
                if outcome is None:
                    continue
                # Unfilled real_trade: let it resolve like a paper trade so paper_pnl
                # reflects the actual directional outcome. real_pnl/natural_close_pnl
                # writes are already gated by `filled_size > 0` below, so the wallet
                # side stays clean. Auto-pause + TG also gated on fill_confirmed=True.
                stake  = t['stake']
                shares = t['shares']
                if outcome == 'WIN':
                    pnl = round(shares * 1.0 - stake, 4)
                elif outcome == 'LOSS':
                    pnl = round(-stake, 4)
                else:
                    pnl = 0.0
                t.update({
                    'resolved':    True,
                    'outcome':     outcome,
                    'won':         outcome == 'WIN',
                    'pnl':         pnl,
                    'paper_pnl':   pnl,
                    'resolved_at': datetime.now(timezone.utc).isoformat(),
                })
                # For real trades, write real_pnl + natural_close_pnl + actual_realized_pnl
                # + sl_savings. natural is the held-to-close scenario; actual reflects any
                # SL-driven early exit (whether via _execute_sl_exit or resting SL fill).
                # Resting-SL fill amount is queried in the post-lock pass below.
                if t.get('real_trade'):
                    fs = 0.0
                    try:
                        fs = float(t.get('filled_size') or 0)
                    except (TypeError, ValueError):
                        fs = 0.0
                    # Cost basis: prefer actual_fill_price (BUY VWAP) over entry_price (limit)
                    ep_src = (t.get('actual_fill_price')
                              if t.get('actual_fill_price') is not None
                              else t.get('entry_price'))
                    ep = float(ep_src or 0)
                    if fs > 0 and ep > 0:
                        cost = fs * ep
                        # Natural close: what would have happened without any SL exit
                        if outcome == 'WIN':
                            ncp = round(fs - cost, 4)
                        elif outcome == 'LOSS':
                            ncp = round(-cost, 4)
                        else:
                            ncp = 0.0
                        t['natural_close_pnl'] = ncp
                        # SL-exited (existing _execute_sl_exit path) overrides actual
                        if t.get('sl_triggered') and t.get('sl_exit_price') is not None:
                            try:
                                xp = float(t['sl_exit_price'])
                                actual = round(fs * xp - cost, 4)
                                t['real_pnl'] = actual
                                t['actual_realized_pnl'] = actual
                                t['sl_savings'] = round(actual - ncp, 4)
                            except (TypeError, ValueError):
                                t['real_pnl'] = ncp
                                t['actual_realized_pnl'] = ncp
                                t['sl_savings'] = 0.0
                        else:
                            t['real_pnl'] = ncp
                            t['actual_realized_pnl'] = ncp
                            t['sl_savings'] = 0.0
                self._entered_keys.discard(f"{t.get('market_slug','')}_{t.get('direction','')}")
                _xbot_clear(t.get('market_slug', ''))  # free slug for other bots
                # Unsubscribe resolved token from WS feed
                if t.get('token_id'):
                    self._ws_feed.unsubscribe(t['token_id'])
                changed = True
                _slug_tf = t.get('market_slug', '')
                _tf_label = '15m' if '-updown-15m-' in _slug_tf else '5m'
                logger.info(f"[HFT] {outcome} | {t['strategy']} {t['symbol']} ({_tf_label}) {t['direction']} "
                            f"PnL={pnl:+.2f}")
                # TG notification — only for trades that actually filled. Unfilled
                # real orders still resolve to paper-equivalent outcomes but didn't
                # move real money, so no ping.
                if t.get('real_trade') and t.get('fill_confirmed') is True and self.bot:
                    try:
                        icon = '✅' if outcome == 'WIN' else ('❌' if outcome == 'LOSS' else '➖')
                        strat_short = 'MB' if t.get('strategy') == 'MOMENTUM-BURST' else 'ER'
                        dir_arrow = '▲' if t.get('direction') == 'UP' else '▼'
                        self.bot._tg_notify(
                            f'{icon} HFT {strat_short} {dir_arrow} <b>{t["symbol"]}</b>  {outcome}\n'
                            f'PnL: {pnl:+.2f} @ {t.get("entry_price", 0):.3f}'
                        )
                    except Exception:
                        pass
                # Per-strategy auto-pause gate — only filled real trades count; unfilled
                # paper-equivalent losses must not trip the live circuit breaker.
                if t.get('real_trade') is True and t.get('fill_confirmed') is True:
                    try:
                        auto_pause_gate().record_resolved(t.get('strategy', ''), pnl)
                    except Exception as _ap_err:
                        logger.debug(f'[AUTO-PAUSE] HFT record err: {_ap_err}')
                # RL update — teach the model about this outcome
                try:
                    self.rl.update(
                        t.get('symbol', ''), t.get('entry_price', 0.5),
                        t.get('secs_to_close', 30), t.get('strategy', 'MOMENTUM-BURST'),
                        t.get('stake', 0), pnl,
                    )
                except Exception as _rl_err:
                    logger.debug(f'[HFT-RL] Update error: {_rl_err}')
            if changed:
                self._save_log()

        # SL-aware PnL pass (outside lock) — for newly-resolved real trades with
        # a resting SL, query the order to see how much filled, then update
        # real_pnl / actual_realized_pnl / sl_savings. Mirror of ML scanner.
        bot = self.bot
        if bot and getattr(bot, 'clob_client', None):
            sl_resolved = [(t, oc) for t, oc in results
                           if oc and t.get('real_trade')
                           and not t.get('sl_triggered')  # _execute_sl_exit path already accounted
                           and t.get('sl_resting_order_id')
                           and t.get('sl_resting_filled_size') is None]
            # Pre-fetch wallet trades once for VWAP lookup (the resting SL may have
            # matched against a higher-priced bid; the actual fill price differs
            # from the limit, and on Polymarket the maker's price wins).
            by_order = {}
            if sl_resolved:
                try:
                    from py_clob_client_v2.clob_types import TradeParams
                    proxy = (getattr(bot, 'proxy_address', None)
                             or getattr(bot, 'wallet_address', None))
                    if proxy:
                        recent = bot.clob_client.get_trades(
                            TradeParams(maker_address=proxy), only_first_page=True
                        )
                        for tr in recent or []:
                            if not isinstance(tr, dict):
                                continue
                            for mo in (tr.get('maker_orders') or tr.get('makerOrders') or []):
                                if not isinstance(mo, dict):
                                    continue
                                k = (mo.get('order_id') or mo.get('orderID')
                                     or mo.get('orderId') or mo.get('maker_order_id'))
                                if k:
                                    by_order.setdefault(k, []).append((mo, tr))
                except Exception as _ve:
                    logger.debug(f'[HFT-SL-VWAP] prefetch err: {_ve}')

            def _vwap_for(oid):
                matches = by_order.get(oid, [])
                tsz, tcost = 0.0, 0.0
                for mo, tr in matches:
                    try:
                        sz = float(mo.get('matched_amount') or mo.get('matchedAmount')
                                   or mo.get('size') or 0)
                        pr = float(mo.get('price') or tr.get('price') or 0)
                    except (TypeError, ValueError):
                        continue
                    if sz > 0 and pr > 0:
                        tsz += sz
                        tcost += sz * pr
                if tsz > 0:
                    return tsz, tcost / tsz
                return 0.0, 0.0

            sl_updated = 0
            for t, oc in sl_resolved:
                sl_id = t['sl_resting_order_id']
                sl_filled = 0.0
                try:
                    sl_order = bot.clob_client.get_order(sl_id)
                    sl_matched = getattr(sl_order, 'size_matched', None)
                    if sl_matched is None and isinstance(sl_order, dict):
                        sl_matched = sl_order.get('size_matched', 0)
                    sl_filled = float(sl_matched or 0)
                except Exception as _se:
                    logger.debug(f'[HFT-SL-CHECK] order={sl_id[:14] if sl_id else "?"}.. err={_se}')
                with self._lock:
                    t['sl_resting_filled_size'] = round(sl_filled, 4)
                if sl_filled <= 0:
                    continue
                vwap_sz, vwap_price = _vwap_for(sl_id)
                sl_limit = float(t.get('sl_resting_price') or 0)
                sl_actual = vwap_price if vwap_price > 0 else sl_limit
                price_src = 'vwap' if vwap_price > 0 else 'limit'
                fs = float(t.get('filled_size') or 0)
                # Cost basis: prefer actual_fill_price (BUY VWAP) over entry_price (limit)
                ep_src = (t.get('actual_fill_price')
                          if t.get('actual_fill_price') is not None
                          else t.get('entry_price'))
                ep = float(ep_src or 0)
                if fs <= 0 or ep <= 0 or sl_actual <= 0:
                    continue
                cost = fs * ep
                close_payoff = 1.0 if oc == 'WIN' else 0.0
                remainder = max(0.0, fs - sl_filled)
                actual = round(sl_filled * sl_actual + remainder * close_payoff - cost, 4)
                ncp = t.get('natural_close_pnl') or 0.0
                savings = round(actual - ncp, 4)
                with self._lock:
                    t['sl_resting_actual_price'] = round(sl_actual, 6)
                    t['actual_realized_pnl']     = actual
                    t['real_pnl']                = actual
                    t['sl_savings']              = savings
                sl_updated += 1
                logger.info(
                    f'[HFT-SL-FILL] {t.get("symbol")} {t.get("direction")} '
                    f'sl_filled={sl_filled:.2f}/{fs:.2f} @ {sl_actual:.3f} ({price_src}, '
                    f'limit={sl_limit:.3f}) actual=${actual:+.2f} natural=${ncp:+.2f} '
                    f'savings=${savings:+.2f}'
                )
            if sl_updated:
                with self._lock:
                    self._save_log()

    # ── single scan pass ──────────────────────────────────────────────────────

    def scan_once(self):
        """One scan iteration — parallel market fetch + parallel price fetch."""
        from concurrent.futures import ThreadPoolExecutor, as_completed
        try:
            now_ts = time.time()
            self._scan_count += 1
            self._last_scan_ts = now_ts

            # Reload settings every 60 scans (~5 min) so file changes take effect without restart
            self._settings_reload_counter += 1
            if self._settings_reload_counter >= 60:
                self._settings_reload_counter = 0
                self._load_settings()

            # Auto profitability filter — re-evaluate every 60 scans
            self._auto_filter_counter += 1
            if self._auto_filter_counter >= 60:
                self._auto_filter_counter = 0
                self._update_auto_paper_filter()

            # Drawdown floor — non-blocking read of cached CLOB collateral balance.
            # Background poller (start_drawdown_poller) refreshes _cached_clob_balance every 30s.
            # Per-scan HTTP call removed — saved ~110ms per scan on Toronto VPN exit.
            if self.live_mode and self.drawdown_floor > 0:
                cb = self._cached_clob_balance
                if cb is not None and cb > 10 and cb < self.drawdown_floor:
                    self.live_mode = False
                    self._save_settings()
                    msg = (f'⚠️ HFT auto-switched to PAPER — CLOB balance ${cb:.2f} '
                           f'below floor ${self.drawdown_floor:.2f}')
                    logger.warning(f'[HFT-DRAWDOWN] {msg}')
                    try:
                        if self.bot:
                            self.bot._tg_notify(msg)
                    except Exception:
                        pass

            # Step 1: read market metadata from background cache (refreshed every 3s
            # by start_market_refresh thread). Avoids per-scan ~300-500ms Gamma probes.
            with self._market_bg_lock:
                markets = list(self._market_bg_cache)
            if not markets:
                # Cache not populated yet (first ~3s after startup) — fall back to direct fetch
                markets = self._fetch_active_5m_markets() + self._fetch_active_15m_markets()

            # Filter to the action window before price fetching
            active = []
            for m in markets:
                end_ts = self._get_end_ts(m)
                if not end_ts:
                    continue
                secs_left = end_ts - now_ts
                if secs_left < 5 or secs_left > 130:
                    continue
                m['_secs_left'] = secs_left
                m['_end_ts']    = end_ts
                active.append(m)

            if not active:
                return

            logger.info(f'[HFT] Scan #{self._scan_count}: {len(active)} markets in action window')

            # Step 2: fetch CLOB prices for all active markets in parallel
            def _fetch_price(m):
                price, yes_tid, no_tid = self._get_yes_price(m)
                # Pre-warm CLOB tick/neg_risk/fee cache OFF the hot path so _live_enter's
                # create_order does zero network (saves ~340-420ms/order on first-touch
                # tokens; HFT tokens rotate every cycle so ~every entry is first-touch).
                # One get_clob_market_info call warms BOTH tokens. Deduped per condition,
                # gated on live_mode. Idempotent — a benign race just re-warms once.
                if self.live_mode and self.bot and getattr(self.bot, 'clob_client', None):
                    cond = m.get('conditionId')
                    if cond and cond not in self._prewarmed_conditions:
                        try:
                            self.bot.clob_client.get_clob_market_info(cond)
                            if len(self._prewarmed_conditions) > 4000:
                                self._prewarmed_conditions.clear()
                            self._prewarmed_conditions.add(cond)
                        except Exception as _pw:
                            logger.debug(f'[HFT-PREWARM] {m.get("slug","")}: {_pw}')
                return m, price

            with ThreadPoolExecutor(max_workers=len(active)) as ex:
                price_futures = [ex.submit(_fetch_price, m) for m in active]
                priced = [f.result() for f in as_completed(price_futures)]

            # Step 3: evaluate strategies and collect signals
            hits = 0
            pending_live = []   # (symbol, slug, sig, secs_left, end_ts, m)
            manip_blocked = self._get_active_manip_blocked_keys()
            for m, price in priced:
                if price <= 0:
                    continue
                symbol    = m.get('_symbol', '')
                slug      = m.get('slug', '')
                tf        = '15m' if '-updown-15m-' in slug else '5m'
                secs_left = m['_secs_left']
                end_ts    = m['_end_ts']

                # Keep fade/extreme cache current for ALL markets regardless of signal
                fkey = f"{slug}_fade"
                if fkey not in self._market_cache:
                    self._market_cache[fkey] = {'price': price, 'ts': now_ts - 20}
                # EXTREME-RIDE (_strategy_fade_extend) disabled 2026-05-03 per backtest:
                # n=1670, 85.5% WR vs 85.8% breakeven = ZERO edge, -$72 PnL.
                # 2026-05-14 RE-ENABLED on SOL only — that backtest used poisoned shadow-PnL
                # data (journal #20). Corrected per-symbol: SOL 174t/85.6% WR/+$87.
                # _strategy_fade_extend internally restricts to symbol=='SOL'.
                for strat_fn in (self._strategy_momentum_burst, self._strategy_fade_extend):
                    sig = strat_fn(symbol, slug, price, secs_left)
                    if not sig:
                        continue
                    # fix 2026-05-30: filtered cell_overrides (api_hft_cell_override) match via
                    # _cell_filters_match, which reads sig['secs_to_close'] and sig['slug']. The
                    # strategy fns don't set them, so every override with a secs= or timeframe=15m
                    # filter silently defaulted (secs->999='60s+', slug=''->'5m') and NEVER matched —
                    # complex/specific overrides looked like they "didn't apply." Inject loop-local
                    # context so price/hour/session AND secs/timeframe filters all resolve correctly.
                    sig.setdefault('secs_to_close', secs_left)
                    sig.setdefault('slug', slug)
                    key = f"{slug}_{sig['direction']}"
                    opp = 'DOWN' if sig['direction'] == 'UP' else 'UP'
                    if key in self._entered_keys or f"{slug}_{opp}" in self._entered_keys:
                        continue
                    # Block HFT if an active MANIP signal covers the opposite side
                    if key in manip_blocked:
                        logger.info(f'[HFT] MANIP-BLOCK {symbol} ({tf}) {sig["direction"]} '
                                    f'— active MANIP signal on opposite side, skipping')
                        continue
                    # Per-symbol gate (2026-05-19) — applied BEFORE RL. Each override field is
                    # optional; missing/null means no restriction for that dimension. Hours
                    # override sessions when both are set.
                    _sym_ovr = self.symbol_overrides.get(symbol)
                    if _sym_ovr:
                        _adir = _sym_ovr.get('directions')
                        if _adir and sig.get('direction') not in _adir:
                            logger.info(f'[HFT-PERSYM] SKIP {symbol} dir={sig.get("direction")} '
                                        f'not in {_adir}')
                            continue
                        _astrat = _sym_ovr.get('strategies')
                        if _astrat and sig.get('strategy') not in _astrat:
                            logger.info(f'[HFT-PERSYM] SKIP {symbol} strat={sig.get("strategy")} '
                                        f'not in {_astrat}')
                            continue
                        _ahours = _sym_ovr.get('hours')
                        _asess  = _sym_ovr.get('sessions')
                        if _ahours or _asess:
                            _now_h = datetime.now().hour
                            if _ahours:
                                if _now_h not in _ahours:
                                    logger.info(f'[HFT-PERSYM] SKIP {symbol} hour={_now_h} not in allowed hours')
                                    continue
                            elif _asess:
                                _cur_sess = ('ASIA' if 0 <= _now_h < 8 else 'US_OPEN' if 8 <= _now_h < 12
                                             else 'US_AFT' if 12 <= _now_h < 20 else 'OVERNIGHT')
                                if _cur_sess not in _asess:
                                    logger.info(f'[HFT-PERSYM] SKIP {symbol} session={_cur_sess} not in {_asess}')
                                    continue
                    # 2026-05-22: per-cell RL bypass. If the user marked this cell as
                    # bypass_rl=true in cell_overrides, skip the RL gate entirely. The Q-table
                    # still updates from outcomes (learning continues), this just overrides the
                    # current gate decision. Used when the RL has over-suppressed a cell that
                    # the data actually shows is profitable. The filter system still applies —
                    # bypass only triggers when filters match (e.g. only bypass during certain
                    # hours/sessions). Subsequent paper/real logic is unchanged.
                    _bypass_cell_key = f'{symbol}|{sig.get("direction","?")}|{sig.get("strategy","?")}'
                    _bypass_entry = self.cell_overrides.get(_bypass_cell_key)
                    _rl_bypassed = False
                    if isinstance(_bypass_entry, dict) and _bypass_entry.get('bypass_rl'):
                        if self._cell_filters_match(_bypass_entry, sig, symbol):
                            _rl_bypassed = True
                    # RL gate — skip states the model has learned are unprofitable
                    if _rl_bypassed:
                        rl_allow, rl_reason = True, 'cell_overrides.bypass_rl'
                    else:
                        rl_allow, rl_reason = self.rl.should_enter(
                            symbol, sig['entry_price'], secs_left, sig['strategy'])
                    # Shadow gate — what would the OTHER mode's gate decide on this
                    # same state? Append to hft_gate_compare.jsonl on divergence so we
                    # can later judge whether the weekend/weekday split is doing useful
                    # work. Read-only; never touches the other mode's state file.
                    try:
                        _sh_allow, _sh_q, _sh_n, _sh_key = self.rl.shadow_decide(
                            symbol, sig['entry_price'], secs_left, sig['strategy'])
                        if _sh_allow != rl_allow:
                            _a_q, _a_n, _ = self.rl.score(
                                symbol, sig['entry_price'], secs_left, sig['strategy'])
                            _log_gate_compare({
                                'ts':            datetime.now(timezone.utc).isoformat(),
                                'scanner':       'HFT',
                                'state_key':     _sh_key,
                                'symbol':        symbol,
                                'strategy':      sig['strategy'],
                                'direction':     sig['direction'],
                                'entry_price':   sig['entry_price'],
                                'secs_to_close': round(secs_left, 1),
                                'slug':          slug,
                                'mode_active':   'weekend' if _is_weekend_mode_now() else 'weekday',
                                'active_allow':  bool(rl_allow),
                                'active_q':      round(_a_q, 4),
                                'active_n':      _a_n,
                                'shadow_allow':  bool(_sh_allow),
                                'shadow_q':      round(_sh_q, 4),
                                'shadow_n':      _sh_n,
                            })
                    except Exception as _ce:
                        logger.debug(f'[GATE-CMP] {_ce}')
                    if not rl_allow:
                        logger.info(f'[HFT-RL] SKIP {symbol} ({tf}) {sig["strategy"]} '
                                    f'@ {sig["entry_price"]:.2f} {secs_left:.0f}s: {rl_reason}')
                        _rl_q, _rl_n, _rl_key = self.rl.score(
                            symbol, sig['entry_price'], secs_left, sig['strategy'])
                        try:
                            self.rl_shadow.log_blocked(
                                rl_system='hft', state_key=_rl_key,
                                rl_q=_rl_q, rl_n=_rl_n, rl_reason=rl_reason,
                                symbol=symbol, direction=sig['direction'],
                                entry_price=sig['entry_price'],
                                stake=self._kelly_stake(symbol, sig['entry_price'], secs_left, sig['strategy']),
                                secs_to_close=secs_left, market_end_ts=end_ts,
                                market_slug=slug, strategy=sig['strategy'])
                        except Exception as _se:
                            logger.debug(f'[RL-SHADOW] log error: {_se}')
                        continue
                    # paper_strategies / paper_symbols override live_mode for specific combos.
                    # User intent takes precedence over auto-filter — auto-filter is advisory.
                    # 2026-05-17 protection_override: skip the AutoPauseGate check too.
                    _pause_check = (False if getattr(self, 'protection_override', False)
                                    else auto_pause_gate().is_paused(sig.get('strategy', '')))
                    # 2026-05-22: per-cell override takes PRECEDENCE over dimension-level paper_*
                    # lists. Mirrors Claude Picks _cell_overrides. Lets the operator whitelist a
                    # profitable cell inside an otherwise-papered symbol, or quarantine a single
                    # bleeding cell without papering the whole strategy. AutoPauseGate still wins
                    # (pause is a safety mechanism that shouldn't be bypassed by a cell whitelist).
                    # 2026-05-22 extension: override value can be a dict with optional filters
                    # {hour, session, timeframe, price, secs}. Filters must ALL match the live
                    # signal context before the override mode is applied (else fall through).
                    _cell_key = f'{symbol}|{sig.get("direction","?")}|{sig.get("strategy","?")}'
                    _cell_entry = self.cell_overrides.get(_cell_key)
                    _cell_mode = None
                    if isinstance(_cell_entry, str):
                        _cell_mode = _cell_entry  # backward compat — no filters
                    elif isinstance(_cell_entry, dict):
                        if self._cell_filters_match(_cell_entry, sig, symbol):
                            _cell_mode = _cell_entry.get('mode')
                    if _cell_mode == 'real' and not _pause_check:
                        _force_paper = False
                    elif _cell_mode == 'paper':
                        _force_paper = True
                    else:
                        _force_paper = (sig.get('strategy') in self.paper_strategies
                                        or symbol in self.paper_symbols
                                        or sig.get('direction') in self.paper_directions
                                        or _pause_check)
                    # Auto profitability filter — informational only (label shown in UI).
                    # User explicitly set live/paper via paper_symbols — respect that choice.
                    _auto_paper  = f'{symbol}_{sig["strategy"]}' in self._auto_paper_keys
                    if _auto_paper and not _force_paper:
                        logger.debug(
                            f'[AUTO-FILTER] {symbol} {sig["strategy"]} flagged unprofitable '
                            f'(advisory — user override active, going live)'
                        )
                    if self.live_mode and not _force_paper:
                        # Reserve key now — prevents duplicate signals before parallel dispatch
                        self._entered_keys.add(key)
                        pending_live.append((symbol, slug, sig, secs_left, end_ts, m))
                    else:
                        # Always paper — data still collected for RL + rolling filter
                        self._paper_enter(symbol, slug, sig, secs_left, end_ts)
                    hits += 1

            # Step 4: fire all live orders in parallel (saves N-1 round trips vs serial)
            if pending_live:
                def _fire(args):
                    self._live_enter(*args)
                with ThreadPoolExecutor(max_workers=len(pending_live)) as ex:
                    list(ex.map(_fire, pending_live))

            if hits:
                logger.info(f'[HFT] Scan #{self._scan_count}: {hits} signals fired')
        except Exception as e:
            logger.warning(f'[HFT] scan_once error: {e}')

    def get_stats(self) -> dict:
        """Return summary statistics for the API."""
        with self._lock:
            trades = list(self._trades)
        resolved = [t for t in trades if t.get('resolved')]
        pending  = [t for t in trades if not t.get('resolved')]
        wins   = [t for t in resolved if t.get('outcome') == 'WIN']
        losses = [t for t in resolved if t.get('outcome') == 'LOSS']
        total_pnl = sum(t.get('paper_pnl') or 0 for t in resolved)

        # Daily PnL — UTC day, full PnL (filled + paper, what get_stats() already shows)
        _today = datetime.now(timezone.utc).strftime('%Y-%m-%d')
        today_resolved = [t for t in resolved
                          if (t.get('logged_at') or '').startswith(_today)
                          and t.get('outcome') in ('WIN','LOSS')]
        today_wins = sum(1 for t in today_resolved if t.get('outcome') == 'WIN')
        today_pnl  = round(sum(t.get('paper_pnl') or 0 for t in today_resolved), 2)
        today_wr   = round(today_wins / max(len(today_resolved), 1) * 100, 1)
        # Split daily into paper vs filled-real (same definition as the sidebar
        # Real PnL: only fill_confirmed=True counts as real). Anything else is
        # paper from a daily-PnL perspective — including REAL ✗ unfilled records
        # which now resolve to paper-equivalent outcomes (no wallet movement).
        today_real_resolved  = [t for t in today_resolved
                                if t.get('real_trade') and t.get('fill_confirmed') is True]
        today_paper_resolved = [t for t in today_resolved if t not in today_real_resolved]
        today_real_wins  = sum(1 for t in today_real_resolved if t.get('outcome') == 'WIN')
        today_paper_wins = sum(1 for t in today_paper_resolved if t.get('outcome') == 'WIN')
        today_real_pnl   = round(sum(t.get('paper_pnl') or 0 for t in today_real_resolved), 2)
        today_paper_pnl  = round(sum(t.get('paper_pnl') or 0 for t in today_paper_resolved), 2)
        today_real_wr    = round(today_real_wins  / max(len(today_real_resolved),  1) * 100, 1) if today_real_resolved  else None
        today_paper_wr   = round(today_paper_wins / max(len(today_paper_resolved), 1) * 100, 1) if today_paper_resolved else None

        def _strat(name):
            ts = [t for t in resolved if t.get('strategy') == name]
            w  = sum(1 for t in ts if t.get('outcome') == 'WIN')
            l  = sum(1 for t in ts if t.get('outcome') == 'LOSS')
            return {'wins': w, 'losses': l, 'total': len(ts),
                    'win_rate': round(w / max(w + l, 1) * 100, 1),
                    'pnl': round(sum(t.get('paper_pnl') or 0 for t in ts), 2)}

        total_volume = round(sum(t.get('stake', 0) or 0 for t in resolved), 2)

        # Real trade stats — only count fill_confirmed=True (CLOB verified MATCHED/FILLED)
        # GTC orders in fast markets expire without matching; the 0x-hash fallback was over-counting
        real_trades     = [t for t in trades if t.get('real_trade')]
        filled_trades   = [t for t in real_trades if t.get('fill_confirmed') is True]
        filled_resolved = [t for t in filled_trades if t.get('resolved')]
        unfilled_trades = [t for t in real_trades if t.get('fill_confirmed') is False]
        pending_fill    = [t for t in real_trades if t.get('fill_confirmed') is None]
        fill_rate = round(len(filled_trades) / max(len(real_trades), 1) * 100, 1)

        real_wins   = [t for t in filled_resolved if t.get('outcome') == 'WIN']
        real_losses = [t for t in filled_resolved if t.get('outcome') == 'LOSS']
        real_pnl    = round(sum(t.get('paper_pnl') or 0 for t in filled_resolved), 2)
        real_wr     = round(len(real_wins) / max(len(real_wins) + len(real_losses), 1) * 100, 1)
        real_volume = round(sum(t.get('stake', 0) or 0 for t in filled_resolved), 2)

        # Session breakdown
        SESSIONS = ['ASIA', 'US_OPEN', 'US_AFT', 'OVERNIGHT']
        session_stats = {}
        for sess in SESSIONS:
            st = [t for t in resolved if t.get('fill_session') == sess]
            sw = sum(1 for t in st if t.get('outcome') == 'WIN')
            sl = sum(1 for t in st if t.get('outcome') == 'LOSS')
            session_stats[sess] = {
                'total': len(st),
                'wins': sw,
                'losses': sl,
                'win_rate': round(sw / max(sw + sl, 1) * 100, 1) if (sw + sl) > 0 else None,
                'pnl': round(sum(t.get('paper_pnl') or 0 for t in st), 2),
            }

        # Per-symbol stats — all resolved trades (paper + real combined)
        # Previously filtered to filled_resolved only, which froze the table in paper mode.
        # by_symbol_real is kept separately for callers that need wallet-only view.
        all_syms = sorted(set(t.get('symbol', '') for t in resolved if t.get('symbol')))
        by_symbol = {}
        for sym in all_syms:
            st = [t for t in resolved if t.get('symbol') == sym]
            sw = sum(1 for t in st if t.get('outcome') == 'WIN')
            sl = sum(1 for t in st if t.get('outcome') == 'LOSS')
            sp = round(sum(t.get('paper_pnl') or 0 for t in st), 2)
            by_symbol[sym] = {
                'wins': sw, 'losses': sl, 'total': len(st),
                'win_rate': round(sw / max(sw + sl, 1) * 100, 1),
                'pnl': sp,
            }
        # Real-only breakdown (preserved for live wallet reporting)
        by_symbol_real = {}
        for sym in sorted(set(t.get('symbol', '') for t in filled_resolved if t.get('symbol'))):
            st = [t for t in filled_resolved if t.get('symbol') == sym]
            sw = sum(1 for t in st if t.get('outcome') == 'WIN')
            sl = sum(1 for t in st if t.get('outcome') == 'LOSS')
            sp = round(sum(t.get('paper_pnl') or 0 for t in st), 2)
            by_symbol_real[sym] = {
                'wins': sw, 'losses': sl, 'total': len(st),
                'win_rate': round(sw / max(sw + sl, 1) * 100, 1),
                'pnl': sp,
            }

        return {
            'total_trades': len(trades),
            'resolved': len(resolved),
            'pending': len(pending),
            'wins': len(wins),
            'losses': len(losses),
            'win_rate': round(len(wins) / max(len(resolved), 1) * 100, 1),
            'total_pnl': round(total_pnl, 2),
            'total_volume': total_volume,
            'scan_count': self._scan_count,
            'last_scan_ts': self._last_scan_ts,
            'live_mode': self.live_mode,
            'stake': self.stake,
            'paper_strategies': sorted(self.paper_strategies),
            'paper_symbols': sorted(self.paper_symbols),
            'auto_papered': sorted(self._auto_paper_keys),
            'wallet_live': bool(self.bot and self.bot.wallet_live and self.bot.clob_client),
            'real_trades': len(real_trades),
            'filled_trades': len(filled_trades),
            'unfilled_trades': len(unfilled_trades),
            'pending_fill': len(pending_fill),
            'fill_rate': fill_rate,
            'real_wins': len(real_wins),
            'real_losses': len(real_losses),
            'real_pnl': real_pnl,
            'real_wr': real_wr,
            'real_volume': real_volume,
            # Today (UTC) — full PnL across paper + filled
            'today_resolved': len(today_resolved),
            'today_wins':     today_wins,
            'today_pnl':      today_pnl,
            'today_wr':       today_wr,
            # Today split — paper-only vs filled-real (sidebar Real PnL convention)
            'today_paper_resolved': len(today_paper_resolved),
            'today_paper_pnl':      today_paper_pnl,
            'today_paper_wr':       today_paper_wr,
            'today_real_resolved':  len(today_real_resolved),
            'today_real_pnl':       today_real_pnl,
            'today_real_wr':        today_real_wr,
            'strategies': {
                'MOMENTUM-BURST': _strat('MOMENTUM-BURST'),
                'EXTREME-RIDE':   _strat('EXTREME-RIDE'),
            },
            'by_symbol': by_symbol,
            'by_symbol_real': by_symbol_real,
            'session_breakdown': session_stats,
            # Resting-SL effectiveness (separate from _execute_sl_exit path)
            'resting_sl_comparison': self._build_resting_sl_stats(filled_resolved),
            # Slippage telemetry (actual_fill_price vs entry_price)
            'slippage': self._build_slippage_stats(filled_resolved),
        }

    def _build_resting_sl_stats(self, real_resolved):
        """Aggregate resting-SL effectiveness across resolved real HFT trades."""
        rsl = [t for t in real_resolved if t.get('sl_resting_order_id')]
        n_placed = len(rsl)
        n_filled = sum(1 for t in rsl if (t.get('sl_resting_filled_size') or 0) > 0)
        total_natural = round(sum(t.get('natural_close_pnl') or 0 for t in rsl), 2)
        total_actual  = round(sum(t.get('actual_realized_pnl') or 0 for t in rsl), 2)
        delta = round(total_actual - total_natural, 2)
        by_dir = {}
        for d in ('UP', 'DOWN'):
            sub = [t for t in rsl if t.get('direction') == d]
            sf = sum(1 for t in sub if (t.get('sl_resting_filled_size') or 0) > 0)
            by_dir[d] = {
                'n_placed': len(sub), 'n_filled': sf,
                'fill_rate': round(sf / max(len(sub), 1) * 100, 1),
                'natural_pnl': round(sum(t.get('natural_close_pnl') or 0 for t in sub), 2),
                'actual_pnl':  round(sum(t.get('actual_realized_pnl') or 0 for t in sub), 2),
                'delta':       round(sum(t.get('sl_savings') or 0 for t in sub), 2),
            }
        filled_only = [t for t in rsl if (t.get('sl_resting_filled_size') or 0) > 0]
        avg_sav = (round(sum(t.get('sl_savings') or 0 for t in filled_only) / max(len(filled_only), 1), 3)
                   if filled_only else 0.0)
        false_alarms = [t for t in filled_only if t.get('outcome') == 'WIN']
        true_saves   = [t for t in filled_only if t.get('outcome') == 'LOSS']
        return {
            'n_placed':          n_placed,
            'n_filled':          n_filled,
            'fill_rate':         round(n_filled / max(n_placed, 1) * 100, 1),
            'total_natural_pnl': total_natural,
            'total_actual_pnl':  total_actual,
            'delta':             delta,
            'avg_savings_per_fill': avg_sav,
            'true_saves':        {'n': len(true_saves),  'value': round(sum(t.get('sl_savings') or 0 for t in true_saves), 2)},
            'false_alarms':      {'n': len(false_alarms),'cost':  round(sum(t.get('sl_savings') or 0 for t in false_alarms), 2)},
            'by_direction':      by_dir,
        }

    def _build_slippage_stats(self, real_resolved):
        slipped = [t for t in real_resolved
                   if t.get('actual_fill_price') is not None
                   and (t.get('entry_price') or 0) > 0]
        if not slipped:
            return {'n': 0}
        bps = [(float(t['actual_fill_price']) - float(t['entry_price'])) * 10000 for t in slipped]
        return {
            'n':       len(slipped),
            'avg_bps': round(sum(bps) / len(bps), 1),
            'max_bps': round(max(bps), 1),
            'min_bps': round(min(bps), 1),
            'over_50bps': sum(1 for b in bps if b > 50),
            'under_neg50bps': sum(1 for b in bps if b < -50),
        }


# ──────────────────────────────────────────────────────────────────────────────
# BTC ML-HFT — machine-learning scanner for BTC 5m/15m up-down markets
# ──────────────────────────────────────────────────────────────────────────────

class BTCMLModel:
    """
    Pure-Python logistic regression trained on 10 hand-crafted features
    extracted from 1m/5m Binance candles + Polymarket order book.

    No sklearn — inference is a single dot-product + sigmoid.
    Weights are persisted to btc_ml_model.json and retrained every 25 resolved trades.
    """
    RETRAIN_EVERY   = 25
    MIN_TRAIN_N     = 10
    LR              = 0.05
    EPOCHS          = 200
    # TRAIN_WINDOW_N removed 2026-06-09: cap disabled, full history used for training.
    FEATURE_NAMES = [
        'price_momentum_1m',    # 0
        'price_momentum_5m',    # 1
        'volume_spike',         # 2
        'wick_pressure',        # 3
        'body_strength',        # 4
        'bid_ask_imbalance',    # 5  (CLOB)
        'price_distance_50',    # 6
        'volatility',           # 7
        'session_code',         # 8
        'secs_left_norm',       # 9
        'depth_imbalance',      # 10 (Binance depth20) — bid/(bid+ask) qty
        'trade_flow_imbal',     # 11 (Binance aggTrade 30s) — buy vol / total
        'liq_cascade',          # 12 (Binance futures forceOrder 5s) — normalized $
        'funding_rate',         # 13 (Binance futures premiumIndex)
    ]
    N_FEATURES = 14

    def __init__(self, symbol: str = 'BTC'):
        self.SYMBOL  = symbol.upper()
        self._sym_lc = symbol.lower()
        self.MODEL_FILE = f'{self._sym_lc}_ml_model.json'
        self._log    = f'{self.SYMBOL}-ML'   # log prefix: 'BTC-ML' or 'ETH-ML'
        self.weights: list = [0.0] * self.N_FEATURES
        self.bias: float = 0.0
        self.n_trained: int = 0
        self.last_retrain_ts: Optional[float] = None
        self.accuracy: Optional[float] = None
        self._untrained_count: int = 0
        self._load()

    def _load(self):
        try:
            path = _resolve_state_path(self.MODEL_FILE)
            if os.path.exists(path):
                with open(path, 'r') as f:
                    d = json.load(f)
                loaded_w = d.get('weights', [])
                # Pad to N_FEATURES if model was saved with fewer features
                if len(loaded_w) < self.N_FEATURES:
                    loaded_w = loaded_w + [0.0] * (self.N_FEATURES - len(loaded_w))
                self.weights         = loaded_w[:self.N_FEATURES]
                self.bias            = d.get('bias', 0.0)
                self.n_trained       = d.get('n_trained', 0)
                self.last_retrain_ts = d.get('last_retrain_ts')
                self.accuracy        = d.get('accuracy')
                logger.info(f'[{self._log}] Loaded model from {os.path.basename(path)} (n_trained={self.n_trained})')
        except Exception as e:
            logger.debug(f'[{self._log}] Model load error: {e}')

    def _save(self):
        path = _resolve_state_path(self.MODEL_FILE)
        tmp  = path + f'.tmp_{os.getpid()}'
        try:
            with open(tmp, 'w') as f:
                json.dump({
                    'weights':         self.weights,
                    'bias':            self.bias,
                    'feature_names':   self.FEATURE_NAMES,
                    'n_trained':       self.n_trained,
                    'last_retrain_ts': self.last_retrain_ts,
                    'accuracy':        self.accuracy,
                }, f, indent=2)
            os.replace(tmp, path)
        except Exception as e:
            logger.warning(f'[{self._log}] Model save error: {e}')
            try: os.remove(tmp)
            except OSError: pass

    # ── feature extraction ────────────────────────────────────────────────────

    def extract_features(self, candles_1m: list, candles_5m: list,
                         yes_price: float, secs_left: float,
                         bids: list, asks: list,
                         depth_imbalance: float = 0.5,
                         trade_flow_imbal: float = 0.5,
                         liq_cascade_usd: float = 0.0,
                         funding_rate: float = 0.0) -> list:
        """Extract 14 ML features. Always returns a list of 14 floats."""
        import math as _math

        # Feature 0 — price_momentum_1m: recent 3 closes vs prior 3
        if len(candles_1m) >= 6:
            r_avg = sum(c['close'] for c in candles_1m[-3:]) / 3
            p_avg = sum(c['close'] for c in candles_1m[-6:-3]) / 3
            f0 = (r_avg - p_avg) / max(p_avg, 1.0)
        else:
            f0 = 0.0

        # Feature 1 — price_momentum_5m: recent 2 closes vs prior 2
        if len(candles_5m) >= 4:
            r5 = sum(c['close'] for c in candles_5m[-2:]) / 2
            p5 = sum(c['close'] for c in candles_5m[-4:-2]) / 2
            f1 = (r5 - p5) / max(p5, 1.0)
        else:
            f1 = 0.0

        # Feature 2 — volume_spike: current 1m vol vs rolling avg
        if len(candles_1m) >= 2:
            avg_vol = sum(c['volume'] for c in candles_1m[:-1]) / max(len(candles_1m) - 1, 1)
            f2 = candles_1m[-1]['volume'] / max(avg_vol, 1.0) - 1.0
            f2 = max(-2.0, min(3.0, f2))
        else:
            f2 = 0.0

        # Feature 3 — wick_pressure: (lower_wick - upper_wick) / range
        if candles_1m:
            c = candles_1m[-1]
            rng = max(c['high'] - c['low'], 1e-8)
            upper = c['high'] - max(c['open'], c['close'])
            lower = min(c['open'], c['close']) - c['low']
            f3 = (lower - upper) / rng
        else:
            f3 = 0.0

        # Feature 4 — body_strength: signed body / range
        if candles_1m:
            c = candles_1m[-1]
            rng = max(c['high'] - c['low'], 1e-8)
            f4 = (c['close'] - c['open']) / rng
        else:
            f4 = 0.0

        # Feature 5 — bid_ask_imbalance from CLOB top-5 levels
        if bids and asks:
            bid_d = sum(float(b.get('size', 0)) for b in bids[:5])
            ask_d = sum(float(a.get('size', 0)) for a in asks[:5])
            total = bid_d + ask_d
            f5 = (bid_d - ask_d) / max(total, 1e-8)
        else:
            f5 = 0.0

        # Feature 6 — price_distance_50: yes_price distance from neutral
        f6 = (yes_price - 0.50) * 2.0

        # Feature 7 — volatility: rolling std of 1m close returns × 100
        if len(candles_1m) >= 3:
            closes = [c['close'] for c in candles_1m[-10:]]
            rets   = [(closes[i] - closes[i-1]) / max(closes[i-1], 1.0)
                      for i in range(1, len(closes))]
            mean_r = sum(rets) / len(rets)
            var    = sum((r - mean_r) ** 2 for r in rets) / len(rets)
            f7     = min(var ** 0.5 * 100.0, 2.0)
        else:
            f7 = 0.0

        # Feature 8 — session_code
        hr = datetime.now(timezone.utc).hour
        if 0 <= hr < 8:     f8 = -1.0
        elif 8 <= hr < 12:  f8 =  0.0
        elif 12 <= hr < 20: f8 =  0.5
        else:               f8 =  1.0

        # Feature 9 — secs_left_norm
        f9 = min(max(secs_left / 130.0, 0.0), 1.0)

        # Feature 10 — depth_imbalance: Binance top-20 bid/(bid+ask) qty
        # 0.5=neutral, >0.6=bids stacked (bullish), <0.4=asks stacked (bearish)
        f10 = round(max(0.0, min(1.0, depth_imbalance)), 6)

        # Feature 11 — trade_flow_imbalance: aggressive buy vol / total (30s window)
        # 0.5=neutral, >0.65=strong buy pressure, <0.35=strong sell pressure
        f11 = round(max(0.0, min(1.0, trade_flow_imbal)), 6)

        # Feature 12 — liq_cascade: recent 5s liquidation $USD, normalized + signed
        # Positive = long liquidations (bearish), negative = short liquidations (bullish)
        # Scaled: $300k→0.3, $1M→1.0, capped at ±1.5
        import math as _m2
        f12 = round(max(-1.5, min(1.5, liq_cascade_usd / 1_000_000.0)), 6)

        # Feature 13 — funding_rate: extreme positive = overcrowded longs (fade UP)
        # Normalized: 0.01% funding → 1.0; typical range ±0.03% so scale ×100
        f13 = round(max(-3.0, min(3.0, funding_rate * 1000.0)), 6)

        return [round(x, 6) for x in (f0, f1, f2, f3, f4, f5, f6, f7, f8, f9,
                                       f10, f11, f12, f13)]

    # ── inference ─────────────────────────────────────────────────────────────

    def predict(self, features: list) -> tuple:
        """Returns (prob_up: float, direction: str)."""
        import math as _math
        z = sum(w * x for w, x in zip(self.weights, features)) + self.bias
        if z >= 0:
            prob = 1.0 / (1.0 + _math.exp(-z))
        else:
            ez   = _math.exp(z)
            prob = ez / (1.0 + ez)
        direction = 'UP' if prob >= 0.5 else 'DOWN'
        return prob, direction

    # ── training ──────────────────────────────────────────────────────────────

    def train(self, examples: list) -> dict:
        """Full-batch gradient descent. examples: [{'features': [...], 'label': 0|1}]"""
        import math as _math
        n = len(examples)
        if n < self.MIN_TRAIN_N:
            return {'ok': False, 'reason': f'need {self.MIN_TRAIN_N} samples, have {n}'}

        w = list(self.weights)
        b = self.bias
        nf = self.N_FEATURES

        for epoch in range(self.EPOCHS):
            dw = [0.0] * nf
            db = 0.0
            total_loss = 0.0
            correct = 0
            for ex in examples:
                x = ex['features']
                y = ex['label']
                z = sum(w[i] * x[i] for i in range(nf)) + b
                if z >= 0:
                    p = 1.0 / (1.0 + _math.exp(-z))
                else:
                    ez = _math.exp(z)
                    p  = ez / (1.0 + ez)
                err = p - y
                for i in range(nf):
                    dw[i] += err * x[i]
                db += err
                total_loss += -(y * _math.log(max(p, 1e-9)) +
                                (1 - y) * _math.log(max(1 - p, 1e-9)))
                if (p >= 0.5) == (y == 1):
                    correct += 1
            for i in range(nf):
                w[i] -= self.LR * dw[i] / n
            b -= self.LR * db / n

        accuracy = round(correct / n * 100, 1)
        self.weights         = [round(wi, 6) for wi in w]
        self.bias            = round(b, 6)
        self.n_trained       = n
        self.last_retrain_ts = time.time()
        self.accuracy        = accuracy
        self._save()
        logger.info(f'[{self._log}] Retrained on {n} samples — accuracy={accuracy}% '
                    f'loss={total_loss/n:.4f}')
        return {'ok': True, 'n': n, 'accuracy': accuracy, 'loss': round(total_loss / n, 4)}

    def retrain_from_log(self, trades: list) -> dict:
        """Build examples from time-close resolved trades only (not scalp exits).
        Scalp exits resolve on TP/SL mid-candle — their outcome reflects price noise,
        not the true directional signal. Time-close trades give clean labels.

        Weekend-aware filtering (when weekend_mode.json is configured):
          - Weekend mode active: keep only weekend-window trades.
          - Weekday mode + weekend feature configured: drop weekend-window trades so
            weekday weights stay pure (Monday picks up from Friday-night state).
          - Weekend feature disabled/absent: use all trades (legacy behavior)."""
        _wcfg = _weekend_mode_config()
        if _is_weekend_mode_now():
            n_all = len(trades)
            trades = [t for t in trades if _trade_logged_in_weekend(t)]
            logger.info(f'[{self._log}] Weekend retrain: filtered to {len(trades)} weekend trades from {n_all} total')
        elif _wcfg.get('enabled'):
            n_all = len(trades)
            trades = [t for t in trades if not _trade_logged_in_weekend(t)]
            logger.info(f'[{self._log}] Weekday retrain: excluded weekend trades, {len(trades)} weekday trades from {n_all} total')
        examples = []
        for t in trades:
            if not t.get('resolved') or t.get('outcome') not in ('WIN', 'LOSS'):
                continue
            if t.get('scalp_exited'):
                continue   # skip — scalp outcome is noisy, not the true market direction
            feats = t.get('ml_features')
            if not feats or len(feats) != self.N_FEATURES:
                continue
            direction = t.get('direction', 'UP').upper()
            outcome   = t.get('outcome', 'LOSS')
            # label=1 means the UP prediction was correct
            if direction == 'UP':
                label = 1 if outcome == 'WIN' else 0
            else:
                label = 0 if outcome == 'WIN' else 1
            examples.append({'features': feats, 'label': label})
        return self.train(examples)

    def add_resolved_trade(self, _trade: dict) -> bool:
        """Increment counter; return True when a retrain is due.
        During weekend mode, retraining still fires, but retrain_from_log filters
        the trade list to weekend-window trades only — so weekend weights learn
        only from weekend data (and weekday weights are untouched on disk)."""
        self._untrained_count += 1
        if self._untrained_count >= self.RETRAIN_EVERY:
            self._untrained_count = 0
            return True
        return False

    def feature_importances(self) -> list:
        abs_w = [abs(w) for w in self.weights]
        max_w = max(abs_w) if any(abs_w) else 1.0
        return [
            {'name': n, 'weight': round(self.weights[i], 4),
             'importance': round(abs_w[i] / max_w, 3)}
            for i, n in enumerate(self.FEATURE_NAMES)
        ]


class BTCMLRl:
    """
    Q-table RL gate — identical pattern to HFTRL but ML-symbol-scoped.
    Disabled until ENABLED_AFTER resolved trades exist (data collection phase).
    State key: '<SYMBOL>|{price_bucket}|{secs_bucket}|ML'
    """
    ALPHA         = 0.15
    SKIP_THRESHOLD = -0.30  # class default. Per-symbol override via instance attr set by
                             # BTCMLScanner._load_settings -> self.rl.SKIP_THRESHOLD = <from settings file>.
                             # History: -0.10 (Apr 30 original), -0.30 (May 10 audit, daily_notes #18),
                             # -0.40 briefly globally 2026-05-18 then reverted to per-symbol same day (entry #67).
    MIN_VISITS    = 5
    ENABLED_AFTER = 50

    def __init__(self, symbol: str = 'BTC', skip_threshold: Optional[float] = None):
        # 2026-05-18: allow per-instance threshold override so BTC and ETH can tune independently.
        # Class-level SKIP_THRESHOLD remains the default; passing skip_threshold here (or assigning
        # self.SKIP_THRESHOLD after construction) shadows the class default with an instance attribute.
        if skip_threshold is not None:
            self.SKIP_THRESHOLD = float(skip_threshold)
        self.SYMBOL  = symbol.upper()
        self._sym_lc = symbol.lower()
        self.RL_FILE = f'{self._sym_lc}_ml_rl_state.json'
        self._log    = f'{self.SYMBOL}-ML-RL'
        self._q: dict = {}
        self._dirty   = False
        self._load()
        _start_q_decay_sweeper(self, self._log)
        _start_dirty_flush_loop(self, self._log)

    def _load(self):
        try:
            path = _resolve_state_path(self.RL_FILE)
            if os.path.exists(path):
                with open(path, 'r') as f:
                    self._q = json.load(f)
                logger.info(f'[{self._log}] Loaded {len(self._q)} states from {os.path.basename(path)}')
        except Exception:
            self._q = {}

    def _save(self):
        path = _resolve_state_path(self.RL_FILE)
        tmp  = path + f'.tmp_{os.getpid()}'
        try:
            with open(tmp, 'w') as f:
                json.dump(self._q, f, indent=2)
            os.replace(tmp, path)
        except Exception as e:
            logger.warning(f'[{self._log}] Save error: {e}')
            try: os.remove(tmp)
            except OSError: pass

    def _state_key(self, entry_price: float, secs_left: float) -> str:
        if entry_price < 0.60:   price_b = 'p_low'
        elif entry_price < 0.70: price_b = 'p_mid'
        elif entry_price < 0.80: price_b = 'p_hi'
        else:                    price_b = 'p_top'
        if secs_left < 20:       secs_b  = 's_final'
        elif secs_left < 40:     secs_b  = 's_late'
        elif secs_left < 60:     secs_b  = 's_mid'
        else:                    secs_b  = 's_early'
        return f'{self.SYMBOL}|{price_b}|{secs_b}|ML'

    def score(self, entry_price: float, secs_left: float) -> tuple:
        key  = self._state_key(entry_price, secs_left)
        cell = self._q.get(key, {'q': 0.0, 'n': 0})
        return cell['q'], cell['n'], key

    def should_enter(self, entry_price: float, secs_left: float,
                     resolved_count: int) -> tuple:
        if resolved_count < self.ENABLED_AFTER:
            return True, 'rl_disabled_collecting'
        q, n, key = self.score(entry_price, secs_left)
        if n < self.MIN_VISITS:
            return True, f'exploring n={n}'
        if q < self.SKIP_THRESHOLD:
            return False, f'Q={q:.3f} below threshold'
        return True, f'Q={q:.3f} n={n}'

    def update(self, entry_price: float, secs_left: float,
               stake: float, pnl: float, weight: float = 1.0):
        """Update Q-value for the state.

        weight: scales the EWMA learning rate. Real trade outcomes use
        weight=1.0; shadow-block resolutions use weight<1.0 (typically 0.3)
        so blocked-cell data informs the gate but doesn't dominate real
        outcomes. Added 2026-05-20 to break the self-fulfilling loop where
        cells dropped below SKIP_THRESHOLD got no fresh data and could
        only drift more negative.
        """
        if stake <= 0 or weight <= 0:
            return
        roi = pnl / stake
        key = self._state_key(entry_price, secs_left)
        if key not in self._q:
            self._q[key] = {'q': 0.0, 'n': 0, 'last_ts': time.time()}
        cell    = self._q[key]
        _apply_q_decay(cell, 168.0)
        alpha_eff = self.ALPHA * weight
        cell['q'] = round((1 - alpha_eff) * cell['q'] + alpha_eff * roi, 6)
        cell['n'] += 1
        cell['last_ts'] = time.time()
        self._dirty = True

    def summary(self) -> dict:
        total   = len(self._q)
        blocked = sum(1 for v in self._q.values()
                      if v['n'] >= self.MIN_VISITS and v['q'] < self.SKIP_THRESHOLD)
        allowed = sum(1 for v in self._q.values()
                      if v['n'] >= self.MIN_VISITS and v['q'] >= self.SKIP_THRESHOLD)
        exploring = sum(1 for v in self._q.values() if v['n'] < self.MIN_VISITS)
        avg_q = (sum(v['q'] for v in self._q.values()) / total) if total else 0.0
        states = [{'key': k, 'q': round(v['q'], 4), 'n': v['n']}
                  for k, v in sorted(self._q.items(), key=lambda x: x[1]['q'])]
        return {
            'total': total, 'blocked': blocked, 'allowed': allowed,
            'exploring': exploring, 'avg_q': round(avg_q, 4), 'states': states,
        }


# ──────────────────────────────────────────────────────────────────────────────
# BINANCE WEBSOCKET FEEDS — spot + futures data for maximum edge
#
# BinancePriceWS  (spot):   aggTrade + kline_1m + kline_5m + depth20@100ms
#   → price triggers, live candles, real-time order book depth imbalance
#
# BinanceFuturesWS (futures): forceOrder liquidations + funding rate REST poll
#   → liquidation cascade signals, funding rate sentiment
#
# Edge stack:
#   1. Binance price → Polymarket 100-500ms lag arb  (already active)
#   2. Depth imbalance → stacked bids/asks predict next tick direction
#   3. Trade flow imbalance → aggressive buys/sells signal momentum
#   4. Liquidation cascade → forced position unwinds = violent, predictable moves
#   5. Funding rate → extreme values signal overcrowded positions → mean reversion
# ──────────────────────────────────────────────────────────────────────────────

class BinancePriceWS:
    """
    Spot stream: aggTrade + kline_1m + kline_5m + depth20@100ms.
    Tracks price moves, rolling candles, depth imbalance, and trade flow imbalance.
    Default symbol BTC (back-compat); pass symbol='ETH' etc. for parallel feeds.
    """
    MAX_CANDLES    = 35
    TRADE_WINDOW_S = 30   # rolling window for buy/sell vol imbalance

    def __init__(self, move_threshold: float = 0.0010, symbol: str = 'BTC'):
        self.SYMBOL = symbol.upper()
        sym_lc = symbol.lower()
        self.WS_URL = ('wss://stream.binance.com:9443/stream?streams='
                       f'{sym_lc}usdt@aggTrade/{sym_lc}usdt@kline_1m/'
                       f'{sym_lc}usdt@kline_5m/{sym_lc}usdt@depth20@100ms')
        self._move_threshold = move_threshold
        self._ref_price: float | None = None
        self._last_price: float | None = None
        self._callbacks: list = []
        self._running = True
        self._lock = threading.Lock()
        from collections import deque as _dq
        # Candle buffers
        self._candles: dict = {'1m': _dq(maxlen=self.MAX_CANDLES),
                                '5m': _dq(maxlen=self.MAX_CANDLES)}
        self._candle_lock = threading.Lock()
        # Depth imbalance: top-20 bid vs ask total quantity
        self._depth_bid_qty  = 0.0
        self._depth_ask_qty  = 0.0
        self._depth_lock     = threading.Lock()
        # Trade flow: rolling (timestamp, buy_qty, sell_qty)
        self._trade_flow: _dq = _dq(maxlen=500)  # ~500 trades covers 30s easily
        self._flow_lock  = threading.Lock()
        # 1-second candle builder (for low-latency video-game chart)
        self._candles_1s: _dq = _dq(maxlen=300)   # 5 min of 1s bars
        self._candles_15s: _dq = _dq(maxlen=240)  # 1 hr of 15s bars
        self._cur_1s:  dict | None = None
        self._cur_15s: dict | None = None
        self._tick_lock = threading.Lock()
        # Recent large trades for liquidation star effect
        self._big_trades: _dq = _dq(maxlen=50)  # (ts, price, qty, side)
        self._t = threading.Thread(target=self._run, daemon=True,
                                    name=f'binance-spot-ws-{self.SYMBOL}')
        self._t.start()
        logger.info(f'[BinanceWS-{self.SYMBOL}] Spot stream started (aggTrade+klines+depth20+1s bars)')

    def register(self, cb):
        """Register callback(price, pct, direction) fired on price move >= threshold."""
        self._callbacks.append(cb)

    def get_candles(self, interval: str) -> list:
        if interval in ('1s', '15s'):
            with self._tick_lock:
                if interval == '1s':
                    result = list(self._candles_1s)
                    if self._cur_1s:
                        result.append(dict(self._cur_1s))
                else:
                    result = list(self._candles_15s)
                    if self._cur_15s:
                        result.append(dict(self._cur_15s))
            return result
        with self._candle_lock:
            return list(self._candles.get(interval, []))

    def get_big_trades(self, since_s: float = 2.0) -> list:
        """Returns large trades (>0.5 BTC) in last since_s seconds for star effect."""
        cutoff = time.time() - since_s
        with self._tick_lock:
            return [t for t in self._big_trades if t[0] >= cutoff]

    def get_depth_imbalance(self) -> float:
        """Bid/(bid+ask) qty ratio. >0.6 = bids stacked (bullish), <0.4 = asks stacked."""
        with self._depth_lock:
            total = self._depth_bid_qty + self._depth_ask_qty
            if total <= 0:
                return 0.5
            return self._depth_bid_qty / total

    def get_trade_flow_imbalance(self) -> float:
        """Aggressive buy vol / total vol in last 30s. >0.6 = buy pressure."""
        now = time.time()
        cutoff = now - self.TRADE_WINDOW_S
        with self._flow_lock:
            recent = [(b, s) for ts, b, s in self._trade_flow if ts >= cutoff]
        if not recent:
            return 0.5
        buy_vol  = sum(b for b, s in recent)
        sell_vol = sum(s for b, s in recent)
        total = buy_vol + sell_vol
        return buy_vol / total if total > 0 else 0.5

    @property
    def last_price(self) -> float | None:
        return self._last_price

    def _run(self):
        import websocket as _wslib
        delay = 2
        while self._running:
            try:
                ws = _wslib.WebSocketApp(
                    self.WS_URL,
                    on_message=self._on_msg,
                    on_error=lambda ws, e: logger.debug(f'[BinanceWS] error: {e}'),
                    on_open=lambda ws: logger.info('[BinanceWS] spot connected'),
                    on_close=lambda ws, c, m: logger.debug(f'[BinanceWS] spot closed'),
                )
                ws.run_forever(ping_interval=25, ping_timeout=10)
                delay = min(delay * 2, 30)
            except Exception as e:
                logger.debug(f'[BinanceWS] run error: {e}')
            if self._running:
                time.sleep(delay)

    def _on_msg(self, ws, raw):
        try:
            outer  = json.loads(raw)
            stream = outer.get('stream', '')
            d      = outer.get('data', outer)

            if 'kline' in stream:
                k = d.get('k', {})
                iv = k.get('i', '')
                if iv not in self._candles:
                    return
                c = {'time': int(k['t'])//1000, 'open': float(k['o']),
                     'high': float(k['h']),     'low':  float(k['l']),
                     'close': float(k['c']),    'volume': float(k['v'])}
                with self._candle_lock:
                    buf = self._candles[iv]
                    if buf and buf[-1]['time'] == c['time']:
                        buf[-1] = c
                    else:
                        buf.append(c)
                return

            if 'depth' in stream:
                bids = d.get('bids', [])
                asks = d.get('asks', [])
                with self._depth_lock:
                    self._depth_bid_qty = sum(float(b[1]) for b in bids)
                    self._depth_ask_qty = sum(float(a[1]) for a in asks)
                return

            # aggTrade
            price = float(d.get('p', 0))
            if price <= 0:
                return
            qty      = float(d.get('q', 0))
            is_maker = bool(d.get('m', False))  # m=True → seller was maker → buyer aggressive
            buy_qty  = qty if not is_maker else 0.0
            sell_qty = qty if is_maker     else 0.0
            now = time.time()
            with self._flow_lock:
                self._trade_flow.append((now, buy_qty, sell_qty))

            # Build 1s and 15s candles from aggTrades
            t1  = int(now)
            t15 = int(now) - (int(now) % 15)
            with self._tick_lock:
                # 1-second candles
                if self._cur_1s is None or self._cur_1s['time'] != t1:
                    if self._cur_1s:
                        self._candles_1s.append(dict(self._cur_1s))
                    self._cur_1s = {'time':t1,'open':price,'high':price,'low':price,'close':price,'volume':qty}
                else:
                    c = self._cur_1s
                    c['high']   = max(c['high'], price)
                    c['low']    = min(c['low'],  price)
                    c['close']  = price
                    c['volume'] += qty
                # 15-second candles
                if self._cur_15s is None or self._cur_15s['time'] != t15:
                    if self._cur_15s:
                        self._candles_15s.append(dict(self._cur_15s))
                    self._cur_15s = {'time':t15,'open':price,'high':price,'low':price,'close':price,'volume':qty}
                else:
                    c = self._cur_15s
                    c['high']   = max(c['high'], price)
                    c['low']    = min(c['low'],  price)
                    c['close']  = price
                    c['volume'] += qty
                # Track big trades for liquidation star effect
                if qty >= 0.5:  # 0.5 BTC+
                    side = 'BUY' if not is_maker else 'SELL'
                    self._big_trades.append((now, price, qty, side))

            with self._lock:
                self._last_price = price
                ref = self._ref_price
                if ref is None:
                    self._ref_price = price
                    return
                pct = (price - ref) / ref
                if abs(pct) < self._move_threshold:
                    return
                direction = 'DOWN' if pct < 0 else 'UP'
                self._ref_price = price
            logger.info(f'[BinanceWS-{self.SYMBOL}] {direction} {pct*100:+.2f}% @ ${price:,.0f}')
            for cb in self._callbacks:
                try:
                    cb(price, pct, direction)
                except Exception as e:
                    logger.debug(f'[BinanceWS-{self.SYMBOL}] cb error: {e}')
        except Exception as e:
            logger.debug(f'[BinanceWS-{self.SYMBOL}] parse error: {e}')

    def stop(self):
        self._running = False


class BinanceFuturesWS:
    """
    Futures stream: forceOrder (liquidations) + REST-polled funding rate.

    Liquidation cascade edge:
      When $300k+ of BTC longs/shorts are force-liquidated in 5 seconds,
      a violent price move is already in progress. Polymarket won't have repriced
      yet — this is the highest-conviction window to enter.

    Funding rate edge:
      Extreme positive funding (+0.05%+) = overcrowded longs → fade UP, ride DOWN.
      Extreme negative funding = overcrowded shorts → fade DOWN, ride UP.
    """
    CASCADE_THRESH  = 300_000   # $300k liquidated in 5s = cascade signal
    CASCADE_WINDOW  = 5.0       # seconds

    def __init__(self, symbol: str = 'BTC'):
        self.SYMBOL = symbol.upper()
        sym_lc      = symbol.lower()
        self.WS_URL      = f'wss://fstream.binance.com/ws/{sym_lc}usdt@forceOrder'
        self.FUNDING_URL = f'https://fapi.binance.com/fapi/v1/premiumIndex?symbol={self.SYMBOL}USDT'
        self._log        = f'BinanceFut-{self.SYMBOL}'
        from collections import deque as _dq
        self._liqs: _dq = _dq(maxlen=200)   # (timestamp, usd_value, side)
        self._liq_lock   = threading.Lock()
        self._funding_rate: float = 0.0
        self._funding_lock = threading.Lock()
        self._cascade_callbacks: list = []
        self._running = True
        self._t = threading.Thread(target=self._run_ws,
                                    daemon=True, name=f'binance-futures-ws-{self.SYMBOL}')
        self._f = threading.Thread(target=self._run_funding,
                                    daemon=True, name=f'binance-funding-{self.SYMBOL}')
        self._t.start()
        self._f.start()
        logger.info(f'[{self._log}] Futures stream started (forceOrder + funding rate)')

    def register_cascade(self, cb):
        """Register callback(usd_volume, direction) fired on liquidation cascade."""
        self._cascade_callbacks.append(cb)

    def get_liq_cascade(self) -> tuple:
        """Returns (usd_vol, direction) for last CASCADE_WINDOW seconds, or (0, None)."""
        now = time.time()
        cutoff = now - self.CASCADE_WINDOW
        with self._liq_lock:
            recent = [(v, s) for ts, v, s in self._liqs if ts >= cutoff]
        if not recent:
            return 0.0, None
        long_liqs  = sum(v for v, s in recent if s == 'SELL')  # long liquidated
        short_liqs = sum(v for v, s in recent if s == 'BUY')   # short liquidated
        total = long_liqs + short_liqs
        if total == 0:
            return 0.0, None
        direction = 'DOWN' if long_liqs > short_liqs else 'UP'
        return total, direction

    def get_funding_rate(self) -> float:
        with self._funding_lock:
            return self._funding_rate

    def _run_ws(self):
        import websocket as _wslib
        delay = 2
        while self._running:
            try:
                ws = _wslib.WebSocketApp(
                    self.WS_URL,
                    on_message=self._on_liq,
                    on_open=lambda ws: logger.info(f'[{self._log}] liquidation feed connected'),
                    on_error=lambda ws, e: logger.debug(f'[{self._log}] error: {e}'),
                    on_close=lambda ws, c, m: logger.debug(f'[{self._log}] closed'),
                )
                ws.run_forever(ping_interval=25, ping_timeout=10)
                delay = min(delay * 2, 30)
            except Exception as e:
                logger.debug(f'[{self._log}] ws error: {e}')
            if self._running:
                time.sleep(delay)

    def _on_liq(self, ws, raw):
        try:
            d = json.loads(raw)
            o = d.get('o', d)   # forceOrder wraps in 'o'
            side = o.get('S', '')   # BUY=short liq, SELL=long liq
            qty  = float(o.get('q', 0))
            ap   = float(o.get('ap', 0) or o.get('p', 0))
            usd  = qty * ap
            if usd < 10_000:
                return   # ignore tiny liquidations
            now = time.time()
            with self._liq_lock:
                self._liqs.append((now, usd, side))
            # Check if cascade threshold crossed
            total, direction = self.get_liq_cascade()
            if total >= self.CASCADE_THRESH and direction:
                logger.info(f'[{self._log}] CASCADE {direction} ${total:,.0f} liquidated in {self.CASCADE_WINDOW}s')
                for cb in self._cascade_callbacks:
                    try:
                        cb(total, direction)
                    except Exception as e:
                        logger.debug(f'[{self._log}] cascade cb error: {e}')
        except Exception as e:
            logger.debug(f'[{self._log}] liq parse error: {e}')

    def _run_funding(self):
        """Poll funding rate every 30s via REST."""
        import requests as _req
        s = _req.Session()
        while self._running:
            try:
                r = s.get(self.FUNDING_URL, timeout=5)
                if r.status_code == 200:
                    rate = float(r.json().get('lastFundingRate', 0))
                    with self._funding_lock:
                        self._funding_rate = rate
            except Exception:
                pass
            time.sleep(30)

    def stop(self):
        self._running = False


class BinanceMultiAggTradeWS:
    """
    Lightweight multi-symbol Binance aggTrade feed for HFT triggering.
    Single WS connection covers multiple symbols. Fires registered callbacks
    on per-symbol price moves >= threshold so HFT can race into the lag window
    BEFORE Polymarket reprices.

    HYPE excluded — it's on Hyperliquid, not Binance.
    """
    DEFAULT_SYMBOLS = ['SOLUSDT', 'XRPUSDT', 'BNBUSDT', 'ETHUSDT', 'DOGEUSDT']

    def __init__(self, symbols=None, move_threshold: float = 0.0005):
        self.symbols = [s.upper() for s in (symbols or self.DEFAULT_SYMBOLS)]
        self._move_threshold = move_threshold
        streams = '/'.join(f'{s.lower()}@aggTrade' for s in self.symbols)
        self.WS_URL = f'wss://stream.binance.com:9443/stream?streams={streams}'
        self._ref_prices: dict = {}    # symbol -> reference price for threshold compute
        self._last_prices: dict = {}   # symbol -> last seen price
        self._callbacks: list = []
        self._lock = threading.Lock()
        self._running = True
        self._t = threading.Thread(
            target=self._run, daemon=True, name='binance-multi-aggtrade-ws')
        self._t.start()
        logger.info(f'[BinanceMultiWS] Started: {len(self.symbols)} symbols '
                    f'@ {move_threshold*100:.2f}% threshold')

    def register(self, cb):
        """Callback signature: cb(symbol, price, pct, direction)"""
        self._callbacks.append(cb)

    def get_last_price(self, symbol: str) -> Optional[float]:
        with self._lock:
            return self._last_prices.get(symbol.upper())

    def _run(self):
        import websocket as _wslib
        delay = 2
        while self._running:
            try:
                ws = _wslib.WebSocketApp(
                    self.WS_URL,
                    on_message=self._on_msg,
                    on_error=lambda ws, e: logger.debug(f'[BinanceMultiWS] error: {e}'),
                    on_open=lambda ws: logger.info(f'[BinanceMultiWS] connected ({len(self.symbols)} streams)'),
                    on_close=lambda ws, c, m: logger.debug('[BinanceMultiWS] closed'),
                )
                ws.run_forever(ping_interval=25, ping_timeout=10)
                delay = min(delay * 2, 30)
            except Exception as e:
                logger.debug(f'[BinanceMultiWS] run error: {e}')
            if self._running:
                time.sleep(delay)

    def _on_msg(self, ws, raw):
        try:
            outer = json.loads(raw)
            stream = outer.get('stream', '')
            d      = outer.get('data', outer)
            # Extract symbol from stream name (e.g. "solusdt@aggTrade" -> "SOLUSDT")
            sym = stream.split('@')[0].upper() if stream else d.get('s', '').upper()
            if not sym:
                return
            price = float(d.get('p', 0))
            if price <= 0:
                return
            with self._lock:
                self._last_prices[sym] = price
                ref = self._ref_prices.get(sym)
                if ref is None:
                    self._ref_prices[sym] = price
                    return
                pct = (price - ref) / ref
                if abs(pct) < self._move_threshold:
                    return
                direction = 'DOWN' if pct < 0 else 'UP'
                self._ref_prices[sym] = price
            for cb in self._callbacks:
                try:
                    cb(sym, price, pct, direction)
                except Exception as e:
                    logger.debug(f'[BinanceMultiWS] cb error: {e}')
        except Exception as e:
            logger.debug(f'[BinanceMultiWS] parse error: {e}')

    def stop(self):
        self._running = False


class OKXLiqWS:
    """
    OKX SWAP liquidation feed. Replacement for BinanceFuturesWS liquidation half —
    fstream.binance.com WebSocket is geo-blocked from Mexico/Canada VPN exits, but
    OKX's public WS is fully accessible. Verified Apr 2026 with parallel A/B test.

    Provides drop-in compatible API:
        get_liq_cascade() -> (usd_volume, direction)
        register_cascade(cb)        # cb(usd_volume, direction) on threshold crossing

    Cascade sizing tuned for OKX volume (lower than Binance):
        threshold $100k / 30s window  (vs Binance $300k / 5s)
    """
    WS_URL = 'wss://ws.okx.com:8443/ws/v5/public'
    CASCADE_THRESH = 100_000     # $100k window threshold (OKX has lower volume than Binance)
    CASCADE_WINDOW = 30.0        # 30s window — wider than Binance's 5s

    # OKX SWAP contract sizes — base currency units per contract.
    # Source: https://www.okx.com/api/v5/public/instruments?instType=SWAP (ctVal field)
    CONTRACT_SIZES = {
        'BTC-USDT-SWAP':  0.01,
        'ETH-USDT-SWAP':  0.1,
        'SOL-USDT-SWAP':  1.0,
        'XRP-USDT-SWAP':  100.0,
        'BNB-USDT-SWAP':  0.1,
        'DOGE-USDT-SWAP': 1000.0,
    }

    def __init__(self, instruments=None, primary_inst: str = 'BTC-USDT-SWAP'):
        from collections import deque as _dq
        self.instruments  = instruments or list(self.CONTRACT_SIZES.keys())
        self.primary_inst = primary_inst
        self._liqs: _dq   = _dq(maxlen=500)
        self._liq_lock    = threading.Lock()
        self._cascade_callbacks: list = []
        self._running     = True
        self._t = threading.Thread(target=self._run, daemon=True, name='okx-liq-ws')
        self._t.start()
        logger.info(f'[OKX-Liq] Started — SWAP liquidation feed '
                    f'(threshold ${self.CASCADE_THRESH:,}/{self.CASCADE_WINDOW:.0f}s on {primary_inst})')

    def register_cascade(self, cb):
        """Register cb(usd_volume, direction) — fired when cascade threshold crossed."""
        self._cascade_callbacks.append(cb)

    def get_liq_cascade(self) -> tuple:
        """Returns (usd_vol, direction) for primary_inst's last CASCADE_WINDOW seconds.
        Compatible with BinanceFuturesWS.get_liq_cascade()."""
        now = time.time()
        cutoff = now - self.CASCADE_WINDOW
        with self._liq_lock:
            recent = [(usd, side) for ts, usd, side, inst in self._liqs
                      if ts >= cutoff and inst == self.primary_inst]
        if not recent:
            return 0.0, None
        long_liqs  = sum(u for u, s in recent if s == 'sell')   # sell side = long position liquidated
        short_liqs = sum(u for u, s in recent if s == 'buy')    # buy side = short position liquidated
        total = long_liqs + short_liqs
        if total == 0:
            return 0.0, None
        direction = 'DOWN' if long_liqs > short_liqs else 'UP'
        return total, direction

    def _run(self):
        import websocket as _wslib
        delay = 2
        while self._running:
            try:
                ws = _wslib.WebSocketApp(
                    self.WS_URL,
                    on_open=self._on_open,
                    on_message=self._on_msg,
                    on_error=lambda ws, e: logger.debug(f'[OKX-Liq] error: {e}'),
                    on_close=lambda ws, c, m: logger.debug('[OKX-Liq] closed'),
                )
                ws.run_forever(ping_interval=25, ping_timeout=10)
                delay = min(delay * 2, 30)
            except Exception as e:
                logger.debug(f'[OKX-Liq] run error: {e}')
            if self._running:
                time.sleep(delay)

    def _on_open(self, ws):
        # OKX requires `instFamily` on liquidation-orders subscriptions. Without it,
        # the subscribe is acked but no data ever flows (verified by A/B test 2026-05-11).
        # Derive family from primary instrument: 'BTC-USDT-SWAP' -> 'BTC-USDT'.
        parts = self.primary_inst.split('-')
        inst_family = '-'.join(parts[:2]) if len(parts) >= 2 else self.primary_inst
        msg = {"op": "subscribe",
               "args": [{"channel": "liquidation-orders",
                         "instType": "SWAP",
                         "instFamily": inst_family}]}
        try:
            ws.send(json.dumps(msg))
            logger.info(f'[OKX-Liq] subscribed to SWAP liquidation-orders (instFamily={inst_family})')
        except Exception as e:
            logger.warning(f'[OKX-Liq] subscribe send failed: {e}')

    def _on_msg(self, ws, raw):
        try:
            d = json.loads(raw)
            if d.get('event') == 'subscribe':
                return
            if d.get('event') == 'error':
                logger.warning(f'[OKX-Liq] error event: {d}')
                return
            if d.get('arg', {}).get('channel') != 'liquidation-orders':
                return
            for entry in d.get('data', []):
                inst = entry.get('instId', '')
                if inst not in self.instruments:
                    continue
                ctval = self.CONTRACT_SIZES.get(inst)
                if not ctval:
                    continue
                for det in entry.get('details', []):
                    side = det.get('side', '')
                    try:
                        sz   = float(det.get('sz', 0))
                        bkPx = float(det.get('bkPx', 0) or det.get('px', 0))
                    except (TypeError, ValueError):
                        continue
                    if sz <= 0 or bkPx <= 0:
                        continue
                    usd = sz * ctval * bkPx
                    try:
                        ts_ms = float(det.get('ts', 0))
                    except (TypeError, ValueError):
                        ts_ms = 0
                    ts = ts_ms / 1000.0 if ts_ms > 1e10 else time.time()
                    with self._liq_lock:
                        self._liqs.append((ts, usd, side, inst))
                # Cascade threshold check is per primary_inst only
                if inst == self.primary_inst:
                    total, direction = self.get_liq_cascade()
                    if total >= self.CASCADE_THRESH and direction:
                        logger.info(f'[OKX-Liq] CASCADE {direction} ${total:,.0f} liquidated '
                                    f'in {self.CASCADE_WINDOW:.0f}s on {inst}')
                        for cb in self._cascade_callbacks:
                            try:
                                cb(total, direction)
                            except Exception as e:
                                logger.debug(f'[OKX-Liq] cb error: {e}')
        except Exception as e:
            logger.debug(f'[OKX-Liq] parse error: {e}')

    def stop(self):
        self._running = False


class BTCMLScanner:
    """
    Symbol-scoped ML-driven HFT scanner. Default symbol BTC; pass symbol='ETH'
    etc. for parallel scanners. Each instance owns its own Binance spot WS,
    Binance futures funding poll, OKX liquidation feed, model, RL gate, and
    paper trade log — all keyed by self.SYMBOL.

    Scans the symbol's 5m + 15m Polymarket markets every 8 seconds.
    Extracts 14 features from Binance 1m/5m candles + CLOB order book.
    Runs ML logistic regression → confidence gate → RL gate → paper entry.
    RL gating auto-enables after 50 resolved trades.
    """
    GAMMA    = "https://gamma-api.polymarket.com"
    BINANCE  = "https://api.binance.com/api/v3"
    LOG_MAX_ENTRIES = 50000  # disk-write cap per ML scanner. Async save worker
                             # keeps it off the hot path.
    PAPER_STAKE   = 5.0
    FEE_RATE      = 0.0   # 2026-05-10: confirmed 0% via Polymarket data API — was 0.02
    ML_PROB_THRESHOLD = 0.58   # min confidence to fire a signal
    # Scalping exit parameters — trade multiple times per bar.
    # When SCALP_EXITS_ENABLED is False, _check_scalp_exits records the FIRST would-be
    # TP/SL hit on each trade as shadow data (shadow_tp_*, shadow_sl_*) but does NOT
    # actually exit — trade runs to TIME_CLOSE for full payout/loss. The dashboard
    # then shows actual vs counterfactual scalp PnL so the methods can be A/B-compared.
    SCALP_EXITS_ENABLED = False
    TAKE_PROFIT_PCT  = 0.08   # threshold used for both real exits (when enabled) and shadow logging
    STOP_LOSS_PCT    = 0.25
    REENTRY_COOLDOWN = 90     # seconds before re-entering same market after TP exit (cap to ~2/candle)

    def __init__(self, symbol: str = 'BTC', bot_ref=None, clob_ws=None):
        self.SYMBOL  = symbol.upper()
        self._sym_lc = symbol.lower()
        self.LOG_FILE      = f'{self._sym_lc}_ml_trades.json'
        self.SETTINGS_FILE = f'{self._sym_lc}_ml_settings.json'
        self._log          = f'{self.SYMBOL}-ML'
        self.bot      = bot_ref
        self._clob_ws = clob_ws   # shared CLOBWebSocketFeed from HFTScanner
        self._trades: list  = []
        self._lock  = __import__('threading').Lock()
        # Async save worker — JSON serialization (~60ms for 2000-trade list) moved off
        # trade entry hot path. _request_save() puts a marker on this queue; worker
        # thread snapshots + writes. Mirrors HFTScanner.start_save_worker pattern.
        import queue as _queue
        self._save_queue: _queue.Queue = _queue.Queue(maxsize=1)  # bounded — coalesces requests
        self._save_thread: Optional[threading.Thread] = None
        self._scan_count    = 0
        self._last_scan_ts  = 0.0
        self._last_triggered_ts = 0.0  # rate-limit on event-driven scans
        self._meta_cache: dict = {}
        self._entered_keys: set = set()
        self._candle_cache: dict = {}
        self._book_cache: dict   = {}  # token_id -> (book_data, timestamp) — 1.5s TTL
        self._reentry_cooldown: dict = {}  # key -> exit_timestamp (seconds)
        self._session = __import__('requests').Session()
        self._session.headers.update({'Accept-Encoding': 'gzip'})
        # 2026-05-17 protection_override: blocks circuit-breaker auto-flips. Loaded from settings.
        self.protection_override: bool = False
        self.model = BTCMLModel(symbol=self.SYMBOL)
        self.rl    = BTCMLRl(symbol=self.SYMBOL)
        # 2026-05-20: shadow-to-RL feedback loop. When a blocked trade
        # resolves, feed its shadow_pnl back to the main gate at 0.3 weight
        # so blocked cells get fresh data instead of drifting on stale Q.
        # Bullish-filter records and other non-main-gate systems are ignored.
        _expected_rl_system = f'{self._sym_lc}_ml'
        def _on_shadow_resolve(record):
            if record.get('rl_system') != _expected_rl_system:
                return
            pnl   = record.get('shadow_pnl')
            entry = float(record.get('entry_price') or 0)
            secs  = float(record.get('secs_to_close') or 0)
            stake = float(record.get('stake') or 0)
            if pnl is None or entry <= 0 or stake <= 0:
                return
            try:
                self.rl.update(entry, secs, stake, pnl, weight=0.3)
            except Exception as _ue:
                logger.warning(f'[{self._log}-RL] shadow update error: {_ue}')
        self.rl_shadow = RLShadowLog(f'{self._sym_lc}_ml_rl_blocked.json',
                                     on_resolve=_on_shadow_resolve)
        self.live_mode: bool = False
        self.stake: float    = self.PAPER_STAKE
        # TP/SL config — disabled by default; per-symbol settings file enables.
        # When enabled, _track_price_path() polls token midpoint at 30s/60s/120s/180s
        # post-entry on real fill_confirmed trades and exits early at threshold hit.
        self.tp_sl_enabled: bool = False
        self.tp_pct: float = 0.30   # +30% move locks in profit
        self.sl_pct: float = -0.15  # -15% move cuts loss
        # 2026-05-23 hour-of-day blocklist. UTC hours (0-23) listed here are
        # shadow-blocked at scan time before the RL gate runs. Empty = no
        # filter. Per-symbol values in *_ml_settings.json. Default for BTC
        # picks the 4 worst UTC hours from 2026-05-23 cohort analysis
        # (avoided -$173/100 trades); ETH picks 13/16/17 (avoided -$73/100).
        self.blocked_hours: list = []
        # 2026-05-30 hour-block ENFORCEMENT toggle. When True (default) a blocked
        # hour is skipped (shadow-only). When False the gate is in TRAINING mode:
        # the would-be-blocked trade is STILL shadow-logged (so the blocked-cohort
        # evidence keeps accumulating) but ALSO fires for real/paper, so those hours
        # finally enter self._trades and feed model retraining — lets us train the
        # flagged hours faster. While False, auto-REVERT is frozen (see
        # _maybe_autoflip_blocked_hours) so the hours stay in the list and keep
        # shadow-logging instead of being auto-removed. Settable via *_ml_settings.json
        # / the ML tile toggle. Trades still honor live_mode when the gate is off.
        self.hour_block_enabled: bool = True
        # 2026-05-26 per-hour timestamp of when the block was added (str hr → ISO
        # timestamp). Used by _hour_block_shadow_summary to filter shadow entries
        # to FRESH ones since the block — without this filter, leftover shadow
        # from a previous block period gets picked up by auto-revert on the next
        # tick, causing whipsaw. Persisted in settings so a restart doesn't lose it.
        self._hour_block_added_at: dict = {}
        # 2026-05-25 auto-flip. Periodic sweep removes a hour from blocked_hours
        # if its shadow-cohort PnL turns net-positive with enough samples — so a
        # stale blocklist (regime shift since the hour was first added) self-heals
        # instead of silently bleeding gains. 2026-05-26 added bidirectional ADD
        # mirror; see _maybe_autoadd_blocked_hours. Per check uses
        # _hour_block_shadow_summary() (same numbers the UI tile shows).
        self.AUTOFLIP_ENABLED      = True
        self.AUTOFLIP_MIN_SAMPLES  = 20
        self.AUTOFLIP_MIN_AVG_PNL  = 0.30
        # 2026-05-27 cap on blocked_hours size. Auto-add bidirectional flip can fill
        # the blocklist quickly in a bleeding regime — BTC hit 14 hours, ETH 16,
        # essentially silencing the scanner. Cap limits growth and trims at startup.
        # 0 = uncapped (legacy behavior). Settable via *_ml_settings.json.
        self.max_blocked_hours: int = 8
        # 2026-05-23 volatility gate. Skip entries where ml_features[7] (volatility)
        # exceeds this threshold. 0 = disabled (default — non-monotonic vol patterns
        # like BTC-ML's don't benefit from a flat cap). ETH-ML enabled at 0.06 based
        # on cohort analysis: edge flips from +8% avg (band 0.02-0.04) to -10% (0.06-0.08)
        # to -54% (0.10-0.15). Saves ~-$130 over the historical bleed bands at full stake.
        self.max_volatility: float = 0.0
        # 2026-05-27 volume-spike band gate. Skip entries where ml_features[2]
        # (volume_spike) falls in [block_lo, block_hi). Per-symbol patterns differ:
        #   BTC: spikes are reactive (liq cascades, news) — WR drops from 72.5% to
        #        57.3% as spike rises. Set block_lo=0, block_hi=999 to block all
        #        above-average-volume entries (16% volume cut, +1pp WR, +$343 lifetime).
        #   ETH: U-shaped — calm AND large spikes profitable, middle band bleeds.
        #        Set block_lo=-0.5, block_hi=0.5 (middle band block, 31% cut,
        #        +1pp WR, +$682 lifetime, robust on 7d/OOS).
        # Disabled when block_lo == block_hi. Hot-reloaded from settings file.
        self.volume_spike_block_lo: float = 0.0
        self.volume_spike_block_hi: float = 0.0
        # 2026-05-28 skip_directions gate. Directions here (e.g. ["UP"]) are
        # shadow-blocked, not entered. ML deepdive 5/20: UP bleeds both feeds
        # (BTC-ML UP -$216, ETH-ML UP -$396); DOWN carries P&L. Hot-reloaded.
        self.skip_directions: list = []
        # 2026-05-29 max_entry_price gate. Skip+shadow-log entries priced at or
        # above this (0.0 = disabled). ML deepdive 5/29: the 0.70+ favorite bucket
        # is 1442 trades / -$274 at 69% WR — high win rate, negative EV. Capping at
        # 0.70 lifts EV/trade $0.033 -> $0.263 (+$97 -> +$375). Hot-reloaded.
        self.max_entry_price: float = 0.0
        self._last_prediction: dict = {}
        self._cascade_signal: dict  = {}   # set by _on_liq_cascade, consumed by scan_once
        # Background market cache — refreshed every 3s so scan_once never hits Gamma
        self._market_bg_cache: list = []
        self._market_bg_lock  = __import__('threading').Lock()
        # Event-driven scanning: set by BinancePriceWS callback
        self._scan_event = __import__('threading').Event()
        self._load_settings()
        self._load_log()
        # Retrain model from existing resolved trades on startup (so restarts don't lose the model).
        # During weekend mode, retrain_from_log internally filters to weekend-window trades only —
        # weekend ML weights start at zero and learn from weekend data as it accumulates.
        _resolved_on_load = [t for t in self._trades
                             if t.get('resolved') and t.get('outcome') in ('WIN', 'LOSS')]
        if len(_resolved_on_load) >= self.model.MIN_TRAIN_N:
            try:
                result = self.model.retrain_from_log(self._trades)
                logger.info(f'[{self._log}] Startup retrain: {result}')
            except Exception as _e:
                logger.warning(f'[{self._log}] Startup retrain error: {_e}')
        # Re-seed entered_keys from pending trades
        for t in self._trades:
            if not t.get('resolved'):
                self._entered_keys.add(
                    f"{t.get('market_slug','')}_{t.get('direction','')}")
        # Start Binance spot stream — aggTrade triggers + live kline + depth imbalance
        self._binance_ws = BinancePriceWS(move_threshold=0.0010, symbol=self.SYMBOL)
        self._binance_ws.register(self._on_price_move)
        # Start Binance futures stream — KEPT for funding rate REST poll only.
        # The fstream.binance.com WebSocket (liquidations, futures aggTrade) is geo-blocked
        # from Mexico/Canada VPN exits — verified zero messages over 180s parallel test.
        # Liquidation cascade signal now comes from OKX (below).
        self._futures_ws = BinanceFuturesWS(symbol=self.SYMBOL)
        # Liquidation cascade source — OKX SWAP feed. Drop-in API-compatible with BinanceFuturesWS.
        self._okx_liq_ws = OKXLiqWS(primary_inst=f'{self.SYMBOL}-USDT-SWAP')
        self._okx_liq_ws.register_cascade(self._on_liq_cascade)
        # Start background market cache thread
        _mt = __import__('threading').Thread(
            target=self._market_refresh_loop, daemon=True,
            name=f'{self._sym_lc}-market-cache')
        _mt.start()

    def _on_price_move(self, price: float, pct: float, direction: str):
        """Called by BinancePriceWS on price moves >= 0.10%. Wake scan loop immediately."""
        self._scan_event.set()

    # Back-compat alias for callers that still reference _on_btc_move
    _on_btc_move = _on_price_move

    def _on_liq_cascade(self, usd_volume: float, direction: str):
        """
        Called by BinanceFuturesWS when $300k+ liquidated in 5s.
        Highest-confidence signal: forced unwinds create violent, predictable moves.
        Injects a cascade override so scan_once skips the normal 0.58 ML gate.
        """
        self._cascade_signal = {
            'direction': direction,
            'usd_volume': usd_volume,
            'ts': time.time(),
            'prob': min(0.92, 0.75 + usd_volume / 2_000_000),  # scales with cascade size
        }
        self._scan_event.set()
        logger.info(f'[{self._log}] CASCADE SIGNAL {direction} ${usd_volume:,.0f} — '
                    f'override prob={self._cascade_signal["prob"]:.3f}')

    def _market_refresh_loop(self):
        """Background thread: refreshes active BTC market list every 3s.
        scan_once() reads from _market_bg_cache instead of hitting Gamma per-scan."""
        import time as _t
        _t.sleep(3)   # let init finish first
        while True:
            try:
                fresh = self._fetch_active_markets()
                with self._market_bg_lock:
                    self._market_bg_cache = fresh
            except Exception as e:
                logger.debug(f'[{self._log}] Market cache refresh error: {e}')
            _t.sleep(3)

    # ── persistence ───────────────────────────────────────────────────────────

    def _load_log(self):
        path = _resolve_state_path(self.LOG_FILE)
        try:
            if os.path.exists(path):
                # 2026-05-23 PR-5 fix: utf-8 for orjson-written files
                with open(path, 'r', encoding='utf-8') as f:
                    self._trades = json.load(f)
                logger.info(f'[{self._log}] Loaded {len(self._trades)} trades from {os.path.basename(path)}')
        except Exception:
            self._trades = []

    def _save_log(self):
        """Save trades to disk. Delegates to async worker (~1ms) when running,
        falls back to synchronous serialization (~60ms for 2000 trades) before worker starts."""
        if self._save_thread and self._save_thread.is_alive():
            self._request_save()
            return
        # Synchronous fallback — used during __init__ and before start_save_worker()
        path = _resolve_state_path(self.LOG_FILE)
        try:
            # 2026-05-23 PR-5: orjson-backed atomic write
            _atomic_write_json(path, self._trades[-self.LOG_MAX_ENTRIES:], indent=False)
        except Exception as e:
            logger.warning(f'[{self._log}] Log save error: {e}')

    def start_save_worker(self):
        """Start background thread that performs trade log saves off the hot path.
        Trade entry calls _request_save() which is ~1ms (queue put + lock copy);
        actual JSON serialization (~60ms for 2000-trade list) happens here."""
        import threading as _th
        if self._save_thread and self._save_thread.is_alive():
            return
        self._save_thread = _th.Thread(
            target=self._save_worker, daemon=True,
            name=f'{self._sym_lc}-ml-save')
        self._save_thread.start()
        logger.info(f'[{self._log}] Async save worker started')

    def _request_save(self):
        """Mark save as needed. No-op if a save is already pending (coalesces bursts)."""
        try:
            self._save_queue.put_nowait(True)
        except Exception:
            pass  # queue full = save already pending

    def _save_worker(self):
        """Snapshot _trades under lock, serialize and write outside lock."""
        while True:
            try:
                self._save_queue.get()  # blocks until save requested
                with self._lock:
                    snapshot = list(self._trades[-self.LOG_MAX_ENTRIES:])
                path = _resolve_state_path(self.LOG_FILE)
                # 2026-05-23 PR-5: orjson-backed atomic write
                _atomic_write_json(path, snapshot, indent=False)
            except Exception as e:
                logger.warning(f'[{self._log}] Async save error: {e}')

    def _load_settings(self):
        path = _resolve_state_path(self.SETTINGS_FILE)
        try:
            if os.path.exists(path):
                with open(path, 'r') as f:
                    d = json.load(f)
                self.live_mode = bool(d.get('live_mode', False))
                self.stake     = float(d.get('stake', self.PAPER_STAKE))
                self.tp_sl_enabled = bool(d.get('tp_sl_enabled', False))
                self.tp_pct        = float(d.get('tp_pct', 0.30))
                self.sl_pct        = float(d.get('sl_pct', -0.15))
                # 2026-05-17: protection_override bypasses circuit-breaker auto-flips so user-set
                # live_mode is sticky. Default off.
                self.protection_override = bool(d.get('protection_override', False))
                # 2026-05-20: per-instance SCALP_EXITS_ENABLED override. Class default is False
                # (paper trades run to time-close). Shadow A/B over 5/3-5/20 showed BTC-ML
                # benefits (+$210 counterfactual) while ETH-ML hurts (-$172) — flag must be
                # per-symbol. Absent setting => class default => paper time-close behavior.
                if 'scalp_exits_enabled' in d:
                    self.SCALP_EXITS_ENABLED = bool(d['scalp_exits_enabled'])
                # 2026-05-18: per-symbol RL skip_threshold. Without this, BTC-ML and ETH-ML share the
                # BTCMLRl class-level SKIP_THRESHOLD (-0.30). Setting this per-settings-file lets each
                # symbol tune its own gate independently. Falls back to class default when absent.
                if 'skip_threshold' in d and hasattr(self, 'rl') and self.rl is not None:
                    try:
                        new_t = float(d['skip_threshold'])
                        if self.rl.SKIP_THRESHOLD != new_t:
                            self.rl.SKIP_THRESHOLD = new_t
                            logger.info(f'[{self._log}-RL] skip_threshold set to {new_t:+.3f} from settings')
                    except (TypeError, ValueError):
                        pass
                # 2026-05-23: blocked_hours filter. UTC hours (0-23) where this scanner
                # will shadow-block instead of entering. See __init__ for derivation.
                if 'blocked_hours' in d:
                    try:
                        bh = d.get('blocked_hours') or []
                        if isinstance(bh, list):
                            self.blocked_hours = sorted({int(h) for h in bh if 0 <= int(h) <= 23})
                    except (TypeError, ValueError):
                        self.blocked_hours = []
                # 2026-05-30: hour-block enforcement toggle. Missing key = enforced
                # (True), preserving legacy behavior for older snapshots.
                if 'hour_block_enabled' in d:
                    self.hour_block_enabled = bool(d.get('hour_block_enabled', True))
                # 2026-05-26: per-hour block_added_at timestamps. Tolerant of
                # missing key (older snapshots) and missing entries (older blocks
                # set before this field existed). Missing entries for currently-
                # blocked hours get stamped NOW (migration) so a restart doesn't
                # cause auto-revert to fire on stale shadow.
                ba = d.get('block_added_at')
                if isinstance(ba, dict):
                    self._hour_block_added_at = {str(k): str(v) for k, v in ba.items()
                                                  if v}
                else:
                    self._hour_block_added_at = {}
                _migrate_ts = datetime.now(timezone.utc).isoformat()
                _migrated = False
                for _h in (self.blocked_hours or []):
                    if str(_h) not in self._hour_block_added_at:
                        self._hour_block_added_at[str(_h)] = _migrate_ts
                        _migrated = True
                if _migrated:
                    try: self._save_settings()
                    except Exception: pass
                # 2026-05-23: max_volatility gate. Skip when features[7] > threshold.
                if 'max_volatility' in d:
                    try:
                        mv = float(d.get('max_volatility') or 0.0)
                        self.max_volatility = max(0.0, mv)
                    except (TypeError, ValueError):
                        self.max_volatility = 0.0
                # 2026-05-29: max_entry_price gate. Skip when entry_price >= cap.
                if 'max_entry_price' in d:
                    try:
                        mep = float(d.get('max_entry_price') or 0.0)
                        self.max_entry_price = min(1.0, max(0.0, mep))
                    except (TypeError, ValueError):
                        self.max_entry_price = 0.0
                # 2026-05-27 volume-spike band gate.
                try:
                    self.volume_spike_block_lo = float(d.get('volume_spike_block_lo') or 0.0)
                    self.volume_spike_block_hi = float(d.get('volume_spike_block_hi') or 0.0)
                except (TypeError, ValueError):
                    self.volume_spike_block_lo = 0.0
                    self.volume_spike_block_hi = 0.0
                # 2026-05-28 skip_directions gate (hot-reloaded). ["UP"] = DOWN-only.
                try:
                    _sd = d.get('skip_directions') or []
                    self.skip_directions = [str(x).upper() for x in _sd
                                            if str(x).upper() in ('UP', 'DOWN')]
                except (TypeError, ValueError):
                    self.skip_directions = []
                # 2026-05-27 cap on blocked_hours length.
                try:
                    _mb = d.get('max_blocked_hours')
                    if _mb is not None:
                        self.max_blocked_hours = max(0, int(_mb))
                except (TypeError, ValueError):
                    pass
                logger.info(f'[{self._log}] Loaded settings from {os.path.basename(path)} protection_override={self.protection_override} skip_threshold={getattr(self.rl, "SKIP_THRESHOLD", "?")} blocked_hours={self.blocked_hours} max_volatility={self.max_volatility}')
        except Exception:
            pass

    def _save_settings(self):
        path = _resolve_state_path(self.SETTINGS_FILE)
        tmp  = path + f'.tmp_{os.getpid()}'
        try:
            with open(tmp, 'w') as f:
                json.dump({
                    'live_mode': self.live_mode,
                    'stake': self.stake,
                    'tp_sl_enabled': self.tp_sl_enabled,
                    'tp_pct': self.tp_pct,
                    'sl_pct': self.sl_pct,
                    'protection_override': bool(getattr(self, 'protection_override', False)),
                    'skip_threshold': float(getattr(getattr(self, 'rl', None), 'SKIP_THRESHOLD', -0.30)),
                    'scalp_exits_enabled': bool(getattr(self, 'SCALP_EXITS_ENABLED', False)),
                    'blocked_hours': list(getattr(self, 'blocked_hours', []) or []),
                    'hour_block_enabled': bool(getattr(self, 'hour_block_enabled', True)),
                    'block_added_at': dict(getattr(self, '_hour_block_added_at', {}) or {}),
                    'max_volatility': float(getattr(self, 'max_volatility', 0.0) or 0.0),
                    'volume_spike_block_lo': float(getattr(self, 'volume_spike_block_lo', 0.0) or 0.0),
                    'volume_spike_block_hi': float(getattr(self, 'volume_spike_block_hi', 0.0) or 0.0),
                    'max_blocked_hours': int(getattr(self, 'max_blocked_hours', 0) or 0),
                    'skip_directions': list(getattr(self, 'skip_directions', []) or []),
                    'max_entry_price': float(getattr(self, 'max_entry_price', 0.0) or 0.0),
                }, f)
            os.replace(tmp, path)
        except Exception as e:
            logger.warning(f'[{self._log}] Settings save error: {e}')
            try: os.remove(tmp)
            except OSError: pass

    def _stamp_block_adds(self, old_hours, new_hours) -> None:
        # Stamp `block_added_at[str(hr)]` for hours present in new_hours but not
        # in old_hours. Called from auto-add and from the UI POST endpoint so any
        # path that adds a block records its add-timestamp. Existing entries are
        # NOT overwritten (so a manual re-block of a hour that was just blocked
        # by auto-add doesn't reset its settling clock).
        old_set = set(int(h) for h in (old_hours or []))
        new_set = set(int(h) for h in (new_hours or []))
        added = new_set - old_set
        if not added:
            return
        ts = datetime.now(timezone.utc).isoformat()
        if not isinstance(getattr(self, '_hour_block_added_at', None), dict):
            self._hour_block_added_at = {}
        for hr in added:
            self._hour_block_added_at.setdefault(str(hr), ts)
        # Optional cleanup: drop entries for hours no longer blocked (keeps file tidy)
        removed = old_set - new_set
        for hr in removed:
            self._hour_block_added_at.pop(str(hr), None)

    # ── hour-block shadow aggregation + auto-flip ──────────────────────────
    def _hour_block_shadow_summary(self) -> dict:
        # Per-hour {wins, losses, pending, pnl, wr, n_resolved} for currently
        # blocked hours. Deduped by (market_slug, direction) — the scanner re-logs
        # each block on every scan tick, inflating raw counts ~15-17x. Reverted
        # hours are excluded so we don't surface stale evidence. Shared by
        # /api/{sym}-ml-state and _maybe_autoflip_blocked_hours.
        try:
            shadow_trades = list(self.rl_shadow._trades)
        except Exception:
            shadow_trades = []
        sys_key = f'{self._sym_lc}_ml_hour_block'
        raw = [t for t in shadow_trades if t.get('rl_system') == sys_key]
        seen: set = set()
        uniq: list = []
        for t in raw:
            k = (t.get('market_slug'), t.get('direction'))
            if k in seen:
                continue
            seen.add(k)
            uniq.append(t)
        blocked_now = set(self.blocked_hours or [])
        visible_keys = {f'HR_{h:02d}' for h in blocked_now}
        uniq = [t for t in uniq if t.get('rl_state_key') in visible_keys]
        # 2026-05-26: filter shadow entries to FRESH ones since the most recent
        # block-add for each hour. Without this, leftover shadow from a previous
        # block-revert-reblock cycle gets counted, and auto-revert fires on stale
        # "this hour is fine" data immediately after auto-add. The cutoff comes
        # from _hour_block_added_at (persisted in settings).
        ba = getattr(self, '_hour_block_added_at', {}) or {}
        if ba:
            def _fresh(t):
                key = t.get('rl_state_key', '')
                if not key.startswith('HR_'):
                    return True
                try:
                    hr = int(key[3:])
                except ValueError:
                    return True
                cutoff = ba.get(str(hr))
                if not cutoff:
                    return True
                return (t.get('logged_at') or '') >= cutoff
            uniq = [t for t in uniq if _fresh(t)]
        from collections import defaultdict as _dd
        per_hr: dict = _dd(lambda: {'wins': 0, 'losses': 0, 'pending': 0, 'pnl': 0.0})
        for t in uniq:
            k = t.get('rl_state_key', '')
            if not t.get('resolved'):
                per_hr[k]['pending'] += 1
                continue
            if t.get('outcome') == 'WIN':
                per_hr[k]['wins'] += 1
            elif t.get('outcome') == 'LOSS':
                per_hr[k]['losses'] += 1
            per_hr[k]['pnl'] += t.get('shadow_pnl') or 0
        return {
            k: {**v, 'pnl': round(v['pnl'], 2),
                'wr': (round(v['wins'] / (v['wins'] + v['losses']) * 100, 1)
                       if (v['wins'] + v['losses']) else None)}
            for k, v in per_hr.items()
        }

    def _maybe_autoflip_blocked_hours(self) -> None:
        # Revert: drop a hour from blocked_hours when its shadow cohort has turned
        # net-positive AND the live 7d cohort no longer says it bleeds. Self-heals
        # stale entries from regime shifts without thrashing against auto-add — both
        # now consult _live_7d_hour_summary, so they can't fight over a contested
        # hour every tick. Never auto-adds (that stays in _maybe_autoadd).
        # 2026-05-30: when the enforcement gate is OFF (training mode) freeze
        # auto-revert. Shadow logging only fires while a hour is in blocked_hours
        # (see scan-loop gate), so letting auto-revert remove hours here would
        # silently stop the shadow log the user explicitly wants to keep running.
        # Auto-ADD is intentionally NOT frozen — it only grows the list, never
        # stops a shadow log.
        if not getattr(self, 'hour_block_enabled', True):
            return
        if not (getattr(self, 'AUTOFLIP_ENABLED', False) and self.blocked_hours):
            return
        try:
            by_hr = self._hour_block_shadow_summary()
        except Exception as e:
            logger.debug(f'[{self._log}-AUTOFLIP] summary error: {e}')
            return
        # REVERT veto window. ETH shadow runs systematically optimistic vs live
        # (14/18 hrs, 2026-06-08), so its shadow-driven revert unblocks genuinely-
        # bad low-volume hours (e.g. hr18/21) whenever the 7d live veto can't reach
        # n>=AUTOFLIP_MIN_SAMPLES. Use a longer (but finite) veto window for ETH so
        # those bleeders stay blocked; samples still age out -> ~monthly re-test,
        # self-healing preserved. BTC shadow~=live (no bias) -> keep 7d. ADD is
        # unaffected (calls _live_7d_hour_summary() with the 7d default).
        _veto_days = 30 if getattr(self, '_sym_lc', '') == 'eth' else 7
        live = self._live_7d_hour_summary(days=_veto_days)
        to_revert = []
        for hr in list(self.blocked_hours):
            rec = by_hr.get(f'HR_{hr:02d}')
            if not rec:
                continue
            n = rec['wins'] + rec['losses']
            if n < self.AUTOFLIP_MIN_SAMPLES:
                continue
            avg = rec['pnl'] / n
            if rec['pnl'] > 0 and avg >= self.AUTOFLIP_MIN_AVG_PNL:
                # Cross-check live money before unblocking. Shadow is counterfactual;
                # the live 7d cohort is real fills. When they disagree (shadow "fine",
                # live still bleeds), trust live and hold the block — this is what
                # stops the every-tick revert/add oscillation. Once the pre-block live
                # trades age past 7d the hour's live samples fall below MIN and shadow
                # is free to revert it (a deliberate weekly re-test, not a thrash).
                lv = live.get(hr)
                if lv and lv['n'] >= self.AUTOFLIP_MIN_SAMPLES and lv['avg'] <= -self.AUTOFLIP_MIN_AVG_PNL:
                    logger.info(f'[{self._log}-AUTOFLIP] hr {hr} UTC shadow+ '
                                f'(avg={avg:+.3f}) but live {_veto_days}d still bleeds '
                                f'(avg={lv["avg"]:+.3f} n={lv["n"]}) — holding block')
                    continue
                to_revert.append({'hr': hr, 'n': n, 'pnl': rec['pnl'],
                                  'avg': round(avg, 3), 'wr': rec.get('wr')})
        if not to_revert:
            return
        flipped = {x['hr'] for x in to_revert}
        old_list = list(self.blocked_hours)
        new_list = [h for h in self.blocked_hours if h not in flipped]
        self.blocked_hours = new_list
        try:
            self._save_settings()
        except Exception as e:
            logger.warning(f'[{self._log}-AUTOFLIP] save_settings error: {e}')
            self.blocked_hours = old_list
            return
        for r in to_revert:
            logger.info(
                f"[{self._log}-AUTOFLIP] reverted hr {r['hr']} UTC: "
                f"n={r['n']} pnl=${r['pnl']:+.2f} avg={r['avg']:+.3f} WR={r['wr']}%"
            )
        self._append_autoflip_audit(old_list, new_list, to_revert)

    def _append_autoflip_audit(self, old_list: list, new_list: list, reverted: list,
                                added: list = None) -> None:
        # Audit trail of auto-flips. Weekend variant routed via _resolve_state_path.
        # Append-only JSON list; tolerant of corrupt/missing file.
        path = _resolve_state_path(f'{self._sym_lc}_ml_autoflip.json')
        try:
            try:
                with open(path, 'r') as f:
                    log = json.load(f)
                if not isinstance(log, list):
                    log = []
            except (FileNotFoundError, json.JSONDecodeError):
                log = []
            log.append({
                'ts': datetime.now(timezone.utc).isoformat(),
                'symbol': self.SYMBOL,
                'old_blocked': old_list,
                'new_blocked': new_list,
                'reverted': reverted,
                'added':    added or [],
                'min_samples': self.AUTOFLIP_MIN_SAMPLES,
                'min_avg_pnl': self.AUTOFLIP_MIN_AVG_PNL,
            })
            tmp = path + f'.tmp_{os.getpid()}'
            with open(tmp, 'w') as f:
                json.dump(log, f, indent=2)
            os.replace(tmp, path)
        except Exception as e:
            logger.warning(f'[{self._log}-AUTOFLIP] audit write error: {e}')

    def _trim_blocked_hours_to_cap(self) -> None:
        # If blocked_hours exceeds max_blocked_hours, evict the BEST-performing
        # blocked hours (least-negative 7d avg) until at cap. Hours with no 7d
        # data are kept (we don't have evidence they recovered). Symmetric to
        # _maybe_autoadd's metric so cap behavior is consistent with growth rule.
        cap = int(getattr(self, 'max_blocked_hours', 0) or 0)
        if cap <= 0:
            return
        cur = list(self.blocked_hours or [])
        if len(cur) <= cap:
            return
        # Compute per-hour 7d avg PnL (same window as _maybe_autoadd)
        from datetime import timedelta
        from collections import defaultdict as _dd
        cutoff = (datetime.now(timezone.utc) - timedelta(days=7)).isoformat()
        try:
            recent = [t for t in self._trades
                      if t.get('resolved')
                      and t.get('outcome') in ('WIN', 'LOSS')
                      and not t.get('rl_system')
                      and (t.get('logged_at') or '') >= cutoff]
        except Exception as e:
            logger.debug(f'[{self._log}-TRIM] window error: {e}')
            return
        per_hr = _dd(lambda: {'n': 0, 'pnl': 0.0})
        for t in recent:
            hr = t.get('fill_hour')
            if hr is None:
                continue
            per_hr[hr]['n']   += 1
            per_hr[hr]['pnl'] += (t.get('pnl') or t.get('paper_pnl') or 0)
        # Score each currently-blocked hour. Hours with no recent data score
        # -inf (kept) — we don't have evidence they recovered. Hours WITH data
        # score by avg PnL (more negative = worse = keep).
        scored = []
        for hr in cur:
            d = per_hr.get(hr) or {}
            n = d.get('n', 0)
            if n == 0:
                avg = float('-inf')  # no data = keep blocked
            else:
                avg = d['pnl'] / n
            scored.append((hr, avg, n))
        # Sort ascending by avg — worst first. Keep first `cap`.
        scored.sort(key=lambda x: x[1])
        keep = sorted(int(s[0]) for s in scored[:cap])
        evict = sorted(int(s[0]) for s in scored[cap:])
        if not evict:
            return
        old_list = list(self.blocked_hours)
        self.blocked_hours = keep
        # Drop block_added_at entries for evicted hours
        if isinstance(getattr(self, '_hour_block_added_at', None), dict):
            for hr in evict:
                self._hour_block_added_at.pop(str(hr), None)
        try:
            self._save_settings()
        except Exception as e:
            logger.warning(f'[{self._log}-TRIM] save_settings error: {e}')
            self.blocked_hours = old_list
            return
        logger.info(
            f"[{self._log}-TRIM] evicted hrs {evict} from blocked_hours "
            f"(cap={cap}, was {len(old_list)} now {len(keep)})"
        )
        # Audit trail under the existing autoflip log (set added=[], reverted=evicted-with-flag)
        try:
            evicted_records = []
            for hr in evict:
                d = per_hr.get(hr) or {}
                n = d.get('n', 0)
                evicted_records.append({
                    'hr': hr, 'n': n,
                    'pnl': round(d.get('pnl', 0.0), 2),
                    'avg': round(d['pnl'] / n, 3) if n else None,
                    'wr': None,
                    'reason': 'cap-trim',
                })
            self._append_autoflip_audit(old_list, keep, evicted_records, added=[])
        except Exception as _ae:
            logger.debug(f'[{self._log}-TRIM] audit error: {_ae}')

    def _live_7d_hour_summary(self, days: int = 7) -> dict:
        # Per-hour {wins,losses,pnl,n,avg} from the LIVE (allowed, non-shadow)
        # cohort over a rolling `days`-day window (default 7), keyed by fill_hour.
        # 2026-06-08: `days` parameterized so the REVERT veto can use a longer
        # window for ETH (systematic shadow-optimism) while ADD stays 7d. Shared by
        # auto-ADD (block an hour that bleeds) and auto-REVERT (refuse to unblock
        # an hour live money still says bleeds). Both controllers judging the same
        # ground-truth source is what stops the revert/add thrash — shadow alone
        # could exonerate an hour the live cohort is losing on.
        from datetime import timedelta
        from collections import defaultdict as _dd
        cutoff = (datetime.now(timezone.utc) - timedelta(days=days)).isoformat()
        per_hr = _dd(lambda: {'wins': 0, 'losses': 0, 'pnl': 0.0})
        try:
            # Live cohort = rl_system not set (blocked-shadow entries live in
            # *_ml_rl_blocked.json, not self._trades).
            recent = [t for t in self._trades
                      if t.get('resolved')
                      and t.get('outcome') in ('WIN', 'LOSS')
                      and not t.get('rl_system')
                      and (t.get('logged_at') or '') >= cutoff]
        except Exception as e:
            logger.debug(f'[{self._log}-AUTOADD] window error: {e}')
            return {}
        for t in recent:
            hr = t.get('fill_hour')
            if hr is None:
                continue
            if t.get('outcome') == 'WIN':
                per_hr[hr]['wins'] += 1
            else:
                per_hr[hr]['losses'] += 1
            per_hr[hr]['pnl'] += (t.get('pnl') or t.get('paper_pnl') or 0)
        return {hr: {**d, 'n': d['wins'] + d['losses'],
                     'avg': (d['pnl'] / (d['wins'] + d['losses'])
                             if (d['wins'] + d['losses']) else 0.0)}
                for hr, d in per_hr.items()}

    def _maybe_autoadd_blocked_hours(self) -> None:
        # Symmetric ADD: block a hour when the live (allowed) 7d cohort shows
        # net-negative PnL with enough samples. Mirrors _maybe_autoflip_blocked_hours
        # (sign-flipped) and shares _live_7d_hour_summary with REVERT's live
        # cross-check, so the two can't fight over a contested hour.
        if not getattr(self, 'AUTOFLIP_ENABLED', False):
            return
        # 2026-05-27 cap. When blocked_hours length >= max_blocked_hours, ADD is
        # silenced. Existing blocks stay; auto-revert (uncapped) can still free
        # slots as shadow data accumulates. 0 = uncapped (legacy behavior).
        _cap = int(getattr(self, 'max_blocked_hours', 0) or 0)
        if _cap > 0 and len(self.blocked_hours or []) >= _cap:
            return
        live = self._live_7d_hour_summary()
        blocked_now = set(self.blocked_hours or [])
        to_add = []
        for hr in range(24):
            if hr in blocked_now:
                continue
            d = live.get(hr)
            if not d or d['n'] < self.AUTOFLIP_MIN_SAMPLES:
                continue
            if d['pnl'] < 0 and d['avg'] <= -self.AUTOFLIP_MIN_AVG_PNL:
                wr = round(d['wins'] / d['n'] * 100, 1)
                to_add.append({'hr': hr, 'n': d['n'], 'pnl': round(d['pnl'], 2),
                               'avg': round(d['avg'], 3), 'wr': wr})
        if not to_add:
            return
        # Cap at 1 hour per tick. Worst-first (most-negative avg). Reasoning: a
        # bad ADD takes the form of silent lost opportunity (slow feedback);
        # blocking many at once on a single 7-day snapshot trades safety for
        # speed. After each tick the next 75-scan window re-evaluates the
        # remaining hours against the new blocked set — so a sustained bad
        # regime fills the blocklist over a few ticks instead of one slam.
        # REVERT stays uncapped (visible PnL feedback if wrong → fast to fix).
        to_add.sort(key=lambda r: r['avg'])
        queued_summary = ', '.join(f"hr{r['hr']:02d}({r['avg']:+.2f})" for r in to_add)
        chosen = to_add[:1]
        added_hrs = {x['hr'] for x in chosen}
        old_list = list(self.blocked_hours)
        new_list = sorted(set(self.blocked_hours) | added_hrs)
        self.blocked_hours = new_list
        self._stamp_block_adds(old_list, new_list)
        try:
            self._save_settings()
        except Exception as e:
            logger.warning(f'[{self._log}-AUTOADD] save_settings error: {e}')
            self.blocked_hours = old_list
            return
        for r in chosen:
            logger.info(
                f"[{self._log}-AUTOADD] added hr {r['hr']} UTC (worst of {len(to_add)}): "
                f"n={r['n']} pnl=${r['pnl']:+.2f} avg={r['avg']:+.3f} WR={r['wr']}% "
                f"| queued behind: {queued_summary}"
            )
        self._append_autoflip_audit(old_list, new_list, [], added=chosen)

    # ── market discovery (BTC-only, adapted from HFTScanner) ─────────────────

    @staticmethod
    def _current_5m_ts() -> int:
        from datetime import timezone as _tz
        now = datetime.now(_tz.utc)
        return int(now.replace(minute=(now.minute // 5) * 5, second=0, microsecond=0).timestamp())

    @staticmethod
    def _current_15m_ts() -> int:
        from datetime import timezone as _tz
        now = datetime.now(_tz.utc)
        return int(now.replace(minute=(now.minute // 15) * 15, second=0, microsecond=0).timestamp())

    def _probe_slug(self, slug: str, end_ts: float) -> Optional[dict]:
        if slug in self._meta_cache:
            return self._meta_cache[slug]
        try:
            r = self._session.get(
                f"{self.GAMMA}/events", params={'slug': slug}, timeout=4)
            if r.status_code != 200:
                return None
            data = r.json()
            if not isinstance(data, list) or not data:
                return None
            event = data[0]
            mkt   = event.get('markets', [{}])[0] if event.get('markets') else {}
            if not mkt:
                return None
            token_ids = mkt.get('clobTokenIds', [])
            if isinstance(token_ids, str):
                token_ids = json.loads(token_ids)
            entry = {
                'slug': slug, '_symbol': self.SYMBOL, 'end_ts': end_ts,
                'tokens': token_ids,
                'outcomePrices': mkt.get('outcomePrices', []),
                'active': mkt.get('active', True),
                'closed': mkt.get('closed', False),
            }
            self._meta_cache[slug] = entry
            return entry
        except Exception as e:
            logger.debug(f'[{self._log}] Probe {slug}: {e}')
            return None

    def _fetch_active_markets(self) -> list:
        from concurrent.futures import ThreadPoolExecutor, as_completed
        now_ts = time.time()
        # Purge stale cache
        stale = [s for s, m in self._meta_cache.items() if m['end_ts'] < now_ts - 60]
        for s in stale:
            del self._meta_cache[s]

        sym = self.SYMBOL.lower()
        candidates = []
        # 5m markets
        base5 = self._current_5m_ts()
        for ts in (base5, base5 + 300, base5 + 600):
            end = ts + 300
            sl  = end - now_ts
            if 5 <= sl <= 310:
                candidates.append((f"{sym}-updown-5m-{ts}", end))
        # 15m markets
        base15 = self._current_15m_ts()
        for ts in (base15, base15 + 900, base15 + 1800):
            end = ts + 900
            sl  = end - now_ts
            if 5 <= sl <= 910:
                candidates.append((f"{sym}-updown-15m-{ts}", end))

        if not candidates:
            return []

        result, to_probe = [], []
        for slug, end in candidates:
            if slug in self._meta_cache:
                result.append(self._meta_cache[slug])
            else:
                to_probe.append((slug, end))

        if to_probe:
            with ThreadPoolExecutor(max_workers=len(to_probe)) as ex:
                futs = {ex.submit(self._probe_slug, s, e): s for s, e in to_probe}
                for fut in as_completed(futs):
                    m = fut.result()
                    if m:
                        result.append(m)
        return result

    # ── price + order book fetching ───────────────────────────────────────────

    def _get_yes_price_and_tokens(self, market: dict) -> tuple:
        """Returns (yes_price, yes_token_id, no_token_id). Sets market['_yes_token_id']."""
        tokens = market.get('tokens') or []
        yes_tid = no_tid = None
        if tokens:
            if isinstance(tokens[0], dict):
                for tok in tokens:
                    outcome = tok.get('outcome', '').lower()
                    tid = tok.get('tokenId') or tok.get('token_id')
                    if outcome in ('yes', 'up'):   yes_tid = tid
                    elif outcome in ('no', 'down'): no_tid  = tid
                if not yes_tid and tokens:
                    yes_tid = tokens[0].get('tokenId') or tokens[0].get('token_id')
            else:
                yes_tid = str(tokens[0]) if len(tokens) > 0 else None
                no_tid  = str(tokens[1]) if len(tokens) > 1 else None
        market['_yes_token_id'] = yes_tid
        market['_no_token_id']  = no_tid

        if yes_tid:
            # Subscribe to CLOB WS so future scans get price from WS cache (sub-50ms)
            if self._clob_ws:
                self._clob_ws.subscribe(yes_tid)
                ws_ask = self._clob_ws.get_ask(yes_tid)
                if ws_ask is not None:
                    market['_live_yes_ask'] = ws_ask
                    market['_price_source'] = 'ws'
                    # Book data for ML features — use cache if fresh, else skip (features degrade gracefully)
                    cached_book = self._book_cache.get(yes_tid)
                    if cached_book and time.time() - cached_book[1] < 3.0:
                        market['_clob_bids'] = cached_book[0].get('bids', [])
                        market['_clob_asks'] = cached_book[0].get('asks', [])
                    return ws_ask, yes_tid, no_tid
            try:
                # Fall back to HTTP book (also populates bids/asks for ML features)
                cached_book = self._book_cache.get(yes_tid)
                if cached_book and time.time() - cached_book[1] < 1.5:
                    book = cached_book[0]
                else:
                    resp = self._session.get(
                        'https://clob.polymarket.com/book',
                        params={'token_id': yes_tid}, timeout=3)
                    if resp.status_code == 200:
                        book = resp.json()
                        self._book_cache[yes_tid] = (book, time.time())
                    else:
                        book = None
                if book:
                    asks = book.get('asks', [])
                    if asks:
                        price = float(sorted(asks, key=lambda x: float(x.get('price', 999)))[0]['price'])
                        market['_live_yes_ask'] = price
                        market['_clob_bids']    = book.get('bids', [])
                        market['_clob_asks']    = asks
                        return price, yes_tid, no_tid
            except Exception:
                pass

        prices = market.get('outcomePrices', [])
        if prices:
            try:
                price = float(prices[0])
                market['_live_yes_ask'] = price
                return price, yes_tid, no_tid
            except Exception:
                pass
        return 0.0, yes_tid, no_tid

    # ── candle data ───────────────────────────────────────────────────────────

    def _get_candles(self, interval: str = '1m', limit: int = 30) -> list:
        # Prefer live WS buffer — always current, zero latency, no REST round-trip
        if hasattr(self, '_binance_ws'):
            ws_candles = self._binance_ws.get_candles(interval)
            if len(ws_candles) >= 5:   # at least 5 candles to be useful
                return ws_candles[-limit:]
        # Fallback: REST fetch (used during WS warm-up, first ~1 minute)
        cache_key = interval
        cached = self._candle_cache.get(cache_key)
        if cached and time.time() - cached[1] < 20:
            return cached[0]
        try:
            r = self._session.get(
                f"{self.BINANCE}/klines",
                params={'symbol': f'{self.SYMBOL}USDT', 'interval': interval, 'limit': limit},
                timeout=5)
            raw = r.json()
            result = [{'open': float(c[1]), 'high': float(c[2]),
                       'low':  float(c[3]),  'close': float(c[4]),
                       'volume': float(c[5]), 'time': int(c[0]) // 1000}
                      for c in raw]
            self._candle_cache[cache_key] = (result, time.time())
            return result
        except Exception as e:
            logger.debug(f'[{self._log}] Candle fetch error: {e}')
            return cached[0] if cached else []

    # ── Kelly sizing ──────────────────────────────────────────────────────────

    def _kelly_stake(self, entry_price: float, prob: float = None) -> float:
        resolved = [t for t in self._trades
                    if t.get('resolved') and t.get('outcome') in ('WIN', 'LOSS')]
        if len(resolved) < 10:
            return self.stake
        wins = sum(1 for t in resolved if t.get('outcome') == 'WIN')
        wr   = wins / len(resolved)
        b    = (1.0 - entry_price) / max(entry_price, 0.01)
        kelly_f = (b * wr - (1 - wr)) / max(b, 0.01)
        if kelly_f <= 0:
            return self.stake  # respect user's stake setting even on negative-Kelly
        # Use live USDC balance as bankroll (cached 2min via bot helper).
        # Fall back to 75× current stake if chain call fails or bot unavailable.
        bankroll = self.stake * 75
        if self.bot:
            try:
                bal = self.bot.get_usdc_balance(max_age=120)
                if bal > 0:
                    bankroll = bal
            except Exception:
                pass
        raw = 0.25 * kelly_f * bankroll
        # Cap respects user's settings.stake. Extreme longshots (ev_per_dollar > 1.0)
        # can scale up to 2.5× the configured cap.
        # FLOOR is now self.stake (was 5.0): user's stake setting acts as minimum bet,
        # not just an upper cap. Setting stake=$21 → every real bet ≥ $21.
        max_cap = self.stake
        if prob is not None and entry_price > 0:
            ev_per_dollar = prob / entry_price - 1.0
            if ev_per_dollar > 1.0:
                max_cap = self.stake * 2.5
        stake_out = round(max(self.stake, min(max_cap, raw)), 2)
        logger.debug(f'[{self._log}-KELLY] entry={entry_price:.3f} wr={wr:.3f} '
                     f'bankroll=${bankroll:.0f} f*={kelly_f:.3f} raw=${raw:.2f} '
                     f'cap=${max_cap:.0f} -> stake=${stake_out:.2f}')
        return stake_out

    # ── paper entry ───────────────────────────────────────────────────────────

    def _paper_enter(self, slug: str, direction: str, entry_price: float,
                     prob: float, features: list, secs_left: float, end_ts: float,
                     yes_token_id: str = None):
        import uuid as _uuid
        # Cross-bot conflict guard
        _xb_ok, _xb_reason = _xbot_check(slug, direction, self._log)
        if not _xb_ok:
            logger.warning(f'[{self._log}] SKIPPED {direction} — {_xb_reason}')
            return
        stake = self._kelly_stake(entry_price, prob=prob)
        hr    = datetime.now(timezone.utc).hour
        sess  = ('ASIA' if 0 <= hr < 8 else 'US_OPEN' if 8 <= hr < 12
                 else 'US_AFT' if 12 <= hr < 20 else 'OVERNIGHT')
        tf    = '15m' if '-updown-15m-' in slug else '5m'
        trade = {
            'id':            _uuid.uuid4().hex[:12],
            'logged_at':     datetime.now(timezone.utc).isoformat(),
            'fill_hour':     hr,
            'fill_session':  sess,
            'symbol':        self.SYMBOL,
            'market_slug':   slug,
            'timeframe':     tf,
            'strategy':      self._log,
            'direction':     direction,
            'entry_price':   entry_price,
            'stake':         stake,
            'shares':        round(stake / (entry_price * (1 + self.FEE_RATE)), 4),
            'secs_to_close': round(secs_left, 1),
            'market_end_ts': end_ts,
            'ml_prob':       round(prob, 4),
            'ml_features':   features,
            'token_id':      yes_token_id,   # needed for scalp exit price lookup
            'resolved':      False,
            'outcome':       None,
            'exit_price':    None,
            'paper_pnl':     None,
        }
        with self._lock:
            self._trades.append(trade)
            self._save_log()
            self._entered_keys.add(f"{slug}_{direction}")
        logger.info(f'[{self._log}] PAPER {direction} ({tf}) @ {entry_price:.3f} '
                    f'prob={prob:.3f} ({secs_left:.0f}s left) stake=${stake}')

    # ── live entry ────────────────────────────────────────────────────────────

    def _live_enter(self, slug: str, direction: str, entry_price: float,
                    prob: float, features: list, secs_left: float, end_ts: float,
                    yes_token_id: str = None, no_token_id: str = None, market: dict = None):
        """Place a real Polymarket order. Falls back to paper on any failure."""
        from py_clob_client_v2.clob_types import OrderType
        import uuid as _uuid

        # Auto-pause gate — if this strategy bled recently, force-paper until next hour.
        # See AutoPauseGate (~line 380); self-clears at next hour boundary.
        # 2026-05-17 protection_override: user can disable the pause check.
        if not getattr(self, 'protection_override', False) and auto_pause_gate().is_paused(self._log):
            logger.info(f'[{self._log}-LIVE] AUTO-PAUSED -> PAPER ({direction} {slug})')
            self._paper_enter(slug, direction, entry_price, prob, features,
                              secs_left, end_ts, yes_token_id=yes_token_id)
            return

        # Cross-bot conflict guard
        _xb_ok, _xb_reason = _xbot_check(slug, direction, self._log)
        if not _xb_ok:
            logger.warning(f'[{self._log}-LIVE] SKIPPED {direction} — {_xb_reason}')
            return

        # Correlation gate (Monday journal #43 idea #5)
        # 2026-05-17 protection_override: user can disable this gate to keep live_mode sticky
        # across correlated bets. Risk: simultaneous BTC+ETH+SOL DOWN at full stake each.
        if not getattr(self, 'protection_override', False):
            _corr_ok, _corr_reason = _correlation_check(self.SYMBOL, direction)
            if not _corr_ok:
                logger.warning(f'[{self._log}-LIVE] CORR-GATE — {_corr_reason}, paper instead')
                self._paper_enter(slug, direction, entry_price, prob, features,
                                  secs_left, end_ts, yes_token_id=yes_token_id)
                return

        bot = self.bot
        if not bot or not bot.wallet_live or not bot.clob_client:
            logger.warning(f'[{self._log}-LIVE] No live wallet — falling back to paper')
            self._paper_enter(slug, direction, entry_price, prob, features,
                              secs_left, end_ts, yes_token_id=yes_token_id)
            return

        # Pick the token for the predicted direction
        token_id = yes_token_id if direction == 'UP' else no_token_id
        if not token_id and market:
            token_id = market.get('_yes_token_id') if direction == 'UP' else market.get('_no_token_id')
        if not token_id:
            logger.warning(f'[{self._log}-LIVE] No token_id for {slug} {direction} — falling back to paper')
            self._paper_enter(slug, direction, entry_price, prob, features,
                              secs_left, end_ts, yes_token_id=yes_token_id)
            return

        # Get live ask price for the token we're buying
        yes_ask = (market or {}).get('_live_yes_ask', entry_price)
        live_ask = yes_ask if direction == 'UP' else (1.0 - yes_ask)
        if live_ask <= 0:
            live_ask = entry_price
        if live_ask >= 0.99:
            logger.warning(f'[{self._log}-LIVE] Price {live_ask:.4f} >= 0.99, skipping {slug}')
            return

        stake = self._kelly_stake(live_ask)
        # PRICE-AGGRESSION: cross the spread so BUY orders fill as takers (take the
        # lowest offer <= ceiling). 2026-06-01: 0.01 -> 0.02 (ML scanner only). Data:
        # ML entries miss ~14-17% (ETH-ML 83.2% / BTC-ML 86.6% fill) and the misses
        # are ~all winners (price ran past ask+1 before the order landed). As a taker,
        # a higher ceiling reaches higher offers (captures misses) WITHOUT overpaying
        # existing fills (verified: actual_fill_price is a real CLOB VWAP, ~60% fill
        # exactly at the old +1-tick ceiling and would still take that lowest offer).
        # Conservative +1-tick nudge: realized gain is BELOW the survivorship upper
        # bound (chasing also fills pops that reverse); optimum to be MEASURED live via
        # fill_confirmed rates, not guessed. Bump again only if misses persist.
        AGGRESSION_TICKS = 0.02
        target_price = min(0.99, live_ask + AGGRESSION_TICKS)
        rounded_price = bot.round_price(target_price)
        if rounded_price <= 0:
            return
        size = stake / rounded_price
        size = bot.round_maker_size(rounded_price, size)
        size = bot._validate_size(size, rounded_price, self.SYMBOL)
        if size * rounded_price < bot.kelly_min_bet:
            import math as _math
            size = _math.ceil(bot.kelly_min_bet / rounded_price)
        stake_actual = round(size * rounded_price, 4)

        ok, result, order_id = False, None, None
        try:
            ok, result, order_id = bot._safe_create_and_post(
                token_id=token_id,
                price=rounded_price,
                size=size,
                side='BUY',
                order_type=OrderType.GTC,
                symbol=self.SYMBOL,
            )
        except Exception as e:
            logger.error(f'[{self._log}-LIVE] Order exception for {slug}: {e}')

        hr   = datetime.now(timezone.utc).hour
        sess = ('ASIA' if 0 <= hr < 8 else 'US_OPEN' if 8 <= hr < 12
                else 'US_AFT' if 12 <= hr < 20 else 'OVERNIGHT')
        tf   = '15m' if '-updown-15m-' in slug else '5m'
        trade = {
            'id':            _uuid.uuid4().hex[:12],
            'logged_at':     datetime.now(timezone.utc).isoformat(),
            'fill_hour':     hr,
            'fill_session':  sess,
            'entry_ts':      time.time(),
            'symbol':        self.SYMBOL,
            'market_slug':   slug,
            'timeframe':     tf,
            'strategy':      self._log,
            'direction':     direction,
            'entry_price':   rounded_price,
            'stake':         stake_actual,
            'shares':        size,
            'secs_to_close': round(secs_left, 1),
            'market_end_ts': end_ts,
            'ml_prob':       round(prob, 4),
            'ml_features':   features,
            'token_id':      token_id,
            'resolved':      False,
            'outcome':       None,
            'exit_price':    None,
            'paper_pnl':     None,
            'real_trade':    True,
            'order_id':      order_id,
            'order_ok':      ok,
            'fill_confirmed': None,
            'filled_size':   None,
        }
        with self._lock:
            self._trades.append(trade)
            self._save_log()
            self._entered_keys.add(f"{slug}_{direction}")

        if ok:
            logger.info(f'[{self._log}-LIVE] ORDER OK {direction} ({tf}) @ {rounded_price:.3f} '
                        f'x {size:.2f} prob={prob:.3f} | order={order_id} | ${stake_actual:.2f}')
            _correlation_record(self.SYMBOL, direction)
        else:
            logger.warning(f'[{self._log}-LIVE] ORDER FAILED {direction} ({tf}) — logged for tracking')

        # TG notification
        try:
            dir_arrow   = '▲' if direction == 'UP' else '▼'
            status_icon = '✅' if ok else '⚠️'
            bot._tg_notify(
                f'{status_icon} {self._log} LIVE {dir_arrow} ${stake_actual:.2f}\n'
                f'@ {rounded_price:.3f} · {secs_left:.0f}s left · prob={prob:.2f}'
            )
        except Exception:
            pass

    # ── fill verification ─────────────────────────────────────────────────────

    def _track_price_path(self):
        """TP/SL price tracking for filled real ML trades.
        Gated by self.tp_sl_enabled. Polls token midpoint between 30-240s post-entry
        and exits early on tp_pct/sl_pct threshold hit. Skips if mid<0.05 (market resolved)."""
        if not self.tp_sl_enabled:
            return
        now = time.time()
        with self._lock:
            tracking = [
                t for t in self._trades
                if t.get('real_trade') and not t.get('resolved')
                and t.get('fill_confirmed') is True
                and t.get('token_id') and t.get('entry_ts')
                and not t.get('tp_sl_triggered')
            ]
        if not tracking:
            return
        changed = False
        for t in tracking:
            elapsed = now - t['entry_ts']
            if elapsed < 30 or elapsed > 240:
                continue
            try:
                resp = self._session.get(
                    f'https://clob.polymarket.com/midpoint?token_id={t["token_id"]}',
                    timeout=3
                )
                mid = resp.json().get('mid')
                if mid is None:
                    continue
                mid = float(mid)
                token_mid = (1.0 - mid) if t.get('direction') == 'DOWN' else mid
                ep = t.get('entry_price', 0)
                if ep <= 0 or token_mid < 0.05:
                    continue
                move_pct = (token_mid - ep) / ep
                if move_pct >= self.tp_pct:
                    logger.info(f'[{self._log}-TP] {t["direction"]} entry={ep:.3f} '
                                f'mid={token_mid:.3f} move={move_pct*100:+.1f}% '
                                f'>= {self.tp_pct*100:.0f}% — TAKE PROFIT')
                    t['tp_sl_triggered'] = 'TP'
                    changed = True
                    self._execute_exit(t)
                elif move_pct <= self.sl_pct:
                    logger.info(f'[{self._log}-SL] {t["direction"]} entry={ep:.3f} '
                                f'mid={token_mid:.3f} move={move_pct*100:+.1f}% '
                                f'<= {self.sl_pct*100:.0f}% — STOP LOSS')
                    t['tp_sl_triggered'] = 'SL'
                    changed = True
                    self._execute_exit(t)
            except Exception as e:
                logger.debug(f'[{self._log}-TPSL] track error: {e}')
        if changed:
            with self._lock:
                self._save_log()

    def _execute_exit(self, trade: dict):
        """Sell held token to exit on TP/SL hit. Chunked-order strategy:
        split the position into ~$1 GTC orders posted at best-bid (or a fallback
        price if the book is empty). The point is that several small orders can
        match independently as fresh bids arrive; a single large order may sit
        unmatched even if some bids exist for a smaller size. Rests on the book
        so partial fills accumulate over the trade's remaining window.
        """
        bot = self.bot if hasattr(self, 'bot') else getattr(self, '_bot', None)
        if not bot or not getattr(bot, 'clob_client', None) or not getattr(bot, 'wallet_live', False):
            logger.warning(f'[{self._log}-EXIT] No live wallet — cannot execute exit')
            return
        token_id = trade.get('token_id')
        try:
            shares = float(trade.get('filled_size') or trade.get('shares', 0) or 0)
        except (TypeError, ValueError):
            shares = 0.0
        if not token_id or shares <= 0:
            return
        try:
            try:
                params = BalanceAllowanceParams(
                    asset_type=AssetType.CONDITIONAL,
                    token_id=token_id,
                    signature_type=2,
                )
                bot.clob_client.update_balance_allowance(params)
            except Exception as _ae:
                logger.debug(f'[{self._log}-EXIT] Allowance update (may already be set): {_ae}')

            # On-chain balance guard. Without this, _execute_exit posts SELL
            # orders for the original filled_size even when the resting SL has
            # already drained the position — Polymarket rejects with
            # "not enough balance / allowance: balance: 0, order amount: ...",
            # producing a burst of ERROR lines per TP/SL trigger. See 2026-05-23
            # error spike: fill=14.2 / sl_resting_filled=14.0 → exit tried 14.2
            # but only 0.2 remained on-chain.
            try:
                _bal_info = bot.clob_client.get_balance_allowance(params)
                _raw_bal  = float(_bal_info.get('balance', 0)) if isinstance(_bal_info, dict) else 0.0
                # API has returned both share-units (5.0) and raw 6-decimal (5000000)
                # historically — 1000 is a safe cut; no real ML position exceeds it.
                onchain_shares = _raw_bal / 1e6 if _raw_bal > 1000 else _raw_bal
            except Exception as _be:
                logger.debug(f'[{self._log}-EXIT] balance probe failed (proceeding optimistically): {_be}')
                onchain_shares = None

            if onchain_shares is not None and onchain_shares < 0.5:
                trade['exit_skipped_reason'] = f'no_onchain_balance ({onchain_shares:.4f})'
                logger.info(
                    f'[{self._log}-EXIT] {trade.get("symbol")} {trade.get("direction")} '
                    f'on-chain balance ~0 (local filled_size={shares:.2f} '
                    f'sl_resting_filled={trade.get("sl_resting_filled_size")}) — '
                    f'position already gone, skipping exit'
                )
                return

            if onchain_shares is not None and onchain_shares + 0.01 < shares:
                logger.info(
                    f'[{self._log}-EXIT] {trade.get("symbol")} clamping {shares:.2f} -> '
                    f'{onchain_shares:.2f} shares (on-chain residual after resting-SL)'
                )
                shares = onchain_shares

            # Determine sell target price.
            book = bot.clob_client.get_order_book(token_id)
            bids = book.bids if (book and hasattr(book, 'bids')) else []
            if bids:
                best_bid = max(float(b.price) for b in bids)
                target = best_bid
                src = 'best_bid'
            else:
                # No bids — fall back to a discounted limit so the resting GTC
                # orders are still in a sensible range. Use last known mid or
                # entry price * 0.9, clipped to [0.05, 0.95].
                ref = (trade.get('current_yes_price')
                       or trade.get('entry_price')
                       or 0.5)
                try:
                    target = max(0.05, min(0.95, float(ref) * 0.9))
                except (TypeError, ValueError):
                    target = 0.5
                src = 'fallback'

            target_price = bot.round_price(target)
            if target_price <= 0:
                logger.warning(f'[{self._log}-EXIT] target_price={target_price} <= 0; aborting')
                return

            # Split shares into ~$1 chunks. Each chunk size = $1 / price.
            DOLLAR_PER_CHUNK = 1.0
            ideal_chunks = max(1, int(shares * target_price / DOLLAR_PER_CHUNK))
            chunk_share_size = shares / ideal_chunks

            placed = 0
            failed = 0
            total_size_placed = 0.0
            first_order_id = None
            for i in range(ideal_chunks):
                csize = bot._validate_size(
                    bot.round_maker_size(target_price, chunk_share_size),
                    target_price, self.SYMBOL
                )
                if csize <= 0:
                    failed += 1
                    continue
                ok, result, order_id = bot._safe_create_and_post(
                    token_id=token_id,
                    price=target_price,
                    size=csize,
                    side='SELL',
                    order_type=OrderType.GTC,
                    symbol=self.SYMBOL,
                )
                if ok:
                    placed += 1
                    total_size_placed += csize
                    if first_order_id is None:
                        first_order_id = order_id
                else:
                    failed += 1
                    # If the very first chunk fails (validation / min-size /
                    # auth issue), no point looping — bail out.
                    if placed == 0 and i == 0:
                        logger.warning(f'[{self._log}-EXIT] first chunk failed: {result}; aborting')
                        return

            if placed > 0:
                trade['exit_order_id'] = first_order_id  # back-compat (first chunk)
                trade['exit_price']    = target_price
                trade['exit_chunks_placed'] = placed
                trade['exit_chunks_failed'] = failed
                trade['exit_size_total']   = round(total_size_placed, 4)
                logger.info(
                    f'[{self._log}-EXIT] OK chunked SELL {placed}/{ideal_chunks} @ '
                    f'{target_price:.3f} ({src}) total_size={total_size_placed:.2f}/{shares:.2f} '
                    f'reason={trade.get("tp_sl_triggered")}'
                )
            else:
                logger.warning(
                    f'[{self._log}-EXIT] No chunks placed (target={target_price:.3f} {src}, '
                    f'ideal_chunks={ideal_chunks}, failed={failed})'
                )
        except Exception as e:
            logger.error(f'[{self._log}-EXIT] error: {e}')

    def _place_resting_sl(self, trade: dict):
        """Post a resting GTC SELL at entry_price * (1 + sl_pct) immediately after
        BUY fill confirmation. Caps the loss without needing _track_price_path
        detection latency — by the time detection fires + chunked exit places
        orders, the price has often moved further and the book has thinned.
        A resting limit catches the SL move as it happens.

        Bracket gotcha on Polymarket: you can only sell shares you hold. So we
        post one resting SELL (the SL leg). TP stays in the existing detection
        path because failed TP exits cost nothing — natural market close pays
        the same as a TP-triggered fill.

        Gated by self.tp_sl_enabled — when the user turns TP/SL off, no resting
        SL either."""
        if not self.tp_sl_enabled:
            return
        bot = self.bot if hasattr(self, 'bot') else getattr(self, '_bot', None)
        if not bot or not getattr(bot, 'clob_client', None) or not getattr(bot, 'wallet_live', False):
            return
        token_id = trade.get('token_id')
        try:
            filled = float(trade.get('filled_size') or 0)
        except (TypeError, ValueError):
            filled = 0.0
        if not token_id or filled <= 0:
            return
        ep = float(trade.get('entry_price') or 0)
        if ep <= 0:
            return
        sl_target = ep * (1 + float(self.sl_pct))
        if sl_target <= 0.01:
            return  # below 1c — not a usable order
        try:
            try:
                params = BalanceAllowanceParams(
                    asset_type=AssetType.CONDITIONAL,
                    token_id=token_id, signature_type=2,
                )
                bot.clob_client.update_balance_allowance(params)
            except Exception as _ae:
                logger.debug(f'[{self._log}-RESTING-SL] allowance: {_ae}')
            rounded_price = bot.round_price(sl_target)
            rounded_size = bot._validate_size(
                bot.round_maker_size(rounded_price, filled),
                rounded_price, self.SYMBOL,
            )
            if rounded_size <= 0:
                logger.debug(f'[{self._log}-RESTING-SL] size after round/validate <= 0; skipping')
                return
            ok, result, order_id = bot._safe_create_and_post(
                token_id=token_id,
                price=rounded_price,
                size=rounded_size,
                side='SELL',
                order_type=OrderType.GTC,
                symbol=self.SYMBOL,
            )
            if ok:
                trade['sl_resting_order_id'] = order_id
                trade['sl_resting_price']    = rounded_price
                trade['sl_resting_size']     = rounded_size
                logger.info(
                    f'[{self._log}-RESTING-SL] placed @ {rounded_price:.3f} '
                    f'x {rounded_size:.2f} (entry={ep:.3f} sl_pct={self.sl_pct:+.0%}) '
                    f'order={order_id}'
                )
            else:
                logger.warning(f'[{self._log}-RESTING-SL] place failed: {result}')
        except Exception as e:
            logger.error(f'[{self._log}-RESTING-SL] error: {e}')

    def _check_fill_status(self):
        """Poll CLOB for fill status on pending real ML trades with valid order_ids.
        Mirrors HFTScanner._check_fill_status — without this, unfilled limit orders
        would silently credit phantom PnL when their market resolved."""
        bot = self.bot if hasattr(self, 'bot') else getattr(self, '_bot', None)
        if not bot or not getattr(bot, 'clob_client', None):
            return
        # 2026-05-23 PR-7: age-cap polling. See HFTScanner._check_fill_status for
        # rationale. Same 5-min cutoff applies — past that, mark orphan and stop.
        import time as _t
        FILL_POLL_MAX_AGE = 300
        now = _t.time()
        with self._lock:
            young_pending = []
            stale_orphans = []
            for t in self._trades:
                # Strict None check: explicit False (cancelled / poll_timed_out)
                # is terminal — don't re-poll or re-mark.
                if not (t.get('real_trade') and t.get('fill_confirmed') is None
                        and t.get('order_id') and t['order_id'] != 'N/A'):
                    continue
                ts = t.get('entry_ts')
                if not isinstance(ts, (int, float)):
                    try:
                        ts = datetime.fromisoformat(
                            (t.get('logged_at') or '').replace('Z','+00:00')
                        ).timestamp()
                    except Exception:
                        ts = 0
                age = now - ts if ts else 0
                if age <= FILL_POLL_MAX_AGE:
                    young_pending.append(t)
                else:
                    stale_orphans.append(t)
        if stale_orphans:
            with self._lock:
                for t in stale_orphans:
                    t['fill_confirmed'] = False
                    t['fill_status']    = 'poll_timed_out'
                logger.info(f'[{self._log}-FILL] Aged out {len(stale_orphans)} orphan(s) past {FILL_POLL_MAX_AGE}s — marked poll_timed_out')
                self._save_log()
        pending_real = young_pending
        if not pending_real:
            return
        changed = False
        newly_filled = []
        for t in pending_real:
            try:
                order = bot.clob_client.get_order(t['order_id'])
                status = getattr(order, 'status', None)
                if status is None and isinstance(order, dict):
                    status = order.get('status')
                filled = getattr(order, 'size_matched', None)
                if filled is None and isinstance(order, dict):
                    filled = order.get('size_matched', 0)
                if status in ('FILLED', 'MATCHED'):
                    t['fill_confirmed'] = True
                    # See HFT _check_fill_status for why this cast matters (silent SL no-op).
                    try:
                        t['filled_size'] = float(filled) if filled is not None else None
                    except (TypeError, ValueError):
                        t['filled_size'] = None
                    changed = True
                    logger.info(f"[{self._log}-FILL] Confirmed fill order_id={t['order_id']} size={filled}")
                    newly_filled.append(t)
                elif status in ('CANCELLED', 'EXPIRED'):
                    t['fill_confirmed'] = False
                    t['fill_status'] = status
                    changed = True
                    logger.info(f"[{self._log}-FILL] Order {status} order_id={t['order_id']}")
            except Exception as e:
                logger.debug(f'[{self._log}-FILL] Check error order_id={t.get("order_id")}: {e}')
        if changed:
            with self._lock:
                self._save_log()
        # Post-fill BUY VWAP lookup — capture actual_fill_price + actual_filled_size
        # from CLOB trade history. The bot's entry_price is the LIMIT we placed;
        # actual fill may be 1-3¢ better when a higher-priced bid was the maker
        # (Polymarket settles at the maker's price). Same pattern as the SL-fill
        # VWAP pass. Done OUTSIDE the lock — network I/O.
        if newly_filled and bot and getattr(bot, 'clob_client', None):
            try:
                from py_clob_client_v2.clob_types import TradeParams
                proxy = (getattr(bot, 'proxy_address', None)
                         or getattr(bot, 'wallet_address', None))
                if proxy:
                    recent = bot.clob_client.get_trades(
                        TradeParams(maker_address=proxy), only_first_page=True
                    )
                    by_order = {}
                    for tr in recent or []:
                        if not isinstance(tr, dict):
                            continue
                        toi = (tr.get('taker_order_id') or tr.get('takerOrderID')
                               or tr.get('takerOrderId'))
                        if toi:
                            by_order.setdefault(toi, []).append(('taker', None, tr))
                        for mo in (tr.get('maker_orders') or tr.get('makerOrders') or []):
                            if not isinstance(mo, dict):
                                continue
                            k = (mo.get('order_id') or mo.get('orderID')
                                 or mo.get('orderId') or mo.get('maker_order_id'))
                            if k:
                                by_order.setdefault(k, []).append(('maker', mo, tr))
                    for t in newly_filled:
                        oid = t.get('order_id')
                        if not oid or oid == 'N/A':
                            continue
                        matches = by_order.get(oid, [])
                        if not matches:
                            continue
                        tsz, tcost = 0.0, 0.0
                        for role, mo, tr in matches:
                            try:
                                if role == 'maker' and mo:
                                    sz = float(mo.get('matched_amount')
                                               or mo.get('matchedAmount')
                                               or mo.get('size') or 0)
                                    pr = float(mo.get('price') or tr.get('price') or 0)
                                else:
                                    sz = float(tr.get('size') or 0)
                                    pr = float(tr.get('price') or 0)
                            except (TypeError, ValueError):
                                continue
                            if sz > 0 and pr > 0:
                                tsz += sz
                                tcost += sz * pr
                        if tsz > 0:
                            vwap = tcost / tsz
                            with self._lock:
                                t['actual_fill_price']  = round(vwap, 6)
                                t['actual_filled_size'] = round(tsz, 4)
                            slip_bps = ((vwap - float(t.get('entry_price') or 0)) * 10000
                                        if t.get('entry_price') else 0)
                            logger.info(
                                f'[{self._log}-BUY-VWAP] {t.get("symbol")} {t.get("direction")} '
                                f'limit={t.get("entry_price")} vwap={vwap:.4f} '
                                f'size={tsz:.2f} slip={slip_bps:+.0f}bps'
                            )
            except Exception as _be:
                logger.debug(f'[{self._log}-BUY-VWAP] err: {_be}')

        # Place resting SL on newly-confirmed fills (outside the lock — _place_resting_sl
        # does its own network I/O). Skips if tp_sl_enabled is False.
        for t in newly_filled:
            try:
                self._place_resting_sl(t)
            except Exception as _re:
                logger.warning(f'[{self._log}-RESTING-SL] hook error: {_re}')
        if newly_filled:
            with self._lock:
                self._save_log()

    # ── outcome resolution ────────────────────────────────────────────────────

    def _resolve_one(self, t: dict) -> Optional[str]:
        now_ts = time.time()
        end_ts = t.get('market_end_ts', 0)
        if end_ts and now_ts < end_ts + 30:
            return None
        slug      = t.get('market_slug', '')
        direction = t.get('direction', 'UP').upper()
        if not slug:
            return None
        try:
            r = self._session.get(
                f"{self.GAMMA}/events", params={'slug': slug}, timeout=4)
            if r.status_code != 200:
                return None
            events = r.json()
            event  = events[0] if isinstance(events, list) and events else None
            if not event:
                return None
            mkt = (event.get('markets') or [None])[0]
            if not mkt:
                return None
            closed         = mkt.get('closed', False)
            out_prices_raw = mkt.get('outcomePrices', '[]')
            outcomes_raw   = mkt.get('outcomes', '["Up","Down"]')
            if isinstance(out_prices_raw, str):
                try: out_prices = [float(x) for x in json.loads(out_prices_raw)]
                except Exception: out_prices = []
            else:
                out_prices = [float(x) for x in (out_prices_raw or [])]
            if isinstance(outcomes_raw, str):
                try: outcomes = json.loads(outcomes_raw)
                except Exception: outcomes = []
            else:
                outcomes = list(outcomes_raw or [])
            for i, o in enumerate(outcomes):
                if o.upper() == direction and i < len(out_prices):
                    p = out_prices[i]
                    if p >= 0.99:   return 'WIN'
                    elif p <= 0.01: return 'LOSS'
                    elif closed:    return 'PUSH'
                    return None
        except Exception as e:
            logger.debug(f'[{self._log}] Resolve error {slug}: {e}')
        return None

    def check_outcomes(self):
        from concurrent.futures import ThreadPoolExecutor, as_completed
        # Include both (a) unresolved trades and (b) scalp-exited trades that
        # still need a time_close_counter_pnl backfill. The backfill gives us
        # hard data on "what would time-close have been?" for trades we
        # exited early — needed by auto_toggle_scalp.py to make a symmetric
        # OFF-vs-ON decision when scalp is currently ON.
        now_ts = time.time()
        with self._lock:
            pending = [t for t in self._trades
                       if not t.get('resolved')
                          or (t.get('scalp_exited')
                              and t.get('time_close_counter_pnl') is None
                              and now_ts >= (t.get('market_end_ts', 0) + 30))]
        if not pending:
            return

        # Failed-order trades (order_ok=False or fill_confirmed=False) flow through
        # _resolve_one to capture the market's directional outcome, so the prediction
        # still feeds ML weights and the RL Q-table. Real-money PnL stays zero
        # (no phantom credit) — see no_fill_shadow branch below.
        def _resolve(t):
            return t, self._resolve_one(t)
        with ThreadPoolExecutor(max_workers=min(len(pending), 8)) as ex:
            results = [f.result() for f in as_completed(ex.submit(_resolve, t) for t in pending)]
        changed = False
        shadow_n = 0
        with self._lock:
            for t, outcome in results:
                if outcome is None:
                    continue
                # Scalp-exited backfill path: trade is already resolved with
                # scalp PnL in paper_pnl/outcome. We only attach what the
                # time-close PnL WOULD have been so the auto-toggle has hard
                # data to compare against the scalp outcome. Skip the rest of
                # the loop — we don't re-resolve, retrain, or update RL here.
                if t.get('scalp_exited') and t.get('time_close_counter_pnl') is None:
                    _stake  = t.get('stake', 0) or 0
                    _shares = t.get('shares', 0) or 0
                    if outcome == 'WIN':
                        _tc_pnl = round(_shares * 1.0 - _stake, 4)
                    elif outcome == 'LOSS':
                        _tc_pnl = -_stake
                    else:  # PUSH
                        _tc_pnl = 0.0
                    t['time_close_counter_pnl']     = _tc_pnl
                    t['time_close_counter_outcome'] = outcome
                    changed = True
                    continue
                stake  = t['stake']
                shares = t['shares']
                is_shadow = (t.get('real_trade') and
                             (t.get('order_ok') is False or t.get('fill_confirmed') is False))
                # Virtual PnL = what the trade would have earned if it had filled.
                # Used for RL credit only; never written to pnl/paper_pnl on shadow trades.
                # TP/SL-aware cap: when tp_sl_enabled, real trades exit via _track_price_path
                # in the 30-240s window or the resting SL throughout the 15m. Without this
                # cap, paper_pnl on LOSS = -stake (~5x larger than live reality at sl=-0.20)
                # and on WIN = full natural close (often 3x the TP-capped amount). RL credit
                # signals (roi = paper_pnl/stake) also use this, so the cap keeps them honest.
                ep_vp = float(t.get('entry_price') or 0)
                if getattr(self, 'tp_sl_enabled', False) and ep_vp > 0:
                    _tp = float(getattr(self, 'tp_pct',  0.30))
                    _sl = float(getattr(self, 'sl_pct', -0.20))
                    if outcome == 'WIN':
                        virtual_pnl = round(shares * (ep_vp * (1 + _tp)) - stake, 4)
                    elif outcome == 'LOSS':
                        virtual_pnl = round(shares * (ep_vp * (1 + _sl)) - stake, 4)
                    else:
                        virtual_pnl = 0.0
                else:
                    virtual_pnl = (round(shares * 1.0 - stake, 4) if outcome == 'WIN'
                                   else (-stake if outcome == 'LOSS' else 0.0))
                if is_shadow:
                    pnl = 0.0
                    paper_pnl = 0.0
                    shadow_n += 1
                else:
                    pnl = virtual_pnl
                    paper_pnl = virtual_pnl
                t.update({
                    'resolved':    True,
                    'outcome':     outcome,
                    'won':         outcome == 'WIN',
                    'pnl':         pnl,
                    'paper_pnl':   paper_pnl,
                    'resolved_at': datetime.now(timezone.utc).isoformat(),
                })
                # Real-money PnL for live ML trades — same formula as HFT.check_outcomes.
                # natural_close_pnl is what the trade WOULD have paid if held to market
                # close (no resting SL). real_pnl/actual_realized_pnl reflects the actual
                # outcome including any resting-SL fill (computed in the SL-aware pass
                # below, outside the lock). For trades without a resting SL, natural ==
                # actual and sl_savings = 0.
                if t.get('real_trade'):
                    if is_shadow:
                        t['real_pnl'] = 0.0
                        t['natural_close_pnl'] = 0.0
                        t['actual_realized_pnl'] = 0.0
                        t['sl_savings'] = 0.0
                    else:
                        fs = 0.0
                        try:
                            fs = float(t.get('filled_size') or 0)
                        except (TypeError, ValueError):
                            fs = 0.0
                        # Cost basis: prefer actual_fill_price (the VWAP we actually paid)
                        # over entry_price (the limit we quoted). Polymarket maker-price
                        # mechanics often give us a few cents better on entry too.
                        ep_actual = (t.get('actual_fill_price')
                                     if t.get('actual_fill_price') is not None
                                     else t.get('entry_price'))
                        ep = float(ep_actual or 0)
                        if fs > 0 and ep > 0:
                            cost = fs * ep
                            if outcome == 'WIN':
                                ncp = round(fs - cost, 4)
                            elif outcome == 'LOSS':
                                ncp = round(-cost, 4)
                            else:
                                ncp = 0.0
                            t['natural_close_pnl'] = ncp
                            # Initial real_pnl = natural-close. SL-aware pass below may
                            # override if a resting SL filled (partial or full).
                            t['real_pnl'] = ncp
                            t['actual_realized_pnl'] = ncp
                            t['sl_savings'] = 0.0
                if is_shadow:
                    t['no_fill_shadow'] = True
                    t['virtual_pnl']    = virtual_pnl
                self._entered_keys.discard(
                    f"{t.get('market_slug','')}_{t.get('direction','')}")
                _xbot_clear(t.get('market_slug', ''))  # free slug for other bots
                tf_label = t.get('timeframe', '?')
                tag = ' SHADOW' if is_shadow else ''
                logger.info(f'[{self._log}]{tag} {outcome} | {tf_label} {t["direction"]} '
                            f'prob={t.get("ml_prob",0):.3f} PnL={pnl:+.2f}'
                            + (f' (virtual={virtual_pnl:+.2f})' if is_shadow else ''))
                try:
                    self.rl.update(t.get('entry_price', 0.5),
                                   t.get('secs_to_close', 30),
                                   stake, virtual_pnl)
                except Exception as _rl_err:
                    logger.debug(f'[{self._log}-RL] Update error: {_rl_err}')
                # Auto-pause gate: feed REAL trades only (paper outcomes don't move wallet).
                # Triggers if rolling 30m PnL <= -$25 OR 3 consecutive losses.
                if t.get('real_trade') is True and not is_shadow:
                    try:
                        auto_pause_gate().record_resolved(self._log, virtual_pnl)
                    except Exception as _ap_err:
                        logger.debug(f'[AUTO-PAUSE] record err: {_ap_err}')
                needs_retrain = self.model.add_resolved_trade(t)
                changed = True
                if needs_retrain:
                    try:
                        self.model.retrain_from_log(list(self._trades))
                    except Exception as _te:
                        logger.warning(f'[{self._log}] Retrain error: {_te}')
            if changed:
                self._save_log()
        if shadow_n:
            logger.info(f'[{self._log}] {shadow_n} no-fill shadow trade(s) resolved '
                        f'— PnL=$0, RL/ML credited')

        # SL-aware PnL pass — for newly-resolved real trades with a resting SL,
        # query the SL order to see how much filled, then update real_pnl /
        # actual_realized_pnl / sl_savings. Done OUTSIDE the lock because the
        # CLOB calls are network round-trips. We use the ACTUAL VWAP fill price
        # (from get_trades), not the SL limit price — because on Polymarket a
        # resting SELL at limit X can match against a higher-priced bid Y; the
        # trade settles at Y (the maker's price), so the limit understates what
        # we actually received.
        bot = self.bot if hasattr(self, 'bot') else getattr(self, '_bot', None)
        if bot and getattr(bot, 'clob_client', None):
            sl_resolved = [(t, oc) for t, oc in results
                           if oc and t.get('real_trade')
                           and not t.get('no_fill_shadow')
                           and t.get('sl_resting_order_id')
                           and t.get('sl_resting_filled_size') is None]
            # Pre-fetch wallet trades once and build order_id -> matches map,
            # so multiple filled SLs in this batch share one network call.
            by_order = {}
            if sl_resolved:
                try:
                    from py_clob_client_v2.clob_types import TradeParams
                    proxy = (getattr(bot, 'proxy_address', None)
                             or getattr(bot, 'wallet_address', None))
                    if proxy:
                        recent = bot.clob_client.get_trades(
                            TradeParams(maker_address=proxy), only_first_page=True
                        )
                        for tr in recent or []:
                            if not isinstance(tr, dict):
                                continue
                            for mo in (tr.get('maker_orders') or tr.get('makerOrders') or []):
                                if not isinstance(mo, dict):
                                    continue
                                k = (mo.get('order_id') or mo.get('orderID')
                                     or mo.get('orderId') or mo.get('maker_order_id'))
                                if k:
                                    by_order.setdefault(k, []).append((mo, tr))
                except Exception as _ve:
                    logger.debug(f'[{self._log}-SL-VWAP] prefetch err: {_ve}')

            def _vwap_for(oid):
                """Returns (matched_size, vwap_price) for an order_id from wallet trades."""
                matches = by_order.get(oid, [])
                tsz, tcost = 0.0, 0.0
                for mo, tr in matches:
                    try:
                        sz = float(mo.get('matched_amount') or mo.get('matchedAmount')
                                   or mo.get('size') or 0)
                        pr = float(mo.get('price') or tr.get('price') or 0)
                    except (TypeError, ValueError):
                        continue
                    if sz > 0 and pr > 0:
                        tsz += sz
                        tcost += sz * pr
                if tsz > 0:
                    return tsz, tcost / tsz
                return 0.0, 0.0

            sl_updated = 0
            for t, oc in sl_resolved:
                sl_id = t['sl_resting_order_id']
                sl_filled = 0.0
                try:
                    sl_order = bot.clob_client.get_order(sl_id)
                    sl_matched = getattr(sl_order, 'size_matched', None)
                    if sl_matched is None and isinstance(sl_order, dict):
                        sl_matched = sl_order.get('size_matched', 0)
                    sl_filled = float(sl_matched or 0)
                except Exception as _se:
                    logger.debug(f'[{self._log}-SL-CHECK] order={sl_id[:14] if sl_id else "?"}.. err={_se}')
                with self._lock:
                    t['sl_resting_filled_size'] = round(sl_filled, 4)
                if sl_filled <= 0:
                    continue   # SL never matched — natural-close numbers stand
                # Look up actual VWAP fill price (may differ from sl_resting_price limit)
                vwap_sz, vwap_price = _vwap_for(sl_id)
                sl_limit = float(t.get('sl_resting_price') or 0)
                sl_actual = vwap_price if vwap_price > 0 else sl_limit
                price_src = 'vwap' if vwap_price > 0 else 'limit'
                fs = float(t.get('filled_size') or 0)
                # Prefer actual_fill_price (BUY-side VWAP) over entry_price (limit)
                # for cost basis — gives accurate sl_savings vs the natural close.
                ep_src = (t.get('actual_fill_price')
                          if t.get('actual_fill_price') is not None
                          else t.get('entry_price'))
                ep = float(ep_src or 0)
                if fs <= 0 or ep <= 0 or sl_actual <= 0:
                    continue
                cost = fs * ep
                close_payoff = 1.0 if oc == 'WIN' else 0.0
                remainder = max(0.0, fs - sl_filled)
                actual = round(sl_filled * sl_actual + remainder * close_payoff - cost, 4)
                ncp = t.get('natural_close_pnl') or 0.0
                savings = round(actual - ncp, 4)
                with self._lock:
                    t['sl_resting_actual_price'] = round(sl_actual, 6)
                    t['actual_realized_pnl']     = actual
                    t['real_pnl']                = actual
                    t['sl_savings']              = savings
                sl_updated += 1
                logger.info(
                    f'[{self._log}-SL-FILL] {t.get("symbol")} {t.get("direction")} '
                    f'sl_filled={sl_filled:.2f}/{fs:.2f} @ {sl_actual:.3f} ({price_src}, '
                    f'limit={sl_limit:.3f}) actual=${actual:+.2f} natural=${ncp:+.2f} '
                    f'savings=${savings:+.2f}'
                )
            if sl_updated:
                with self._lock:
                    self._save_log()

    # ── stats ─────────────────────────────────────────────────────────────────

    def get_stats(self) -> dict:
        with self._lock:
            trades = list(self._trades)
        resolved = [t for t in trades if t.get('resolved') and t.get('outcome') in ('WIN', 'LOSS')]
        pending  = [t for t in trades if not t.get('resolved')]
        wins     = [t for t in resolved if t.get('outcome') == 'WIN']
        wr       = round(len(wins) / len(resolved) * 100, 1) if resolved else 0.0
        total_pnl = round(sum(t.get('pnl', 0) for t in resolved), 2)
        volume    = round(sum(t.get('stake', 0) for t in trades), 2)

        # Daily PnL — UTC day, full PnL (paper + filled)
        _today = datetime.now(timezone.utc).strftime('%Y-%m-%d')
        today_resolved = [t for t in resolved if (t.get('logged_at') or '').startswith(_today)]
        today_wins = sum(1 for t in today_resolved if t.get('outcome') == 'WIN')
        today_pnl  = round(sum(t.get('pnl') or t.get('paper_pnl') or 0 for t in today_resolved), 2)
        today_wr   = round(today_wins / max(len(today_resolved), 1) * 100, 1)

        # ── Scalp A/B comparison (vs TIME_CLOSE actuals) ──────────────────────
        # For each TIME_CLOSE-resolved trade, determine what the scalp PnL would
        # have been: take whichever shadow event fired FIRST (TP or SL by ts).
        # If neither fired, the trade never triggered a scalp exit → counterfactual
        # equals the actual TIME_CLOSE PnL.
        scalp_pnl   = 0.0
        scalp_wins  = 0
        scalp_n     = 0
        tp_only     = 0     # trades where only TP fired
        sl_only     = 0     # trades where only SL fired
        both_fired  = 0     # trades where both fired (TP first wins by ts)
        no_scalp    = 0     # trades where neither fired (held to close cleanly)
        time_close_only = [t for t in resolved if not t.get('scalp_exited')]
        for t in time_close_only:
            tp_ts = t.get('shadow_tp_first_ts')
            sl_ts = t.get('shadow_sl_first_ts')
            scalp_n += 1
            if tp_ts and sl_ts:
                both_fired += 1
                cf_pnl = (t['shadow_tp_first_pnl'] if tp_ts <= sl_ts
                          else t['shadow_sl_first_pnl'])
            elif tp_ts:
                tp_only += 1
                cf_pnl = t['shadow_tp_first_pnl']
            elif sl_ts:
                sl_only += 1
                cf_pnl = t['shadow_sl_first_pnl']
            else:
                no_scalp += 1
                cf_pnl = t.get('pnl', 0)   # never would have exited → same as actual
            scalp_pnl += cf_pnl
            if cf_pnl >= 0:
                scalp_wins += 1
        scalp_pnl = round(scalp_pnl, 2)
        actual_pnl_tc = round(sum(t.get('pnl', 0) for t in time_close_only), 2)
        actual_wins_tc = sum(1 for t in time_close_only if t.get('outcome') == 'WIN')

        # ── Fill verification stats (mirrors HFT pattern) ─────────────────────
        # real_trades = any live order attempt
        # filled = CLOB confirmed FILLED/MATCHED
        # unfilled = CLOB confirmed CANCELLED/EXPIRED OR placement rejected
        # pending_fill = order_ok=True but CLOB not yet replied
        real_trades   = [t for t in trades if t.get('real_trade')]
        filled_trades = [t for t in real_trades if t.get('fill_confirmed') is True]
        unfilled = [t for t in real_trades
                    if t.get('fill_confirmed') is False or t.get('order_ok') is False]
        pending_fill = [t for t in real_trades
                        if t.get('fill_confirmed') is None and t.get('order_ok') is not False]
        fill_rate = round(len(filled_trades) / max(len(real_trades), 1) * 100, 1)
        filled_resolved = [t for t in filled_trades if t.get('resolved')]
        real_wins   = [t for t in filled_resolved if t.get('outcome') == 'WIN']
        real_losses = [t for t in filled_resolved if t.get('outcome') == 'LOSS']
        real_pnl    = round(sum(t.get('pnl') or 0 for t in filled_resolved), 2)
        real_wr     = round(len(real_wins) / max(len(real_wins) + len(real_losses), 1) * 100, 1)
        real_volume = round(sum(t.get('stake', 0) or 0 for t in filled_resolved), 2)

        return {
            'total_trades':  len(trades),
            'resolved':      len(resolved),
            'pending':       len(pending),
            'wins':          len(wins),
            'losses':        len(resolved) - len(wins),
            'win_rate':      wr,
            'total_pnl':     total_pnl,
            'volume':        volume,
            'scan_count':    self._scan_count,
            'last_scan_ts':  self._last_scan_ts,
            'live_mode':     self.live_mode,
            'stake':         self.stake,
            # Today (UTC) — full PnL across paper + filled
            'today_resolved': len(today_resolved),
            'today_wins':     today_wins,
            'today_pnl':      today_pnl,
            'today_wr':       today_wr,
            # Fill verification (NEW — was missing for ML scanners)
            'real_trades':    len(real_trades),
            'filled_trades':  len(filled_trades),
            'unfilled_trades': len(unfilled),
            'pending_fill':   len(pending_fill),
            'fill_rate':      fill_rate,
            'real_wins':      len(real_wins),
            'real_losses':    len(real_losses),
            'real_pnl':       real_pnl,
            'real_wr':        real_wr,
            'real_volume':    real_volume,
            'scalp_exits_enabled': self.SCALP_EXITS_ENABLED,
            'scalp_comparison': {
                # On the same set of TIME_CLOSE-resolved trades:
                'sample_size': scalp_n,
                'actual': {
                    'pnl':  actual_pnl_tc,
                    'wins': actual_wins_tc,
                    'wr':   round(actual_wins_tc / scalp_n * 100, 1) if scalp_n else 0.0,
                },
                'shadow_tp_sl': {
                    'pnl':  scalp_pnl,
                    'wins': scalp_wins,
                    'wr':   round(scalp_wins / scalp_n * 100, 1) if scalp_n else 0.0,
                },
                'delta_pnl':    round(actual_pnl_tc - scalp_pnl, 2),  # +ve = TIME_CLOSE wins
                'tp_only':      tp_only,
                'sl_only':      sl_only,
                'both_fired':   both_fired,
                'neither':      no_scalp,
                'tp_pct':       self.TAKE_PROFIT_PCT,
                'sl_pct':       self.STOP_LOSS_PCT,
            },
            'ml_model': {
                'n_trained':       self.model.n_trained,
                'accuracy':        self.model.accuracy,
                'last_retrain_ts': self.model.last_retrain_ts,
                'feature_importances': self.model.feature_importances(),
            },
            'rl_enabled':    len(resolved) >= BTCMLRl.ENABLED_AFTER,
            'rl_summary':    self.rl.summary(),
            'last_prediction': self._last_prediction,
            # Resting-SL A/B comparison — separate mechanism from scalp_comparison.
            # Aggregates the per-trade fields (natural_close_pnl, actual_realized_pnl,
            # sl_savings, sl_resting_filled_size) written by check_outcomes.
            'resting_sl_comparison': self._build_resting_sl_stats(real_trades),
            # Slippage telemetry — actual_fill_price vs entry_price (the bot's quoted ask).
            # Positive bps = paid more than expected (adverse).
            'slippage': self._build_slippage_stats(real_trades),
        }

    def _build_resting_sl_stats(self, real_trades):
        """Aggregate resting-SL effectiveness across resolved real trades."""
        rsl = [t for t in real_trades
               if t.get('resolved') and t.get('sl_resting_order_id')]
        n_placed = len(rsl)
        n_filled = sum(1 for t in rsl if (t.get('sl_resting_filled_size') or 0) > 0)
        total_natural = round(sum(t.get('natural_close_pnl') or 0 for t in rsl), 2)
        total_actual  = round(sum(t.get('actual_realized_pnl') or 0 for t in rsl), 2)
        delta = round(total_actual - total_natural, 2)
        # Per direction
        by_dir = {}
        for d in ('UP', 'DOWN'):
            sub = [t for t in rsl if t.get('direction') == d]
            sub_filled = sum(1 for t in sub if (t.get('sl_resting_filled_size') or 0) > 0)
            by_dir[d] = {
                'n_placed': len(sub),
                'n_filled': sub_filled,
                'fill_rate': round(sub_filled / max(len(sub), 1) * 100, 1),
                'natural_pnl': round(sum(t.get('natural_close_pnl') or 0 for t in sub), 2),
                'actual_pnl':  round(sum(t.get('actual_realized_pnl') or 0 for t in sub), 2),
                'delta':       round(sum(t.get('sl_savings') or 0 for t in sub), 2),
            }
        # Conditional analysis: when SL filled, what was the avg savings?
        filled_only = [t for t in rsl if (t.get('sl_resting_filled_size') or 0) > 0]
        avg_savings_per_fill = (round(sum(t.get('sl_savings') or 0 for t in filled_only)
                                       / max(len(filled_only), 1), 3)
                                if filled_only else 0.0)
        # When SL filled and outcome would have been WIN at close — "false alarm" cost
        false_alarms = [t for t in filled_only if t.get('outcome') == 'WIN']
        false_alarm_cost = round(sum(t.get('sl_savings') or 0 for t in false_alarms), 2)
        # When SL filled and outcome was LOSS — that's a "true save"
        true_saves = [t for t in filled_only if t.get('outcome') == 'LOSS']
        true_save_value = round(sum(t.get('sl_savings') or 0 for t in true_saves), 2)
        return {
            'n_placed':          n_placed,
            'n_filled':          n_filled,
            'fill_rate':         round(n_filled / max(n_placed, 1) * 100, 1),
            'total_natural_pnl': total_natural,
            'total_actual_pnl':  total_actual,
            'delta':             delta,                  # +ve = SL net helped
            'avg_savings_per_fill': avg_savings_per_fill,
            'true_saves':        {'n': len(true_saves),  'value': true_save_value},
            'false_alarms':      {'n': len(false_alarms),'cost':  false_alarm_cost},
            'by_direction':      by_dir,
        }

    def _build_slippage_stats(self, real_trades):
        """Slippage between the bot's quoted ask (entry_price) and the actual
        VWAP fill (actual_fill_price). Positive bps = paid more than expected."""
        slipped = [t for t in real_trades
                   if t.get('actual_fill_price') is not None
                   and (t.get('entry_price') or 0) > 0]
        if not slipped:
            return {'n': 0}
        deltas = [(float(t['actual_fill_price']) - float(t['entry_price'])) for t in slipped]
        bps = [d * 10000 for d in deltas]
        return {
            'n':       len(slipped),
            'avg_bps': round(sum(bps) / len(bps), 1),
            'max_bps': round(max(bps), 1),
            'min_bps': round(min(bps), 1),
            # Buckets so the UI can show a hist if it wants
            'over_50bps': sum(1 for b in bps if b > 50),
            'under_neg50bps': sum(1 for b in bps if b < -50),
        }

    # ── scalp exit checker ────────────────────────────────────────────────────

    def _check_scalp_exits(self, price_map: dict):
        """
        Check open paper positions for take-profit / stop-loss conditions.
        price_map: {yes_token_id: current_ask_price}

        When SCALP_EXITS_ENABLED is True (legacy behavior):
          - Exit at first TP/SL hit, mark scalp_exited=True, log immediately.

        When SCALP_EXITS_ENABLED is False (current default — A/B comparison mode):
          - Don't actually exit. Record FIRST would-be TP and FIRST would-be SL hit
            on the trade dict as shadow_tp_* / shadow_sl_* fields. Trade continues
            until TIME_CLOSE so we get the real payout/loss, plus the counterfactual
            scalp PnL for direct comparison.
        """
        now_ts = time.time()
        changed = False
        with self._lock:
            for t in self._trades:
                if t.get('resolved') or t.get('scalp_exited'):
                    continue
                yes_tid = t.get('token_id') or t.get('yes_token_id')
                entry   = t.get('entry_price', 0)
                if not yes_tid or entry <= 0:
                    continue
                # Direction UP: we own YES token; DOWN: we own NO token (price = 1 - yes_ask)
                direction = t.get('direction', 'UP')
                # Prefer WS feed (sub-50ms) over scan price_map
                if self._clob_ws:
                    ws_p = self._clob_ws.get_ask(yes_tid)
                    cur_price = ws_p if ws_p is not None else price_map.get(yes_tid)
                else:
                    cur_price = price_map.get(yes_tid)
                if cur_price is None:
                    continue
                token_price = cur_price if direction == 'UP' else (1.0 - cur_price)

                pct_change = (token_price - entry) / entry
                tp_hit = pct_change >=  self.TAKE_PROFIT_PCT
                sl_hit = pct_change <= -self.STOP_LOSS_PCT

                if not tp_hit and not sl_hit:
                    continue

                # Compute scalp PnL at the current price snapshot — used for both real
                # and shadow exit accounting.
                shares = t.get('shares', t.get('stake', 5) / max(entry, 0.01))
                gross  = shares * token_price
                fee    = gross * self.FEE_RATE
                pnl    = round(gross - fee - t.get('stake', 5), 4)
                exit_reason = 'TAKE_PROFIT' if tp_hit else 'STOP_LOSS'

                # ── Shadow logging — capture FIRST hit of each kind ──────────────
                if tp_hit and 'shadow_tp_first_ts' not in t:
                    t['shadow_tp_first_ts']    = now_ts
                    t['shadow_tp_first_price'] = round(token_price, 4)
                    t['shadow_tp_first_pnl']   = pnl
                    t['shadow_tp_first_pct']   = round(pct_change, 4)
                    changed = True
                if sl_hit and 'shadow_sl_first_ts' not in t:
                    t['shadow_sl_first_ts']    = now_ts
                    t['shadow_sl_first_price'] = round(token_price, 4)
                    t['shadow_sl_first_pnl']   = pnl
                    t['shadow_sl_first_pct']   = round(pct_change, 4)
                    changed = True

                if not self.SCALP_EXITS_ENABLED:
                    # A/B mode — skip real exit, let trade run to TIME_CLOSE
                    continue

                # ── Scalp threshold crossed (informational only) ────────────────
                # 2026-05-20: the old "real scalp exit" branch marked the trade
                # resolved + set exit_price to the midpoint + set paper_pnl from
                # midpoint math — but NEVER placed an actual SELL order on CLOB.
                # The position kept running on-chain. User caught this via the
                # Polymarket UI showing bought @ 0.65 / sold @ 0.68 while the bot
                # logged exit=0.78 / paper_pnl=+1.98. Fix: don't mark resolved,
                # don't write fantasy exit_price/paper_pnl. The resting-SL we
                # ship today handles real SL exits via a GTC order placed at
                # fill time; TP-side gets handled by natural close (which on a
                # WIN pays $1/share — generally MORE than a +20% scalp lock-in
                # would have given). Just record the threshold crossing for the
                # A/B counterfactual data already captured via shadow_*_first_*.
                if 'scalp_threshold_first_ts' not in t:
                    t['scalp_threshold_first_ts']     = now_ts
                    t['scalp_threshold_first_reason'] = exit_reason
                    t['scalp_threshold_first_price']  = round(token_price, 4)
                    t['scalp_threshold_first_pct']    = round(pct_change, 4)
                    changed = True
                    logger.info(f'[{self._log}] SCALP {exit_reason} threshold '
                                f'{direction} entry={entry:.3f} mid={token_price:.3f} '
                                f'pct={pct_change*100:+.1f}% — informational only; '
                                f'real exit via resting SL / natural close')
        if changed:
            self._save_log()

    # ── chop detector (shadow-only, 2026-05-20) ───────────────────────────────

    def _btc_chop(self, candles_1m: list) -> dict:
        """Classify BTC 15-min microstructure. Shadow-only — not gating yet.

        Reuses candles already fetched in scan_once. Returns:
          state  — 'TREND' | 'CHOP' | 'NEUTRAL'
          path   — sum of |1m close-to-close| over last 15m, in percent
          eff    — |net move| / path  (1.0 = pure trend, 0 = perfect chop)
          flips  — direction reversals among the 15 close-to-close returns

        Thresholds calibrated 2026-05-20 against the bleed window (5/20 00-04
        UTC, path ~0.44%/15m) vs. the prior win window (5/19 19-23, path
        ~0.29%/15m). Treat as starting point; refine via btc_ml_chop_log.jsonl.
        """
        if not candles_1m or len(candles_1m) < 16:
            return {'state': 'NEUTRAL', 'path': 0.0, 'eff': 0.0, 'flips': 0}
        closes = [c['close'] for c in candles_1m[-16:]]
        rets   = [(closes[i+1] - closes[i]) / closes[i] for i in range(15)
                  if closes[i] > 0]
        if len(rets) < 15:
            return {'state': 'NEUTRAL', 'path': 0.0, 'eff': 0.0, 'flips': 0}
        path  = sum(abs(r) for r in rets) * 100.0
        net   = abs(sum(rets)) * 100.0
        eff   = (net / path) if path > 0 else 0.0
        flips = sum(1 for i in range(1, 15)
                    if (rets[i] > 0) != (rets[i-1] > 0))
        if (path >= 0.40 and eff < 0.30) or flips >= 8:
            state = 'CHOP'
        elif eff >= 0.55 and path >= 0.15:
            state = 'TREND'
        else:
            state = 'NEUTRAL'
        return {'state': state, 'path': round(path, 4),
                'eff': round(eff, 4), 'flips': flips}

    # ── main scan loop ────────────────────────────────────────────────────────

    def scan_once(self, triggered: bool = False):
        from concurrent.futures import ThreadPoolExecutor, as_completed
        try:
            now_ts = time.time()
            # Rate-limit event-triggered scans — max 1 per 0.5s regardless of source
            if triggered:
                if now_ts - self._last_triggered_ts < 0.5:
                    return
                self._last_triggered_ts = now_ts
            self._scan_event.clear()   # reset event so next BTC move re-arms it
            self._scan_count += 1
            self._last_scan_ts = now_ts

            if self._scan_count % 75 == 0:
                self._load_settings()
                self._maybe_autoflip_blocked_hours()
                self._trim_blocked_hours_to_cap()
                self._maybe_autoadd_blocked_hours()

            # Use background-refreshed market cache (avoids Gamma HTTP on hot path)
            with self._market_bg_lock:
                markets = list(self._market_bg_cache)
            if not markets:
                # Cache not ready yet — do a direct fetch this one time
                markets = self._fetch_active_markets()
            active  = []
            for m in markets:
                end_ts    = float(m.get('end_ts', 0))
                secs_left = end_ts - now_ts
                if secs_left < 5 or secs_left > 250:
                    continue
                m['_secs_left'] = secs_left
                m['_end_ts']    = end_ts
                active.append(m)

            if not active:
                return

            # Fetch candles once for all BTC markets (same Binance data)
            candles_1m = self._get_candles('1m', 30)
            candles_5m = self._get_candles('5m', 30)

            # Collect edge signals from all data feeds (all in-memory, zero latency)
            depth_imbal  = self._binance_ws.get_depth_imbalance()
            flow_imbal   = self._binance_ws.get_trade_flow_imbalance()
            liq_usd, liq_dir = self._okx_liq_ws.get_liq_cascade()  # OKX (Binance fstream geo-blocked)
            funding      = self._futures_ws.get_funding_rate()     # Binance fapi REST works fine
            # Consume cascade override if fresh (< 3s old)
            cascade = self._cascade_signal
            cascade_active = (cascade and
                              time.time() - cascade.get('ts', 0) < 3.0)

            # Parallel price + order book fetch
            def _fetch_market(m):
                price, yes_tid, no_tid = self._get_yes_price_and_tokens(m)
                bids = m.get('_clob_bids', [])
                asks = m.get('_clob_asks', [])
                return m, price, yes_tid, no_tid, bids, asks

            with ThreadPoolExecutor(max_workers=len(active)) as ex:
                results = [f.result() for f in as_completed(
                    ex.submit(_fetch_market, m) for m in active)]

            # Build price map and check scalp exits BEFORE entering new positions
            price_map = {yes_tid: price for _, price, yes_tid, _, _, _ in results
                         if yes_tid and price > 0}
            self._check_scalp_exits(price_map)

            # Expire stale re-entry cooldowns
            now_ts2 = time.time()
            self._reentry_cooldown = {k: v for k, v in self._reentry_cooldown.items()
                                      if now_ts2 - v < self.REENTRY_COOLDOWN}

            # Count resolved trades for RL gating
            with self._lock:
                resolved_count = sum(1 for t in self._trades
                                     if t.get('resolved') and
                                     t.get('outcome') in ('WIN', 'LOSS'))

            for m, price, yes_tid, no_tid, bids, asks in results:
                if price <= 0:
                    continue
                secs_left = m['_secs_left']
                end_ts    = m['_end_ts']
                slug      = m.get('slug', '')

                # Sign liq_usd: positive = long liqs (bearish), negative = short liqs (bullish)
                signed_liq = liq_usd if liq_dir == 'DOWN' else -liq_usd
                features  = self.model.extract_features(
                    candles_1m, candles_5m, price, secs_left, bids, asks,
                    depth_imbalance=depth_imbal,
                    trade_flow_imbal=flow_imbal,
                    liq_cascade_usd=signed_liq,
                    funding_rate=funding)
                prob, direction = self.model.predict(features)

                # Liquidation cascade override: skip normal confidence gate
                if cascade_active and cascade.get('direction') == direction:
                    prob = cascade['prob']   # use cascade-computed high confidence

                self._last_prediction = {
                    'slug': slug, 'price': round(price, 4),
                    'prob': round(prob, 4), 'direction': direction,
                    'features': features, 'secs_left': round(secs_left, 1),
                    'depth_imbal': round(depth_imbal, 3),
                    'flow_imbal':  round(flow_imbal, 3),
                    'liq_usd':     round(liq_usd, 0),
                    'funding':     round(funding * 10000, 2),  # bps
                    'ts': now_ts,
                }

                # ── Signal selection ─────────────────────────────────────────────────
                # COLLECTING (n_trained < MIN_TRAIN_N): rule-based momentum/exhaustion
                #   to generate training data.
                # TRAINED: ML probability gate, BUT extreme-zone exhaustion stays as a
                #   bypass since asymmetric payouts (token < 0.28 or > 0.72) reward
                #   longshots even at sub-threshold ML confidence — see +$88.93 ETH-ML
                #   trade 2026-05-03 at 18¢ entry that paid 4.56× stake on a single win.
                collecting = self.model.n_trained < self.model.MIN_TRAIN_N

                # Compute exhaustion zone — used in both phases.
                in_extreme_up   = 0.72 <= price <= 0.93
                in_extreme_down = 0.07 <= price <= 0.28
                price_offset    = abs(price - 0.50)
                exh_fire        = in_extreme_up or in_extreme_down

                if collecting:
                    # Rule-based signal for data collection — two sub-strategies:
                    f = features
                    # MOMENTUM signal: candle alignment + price moved off midpoint
                    mom_score = f[0] * 3 + f[1] * 2 + f[3] + f[4]  # 1m mom, 5m mom, wick, body
                    mom_fire  = abs(mom_score) >= 0.15 and price_offset >= 0.08

                    if mom_fire:
                        direction = 'UP' if mom_score >= 0 else 'DOWN'
                        signal_type = 'MOM'
                        prob = min(0.80, 0.52 + abs(mom_score) * 0.5)
                    elif exh_fire:
                        direction = 'UP' if in_extreme_up else 'DOWN'
                        signal_type = 'EXH'
                        prob = 0.72 if price_offset >= 0.30 else 0.62
                    else:
                        continue
                    logger.debug(f'[{self._log}] COLLECT {signal_type} {direction} '
                                 f'price={price:.3f} score={mom_score:.3f}')
                else:
                    # ML model is trained — use probability confidence gate
                    confidence = max(prob, 1.0 - prob)
                    if confidence < self.ML_PROB_THRESHOLD:
                        # EXH-BYPASS disabled per backtest 2026-05-03:
                        # Both BTC-ML 0.80 bucket (n=121, -3.6% below breakWR, -$24 PnL)
                        # and ETH-ML 0.70 bucket (n=67, -5.4% below breakWR, -$50 PnL)
                        # show the same bug as HFT EXTREME-RIDE — riding consensus at
                        # high entry prices where actual WR matches price-implied breakWR.
                        # No edge in "fade-low-conviction-into-extreme-zone" logic;
                        # buy the cheap longshot only when ML conviction is HIGH.
                        continue

                # Entry price = cost of the predicted-direction token
                entry_price = round(price if direction == 'UP' else 1.0 - price, 4)
                # Upper cap tightened to 0.78 per backtest 2026-05-03:
                # ML scanners bleed at entry_price >= 0.78 (no edge over price-implied WR).
                # 0.06 lower bound preserved (cheap longshots still allowed when ML confident).
                if entry_price < 0.06 or entry_price > 0.78:
                    continue

                key = f"{slug}_{direction}"
                opp = 'DOWN' if direction == 'UP' else 'UP'
                if key in self._entered_keys or f"{slug}_{opp}" in self._entered_keys:
                    continue
                # Re-entry cooldown: wait REENTRY_COOLDOWN seconds after a scalp exit
                if key in self._reentry_cooldown:
                    continue

                # 2026-05-28 skip_directions gate: shadow-block configured
                # directions so their would-be outcome still resolves for validation.
                if direction in self.skip_directions:
                    try:
                        self.rl_shadow.log_blocked(
                            rl_system=f'{self._sym_lc}_ml_skip_dir',
                            state_key='SKIP_DIR',
                            rl_q=0.0, rl_n=0, rl_reason=f'{direction} in skip_directions',
                            symbol=self.SYMBOL, direction=direction,
                            entry_price=entry_price, stake=self.stake,
                            secs_to_close=secs_left, market_end_ts=end_ts,
                            market_slug=slug, strategy='ML',
                            token_id=(yes_tid if direction == 'UP' else no_tid) or '')
                    except Exception as _se:
                        logger.debug(f'[SKIPDIR-SHADOW] log error: {_se}')
                    continue

                # 2026-05-29 max_entry_price gate. Shadow-block entries priced at
                # or above the cap (favorite trap: high WR, negative EV). 0.0 =
                # disabled. State key buckets by 5c band (PX_70_75 = 0.70-0.75).
                if self.max_entry_price > 0 and entry_price >= self.max_entry_price:
                    _px_reason = f'entry_price {entry_price:.3f} >= max_entry_price {self.max_entry_price:.3f}'
                    _px_lo = int(entry_price * 100) // 5 * 5
                    _px_state_key = f'PX_{_px_lo:02d}_{_px_lo+5:02d}'
                    logger.info(f'[{self._log}-PXBLOCK] SKIP {slug} {direction}: {_px_reason}')
                    try:
                        self.rl_shadow.log_blocked(
                            rl_system=f'{self._sym_lc}_ml_price_block',
                            state_key=_px_state_key,
                            rl_q=round(float(entry_price), 4), rl_n=0, rl_reason=_px_reason,
                            symbol=self.SYMBOL, direction=direction,
                            entry_price=entry_price, stake=self.stake,
                            secs_to_close=secs_left, market_end_ts=end_ts,
                            market_slug=slug, strategy='ML',
                            token_id=(yes_tid if direction == 'UP' else no_tid) or '')
                    except Exception as _se:
                        logger.debug(f'[PXBLOCK-SHADOW] log error: {_se}')
                    continue

                # Bullish-market filter for UP signals only (DOWN side currently carries P&L).
                # Last 30 min of 5m closes vs prior 30 min — skip UP if not trending up.
                # Shadow-log skips so we can evaluate whether the filter helps.
                if direction == 'UP' and len(candles_5m) >= 12:
                    recent_avg = sum(c['close'] for c in candles_5m[-6:]) / 6
                    prior_avg  = sum(c['close'] for c in candles_5m[-12:-6]) / 6
                    if recent_avg <= prior_avg:
                        _reason = f'recent_avg {recent_avg:.1f} <= prior_avg {prior_avg:.1f}'
                        logger.debug(f'[{self._log}] SKIP UP {slug}: market not bullish ({_reason})')
                        try:
                            self.rl_shadow.log_blocked(
                                rl_system=f'{self._sym_lc}_ml_bullish_filter',
                                state_key='BULLISH_FILTER',
                                rl_q=0.0, rl_n=0, rl_reason=_reason,
                                symbol=self.SYMBOL, direction=direction,
                                entry_price=entry_price, stake=self.stake,
                                secs_to_close=secs_left, market_end_ts=end_ts,
                                market_slug=slug, strategy='ML',
                                token_id=(yes_tid if direction == 'UP' else no_tid) or '')
                        except Exception as _se:
                            logger.debug(f'[BULLISH-SHADOW] log error: {_se}')
                        continue

                # 2026-05-23 hour-of-day blocklist. Shadow-only — the trade is
                # recorded as blocked so its would-be outcome resolves into the
                # rl_shadow log, giving the UI a live winrate for the blocked
                # cohort. Cohort can be reverted by editing blocked_hours in
                # *_ml_settings.json (or via /api/{sym}-ml-settings POST).
                if self.blocked_hours:
                    _now_hr = datetime.now(timezone.utc).hour
                    if _now_hr in self.blocked_hours:
                        # 2026-05-30: enforcement toggle. When hour_block_enabled is
                        # False (training mode) we STILL shadow-log the would-be block
                        # (keeps the blocked-cohort evidence flowing) but DON'T skip —
                        # the trade falls through to entry so the hour trains the model.
                        _enforced = getattr(self, 'hour_block_enabled', True)
                        _hr_reason = f'hour {_now_hr} UTC in blocked_hours={self.blocked_hours}'
                        _mode = 'SKIP' if _enforced else 'SHADOW-ONLY (gate off, training)'
                        logger.info(f'[{self._log}-HRBLOCK] {_mode} {slug} {direction}: {_hr_reason}')
                        try:
                            self.rl_shadow.log_blocked(
                                rl_system=f'{self._sym_lc}_ml_hour_block',
                                state_key=f'HR_{_now_hr:02d}',
                                rl_q=0.0, rl_n=0, rl_reason=_hr_reason,
                                symbol=self.SYMBOL, direction=direction,
                                entry_price=entry_price, stake=self.stake,
                                secs_to_close=secs_left, market_end_ts=end_ts,
                                market_slug=slug, strategy='ML',
                                token_id=(yes_tid if direction == 'UP' else no_tid) or '')
                        except Exception as _se:
                            logger.debug(f'[HRBLOCK-SHADOW] log error: {_se}')
                        if _enforced:
                            continue
                        # gate off → fall through to entry (honors live_mode)

                # 2026-05-23 volatility gate. Features index 7 is volatility (see
                # BTCMLModel.FEATURE_NAMES). Skip if exceeds threshold and shadow-log
                # so we can measure the gate's effectiveness via /api/{sym}-ml-state.
                # 0.0 threshold = disabled. ETH-ML default 0.06 (edge flips below this).
                if self.max_volatility > 0 and len(features) > 7:
                    _vol = features[7]
                    if _vol is not None and _vol > self.max_volatility:
                        _vol_reason = f'vol {_vol:.3f} > max_volatility {self.max_volatility:.3f}'
                        # Bucket key for per-band tile: VOL_06_08 means 0.06-0.08, etc.
                        _vol_band_lo = int(_vol * 100) // 2 * 2  # 6, 8, 10, 12...
                        _vol_state_key = f'VOL_{_vol_band_lo:02d}_{_vol_band_lo+2:02d}'
                        logger.info(f'[{self._log}-VOLBLOCK] SKIP {slug} {direction}: {_vol_reason}')
                        try:
                            self.rl_shadow.log_blocked(
                                rl_system=f'{self._sym_lc}_ml_vol_block',
                                state_key=_vol_state_key,
                                rl_q=round(float(_vol), 4), rl_n=0, rl_reason=_vol_reason,
                                symbol=self.SYMBOL, direction=direction,
                                entry_price=entry_price, stake=self.stake,
                                secs_to_close=secs_left, market_end_ts=end_ts,
                                market_slug=slug, strategy='ML',
                                token_id=(yes_tid if direction == 'UP' else no_tid) or '')
                        except Exception as _se:
                            logger.debug(f'[VOLBLOCK-SHADOW] log error: {_se}')
                        continue

                # 2026-05-27 volume-spike band gate. Skip when ml_features[2]
                # (volume_spike) is in [block_lo, block_hi). Per-symbol settings:
                # BTC blocks all f2>=0 (block_lo=0, block_hi=999); ETH blocks the
                # bleeding middle band [-0.5, 0.5). Disabled when lo==hi.
                _vs_lo = float(getattr(self, 'volume_spike_block_lo', 0.0))
                _vs_hi = float(getattr(self, 'volume_spike_block_hi', 0.0))
                if _vs_lo != _vs_hi and len(features) > 2:
                    _vs = features[2]
                    if _vs is not None and _vs_lo <= _vs < _vs_hi:
                        _vs_reason = f'volume_spike {_vs:+.3f} in [{_vs_lo:+.2f}, {_vs_hi:+.2f})'
                        # Bucket key for per-band tile: VS_neg05_pos05, VS_pos00_pos99 etc.
                        def _vs_tag(x):
                            s = 'neg' if x < 0 else 'pos'
                            return f'{s}{int(abs(x*100)):02d}'
                        _vs_state_key = f'VS_{_vs_tag(_vs_lo)}_{_vs_tag(_vs_hi)}'
                        logger.info(f'[{self._log}-VSBLOCK] SKIP {slug} {direction}: {_vs_reason}')
                        try:
                            self.rl_shadow.log_blocked(
                                rl_system=f'{self._sym_lc}_ml_vs_block',
                                state_key=_vs_state_key,
                                rl_q=round(float(_vs), 4), rl_n=0, rl_reason=_vs_reason,
                                symbol=self.SYMBOL, direction=direction,
                                entry_price=entry_price, stake=self.stake,
                                secs_to_close=secs_left, market_end_ts=end_ts,
                                market_slug=slug, strategy='ML',
                                token_id=(yes_tid if direction == 'UP' else no_tid) or '')
                        except Exception as _se:
                            logger.debug(f'[VSBLOCK-SHADOW] log error: {_se}')
                        continue

                rl_allow, _rl_reason = self.rl.should_enter(
                    entry_price, secs_left, resolved_count)
                if not rl_allow:
                    logger.info(f'[{self._log}-RL] SKIP {slug} {direction}: {_rl_reason}')
                    _rl_q, _rl_n, _rl_key = self.rl.score(entry_price, secs_left)
                    try:
                        self.rl_shadow.log_blocked(
                            rl_system=f'{self._sym_lc}_ml', state_key=_rl_key,
                            rl_q=_rl_q, rl_n=_rl_n, rl_reason=_rl_reason,
                            symbol=self.SYMBOL, direction=direction,
                            entry_price=entry_price, stake=self.stake,
                            secs_to_close=secs_left, market_end_ts=end_ts,
                            market_slug=slug, strategy='ML',
                            token_id=(yes_tid if direction == 'UP' else no_tid) or '')
                    except Exception as _se:
                        logger.debug(f'[RL-SHADOW] log error: {_se}')
                    continue

                # Shadow-log chop signal at decision time so we can later
                # join chop_state against trade outcome by slug. No gating —
                # see _btc_chop docstring for threshold provenance.
                try:
                    _chop = self._btc_chop(candles_1m)
                    with open('btc_ml_chop_log.jsonl', 'a', encoding='utf-8') as _cf:
                        _cf.write(json.dumps({
                            'ts': datetime.now(timezone.utc).isoformat(),
                            'slug': slug, 'symbol': self.SYMBOL,
                            'direction': direction, 'prob': round(prob, 4),
                            'entry_price': entry_price,
                            'secs_to_close': round(secs_left, 1),
                            'chop_state': _chop['state'],
                            'chop_path':  _chop['path'],
                            'chop_eff':   _chop['eff'],
                            'chop_flips': _chop['flips'],
                        }) + '\n')
                except Exception as _ce:
                    logger.debug(f'[{self._log}] chop shadow log error: {_ce}')

                if self.live_mode:
                    self._live_enter(slug, direction, entry_price,
                                     prob, features, secs_left, end_ts,
                                     yes_token_id=yes_tid,
                                     no_token_id=no_tid,
                                     market=m)
                else:
                    self._paper_enter(slug, direction, entry_price,
                                      prob, features, secs_left, end_ts,
                                      yes_token_id=yes_tid)

        except Exception as e:
            logger.warning(f'[{self._log}] scan_once error: {e}')


# ──────────────────────────────────────────────────────────────────────────────
# BTC-HERMES — Markov persistence trader (5-min BTC), Hermes nightly self-learn
# ──────────────────────────────────────────────────────────────────────────────

class BTCHermesScanner:
    """
    BTC 5-minute persistence trader. Pure Markov chain on candle direction.

    Model:
      state = direction of last CLOSED 5m candle ('UP' if close > open else 'DOWN')
      p     = transition probability p(next=state | current=state)   from matrix
      q     = current Polymarket bid (model_q from CLOB)             live
      edge  = p - q

    Entry: p >= MIN_PROB AND edge >= MIN_EDGE.
    Sizing: Kelly f* = (p - q) / (1 - q), clamped to [floor, user stake ceiling].

    Hermes nightly (btc_hermes_nightly.py — Phase 3) retunes MIN_PROB, MIN_EDGE,
    Kelly fraction in btc_hermes_settings.json AND refits the transition matrix
    in btc_hermes_matrix.json from rolling 5m candle history. Bot reloads both
    every 75 scans via _load_settings.

    Shared infrastructure (passed in __init__):
      bot_ref     — PolymarketPredictionBot (clob_client, balance, allowances)
      clob_ws     — CLOBWebSocketFeed (shared with HFT/BTC-ML)
      btc_ml_ref  — BTCMLScanner (shares 5m candle cache + Binance WS trigger)

    Critical correctness: _markov_state() uses candles_5m[-2] (last CLOSED),
    NOT [-1] (currently forming). Off-by-one silently destroys edge — the
    [-1] candle's close changes every tick and correlates with the bet
    outcome. Unit test in Phase 6 asserts this.

    Phase 2a (this commit): class skeleton + data management + Markov + Kelly.
    scan_once / check_outcomes / _paper_enter / _live_enter are STUBS — Phase 2b.
    """

    SYMBOL              = 'BTC'
    LOG_FILE            = 'btc_hermes_trades.json'
    SETTINGS_FILE       = 'btc_hermes_settings.json'
    MATRIX_FILE         = 'btc_hermes_matrix.json'
    PAPER_STAKE         = 5.0
    FEE_RATE            = 0.0
    LOG_MAX_ENTRIES     = 50000
    # Kelly bounds — user-configured self.stake is the HARD CEILING. Mirrors
    # HFT _kelly_stake pattern (polymarket_bot.py:9098, shipped 2026-05-24).
    KELLY_MIN_STAKE     = 5.0
    KELLY_MAX_STAKE     = 25.0
    KELLY_MIN_N_SAMPLES = 200    # require this many matrix samples before any trade

    def __init__(self, bot_ref=None, clob_ws=None, btc_ml_ref=None):
        self._log     = f'{self.SYMBOL}-HERMES'
        self.bot      = bot_ref
        self._clob_ws = clob_ws
        self._btc_ml  = btc_ml_ref
        # HTTP session for Gamma resolution + CLOB book fallback
        import requests as _req
        self._session = _req.Session()
        self._session.headers.update({'Accept-Encoding': 'gzip'})
        self.GAMMA = 'https://gamma-api.polymarket.com'
        self._trades: list = []
        self._lock         = threading.Lock()
        # Async save worker (same pattern as BTCMLScanner). Inline queue import
        # since host file does not import queue at module level.
        import queue as _queue
        self._save_queue = _queue.Queue(maxsize=1)
        self._save_thread: Optional[threading.Thread] = None
        # Scan bookkeeping
        self._scan_count        = 0
        self._last_scan_ts      = 0.0
        self._last_triggered_ts = 0.0
        self._entered_keys: set = set()
        self._book_cache: dict  = {}
        # Background market cache (refreshed by _market_refresh_loop)
        self._market_bg_cache: list = []
        self._market_bg_lock = threading.Lock()
        # Scan event: share with btc_ml_ref so HERMES fires on the same Binance
        # triggers (zero extra WS). Falls back to private event if no ref.
        self._scan_event = (btc_ml_ref._scan_event if btc_ml_ref is not None
                            else threading.Event())
        # Layer 3: register Binance tick callback for instant sell/cut decisions.
        # Runs in WS thread — _on_binance_tick uses self._lock for thread safety.
        if btc_ml_ref is not None and hasattr(btc_ml_ref, '_binance_ws'):
            try:
                btc_ml_ref._binance_ws.register(self._on_binance_tick)
                # (will log success at end of __init__ since logger uses self._log)
                self._binance_callback_registered = True
            except Exception as _be:
                self._binance_callback_registered = False
        else:
            self._binance_callback_registered = False
        # Markov state — populated by _load_matrix() and Hermes nightly retrains
        self.markov: dict = {
            'p_uu':             0.5,
            'p_dd':             0.5,
            'n_samples':        0,
            'window_days':      7,
            'last_refit_ts':    None,
            'binance_first_ts': None,
            'binance_last_ts':  None,
        }
        # Settings defaults — overridden by _load_settings if file exists
        self.live_mode:           bool  = False
        self.stake:               float = self.PAPER_STAKE
        self.tp_sl_enabled:       bool  = False   # OFF by default (weekend report: SL killed wins)
        self.tp_pct:              float = 0.30
        self.sl_pct:              float = -0.15
        self.min_prob:            float = 0.87
        self.min_edge:            float = 0.05
        self.kelly_fraction:      float = 0.25
        self.protection_override: bool  = False
        # Straddle tunables (Hermes-controlled via nightly)
        # sell_threshold: winning side sells when bid >= entry * (1 + sell_threshold)
        # price_balance_max_dev: max deviation from 0.50 at entry. up_q must be
        #   in [0.50-dev, 0.50+dev]. e.g. 0.20 -> [0.30, 0.70]. Tighter = only
        #   straddle fresh markets; wider = more entries but more imbalanced.
        self.sell_threshold:        float = 0.05
        self.price_balance_max_dev: float = 0.20
        self.cut_loss_threshold:    float = 0.30   # sell loser if bid <= entry*(1-0.30)
        self.re_entry_threshold:    float = 0.05   # re-buy after sell if ask <= entry*(1-0.05)
        self.max_reentries_per_side: int  = 0     # Path B5: disabled — re-entries compound losses on directional days
        # Layer 3: Binance-direction-driven decisions (lag-arb).
        # When BTC moves >= winner_threshold since position entry in the SIDE'S
        # favor, sell that side on Polymarket (lock gain before market makers reprice).
        # When BTC moves >= loser_threshold AGAINST the side, cut that side.
        self.binance_winner_threshold: float = 0.002   # +0.2% BTC move = sell winner
        self.binance_loser_threshold:  float = 0.005   # +0.5% BTC move = cut loser
        # 2026-05-26 1s entry gate. Realized volatility over last vol_window_s
        # of 1s candles, expressed in bps of price. The straddle profits from
        # MOVEMENT (not direction) — calm windows lose to fees/spread, volatile
        # windows win. Setting min_1s_volatility_bps>0 skips entry when 1s vol
        # is below threshold. Setting 0 = gate disabled (still computes + logs
        # the signal so you can see analysis happening in the scanner logs).
        self.min_1s_volatility_bps: float = 0.0    # 0 = gate disabled, log only
        self.vol_window_s:          int   = 60     # seconds of 1s data to average
        # M1 contrarian-tilt straddle (default OFF — preserves existing behavior).
        # See _load_settings docstring for semantics.
        self.tilt_enabled:              bool  = False
        self.tilt_entry_secs_left_min:  float = 30.0
        self.tilt_entry_secs_left_max:  float = 120.0
        self.tilt_min_elapsed_s:        float = 60.0
        self.tilt_threshold_bps:        float = 5.0
        self.tilt_strength:             float = 0.6
        self.tilt_direction:            str   = 'momentum'
        # Pyramid-winner mode (default OFF — preserves straddle behavior).
        # When ON, the winning side is NOT sold at +sell_threshold; instead the
        # bot BUYS MORE of that side each time its bid crosses the next
        # +sell_threshold rung (entry*(1+st), *(1+2st), ...), up to
        # pyramid_max_adds times. Each add stakes stake*pyramid_add_fraction.
        # The losing side's cut-loss is unchanged, and the fast Binance lag-arb
        # WIN-sell is suppressed (else it sells the winner before any add fires).
        # Adds ride to market resolution like any straddle leg.
        self.pyramid_winner:            bool  = False
        self.pyramid_add_fraction:      float = 0.25
        self.pyramid_max_adds:          int   = 3
        # Last prediction snapshot for the UI
        self._last_prediction: dict = {}
        self._load_settings()
        self._load_matrix()
        self._load_log()
        # Re-seed entered_keys from pending trades. For straddles (pair_id set),
        # add the {slug}_PAIR key so we don't re-enter on the same market after
        # a bot restart. For legacy single-side trades, add the {slug}_{dir} key.
        for t in self._trades:
            if not t.get('resolved'):
                slug = t.get('market_slug', '')
                if t.get('pair_id'):
                    self._entered_keys.add(f"{slug}_PAIR")
                else:
                    self._entered_keys.add(f"{slug}_{t.get('direction','')}")
        # Background market cache thread
        _mt = threading.Thread(
            target=self._market_refresh_loop, daemon=True,
            name='btc-hermes-market-cache')
        _mt.start()
        logger.info(
            f'[{self._log}] init — markov samples={self.markov["n_samples"]} '
            f'p_uu={self.markov["p_uu"]:.3f} p_dd={self.markov["p_dd"]:.3f} '
            f'mode={"LIVE" if self.live_mode else "PAPER"} stake=${self.stake:.2f}'
        )

    # ── settings persistence ──────────────────────────────────────────────────

    def _load_settings(self):
        path = _resolve_state_path(self.SETTINGS_FILE)
        try:
            if os.path.exists(path):
                with open(path, 'r', encoding='utf-8') as f:
                    d = json.load(f)
                self.live_mode           = bool(d.get('live_mode', False))
                self.stake               = float(d.get('stake', self.PAPER_STAKE))
                self.tp_sl_enabled       = bool(d.get('tp_sl_enabled', False))
                self.tp_pct              = float(d.get('tp_pct', 0.30))
                self.sl_pct              = float(d.get('sl_pct', -0.15))
                self.min_prob            = float(d.get('min_prob', 0.87))
                self.min_edge            = float(d.get('min_edge', 0.05))
                self.kelly_fraction      = float(d.get('kelly_fraction', 0.25))
                self.protection_override = bool(d.get('protection_override', False))
                # Straddle tunables — Hermes nightly may have updated these
                self.sell_threshold        = float(d.get('sell_threshold', 0.05))
                self.price_balance_max_dev = float(d.get('price_balance_max_dev', 0.20))
                self.cut_loss_threshold    = float(d.get('cut_loss_threshold', 0.30))
                self.re_entry_threshold    = float(d.get('re_entry_threshold', 0.05))
                self.binance_winner_threshold = float(d.get('binance_winner_threshold', 0.002))
                self.binance_loser_threshold  = float(d.get('binance_loser_threshold', 0.005))
                self.min_1s_volatility_bps    = float(d.get('min_1s_volatility_bps', 0.0))
                try:
                    self.vol_window_s         = max(10, int(d.get('vol_window_s', 60)))
                except (TypeError, ValueError):
                    self.vol_window_s         = 60
                # ── M1: contrarian-tilt straddle (bonereaper replication, default OFF) ──
                # When tilt_enabled, scan_once uses tilt_entry_secs_left_* window instead
                # of the default 180-310s window, observes BTC slope from market open to
                # now, and tilts the UP/DOWN $-split AGAINST the slope direction when
                # |slope| > tilt_threshold_bps. Tilt_strength 0 = balanced; 0.6 = 80/20;
                # 1.0 = 100/0. Default OFF preserves existing straddle behavior.
                self.tilt_enabled              = bool(d.get('tilt_enabled', False))
                self.tilt_entry_secs_left_min  = float(d.get('tilt_entry_secs_left_min', 30.0))
                self.tilt_entry_secs_left_max  = float(d.get('tilt_entry_secs_left_max', 120.0))
                self.tilt_min_elapsed_s        = float(d.get('tilt_min_elapsed_s', 60.0))
                self.tilt_threshold_bps        = float(d.get('tilt_threshold_bps', 5.0))
                self.tilt_strength             = float(d.get('tilt_strength', 0.6))
                self.tilt_direction            = str(d.get('tilt_direction', 'momentum'))
                # ── Pyramid-winner mode (default OFF) ──
                self.pyramid_winner            = bool(d.get('pyramid_winner', False))
                self.pyramid_add_fraction      = float(d.get('pyramid_add_fraction', 0.25))
                try:
                    self.pyramid_max_adds      = max(0, int(d.get('pyramid_max_adds', 3)))
                except (TypeError, ValueError):
                    self.pyramid_max_adds      = 3
                # Hermes nightly may have refit the matrix — pick it up on each reload.
                self._load_matrix()
        except Exception as e:
            logger.warning(f'[{self._log}] settings load error: {e}')

    def _save_settings(self):
        path = _resolve_state_path(self.SETTINGS_FILE)
        try:
            with open(path, 'w', encoding='utf-8') as f:
                json.dump({
                    'live_mode':           self.live_mode,
                    'stake':               self.stake,
                    'tp_sl_enabled':       self.tp_sl_enabled,
                    'tp_pct':              self.tp_pct,
                    'sl_pct':              self.sl_pct,
                    'min_prob':            self.min_prob,
                    'min_edge':            self.min_edge,
                    'kelly_fraction':      self.kelly_fraction,
                    'protection_override': self.protection_override,
                    'sell_threshold':      self.sell_threshold,
                    'price_balance_max_dev': self.price_balance_max_dev,
                    'cut_loss_threshold':  self.cut_loss_threshold,
                    're_entry_threshold':  self.re_entry_threshold,
                    'binance_winner_threshold': self.binance_winner_threshold,
                    'binance_loser_threshold':  self.binance_loser_threshold,
                    'min_1s_volatility_bps':    self.min_1s_volatility_bps,
                    'vol_window_s':             self.vol_window_s,
                    'pyramid_winner':           self.pyramid_winner,
                    'pyramid_add_fraction':     self.pyramid_add_fraction,
                    'pyramid_max_adds':         self.pyramid_max_adds,
                }, f)
        except Exception as e:
            logger.warning(f'[{self._log}] settings save error: {e}')

    def _load_matrix(self):
        """Read btc_hermes_matrix.json into self.markov. Quiet on missing —
        bot starts cold; the Phase-3 nightly script populates on first run."""
        path = _resolve_state_path(self.MATRIX_FILE)
        if not os.path.exists(path):
            return
        try:
            with open(path, 'r', encoding='utf-8') as f:
                m = json.load(f)
            self.markov.update({
                'p_uu':             float(m.get('p_uu', 0.5)),
                'p_dd':             float(m.get('p_dd', 0.5)),
                'n_samples':        int(m.get('n_samples', 0)),
                'window_days':      int(m.get('window_days', 7)),
                'last_refit_ts':    m.get('last_refit_ts'),
                'binance_first_ts': m.get('binance_first_ts'),
                'binance_last_ts':  m.get('binance_last_ts'),
            })
        except Exception as e:
            logger.warning(f'[{self._log}] matrix load error: {e}')

    # ── trade log (async save) — mirrors BTCMLScanner pattern ─────────────────

    def _load_log(self):
        path = _resolve_state_path(self.LOG_FILE)
        try:
            if os.path.exists(path):
                with open(path, 'r', encoding='utf-8') as f:
                    self._trades = json.load(f)
                logger.info(f'[{self._log}] Loaded {len(self._trades)} trades from {os.path.basename(path)}')
        except Exception:
            self._trades = []

    def _save_log(self):
        if self._save_thread and self._save_thread.is_alive():
            self._request_save()
            return
        path = _resolve_state_path(self.LOG_FILE)
        try:
            _atomic_write_json(path, self._trades[-self.LOG_MAX_ENTRIES:], indent=False)
        except Exception as e:
            logger.warning(f'[{self._log}] save error: {e}')

    def _request_save(self):
        try:
            self._save_queue.put_nowait(True)
        except Exception:
            pass

    def _save_worker(self):
        import time as _t
        while True:
            try:
                self._save_queue.get(timeout=5)
            except Exception:
                continue
            try:
                with self._lock:
                    snapshot = list(self._trades[-self.LOG_MAX_ENTRIES:])
                path = _resolve_state_path(self.LOG_FILE)
                _atomic_write_json(path, snapshot, indent=False)
            except Exception as e:
                logger.warning(f'[{self._log}] async save error: {e}')
            _t.sleep(0.1)

    def start_save_worker(self):
        if self._save_thread and self._save_thread.is_alive():
            return
        self._save_thread = threading.Thread(
            target=self._save_worker, daemon=True, name='btc-hermes-save')
        self._save_thread.start()

    # ── Markov core ──────────────────────────────────────────────────────────

    def _markov_state(self) -> Optional[str]:
        """Return 'UP' or 'DOWN' = direction of the last CLOSED 5m candle.

        CORRECTNESS-CRITICAL OFF-BY-ONE: uses candles_5m[-2], NOT [-1].
        The [-1] element is the candle currently forming (its close changes
        every tick). The Polymarket "next 5m" market is conditioned on the
        most-recently-closed candle = [-2]. Using [-1] makes the prediction
        stale + correlates with the bet outcome → destroys edge.
        """
        candles = self._get_5m_candles()
        if not candles or len(candles) < 2:
            return None
        c = candles[-2]
        try:
            if isinstance(c, dict):
                o, cl = float(c.get('open')), float(c.get('close'))
            else:
                # list/tuple format from Binance klines: [openTime, o, h, l, c, v, ...]
                o, cl = float(c[1]), float(c[4])
        except (TypeError, ValueError, IndexError):
            return None
        return 'UP' if cl > o else 'DOWN'

    def _markov_predict(self, state: str) -> float:
        """Return persistence p(next=state | current=state) from the matrix."""
        if state == 'UP':
            return float(self.markov.get('p_uu', 0.5))
        elif state == 'DOWN':
            return float(self.markov.get('p_dd', 0.5))
        return 0.5

    def _get_5m_candles(self):
        """Shared 5m candle stream — borrowed from btc_ml_ref to avoid duplicate
        Binance polling. Returns None if reference not wired (Phase 2b will
        validate this is hooked up correctly)."""
        if self._btc_ml is not None and hasattr(self._btc_ml, '_get_candles'):
            try:
                return self._btc_ml._get_candles('5m', 60)
            except Exception as e:
                logger.debug(f'[{self._log}] candle fetch via btc_ml_ref err: {e}')
        return None

    def _compute_1s_vol_bps(self) -> Optional[float]:
        """Realized 1s volatility over the last vol_window_s of 1s candles,
        expressed in basis points of price. None if no data available.

        Pulled from btc_ml._binance_ws (shared aggTrade-built 1s stream — no
        extra WS subscription, no REST). Straddle profits from movement, so
        this signal is direction-agnostic: high = good window, low = skip.
        """
        if self._btc_ml is None or not hasattr(self._btc_ml, '_binance_ws'):
            return None
        try:
            ws = self._btc_ml._binance_ws
            if ws is None:
                return None
            candles = ws.get_candles('1s') or []
        except Exception as e:
            logger.debug(f'[{self._log}] 1s candle fetch err: {e}')
            return None
        window = max(10, int(getattr(self, 'vol_window_s', 60)))
        cs = candles[-window:]
        closes = []
        for c in cs:
            try:
                v = float(c.get('close') if isinstance(c, dict) else c[4])
                if v > 0:
                    closes.append(v)
            except (TypeError, ValueError, IndexError):
                continue
        if len(closes) < 5:  # need a few points for a stable std
            return None
        rets = [(closes[i] - closes[i-1]) / closes[i-1] for i in range(1, len(closes))]
        if len(rets) < 2:
            return None
        m = sum(rets) / len(rets)
        var = sum((r - m) ** 2 for r in rets) / (len(rets) - 1)
        std = var ** 0.5
        # Scale to window-realized vol (sqrt(N) * per-step std)
        return round(std * (len(rets) ** 0.5) * 10000, 2)

    # ── M1 contrarian-tilt straddle helpers ─────────────────────────────────

    def _compute_btc_slope_bps(self, window_open_ts: float) -> Optional[float]:
        """Slope from market open to now, in bps.

        slope = (price_now - price_at_open) / price_at_open * 10000

        Reads 1s candles from btc_ml._binance_ws. Picks the candle closest to
        (but not before) window_open_ts. Returns None if not enough history
        (e.g. bot just restarted) or btc_ml unavailable.

        Used by _compute_tilt for the M1 contrarian-entry signal. Step 0 v3
        on 30d of 1m BTC data showed mean reversion at strong slope thresholds:
        |slope| > 15 bps at +180s observation -> contrarian WR 57.67%.
        """
        if self._btc_ml is None or not hasattr(self._btc_ml, '_binance_ws'):
            return None
        try:
            ws = self._btc_ml._binance_ws
            if ws is None:
                return None
            candles = ws.get_candles('1s') or []
        except Exception as e:
            logger.debug(f'[{self._log}] slope candle fetch err: {e}')
            return None
        if not candles:
            return None
        # candles are dicts with 'time' (1s epoch second) and 'close'.
        # Find the candle at or just after window_open_ts; use its close as p_open.
        p_open = None
        for c in candles:
            try:
                t = float(c.get('time', 0))
                if t >= window_open_ts:
                    p_open = float(c.get('close', 0)) or float(c.get('open', 0))
                    break
            except (TypeError, ValueError):
                continue
        if p_open is None or p_open <= 0:
            return None
        # Current price from the most recent candle
        try:
            p_now = float(candles[-1].get('close', 0)) or float(candles[-1].get('open', 0))
        except (TypeError, ValueError):
            return None
        if p_now <= 0:
            return None
        return round((p_now - p_open) / p_open * 1e4, 2)

    def _compute_tilt(self, market_end_ts: float, secs_left: float) -> dict:
        """Decide entry UP-fraction based on BTC slope since market open.

        Returns a dict:
          up_fraction: float in [tilt_floor, 1-tilt_floor]  (0.5 = balanced)
          slope_bps:   float or None
          elapsed_s:   float
          tilt_reason: str
          tilt_taken:  bool
        """
        WINDOW_S = 300  # 5m markets
        window_open_ts = float(market_end_ts) - WINDOW_S
        now_ts = time.time()
        elapsed = now_ts - window_open_ts
        out = {
            'up_fraction': 0.5,
            'slope_bps':   None,
            'elapsed_s':   round(elapsed, 1),
            'tilt_reason': '',
            'tilt_taken':  False,
        }
        # Need at least tilt_min_elapsed_s of price action to compute slope
        if elapsed < self.tilt_min_elapsed_s:
            out['tilt_reason'] = f'elapsed {elapsed:.0f}s < min {self.tilt_min_elapsed_s:.0f}s, balanced'
            return out
        slope = self._compute_btc_slope_bps(window_open_ts)
        out['slope_bps'] = slope
        if slope is None:
            out['tilt_reason'] = 'no slope available, balanced'
            return out
        if abs(slope) < float(self.tilt_threshold_bps):
            out['tilt_reason'] = f'|slope|={abs(slope):.1f} < {self.tilt_threshold_bps:.1f}, balanced'
            return out
        # Strong slope. Tilt direction: contrarian (against slope) or momentum (with).
        direction_factor = -1.0 if self.tilt_direction == 'contrarian' else 1.0
        strength = max(0.0, min(1.0, float(self.tilt_strength)))
        # Slope positive + contrarian -> tilt to DOWN (up_fraction < 0.5)
        # Slope positive + momentum   -> tilt to UP   (up_fraction > 0.5)
        signed = (1.0 if slope > 0 else -1.0) * direction_factor
        up_fraction = 0.5 + signed * 0.5 * strength
        # Clamp [tilt_floor, 1 - tilt_floor] to avoid 100/0
        FLOOR = 0.10
        up_fraction = max(FLOOR, min(1 - FLOOR, up_fraction))
        out['up_fraction'] = round(up_fraction, 4)
        out['tilt_taken']  = True
        out['tilt_reason'] = (f'slope={slope:+.1f}bps {self.tilt_direction} '
                              f'-> up_fraction={up_fraction:.2f}')
        return out

    # ── Kelly sizing ─────────────────────────────────────────────────────────

    def _kelly_stake(self, p: float, q: float) -> float:
        """Edge-based Kelly: f* = (p - q) / (1 - q).

        Stake = kelly_fraction * f* * bankroll, clamped to [floor, user_max].
        User-configured self.stake is the HARD CEILING (same pattern shipped
        for HFT _kelly_stake at file:9098 on 2026-05-24).

        Returns the floor (capped to user_max) if edge is non-positive or q≈1.
        """
        try:
            _max = float(self.stake)
            _min = min(self.KELLY_MIN_STAKE, _max)
            if q >= 0.99 or p <= q:
                return _min
            kelly_f = (p - q) / (1.0 - q)
            # Bankroll: live USDC if available, else 75x stake fallback
            bankroll = self.stake * 75
            if self.bot is not None:
                try:
                    bal = self.bot.get_usdc_balance(max_age=120)
                    if bal and bal > 0:
                        bankroll = bal
                except Exception:
                    pass
            raw = self.kelly_fraction * kelly_f * bankroll
            stake = round(max(min(raw, _max), _min), 2)
            return stake
        except Exception as e:
            logger.debug(f'[{self._log}-KELLY] error: {e} — using user stake')
            return float(self.stake)

    # ── background market cache ──────────────────────────────────────────────

    def _market_refresh_loop(self):
        """Refresh active BTC 5m Polymarket markets every 3s."""
        import time as _t
        _t.sleep(3)
        while True:
            try:
                fresh = self._fetch_active_markets()
                with self._market_bg_lock:
                    self._market_bg_cache = fresh
            except Exception as e:
                logger.debug(f'[{self._log}] market refresh error: {e}')
            _t.sleep(3)

    def _fetch_active_markets(self) -> list:
        """Discover currently-active 5m BTC up/down Polymarket markets.
        Phase 2a: defers to btc_ml_ref's market cache, filtering to 5m slugs only
        (BTC-ML scans both 5m and 15m; HERMES is 5m-only). Phase 2b may replace
        with an independent fetcher if shared cache turns out to be lossy."""
        if self._btc_ml is None:
            return []
        try:
            with self._btc_ml._market_bg_lock:
                btc_ml_markets = list(self._btc_ml._market_bg_cache)
        except Exception:
            return []
        return [m for m in btc_ml_markets
                if '-updown-5m-' in (m.get('slug') or m.get('market_slug') or '')]

    # ── Polymarket integration helpers ───────────────────────────────────────

    def _get_yes_price_and_tokens(self, market: dict) -> tuple:
        """Return (yes_price, yes_token_id, no_token_id). Sets market['_yes_token_id'].
        Verbatim from BTCMLScanner._get_yes_price_and_tokens (file:12557 of original).
        Uses self._clob_ws WS cache when subscribed, HTTP /book fallback otherwise."""
        tokens = market.get('tokens') or []
        yes_tid = no_tid = None
        if tokens:
            if isinstance(tokens[0], dict):
                for tok in tokens:
                    outcome = tok.get('outcome', '').lower()
                    tid = tok.get('tokenId') or tok.get('token_id')
                    if outcome in ('yes', 'up'):    yes_tid = tid
                    elif outcome in ('no', 'down'): no_tid  = tid
                if not yes_tid and tokens:
                    yes_tid = tokens[0].get('tokenId') or tokens[0].get('token_id')
            else:
                yes_tid = str(tokens[0]) if len(tokens) > 0 else None
                no_tid  = str(tokens[1]) if len(tokens) > 1 else None
        market['_yes_token_id'] = yes_tid
        market['_no_token_id']  = no_tid

        if yes_tid:
            if self._clob_ws:
                # Subscribe BOTH tokens — straddle needs live prices on both
                # YES (UP side) and NO (DOWN side) for _check_winner_sells.
                # Without this, DOWN-side sell checks fall back to HTTP (50-500ms latency).
                self._clob_ws.subscribe(yes_tid)
                if no_tid:
                    self._clob_ws.subscribe(no_tid)
                ws_ask = self._clob_ws.get_ask(yes_tid)
                if ws_ask is not None:
                    market['_live_yes_ask']  = ws_ask
                    market['_price_source']  = 'ws'
                    return ws_ask, yes_tid, no_tid
            try:
                cached_book = self._book_cache.get(yes_tid)
                if cached_book and time.time() - cached_book[1] < 1.5:
                    book = cached_book[0]
                else:
                    resp = self._session.get(
                        'https://clob.polymarket.com/book',
                        params={'token_id': yes_tid}, timeout=3)
                    if resp.status_code == 200:
                        book = resp.json()
                        self._book_cache[yes_tid] = (book, time.time())
                    else:
                        book = None
                if book:
                    asks = book.get('asks', [])
                    if asks:
                        price = float(sorted(asks, key=lambda x: float(x.get('price', 999)))[0]['price'])
                        market['_live_yes_ask'] = price
                        return price, yes_tid, no_tid
            except Exception:
                pass

        prices = market.get('outcomePrices', [])
        if prices:
            try:
                return float(prices[0]), yes_tid, no_tid
            except Exception:
                pass
        return 0.0, yes_tid, no_tid

    def _resolve_one(self, t: dict):
        """Resolve a single trade via Gamma API. Returns 'WIN' | 'LOSS' | 'PUSH' | None.
        Verbatim from BTCMLScanner._resolve_one (file:13314 of original)."""
        now_ts = time.time()
        end_ts = t.get('market_end_ts', 0)
        if end_ts and now_ts < end_ts + 30:
            return None
        slug      = t.get('market_slug', '')
        direction = t.get('direction', 'UP').upper()
        if not slug:
            return None
        try:
            r = self._session.get(
                f"{self.GAMMA}/events", params={'slug': slug}, timeout=4)
            if r.status_code != 200:
                return None
            events = r.json()
            event  = events[0] if isinstance(events, list) and events else None
            if not event:
                return None
            mkt = (event.get('markets') or [None])[0]
            if not mkt:
                return None
            closed         = mkt.get('closed', False)
            out_prices_raw = mkt.get('outcomePrices', '[]')
            outcomes_raw   = mkt.get('outcomes', '["Up","Down"]')
            if isinstance(out_prices_raw, str):
                try: out_prices = [float(x) for x in json.loads(out_prices_raw)]
                except Exception: out_prices = []
            else:
                out_prices = [float(x) for x in (out_prices_raw or [])]
            if isinstance(outcomes_raw, str):
                try: outcomes = json.loads(outcomes_raw)
                except Exception: outcomes = []
            else:
                outcomes = list(outcomes_raw or [])
            for i, o in enumerate(outcomes):
                if o.upper() == direction and i < len(out_prices):
                    px = out_prices[i]
                    if px >= 0.99:   return 'WIN'
                    elif px <= 0.01: return 'LOSS'
                    elif closed:     return 'PUSH'
                    return None
        except Exception as e:
            logger.debug(f'[{self._log}] Resolve error {slug}: {e}')
        return None

    def _paper_enter(self, slug, direction, entry_price, p, q, edge,
                      secs_left, end_ts, token_id, state):
        """Record a paper trade with full Markov context. Guarded by xbot
        cross-bot lock so HERMES + BTC-ML never double-bet the same slug."""
        import uuid as _uuid
        _xb_ok, _xb_reason = _xbot_check(slug, direction, self._log)
        if not _xb_ok:
            logger.debug(f'[{self._log}] SKIPPED {direction} {slug[:40]} — {_xb_reason}')
            return
        stake = self._kelly_stake(p, q)
        if stake <= 0:
            return
        kelly_f = (p - q) / (1.0 - q) if q < 0.99 and p > q else 0.0
        hr   = datetime.now(timezone.utc).hour
        sess = ('ASIA' if 0 <= hr < 8 else 'US_OPEN' if 8 <= hr < 12
                else 'US_AFT' if 12 <= hr < 20 else 'OVERNIGHT')
        trade = {
            'id':              _uuid.uuid4().hex[:12],
            'logged_at':       datetime.now(timezone.utc).isoformat(),
            'fill_hour':       hr,
            'fill_session':    sess,
            'symbol':          self.SYMBOL,
            'market_slug':     slug,
            'timeframe':       '5m',
            'strategy':        self._log,
            'direction':       direction,
            'entry_price':     entry_price,
            'stake':           stake,
            'shares':          round(stake / (entry_price * (1 + self.FEE_RATE)), 4) if entry_price > 0 else 0,
            'secs_to_close':   round(secs_left, 1),
            'market_end_ts':   end_ts,
            'token_id':        token_id,
            'real_trade':      False,
            'resolved':        False,
            'outcome':         None,
            'exit_price':      None,
            'paper_pnl':       None,
            # Markov-specific (replaces ML's ml_prob/ml_features)
            'markov_state':    state,
            'markov_p':        round(p, 4),
            'market_q':        round(q, 4),
            'edge':            round(edge, 4),
            'kelly_f_star':    round(kelly_f, 4),
            'matrix_samples':  self.markov.get('n_samples'),
        }
        with self._lock:
            self._trades.append(trade)
            self._save_log()
            self._entered_keys.add(f"{slug}_{direction}")
        logger.info(
            f'[{self._log}] PAPER {direction} @ q={q:.3f} p={p:.3f} edge={edge:+.3f} '
            f'({secs_left:.0f}s left) stake=${stake}'
        )

    # ── trading loop — STUBS for Phase 2b ────────────────────────────────────

    def scan_once(self, triggered: bool = False):
        """STRADDLE strategy (Phase 6): buy BOTH UP and DOWN at 5m market open,
        sell the winning side when its bid moves +5% from entry, hold loser
        to market resolution.

        Per scan:
          (1) For each open straddle side: poll current bid, sell if it
              reached entry_price * 1.05.
          (2) For each NEW 5m market in entry window (secs_left in [240, 300]):
              buy 50/50 paired entry if not already entered.
        """
        try:
            now_ts = time.time()
            if triggered:
                if now_ts - self._last_triggered_ts < 0.5:
                    return
                self._last_triggered_ts = now_ts
            self._scan_event.clear()
            self._scan_count += 1
            self._last_scan_ts = now_ts

            if self._scan_count % 75 == 0:
                self._load_settings()

            # (1) Check existing open positions for +5% sell / cut-loss trigger
            try:
                self._check_winner_sells()
            except Exception as _se:
                logger.debug(f'[{self._log}] sell-check err: {_se}')

            # (1b) Check for re-entry opportunities on previously-sold sides
            try:
                self._check_reentries()
            except Exception as _re:
                logger.debug(f'[{self._log}] reentry-check err: {_re}')

            # (2) Look for new 5m markets to straddle
            with self._market_bg_lock:
                markets = list(self._market_bg_cache)
            if not markets:
                markets = self._fetch_active_markets()
            entry_candidates = []
            for m in markets:
                try:
                    end_ts = float(m.get('end_ts') or m.get('market_end_ts') or 0)
                except (TypeError, ValueError):
                    continue
                secs_left = end_ts - now_ts
                # Entry window selection:
                #   - Default straddle: 180-310s left (enter early, near open)
                #   - tilt_enabled (M1): 30-120s left (enter late, after observing
                #     enough BTC slope to know which side to tilt against).
                # _entered_keys prevents re-entry on the same slug.
                if self.tilt_enabled:
                    if secs_left < self.tilt_entry_secs_left_min or secs_left > self.tilt_entry_secs_left_max:
                        continue
                else:
                    if secs_left < 180 or secs_left > 310:
                        continue
                m['_secs_left'] = secs_left
                m['_end_ts']    = end_ts
                entry_candidates.append(m)

            state = self._markov_state()
            p     = self._markov_predict(state) if state else None

            if not entry_candidates:
                self._last_prediction = {
                    'ts': now_ts, 'state': state,
                    'p': round(p, 4) if p else None,
                    'q': None, 'edge': None, 'slug': None, 'secs_left': None,
                    'would_enter': False,
                    'reason': f'no markets in entry window ({len(markets)} active)',
                }
                return

            for m in entry_candidates:
                slug = m.get('slug') or m.get('market_slug') or ''
                if not slug:
                    continue
                if f'{slug}_PAIR' in self._entered_keys:
                    continue
                yes_price, yes_tid, no_tid = self._get_yes_price_and_tokens(m)
                if yes_price <= 0 or not yes_tid or not no_tid:
                    continue
                up_q   = yes_price
                down_q = 1.0 - yes_price
                # Price-balance filter: only enter when market is near 50/50.
                # max_dev is Hermes-tuned; bounds = [0.50 - dev, 0.50 + dev].
                # Tighter dev = only enter on fresh markets; wider = catch more.
                _dev = float(self.price_balance_max_dev)
                _lo, _hi = 0.50 - _dev, 0.50 + _dev
                if up_q < _lo or up_q > _hi:
                    self._last_prediction = {
                        'ts': now_ts, 'state': state,
                        'p': round(p, 4) if p else None,
                        'q': round(up_q, 4), 'edge': None,
                        'slug': slug, 'secs_left': round(m['_secs_left'], 1),
                        'would_enter': False,
                        'reason': f'market too imbalanced for straddle (up_q={up_q:.3f}, want [{_lo:.2f}, {_hi:.2f}])',
                    }
                    continue
                # 1s volatility gate. Always compute (so analysis surfaces in
                # logs + state API); skip entry only if min_1s_volatility_bps>0
                # and current vol is below it. Straddle profits from movement,
                # so this signal is direction-agnostic — high vol = enter.
                vol_bps   = self._compute_1s_vol_bps()
                vol_floor = float(getattr(self, 'min_1s_volatility_bps', 0.0) or 0.0)
                if vol_floor > 0 and vol_bps is not None and vol_bps < vol_floor:
                    self._last_prediction = {
                        'ts': now_ts, 'state': state,
                        'p': round(p, 4) if p else None,
                        'q': round(up_q, 4), 'edge': None,
                        'slug': slug, 'secs_left': round(m['_secs_left'], 1),
                        'vol_1s_bps': vol_bps, 'vol_floor_bps': vol_floor,
                        'would_enter': False,
                        'reason': f'1s vol {vol_bps:.2f}bps < floor {vol_floor:.2f}bps (calm window — skip)',
                    }
                    logger.info(
                        f'[{self._log}] SKIP {slug[:40]} — 1s vol {vol_bps:.2f}bps < '
                        f'floor {vol_floor:.2f}bps ({self.vol_window_s}s window)'
                    )
                    continue
                self._last_prediction = {
                    'ts': now_ts, 'state': state,
                    'p': round(p, 4) if p else None,
                    'q': round(up_q, 4), 'edge': None,
                    'slug': slug, 'secs_left': round(m['_secs_left'], 1),
                    'vol_1s_bps': vol_bps, 'vol_floor_bps': vol_floor,
                    'would_enter': True,
                    'reason': (f'opening straddle (up_q={up_q:.3f}, down_q={down_q:.3f}, '
                               f'1s vol={vol_bps:.2f}bps)' if vol_bps is not None
                               else f'opening straddle (up_q={up_q:.3f}, down_q={down_q:.3f})'),
                }
                _xb_ok, _xb_reason = _xbot_check(slug, 'UP', self._log)
                if not _xb_ok:
                    logger.debug(f'[{self._log}] SKIP {slug[:40]}: {_xb_reason}')
                    continue
                tilt = self._compute_tilt(m['_end_ts'], m['_secs_left']) if self.tilt_enabled else None
                if tilt is not None:
                    self._last_prediction['tilt'] = tilt
                self._enter_pair(
                    slug=slug, end_ts=m['_end_ts'], secs_left=m['_secs_left'],
                    up_q=up_q, down_q=down_q, up_tid=yes_tid, down_tid=no_tid,
                    entry_vol_bps=vol_bps, tilt=tilt,
                )

        except Exception as e:
            logger.warning(f'[{self._log}] scan_once error: {e}')

    def _enter_pair(self, slug, end_ts, secs_left, up_q, down_q, up_tid, down_tid,
                    entry_vol_bps=None, tilt=None):
        """Record a straddle as two trade records (UP + DOWN) sharing one pair_id.

        If `tilt` is provided (from _compute_tilt), the per-side stakes are
        split asymmetrically: up_stake = 2 * stake * up_fraction, down_stake =
        2 * stake * (1 - up_fraction). At up_fraction=0.5 the math gives the
        original balanced behavior (each side = self.stake).
        """
        import uuid as _uuid
        pair_id = _uuid.uuid4().hex[:12]
        if tilt is not None and tilt.get('tilt_taken'):
            uf = float(tilt.get('up_fraction', 0.5))
            up_stake   = round(2.0 * float(self.stake) * uf, 2)
            down_stake = round(2.0 * float(self.stake) * (1.0 - uf), 2)
        else:
            up_stake = down_stake = float(self.stake)
        stake_per_side = float(self.stake)  # preserved for legacy log fields below
        hr   = datetime.now(timezone.utc).hour
        sess = ('ASIA' if 0 <= hr < 8 else 'US_OPEN' if 8 <= hr < 12
                else 'US_AFT' if 12 <= hr < 20 else 'OVERNIGHT')
        # Capture BTC price at entry for Binance-driven sell decisions (layer 3)
        btc_at_entry = None
        if self._btc_ml is not None and hasattr(self._btc_ml, '_binance_ws'):
            try:
                _wsc = self._btc_ml._binance_ws.get_candles('1m')
                if _wsc:
                    btc_at_entry = float(_wsc[-1].get('close', 0))
            except Exception:
                pass
        common = {
            'pair_id':       pair_id,
            'btc_at_entry':  btc_at_entry,
            'logged_at':     datetime.now(timezone.utc).isoformat(),
            'fill_hour':     hr,
            'fill_session':  sess,
            'symbol':        self.SYMBOL,
            'market_slug':   slug,
            'timeframe':     '5m',
            'strategy':      self._log,
            'secs_to_close': round(secs_left, 1),
            'market_end_ts': end_ts,
            'real_trade':    False,
            'resolved':      False,
            'outcome':       None,
            'exit_price':    None,
            'exit_ts':       None,
            'exit_reason':   None,
            'paper_pnl':     None,
            'entry_vol_1s_bps': entry_vol_bps,
        }
        # Carry tilt diagnostics on both legs for later attribution analysis.
        tilt_fields = {}
        if tilt is not None:
            tilt_fields = {
                'tilt_taken':    bool(tilt.get('tilt_taken', False)),
                'tilt_slope_bps': tilt.get('slope_bps'),
                'tilt_elapsed_s': tilt.get('elapsed_s'),
                'tilt_up_fraction': tilt.get('up_fraction'),
                'tilt_direction': str(self.tilt_direction),
            }
        up_trade = {
            **common, **tilt_fields, 'id': _uuid.uuid4().hex[:12],
            'side':        'UP', 'direction': 'UP',
            'entry_price': round(up_q, 4),
            'stake':       round(up_stake, 2),
            'shares':      round(up_stake / up_q, 4) if up_q > 0 else 0,
            'token_id':    up_tid,
        }
        down_trade = {
            **common, **tilt_fields, 'id': _uuid.uuid4().hex[:12],
            'side':        'DOWN', 'direction': 'DOWN',
            'entry_price': round(down_q, 4),
            'stake':       round(down_stake, 2),
            'shares':      round(down_stake / down_q, 4) if down_q > 0 else 0,
            'token_id':    down_tid,
        }
        with self._lock:
            self._trades.append(up_trade)
            self._trades.append(down_trade)
            self._save_log()
            self._entered_keys.add(f'{slug}_PAIR')
        if tilt is not None and tilt.get('tilt_taken'):
            logger.info(
                f'[{self._log}] TILT-STRADDLE {slug[:40]} pair={pair_id} '
                f'UP @ {up_q:.3f} (${up_stake:.2f}) + '
                f'DOWN @ {down_q:.3f} (${down_stake:.2f}) '
                f'({secs_left:.0f}s left) '
                f'[{tilt.get("tilt_reason","")}]'
            )
        else:
            logger.info(
                f'[{self._log}] STRADDLE {slug[:40]} pair={pair_id} '
                f'UP @ {up_q:.3f} (${up_stake:.2f}) + '
                f'DOWN @ {down_q:.3f} (${down_stake:.2f}) '
                f'({secs_left:.0f}s left)'
            )

    def _check_winner_sells(self):
        """Poll current bid on each open straddle side; sell if bid >= entry * (1 + self.sell_threshold).
        Loser side stays unsold and resolves naturally at market close."""
        SELL_THRESHOLD = float(self.sell_threshold)
        with self._lock:
            open_sides = [t for t in self._trades
                          if t.get('pair_id') and not t.get('resolved')
                          and not t.get('exit_price') and t.get('token_id')]
        if not open_sides:
            return
        changed = False
        for t in open_sides:
            tid = t.get('token_id')
            if not tid:
                continue
            cur_price = None
            if self._clob_ws:
                try:
                    cur_price = self._clob_ws.get_bid(tid)
                except Exception:
                    cur_price = None
            if cur_price is None:
                try:
                    r = self._session.get(
                        'https://clob.polymarket.com/book',
                        params={'token_id': tid}, timeout=3)
                    if r.status_code == 200:
                        bids = r.json().get('bids', [])
                        if bids:
                            cur_price = max(float(b.get('price', 0)) for b in bids)
                except Exception:
                    cur_price = None
            if cur_price is None or cur_price <= 0:
                continue
            entry = float(t.get('entry_price') or 0)
            if entry <= 0:
                continue
            CUT_LOSS = float(self.cut_loss_threshold)
            sell_reason = None
            if cur_price >= entry * (1 + SELL_THRESHOLD):
                if getattr(self, 'pyramid_winner', False):
                    # Pyramid mode: do NOT sell the winner — buy more at each
                    # +SELL_THRESHOLD rung. Drive adds off the BASE leg only so
                    # adds don't compound on adds. Add-records with a gain just
                    # ride (no sell). Cut-loss below still protects on reversal.
                    if not t.get('pyramid_add'):
                        try:
                            self._maybe_pyramid_add(t, entry, cur_price)
                        except Exception as _pe:
                            logger.debug(f'[{self._log}] pyramid-add err: {_pe}')
                    continue
                sell_reason = f'+{SELL_THRESHOLD*100:.1f}pct gain (entry={entry:.3f} -> bid={cur_price:.3f})'
            elif cur_price <= entry * (1 - CUT_LOSS):
                sell_reason = f'CUT-LOSS -{CUT_LOSS*100:.0f}pct (entry={entry:.3f} -> bid={cur_price:.3f})'
            if sell_reason:
                shares   = float(t.get('shares') or 0)
                proceeds = round(shares * cur_price, 4)
                cost     = float(t.get('stake') or 0)
                pnl      = round(proceeds - cost, 4)
                t['exit_price']  = round(cur_price, 4)
                t['exit_ts']     = datetime.now(timezone.utc).isoformat()
                t['exit_reason'] = sell_reason
                t['paper_pnl']   = pnl
                t['side_exited'] = True
                changed = True
                tag = 'CUT' if 'CUT-LOSS' in sell_reason else 'SELL'
                logger.info(
                    f'[{self._log}] {tag} {t.get("market_slug","")[:40]} {t.get("side")} '
                    f'@ {cur_price:.3f} (entry {entry:.3f}) shares={shares:.2f} '
                    f'pnl=$' + f'{pnl:+.2f}'
                )
        if changed:
            with self._lock:
                self._save_log()

    def _maybe_pyramid_add(self, base_trade, entry, cur_bid):
        """Pyramid mode: buy MORE of a winning straddle leg instead of selling.
        Called from _check_winner_sells when a BASE leg's bid has crossed the
        +sell_threshold gain rung. Adds one buy each time bid crosses the next
        rung (entry*(1+st), entry*(1+2*st), ...), up to pyramid_max_adds, each
        staking stake*pyramid_add_fraction at the current ask. The add resolves
        to $1/$0 at market close like any leg; the loser-cut still protects it."""
        import uuid as _uuid
        pid    = base_trade.get('pair_id')
        side   = base_trade.get('side')
        tid    = base_trade.get('token_id')
        slug   = base_trade.get('market_slug', '')
        end_ts = float(base_trade.get('market_end_ts') or 0)
        if not (pid and side and tid):
            return
        now_ts = time.time()
        if end_ts and now_ts >= end_ts - 5:
            return  # market about to close — don't add at the bell
        st       = float(self.sell_threshold)
        max_adds = int(getattr(self, 'pyramid_max_adds', 3))
        frac     = float(getattr(self, 'pyramid_add_fraction', 0.25))
        # Count adds already placed on this (pair, side)
        with self._lock:
            n_adds = sum(1 for r in self._trades
                         if r.get('pair_id') == pid and r.get('side') == side
                         and r.get('pyramid_add'))
        if n_adds >= max_adds:
            return  # cap reached — ride to resolution
        # Require bid to have crossed the NEXT rung before adding again
        next_rung = entry * (1.0 + st * (n_adds + 1))
        if cur_bid < next_rung:
            return
        # Buy at the current ASK (we're buying). WS ask if available, else book.
        ask = None
        if self._clob_ws:
            try:
                ask = self._clob_ws.get_ask(tid)
            except Exception:
                ask = None
        if ask is None or ask <= 0:
            try:
                r = self._session.get(
                    'https://clob.polymarket.com/book',
                    params={'token_id': tid}, timeout=3)
                if r.status_code == 200:
                    asks = r.json().get('asks', [])
                    if asks:
                        ask = min(float(a.get('price', 999)) for a in asks)
            except Exception:
                ask = None
        if ask is None or ask <= 0 or ask >= 1.0:
            return
        add_stake = round(float(self.stake) * frac, 2)
        shares    = round(add_stake / ask, 4) if ask > 0 else 0
        if add_stake <= 0 or shares <= 0:
            return
        # BTC price now (for the add's own lag-arb loser-cut reference)
        btc_now = None
        if self._btc_ml is not None and hasattr(self._btc_ml, '_binance_ws'):
            try:
                _wsc = self._btc_ml._binance_ws.get_candles('1m')
                if _wsc:
                    btc_now = float(_wsc[-1].get('close', 0))
            except Exception:
                btc_now = None
        hr = datetime.now(timezone.utc).hour
        sess = ('ASIA' if 0 <= hr < 8 else 'US_OPEN' if 8 <= hr < 12
                else 'US_AFT' if 12 <= hr < 20 else 'OVERNIGHT')
        add_trade = {
            'id':            _uuid.uuid4().hex[:12],
            'pair_id':       pid,
            'side':          side,
            'direction':     side,
            'logged_at':     datetime.now(timezone.utc).isoformat(),
            'fill_hour':     hr,
            'fill_session':  sess,
            'symbol':        self.SYMBOL,
            'market_slug':   slug,
            'timeframe':     '5m',
            'strategy':      self._log,
            'secs_to_close': round(max(0.0, end_ts - now_ts), 1),
            'market_end_ts': end_ts,
            'btc_at_entry':  btc_now,
            'real_trade':    False,
            'resolved':      False,
            'outcome':       None,
            'exit_price':    None,
            'exit_ts':       None,
            'exit_reason':   None,
            'paper_pnl':     None,
            'entry_price':   round(ask, 4),
            'stake':         round(add_stake, 2),
            'shares':        shares,
            'token_id':      tid,
            'pyramid_add':   True,
            'pyramid_n':     n_adds + 1,
            'base_entry':    round(float(entry), 4),
        }
        with self._lock:
            self._trades.append(add_trade)
            self._save_log()
        logger.info(
            f'[{self._log}] PYRAMID-ADD {slug[:40]} {side} #{n_adds + 1}/{max_adds} '
            f'@ {ask:.3f} (base entry {entry:.3f}, rung {next_rung:.3f}, '
            f'bid {cur_bid:.3f}) ${add_stake:.2f} shares={shares:.2f}'
        )

    def _on_binance_tick(self, price: float, pct: float, direction: str):
        """Layer 3 callback: runs in BinancePriceWS thread on every BTC move
        >= 0.10%. For each open straddle side, compute BTC delta from entry
        and trigger Polymarket sell/cut WITHOUT waiting for Polymarket bid to
        reprice. Uses CLOB WS bid (both tokens are subscribed) for execution
        price. Race-safe via self._lock."""
        try:
            btc_now = float(price)
            if btc_now <= 0:
                return
        except Exception:
            return
        WIN_TH  = float(self.binance_winner_threshold)
        LOSE_TH = float(self.binance_loser_threshold)
        with self._lock:
            open_sides = [t for t in self._trades
                          if t.get('pair_id') and not t.get('resolved')
                          and not t.get('exit_price') and t.get('token_id')
                          and t.get('btc_at_entry')]
        if not open_sides:
            return
        changed = False
        for t in open_sides:
            try:
                btc_at_entry = float(t.get('btc_at_entry') or 0)
                if btc_at_entry <= 0:
                    continue
                btc_delta = (btc_now - btc_at_entry) / btc_at_entry
                side = t.get('side')
                # Determine if this side is the winner or loser given the move
                if side == 'UP':
                    is_winning = btc_delta > 0
                elif side == 'DOWN':
                    is_winning = btc_delta < 0
                else:
                    continue
                move_abs = abs(btc_delta)
                # Winner: BTC moved >= WIN_TH in our direction -> sell now
                # Loser: BTC moved >= LOSE_TH against us -> cut now
                trigger = None
                if is_winning and move_abs >= WIN_TH:
                    trigger = 'WIN'
                elif (not is_winning) and move_abs >= LOSE_TH:
                    trigger = 'LOSE'
                # Pyramid mode: don't fast-sell winners via lag-arb — winners
                # ride to resolution and get pyramided by _check_winner_sells.
                # The LOSE trigger (cut loser) still runs.
                if trigger == 'WIN' and getattr(self, 'pyramid_winner', False):
                    continue
                if not trigger:
                    continue
                # Get current Polymarket bid via WS (token IS subscribed now)
                tid = t.get('token_id')
                cur_bid = None
                if self._clob_ws and tid:
                    try:
                        cur_bid = self._clob_ws.get_bid(tid)
                    except Exception:
                        cur_bid = None
                if cur_bid is None or cur_bid <= 0:
                    continue  # no WS bid available, skip (next scan will catch via HTTP)
                entry = float(t.get('entry_price') or 0)
                if entry <= 0:
                    continue
                shares   = float(t.get('shares') or 0)
                proceeds = round(shares * cur_bid, 4)
                cost     = float(t.get('stake') or 0)
                pnl      = round(proceeds - cost, 4)
                # Only sell if at least breakeven for WIN trigger; always sell for LOSE trigger
                if trigger == 'WIN' and pnl < 0:
                    continue  # winner trigger fired but Polymarket bid not yet caught up
                reason = (f'LAG-ARB WIN: BTC {btc_delta*100:+.2f}% favors {side}, sell @ {cur_bid:.3f}'
                          if trigger == 'WIN' else
                          f'LAG-ARB CUT: BTC {btc_delta*100:+.2f}% against {side}, cut @ {cur_bid:.3f}')
                t['exit_price']  = round(cur_bid, 4)
                t['exit_ts']     = datetime.now(timezone.utc).isoformat()
                t['exit_reason'] = reason
                t['paper_pnl']   = pnl
                t['side_exited'] = True
                changed = True
                tag = 'LAG-WIN' if trigger == 'WIN' else 'LAG-CUT'
                logger.info(
                    f'[{self._log}] {tag} {t.get("market_slug","")[:40]} {side} '
                    f'btc_delta={btc_delta*100:+.2f}% @ bid={cur_bid:.3f} (entry {entry:.3f}) '
                    f'pnl=$' + f'{pnl:+.2f}'
                )
            except Exception as _e:
                logger.debug(f'[{self._log}] lag-arb tick err: {_e}')
        if changed:
            with self._lock:
                self._save_log()

    def _check_reentries(self):
        """After a side was sold, allow re-buying that side IF current ask
        has pulled back to entry*(1-re_entry_threshold) or lower. This creates
        a scalping loop: buy -> sell at +5% -> wait for pullback -> re-buy ->
        sell again. Limited per (pair, side) to max_reentries_per_side."""
        RE_TH = float(self.re_entry_threshold)
        MAX_R = int(getattr(self, 'max_reentries_per_side', 5))
        import uuid as _uuid
        now_ts = time.time()
        with self._lock:
            # Group trades by (pair_id, side) and find the LATEST entry
            from collections import defaultdict
            by_key = defaultdict(list)
            for t in self._trades:
                pid = t.get('pair_id')
                side = t.get('side')
                if pid and side:
                    by_key[(pid, side)].append(t)
        # Find candidates: latest trade on this (pair, side) is sold + market still open
        candidates = []
        for (pid, side), records in by_key.items():
            records.sort(key=lambda r: r.get('logged_at', ''))
            latest = records[-1]
            if not latest.get('exit_price'):
                continue  # latest is still open or already resolved
            if latest.get('resolved'):
                continue  # market already resolved
            # CRITICAL: only re-enter after a PROFIT sell. Re-entering after a
            # cut-loss creates a martingale death spiral when a side is going
            # to $0 (each re-buy triggers another cut at lower price).
            exit_reason = (latest.get('exit_reason') or '')
            if 'CUT-LOSS' in exit_reason or (latest.get('paper_pnl') or 0) <= 0:
                continue
            end_ts = float(latest.get('market_end_ts') or 0)
            if now_ts >= end_ts - 5:
                continue  # market about to close, don't re-enter
            if len(records) > MAX_R:
                continue  # cap re-entries
            candidates.append((pid, side, latest, end_ts))
        if not candidates:
            return
        changed = False
        for pid, side, last_trade, end_ts in candidates:
            tid = last_trade.get('token_id')
            if not tid:
                continue
            # Get current ASK (we're buying, so we need ask)
            cur_ask = None
            try:
                r = self._session.get(
                    'https://clob.polymarket.com/book',
                    params={'token_id': tid}, timeout=3)
                if r.status_code == 200:
                    asks = r.json().get('asks', [])
                    if asks:
                        cur_ask = min(float(a.get('price', 999)) for a in asks)
            except Exception:
                continue
            if cur_ask is None or cur_ask <= 0:
                continue
            entry = float(last_trade.get('entry_price') or 0)
            if entry <= 0:
                continue
            # Re-entry trigger: ask has pulled back to entry*(1-RE_TH) or lower
            if cur_ask > entry * (1 - RE_TH):
                continue
            # Record a new buy on this side with same pair_id
            stake = float(self.stake)
            shares = round(stake / cur_ask, 4) if cur_ask > 0 else 0
            if shares <= 0:
                continue
            slug = last_trade.get('market_slug', '')
            secs_left = max(0, end_ts - now_ts)
            hr = datetime.now(timezone.utc).hour
            sess = ('ASIA' if 0 <= hr < 8 else 'US_OPEN' if 8 <= hr < 12
                    else 'US_AFT' if 12 <= hr < 20 else 'OVERNIGHT')
            new_trade = {
                'id':              _uuid.uuid4().hex[:12],
                'pair_id':         pid,
                'side':            side,
                'direction':       side,
                'logged_at':       datetime.now(timezone.utc).isoformat(),
                'fill_hour':       hr,
                'fill_session':    sess,
                'symbol':          self.SYMBOL,
                'market_slug':     slug,
                'timeframe':       '5m',
                'strategy':        self._log,
                'secs_to_close':   round(secs_left, 1),
                'market_end_ts':   end_ts,
                'real_trade':      False,
                'resolved':        False,
                'outcome':         None,
                'exit_price':      None,
                'exit_ts':         None,
                'exit_reason':     None,
                'paper_pnl':       None,
                'entry_price':     round(cur_ask, 4),
                'stake':           round(stake, 2),
                'shares':          shares,
                'token_id':        tid,
                're_entry':        True,
                're_entry_n':      len([r for r in by_key[(pid, side)] if r.get('re_entry')]) + 1,
                'previous_exit':   last_trade.get('exit_price'),
            }
            with self._lock:
                self._trades.append(new_trade)
            changed = True
            logger.info(
                f'[{self._log}] RE-ENTRY {slug[:40]} {side} '
                f'@ {cur_ask:.3f} (prev exit {last_trade.get("exit_price"):.3f}, '
                f'orig entry {entry:.3f}) shares={shares:.2f}'
            )
        if changed:
            with self._lock:
                self._save_log()

    def check_outcomes(self):
        """Resolve straddle trades via Gamma. For each unique slug, resolve the
        MARKET'S winning direction (UP or DOWN) once, then map to per-trade
        WIN/LOSS based on each trade's direction. Side already sold early keeps
        its paper_pnl; side still open computes pnl from market outcome."""
        from concurrent.futures import ThreadPoolExecutor, as_completed
        now_ts = time.time()
        with self._lock:
            pending = [t for t in self._trades
                       if not t.get('resolved')
                       and now_ts >= (t.get('market_end_ts', 0) + 30)]
        if not pending:
            return

        # Resolve each unique slug ONCE using a UP-direction probe.
        # _resolve_one returns 'WIN'/'LOSS'/'PUSH' based on the trade's direction.
        # Probing with direction='UP' tells us the market's winning side directly.
        unique_slugs = {}
        for t in pending:
            unique_slugs.setdefault(t.get('market_slug'), t)
        def _probe(slug, end_ts):
            probe = {'market_slug': slug, 'market_end_ts': end_ts, 'direction': 'UP'}
            return slug, self._resolve_one(probe)
        slug_market_dir = {}   # slug -> 'UP' | 'DOWN' | 'PUSH'
        with ThreadPoolExecutor(max_workers=min(len(unique_slugs), 8)) as ex:
            futures = [ex.submit(_probe, t.get('market_slug'), t.get('market_end_ts', 0))
                       for t in unique_slugs.values()]
            for fut in as_completed(futures):
                slug, probe_result = fut.result()
                if probe_result == 'WIN':   slug_market_dir[slug] = 'UP'
                elif probe_result == 'LOSS': slug_market_dir[slug] = 'DOWN'
                elif probe_result == 'PUSH': slug_market_dir[slug] = 'PUSH'
                # None = not resolved yet on Gamma; skip this round

        changed = False
        with self._lock:
            for t in pending:
                market_dir = slug_market_dir.get(t.get('market_slug'))
                if market_dir is None:
                    continue
                # Translate market direction to per-trade outcome
                trade_dir = (t.get('direction') or t.get('side') or '').upper()
                if market_dir == 'PUSH':
                    outcome = 'PUSH'
                elif market_dir == trade_dir:
                    outcome = 'WIN'
                else:
                    outcome = 'LOSS'
                if t.get('exit_price') is None:
                    shares = float(t.get('shares') or 0)
                    stake  = float(t.get('stake') or 0)
                    if outcome == 'WIN':
                        paper_pnl = round(shares * 1.0 - stake, 4)
                    elif outcome == 'LOSS':
                        paper_pnl = -stake
                    else:
                        paper_pnl = 0.0
                    t['paper_pnl']   = paper_pnl
                    t['exit_reason'] = 'held_to_resolution'
                t.update({
                    'resolved':    True,
                    'outcome':     outcome,
                    'won':         outcome == 'WIN',
                    'pnl':         t.get('paper_pnl', 0),
                    'resolved_at': datetime.now(timezone.utc).isoformat(),
                })
                try:
                    _xbot_clear(t.get('market_slug', ''))
                except Exception:
                    pass
                changed = True
        if changed:
            with self._lock:
                self._save_log()
            n_markets = sum(1 for _, d in slug_market_dir.items() if d)
            logger.info(f'[{self._log}] Resolved {n_markets} markets ({len(pending)} sides updated)')

    def _check_fill_status(self):
        """Phase 2b will implement real-trade fill polling (same pattern as
        BTCMLScanner._check_fill_status at file:13159)."""
        return

    # ── stats for the /api/btc-hermes-state endpoint (Phase 4) ───────────────

    def get_stats(self) -> dict:
        with self._lock:
            trades = list(self._trades)
        resolved = [t for t in trades if t.get('resolved')]
        wins     = [t for t in resolved if t.get('outcome') == 'WIN']
        losses   = [t for t in resolved if t.get('outcome') == 'LOSS']
        pnl      = round(sum((t.get('paper_pnl') or 0) for t in resolved), 2)
        return {
            'symbol':          self.SYMBOL,
            'mode':            'LIVE' if self.live_mode else 'PAPER',
            'stake':           self.stake,
            'tp_sl_enabled':   self.tp_sl_enabled,
            'min_prob':        self.min_prob,
            'min_edge':        self.min_edge,
            'kelly_fraction':  self.kelly_fraction,
            'markov':          dict(self.markov),
            'trades_total':    len(trades),
            'resolved':        len(resolved),
            'wins':            len(wins),
            'losses':          len(losses),
            'win_rate':        round(100 * len(wins) / max(len(wins)+len(losses), 1), 1),
            'paper_pnl_total': pnl,
            'last_prediction': dict(self._last_prediction),
            'scan_count':      self._scan_count,
            'last_scan_ts':    self._last_scan_ts,
            'last_scan_age_s': round(time.time() - self._last_scan_ts, 1) if self._last_scan_ts else None,
        }


# ──────────────────────────────────────────────────────────────────────────────
# CLAUDE PICKS — high-confidence Polymarket opportunity scanner
# ──────────────────────────────────────────────────────────────────────────────

class ClaudePicksScanner:
    """
    Claude's own edge: scan for high-EV Polymarket opportunities across three
    distinct play-types ranked by conviction.

    Play 1 — TIME-LOCK  (highest conviction)
        A 15m or 5m market is < 5 min from close, price has been on the
        winning side for most of the bar.  The token is still trading at a
        discount to $1.00, creating near-free-money.

    Play 2 — MOMENTUM LOCK  (high conviction)
        3+ aligned indicators (RSI + candle body + volume ratio) all point the
        same direction with >= 80 % confidence.  The bot's own signal engine is
        used, so this is the same logic that actually wins.

    Play 3 — MISPRICED MARKET  (good conviction)
        Market price is significantly below/above Claude's estimated fair-value
        based on recent price momentum over the last N candles.
    """

    SYMBOLS = ['BTC', 'ETH', 'SOL', 'XRP', 'DOGE', 'HYPE', 'BNB']
    GAMMA   = "https://gamma-api.polymarket.com"
    BINANCE = "https://api.binance.com/api/v3"

    def __init__(self, bot_ref):
        self.bot = bot_ref
        self._cache: Dict = {}
        self._cache_ts: float = 0
        self.brain_log: list = []          # rolling thought stream, max 200 entries
        self._brain_total: int = 0         # monotonic count of all entries ever added
        self.scan_matrix: Dict = {}        # {symbol: {tf: {status, prob, ev, direction}}}
        self._scanning: bool = False
        self._market_scan_cache: Dict = {} # per-scan market cache; cleared at scan start
        self._candle_api_cache: Dict = {}  # {(symbol, interval): (candles, ts)} 60s TTL
        self._logged_trade_keys: set = set()  # dedup: slug+direction+date already logged
        self._autobuy_lock = threading.Lock()  # prevents race condition double-buys
        import time as _ti_init
        self._startup_time: float = _ti_init.time()  # used for post-restart TP/SL warmup
        from datetime import timezone as _tz
        self._dedup_date: str = datetime.now(_tz.utc).strftime('%Y-%m-%d')  # reset at midnight
        self._spot_price_cache: Dict = {}  # {symbol: (price, ts)} 10s TTL fallback
        self._token_price_cache: Dict = {} # {token_id: price} CLOB live prices; cleared at scan start
        self._gamma_price_cache: Dict = {} # {token_id: price} Gamma fallback only; cleared at scan start
        self._ws_prices: Dict = {}         # {symbol: float} kept live by Binance WS thread
        self._ws_connected: bool = False
        # Persistent HTTP session — reuses TCP/TLS connections, saves ~50-200ms per call.
        # 2026-05-16 profile: 86% of bot CPU was in ssl_wrap_socket from this scanner's
        # bare requests.get() calls. Mirror HFTScanner pool sizing (line 8133).
        self._session = requests.Session()
        self._session.headers.update({'Accept-Encoding': 'gzip'})
        from requests.adapters import HTTPAdapter as _HTTPAdapter
        _picks_adapter = _HTTPAdapter(pool_connections=50, pool_maxsize=100, max_retries=2)
        self._session.mount('http://', _picks_adapter)
        self._session.mount('https://', _picks_adapter)
        self.FEE_RATE = 0.0   # 2026-05-10: confirmed 0% via Polymarket data API (fee_rate_bps null on recent fills) — was 0.02
        self.STRATEGY_MODES_FILE = 'claude_strategy_modes.json'
        self.strategy_modes = self._load_strategy_modes()
        self.conviction_threshold = self.strategy_modes.get('_conviction_threshold', 'HIGH')
        # Explicit enabled-levels set — overrides min-threshold when present
        _saved_levels = self.strategy_modes.get('_conviction_levels')
        self.conviction_levels: set = set(_saved_levels) if _saved_levels else None
        # Per-conviction max bet — replaces single claude_max_bet
        _default_bets = {'MEDIUM': 1.0, 'HIGH': 3.0, 'STRONG': 5.0, 'EXTREME': 5.0}
        _saved_bets = self.strategy_modes.get('_conviction_bets', {})
        self.conviction_bets = {k: float(_saved_bets.get(k, v)) for k, v in _default_bets.items()}
        self.claude_max_bet = max(self.conviction_bets.values())  # kept for backward compat
        # ── Drawdown protection ───────────────────────────────────────────────
        self.circuit_breaker_active = False       # all real buying paused
        self.circuit_breaker_reason = ''
        self.DRAWDOWN_WARN_PCT   = 0.10           # TG warn at -10% of session start balance
        self.DRAWDOWN_PAUSE_PCT  = 0.20           # pause all buying at -20%
        self.CONSEC_LOSS_LIMIT   = 8              # pause after 8 consecutive losses
        # Seed session baseline from current file so restarts don't look like drawdowns
        # Only count real_trade=True — paper-mode sims don't move real money
        try:
            _seed_trades = self._load_paper_log()
            self._session_start_pnl: Optional[float] = sum(
                t.get('paper_pnl') or 0 for t in _seed_trades
                if t.get('resolved') and t.get('real_trade')
            )
        except Exception:
            self._session_start_pnl: Optional[float] = None  # fallback: set on first trade
        self._consec_losses: int = 0
        self._last_known_balance: Optional[float] = None  # cached real balance to avoid $100 fallback
        self._last_dd_warn_ts: float = 0.0  # rate-limit TG drawdown warnings (max 1/2h)
        # Drawdown protection master toggle — settable via /drawdown off|on (persisted).
        # When OFF: no consecutive-loss tracking, no -10% TG warning, no -20% auto-pause.
        # When ON  (default): all three protections active.
        self.drawdown_protection_enabled: bool = bool(
            self.strategy_modes.get('_drawdown_protection_enabled', True))
        # ── MANIP RL — contextual bandit ─────────────────────────────────────
        self.manip_rl  = ManipRL()
        # Per-play_type Picks RL: separate Q-table file per play type so each
        # category learns independently. State key still {pt|sym|ask|conv}, but
        # MISPRICED's bad cells can't drag TIME-LOCK exploration down via the
        # pool gate, and tuning thresholds per category becomes possible later.
        # MANIP excluded — uses the dedicated ManipRL contextual bandit.
        _migrate_picks_rl_to_per_type()
        # Per-category gate config — each play_type tuned for its structural risk:
        #   MISPRICED: TIGHTER gate (live diverging from paper, limit damage)
        #   MOMENTUM / VOL-SURGE / TIME-LOCK: LOOSER gate (more exploration needed)
        #   NEAR-CLOSE: default
        # 2026-05-10: TIME-LOCK loosened to -0.40/n=10 per user — was blocking too many trades.
        # 2026-05-14: min_visits 10 -> 5 to accelerate convergence after the 5/10 wipe.
        # 2026-05-26: TIME-LOCK tightened back -0.40 -> -0.20. Lifetime -$142 / 877 trades
        # (68% WR but small wins / full-stake losses on high-ask entries makes -0.40 too
        # permissive). Counterfactual on 7d=645 trades: kept-cohort PnL goes +$74 -> +$155;
        # blocks 192 additional bleeding trades (q in [-0.40,-0.20]) that summed to -$80
        # over the window. Surviving cells (n=390, 76.4% WR) print positive — change is
        # not a band-aid, the gate just had too low a bar. See journal #190.
        _PT_RL_CONFIG = {
            'TIME-LOCK':  {'skip_threshold': -0.20, 'min_visits': 5},
            'MISPRICED':  {'skip_threshold': -0.10, 'min_visits': 5},
            'MOMENTUM':   {'skip_threshold': -0.40, 'min_visits': 5},
            'VOL-SURGE':  {'skip_threshold': -0.20, 'min_visits': 8},
            'NEAR-CLOSE': {'skip_threshold': -0.15, 'min_visits': 5},
        }
        self.picks_rl_by_type: dict = {}
        for _pt, _cfg in _PT_RL_CONFIG.items():
            _fname = f'claude_picks_{_pt.lower().replace("-","_")}_rl_state.json'
            self.picks_rl_by_type[_pt] = ClaudePicksRL(
                play_type=_pt, state_file=_fname,
                skip_threshold=_cfg['skip_threshold'], min_visits=_cfg['min_visits'])
            logger.info(f'[PICKS-RL] {_pt} config: skip={_cfg["skip_threshold"]} min_n={_cfg["min_visits"]}')
        # Backward-compat: self.picks_rl points to TIME-LOCK instance (most queried).
        # All call sites use _picks_rl_for(play_type) to dispatch correctly.
        self.picks_rl = self.picks_rl_by_type['TIME-LOCK']
        self.rl_shadow = RLShadowLog('claude_rl_blocked.json')
        import threading as _th
        _th.Thread(target=self._start_price_ws, daemon=True).start()
        # Seed balance cache immediately in background so drawdown check has a real value from the start
        def _seed_balance():
            import time as _t
            _t.sleep(8)  # let bot finish init first
            # 2026-05-23 PR-6: curated top-3 list (see _POLYGON_RPCS comment)
            _RPCS = [
                'https://polygon-bor-rpc.publicnode.com',
                'https://rpc-mainnet.matic.quiknode.pro',
                'https://polygon.gateway.tenderly.co',
            ]
            _ABI = [{"constant": True, "inputs": [{"name": "_owner", "type": "address"}],
                     "name": "balanceOf", "outputs": [{"name": "balance", "type": "uint256"}], "type": "function"}]
            _wallet = (getattr(self.bot, 'proxy_address', None) or
                       getattr(self.bot, 'wallet_address', None) or
                       '')
            for _rpc in _RPCS:
                try:
                    _w3 = Web3(Web3.HTTPProvider(_rpc, request_kwargs={'timeout': 3}))
                    _contract = _w3.eth.contract(
                        address=Web3.to_checksum_address(USDC_E_ADDRESS), abi=_ABI)
                    _raw = _contract.functions.balanceOf(Web3.to_checksum_address(_wallet)).call()
                    bal = round(_raw / 1e6, 2)
                    if bal > 100:
                        self._last_known_balance = bal
                        self.bot._cached_usdc_balance = bal  # also seed bot's cache
                        import time as _ti; self.bot._cached_usdc_ts = _ti.time()
                        logger.info(f'[DRAWDOWN] Seeded balance cache: ${bal:.2f}')
                    else:
                        logger.warning(f'[DRAWDOWN] Seed got low balance ${bal:.2f} from {_rpc}')
                    break
                except Exception as _e:
                    logger.warning(f'[DRAWDOWN] Seed RPC failed {_rpc}: {_e}')
                    continue
            else:
                logger.warning('[DRAWDOWN] All seed RPCs failed — drawdown will use cached balance when available')
        _th.Thread(target=_seed_balance, daemon=True).start()

    PLAY_TYPES = ['TIME-LOCK', 'MOMENTUM', 'MISPRICED', 'MANIP', 'NEAR-CLOSE', 'VOL-SURGE']

    def _load_strategy_modes(self) -> dict:
        """Load per-strategy real/paper modes from disk. Default all to paper."""
        try:
            if os.path.exists(self.STRATEGY_MODES_FILE):
                with open(self.STRATEGY_MODES_FILE, 'r') as f:
                    saved = json.load(f)
                    # 2026-05-21: strip vestigial _claude_max_bet (pre-per-conviction slider field,
                    # no longer read anywhere). Keeps it from being re-saved on next write.
                    saved.pop('_claude_max_bet', None)
                    # Ensure all play types have an entry
                    for pt in self.PLAY_TYPES:
                        if pt not in saved:
                            saved[pt] = 'paper'
                    return saved
        except Exception:
            pass
        return {pt: 'real' for pt in self.PLAY_TYPES}

    def _save_strategy_modes(self):
        try:
            with open(self.STRATEGY_MODES_FILE, 'w') as f:
                json.dump(self.strategy_modes, f, indent=2)
        except Exception as e:
            logger.warning(f'[MODES] Save error: {e}')

    def _picks_rl_for(self, play_type: str):
        """Dispatch to the per-play_type Picks RL instance. Falls back to
        TIME-LOCK if play_type isn't in the dict (defensive — shouldn't happen)."""
        return self.picks_rl_by_type.get(play_type) or self.picks_rl_by_type.get('TIME-LOCK')

    def _think(self, msg: str, level: str = 'info'):
        """Append a thought to the brain log."""
        from datetime import datetime as _dt
        entry = {
            'ts': _dt.now(timezone.utc).strftime('%H:%M:%S'),
            'msg': msg,
            'level': level,   # info | check | found | skip | warn
        }
        self.brain_log.append(entry)
        self._brain_total += 1
        if len(self.brain_log) > 200:
            self.brain_log = self.brain_log[-200:]

    # ── helpers ───────────────────────────────────────────────────────────────

    def _get_price(self, symbol: str) -> Optional[float]:
        """Current spot price — live from WebSocket if connected, HTTP fallback otherwise."""
        ws_price = self._ws_prices.get(symbol)
        if ws_price is not None:
            return ws_price
        # WebSocket not yet connected — fall back to cached HTTP
        import time as _time
        cached = self._spot_price_cache.get(symbol)
        if cached and _time.time() - cached[1] < 10:
            return cached[0]
        pair_map = {'BTC':'BTCUSDT','ETH':'ETHUSDT','SOL':'SOLUSDT',
                    'XRP':'XRPUSDT','DOGE':'DOGEUSDT','HYPE':'HYPEUSDT',
                    'BNB':'BNBUSDT'}
        pair = pair_map.get(symbol)
        if not pair:
            return None
        try:
            r = self._session.get(f"{self.BINANCE}/ticker/price", params={'symbol': pair}, timeout=3)
            price = float(r.json()['price'])
            self._spot_price_cache[symbol] = (price, _time.time())
            return price
        except Exception:
            return cached[0] if cached else None

    def _prefetch_prices(self):
        """Batch-fetch all symbol spot prices via HTTP — only used when WebSocket isn't live yet."""
        if self._ws_connected and len(self._ws_prices) >= len(self.SYMBOLS):
            return  # WS stream already has fresh prices for everything
        import time as _time, json as _json
        pair_map = {'BTC':'BTCUSDT','ETH':'ETHUSDT','SOL':'SOLUSDT',
                    'XRP':'XRPUSDT','DOGE':'DOGEUSDT','HYPE':'HYPEUSDT',
                    'BNB':'BNBUSDT'}
        reverse = {v: k for k, v in pair_map.items()}
        symbols_json = _json.dumps(list(pair_map.values()))
        try:
            r = self._session.get(f"{self.BINANCE}/ticker/price",
                             params={'symbols': symbols_json}, timeout=3)
            if r.status_code == 200:
                now = _time.time()
                for item in r.json():
                    sym = reverse.get(item['symbol'])
                    if sym:
                        self._spot_price_cache[sym] = (float(item['price']), now)
        except Exception:
            pass

    def _start_price_ws(self):
        """Subscribe to Binance miniTicker WebSocket for all symbols.
        Runs in a background daemon thread with auto-reconnect on disconnect."""
        import websocket, json as _json, time as _time

        pair_map = {'BTC':'BTCUSDT','ETH':'ETHUSDT','SOL':'SOLUSDT',
                    'XRP':'XRPUSDT','DOGE':'DOGEUSDT','HYPE':'HYPEUSDT',
                    'BNB':'BNBUSDT'}
        reverse = {v: k for k, v in pair_map.items()}
        streams = '/'.join(f"{p.lower()}@miniTicker" for p in pair_map.values())
        url = f"wss://stream.binance.com:9443/stream?streams={streams}"

        def on_message(ws, raw):
            try:
                msg = _json.loads(raw)
                data = msg.get('data', {})
                sym = reverse.get(data.get('s'))
                if sym and 'c' in data:
                    self._ws_prices[sym] = float(data['c'])
            except Exception:
                pass

        def on_open(ws):
            self._ws_connected = True
            self._think('[WS] Binance price stream connected', 'info')

        def on_close(ws, code, msg):
            self._ws_connected = False
            self._think(f'[WS] Binance price stream closed ({code}) — reconnecting...', 'warn')

        def on_error(ws, err):
            self._think(f'[WS] Binance price stream error: {str(err)[:60]}', 'warn')

        while True:
            try:
                ws = websocket.WebSocketApp(url,
                                            on_open=on_open,
                                            on_message=on_message,
                                            on_close=on_close,
                                            on_error=on_error)
                ws.run_forever(ping_interval=20, ping_timeout=10)
            except Exception as e:
                self._think(f'[WS] run_forever exception: {str(e)[:60]}', 'warn')
            self._ws_connected = False
            _time.sleep(3)  # brief pause before reconnect

    def _get_candles(self, symbol: str, interval: str = '1m', limit: int = 20) -> list:
        import time as _time
        cache_key = (symbol, interval)
        cached = self._candle_api_cache.get(cache_key)
        if cached and _time.time() - cached[1] < 60:
            return cached[0]
        pair_map = {'BTC':'BTCUSDT','ETH':'ETHUSDT','SOL':'SOLUSDT',
                    'XRP':'XRPUSDT','DOGE':'DOGEUSDT','HYPE':'HYPEUSDT',
                    'BNB':'BNBUSDT'}
        pair = pair_map.get(symbol)
        if not pair:
            return []
        try:
            r = self._session.get(f"{self.BINANCE}/klines",
                             params={'symbol': pair, 'interval': interval, 'limit': limit},
                             timeout=5)
            raw = r.json()
            result = [{'open': float(c[1]), 'high': float(c[2]),
                       'low': float(c[3]),  'close': float(c[4]),
                       'volume': float(c[5])} for c in raw]
            self._candle_api_cache[cache_key] = (result, _time.time())
            return result
        except Exception:
            return cached[0] if cached else []

    def _active_markets(self, symbol: str, tf: str) -> list:
        """Return active up/down markets for the given symbol + timeframe.
        Results are cached per scan (reset at scan() start) so each (symbol, tf)
        is only fetched once even though three play-types call this method.
        The three slug requests run in parallel for speed.
        """
        cache_key = (symbol, tf)
        if cache_key in self._market_scan_cache:
            return self._market_scan_cache[cache_key]

        sym = symbol.lower()
        now = int(time.time())
        interval = 300 if tf == '5m' else 900
        # Only fetch the current bar — future bars (i=1,2) exist in Gamma but have
        # no CLOB order book yet, causing 404s on every midpoint/order-book call.
        current_bar = now - (now % interval)
        slugs = [f"{sym}-updown-{tf}-{current_bar}"]

        def _fetch_slug(slug):
            try:
                r = self._session.get(f"{self.GAMMA}/events", params={'slug': slug}, timeout=5)
                if r.status_code == 200:
                    data = r.json()
                    if data:
                        ev  = data[0]
                        mkt = ev.get('markets', [{}])[0]
                        outcomes  = mkt.get('outcomes', '[]')
                        token_ids = mkt.get('clobTokenIds', '[]')
                        if isinstance(outcomes, str):  outcomes  = json.loads(outcomes)
                        if isinstance(token_ids, str): token_ids = json.loads(token_ids)

                        # Pre-populate token price cache with Gamma mid-prices.
                        # This lets _token_price work even without a CLOB client (no wallet).
                        out_prices_raw = mkt.get('outcomePrices', '[]')
                        if isinstance(out_prices_raw, str):
                            try:
                                out_prices = [float(x) for x in json.loads(out_prices_raw)]
                            except Exception:
                                out_prices = []
                        else:
                            out_prices = [float(x) for x in (out_prices_raw or [])]
                        for idx, tid in enumerate(token_ids):
                            if tid and idx < len(out_prices):
                                self._gamma_price_cache[tid] = out_prices[idx]

                        return {
                            'slug': slug,
                            'title': ev.get('title', ''),
                            'end_date': ev.get('endDate', ''),
                            'outcomes': outcomes,
                            'token_ids': token_ids,
                            'condition_id': mkt.get('conditionId', ''),
                            'market_ts': int(slug.split('-')[-1]),
                        }
            except Exception:
                pass
            return None

        from concurrent.futures import ThreadPoolExecutor, as_completed
        markets = []
        with ThreadPoolExecutor(max_workers=3) as ex:
            futures = [ex.submit(_fetch_slug, s) for s in slugs]
            for fut in as_completed(futures):
                result = fut.result()
                if result:
                    markets.append(result)

        markets.sort(key=lambda m: m['market_ts'])
        self._market_scan_cache[cache_key] = markets
        return markets

    def _token_price(self, token_id: str) -> Optional[float]:
        """Live market midpoint price at call time (matches Polymarket UI).
        Falls back to Gamma mid-price when CLOB is unavailable."""
        if self.bot.clob_client:
            try:
                mid = self.bot.clob_client.get_midpoint(token_id)
                if mid is not None:
                    price = float(mid) if not isinstance(mid, dict) else float(mid.get('mid', 0))
                    if 0 < price < 1:
                        self._token_price_cache[token_id] = price
                        return price
            except Exception:
                pass
        # Fall back to Gamma mid-price pre-loaded by _active_markets
        gamma = self._gamma_price_cache.get(token_id)
        if gamma is not None:
            return gamma
        return None

    # ── play generators ───────────────────────────────────────────────────────

    def _btc_regime(self) -> str:
        """Classify BTC overall regime using 1h price change.
        Returns 'BULLISH', 'BEARISH', or 'NEUTRAL'.
        Threshold: ±0.3% over last 60 minutes.
        Result is cached via _get_candles' 60s TTL."""
        candles = self._get_candles('BTC', '1m', limit=60)
        if len(candles) < 30:
            return 'NEUTRAL'
        pct = (candles[-1]['close'] - candles[0]['close']) / candles[0]['close'] * 100
        if pct >= 0.3:
            return 'BULLISH'
        if pct <= -0.3:
            return 'BEARISH'
        return 'NEUTRAL'

    def _play_time_lock(self, symbol: str, tf: str) -> Optional[Dict]:
        """
        TIME-LOCK: market closes soon, price is clearly on one side.
        Returns a play dict or None.
        Regime-aware: bullish overall → only UP signals; bearish → only DOWN.
        """
        from datetime import timezone
        markets = self._active_markets(symbol, tf)
        now_utc = datetime.now(timezone.utc)
        regime = self._btc_regime()

        for mkt in markets:
            try:
                end = datetime.fromisoformat(mkt['end_date'].replace('Z', '+00:00'))
            except Exception:
                continue
            secs_left = (end - now_utc).total_seconds()
            if not (30 < secs_left < 150):  # 30s–2.5min window (data shows 4-5min entries lose at 39%)
                continue

            # Get 1m candles covering the full bar duration
            bar_duration = 300 if tf == '5m' else 900
            candles = self._get_candles(symbol, '1m', limit=20)
            if len(candles) < 3:
                continue

            # Bar open is (bar_duration - secs_left) seconds ago = that many minutes back
            elapsed_mins = int((bar_duration - secs_left) / 60) + 1
            bar_open_idx = max(elapsed_mins + 1, 2)  # at least 2 candles back
            bar_open = candles[-min(bar_open_idx, len(candles))]['open']
            current  = candles[-1]['close']
            pct_move = (current - bar_open) / bar_open * 100

            # Only act if price moved at least 0.08% (loosened 2026-05-10 per user — was 0.15% blocking too many trades)
            if abs(pct_move) < 0.08:
                continue

            direction = 'UP' if pct_move > 0 else 'DOWN'

            # Regime alignment filter DISABLED 2026-05-10 per user — was dropping too many counter-trend TIME-LOCKs.
            # if regime == 'BULLISH' and direction == 'DOWN':
            #     continue
            # if regime == 'BEARISH' and direction == 'UP':
            #     continue
            outcomes  = mkt.get('outcomes', ['Up', 'Down'])
            token_ids = mkt.get('token_ids', [])

            # Match token
            target_outcome = 'Up' if direction == 'UP' else 'Down'
            token_id = None
            for i, o in enumerate(outcomes):
                if o.lower() == target_outcome.lower() and i < len(token_ids):
                    token_id = token_ids[i]
                    break
            if not token_id:
                continue

            mid = self._token_price(token_id)
            if not mid or mid >= 0.98:
                continue

            # Probability estimate: higher the longer price has been on this side
            # and less time is left
            time_factor = 1 - (secs_left / 300)   # 0→1 as time runs out
            price_factor = min(abs(pct_move) / 0.5, 1.0)  # saturates at 0.5% move
            prob = 0.75 + 0.20 * time_factor + 0.05 * price_factor
            prob = min(prob, 0.99)

            ev = prob * 1.0 - mid * (1 + self.FEE_RATE)
            if ev < 0.02:
                continue

            # ── Volatility gate (2026-06-01) ──────────────────────────────────
            # TIME-LOCK assumes price PERSISTS into close; in high-vol regimes the
            # leading token reverses near close -> losses. Backtest (last 16h, 193
            # trades): 1m realized vol <0.06 -> 77.5% WR / +$233; >=0.06 -> 49% WR /
            # -$715. Block elevated-vol entries and SHADOW-LOG them (do NOT silently
            # drop) so the gate's accuracy is verifiable from claude_rl_blocked.json
            # (rl_system='timelock_vol_block'). Threshold matches ETH-ML's vol gate.
            # vol = pstdev of last 10 1m pct-returns, in %.
            _tl_vol = None
            try:
                _cl = [c['close'] for c in candles[-11:]]
                if len(_cl) >= 11:
                    _rets = [(_cl[i] - _cl[i - 1]) / _cl[i - 1]
                             for i in range(1, len(_cl)) if _cl[i - 1]]
                    if _rets:
                        import statistics as _st
                        _tl_vol = _st.pstdev(_rets) * 100.0
            except Exception:
                _tl_vol = None
            if _tl_vol is not None and _tl_vol >= 0.06:
                try:
                    self.rl_shadow.log_blocked(
                        rl_system='timelock_vol_block',
                        state_key=f'{symbol}|{direction}|vol{_tl_vol:.3f}',
                        rl_q=0.0, rl_n=0,
                        rl_reason=f'1m realized vol {_tl_vol:.3f}% >= 0.06% (high-vol regime)',
                        symbol=symbol, direction=direction,
                        entry_price=mid, stake=5.0,
                        secs_to_close=secs_left, market_end_ts=end.timestamp(),
                        market_slug=mkt['slug'], play_type='TIME-LOCK',
                        token_id=token_id or '')
                except Exception as _ve:
                    logger.debug(f'[TIMELOCK-VOL] shadow log error: {_ve}')
                logger.info(f'[TIMELOCK-VOL] BLOCK {symbol} {direction} — 1m vol {_tl_vol:.3f}% >= 0.06%')
                continue

            return {
                'play_type': 'TIME-LOCK',
                'symbol': symbol,
                'timeframe': tf,
                'direction': direction,
                'token_id': token_id,
                'ask': round(mid, 4),
                'prob': round(prob * 100, 1),
                'ev': round(ev, 4),
                'ev_pct': round(ev / (mid * (1 + self.FEE_RATE)) * 100, 1),
                'secs_left': int(secs_left),
                'pct_move': round(pct_move, 3),
                'slug': mkt['slug'],
                'condition_id': mkt['condition_id'],
                'reasoning': (
                    f"Market closes in {int(secs_left)}s. "
                    f"Price {'+' if pct_move>0 else ''}{pct_move:.3f}% since bar open. "
                    f"Market price {mid:.3f} — should settle at $1.00. "
                    f"EV: +{ev:.4f} per $1 risked (after 2% fee)."
                ),
                'conviction': 'EXTREME' if prob > 0.93 else ('STRONG' if prob > 0.90 else 'HIGH'),
            }
        return None

    def _play_momentum_lock(self, symbol: str, tf: str) -> Optional[Dict]:
        """
        MOMENTUM LOCK: bot's own signal engine says 65%+ directional confidence
        but token price hasn't fully priced it in yet.
        Threshold lowered from 80→65 to generate more signals for data collection.
        """
        cached = self.bot.latest_analysis.get(symbol, {})
        analysis = cached.get('analysis', {})
        conf = analysis.get('confidence', 0)
        signal = analysis.get('signal', 'NEUTRAL')

        if signal == 'NEUTRAL' or conf < 65:
            return None

        markets = self._active_markets(symbol, tf)
        if not markets:
            return None
        mkt = markets[0]  # most imminent

        direction = 'UP' if signal == 'BULLISH' else 'DOWN'
        outcomes  = mkt.get('outcomes', ['Up', 'Down'])
        token_ids = mkt.get('token_ids', [])
        target    = 'Up' if direction == 'UP' else 'Down'

        token_id = None
        for i, o in enumerate(outcomes):
            if o.lower() == target.lower() and i < len(token_ids):
                token_id = token_ids[i]
                break
        if not token_id:
            return None

        mid = self._token_price(token_id)
        if not mid:
            return None

        prob = conf / 100.0
        ev   = prob * 1.0 - mid * (1 + self.FEE_RATE)
        if ev < 0.01:
            return None

        return {
            'play_type': 'MOMENTUM',
            'symbol': symbol,
            'timeframe': tf,
            'direction': direction,
            'token_id': token_id,
            'ask': round(mid, 4),
            'prob': round(prob * 100, 1),
            'ev': round(ev, 4),
            'ev_pct': round(ev / (mid * (1 + self.FEE_RATE)) * 100, 1),
            'secs_left': None,
            'slug': mkt['slug'],
            'condition_id': mkt['condition_id'],
            'reasoning': (
                f"Bot signal: {signal} at {conf}% confidence. "
                f"Implied prob = {prob*100:.0f}% vs market price of {mid:.2f}. "
                f"Edge = {ev:.4f}/token (after 2% fee)."
            ),
            'conviction': 'STRONG' if conf >= 95 else ('HIGH' if conf >= 85 else ('MEDIUM' if conf >= 70 else 'MEDIUM')),
        }

    def _play_mispriced(self, symbol: str, tf: str) -> Optional[Dict]:
        """
        MISPRICED: rolling candle analysis says direction is clear,
        but token price is lagging.

        Signal paths (either can fire):
          A) 1m candles: 5/10 aligned (lowered from 6/8 → more signals)
          B) 5m candles: 4/6 aligned (secondary path for slower-moving markets)

        Thresholds loosened for data collection; EV floor 0.04→0.01.
        sym_rate bug fixed: was treating 0-data symbols as 0% hit rate; now
        defaults to 50% neutral when no resolved trades exist.
        """
        # --- Path A: 1m candles (primary) ---
        candles_1m = self._get_candles(symbol, '1m', limit=15)
        direction_1m = None
        prob_raw = 0.0
        window_str = ''

        if len(candles_1m) >= 10:
            last = candles_1m[-10:]
            ups   = sum(1 for c in last if c['close'] > c['open'])
            downs = 10 - ups
            if max(ups, downs) >= 8:  # 8/10 = 80% threshold (tightened 2026-05-22 from 6/10)
                direction_1m = 'UP' if ups > downs else 'DOWN'
                prob_raw = max(ups, downs) / 10
                window_str = f'{max(ups, downs)}/10 1m candles'

        # --- Path B: 5m candles (secondary, fires if 1m didn't) ---
        direction_5m = None
        if direction_1m is None:
            candles_5m = self._get_candles(symbol, '5m', limit=10)
            if len(candles_5m) >= 6:
                last5 = candles_5m[-6:]
                ups5   = sum(1 for c in last5 if c['close'] > c['open'])
                downs5 = 6 - ups5
                if max(ups5, downs5) >= 5:  # 5/6 = 83% (tightened 2026-05-22 from 4/6)
                    direction_5m = 'UP' if ups5 > downs5 else 'DOWN'
                    prob_raw = max(ups5, downs5) / 6
                    window_str = f'{max(ups5, downs5)}/6 5m candles'

        direction = direction_1m or direction_5m
        if direction is None or prob_raw == 0:
            return None

        markets = self._active_markets(symbol, tf)
        if not markets:
            return None
        mkt = markets[0]

        outcomes  = mkt.get('outcomes', ['Up', 'Down'])
        token_ids = mkt.get('token_ids', [])
        target    = 'Up' if direction == 'UP' else 'Down'

        token_id = None
        for i, o in enumerate(outcomes):
            if o.lower() == target.lower() and i < len(token_ids):
                token_id = token_ids[i]
                break
        if not token_id:
            return None

        mid = self._token_price(token_id)
        if not mid:
            return None

        # Filter near-expired/junk markets: prices below 0.10 mean the market has nearly
        # resolved already — signals are noise and fills are impossible
        if mid < 0.10:
            return None

        # 2026-06-04: coinflip-price gate. When the bought token is priced 0.45-0.55,
        # the market is calling the outcome a coinflip — directly contradicting MISPRICED's
        # "direction is clear" thesis. Weekday counterfactual (true-ev reconstructed):
        # this band bleeds -31.3% ret/$ over 7d (n=229) and -27.6% over 3d (n=109) — the
        # one consistent loser across both windows. Cutting it ~halves the weekday MISPRICED
        # bleed (7d -14.1%->-8.6%, 3d -8.9%->-4.7%) for -19% volume. EV-floor by contrast
        # did not separate. See journal idx 217. Reversal: remove this block + restart.
        if 0.45 <= mid < 0.55:
            return None

        # Fix: get_hit_rates returns 0 for symbols with no resolved trades (not missing).
        # Use 50% as neutral default so missing data doesn't crush prob.
        rates = self.bot.get_hit_rates()
        raw_rate = rates.get(symbol.lower())
        sym_rate = (raw_rate / 100.0) if raw_rate else 0.50

        # Blend candle momentum with historical hit-rate (neutral=50% if no history)
        prob = (prob_raw + sym_rate) / 2

        ev = prob * 1.0 - mid * (1 + self.FEE_RATE)
        if ev < 0.04:  # tightened 2026-05-22 from 0.01 (back to pre-loosening level)
            return None
        # 2026-05-26 EV ceiling. High-EV signals are model overconfidence: 7d/OOS both
        # show ev>0.12 bucket bleeds at -$0.43 to -$1.06/trade despite "high edge"
        # math. The market prices the truth; the alignment model overestimates prob
        # on tail signals. Adds the matched cap to the 0.04 floor. See journal #191.
        if ev > 0.12:
            return None

        # MISPRICED runs in NORMAL (non-inverted) mode; RL gate handles bad-state filtering.
        inverted = False

        # Conviction tiers extended 2026-05-22 so MISPRICED can produce STRONG/EXTREME
        # signals that pass the global conviction_levels=["STRONG","EXTREME"] live filter.
        if prob_raw >= 0.90:
            conv = 'EXTREME'
        elif prob_raw >= 0.80:
            conv = 'STRONG'
        elif prob_raw >= 0.75:
            conv = 'HIGH'
        else:
            conv = 'MEDIUM'
        # 2026-05-26: EXTREME conviction (9-10/10 alignment) signals are the most
        # confident the alignment model gets — and the worst-performing bucket
        # in 7d (n=240, -$159, -$0.66/trade). Same overconfidence story as the
        # EV cap above. Block at entry, not at the conviction_levels gate (that
        # only affects real-money routing, not paper).
        if conv == 'EXTREME':
            return None

        # ── REGIME-LOG (side-channel; never blocks trade) ──
        # Tag each MISPRICED signal with regime features so we can later segment
        # PnL by regime (trending vs chop, vol level, BTC context). Join on slug
        # to claude_paper_trades.json after resolution.
        try:
            _c1 = candles_1m[-10:]
            _bodies = []
            for _c in _c1:
                _rng = _c['high'] - _c['low']
                if _rng > 1e-9:
                    _bodies.append(abs(_c['close'] - _c['open']) / _rng)
            _body_ratio = (sum(_bodies) / len(_bodies)) if _bodies else None
            if len(candles_1m) >= 15:
                _u15 = sum(1 for _c in candles_1m[-15:] if _c['close'] > _c['open'])
                _align_15 = max(_u15, 15 - _u15) / 15
            else:
                _align_15 = None
            _c5 = self._get_candles(symbol, '5m', limit=12)
            _vol5m = None
            if len(_c5) >= 5:
                _rets = []
                for _i in range(1, len(_c5)):
                    _p0, _p1 = _c5[_i - 1]['close'], _c5[_i]['close']
                    if _p0 > 0:
                        _rets.append((_p1 - _p0) / _p0)
                if _rets:
                    _m = sum(_rets) / len(_rets)
                    _vol5m = (sum((_r - _m) ** 2 for _r in _rets) / len(_rets)) ** 0.5
            if symbol == 'BTC':
                _btc_dir, _btc_chg = 'SELF', None
            else:
                _btc = self._get_candles('BTC', '5m', limit=12)
                if len(_btc) >= 2 and _btc[0]['close'] > 0:
                    _btc_chg = (_btc[-1]['close'] - _btc[0]['close']) / _btc[0]['close'] * 100
                    _btc_dir = 'UP' if _btc_chg > 0 else 'DOWN'
                else:
                    _btc_dir, _btc_chg = None, None
            _entry = {
                'ts':          datetime.now(timezone.utc).isoformat(),
                'slug':        mkt['slug'],
                'symbol':      symbol,
                'direction':   direction,
                'ask':         round(mid, 4),
                'conv':        conv,
                'window':      window_str,
                'align_short': round(prob_raw, 3),
                'align_15':    round(_align_15, 3) if _align_15 is not None else None,
                'body_ratio':  round(_body_ratio, 3) if _body_ratio is not None else None,
                'vol5m':       round(_vol5m, 5) if _vol5m is not None else None,
                'btc_dir':     _btc_dir,
                'btc_chg_pct': round(_btc_chg, 3) if _btc_chg is not None else None,
                'utc_hour':    datetime.now(timezone.utc).hour,
            }
            with open('mispriced_regime_log.jsonl', 'a', encoding='utf-8') as _f:
                _f.write(json.dumps(_entry) + '\n')
        except Exception as _re:
            try: logger.warning(f'[MISPRICED-REGIME-LOG] {_re}')
            except Exception: pass
        # ── end regime log ──

        return {
            'play_type': 'MISPRICED',
            'symbol': symbol,
            'timeframe': tf,
            'direction': direction,
            'token_id': token_id,
            'ask': round(mid, 4),
            'prob': round(prob * 100, 1),
            'ev': round(ev, 4),
            'ev_pct': round(ev / (mid * (1 + self.FEE_RATE)) * 100, 1),
            'secs_left': None,
            'slug': mkt['slug'],
            'condition_id': mkt['condition_id'],
            'reasoning': (
                f"{window_str} point {direction}. "
                f"Historical hit-rate {sym_rate*100:.0f}%. "
                f"Blended prob {prob*100:.0f}% vs market price {mid:.3f}. "
                f"EV = {ev:.4f}."
                + (' [INVERTED]' if inverted else '')
            ),
            'conviction': conv,
            'inverted': inverted,
        }

    def _play_manipulation(self, symbol: str, tf: str) -> Optional[Dict]:
        """
        MANIPULATION DETECTION — two independent signals combined:

        1. WICK HUNT: 3+ pin-bar rejections in the same direction over the last
           10 candles (lower wick > 1.5× body for bull, upper for bear).
           Pattern = someone repeatedly trying to push price one way but failing.

        2. PRICE SUPPRESS: Strong directional momentum (≥6/8 candles aligned)
           but the corresponding YES/NO token is priced 20¢+ below fair value.
           Pattern = market price being artificially held away from fair value.

        Returns a play when either signal fires AND the EV is >= 0.08.
        """
        # Symbols in paper-only mode for MANIP — confirmed negative EV, still collecting data
        _MANIP_PAPER_SYMBOLS = {'BTC', 'SOL'}

        candles = self._get_candles(symbol, '1m', limit=20)
        if len(candles) < 10:
            return None

        last10 = candles[-10:]
        last8  = candles[-8:]

        # ── 1. Wick hunt analysis ─────────────────────────────────────────────
        bull_rejections = 0   # lower wick >> body = price rejected downside
        bear_rejections = 0   # upper wick >> body = price rejected upside
        for c in last10:
            body       = abs(c['close'] - c['open'])
            rng        = c['high'] - c['low']
            if rng < 1e-9:
                continue
            lower_wick = min(c['open'], c['close']) - c['low']
            upper_wick = c['high'] - max(c['open'], c['close'])
            # Pin bar: wick > 1.5× body AND > 35% of full range
            if lower_wick > max(body * 1.5, rng * 0.35):
                bull_rejections += 1
            if upper_wick > max(body * 1.5, rng * 0.35):
                bear_rejections += 1

        wick_direction: Optional[str] = None
        wick_count = 0
        if bull_rejections >= 4:
            wick_direction, wick_count = 'UP',   bull_rejections
        elif bear_rejections >= 4:
            wick_direction, wick_count = 'DOWN', bear_rejections

        # ── 2. Momentum / price divergence ───────────────────────────────────
        ups   = sum(1 for c in last8 if c['close'] > c['open'])
        downs = 8 - ups
        momentum_direction = 'UP' if ups >= downs else 'DOWN'
        momentum_strength  = max(ups, downs) / 8   # 0.5–1.0

        # Only care about strong momentum (≥6/8)
        momentum_signal = momentum_strength >= 0.75

        # Need at least one signal
        direction = wick_direction or (momentum_direction if momentum_signal else None)
        if not direction:
            return None

        # ── Market token price ────────────────────────────────────────────────
        markets = self._active_markets(symbol, tf)
        if not markets:
            return None
        mkt = markets[0]

        outcomes  = mkt.get('outcomes', ['Up', 'Down'])
        token_ids = mkt.get('token_ids', [])
        target    = 'Up' if direction == 'UP' else 'Down'
        token_id  = None
        for i, o in enumerate(outcomes):
            if o.lower() == target.lower() and i < len(token_ids):
                token_id = token_ids[i]
                break
        if not token_id:
            return None

        mid = self._token_price(token_id)
        # Upper bound: already priced in, no edge. Lower bound bumped 0.10 -> 0.20
        # (audit 2026-05-14, n=28,513 blocked-shadow MANIP signals): ask < $0.20 was
        # 5,864 trades / 6.5% WR / -$8,228 shadow PnL — by far the largest single bleed
        # vector. Cutting it lifts the rest of MANIP from -$2,694 to +$5,533 lifetime
        # and WR from 39.5% to 48.0%. These are near-resolved markets where price is noise.
        if not mid or mid < 0.20 or mid >= 0.92:
            return None

        # Time-to-resolution floor — audit 2026-05-14: secs_to_close < 60s = 5,650 trades,
        # 27% WR, -$4,678 shadow PnL. Adverse moves can't reverse fast enough at <60s.
        _interval = 300 if tf == '5m' else 900
        _market_ts = mkt.get('market_ts', 0)
        if _market_ts:
            secs_to_close = (_market_ts + _interval) - time.time()
            if secs_to_close < 60:
                return None

        # ── Fair value estimate ───────────────────────────────────────────────
        fair = momentum_strength if momentum_signal else 0.60
        if wick_direction == direction:
            # Wick confirmation — each extra rejection adds a small boost
            fair = min(fair + min(wick_count - 2, 4) * 0.025, 0.95)

        divergence = fair - mid   # how much the market is underpricing this side

        # Need meaningful suppression gap — raised from 0.15 to 0.22 to filter weak signals
        # Data: 42% WR at 0.15+ threshold; tightening removes low-quality noise trades
        if divergence < 0.22:
            return None

        ev = fair - mid * (1 + self.FEE_RATE)
        if ev < 0.08:
            return None

        # ── RL gate — skip states learned to be unprofitable ─────────────────
        rl_allow, rl_reason = self.manip_rl.should_enter(
            symbol, mid, momentum_strength, divergence, direction)
        if not rl_allow:
            self._think(f'  [MANIP-RL] Skipping {symbol} {direction}: {rl_reason}', 'skip')
            _rl_q, _rl_n, _rl_key = self.manip_rl.score(symbol, mid, momentum_strength, divergence, direction)
            _interval = 300 if tf == '5m' else 900
            _end_ts = float(mkt.get('market_ts', 0) + _interval)
            try:
                self.rl_shadow.log_blocked(
                    rl_system='manip', state_key=_rl_key,
                    rl_q=_rl_q, rl_n=_rl_n, rl_reason=rl_reason,
                    symbol=symbol, direction=direction,
                    entry_price=mid, stake=5.0,
                    secs_to_close=max(_end_ts - time.time(), 0),
                    market_end_ts=_end_ts,
                    market_slug=mkt.get('slug', ''),
                    play_type='MANIP', token_id=token_id or '')
            except Exception as _se:
                logger.debug(f'[RL-SHADOW] manip log error: {_se}')
            return None

        # ── Classify ─────────────────────────────────────────────────────────
        # Thresholds tightened: data shows STRONG (36% WR) < MEDIUM (40% WR) — confidence
        # was miscalibrated. EXTREME added for highest-quality COMBINED signals.
        if wick_direction == direction and momentum_signal:
            manip_type = 'COMBINED'
            if divergence >= 0.40 and wick_count >= 5:
                conviction = 'EXTREME'
            elif divergence >= 0.32:
                conviction = 'STRONG'
            elif divergence >= 0.24:
                conviction = 'HIGH'
            else:
                conviction = 'MEDIUM'
        elif wick_direction == direction:
            manip_type = 'WICK-HUNT'
            conviction = 'HIGH' if wick_count >= 6 else 'MEDIUM'
        else:
            manip_type = 'SUPPRESSION'
            conviction = 'STRONG' if divergence >= 0.38 else ('HIGH' if divergence >= 0.28 else 'MEDIUM')

        wick_label = (
            f"{wick_count} {'lower' if direction=='UP' else 'upper'}-wick rejections"
            if wick_direction else 'no wick signal'
        )
        mom_label = (
            f"{max(ups,downs)}/8 candles {direction}"
            if momentum_signal else 'weak momentum'
        )

        # Data-driven MANIP filter (backtest 2026-05-02, n=66, baseline PnL -$208):
        # DOGE always allowed (+$50/n=9, 44% WR — only profitable symbol).
        # UP direction allowed for non-ETH (UP+NOT-ETH: +$26/n=10, 60% WR).
        # ETH MANIP catastrophic (-$156/n=14, 7.1% WR). DOWN MANIP loses everywhere else.
        allow = (symbol == 'DOGE') or (direction == 'UP' and symbol != 'ETH')
        if not allow:
            return None

        return {
            'play_type':   'MANIP',
            'manip_type':  manip_type,
            'symbol':      symbol,
            'timeframe':   tf,
            'direction':   direction,
            'token_id':    token_id,
            'ask':         round(mid,  4),
            'fair_value':  round(fair, 4),
            'divergence':  round(divergence, 4),
            'prob':        round(fair * 100, 1),
            'ev':          round(ev,   4),
            'ev_pct':      round(ev / (mid * (1 + self.FEE_RATE)) * 100, 1),
            'secs_left':   None,
            'slug':        mkt['slug'],
            'condition_id': mkt.get('condition_id', ''),
            'conviction':  conviction,
            'wick_count':  wick_count,
            'bull_rejections': bull_rejections,
            'bear_rejections': bear_rejections,
            'momentum_pct': round(momentum_strength * 100, 0),
            'force_paper': symbol in _MANIP_PAPER_SYMBOLS,  # paper-only symbols still generate signals for data
            'reasoning': (
                f"[{manip_type}] {symbol} {direction}: "
                f"fair={fair*100:.0f}% — market only {mid:.3f} ({divergence*100:.0f}¢ gap). "
                f"{wick_label}. {mom_label}."
            ),
        }

    # ── public API ────────────────────────────────────────────────────────────

    def _instrumented_play(self, symbol: str, tf: str, generator) -> Optional[Dict]:
        """Run one play-type generator with brain logging."""
        play_name = {'_play_time_lock':    'TIME-LOCK',
                     '_play_momentum_lock': 'MOMENTUM',
                     '_play_mispriced':    'MISPRICED',
                     '_play_manipulation': 'MANIP'}.get(generator.__name__, generator.__name__)
        self._think(f"  [{play_name}] {symbol}/{tf} — checking...", 'check')

        # Update matrix to 'scanning' state
        if symbol not in self.scan_matrix:
            self.scan_matrix[symbol] = {}
        self.scan_matrix[symbol][tf] = {'status': 'scanning', 'play': play_name, 'prob': None, 'ev': None, 'direction': None}

        try:
            p = generator(symbol, tf)
        except Exception as e:
            self._think(f"  [{play_name}] {symbol}/{tf} error: {str(e)[:60]}", 'warn')
            self.scan_matrix[symbol][tf] = {'status': 'error', 'play': play_name, 'prob': None, 'ev': None, 'direction': None}
            return None

        if p:
            self._think(f"  [{play_name}] {symbol}/{tf} ★ PLAY FOUND: {p['direction']} prob={p['prob']}% EV=+{p['ev']} ({p['conviction']})", 'found')
            self.scan_matrix[symbol][tf] = {
                'status': 'found',
                'play': play_name,
                'prob': p['prob'],
                'ev': p['ev'],
                'direction': p['direction'],
                'conviction': p['conviction'],
            }
        else:
            self.scan_matrix[symbol][tf] = {'status': 'skip', 'play': play_name, 'prob': None, 'ev': None, 'direction': None}

        return p

    # ── broad-market (non-crypto) plays ──────────────────────────────────────

    def _fetch_broad_markets(self) -> list:
        """Fetch top active markets by 24h volume from Gamma API.
        Cached 5 minutes to avoid hammering. Returns raw market dicts
        with pre-parsed token IDs and outcome prices attached.

        2026-05-30: NEAR-CLOSE pool fix. The original single fetch sorted by
        volume24hr desc returns mostly long-dated headline markets (elections,
        sports finals) — almost none fall inside NEAR-CLOSE's 60s-48h window.
        Add a SECOND fetch sorted by endDate ascending with end_date_min=now
        so we actually see markets that are about to close. Merge + dedupe by
        market id. Volume floor stays at 1000 to keep illiquid junk out.
        """
        import time as _time
        from datetime import timezone as _tz
        cached = self._candle_api_cache.get('__broad_markets')
        if cached and _time.time() - cached[1] < 300:
            return cached[0]

        markets: list = []
        try:
            r = self._session.get(
                f"{self.GAMMA}/markets",
                params={'active': 'true', 'closed': 'false',
                        'limit': 150, 'order': 'volume24hr', 'ascending': 'false'},
                timeout=12
            )
            if r.status_code == 200:
                raw = r.json()
                markets = raw if isinstance(raw, list) else raw.get('data', [])
        except Exception as e:
            self._think(f'[BROAD] Gamma volume-fetch error: {str(e)[:60]}', 'warn')

        # Second pass: markets actually closing soon. Without this, the
        # top-by-volume list is dominated by long-dated markets and
        # NEAR-CLOSE almost never finds candidates in its 48h window.
        try:
            _now_iso = datetime.now(_tz.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
            r2 = self._session.get(
                f"{self.GAMMA}/markets",
                params={'active': 'true', 'closed': 'false',
                        'limit': 150, 'order': 'endDate', 'ascending': 'true',
                        'end_date_min': _now_iso},
                timeout=12
            )
            if r2.status_code == 200:
                raw2 = r2.json()
                soon = raw2 if isinstance(raw2, list) else raw2.get('data', [])
                seen_ids = {m.get('id') for m in markets if m.get('id')}
                for m in soon:
                    if m.get('id') and m['id'] not in seen_ids:
                        markets.append(m)
                        seen_ids.add(m['id'])
        except Exception as e:
            self._think(f'[BROAD] Gamma end-date-fetch error: {str(e)[:60]}', 'warn')

        if not markets:
            return []

        filtered = []
        for m in markets:
            slug = m.get('slug', '') or ''
            # Skip crypto updown markets — already handled by the crypto scanner
            if '-updown-' in slug and ('5m-' in slug or '15m-' in slug):
                continue
            # Must accept orders and have a CLOB
            if not m.get('acceptingOrders', False) or not m.get('enableOrderBook', False):
                continue
            # Parse token IDs
            token_ids = m.get('clobTokenIds', '[]')
            if isinstance(token_ids, str):
                try:
                    token_ids = json.loads(token_ids)
                except Exception:
                    token_ids = []
            if len(token_ids) < 2:
                continue
            # Parse outcome prices (mid-price, no CLOB hit needed)
            out_prices = m.get('outcomePrices', '[]')
            if isinstance(out_prices, str):
                try:
                    out_prices = [float(x) for x in json.loads(out_prices)]
                except Exception:
                    out_prices = []
            if not out_prices:
                continue
            # Must have meaningful volume
            vol24 = float(m.get('volume24hr', 0) or 0)
            if vol24 < 1000:
                continue
            m['_token_ids'] = token_ids
            m['_out_prices'] = out_prices
            filtered.append(m)

        self._candle_api_cache['__broad_markets'] = (filtered, _time.time())
        return filtered

    @staticmethod
    def _parse_outcomes(mkt: dict):
        raw = mkt.get('outcomes', '["Yes","No"]')
        if isinstance(raw, str):
            try:
                return json.loads(raw)
            except Exception:
                pass
        return raw if isinstance(raw, list) else ['Yes', 'No']

    @staticmethod
    def _slug_label(slug: str) -> str:
        parts = [p for p in slug.split('-') if len(p) > 2 and not p.isdigit()]
        return parts[0].upper()[:6] if parts else 'EVENT'

    def _play_broad_near_close(self, mkt: dict) -> Optional[Dict]:
        """
        NEAR-CLOSE (broad): non-crypto binary market ending within 48 hours
        where the crowd is 75–97% confident on one outcome but still
        trading below $1.

        Uses Gamma outcomePrices (market mid) directly — no CLOB needed
        for scanning, only for order placement.  Edge: crowd conviction
        locks in sharply as resolution approaches.
        """
        from datetime import timezone
        end_date = mkt.get('endDate', '')
        if not end_date:
            return None
        try:
            end_dt = datetime.fromisoformat(end_date.replace('Z', '+00:00'))
            now_utc = datetime.now(timezone.utc)
            secs_left = (end_dt - now_utc).total_seconds()
        except Exception:
            return None

        if not (60 < secs_left < 172800):  # 1 min – 48 hours (2026-05-16: extended from 24h to widen candidate pool; time-decay bump still anchored to 24h via clamp below)
            return None

        out_prices = mkt['_out_prices']
        token_ids  = mkt['_token_ids']
        outcomes   = self._parse_outcomes(mkt)

        # Leading outcome: 0.65–0.85 (low bound 0.70->0.65 on 2026-05-30 per user — "produce more plays").
        # Lowering the floor admits cheaper near-resolution markets, which ALSO carry more per-dollar
        # edge (helps pass the EV gate) — the safer direction to widen. Was 0.70-0.85 (2026-05-22, from
        # 0.75-0.82). Above 0.82 the payout is compressed; watch WR — if ask>0.82 drops below 80%, retighten.
        best_idx, best_mid = None, 0.0
        for i, p in enumerate(out_prices[:len(token_ids)]):
            if 0.65 <= p <= 0.85 and p > best_mid:
                best_idx, best_mid = i, p
        if best_idx is None:
            return None

        # Use real CLOB ask if wallet connected, fall back to Gamma mid-price
        clob_ask = self._token_price(token_ids[best_idx])
        ask = clob_ask if clob_ask else best_mid
        outcome_name = outcomes[best_idx] if best_idx < len(outcomes) else 'YES'

        hours_left  = secs_left / 3600
        # The closer to close, the more certain the crowd is correct.
        # Clamped at 0 so markets in the new 24-48h band get NO time-decay bump
        # (preserves the original 0-24h curve; 24-48h gets est_prob = best_mid).
        time_factor = max(0.0, 1 - (hours_left / 24))  # 0→1 as window closes over 24h, 0 beyond
        est_prob    = best_mid + (1.0 - best_mid) * 0.50 * time_factor
        est_prob    = min(est_prob, 0.99)

        ev = est_prob - ask * (1 + self.FEE_RATE)
        if ev < 0.02:  # loosened 2026-05-22 from 0.03 per user — "need more plays"
            return None

        vol24    = float(mkt.get('volume24hr', 0) or 0)
        question = mkt.get('question', mkt.get('slug', 'Unknown'))[:80]
        slug     = mkt.get('slug', '')

        return {
            'play_type':    'NEAR-CLOSE',
            'symbol':       self._slug_label(slug),
            'timeframe':    f'{hours_left:.1f}h',
            'direction':    outcome_name.upper(),
            'token_id':     token_ids[best_idx],
            'ask':          round(ask, 4),
            'prob':         round(est_prob * 100, 1),
            'ev':           round(ev, 4),
            'ev_pct':       round(ev / (ask * (1 + self.FEE_RATE)) * 100, 1),
            'secs_left':    int(secs_left),
            'slug':         slug,
            'condition_id': mkt.get('conditionId', ''),
            'title':        question,
            'volume_24h':   vol24,
            'reasoning': (
                f"Closes in {hours_left:.1f}h. Crowd at {best_mid*100:.0f}% on '{outcome_name}'. "
                f"Time-decay → est. prob {est_prob*100:.0f}%. "
                f"Edge = {ev:.4f}/token (after 2% fee). 24h vol = ${vol24:,.0f}."
            ),
            'conviction': 'STRONG' if (ask >= 0.85 and hours_left < 4) else ('HIGH' if (ask >= 0.80 and hours_left < 8) else 'MEDIUM'),
        }

    def _play_broad_vol_surge(self, mkt: dict) -> Optional[Dict]:
        """
        VOL-SURGE (broad): market where 24h volume is >2.5× its current
        liquidity AND one outcome is priced 0.60–0.96.  High relative
        volume signals informed traders loading a side — price hasn't
        fully caught up.  Uses Gamma outcomePrices; no CLOB needed.
        """
        # LOL and DOTA2 markets are thin/illiquid — high vol/liq ratios are noise,
        # not informed-money signal. Both categories are net-negative in back-data.
        slug = mkt.get('slug', '')
        if slug.startswith('lol-') or slug.startswith('dota2-') or slug.startswith('dota-'):
            return None

        vol24 = float(mkt.get('volume24hr', 0) or 0)
        liq   = float(mkt.get('liquidity', 0) or mkt.get('liquidityNum', 0) or 1)
        if vol24 < 18000:  # 2026-05-30: 25000->18000 per user "produce more plays" — admit thinner-but-liquid
            return None
        surge_ratio = vol24 / max(liq, 1)
        if surge_ratio < 6:  # 2026-05-30: 8->6 per user (was 10 on 2026-05-22). Admit moderate surges; >32 cap unchanged
            return None
        # 2026-05-14 audit (n=52 resolved): surge_ratio > 30 was 0/3 WR,
        # EXTREME conviction (>20) was 50% WR / -$3, while STRONG (12-20)
        # was 82.6% WR / +$27. Mega-surges = illiquid noise, not informed flow.
        # 2026-05-22: loosened max 30 -> 32 per user. Stay just outside the 0/3 zone.
        if surge_ratio > 32:
            return None

        out_prices = mkt['_out_prices']
        token_ids  = mkt['_token_ids']
        outcomes   = self._parse_outcomes(mkt)

        # Dominant outcome: 0.55–0.76 (loosened 2026-05-22 from 0.60-0.72 per user — "need more plays").
        # 2026-05-14 audit: 0.50-0.65 = +$11.89 / 22 trades (sweet spot),
        # 0.65-0.80 = +$1.17 / 24 trades (compressed payout, ~breakeven),
        # >=0.80 = -$3.05 / 6 trades (R/R too compressed even at 67% WR).
        # New band 0.55-0.76 captures the sweet-spot lower edge + a slice of the breakeven zone.
        # Avoids the >=0.80 known-bleeder territory.
        best_idx, best_mid = None, 0.0
        for i, p in enumerate(out_prices[:len(token_ids)]):
            if 0.55 <= p <= 0.76 and p > best_mid:
                best_idx, best_mid = i, p
        if best_idx is None:
            return None

        # Use real CLOB ask if wallet connected, fall back to Gamma mid-price
        clob_ask = self._token_price(token_ids[best_idx])
        ask = clob_ask if clob_ask else best_mid
        outcome_name = outcomes[best_idx] if best_idx < len(outcomes) else 'YES'

        # Info bump: bigger surge ratio = stronger informed signal (anchored to mid-price)
        info_bump = 0.04 * min(surge_ratio / 10, 1.0)
        est_prob  = min(best_mid + info_bump, 0.97)
        ev        = est_prob - ask * (1 + self.FEE_RATE)
        if ev < 0.03:  # loosened 2026-05-22 from 0.04 per user — "need more plays"
            return None

        question = mkt.get('question', mkt.get('slug', 'Unknown'))[:80]
        slug     = mkt.get('slug', '')

        from datetime import timezone
        try:
            end_dt    = datetime.fromisoformat((mkt.get('endDate','') or '').replace('Z','+00:00'))
            secs_left = int((end_dt - datetime.now(timezone.utc)).total_seconds())
            hours_left = secs_left / 3600
            tf_str    = f'{hours_left:.0f}h' if hours_left < 120 else 'open'
        except Exception:
            secs_left = None
            tf_str    = 'open'

        # 2026-05-14: skip long-dated markets. 36/88 lifetime trades pile up
        # as pending forever (one STRIKE bet had secs_left=231 days).
        # 7-day cap keeps the resolved/total ratio healthy.
        if secs_left is not None and secs_left > 7 * 86400:
            return None

        return {
            'play_type':    'VOL-SURGE',
            'symbol':       self._slug_label(slug),
            'timeframe':    tf_str,
            'direction':    outcome_name.upper(),
            'token_id':     token_ids[best_idx],
            'ask':          round(ask, 4),
            'prob':         round(est_prob * 100, 1),
            'ev':           round(ev, 4),
            'ev_pct':       round(ev / (ask * (1 + self.FEE_RATE)) * 100, 1),
            'secs_left':    secs_left,
            'slug':         slug,
            'condition_id': mkt.get('conditionId', ''),
            'title':        question,
            'volume_24h':   vol24,
            'surge_ratio':  round(surge_ratio, 1),
            'reasoning': (
                f"Vol-surge: ${vol24:,.0f} 24h vol vs ${liq:,.0f} liq "
                f"({surge_ratio:.1f}× ratio). "
                f"Informed traders loading '{outcome_name}' at {best_mid*100:.0f}¢. "
                f"EV = {ev:.4f}/token (after 2% fee)."
            ),
            'conviction': 'EXTREME' if surge_ratio > 20 else ('STRONG' if surge_ratio > 12 else ('HIGH' if surge_ratio > 8 else 'MEDIUM')),
        }

    # ── paper-trade logging + outcome tracking ────────────────────────────────

    PAPER_LOG_FILE = 'claude_paper_trades.json'

    def _load_paper_log(self) -> list:
        """Read the paper-trade JSON. Mtime-cached: hot calls (dashboard polling)
        hit the in-memory cache. Cold calls fall through to disk and retry 3x on
        transient failure (Windows os.replace can briefly make the file unopenable
        to readers). Logs the actual exception loudly on persistent failure —
        silent return-[] caused the 2026-05-16 13:40 wipe."""
        import time as _t
        path = _resolve_state_path(self.PAPER_LOG_FILE)
        if not os.path.exists(path):
            return []
        # Try mtime cache first — sub-ms when the file hasn't changed.
        # IMPORTANT: return list(cached) so callers can safely append/remove without
        # polluting the cache for other callers. Trade dicts are still shared by
        # reference — direct dict mutation between load and save is the existing
        # race surface; the lock + atomic os.replace mtime-bump remain the guard.
        try:
            mtime = os.path.getmtime(path)
            _cached = _JSON_CACHE.get(path)
            if _cached and _cached[0] == mtime:
                return list(_cached[1])
        except OSError:
            pass
        last_err = None
        for attempt in range(3):
            try:
                # 2026-05-23 PR-5 fix: explicit utf-8. orjson writes UTF-8 bytes
                # (e.g. emoji / non-ASCII punctuation in market titles); on Windows
                # open() without encoding= defaults to cp1252 and chokes on byte
                # 0x9d in multi-byte UTF-8 sequences.
                with open(path, 'r', encoding='utf-8') as f:
                    data = json.load(f)
                try:
                    _JSON_CACHE[path] = (os.path.getmtime(path), data)
                except OSError:
                    pass
                logger.info(f'[PAPER] Loaded {len(data)} trades from {os.path.basename(path)}')
                # Return a shallow copy so subsequent list-level mutations don't leak
                # into the cache before the writer atomic-replaces and bumps mtime.
                return list(data)
            except Exception as e:
                last_err = e
                _t.sleep(0.05)
        logger.error(f'[PAPER] _load_paper_log FAILED after 3 attempts: {last_err} - returning [] (save guard will refuse to clobber)')
        return []

    _paper_save_lock = __import__('threading').Lock()

    def _save_paper_log(self, trades: list, force: bool = False):
        """Thread-safe write. Refuses to clobber a much larger on-disk file
        with a much smaller new list (the 2026-05-16 wipe pattern): if the
        existing file has >=50 entries and the new payload would drop >50
        entries AND fall below half the prior size, refuse. Pass force=True
        for legitimate truncate/migration paths."""
        import uuid, time as _t
        with self._paper_save_lock:
            path = _resolve_state_path(self.PAPER_LOG_FILE)
            if not force:
                try:
                    if os.path.exists(path):
                        # 2026-05-23 PR-5 fix: utf-8 for orjson-written files
                        with open(path, 'r', encoding='utf-8') as f:
                            _existing = json.load(f)
                        _en = len(_existing) if isinstance(_existing, list) else 0
                        _nn = len(trades) if isinstance(trades, list) else 0
                        if _en >= 50 and _nn < (_en - 50) and _nn < _en * 0.5:
                            logger.error(
                                f'[PAPER] REFUSED save - would write {_nn} entries '
                                f'over {_en} on disk (load-failure wipe guard; '
                                f'pass force=True if intentional)'
                            )
                            return
                except Exception as _ge:
                    logger.warning(f'[PAPER] save-guard read failed: {_ge} - proceeding')
            try:
                # 2026-05-23 PR-5: orjson-backed atomic write (retry built in)
                _atomic_write_json(path, trades[-50000:], indent=False, replace_retries=3)
            except Exception as e:
                logger.warning(f'[PAPER] Save error: {e}')

    MIN_CALIBRATION_SAMPLES = 15  # resolved trades needed before trusting historical WR
    AUTO_DISABLE_THRESHOLD  = 0.40  # auto-flip to paper if win rate < 40% after enough samples

    def _calibrated_wr(self, play_type: str, conviction: str = None) -> Optional[float]:
        """Return actual historical win rate for this play_type (+ optional conviction).
        Returns None if fewer than MIN_CALIBRATION_SAMPLES resolved trades exist."""
        trades = self._load_paper_log()
        resolved = [t for t in trades
                    if t.get('resolved') and t.get('outcome') in ('WIN', 'LOSS')
                    and t.get('play_type') == play_type]
        if conviction:
            resolved = [t for t in resolved if t.get('conviction') == conviction]
        if len(resolved) < self.MIN_CALIBRATION_SAMPLES:
            return None
        wins = sum(1 for t in resolved if t.get('outcome') == 'WIN')
        return wins / len(resolved)

    def _check_auto_disable(self, play_type: str) -> None:
        """Auto-flip a strategy to paper if it's clearly negative EV after enough samples."""
        if self.strategy_modes.get('_protection_override', False):
            return  # 2026-05-17: user toggled protection_override — keep strategy where they set it
        if self.strategy_modes.get(play_type) != 'real':
            return  # already paper, nothing to do
        if 'MANIP' in play_type.upper():
            return  # MANIP: low WR is expected — large winners offset cluster losses
        if 'MISPRICED' in play_type.upper():
            return  # MISPRICED: per user 2026-05-10 — profitable even at low WR, do not auto-paper
        trades = self._load_paper_log()
        resolved = [t for t in trades
                    if t.get('resolved') and t.get('outcome') in ('WIN', 'LOSS')
                    and t.get('play_type') == play_type]
        if len(resolved) < self.MIN_CALIBRATION_SAMPLES:
            return
        wins = sum(1 for t in resolved if t.get('outcome') == 'WIN')
        wr = wins / len(resolved)
        if wr < self.AUTO_DISABLE_THRESHOLD:
            self.strategy_modes[play_type] = 'paper'
            self._save_strategy_modes()
            logger.warning(f'[CALIBRATE] {play_type} auto-disabled (WR={wr*100:.1f}% < {self.AUTO_DISABLE_THRESHOLD*100:.0f}% threshold)')
            try:
                self.bot._tg_notify(
                    f'⚠️ AUTO-DISABLED: {play_type}\n'
                    f'Win rate {wr*100:.1f}% over {len(resolved)} trades — switched to PAPER mode.'
                )
            except Exception:
                pass

    def _update_drawdown(self, outcome: str, pnl: float, play_type: str = '') -> None:
        """Call after each resolved trade. Checks consecutive losses + total PnL drawdown.
        Entire function short-circuits if user has disabled drawdown protection via /drawdown off."""
        if not self.drawdown_protection_enabled:
            return
        # Track consecutive losses — MANIP is exempt (structural edge, small bets,
        # expected clustering losses when markets resolve YES simultaneously)
        is_manip = 'MANIP' in play_type.upper()
        if outcome == 'LOSS' and not is_manip:
            self._consec_losses += 1
        elif outcome != 'LOSS':
            self._consec_losses = 0

        # Init session baseline on first resolved trade — only real_trade=True (paper sims don't move wallet)
        trades = self._load_paper_log()
        total_pnl = sum(t.get('paper_pnl') or 0 for t in trades
                        if t.get('resolved') and t.get('real_trade'))
        if self._session_start_pnl is None:
            # _update_drawdown is only called for real trades, so pnl is always real money
            self._session_start_pnl = total_pnl - pnl  # baseline before this trade

        drawdown = total_pnl - self._session_start_pnl
        if self.bot.wallet_live:
            _raw_bal = self.bot.get_usdc_balance(max_age=60)  # fresher than default 5min
            if _raw_bal > 100:
                self._last_known_balance = _raw_bal  # keep cache fresh
            # If RPC returned $100 fallback, use last known real balance
            if _raw_bal <= 100 and self._last_known_balance and self._last_known_balance > 100:
                balance = self._last_known_balance
                logger.info(f'[DRAWDOWN] RPC returned fallback — using cached balance ${balance:.2f}')
            else:
                balance = max(_raw_bal, self._last_known_balance or 0)
        else:
            balance = self.bot.kelly_bankroll
        # If balance is still the $100 fallback and we have no confirmed real balance,
        # skip percentage-based checks entirely — consecutive-loss check still works
        if balance <= 100 and not self._last_known_balance:
            logger.debug(f'[DRAWDOWN] No confirmed balance yet — skipping pct check (drawdown={drawdown:+.2f})')
            if self._consec_losses >= self.CONSEC_LOSS_LIMIT and not self.circuit_breaker_active:
                self._trigger_circuit_breaker(f'{self._consec_losses} consecutive losses')
            return

        dd_pct   = abs(drawdown) / max(balance, 1) if drawdown < 0 else 0

        # Level 1 — warn at 10% drawdown (real trades only, max 1 TG alert per 2 hours)
        if drawdown < 0 and dd_pct >= self.DRAWDOWN_WARN_PCT and not self.circuit_breaker_active:
            logger.warning(f'[DRAWDOWN] Warning: real-trade PnL {drawdown:+.2f} ({dd_pct*100:.1f}% drawdown)')
            import time as _t2
            _now = _t2.time()
            # TG notify only if user hasn't muted via /dd_warn off
            if self.dd_warn_enabled and _now - self._last_dd_warn_ts >= 7200:
                self._last_dd_warn_ts = _now
                self.bot._tg_notify(
                    f'⚠️ DRAWDOWN WARNING\n'
                    f'Real-trade session PnL: ${drawdown:+.2f} ({dd_pct*100:.1f}% of balance)\n'
                    f'Consecutive losses: {self._consec_losses}\n'
                    f'Still trading — will pause at -20%'
                )

        # Level 2 — pause at 20% drawdown
        if drawdown < 0 and dd_pct >= self.DRAWDOWN_PAUSE_PCT and not self.circuit_breaker_active:
            self._trigger_circuit_breaker(f'PnL drawdown {dd_pct*100:.1f}% (${drawdown:+.2f})')
            return

        # Level 3 — pause after N consecutive losses
        if self._consec_losses >= self.CONSEC_LOSS_LIMIT and not self.circuit_breaker_active:
            self._trigger_circuit_breaker(f'{self._consec_losses} consecutive losses')

    def _trigger_circuit_breaker(self, reason: str) -> None:
        """Flip all strategies to paper and alert user."""
        self.circuit_breaker_active = True
        self.circuit_breaker_reason = reason
        # Save all modes as paper
        for pt in self.PLAY_TYPES:
            self.strategy_modes[pt] = 'paper'
        self._save_strategy_modes()
        logger.warning(f'[CIRCUIT-BREAKER] TRIGGERED: {reason} — all strategies paused')
        self.bot._tg_notify(
            f'🛑 CIRCUIT BREAKER TRIGGERED\n'
            f'Reason: {reason}\n'
            f'All Claude Picks auto-buying PAUSED.\n'
            f'Reply /resume to restart when ready.'
        )

    def resume_trading(self) -> None:
        """Re-enable all strategies and reset counters. Called via /resume TG command."""
        self.circuit_breaker_active = False
        self.circuit_breaker_reason = ''
        self._consec_losses = 0
        # Reset session baseline to current real-trade total so fresh drawdown tracking starts from now
        try:
            _t = self._load_paper_log()
            self._session_start_pnl = sum(t.get('paper_pnl') or 0 for t in _t
                                          if t.get('resolved') and t.get('real_trade'))
        except Exception:
            self._session_start_pnl = None
        self._last_dd_warn_ts = 0.0
        for pt in self.PLAY_TYPES:
            self.strategy_modes[pt] = 'real'
        self._save_strategy_modes()
        logger.info('[CIRCUIT-BREAKER] Manually resumed — all strategies back to REAL')
        self.bot._tg_notify(
            '✅ TRADING RESUMED\n'
            'All Claude Picks strategies back to REAL mode.\n'
            'Consecutive loss counter reset.'
        )

    def _auto_log_paper_trades(self, picks: list):
        """For every HIGH/EXTREME pick not yet seen today:
        - Wallet live: place a real order AND log to paper log (real_trade=True).
        - No wallet: paper-log only.
        """
        from datetime import timezone, timedelta
        today = datetime.now(timezone.utc).strftime('%Y-%m-%d')

        # Midnight reset — clear in-memory dedup keys when date rolls over
        if today != self._dedup_date:
            logger.info(f'[DEDUP] Date rolled to {today} — clearing {len(self._logged_trade_keys)} cached keys')
            self._logged_trade_keys.clear()
            self._dedup_date = today
            # Morning summary — send PnL report at first scan after midnight
            try:
                self.bot._tg_pnl_report()
            except Exception as _e:
                logger.warning(f'[MORNING-SUMMARY] Failed: {_e}')

        wallet_live = bool(self.bot.wallet_live and self.bot.clob_client)

        trades = self._load_paper_log()
        file_slugdays = {t.get('_key', '').rsplit('|', 1)[0] for t in trades}
        added = 0

        for p in picks:
            if p.get('conviction') not in ('EXTREME', 'STRONG', 'HIGH', 'MEDIUM'):
                continue
            key = f"{p['slug']}|{today}"
            # Lock to prevent race condition where two scan threads both pass dedup simultaneously
            with self._autobuy_lock:
                if key in self._logged_trade_keys or key in file_slugdays:
                    continue
                # Reserve the key immediately under the lock before any async work
                self._logged_trade_keys.add(key)

            # Kelly sizing — use calibrated historical WR if enough samples, else raw scanner estimate
            ask = p['ask']
            play_type = p.get('play_type', '')
            raw_prob = p['prob'] / 100.0
            cal_wr = self._calibrated_wr(play_type, p.get('conviction'))
            if cal_wr is not None:
                # Blend: 70% historical, 30% scanner estimate (trust data more, keep some signal)
                est_prob = 0.70 * cal_wr + 0.30 * raw_prob
                logger.debug(f'[CALIBRATE] {play_type} {p.get("conviction")}: raw={raw_prob:.2f} cal={cal_wr:.2f} blended={est_prob:.2f}')
            else:
                est_prob = raw_prob
            # ClaudePicksRL gate — skip (play_type, symbol, ask, conviction) combos learned to lose
            # 2026-05-02: MISPRICED exemption removed — gate audit showed Q-table flagging
            # the BNB|a_mid|MED state at -0.038 over 95 visits (and others worse). Even with
            # the inversion thesis, some MISPRICED states are persistent losers and should be
            # gated alongside other play types.
            _rl_exempt = False
            # 2026-05-23: per-cell RL bypass for Claude Picks (mirrors HFT bypass_rl).
            # When the user clicks →UNBLOCK on a Claude RL-blocked cell, the cell_override
            # entry gets bypass_rl=true. The RL gate is skipped entirely for that combo,
            # while the Q-table still updates from outcomes (learning continues).
            _bypass_cell_key = f'{play_type}|{p.get("symbol","?")}|{p.get("direction","?")}'
            _bypass_entry = (self.strategy_modes.get('_cell_overrides') or {}).get(_bypass_cell_key)
            if isinstance(_bypass_entry, dict) and _bypass_entry.get('bypass_rl'):
                _rl_exempt = True
            _rl_inst = self._picks_rl_for(play_type)
            picks_rl_allow, picks_rl_reason = _rl_inst.should_enter(
                play_type, p.get('symbol', ''), ask, p.get('conviction', 'HIGH'))
            # Slider-driven stake for blocked records too — keeps shadow PnL consistent with intent.
            _blocked_stake = 3.0 if play_type == 'NEAR-CLOSE' else float(
                self.conviction_bets.get(p.get('conviction', 'MEDIUM'), self.claude_max_bet))
            if not picks_rl_allow and not _rl_exempt:
                self._think(f'[PICKS-RL] SKIP {play_type} {p.get("symbol")} '
                            f'{p.get("conviction")}: {picks_rl_reason}', 'skip')
                _rl_q2, _rl_n2, _rl_key2 = _rl_inst.score(
                    play_type, p.get('symbol', ''), ask, p.get('conviction', 'HIGH'))
                _secs2 = p.get('secs_left') or 0
                _end_ts2 = time.time() + _secs2 if _secs2 else 0
                try:
                    self.rl_shadow.log_blocked(
                        rl_system='picks', state_key=_rl_key2,
                        rl_q=_rl_q2, rl_n=_rl_n2, rl_reason=picks_rl_reason,
                        symbol=p.get('symbol', ''), direction=p.get('direction', ''),
                        entry_price=ask, stake=_blocked_stake,
                        secs_to_close=_secs2,
                        market_end_ts=_end_ts2,
                        market_slug=p.get('slug', ''),
                        play_type=play_type, token_id=p.get('token_id', ''))
                except Exception as _se:
                    logger.debug(f'[RL-SHADOW] picks log error: {_se}')
                # Still log to paper file so the UI shows RL-blocked signals
                _blocked_rec = {
                    '_key': key, 'logged_at': datetime.now().isoformat(),
                    'play_type': play_type, 'symbol': p.get('symbol', ''),
                    'title': p.get('title', p.get('symbol', '')),
                    'direction': p.get('direction', ''), 'ask': ask,
                    'prob': p.get('prob', 0), 'ev': p.get('ev', 0),
                    'conviction': p.get('conviction', ''),
                    'slug': p.get('slug', ''), 'token_id': p.get('token_id', ''),
                    'condition_id': p.get('condition_id', ''),
                    'paper_stake': _blocked_stake,
                    'paper_shares': round(_blocked_stake / (ask * (1 + self.FEE_RATE)), 4) if ask > 0 else 0,
                    'paper_pnl': None, 'outcome': None,
                    'resolved': False, 'real_trade': False,
                    'blocked_by': 'RL', 'blocked_reason': picks_rl_reason,
                }
                _bl = self._load_paper_log()
                if not any(t.get('_key') == key for t in _bl):
                    _bl.append(_blocked_rec)
                    self._save_paper_log(_bl)
                else:
                    self._logged_trade_keys.discard(key)
                continue

            # Minimum ask floor — prices below 8c are illiquid/stale and not fillable in practice
            MIN_ASK = 0.08
            if ask < MIN_ASK:
                logger.info(f'[PRICE-FILTER] Skipping {play_type} {p["symbol"]} — ask={ask:.3f} below floor {MIN_ASK} (illiquid/stale)')
                _blocked_rec = {
                    '_key': key, 'logged_at': datetime.now().isoformat(),
                    'play_type': play_type, 'symbol': p.get('symbol', ''),
                    'title': p.get('title', p.get('symbol', '')),
                    'direction': p.get('direction', ''), 'ask': ask,
                    'prob': p.get('prob', 0), 'ev': p.get('ev', 0),
                    'conviction': p.get('conviction', ''),
                    'slug': p.get('slug', ''), 'token_id': p.get('token_id', ''),
                    'condition_id': p.get('condition_id', ''),
                    'paper_stake': _blocked_stake,
                    'paper_shares': round(_blocked_stake / (ask * (1 + self.FEE_RATE)), 4) if ask > 0 else 0,
                    'paper_pnl': None, 'outcome': None,
                    'resolved': False, 'real_trade': False,
                    'blocked_by': 'LOW-ASK', 'blocked_reason': f'ask {ask:.3f} < floor {MIN_ASK}',
                    'inflated': True,
                }
                _bl = self._load_paper_log()
                if not any(t.get('_key') == key for t in _bl):
                    _bl.append(_blocked_rec)
                    self._save_paper_log(_bl)
                else:
                    self._logged_trade_keys.discard(key)
                continue
            b = (1.0 / ask) - 1 if ask > 0 else 0
            kelly_f = max(0.0, (est_prob * b - (1 - est_prob)) / b) if b > 0 else 0.0
            # EV filter — skip trades where expected value per $1 risked is below threshold
            # EV = prob * (payout - 1) - (1 - prob) = prob/ask - 1  (after 2% fee approx)
            # MANIP exempt: its edge is structural (manipulation detection), not prob/ask ratio.
            # VOL-SURGE (0.05) and NEAR-CLOSE (0.04): their internal absolute-EV filters
            # (>=0.04 and >=0.03 respectively) map to ~4-6% per-dollar in their narrow high-ask
            # price bands. A global 0.10 floor is structurally unreachable for these except in
            # the last hours before close or when CLOB ask sits ~3¢ below mid — which silently
            # dropped most candidates (2026-05-18 audit: 8/14 VOL-SURGE and 3/6 NEAR-CLOSE today).
            ev_per_dollar = (est_prob / max(ask, 0.01)) - 1.0
            pt_upper = play_type.upper()
            if 'VOL-SURGE' in pt_upper:
                MIN_EV = 0.05
            elif 'NEAR-CLOSE' in pt_upper:
                # 2026-05-30: 0.04 -> 0.02. NEAR-CLOSE was 100% EV-blocked on the weekend
                # cohort (2/2 today, 3/3 this window) — the EV floor, not generation, was the
                # binding gate. WR is high (64% weekend) but the 0.70-0.85 asks leave thin
                # per-dollar edge that the 0.04 floor caught. Lowered to admit them. Paper-only.
                MIN_EV = 0.02
            elif 'MOMENTUM' in pt_upper:
                # 2026-05-30: split MOMENTUM off the 0.10 default -> 0.05 (matches VOL-SURGE).
                # All 4 generated today were EV-blocked at 0.10. NOTE weekend WR ~45% — these
                # extra plays are for paper volume/measurement, not proven edge. Revisit before
                # any real_mode flip. Generation is still capped upstream (signal NEUTRAL ~99%).
                MIN_EV = 0.05
            else:
                MIN_EV = 0.10  # require at least 10c expected profit per $1 risked
            if 'MANIP' not in pt_upper and ev_per_dollar < MIN_EV:
                logger.info(f'[EV-FILTER] Skipping {play_type} {p.get("conviction")} {p["symbol"]} — EV={ev_per_dollar:.3f} < {MIN_EV} (ask={ask:.2f} prob={est_prob:.2f})')
                _blocked_rec = {
                    '_key': key, 'logged_at': datetime.now().isoformat(),
                    'play_type': play_type, 'symbol': p.get('symbol', ''),
                    'title': p.get('title', p.get('symbol', '')),
                    'direction': p.get('direction', ''), 'ask': ask,
                    'prob': p.get('prob', 0), 'ev': round(ev_per_dollar, 4),
                    'conviction': p.get('conviction', ''),
                    'slug': p.get('slug', ''), 'token_id': p.get('token_id', ''),
                    'condition_id': p.get('condition_id', ''),
                    'paper_stake': _blocked_stake,
                    'paper_shares': round(_blocked_stake / (ask * (1 + self.FEE_RATE)), 4) if ask > 0 else 0,
                    'paper_pnl': None, 'outcome': None,
                    'resolved': False, 'real_trade': False,
                    'blocked_by': 'EV', 'blocked_reason': f'EV={ev_per_dollar:.3f} < {MIN_EV}',
                }
                _bl = self._load_paper_log()
                if not any(t.get('_key') == key for t in _bl):
                    _bl.append(_blocked_rec)
                    self._save_paper_log(_bl)
                else:
                    self._logged_trade_keys.discard(key)
                continue
            bankroll = self.bot.get_usdc_balance() if wallet_live else self.bot.kelly_bankroll
            if wallet_live and bankroll > 100:
                self._last_known_balance = bankroll  # cache for drawdown check
            conv_cap = self.conviction_bets.get(p.get('conviction', 'MEDIUM'), self.claude_max_bet)
            # 2026-05-21: cap is min(slider, 5% bankroll). The slider is the user's explicit
            # ceiling ("I never want more than $X/bet"); the 5% bankroll cap is self-protection
            # on small/drawing-down wallets. Whichever is tighter wins. Floor stays at conv_cap
            # so paper sizing matches intent on healthy bankrolls.
            # NEAR-CLOSE / MANIP keep their hard $3 caps.
            if play_type == 'NEAR-CLOSE':
                floor_stake = 3.0
                stake_max = 3.0
            elif play_type == 'MANIP':
                # MANIP audit 2026-05-13: avg LOSS stake $2.09 vs avg WIN stake $0.34.
                # Kelly inflates on tiny-ask × huge-divergence math, leading to oversized
                # losses on near-resolved markets. Hard $3 cap matches NEAR-CLOSE pattern.
                floor_stake = min(conv_cap, 3.0)
                stake_max   = 3.0
            else:
                bankroll_cap = bankroll * 0.05
                stake_max    = min(conv_cap, bankroll_cap)
                floor_stake  = min(conv_cap, bankroll_cap)   # floor never exceeds the cap
            sess_mult = _session_kelly_mult()
            # 2026-05-16: TIME-LOCK Kelly halved per user — was sizing up to ~10% bankroll.
            # Why: TIME-LOCK hit the bankroll*0.10 cap frequently on low-ask longshots,
            # producing oversized losses on the occasional miss. Halving the Kelly fraction
            # keeps the conviction-slider floor intact but shrinks Kelly-driven scale-up.
            play_kelly_mult = 0.5 if play_type == 'TIME-LOCK' else 1.0
            kelly_stake = min(max(self.bot.kelly_fraction * play_kelly_mult * kelly_f * bankroll * sess_mult, self.bot.kelly_min_bet), stake_max)
            stake = round(max(kelly_stake, floor_stake), 2)
            # ───── SizingAgent v1 hook (2026-06-01) ─────
            # Per-strategy Kelly sizer behind a feature flag. Default OFF for all
            # strategies → agent.size() returns None and `stake` (legacy) is used
            # unchanged. When opted in via sizing_config.json `enabled: true`, the
            # agent's stake replaces the legacy stake on REAL trades only — paper
            # sizing continues to use `paper_stake_intent` below (user-intent slider).
            # Zero file I/O per call: SizingAgent uses an mtime-cached config.
            if _SIZING_AGENT_AVAILABLE:
                try:
                    _agent = _get_sizing_agent()
                    if _agent is not None:
                        # v2 (2026-06-01): real cross-scanner daily PnL with
                        # ~30s cache (see _sizing_agent_daily_pnl_cached above).
                        # Falls back to legacy _today_realized_pnl attr, then
                        # 0.0, so the kill switch is never blocked by a missing
                        # value. Errors -> 0.0 (kill switch dormant rather than
                        # falsely tripped).
                        _today_pnl = 0.0
                        try:
                            _today_pnl = float(_sizing_agent_daily_pnl_cached())
                        except Exception:
                            try:
                                _today_pnl = float(getattr(self, '_today_realized_pnl', 0.0) or 0.0)
                            except Exception:
                                _today_pnl = 0.0
                        _agent_stake = _agent.size(
                            strategy=play_type,
                            conviction=p.get('conviction', 'MEDIUM'),
                            p_hat=est_prob,
                            b=b,
                            asset=(p.get('symbol') or '').upper(),
                            current_bankroll=bankroll,
                            daily_pnl=_today_pnl,
                        )
                        if _agent_stake is not None:
                            # Agent took control — override legacy stake. Still clamp
                            # to non-negative cents.
                            stake = round(max(float(_agent_stake), 0.0), 2)
                except Exception as _sa_err:
                    # Belt-and-braces: any agent error → keep legacy stake.
                    logger.debug(f'[SIZING-AGENT] suppressed error, using legacy: {_sa_err}')
            # 2026-05-25 paper-vs-live stake decoupling. When wallet drains below
            # ~$120, bankroll*0.05 collapses to ~$0.01 and every Kelly-sized paper
            # trade records $0.01 PnL — destroying the paper-performance signal we
            # use to make real decisions. Paper trades represent USER INTENT (the
            # conviction slider), not live-wallet capacity. Mirrors _blocked_stake
            # at 17101 which already uses conv_cap directly for shadow records.
            if play_type in ('NEAR-CLOSE', 'MANIP'):
                paper_stake_intent = min(conv_cap, 3.0)
            else:
                paper_stake_intent = conv_cap

            # Auto-disable check — runs quickly, uses cached paper log
            self._check_auto_disable(play_type)

            # Cross-bot conflict guard
            _cp_slug = p.get('slug', '')
            _cp_dir  = p.get('direction', '')
            _xb_ok, _xb_reason = _xbot_check(_cp_slug, _cp_dir, 'CLAUDE')
            if not _xb_ok:
                logger.warning(f'[CLAUDE-PICKS] SKIPPED {play_type} {p.get("symbol")} {_cp_dir} — {_xb_reason}')
                self._logged_trade_keys.discard(key)
                continue

            real_trade = False
            real_order_id = None
            mode_is_real = self.strategy_modes.get(play_type, 'real') == 'real'
            # Cell-level override (added 2026-05-19) — takes precedence over the
            # play_type setting. Lets the operator quarantine specific
            # (play_type, symbol, direction) cells without paper-ing the whole
            # play_type, OR whitelist specific cells inside an otherwise-paper
            # play_type. Backed by claude_strategy_modes.json `_cell_overrides`
            # dict keyed by "PLAY|SYM|DIR".
            _cell_key = f"{play_type}|{(p.get('symbol') or '').upper()}|{(p.get('direction') or '').upper()}"
            _cell_overrides = self.strategy_modes.get('_cell_overrides', {}) or {}
            _cell_setting = _cell_overrides.get(_cell_key)
            if _cell_setting == 'real' and not mode_is_real:
                mode_is_real = True
                logger.info(f'[CELL-OVERRIDE] {_cell_key} -> LIVE (cell whitelist over play_type paper)')
            elif _cell_setting == 'paper' and mode_is_real:
                mode_is_real = False
                logger.info(f'[CELL-OVERRIDE] {_cell_key} -> PAPER (cell quarantine over play_type real)')
            thresh_order = {'MEDIUM': 0, 'HIGH': 1, 'STRONG': 2, 'EXTREME': 3}
            pick_conviction = p.get('conviction', 'MEDIUM')
            if self.conviction_levels is not None:
                # Explicit multi-select: only trade levels the user enabled
                meets_threshold = pick_conviction in self.conviction_levels
            else:
                # Legacy min-threshold mode
                pick_level = thresh_order.get(pick_conviction, 0)
                min_level  = thresh_order.get(self.conviction_threshold, 1)
                meets_threshold = pick_level >= min_level
            if self.circuit_breaker_active:
                mode_is_real = False  # hard block — circuit breaker overrides everything
            if p.get('force_paper'):
                mode_is_real = False  # symbol-level paper override (e.g. BTC/SOL MANIP)
            # Auto-pause gate — per-strategy cooldown after losing streak / bad rolling window.
            # See AutoPauseGate (~line 380); self-clears at next hour boundary.
            # 2026-05-17 protection_override: skip the pause check if user toggled override.
            if (mode_is_real and not self.strategy_modes.get('_protection_override', False)
                    and auto_pause_gate().is_paused(play_type)):
                logger.info(f'[AUTO-PAUSE] {play_type} {p.get("symbol")} {p.get("direction")} -> PAPER (cooldown active)')
                mode_is_real = False
            # Paper-vs-live divergence gate (2026-05-16 investigation):
            # MISPRICED/5m lives at 29% WR vs 36-47% paper WR — XRP/5m 0%, BTC/5m 28%, BNB/5m 20%.
            # Why: 5m markets fill on spread-cross with adverse selection; paper assumes mid-ask.
            # 15m MISPRICED is fine (48% WR live, +$47 PnL) — only 5m is broken.
            if mode_is_real and play_type == 'MISPRICED' and p.get('timeframe') == '5m':
                logger.info(f'[5M-DIVERGENCE] MISPRICED {p.get("symbol")} 5m -> PAPER (live underperforms paper by 14pp WR)')
                mode_is_real = False
            # Cross-symbol correlation gate (Monday journal #43 idea #5):
            # block this live entry if a correlated symbol had a same-direction live
            # trade in the last 60s. Stops the 01:24 XRP+SOL+ETH DOWN simultaneous
            # bleed pattern (effective 3x stake on one binary outcome).
            # 2026-05-17 protection_override: skip the gate per user toggle.
            if mode_is_real and not self.strategy_modes.get('_protection_override', False):
                _corr_ok, _corr_reason = _correlation_check(p.get('symbol', ''), p.get('direction', ''))
                if not _corr_ok:
                    logger.warning(f'[CORR-GATE] {play_type} {p.get("symbol")} {p.get("direction")} — {_corr_reason}, force-paper')
                    mode_is_real = False
            if wallet_live and meets_threshold and mode_is_real:
                # Real money — only auto-buy HIGH/EXTREME conviction when mode is REAL
                bought, real_order_id = self._auto_buy_pick(p, stake)
                if bought:
                    real_trade = True
                    _correlation_record(p.get('symbol', ''), p.get('direction', ''))
                # Order failed — still log as paper for tracking

            # Key already reserved under lock above — no duplicate add needed
            _now_h = datetime.now(timezone.utc).hour
            _session = ('ASIA' if 0 <= _now_h < 8 else 'US_OPEN' if 8 <= _now_h < 12 else 'US_AFT' if 12 <= _now_h < 20 else 'OVERNIGHT')
            record = {
                '_key':         key,
                'logged_at':    datetime.now().isoformat(),
                'fill_hour':    _now_h,
                'fill_session': _session,
                'play_type':    p['play_type'],
                'symbol':       p['symbol'],
                'title':        p.get('title', p['symbol']),
                'direction':    p['direction'],
                'token_id':     p['token_id'],
                'slug':         p['slug'],
                'condition_id': p.get('condition_id', ''),
                'ask':          ask,
                'prob':         p['prob'],
                'ev':           p['ev'],
                'conviction':   p['conviction'],
                'timeframe':    p['timeframe'],
                'surge_ratio':  p.get('surge_ratio'),
                'market_end':   None,
                # If the trade landed as REAL, record the actual money spent (stake).
                # Otherwise record user-intent (paper_stake_intent) so the paper PnL
                # reflects the slider, not the live bankroll cap. See 17243 comment.
                'paper_stake':  stake if real_trade else paper_stake_intent,
                # Fee-adjusted shares: 2% taker fee on entry means fewer shares per dollar
                # real_cost_per_share = ask * 1.02, so shares = stake / (ask * 1.02)
                'paper_shares': round((stake if real_trade else paper_stake_intent) / (ask * (1 + self.FEE_RATE)), 4) if ask > 0 else 0,
                'entry_fee':    round((stake if real_trade else paper_stake_intent) * self.FEE_RATE, 4),
                'paper_pnl':    None,
                'outcome':      None,
                'resolved':     False,
                'real_trade':   real_trade,
                'order_id':     real_order_id,
                'fill_confirmed': None,
                'reasoning':    p.get('reasoning', ''),
                'volume_24h':   p.get('volume_24h'),
                'secs_left':    p.get('secs_left'),
            }
            if p.get('secs_left'):
                end_dt = datetime.now(timezone.utc) + timedelta(seconds=p['secs_left'])
                record['market_end'] = end_dt.isoformat()
            # MANIP-specific fields — feeds RL state encoding (gap/momentum buckets)
            # and post-hoc analysis (manip_type breakdown).
            if play_type == 'MANIP':
                record.update({
                    'manip_type':       p.get('manip_type'),
                    'divergence':       p.get('divergence'),
                    'fair_value':       p.get('fair_value'),
                    'momentum_pct':     p.get('momentum_pct'),
                    'wick_count':       p.get('wick_count'),
                    'bull_rejections':  p.get('bull_rejections'),
                    'bear_rejections':  p.get('bear_rejections'),
                })
            trades.append(record)
            added += 1
            label = 'REAL' if real_trade else 'PAPER'
            self._think(f'[{label}] Logged {p["play_type"]} {p["symbol"]} {p["direction"]} @ {ask} (HIGH conf)', 'info')

        if added:
            self._save_paper_log(trades)
            logger.info(f'[PAPER] Logged {added} new trade(s) to paper log')

    def _auto_buy_pick(self, pick: dict, stake: float) -> bool:
        """Execute exactly the same flow as the manual Buy button. Returns True on success."""
        from py_clob_client_v2.clob_types import OrderType
        token_id  = pick['token_id']
        title     = pick.get('title', pick['symbol'])[:20]
        direction = pick['direction']
        bot       = self.bot

        def _log_rejected_attempt(reason: str):
            """Persist a failed entry attempt to bot.predictions so the data isn't lost.
            Filtered out of WR / PnL by was_correct=None and outcome_checked=True;
            visible to any audit that wants to count rejections per symbol/play."""
            if not bot:
                return
            try:
                _now = datetime.now()
                bot.predictions.append({
                    'id':              str(int(_now.timestamp() * 1000)),
                    'timestamp':       _now.isoformat(),
                    'symbol':          pick.get('symbol', '').upper(),
                    'timeframe':       pick.get('timeframe', 'open'),
                    'signal':          'BULLISH' if direction == 'UP' else 'BEARISH',
                    'confidence':      int(pick.get('prob', 0) or 0),
                    'strategy':        f'CLAUDE-{pick.get("play_type","AUTO")}',
                    'price':           pick.get('ask'),
                    'size':            0,
                    'cost':            0,
                    'order_id':        None,
                    'order_ok':        False,
                    'fill_status':     'rejected',
                    'rejection_reason': reason,
                    'entry_price':     pick.get('ask'),
                    'outcome_checked': True,    # so TP/SL skips it
                    'was_correct':     None,    # so hit-rate aggregations skip it
                    'final_price':     'ORDER-REJECTED',
                    'token_id':        token_id,
                    'condition_id':    pick.get('condition_id', ''),
                    'bought_outcome':  direction.lower(),
                    'title':           pick.get('title', pick.get('symbol', '')),
                    'slug':            pick.get('slug', ''),
                })
                bot.save_predictions()
            except Exception as _e:
                logger.warning(f'[AUTO-BUY] _log_rejected_attempt failed: {_e}')

        # Step 1: price — try live order book, fall back to scan midpoint
        scan_price = pick.get('ask')
        live_ask = None
        try:
            book = bot.clob_client.get_order_book(token_id)
            if book and hasattr(book, 'asks') and book.asks:
                ob_ask = float(book.asks[0].price)
                # CLOB shows 0.99 for illiquid markets — ignore and use scan midpoint
                if ob_ask < 0.99:
                    live_ask = ob_ask
        except Exception as e:
            logger.warning(f'[AUTO-BUY] get_order_book exception for {title}: {e}')

        if live_ask is None:
            # Use scan-time midpoint — valid for GTC limit order at fair value
            live_ask = scan_price
            if not live_ask:
                logger.warning(f'[AUTO-BUY] No price available for {title}')
                _log_rejected_attempt('NO_PRICE')
                return False, None
            logger.info(f'[AUTO-BUY] Using scan midpoint {live_ask:.4f} for {title}')

        if live_ask >= 0.99:
            logger.warning(f'[AUTO-BUY] Price {live_ask:.4f} >= 0.99, skipping {title}')
            _log_rejected_attempt(f'PRICE_TOO_HIGH:{live_ask:.4f}')
            return False, None

        # Step 2: size — ensure minimum 5 shares, round up not down
        # PRICE-AGGRESSION: cross the spread by 1 tick so BUY orders fill as takers.
        AGGRESSION_TICKS = 0.01
        target_price = min(0.99, live_ask + AGGRESSION_TICKS)
        rounded_price = bot.round_price(target_price)
        if rounded_price <= 0:
            _log_rejected_attempt(f'INVALID_ROUNDED_PRICE:{rounded_price}')
            return False, None
        size = stake / rounded_price
        size = bot.round_maker_size(rounded_price, size)
        size = bot._validate_size(size, rounded_price, title)
        # Enforce Polymarket 5-share minimum (round up if needed)
        if size < 5:
            size = 5.0
            stake = round(size * rounded_price, 4)

        # Step 3: order — identical to api_claude_picks_buy()
        try:
            ok, result, order_id = bot._safe_create_and_post(
                token_id=token_id,
                price=rounded_price,
                size=size,
                side='BUY',
                order_type=OrderType.GTC,
                symbol=title,
            )
        except Exception as e:
            logger.error(f'[AUTO-BUY] _safe_create_and_post exception for {title}: {e}')
            _log_rejected_attempt(f'EXCEPTION:{type(e).__name__}:{str(e)[:80]}')
            return False, None

        if ok:
            logger.info(
                f'[AUTO-BUY] {pick["play_type"]} {pick["symbol"]} {direction} '
                f'@ {live_ask:.4f} x {size:.2f} | order={order_id} | ${stake:.2f}'
            )
            self._think(
                f'[AUTO-BUY] OK {pick["play_type"]} {pick["symbol"]} {direction} '
                f'@ {live_ask:.4f} order {order_id}', 'info'
            )
            # Return order_id so caller can store it in the paper trade record
            # Save prediction record so TP/SL check can manage this position
            _now = datetime.now()
            # market_end_time — derived from secs_left if present, else parsed from slug.
            # Required by the CLAUDE-* expiry resolver (line 6492) so this prediction
            # eventually gets marked EXPIRED instead of sitting pending forever.
            _market_end_iso = None
            try:
                _secs_left = pick.get('secs_left')
                if _secs_left and _secs_left > 0:
                    _market_end_iso = (datetime.now(timezone.utc)
                                       + timedelta(seconds=float(_secs_left))).isoformat()
                else:
                    _slug = pick.get('slug', '')
                    import re as _re
                    _m = _re.match(r'^[a-z]+-updown-(5m|15m)-(\d+)$', _slug, _re.IGNORECASE)
                    if _m:
                        _tf_secs = 300 if _m.group(1).lower() == '5m' else 900
                        _end_ts = int(_m.group(2)) + _tf_secs
                        _market_end_iso = datetime.fromtimestamp(_end_ts, tz=timezone.utc).isoformat()
            except Exception:
                _market_end_iso = None
            pred = {
                'id': str(int(_now.timestamp() * 1000)),
                'timestamp': _now.isoformat(),
                'symbol': pick['symbol'].upper(),
                'timeframe': pick.get('timeframe', 'open'),
                'signal': 'BULLISH' if direction == 'UP' else 'BEARISH',
                'confidence': int(pick.get('prob', 80)),
                'strategy': f'CLAUDE-{pick.get("play_type","AUTO")}',
                'price': rounded_price,
                'size': size,
                'cost': round(size * rounded_price, 4),
                'order_id': order_id,
                'entry_price': pick.get('ask', rounded_price),
                'is_100_confidence': False,
                'outcome_checked': False,
                'was_correct': None,
                'final_price': None,
                'token_id': token_id,
                'condition_id': pick.get('condition_id', ''),
                'bought_outcome': direction.lower(),
                'current_yes_price': live_ask,
                'current_no_price': round(1 - live_ask, 4),
                'potential_profit': None,
                'signal_bar_cycle': 0,
                'title': pick.get('title', pick['symbol']),
                'slug': pick.get('slug', ''),
                'market_end_time': _market_end_iso,
            }
            bot.predictions.append(pred)
            bot.save_predictions()
            conv = pick.get('conviction', '')
            bot._tg_notify(
                f'CLAUDE PICK {direction}  <b>[{conv}]</b>\n'
                f'<b>{title}</b>  ${stake:.2f}\n'
                f'{pick.get("play_type","PICK")} @ {live_ask:.4f}'
                f'{bot._pm_link(pick.get("slug",""))}'
            )
            return True, order_id

        logger.warning(f'[AUTO-BUY] Order rejected for {title}: {result}')
        _log_rejected_attempt(f'ORDER_REJECTED:{str(result)[:100]}')
        return False, None

    def _check_picks_fill_status(self):
        """Pull our recent CLOB trades, match to pending paper-trade records by order_id,
        capture actual_fill_price (vwap) + actual_filled_size + fill_confirmed.
        On resolve, compute real_pnl using actual fill data so paper-vs-live divergence
        is measurable. Single get_trades(maker_address=proxy) API call per invocation."""
        from py_clob_client_v2.clob_types import TradeParams
        bot = self.bot
        if not bot or not bot.clob_client:
            return
        proxy = getattr(bot, 'proxy_address', None) or getattr(bot, 'wallet_address', None)
        if not proxy:
            return

        trades = self._load_paper_log()
        if not trades:
            return

        # Targets: never-confirmed orders, and orders confirmed but missing actual_fill_price
        wanted = {}
        for t in trades:
            oid = t.get('order_id')
            if not (t.get('real_trade') and oid and oid != 'N/A'):
                continue
            if t.get('fill_confirmed') is False:
                continue  # explicitly failed earlier — leave alone
            if t.get('fill_confirmed') is None or t.get('actual_fill_price') is None:
                wanted.setdefault(oid, t)

        # Also: resolved trades with actual_fill_price but no real_pnl yet (compute pass)
        needs_realpnl = [t for t in trades
                        if t.get('real_trade') and t.get('resolved') and t.get('outcome')
                        and t.get('actual_fill_price') is not None
                        and t.get('actual_filled_size') is not None
                        and t.get('real_pnl') is None]

        if not wanted and not needs_realpnl:
            return

        changed = False

        if wanted:
            try:
                recent = bot.clob_client.get_trades(
                    TradeParams(maker_address=proxy), only_first_page=True)
            except Exception as e:
                logger.warning(f'[PICKS-FILL] get_trades failed: {e}')
                recent = []

            # Build order_id -> [trade_record] map. Polymarket trade records can carry
            # taker_order_id (our taker) OR maker_orders[] (our maker) — handle both,
            # and tolerate camelCase/snake_case key variants.
            by_order = {}
            for tr in recent:
                if not isinstance(tr, dict):
                    continue
                toi = tr.get('taker_order_id') or tr.get('takerOrderID') or tr.get('takerOrderId')
                if toi:
                    by_order.setdefault(toi, []).append(tr)
                for mo in (tr.get('maker_orders') or tr.get('makerOrders') or []):
                    if isinstance(mo, dict):
                        moi = (mo.get('order_id') or mo.get('orderID')
                               or mo.get('orderId') or mo.get('maker_order_id'))
                        if moi:
                            by_order.setdefault(moi, []).append(tr)

            for oid, t in wanted.items():
                matches = by_order.get(oid, [])
                if matches:
                    total_size = 0.0; total_cost = 0.0
                    for m in matches:
                        try:
                            # When we are the maker, the trade's outer "price"/"size" reflect
                            # the taker side; our share lives in maker_orders[]. If the matching
                            # entry has matched_amount/price use those, else fall back to outer.
                            sz = None; pr = None
                            for mo in (m.get('maker_orders') or m.get('makerOrders') or []):
                                if not isinstance(mo, dict):
                                    continue
                                k = (mo.get('order_id') or mo.get('orderID')
                                     or mo.get('orderId') or mo.get('maker_order_id'))
                                if k == oid:
                                    sz = float(mo.get('matched_amount') or mo.get('matchedAmount')
                                               or mo.get('size') or 0)
                                    pr = float(mo.get('price') or m.get('price') or 0)
                                    break
                            if sz is None:
                                sz = float(m.get('size') or 0)
                                pr = float(m.get('price') or 0)
                        except (TypeError, ValueError):
                            continue
                        if sz <= 0 or pr <= 0:
                            continue
                        total_size += sz
                        total_cost += sz * pr
                    if total_size > 0:
                        vwap = total_cost / total_size
                        ask = t.get('ask') or 0
                        t['actual_fill_price'] = round(vwap, 6)
                        t['actual_filled_size'] = round(total_size, 4)
                        if t.get('fill_confirmed') is None:
                            t['fill_confirmed'] = True
                        changed = True
                        slip_bps = (vwap - ask) * 10000 if ask else 0
                        logger.info(
                            f'[PICKS-FILL] {t.get("symbol")} {t.get("play_type")} '
                            f'order={oid[:10]}.. ask={ask:.4f} vwap_fill={vwap:.4f} '
                            f'slip={slip_bps:+.0f}bps size={total_size:.2f}/{t.get("paper_shares",0):.2f}')
                else:
                    # Order older than 30min with no fill record → assume never filled
                    try:
                        la = t.get('logged_at', '')
                        dt = datetime.fromisoformat(la.replace('Z', '+00:00'))
                        if dt.tzinfo is None:
                            dt = dt.replace(tzinfo=datetime.now().astimezone().tzinfo)
                        age_min = (datetime.now(timezone.utc) - dt.astimezone(timezone.utc)).total_seconds() / 60
                    except Exception:
                        age_min = 0
                    if age_min > 30 and t.get('fill_confirmed') is None:
                        t['fill_confirmed'] = False
                        t['fill_status'] = 'NO_FILL_FOUND'
                        changed = True
                        logger.info(f'[PICKS-FILL] No fill found for {t.get("symbol")} '
                                    f'order={oid[:10]}.. after {age_min:.0f}min')

        # Real-PnL compute pass — uses actual_fill_price * actual_filled_size as cost basis
        for t in trades:
            if not (t.get('real_trade') and t.get('resolved') and t.get('outcome')
                    and t.get('actual_fill_price') is not None
                    and t.get('actual_filled_size') is not None
                    and t.get('real_pnl') is None):
                continue
            afp = t['actual_fill_price']; afs = t['actual_filled_size']
            outcome = t['outcome']; cost = afp * afs
            if outcome == 'WIN':
                t['real_pnl'] = round(afs - cost, 4)
            elif outcome == 'LOSS':
                t['real_pnl'] = round(-cost, 4)
            elif outcome in ('TP', 'SL'):
                exit_price = t.get('exit_price', t.get('ask', 0.5))
                gross = afs * exit_price
                exit_fee = gross * self.FEE_RATE
                t['real_pnl'] = round(gross - exit_fee - cost, 4)
            else:
                t['real_pnl'] = 0.0
            div = t['real_pnl'] - (t.get('paper_pnl') or 0)
            changed = True
            logger.info(f'[PICKS-FILL] real_pnl {t.get("symbol")} {outcome} '
                        f'paper=${t.get("paper_pnl",0):+.2f} real=${t["real_pnl"]:+.2f} div=${div:+.2f}')

        if changed:
            self._save_paper_log(trades)

    def _resolve_paper_trade_outcome(self, trade: dict) -> Optional[str]:
        """
        Return 'WIN', 'LOSS', or None (still pending).
        For crypto updown markets: compare token price (≥0.99 = WIN, ≤0.01 = LOSS).
        For non-crypto: query Gamma API for outcomePrices post-resolution.
        """
        from datetime import timezone
        token_id   = trade.get('token_id')
        direction  = trade.get('direction', '').upper()
        slug       = trade.get('slug', '')
        play_type  = trade.get('play_type', '')

        # Not resolved if end time hasn't passed yet
        market_end = trade.get('market_end')
        if market_end:
            try:
                end_dt = datetime.fromisoformat(market_end.replace('Z', '+00:00'))
                if datetime.now(timezone.utc) < end_dt:
                    return None
            except Exception:
                pass

        # Crypto updown trades (TIME-LOCK, MOMENTUM, MISPRICED, MANIP, CRYPTO-AUTO)
        # all use event-level slugs (btc-updown-15m-<ts>).
        # Query /events?slug= instead of /markets?slug= for these.
        if slug and '-updown-' in slug:
            try:
                r = self._session.get(f'{self.GAMMA}/events',
                                 params={'slug': slug}, timeout=6)
                if r.status_code == 200:
                    events = r.json()
                    event = events[0] if isinstance(events, list) and events else None
                    if event:
                        mkt = (event.get('markets') or [None])[0]
                        if mkt:
                            closed = mkt.get('closed', False)
                            out_prices_raw = mkt.get('outcomePrices', '[]')
                            outcomes_raw   = mkt.get('outcomes', '["Up","Down"]')
                            if isinstance(out_prices_raw, str):
                                try:
                                    out_prices = [float(x) for x in json.loads(out_prices_raw)]
                                except Exception:
                                    out_prices = []
                            else:
                                out_prices = [float(x) for x in (out_prices_raw or [])]
                            if isinstance(outcomes_raw, str):
                                try:
                                    outcomes = json.loads(outcomes_raw)
                                except Exception:
                                    outcomes = []
                            else:
                                outcomes = outcomes_raw or []
                            for i, o in enumerate(outcomes):
                                if o.upper() == direction and i < len(out_prices):
                                    p = out_prices[i]
                                    if p >= 0.99:
                                        return 'WIN'
                                    elif p <= 0.01:
                                        return 'LOSS'
                                    elif closed:
                                        return 'PUSH'
                                    return None  # still live
            except Exception as e:
                logger.debug(f'[PAPER] updown events check error {slug}: {e}')
            return None  # couldn't resolve via events API

        # Check via Gamma API outcomePrices — works for all market types
        if slug:
            try:
                r = self._session.get(f'{self.GAMMA}/markets',
                                 params={'slug': slug}, timeout=6)
                if r.status_code == 200:
                    items = r.json()
                    mkt = items[0] if isinstance(items, list) and items else None
                    if mkt:
                        closed = mkt.get('closed', False)
                        out_prices_raw = mkt.get('outcomePrices', '[]')
                        outcomes_raw   = mkt.get('outcomes', '["Yes","No"]')
                        if isinstance(out_prices_raw, str):
                            try:
                                out_prices = [float(x) for x in json.loads(out_prices_raw)]
                            except Exception:
                                out_prices = []
                        else:
                            out_prices = [float(x) for x in (out_prices_raw or [])]
                        if isinstance(outcomes_raw, str):
                            try:
                                outcomes = json.loads(outcomes_raw)
                            except Exception:
                                outcomes = []
                        else:
                            outcomes = outcomes_raw or []

                        # Match our direction to an outcome index
                        for i, o in enumerate(outcomes):
                            if o.upper() == direction and i < len(out_prices):
                                p = out_prices[i]
                                if p >= 0.99:
                                    return 'WIN'
                                elif p <= 0.01:
                                    return 'LOSS'
                                elif closed:
                                    # Closed but price not decisive — PUSH/no-resolve
                                    return 'PUSH'
                                return None  # still resolving

                        # No outcome name match — try token_id price as fallback
                        if token_id and closed:
                            if self.bot.clob_client:
                                try:
                                    book = self.bot.clob_client.get_order_book(token_id)
                                    if book and hasattr(book, 'bids') and book.bids:
                                        bid = float(book.bids[0].price)
                                        if bid >= 0.99: return 'WIN'
                                        if bid <= 0.01: return 'LOSS'
                                except Exception:
                                    pass
            except Exception as e:
                logger.debug(f'[PAPER] Gamma check error {slug}: {e}')
        return None

    def check_paper_outcomes(self):
        """Scan all unresolved paper trades and update W/L."""
        trades = self._load_paper_log()
        changed = False
        for t in trades:
            if t.get('resolved'):
                continue
            outcome = self._resolve_paper_trade_outcome(t)
            if outcome:
                t['resolved']  = True
                t['outcome']   = outcome
                stake  = t.get('paper_stake', 5.0)
                shares = t.get('paper_shares', 0)
                # Backfill shares for shadow/blocked records (RL/EV/LOW-ASK gates) that
                # were logged without paper_shares — without this, WIN outcomes compute
                # paper_pnl = 0 - stake = -stake, contaminating shadow PnL tracking.
                if not shares and t.get('ask', 0) > 0:
                    shares = round(stake / (t['ask'] * (1 + self.FEE_RATE)), 4)
                    t['paper_shares'] = shares
                fee_rate = self.FEE_RATE  # 2% taker fee
                if outcome == 'WIN':
                    # Resolution pays $1/share, no exit fee (Polymarket doesn't charge on resolution)
                    # Entry fee already baked in via reduced share count
                    t['paper_pnl'] = round(shares * 1.0 - stake, 4)
                elif outcome == 'LOSS':
                    # Lost full stake (entry fee already spent as part of stake)
                    t['paper_pnl'] = round(-stake, 4)
                elif outcome == 'TP' or outcome == 'SL':
                    # Early exit via sell order — 2% taker fee on exit too
                    exit_price = t.get('exit_price', t.get('ask', 0.5))
                    gross = shares * exit_price
                    exit_fee = gross * fee_rate
                    t['paper_pnl'] = round(gross - exit_fee - stake, 4)
                else:
                    t['paper_pnl'] = 0.0
                # Store slippage estimate for reference (half-spread approximation)
                ask = t.get('ask', 0)
                t['est_slippage'] = round(ask * 0.005 * shares, 4) if ask > 0 else 0  # ~0.5% half-spread
                # ───── SizingAgent v1 calibration hook (2026-06-01) ─────
                # Record predicted vs realized for the nightly LLM tuner. WIN/TP
                # count as `won=True`; LOSS/SL count as `won=False`. Best-effort,
                # never raises into the outcome loop.
                if _SIZING_AGENT_AVAILABLE and outcome in ('WIN', 'LOSS', 'TP', 'SL'):
                    try:
                        _ct = _get_calibration_tracker()
                        if _ct is not None:
                            _ct.record(
                                strategy=t.get('play_type', ''),
                                conviction=t.get('conviction', ''),
                                asset=(t.get('symbol') or '').upper(),
                                p_hat=float(t.get('prob', 0) or 0) / (100.0 if (t.get('prob') or 0) > 1.0 else 1.0),
                                won=(outcome in ('WIN', 'TP')),
                            )
                    except Exception as _cal_err:
                        logger.debug(f'[CALIB] suppressed error: {_cal_err}')
                changed = True
                _xbot_clear(t.get('slug', ''))  # free slug for other bots
                emoji = 'WIN' if outcome == 'WIN' else ('LOSS' if outcome == 'LOSS' else 'PUSH')
                logger.info(f'[PAPER] {emoji} | {t["play_type"]} {t["symbol"]} {t["direction"]} '
                            f'| PnL ${t["paper_pnl"]:+.2f} | {t["title"][:50]}')
                self._think(f'[PAPER] {emoji} {t["symbol"]} {t["direction"]} PnL=${t["paper_pnl"]:+.2f}', 'found' if outcome=='WIN' else 'warn')
                # Drawdown protection — only track real trades (paper trades don't risk real money)
                if t.get('real_trade'):
                    try:
                        self._update_drawdown(outcome, t['paper_pnl'], t.get('play_type', ''))
                    except Exception as _dd_err:
                        logger.warning(f'[DRAWDOWN] update error: {_dd_err}')
                    # Per-strategy auto-pause gate (rolling-30m PnL or consec-loss)
                    try:
                        auto_pause_gate().record_resolved(
                            t.get('play_type', ''), t['paper_pnl'])
                    except Exception as _ap_err:
                        logger.debug(f'[AUTO-PAUSE] record err: {_ap_err}')
                # MANIP RL — update Q-value for this state
                if t.get('play_type') == 'MANIP' and t.get('paper_pnl') is not None:
                    try:
                        gap = t.get('divergence') or max((t.get('prob', 75) / 100) - t.get('ask', 0.5), 0)
                        can_pct = (t.get('momentum_pct') or 75) / 100
                        self.manip_rl.update(
                            symbol    = t.get('symbol', ''),
                            ask       = t.get('ask', 0.5),
                            candle_pct= can_pct,
                            gap       = gap,
                            direction = t.get('direction', 'UP'),
                            stake     = t.get('paper_stake', 5.0),
                            pnl       = t['paper_pnl'],
                        )
                    except Exception as _rl_err:
                        logger.warning(f'[MANIP-RL] Update error: {_rl_err}')
                # ClaudePicksRL — update Q for all other play types (per-type instance)
                if t.get('play_type') != 'MANIP' and t.get('paper_pnl') is not None:
                    try:
                        self._picks_rl_for(t.get('play_type','')).update(
                            play_type  = t.get('play_type', ''),
                            symbol     = t.get('symbol', ''),
                            ask        = t.get('ask', 0.5),
                            conviction = t.get('conviction', 'HIGH'),
                            stake      = t.get('paper_stake', 5.0),
                            pnl        = t['paper_pnl'],
                        )
                    except Exception as _rl_err:
                        logger.warning(f'[PICKS-RL] Update error: {_rl_err}')
        if changed:
            self._save_paper_log(trades)

    def _scan_broad_markets(self) -> list:
        """Scan non-crypto Polymarket markets for NEAR-CLOSE and VOL-SURGE plays."""
        from concurrent.futures import ThreadPoolExecutor, as_completed
        self._think('▶ BROAD MARKETS — scanning non-crypto...', 'info')
        markets = self._fetch_broad_markets()
        if not markets:
            self._think('  [BROAD] No markets returned from Gamma', 'warn')
            return []

        # 2026-05-30: report how many markets fall inside NEAR-CLOSE's 48h
        # time window — this is the binding constraint on candidate volume.
        try:
            from datetime import timezone as _tz
            _now = datetime.now(_tz.utc)
            _eligible = 0
            for _m in markets:
                _ed = _m.get('endDate', '')
                if not _ed:
                    continue
                try:
                    _ed_dt = datetime.fromisoformat(_ed.replace('Z', '+00:00'))
                    _secs = (_ed_dt - _now).total_seconds()
                    if 60 < _secs < 172800:
                        _eligible += 1
                except Exception:
                    continue
            logger.info(f'[BROAD] {len(markets)} markets fetched; {_eligible} inside NEAR-CLOSE 48h window')
        except Exception:
            pass

        self._think(f'  [BROAD] Evaluating {len(markets)} markets for edge...', 'check')
        picks = []

        def _eval_mkt(mkt):
            results = []
            p = self._play_broad_near_close(mkt)
            if p:
                results.append(p)
            else:
                p2 = self._play_broad_vol_surge(mkt)
                if p2:
                    results.append(p2)
            return results

        with ThreadPoolExecutor(max_workers=8) as ex:
            futures = [ex.submit(_eval_mkt, m) for m in markets]
            for fut in as_completed(futures):
                try:
                    for p in fut.result():
                        picks.append(p)
                        self._think(
                            f'  [{p["play_type"]}] ★ {p.get("title","")[:45]} | '
                            f'{p["direction"]} prob={p["prob"]}% EV=+{p["ev"]}', 'found')
                except Exception:
                    pass

        self._think(f'  [BROAD] {len(picks)} non-crypto play{"s" if len(picks)!=1 else ""} found', 'info')
        return picks

    # ── public API ────────────────────────────────────────────────────────────

    def scan(self) -> list:
        """Run all three play-types for all symbols and return ranked picks.
        Symbols are processed in parallel (ThreadPoolExecutor, 4 workers).
        Per-scan market cache is reset here so _active_markets() is called only
        once per (symbol, tf) pair instead of three times.
        Broad non-crypto markets are scanned in parallel with crypto.
        """
        import time as _time
        from concurrent.futures import ThreadPoolExecutor, as_completed
        # Cache for 30s to avoid hammering APIs
        if _time.time() - self._cache_ts < 55 and self._cache:
            return self._cache.get('picks', [])

        self._scanning = True
        self._market_scan_cache = {}   # reset per-scan market cache
        self._token_price_cache = {}   # reset per-scan CLOB cache
        self._gamma_price_cache = {}   # reset per-scan Gamma fallback cache
        self._prefetch_prices()        # batch-fetch all spot prices upfront
        self._think('━━━ SCAN STARTED ━━━', 'info')

        def _scan_symbol(symbol):
            sym_picks = []
            price = self._get_price(symbol)
            price_str = f'${price:,.4f}' if price else 'N/A'
            self._think(f'▶ {symbol}  spot={price_str}', 'info')
            for tf in ['5m', '15m']:
                # MISPRICED re-enabled 2026-05-07 per user request. Backtest 2026-05-03 showed
                # 29.7% WR / -$139 PnL on n=74 — bleeder at the time. Re-enabling to gather fresh
                # post-fix-stack data; mode in claude_strategy_modes.json determines paper vs real.
                for generator in [self._play_time_lock,
                                   self._play_momentum_lock,
                                   self._play_manipulation,
                                   self._play_mispriced]:
                    p = self._instrumented_play(symbol, tf, generator)
                    if p:
                        sym_picks.append(p)
            return sym_picks

        picks = []
        # Run crypto symbols + broad market scan in parallel. Worker count matches
        # task count (len(SYMBOLS)+1) so no task waits behind another — was 5 before,
        # leaving 3 tasks queued on a 7-symbol setup. Capped at 12 as a sanity ceiling.
        _n_workers = min(len(self.SYMBOLS) + 1, 12)
        with ThreadPoolExecutor(max_workers=_n_workers) as ex:
            crypto_futures = {ex.submit(_scan_symbol, sym): sym for sym in self.SYMBOLS}
            broad_future   = ex.submit(self._scan_broad_markets)

            for fut in as_completed(list(crypto_futures.keys()) + [broad_future]):
                try:
                    result = fut.result()
                    if isinstance(result, list):
                        picks.extend(result)
                except Exception as e:
                    self._think(f'Scan error: {str(e)[:60]}', 'warn')

        # Rank: EXTREME first, then by conviction, then EV descending
        order = {'EXTREME': 0, 'STRONG': 1, 'HIGH': 2, 'MEDIUM': 3}
        picks.sort(key=lambda x: (order.get(x['conviction'], 9), -x['ev']))

        # Auto paper-log HIGH/EXTREME picks and check resolved outcomes
        high_count = sum(1 for p in picks if p.get('conviction') in ('HIGH','STRONG','EXTREME'))
        self._think(f'━━━ SCAN DONE — {len(picks)} play{"s" if len(picks)!=1 else ""} found ({high_count} HIGH+) ━━━', 'info')
        self._scanning = False

        self._cache = {'picks': picks}
        self._cache_ts = _time.time()

        # When wallet is live, auto-buy synchronously so TIME-LOCK picks aren't stale
        # When paper-only, run in background so scan returns fast
        import threading
        if self.bot.wallet_live and self.bot.clob_client:
            self._auto_log_paper_trades(picks)
        else:
            threading.Thread(target=self._auto_log_paper_trades, args=(picks,), daemon=True).start()
        threading.Thread(target=self.check_paper_outcomes, daemon=True).start()

        return picks


# Instantiate after prediction_bot exists (done at module bottom)
claude_scanner: Optional['ClaudePicksScanner'] = None
hft_scanner: Optional['HFTScanner'] = None
btc_ml_scanner: Optional['BTCMLScanner'] = None
eth_ml_scanner: Optional['BTCMLScanner'] = None

# ── Cross-bot conflict guard ──────────────────────────────────────────────────
# Shared registry of open positions across all three scanners.
# Key: slug  Value: {'direction': 'UP'/'DOWN', 'source': 'HFT'/'CLAUDE'/'BTC-ML', 'ts': float}
# Before entering any trade, scanners call _xbot_check(slug, direction, source).
# After a trade closes (resolved), scanners call _xbot_clear(slug).
import threading as _xbot_th
_xbot_lock      = _xbot_th.Lock()
_xbot_positions: dict = {}   # slug -> {direction, source, ts}

def _xbot_check(slug: str, direction: str, source: str) -> tuple:
    """Return (allowed: bool, reason: str). Blocks if opposite open position exists."""
    with _xbot_lock:
        existing = _xbot_positions.get(slug)
        if existing and existing['direction'] != direction:
            age = round(time.time() - existing['ts'], 0)
            return False, (f"Cross-bot conflict: {existing['source']} already {existing['direction']} "
                           f"on same slug ({age}s ago)")
        # Register this entry (overwrite if same direction — idempotent)
        _xbot_positions[slug] = {'direction': direction, 'source': source, 'ts': time.time()}
        return True, ''

def _xbot_clear(slug: str):
    """Remove slug from registry when position closes."""
    with _xbot_lock:
        _xbot_positions.pop(slug, None)

def _xbot_clear_expired(max_age_secs: int = 1800):
    """Prune stale entries (safety valve — resolved trades should clear explicitly)."""
    cutoff = time.time() - max_age_secs
    with _xbot_lock:
        stale = [s for s, v in _xbot_positions.items() if v['ts'] < cutoff]
        for s in stale:
            _xbot_positions.pop(s, None)


