@app.route('/api/hft-trades')
def api_hft_trades():
    """Return HFT paper trades + stats. In weekend mode the trade list is
    filtered to weekend-window trades so users see last weekend's data
    instead of having the 200-row slice eaten by weekday volume that bled
    into the file. Stats remain unfiltered."""
    global hft_scanner
    if hft_scanner is None:
        return jsonify({'trades': [], 'stats': {}, 'error': 'HFT scanner not running'})
    with hft_scanner._lock:
        trades = list(hft_scanner._trades)
    if _is_weekend_mode_now():
        trades = [t for t in trades if _trade_logged_in_weekend(t)]
    trades_sorted = sorted(trades, key=lambda t: t.get('logged_at', ''), reverse=True)
    stats = hft_scanner.get_stats()
    return jsonify({'trades': trades_sorted[:200], 'stats': stats})


# ── Lifetime view: deduped merge of all current + backup HFT trade files ───
# Created 2026-05-17 after discovering the May 15 trade-log migration dropped ~5500
# trades from the active files. Source data preserved in .bak files; this view
# reconstructs lifetime visibility. File built by merge_hft_lifetime.py — stale until
# you POST /api/hft-merge-lifetime to refresh.
HFT_LIFETIME_FILE = 'hft_paper_trades.lifetime.json'


def _compute_hft_lifetime_stats(trades):
    """Stats computation matching HFTScanner.get_stats shape, but over an arbitrary
    list. Just the headline numbers — not the full strategy breakdown."""
    resolved = [t for t in trades if t.get('resolved')]
    pending = [t for t in trades if not t.get('resolved')]
    wins = [t for t in resolved if t.get('outcome') == 'WIN']
    losses = [t for t in resolved if t.get('outcome') == 'LOSS']
    total_pnl = sum(float(t.get('paper_pnl') or 0) for t in resolved)
    total_volume = sum(float(t.get('stake') or 0) for t in resolved)
    real_trades = [t for t in trades if t.get('real_trade')]
    filled_resolved = [t for t in real_trades if t.get('fill_confirmed') is True and t.get('resolved')]
    real_wins = [t for t in filled_resolved if t.get('outcome') == 'WIN']
    real_losses = [t for t in filled_resolved if t.get('outcome') == 'LOSS']
    real_pnl = sum(float(t.get('paper_pnl') or 0) for t in filled_resolved)
    return {
        'total_trades': len(trades),
        'resolved': len(resolved),
        'pending': len(pending),
        'wins': len(wins),
        'losses': len(losses),
        'win_rate': round(len(wins) / max(len(resolved), 1) * 100, 1),
        'total_pnl': round(total_pnl, 2),
        'total_volume': round(total_volume, 2),
        'real_trades': len(real_trades),
        'real_wins': len(real_wins),
        'real_losses': len(real_losses),
        'real_pnl': round(real_pnl, 2),
        'real_wr': round(len(real_wins) / max(len(real_wins) + len(real_losses), 1) * 100, 1),
    }


@app.route('/api/hft-trades-lifetime')
def api_hft_trades_lifetime():
    """Return the lifetime HFT trade view (deduped across all mode files + backups).
    Stale until /api/hft-merge-lifetime is POSTed. Returns same shape as /api/hft-trades."""
    try:
        path = _resolve_state_path(HFT_LIFETIME_FILE) if False else HFT_LIFETIME_FILE  # not mode-routed
        if not os.path.exists(path):
            return jsonify({'trades': [], 'stats': {}, 'error': 'lifetime file not built yet — POST /api/hft-merge-lifetime'})
        # Mtime-cached read — 5.8MB file, ~30ms cold, sub-ms warm.
        trades = _load_json_cached(path, default=[])
        if not isinstance(trades, list):
            trades = []
        trades = sorted(trades, key=lambda t: t.get('logged_at') or t.get('entered_at') or '', reverse=True)
        stats = _compute_hft_lifetime_stats(trades)
        # Include file mtime so the UI can show when this snapshot was taken
        stats['snapshot_mtime'] = datetime.fromtimestamp(os.path.getmtime(path), tz=timezone.utc).isoformat()
        return jsonify({'trades': trades[:200], 'stats': stats, 'mode': 'lifetime'})
    except Exception as e:
        return jsonify({'trades': [], 'stats': {}, 'error': str(e)})


@app.route('/api/hft-merge-lifetime', methods=['POST'])
def api_hft_merge_lifetime():
    """Re-run the merge script to refresh the lifetime view. Returns the new stats."""
    import subprocess
    try:
        result = subprocess.run(
            ['python', 'merge_hft_lifetime.py'],
            capture_output=True, text=True, timeout=60
        )
        if result.returncode != 0:
            return jsonify({'ok': False, 'error': result.stderr or 'merge failed'}), 500
        # Read fresh stats
        if not os.path.exists(HFT_LIFETIME_FILE):
            return jsonify({'ok': False, 'error': 'merge ran but lifetime file missing'}), 500
        with open(HFT_LIFETIME_FILE, 'r', encoding='utf-8') as f:
            trades = json.load(f)
        return jsonify({'ok': True, 'stats': _compute_hft_lifetime_stats(trades), 'output': result.stdout[-500:]})
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)}), 500


@app.route('/api/hft-backfill-fills', methods=['GET', 'POST'])
def api_hft_backfill_fills():
    """
    One-shot backfill for real trades stuck at fill_confirmed=None.
    Re-polls CLOB for each pending order and updates fill_confirmed:
      FILLED/MATCHED  -> True  (counted in real_pnl)
      CANCELLED/EXPIRED -> False (excluded, fill_status recorded)
      Unverifiable    -> False with fill_inferred='unverifiable_after_close'
                          (option C: conservative — exclude from real_pnl)

    Additive only — never deletes or modifies any field other than
    fill_confirmed, filled_size, fill_status, fill_inferred,
    fill_unverifiable_status. Untouched fields used by RL
    (paper_pnl, stake, outcome, resolved, entry_price, etc.) are preserved.

    Query params:
      ?dry_run=true   preview without writing (default false)
      ?limit=N        cap to N trades for testing (default all pending)
    """
    global hft_scanner
    if hft_scanner is None:
        return jsonify({'error': 'HFT scanner not running'}), 503
    bot = hft_scanner.bot
    if not bot or not getattr(bot, 'clob_client', None):
        return jsonify({'error': 'No clob_client available'}), 503

    dry_run = str(request.args.get('dry_run', 'false')).lower() in ('true', '1', 'yes')
    try:
        limit = int(request.args.get('limit', 0)) or None
    except (TypeError, ValueError):
        limit = None

    with hft_scanner._lock:
        pending = [t for t in hft_scanner._trades
                   if t.get('real_trade')
                   and t.get('fill_confirmed') is None]
    if limit:
        pending = pending[:limit]

    counts = {'filled': 0, 'unfilled': 0, 'unverifiable': 0, 'errors': 0,
              'no_order_id': 0}
    samples = []
    pnl_delta = 0.0   # change to real_pnl from this run
    changes = []

    for t in pending:
        oid = t.get('order_id')
        status = None
        filled_size = 0
        err_kind = None
        no_oid = (not oid) or oid == 'N/A'

        if not no_oid:
            try:
                order = bot.clob_client.get_order(oid)
                status = getattr(order, 'status', None)
                if status is None and isinstance(order, dict):
                    status = order.get('status')
                filled_size = getattr(order, 'size_matched', None)
                if filled_size is None and isinstance(order, dict):
                    filled_size = order.get('size_matched', 0)
            except Exception as e:
                err_kind = type(e).__name__
                counts['errors'] += 1

        new_fields = {}
        if no_oid:
            # Legacy trades where order_id was never recorded (real_trade=True but
            # oid='N/A'). No way to verify with CLOB. Option C: mark as unfilled.
            new_fields = {
                'fill_confirmed': False,
                'fill_inferred': 'no_order_id',
                'fill_unverifiable_status': 'no_order_id',
            }
            counts['no_order_id'] += 1
        elif status in ('FILLED', 'MATCHED'):
            new_fields = {'fill_confirmed': True, 'filled_size': filled_size}
            counts['filled'] += 1
            # paper_pnl now counted in get_stats() once fill_confirmed=True
            pnl_delta += float(t.get('paper_pnl') or 0)
        elif status in ('CANCELLED', 'EXPIRED'):
            new_fields = {'fill_confirmed': False, 'fill_status': status}
            counts['unfilled'] += 1
        else:
            new_fields = {
                'fill_confirmed': False,
                'fill_inferred': 'unverifiable_after_close',
                'fill_unverifiable_status': (err_kind or (str(status) if status else 'no_status')),
            }
            if not err_kind:
                counts['unverifiable'] += 1
        changes.append((t, new_fields))

        if len(samples) < 8:
            samples.append({
                'order_id': oid[:18] + '..',
                'logged_at': t.get('logged_at'),
                'symbol': t.get('symbol'),
                'strategy': t.get('strategy'),
                'outcome': t.get('outcome'),
                'paper_pnl': t.get('paper_pnl'),
                'clob_status': str(status) if status else (err_kind or 'no_status'),
                'action': new_fields,
            })

    committed = False
    if not dry_run and changes:
        with hft_scanner._lock:
            for t, new_fields in changes:
                t.update(new_fields)
            hft_scanner._save_log()
        committed = True
        logger.info(f'[HFT-BACKFILL] Committed: filled={counts["filled"]} '
                    f'unfilled={counts["unfilled"]} unverifiable={counts["unverifiable"]} '
                    f'errors={counts["errors"]} pnl_delta={pnl_delta:+.2f}')

    return jsonify({
        'dry_run': dry_run,
        'committed': committed,
        'total_pending_processed': len(pending),
        'counts': counts,
        'real_pnl_delta_if_committed': round(pnl_delta, 2),
        'note': 'Option C — unverifiable bucket marked fill_confirmed=False. '
                'RL fields (paper_pnl/stake/outcome/resolved) untouched.',
        'samples': samples,
    })


@app.route('/api/rl-blocked')
def api_rl_blocked():
    """Return shadow log stats for RL-blocked trades."""
    global hft_scanner, claude_scanner
    result = {'hft': None, 'picks_manip': None, 'combined': None}
    if hft_scanner and hasattr(hft_scanner, 'rl_shadow'):
        result['hft'] = hft_scanner.rl_shadow.get_stats()
    if claude_scanner and hasattr(claude_scanner, 'rl_shadow'):
        result['picks_manip'] = claude_scanner.rl_shadow.get_stats()
    # Combined totals
    all_stats = [v for v in result.values() if v]
    if all_stats:
        total_blocked  = sum(s.get('total_blocked', 0) for s in all_stats)
        total_resolved = sum(s.get('resolved', 0) for s in all_stats)
        total_wins     = sum(s.get('wins', 0) for s in all_stats)
        total_losses   = sum(s.get('losses', 0) for s in all_stats)
        tot = total_wins + total_losses
        result['combined'] = {
            'total_blocked': total_blocked,
            'resolved':      total_resolved,
            'wins':          total_wins,
            'losses':        total_losses,
            'shadow_wr':     round(total_wins / max(tot, 1) * 100, 1) if tot else None,
            'shadow_pnl':    round(sum(s.get('shadow_pnl', 0) for s in all_stats), 2),
        }
    return jsonify(result)


@app.route('/api/hft-backtest')
def api_hft_backtest():
    """
    Grid-search backtest over all resolved HFT trades.
    Tests 1-variable, 2-variable, and key 3-variable combos.
    Returns ranked results: combo_label, n, wr, breakeven_wr, edge, total_pnl, avg_pnl.
    """
    global hft_scanner
    # Load trades — use scanner if live, else read file directly
    try:
        if hft_scanner:
            with hft_scanner._lock:
                trades = list(hft_scanner._trades)
        else:
            path = os.path.join(os.path.dirname(__file__), 'hft_paper_trades.json')
            with open(path, 'r') as f:
                trades = json.load(f)
    except Exception as e:
        return jsonify({'error': str(e), 'results': []})

    resolved = [t for t in trades
                if t.get('resolved') and t.get('outcome') in ('WIN', 'LOSS')]
    if len(resolved) < 10:
        return jsonify({'error': 'Need at least 10 resolved trades', 'results': [], 'n_total': len(resolved)})

    # ── dimension definitions ─────────────────────────────────────────────────
    def secs_b(t):
        s = t.get('secs_to_close', 999)
        if s < 20:   return '<20s'
        if s < 40:   return '20-40s'
        if s < 60:   return '40-60s'
        return '60s+'

    def price_b(t):
        p = t.get('entry_price', 0)
        if p < 0.65: return 'p60-65'
        if p < 0.70: return 'p65-70'
        if p < 0.75: return 'p70-75'
        if p < 0.80: return 'p75-80'
        if p < 0.85: return 'p80-85'
        return 'p85-90'

    def hour_b(t):
        h = t.get('fill_hour')
        if h is None: return None
        if h < 4:  return 'h00-04'
        if h < 8:  return 'h04-08'
        if h < 12: return 'h08-12'
        if h < 16: return 'h12-16'
        if h < 20: return 'h16-20'
        return 'h20-24'

    def tf_b(t):
        slug = t.get('market_slug', '')
        return '15m' if '-updown-15m-' in slug else '5m'

    dims = {
        'strategy':  lambda t: t.get('strategy', '?'),
        'symbol':    lambda t: t.get('symbol', '?').upper(),
        'secs':      secs_b,
        'price':     price_b,
        'session':   lambda t: t.get('fill_session') or 'UNKNOWN',
        'direction': lambda t: t.get('direction', '?').upper(),
        'hour':      hour_b,
        'timeframe': tf_b,
    }

    MIN_N = 8  # minimum trades to include a combo in results

    def _stats(subset):
        n     = len(subset)
        wins  = sum(1 for t in subset if t.get('outcome') == 'WIN')
        wr    = wins / n
        pnl   = sum(t.get('paper_pnl') or t.get('pnl') or 0 for t in subset)
        avg_e = sum(t.get('entry_price', 0.75) for t in subset) / n
        # Breakeven WR: entry_price = cost, win pays 1.0, so breakeven = avg_entry_price
        be_wr = avg_e
        edge  = wr - be_wr
        pnls  = [t.get('paper_pnl') or t.get('pnl') or 0 for t in subset]
        mean_p = pnl / n
        variance = sum((p - mean_p) ** 2 for p in pnls) / n
        std_p = variance ** 0.5
        sharpe = (mean_p / std_p) if std_p > 0 else 0.0
        return {
            'n':        n,
            'wr':       round(wr * 100, 1),
            'be_wr':    round(be_wr * 100, 1),
            'edge':     round(edge * 100, 1),
            'total_pnl': round(pnl, 2),
            'avg_pnl':  round(mean_p, 3),
            'sharpe':   round(sharpe, 3),
        }

    results = []

    # ── 1-variable slices ─────────────────────────────────────────────────────
    for dim_name, fn in dims.items():
        groups = {}
        for t in resolved:
            key = fn(t)
            if key is None: continue
            groups.setdefault(key, []).append(t)
        for val, subset in groups.items():
            if len(subset) < MIN_N: continue
            s = _stats(subset)
            s['combo'] = f'{dim_name}={val}'
            s['dims']  = {dim_name: val}
            results.append(s)

    # ── 2-variable combos ─────────────────────────────────────────────────────
    dim_names = list(dims.keys())
    for i in range(len(dim_names)):
        for j in range(i + 1, len(dim_names)):
            d1, d2 = dim_names[i], dim_names[j]
            f1, f2 = dims[d1], dims[d2]
            groups = {}
            for t in resolved:
                k1, k2 = f1(t), f2(t)
                if k1 is None or k2 is None: continue
                key = (k1, k2)
                groups.setdefault(key, []).append(t)
            for (v1, v2), subset in groups.items():
                if len(subset) < MIN_N: continue
                s = _stats(subset)
                s['combo'] = f'{d1}={v1} + {d2}={v2}'
                s['dims']  = {d1: v1, d2: v2}
                results.append(s)

    # ── key 3-variable combos ─────────────────────────────────────────────────
    key_triples = [
        ('strategy', 'secs', 'price'),
        ('strategy', 'session', 'symbol'),
        ('strategy', 'secs', 'session'),
        ('symbol', 'secs', 'price'),
        ('symbol', 'session', 'direction'),
        ('strategy', 'timeframe', 'secs'),
        ('strategy', 'timeframe', 'price'),
        ('symbol', 'timeframe', 'secs'),
    ]
    for d1, d2, d3 in key_triples:
        f1, f2, f3 = dims[d1], dims[d2], dims[d3]
        groups = {}
        for t in resolved:
            k1, k2, k3 = f1(t), f2(t), f3(t)
            if any(x is None for x in (k1, k2, k3)): continue
            groups.setdefault((k1, k2, k3), []).append(t)
        for (v1, v2, v3), subset in groups.items():
            if len(subset) < MIN_N: continue
            s = _stats(subset)
            s['combo'] = f'{d1}={v1} + {d2}={v2} + {d3}={v3}'
            s['dims']  = {d1: v1, d2: v2, d3: v3}
            results.append(s)

    # Sort by edge desc, then total_pnl desc
    results.sort(key=lambda r: (r['edge'], r['total_pnl']), reverse=True)

    # Overall baseline
    baseline = _stats(resolved)
    baseline['combo'] = 'ALL (baseline)'
    baseline['dims']  = {}

    return jsonify({
        'results':  results,
        'baseline': baseline,
        'n_total':  len(resolved),
        'n_combos': len(results),
    })


@app.route('/api/hft-backtest-max')
def api_hft_backtest_max():
    """
    MAX backtest — exhaustive 4-variable combo search across all 8 HFT dimensions.
    Counterpart to the Claude Picks /api/backtest-max button: surfaces every
    (strategy × symbol × direction × X) cell with positive edge so the operator
    can spot latent winners that the hand-picked triples in /api/hft-backtest
    might miss.

    Returns same shape as /api/hft-backtest plus 'recommendations' (top cells
    suggested as paper/live overrides per symbol_overrides schema).
    """
    global hft_scanner
    try:
        if hft_scanner:
            with hft_scanner._lock:
                trades = list(hft_scanner._trades)
        else:
            path = os.path.join(os.path.dirname(__file__), 'hft_paper_trades.json')
            with open(path, 'r') as f:
                trades = json.load(f)
    except Exception as e:
        return jsonify({'error': str(e), 'results': []})

    resolved = [t for t in trades
                if t.get('resolved') and t.get('outcome') in ('WIN', 'LOSS')]
    if len(resolved) < 10:
        return jsonify({'error': 'Need at least 10 resolved trades', 'results': [],
                        'n_total': len(resolved)})

    # ── shared bucketers (copy of /api/hft-backtest) ─────────────────────────
    def secs_b(t):
        s = t.get('secs_to_close', 999)
        if s < 20:   return '<20s'
        if s < 40:   return '20-40s'
        if s < 60:   return '40-60s'
        return '60s+'

    def price_b(t):
        p = t.get('entry_price', 0)
        if p < 0.65: return 'p60-65'
        if p < 0.70: return 'p65-70'
        if p < 0.75: return 'p70-75'
        if p < 0.80: return 'p75-80'
        if p < 0.85: return 'p80-85'
        return 'p85-90'

    def hour_b(t):
        h = t.get('fill_hour')
        if h is None: return None
        if h < 4:  return 'h00-04'
        if h < 8:  return 'h04-08'
        if h < 12: return 'h08-12'
        if h < 16: return 'h12-16'
        if h < 20: return 'h16-20'
        return 'h20-24'

    def tf_b(t):
        slug = t.get('market_slug', '')
        return '15m' if '-updown-15m-' in slug else '5m'

    dims = {
        'strategy':  lambda t: t.get('strategy', '?'),
        'symbol':    lambda t: t.get('symbol', '?').upper(),
        'secs':      secs_b,
        'price':     price_b,
        'session':   lambda t: t.get('fill_session') or 'UNKNOWN',
        'direction': lambda t: t.get('direction', '?').upper(),
        'hour':      hour_b,
        'timeframe': tf_b,
    }

    # MAX uses a slightly higher MIN_N because 4-var combos fragment data hard.
    # n=8 was fine for 1-3 var; for 4-var we want at least n=10 to trust the cell.
    MIN_N = 10

    def _stats(subset):
        n     = len(subset)
        wins  = sum(1 for t in subset if t.get('outcome') == 'WIN')
        wr    = wins / n
        pnl   = sum(t.get('paper_pnl') or t.get('pnl') or 0 for t in subset)
        avg_e = sum(t.get('entry_price', 0.75) for t in subset) / n
        be_wr = avg_e
        edge  = wr - be_wr
        pnls  = [t.get('paper_pnl') or t.get('pnl') or 0 for t in subset]
        mean_p = pnl / n
        variance = sum((p - mean_p) ** 2 for p in pnls) / n
        std_p = variance ** 0.5
        sharpe = (mean_p / std_p) if std_p > 0 else 0.0
        return {
            'n':        n,
            'wr':       round(wr * 100, 1),
            'be_wr':    round(be_wr * 100, 1),
            'edge':     round(edge * 100, 1),
            'total_pnl': round(pnl, 2),
            'avg_pnl':  round(mean_p, 3),
            'sharpe':   round(sharpe, 3),
        }

    results = []
    dim_names = list(dims.keys())

    # ── 1-var, 2-var, 3-var combos (same as /api/hft-backtest, recomputed for self-contained response) ─
    # 1-var
    for dim_name, fn in dims.items():
        groups = {}
        for t in resolved:
            key = fn(t)
            if key is None: continue
            groups.setdefault(key, []).append(t)
        for val, subset in groups.items():
            if len(subset) < MIN_N: continue
            s = _stats(subset)
            s['combo'] = f'{dim_name}={val}'
            s['dims']  = {dim_name: val}
            s['depth'] = 1
            results.append(s)

    # 2-var
    for i in range(len(dim_names)):
        for j in range(i + 1, len(dim_names)):
            d1, d2 = dim_names[i], dim_names[j]
            f1, f2 = dims[d1], dims[d2]
            groups = {}
            for t in resolved:
                k1, k2 = f1(t), f2(t)
                if k1 is None or k2 is None: continue
                groups.setdefault((k1, k2), []).append(t)
            for (v1, v2), subset in groups.items():
                if len(subset) < MIN_N: continue
                s = _stats(subset)
                s['combo'] = f'{d1}={v1} + {d2}={v2}'
                s['dims']  = {d1: v1, d2: v2}
                s['depth'] = 2
                results.append(s)

    # 3-var — exhaustive (not just hand-picked triples like in /api/hft-backtest)
    for i in range(len(dim_names)):
        for j in range(i + 1, len(dim_names)):
            for k in range(j + 1, len(dim_names)):
                d1, d2, d3 = dim_names[i], dim_names[j], dim_names[k]
                f1, f2, f3 = dims[d1], dims[d2], dims[d3]
                groups = {}
                for t in resolved:
                    k1, k2, k3 = f1(t), f2(t), f3(t)
                    if any(x is None for x in (k1, k2, k3)): continue
                    groups.setdefault((k1, k2, k3), []).append(t)
                for (v1, v2, v3), subset in groups.items():
                    if len(subset) < MIN_N: continue
                    s = _stats(subset)
                    s['combo'] = f'{d1}={v1} + {d2}={v2} + {d3}={v3}'
                    s['dims']  = {d1: v1, d2: v2, d3: v3}
                    s['depth'] = 3
                    results.append(s)

    # ── 4-variable combos — the MAX extension ────────────────────────────────
    for i in range(len(dim_names)):
        for j in range(i + 1, len(dim_names)):
            for k in range(j + 1, len(dim_names)):
                for l in range(k + 1, len(dim_names)):
                    d1, d2, d3, d4 = dim_names[i], dim_names[j], dim_names[k], dim_names[l]
                    f1, f2, f3, f4 = dims[d1], dims[d2], dims[d3], dims[d4]
                    groups = {}
                    for t in resolved:
                        k1, k2, k3, k4 = f1(t), f2(t), f3(t), f4(t)
                        if any(x is None for x in (k1, k2, k3, k4)): continue
                        groups.setdefault((k1, k2, k3, k4), []).append(t)
                    for (v1, v2, v3, v4), subset in groups.items():
                        if len(subset) < MIN_N: continue
                        s = _stats(subset)
                        s['combo'] = f'{d1}={v1} + {d2}={v2} + {d3}={v3} + {d4}={v4}'
                        s['dims']  = {d1: v1, d2: v2, d3: v3, d4: v4}
                        s['depth'] = 4
                        results.append(s)

    results.sort(key=lambda r: (r['edge'], r['total_pnl']), reverse=True)

    baseline = _stats(resolved)
    baseline['combo'] = 'ALL (baseline)'
    baseline['dims']  = {}

    # ── Recommendations: actionable cells for symbol_overrides ───────────────
    # Surface (symbol, strategy, direction) cells that are strong winners or
    # losers — operator can paste these into hft_settings.json symbol_overrides.
    sym_strat_dir = {}
    for t in resolved:
        sym = t.get('symbol', '?').upper()
        strat = t.get('strategy', '?')
        dir_ = t.get('direction', '?').upper()
        sym_strat_dir.setdefault((sym, strat, dir_), []).append(t)
    recs_promote, recs_quarantine = [], []
    for (sym, strat, dir_), subset in sym_strat_dir.items():
        if len(subset) < 15: continue   # need real sample to trust direction
        s = _stats(subset)
        if s['edge'] >= 8 and s['total_pnl'] > 0:
            recs_promote.append({**s, 'symbol': sym, 'strategy': strat, 'direction': dir_,
                                 'recommendation': 'LIVE — strong edge'})
        elif s['edge'] <= -8 or s['total_pnl'] < -50:
            recs_quarantine.append({**s, 'symbol': sym, 'strategy': strat, 'direction': dir_,
                                    'recommendation': 'PAPER — bleeding'})
    recs_promote.sort(key=lambda r: -r['edge'])
    recs_quarantine.sort(key=lambda r: r['edge'])

    # 2026-05-22: surface all per-(sym, strat, dir) cells with n>=10 so the UI can
    # show ACTIVE CELL OVERRIDES even for combos that don't make the promote/quarantine
    # bands. Keys match the hft_settings.json cell_overrides schema: "SYM|DIR|STRAT".
    all_cells = []
    for (sym, strat, dir_), subset in sym_strat_dir.items():
        if len(subset) < 10: continue
        s = _stats(subset)
        all_cells.append({**s, 'symbol': sym, 'strategy': strat, 'direction': dir_})
    all_cells.sort(key=lambda r: -r['total_pnl'])

    # Active cell_overrides from the scanner (may be empty dict).
    _cell_overrides = {}
    _symbol_overrides = {}
    try:
        if hft_scanner is not None:
            _cell_overrides = dict(hft_scanner.cell_overrides)
            # 2026-05-22: surface symbol_overrides too so the UI can auto-fill missing
            # direction/strategy on combo rows from the symbol's allowed-dimensions whitelist.
            _symbol_overrides = dict(hft_scanner.symbol_overrides)
    except Exception:
        pass

    # 2026-05-22: RL-blocked cells report. Aggregates the shadow log
    # (hft_rl_blocked.json / .weekend.json via _resolve_state_path) by SYM|DIR|STRAT.
    # These are signals the RL gate rejected — they don't show up in regular MAX cells.
    # Useful for spotting cells the RL Q-table is over-suppressing (positive counterfactual PnL
    # means the gate is blocking trades that would have made money).
    _rl_blocked_cells = []
    try:
        _rlb_path = _resolve_state_path('hft_rl_blocked.json')
        if os.path.exists(_rlb_path):
            with open(_rlb_path, 'r', encoding='utf-8') as _f:
                _rlb = json.load(_f)
            _rlb_resolved = [e for e in _rlb
                             if e.get('resolved') and e.get('outcome') in ('WIN','LOSS')
                             and e.get('symbol') and e.get('direction') and e.get('strategy')]
            _by_cell = {}
            for e in _rlb_resolved:
                k = (e['symbol'], e['direction'], e['strategy'])
                _by_cell.setdefault(k, []).append(e)
            for (sym, d, st), subset in _by_cell.items():
                if len(subset) < 10: continue
                n = len(subset)
                wins = sum(1 for e in subset if e['outcome'] == 'WIN')
                # Counterfactual PnL — what the trade WOULD have made if not RL-blocked.
                cf_pnl = sum(float(e.get('shadow_pnl') or 0) for e in subset)
                avg_q = sum(float(e.get('rl_q') or 0) for e in subset) / n
                _rl_blocked_cells.append({
                    'symbol':     sym,
                    'direction':  d,
                    'strategy':   st,
                    'n':          n,
                    'wr':         round(wins / n * 100, 1),
                    'avg_pnl':    round(cf_pnl / n, 3),
                    'total_pnl':  round(cf_pnl, 2),
                    'avg_q':      round(avg_q, 3),
                })
            _rl_blocked_cells.sort(key=lambda c: -c['total_pnl'])
    except Exception as _rlb_err:
        logger.debug(f'[HFT-MAX] rl_blocked aggregation error: {_rlb_err}')

    return jsonify({
        'mode':     'MAX',
        'results':  results,
        'baseline': baseline,
        'n_total':  len(resolved),
        'n_combos': len(results),
        'recommendations': {
            'promote_live':       recs_promote[:10],
            'quarantine_to_paper': recs_quarantine[:10],
        },
        'all_cells':         all_cells[:60],
        'cell_overrides':    _cell_overrides,
        'symbol_overrides':  _symbol_overrides,
        'rl_blocked_cells':  _rl_blocked_cells[:40],
    })


@app.route('/api/rl-state')
def api_rl_state():
    """Return all three RL Q-tables with blocked/allowed/exploring breakdown.
    Reads through _resolve_state_path so weekend mode shows the weekend Q-tables."""
    THRESHOLD = {'hft': -0.05, 'manip': -0.20, 'picks': -0.10}
    MIN_N = 3
    result = {}
    files = {
        'hft':   ('hft_rl_state.json',          THRESHOLD['hft']),
        'manip': ('manip_rl_state.json',         THRESHOLD['manip']),
        'picks': ('claude_picks_rl_state.json',  THRESHOLD['picks']),
    }
    for name, (filename, thresh) in files.items():
        path = _resolve_state_path(filename)
        try:
            with open(path, encoding='utf-8') as _f:
                q = json.load(_f)
        except Exception:
            q = {}
        states = []
        for key, v in q.items():
            n, qv = v['n'], v['q']
            if n < MIN_N:
                status = 'exploring'
            elif qv < thresh:
                status = 'blocked'
            else:
                status = 'allowed'
            states.append({'key': key, 'q': round(qv, 4), 'n': n, 'status': status})
        states.sort(key=lambda s: s['q'])
        result[name] = {
            'threshold': thresh,
            'total':     len(states),
            'blocked':   sum(1 for s in states if s['status'] == 'blocked'),
            'allowed':   sum(1 for s in states if s['status'] == 'allowed'),
            'exploring': sum(1 for s in states if s['status'] == 'exploring'),
            'states':    states,
        }
    return jsonify(result)


@app.route('/api/hft-settings', methods=['GET', 'POST'])
def api_hft_settings():
    """GET: return current live/paper mode and stake. POST: update settings."""
    global hft_scanner
    if hft_scanner is None:
        return jsonify({'error': 'HFT scanner not running'}), 503

    if request.method == 'GET':
        return jsonify({
            'live_mode':    hft_scanner.live_mode,
            'stake':        hft_scanner.stake,
            'wallet_live':  bool(hft_scanner.bot and hft_scanner.bot.wallet_live and hft_scanner.bot.clob_client),
            'paper_symbols':    sorted(hft_scanner.paper_symbols),
            'paper_strategies': sorted(hft_scanner.paper_strategies),
            'mb_sl_threshold':  hft_scanner.mb_sl_threshold,
            'mb_max_entry':     hft_scanner.mb_max_entry,
            'sizing_mode':      getattr(hft_scanner, 'sizing_mode', 'kelly'),
        })

    data = request.get_json(force=True) or {}
    if 'live_mode' in data:
        new_mode = bool(data['live_mode'])
        # Safety: refuse to enable live mode if wallet is not connected
        if new_mode and not (hft_scanner.bot and hft_scanner.bot.wallet_live and hft_scanner.bot.clob_client):
            return jsonify({'error': 'Wallet not connected — cannot enable live mode'}), 400
        hft_scanner.live_mode = new_mode
        logger.info(f'[HFT] Mode switched to {"LIVE" if new_mode else "PAPER"} via UI')
    if 'stake' in data:
        try:
            stake = float(data['stake'])
            if stake < 1.0 or stake > 500.0:
                return jsonify({'error': 'Stake must be between $1 and $500'}), 400
            hft_scanner.stake = round(stake, 2)
        except (ValueError, TypeError):
            return jsonify({'error': 'Invalid stake value'}), 400
    # Per-symbol live/paper toggle: {paper_symbol: 'BTC', enabled: true/false}
    if 'paper_symbol' in data:
        sym = str(data['paper_symbol']).upper().strip()
        if data.get('enabled', True):
            hft_scanner.paper_symbols.add(sym)
            logger.info(f'[HFT] {sym} forced to PAPER via UI toggle')
        else:
            hft_scanner.paper_symbols.discard(sym)
            logger.info(f'[HFT] {sym} set to LIVE via UI toggle')
    # Per-strategy live/paper toggle: {paper_strategy: 'EXTREME-RIDE', enabled: true/false}
    if 'paper_strategy' in data:
        strat = str(data['paper_strategy']).upper().strip()
        if data.get('enabled', True):
            hft_scanner.paper_strategies.add(strat)
            logger.info(f'[HFT] {strat} forced to PAPER via UI toggle')
        else:
            hft_scanner.paper_strategies.discard(strat)
            logger.info(f'[HFT] {strat} set to LIVE via UI toggle')
    # MOMENTUM-BURST stop-loss threshold — accepts negative fraction, e.g. -0.10 = 10%
    if 'mb_sl_threshold' in data:
        try:
            v = float(data['mb_sl_threshold'])
            if not (-0.50 <= v < 0):
                return jsonify({'error': 'mb_sl_threshold must be between -0.50 and 0 (exclusive)'}), 400
            hft_scanner.mb_sl_threshold = round(v, 4)
            logger.info(f'[HFT] mb_sl_threshold set to {hft_scanner.mb_sl_threshold*100:.0f}%')
        except (ValueError, TypeError):
            return jsonify({'error': 'Invalid mb_sl_threshold'}), 400
    # MOMENTUM-BURST max entry price — accepts 0.30..0.87
    if 'mb_max_entry' in data:
        try:
            v = float(data['mb_max_entry'])
            if not (0.30 <= v <= 0.87):
                return jsonify({'error': 'mb_max_entry must be between 0.30 and 0.87'}), 400
            hft_scanner.mb_max_entry = round(v, 4)
            logger.info(f'[HFT] mb_max_entry set to {hft_scanner.mb_max_entry:.2f}')
        except (ValueError, TypeError):
            return jsonify({'error': 'Invalid mb_max_entry'}), 400
    # Sizing mode toggle (2026-05-30): 'kelly' = RL-Kelly (capped at stake); 'fixed' = always bet stake
    if 'sizing_mode' in data:
        sm = str(data.get('sizing_mode', '')).lower()
        if sm not in ('kelly', 'fixed'):
            return jsonify({'error': "sizing_mode must be 'kelly' or 'fixed'"}), 400
        hft_scanner.sizing_mode = sm
        logger.info(f'[HFT] sizing_mode set to {sm}')
    hft_scanner._save_settings()
    return jsonify({
        'live_mode':        hft_scanner.live_mode,
        'stake':            hft_scanner.stake,
        'paper_symbols':    sorted(hft_scanner.paper_symbols),
        'paper_strategies': sorted(hft_scanner.paper_strategies),
        'mb_sl_threshold':  hft_scanner.mb_sl_threshold,
        'mb_max_entry':     hft_scanner.mb_max_entry,
        'sizing_mode':      getattr(hft_scanner, 'sizing_mode', 'kelly'),
    })


# ── Protection override toggle (per-scanner, persisted to settings) ─────────
# 2026-05-17: when ON for a scanner, the bot's automatic protection layers
# (circuit-breaker auto-paper, AutoPauseGate, HFT auto-filter) are bypassed
# so user-set live_mode stays sticky. Manual paper_symbols/strategies still apply.
@app.route('/api/protection-override', methods=['GET', 'POST'])
def api_protection_override():
    """GET: return current override state for all scanners.
       POST: body {scanner: 'hft'|'btc-ml'|'eth-ml'|'picks', on: bool} toggles one."""
    global hft_scanner, btc_ml_scanner, eth_ml_scanner, claude_scanner

    def _state():
        return {
            'hft':    bool(getattr(hft_scanner,    'protection_override', False)) if hft_scanner    else None,
            'btc-ml': bool(getattr(btc_ml_scanner, 'protection_override', False)) if btc_ml_scanner else None,
            'eth-ml': bool(getattr(eth_ml_scanner, 'protection_override', False)) if eth_ml_scanner else None,
            'picks':  bool(claude_scanner.strategy_modes.get('_protection_override', False)) if claude_scanner else None,
        }

    if request.method == 'GET':
        return jsonify(_state())

    data = request.get_json(force=True) or {}
    target = str(data.get('scanner', '')).lower().strip()
    on = bool(data.get('on', False))

    if target == 'hft':
        if hft_scanner is None:
            return jsonify({'error': 'HFT scanner not running'}), 503
        hft_scanner.protection_override = on
        hft_scanner._save_settings()
    elif target == 'btc-ml':
        if btc_ml_scanner is None:
            return jsonify({'error': 'BTC-ML scanner not running'}), 503
        btc_ml_scanner.protection_override = on
        btc_ml_scanner._save_settings()
    elif target == 'eth-ml':
        if eth_ml_scanner is None:
            return jsonify({'error': 'ETH-ML scanner not running'}), 503
        eth_ml_scanner.protection_override = on
        eth_ml_scanner._save_settings()
    elif target == 'picks':
        if claude_scanner is None:
            return jsonify({'error': 'Claude-Picks scanner not running'}), 503
        claude_scanner.strategy_modes['_protection_override'] = on
        claude_scanner._save_strategy_modes()
    else:
        return jsonify({'error': f'unknown scanner "{target}" — expected hft|btc-ml|eth-ml|picks'}), 400

    logger.warning(f'[PROTECTION-OVERRIDE] {target} -> {"ON" if on else "OFF"} via UI')
    return jsonify(_state())


# ── ML scanner route helpers (shared between /btc-ml-* and /eth-ml-*) ───────
def _ml_trades_payload(scanner, label):
    if scanner is None:
        return jsonify({'trades': [], 'stats': {}, 'error': f'{label} scanner not running'})
    with scanner._lock:
        trades = list(scanner._trades)
    trades_sorted = sorted(trades, key=lambda t: t.get('logged_at', ''), reverse=True)
    return jsonify({'trades': trades_sorted[:200], 'stats': scanner.get_stats()})

def _ml_settings_payload(scanner, label):
    if scanner is None:
        return jsonify({'error': f'{label} scanner not running'}), 503
    if request.method == 'GET':
        return jsonify({
            'live_mode':     scanner.live_mode,
            'stake':         scanner.stake,
            'wallet_live':   bool(scanner.bot and scanner.bot.wallet_live and scanner.bot.clob_client),
            'tp_sl_enabled': scanner.tp_sl_enabled,
            'tp_pct':        scanner.tp_pct,
            'sl_pct':        scanner.sl_pct,
            'blocked_hours': list(getattr(scanner, 'blocked_hours', []) or []),
            'hour_block_enabled': bool(getattr(scanner, 'hour_block_enabled', True)),
            'max_volatility': float(getattr(scanner, 'max_volatility', 0.0) or 0.0),
        })
    data = request.get_json(force=True) or {}
    if 'live_mode' in data:
        new_mode = bool(data['live_mode'])
        if new_mode and not (scanner.bot and scanner.bot.wallet_live and scanner.bot.clob_client):
            return jsonify({'error': 'Wallet not connected'}), 400
        scanner.live_mode = new_mode
    if 'stake' in data:
        try:
            stake = float(data['stake'])
            if not (1.0 <= stake <= 500.0):
                return jsonify({'error': 'Stake must be $1–$500'}), 400
            scanner.stake = round(stake, 2)
        except (ValueError, TypeError):
            return jsonify({'error': 'Invalid stake'}), 400
    if 'tp_sl_enabled' in data:
        scanner.tp_sl_enabled = bool(data['tp_sl_enabled'])
        logger.info(f'[{label}] TP/SL {"ENABLED" if scanner.tp_sl_enabled else "DISABLED"} via UI')
    if 'tp_pct' in data:
        try:
            v = float(data['tp_pct'])
            if not (0.05 <= v <= 1.0):
                return jsonify({'error': 'tp_pct must be 0.05–1.0'}), 400
            scanner.tp_pct = round(v, 4)
        except (ValueError, TypeError):
            return jsonify({'error': 'Invalid tp_pct'}), 400
    if 'sl_pct' in data:
        try:
            v = float(data['sl_pct'])
            if not (-0.50 <= v <= -0.05):
                return jsonify({'error': 'sl_pct must be -0.50 to -0.05'}), 400
            scanner.sl_pct = round(v, 4)
        except (ValueError, TypeError):
            return jsonify({'error': 'Invalid sl_pct'}), 400
    if 'blocked_hours' in data:
        bh = data['blocked_hours']
        if not isinstance(bh, list):
            return jsonify({'error': 'blocked_hours must be a list of 0-23 ints'}), 400
        old_hrs = list(getattr(scanner, 'blocked_hours', []) or [])
        try:
            scanner.blocked_hours = sorted({int(h) for h in bh if 0 <= int(h) <= 23})
        except (TypeError, ValueError):
            return jsonify({'error': 'blocked_hours entries must be 0-23 ints'}), 400
        try:
            scanner._stamp_block_adds(old_hrs, scanner.blocked_hours)
        except Exception as _be:
            logger.debug(f'[{label}] stamp_block_adds err: {_be}')
        logger.info(f'[{label}] blocked_hours set to {scanner.blocked_hours} via UI')
    if 'hour_block_enabled' in data:
        scanner.hour_block_enabled = bool(data['hour_block_enabled'])
        logger.info(f'[{label}] hour-block gate '
                    f'{"ENFORCED" if scanner.hour_block_enabled else "OFF (training — shadow-only, auto-revert frozen)"} via UI')
    if 'max_volatility' in data:
        try:
            mv = float(data['max_volatility'])
            if not (0.0 <= mv <= 1.0):
                return jsonify({'error': 'max_volatility must be in [0.0, 1.0]'}), 400
            scanner.max_volatility = mv
            logger.info(f'[{label}] max_volatility set to {scanner.max_volatility:.4f} via UI')
        except (ValueError, TypeError):
            return jsonify({'error': 'Invalid max_volatility'}), 400
    scanner._save_settings()
    return jsonify({
        'live_mode':     scanner.live_mode,
        'stake':         scanner.stake,
        'tp_sl_enabled': scanner.tp_sl_enabled,
        'tp_pct':        scanner.tp_pct,
        'sl_pct':        scanner.sl_pct,
        'blocked_hours': list(getattr(scanner, 'blocked_hours', []) or []),
        'hour_block_enabled': bool(getattr(scanner, 'hour_block_enabled', True)),
        'max_volatility': float(getattr(scanner, 'max_volatility', 0.0) or 0.0),
    })

def _ml_state_payload(scanner, label):
    if scanner is None:
        return jsonify({'error': f'{label} scanner not running'}), 503
    m = scanner.model
    with scanner._lock:
        trades = list(scanner._trades)
        resolved_count = sum(1 for t in trades
                             if t.get('resolved') and t.get('outcome') in ('WIN', 'LOSS'))
        real_trades   = [t for t in trades if t.get('real_trade')]
        filled        = [t for t in real_trades if t.get('fill_confirmed') is True]
        unfilled      = [t for t in real_trades
                         if t.get('fill_confirmed') is False or t.get('order_ok') is False]
        pending_fill  = [t for t in real_trades
                         if t.get('fill_confirmed') is None and t.get('order_ok') is not False]
        filled_resolved = [t for t in filled if t.get('resolved')]
        real_wins   = sum(1 for t in filled_resolved if t.get('outcome') == 'WIN')
        real_losses = sum(1 for t in filled_resolved if t.get('outcome') == 'LOSS')
        real_pnl    = round(sum(t.get('pnl') or 0 for t in filled_resolved), 2)
        # Today (UTC) — full PnL paper+filled
        _today = datetime.now(timezone.utc).strftime('%Y-%m-%d')
        today_resolved = [t for t in trades if t.get('resolved')
                          and t.get('outcome') in ('WIN','LOSS')
                          and (t.get('logged_at') or '').startswith(_today)]
        today_wins = sum(1 for t in today_resolved if t.get('outcome') == 'WIN')
        today_pnl  = round(sum(t.get('pnl') or t.get('paper_pnl') or 0 for t in today_resolved), 2)
    fill_rate = round(len(filled) / max(len(real_trades), 1) * 100, 1)
    real_wr   = round(real_wins / max(real_wins + real_losses, 1) * 100, 1)
    # 2026-05-23 hour-block cohort: surface what the blocklist avoided.
    # Per-hour aggregation now lives on BTCMLScanner._hour_block_shadow_summary
    # (shared with _maybe_autoflip_blocked_hours so UI + auto-flip see the same
    # numbers). Totals are rolled up from the per-hour map.
    _per_hr_clean = scanner._hour_block_shadow_summary()
    _hr_wins   = sum(v['wins']    for v in _per_hr_clean.values())
    _hr_losses = sum(v['losses']  for v in _per_hr_clean.values())
    _hr_pending = sum(v['pending'] for v in _per_hr_clean.values())
    _hr_resolved_n = _hr_wins + _hr_losses
    _hr_pnl = round(sum(v['pnl'] for v in _per_hr_clean.values()), 2)
    _hr_wr  = round(_hr_wins / max(_hr_resolved_n, 1) * 100, 1) if _hr_resolved_n else None

    # 2026-05-25 auto-flip audit: surface recent revert events so the UI tile
    # can show "auto-flip ON, last revert hr 13 at ..." without further plumbing.
    _autoflip_events = []
    try:
        _autoflip_path = _resolve_state_path(f'{scanner._sym_lc}_ml_autoflip.json')
        with open(_autoflip_path) as _f:
            _autoflip_events = (json.load(_f) or [])[-5:]
    except (FileNotFoundError, json.JSONDecodeError, OSError):
        pass

    # 2026-05-23 volatility-gate shadow cohort. Mirrors hour_block_shadow but
    # bucketed by VOL_LL_HH bands. Deduped by (market_slug,direction). Only
    # rendered if max_volatility > 0 (gate enabled).
    try:
        _shadow_trades = list(scanner.rl_shadow._trades)
    except Exception:
        _shadow_trades = []
    _vol_sys = f'{scanner._sym_lc}_ml_vol_block'
    _vol_raw = [t for t in _shadow_trades if t.get('rl_system') == _vol_sys]
    _vol_seen: set = set()
    _vol_all: list = []
    for t in _vol_raw:
        k = (t.get('market_slug'), t.get('direction'))
        if k in _vol_seen:
            continue
        _vol_seen.add(k)
        _vol_all.append(t)
    _vol_resolved = [t for t in _vol_all if t.get('resolved')]
    _vol_wins   = sum(1 for t in _vol_resolved if t.get('outcome') == 'WIN')
    _vol_losses = sum(1 for t in _vol_resolved if t.get('outcome') == 'LOSS')
    _vol_pnl    = round(sum(t.get('shadow_pnl') or 0 for t in _vol_resolved), 2)
    _vol_wr     = round(_vol_wins / max(_vol_wins + _vol_losses, 1) * 100, 1) if (_vol_wins + _vol_losses) else None
    from collections import defaultdict as _dd
    _per_vol: dict = _dd(lambda: {'wins': 0, 'losses': 0, 'pending': 0, 'pnl': 0.0})
    for t in _vol_all:
        k = t.get('rl_state_key', '')  # e.g. VOL_06_08
        if not t.get('resolved'):
            _per_vol[k]['pending'] += 1
            continue
        if t.get('outcome') == 'WIN':
            _per_vol[k]['wins'] += 1
        elif t.get('outcome') == 'LOSS':
            _per_vol[k]['losses'] += 1
        _per_vol[k]['pnl'] += t.get('shadow_pnl') or 0
    _per_vol_clean = {
        k: {**v, 'pnl': round(v['pnl'], 2),
            'wr': (round(v['wins'] / (v['wins']+v['losses']) * 100, 1)
                   if (v['wins']+v['losses']) else None)}
        for k, v in _per_vol.items()
    }
    return jsonify({
        'ml_model': {
            'weights':             m.weights,
            'bias':                m.bias,
            'feature_names':       m.FEATURE_NAMES,
            'feature_importances': m.feature_importances(),
            'n_trained':           m.n_trained,
            'accuracy':            m.accuracy,
            'last_retrain_ts':     m.last_retrain_ts,
        },
        'last_prediction':     scanner._last_prediction,
        'rl_enabled':          resolved_count >= BTCMLRl.ENABLED_AFTER,
        'resolved_count':      resolved_count,
        'rl_summary':          scanner.rl.summary(),
        'live_mode':           scanner.live_mode,
        'stake':               scanner.stake,
        'scan_count':          scanner._scan_count,
        'last_scan_ts':        scanner._last_scan_ts,
        'symbol':              scanner.SYMBOL,
        # Fill verification stats — surface to dashboard
        'real_trades':         len(real_trades),
        'filled_trades':       len(filled),
        'unfilled_trades':     len(unfilled),
        'pending_fill':        len(pending_fill),
        'fill_rate':           fill_rate,
        'real_wins':           real_wins,
        'real_losses':         real_losses,
        'real_pnl':            real_pnl,
        'real_wr':             real_wr,
        # Today (UTC) — full PnL across paper + filled
        'today_resolved':      len(today_resolved),
        'today_wins':          today_wins,
        'today_pnl':           today_pnl,
        'today_wr':            round(today_wins / max(len(today_resolved), 1) * 100, 1),
        # Hour-of-day blocklist & blocked-cohort shadow performance
        'blocked_hours':       list(getattr(scanner, 'blocked_hours', []) or []),
        'hour_block_enabled':  bool(getattr(scanner, 'hour_block_enabled', True)),
        'hour_block_shadow': {
            'total':    _hr_resolved_n + _hr_pending,
            'resolved': _hr_resolved_n,
            'pending':  _hr_pending,
            'wins':     _hr_wins,
            'losses':   _hr_losses,
            'wr':       _hr_wr,
            'pnl':      _hr_pnl,
            'by_hour':  _per_hr_clean,
        },
        # Auto-flip config + last 5 revert events (audit trail on disk)
        'autoflip': {
            'enabled':     bool(getattr(scanner, 'AUTOFLIP_ENABLED', False)),
            'min_samples': int(getattr(scanner, 'AUTOFLIP_MIN_SAMPLES', 0) or 0),
            'min_avg_pnl': float(getattr(scanner, 'AUTOFLIP_MIN_AVG_PNL', 0.0) or 0.0),
            'last_events': _autoflip_events,
        },
        # Volatility gate & vol-cohort shadow performance
        'max_volatility':      float(getattr(scanner, 'max_volatility', 0.0) or 0.0),
        'vol_block_shadow': {
            'total':    len(_vol_all),
            'resolved': len(_vol_resolved),
            'pending':  len(_vol_all) - len(_vol_resolved),
            'wins':     _vol_wins,
            'losses':   _vol_losses,
            'wr':       _vol_wr,
            'pnl':      _vol_pnl,
            'by_band':  _per_vol_clean,
        },
    })


