def _hermes_state_payload(scanner):
    """Wraps scanner.get_stats() and tacks on last_nightly read from
    btc_hermes_nightly_lastrun.json + tail of btc_hermes_journal.json."""
    if not scanner:
        return jsonify({'error': 'btc_hermes_scanner not initialized'}), 503
    stats = scanner.get_stats()
    # Last-run heartbeat (always present after first nightly)
    lr_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'btc_hermes_nightly_lastrun.json')
    last_nightly = {}
    if os.path.exists(lr_path):
        try:
            with open(lr_path, 'r', encoding='utf-8') as f:
                last_nightly = json.load(f) or {}
        except Exception:
            pass
    # Pull rationale + clamped + proposed from the journal tail
    j_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'btc_hermes_journal.json')
    if os.path.exists(j_path):
        try:
            with open(j_path, 'r', encoding='utf-8') as f:
                journal = json.load(f) or []
            if journal:
                tail = journal[-1] or {}
                for k in ('proposed_params', 'final_params', 'clamped', 'hermes_rationale'):
                    if k in tail and tail[k] is not None:
                        # Friendlier key in UI payload
                        ui_k = {'proposed_params': 'proposed', 'final_params': 'final',
                                'hermes_rationale': 'rationale', 'clamped': 'clamped'}.get(k, k)
                        last_nightly[ui_k] = tail[k]
        except Exception:
            pass
    stats['last_nightly'] = last_nightly
    return jsonify(stats)


def _hermes_settings_payload(scanner):
    """GET returns current settings; POST updates allowed keys only.
    min_prob / min_edge / kelly_fraction are Hermes-tuned — POSTs to those
    return 400 with a clear message."""
    if not scanner:
        return jsonify({'error': 'btc_hermes_scanner not initialized'}), 503
    if request.method == 'GET':
        return jsonify({
            'live_mode':           scanner.live_mode,
            'stake':               scanner.stake,
            'tp_sl_enabled':       scanner.tp_sl_enabled,
            'tp_pct':              scanner.tp_pct,
            'sl_pct':              scanner.sl_pct,
            'min_prob':            scanner.min_prob,
            'min_edge':            scanner.min_edge,
            'kelly_fraction':      scanner.kelly_fraction,
            'sell_threshold':      getattr(scanner, 'sell_threshold', 0.05),
            'price_balance_max_dev': getattr(scanner, 'price_balance_max_dev', 0.20),
            'cut_loss_threshold':  getattr(scanner, 'cut_loss_threshold', 0.30),
            're_entry_threshold':  getattr(scanner, 're_entry_threshold', 0.05),
            'binance_winner_threshold': getattr(scanner, 'binance_winner_threshold', 0.002),
            'binance_loser_threshold':  getattr(scanner, 'binance_loser_threshold', 0.005),
            'protection_override': scanner.protection_override,
            'wallet_live':         bool(getattr(scanner.bot, 'wallet_live', False)) if scanner.bot else False,
        })
    # POST
    data = request.get_json(silent=True) or {}
    HERMES_TUNED = ('min_prob', 'min_edge', 'kelly_fraction',
                    'sell_threshold', 'price_balance_max_dev',
                    'cut_loss_threshold', 're_entry_threshold',
                    'binance_winner_threshold', 'binance_loser_threshold')
    for k in HERMES_TUNED:
        if k in data:
            return jsonify({'error': f'{k} is tuned automatically by Hermes nightly — not editable via UI'}), 400
    if 'live_mode' in data:
        new_mode = bool(data['live_mode'])
        if new_mode and not (scanner.bot and getattr(scanner.bot, 'wallet_live', False) and scanner.bot.clob_client):
            return jsonify({'error': 'Wallet not connected'}), 400
        scanner.live_mode = new_mode
        logger.info(f'[BTC-HERMES] live_mode={"ON" if new_mode else "OFF"} via UI')
    if 'stake' in data:
        try:
            s = float(data['stake'])
            if not (1.0 <= s <= 500.0):
                return jsonify({'error': 'stake must be 1-500'}), 400
            scanner.stake = round(s, 2)
        except (ValueError, TypeError):
            return jsonify({'error': 'invalid stake'}), 400
    if 'tp_sl_enabled' in data:
        scanner.tp_sl_enabled = bool(data['tp_sl_enabled'])
        logger.info(f'[BTC-HERMES] tp_sl_enabled={"ON" if scanner.tp_sl_enabled else "OFF"} via UI')
    if 'protection_override' in data:
        scanner.protection_override = bool(data['protection_override'])
        logger.info(f'[BTC-HERMES] protection_override={"ON" if scanner.protection_override else "OFF"} via UI')
    try:
        scanner._save_settings()
    except Exception as e:
        logger.warning(f'[BTC-HERMES] settings save error: {e}')
    return jsonify({
        'live_mode':           scanner.live_mode,
        'stake':               scanner.stake,
        'tp_sl_enabled':       scanner.tp_sl_enabled,
        'protection_override': scanner.protection_override,
    })


