def _ml_candles_payload(scanner, sym_upper: str):
    interval = request.args.get('interval', '1m')
    if interval not in ('1s', '15s', '1m', '5m'):
        return jsonify({'error': 'invalid interval'}), 400
    # 1s and 15s come from the live aggTrade builder — no REST possible
    if interval in ('1s', '15s'):
        if scanner and scanner._binance_ws:
            candles = scanner._binance_ws.get_candles(interval)
            big = scanner._binance_ws.get_big_trades(since_s=3.0)
        else:
            candles = []; big = []
        return jsonify({'candles': candles, 'interval': interval,
                        'big_trades': big, 'live': True})
    if scanner:
        candles = scanner._get_candles(interval, 120)
    else:
        import requests as _req
        try:
            r = _req.get('https://api.binance.com/api/v3/klines',
                         params={'symbol': f'{sym_upper}USDT', 'interval': interval, 'limit': 120},
                         timeout=5)
            raw = r.json()
            candles = [{'open': float(c[1]), 'high': float(c[2]),
                        'low':  float(c[3]),  'close': float(c[4]),
                        'volume': float(c[5]), 'time': int(c[0]) // 1000}
                       for c in raw]
        except Exception:
            candles = []
    return jsonify({'candles': candles, 'interval': interval})

