@app.route('/api/claude-picks')
def api_claude_picks():
    global claude_scanner
    if claude_scanner is None:
        return jsonify({'picks': [], 'error': 'Scanner not initialized'})
    try:
        picks = claude_scanner.scan()
        conv_bets = getattr(claude_scanner, 'conviction_bets', {}) or {}
        for p in picks:
            cap = float(conv_bets.get(p.get('conviction', 'MEDIUM'), claude_scanner.claude_max_bet))
            p['bet_amount'] = round(3.0, 2) if p.get('play_type') == 'NEAR-CLOSE' else round(cap, 2)
        return jsonify({'picks': picks, 'count': len(picks)})
    except Exception as e:
        logger.error(f"[CLAUDE-PICKS] Scan error: {e}")
        return jsonify({'picks': [], 'error': str(e)})


@app.route('/api/claude-brain')
def api_claude_brain():
    """Return the live brain log + scan matrix for visualization."""
    global claude_scanner
    if claude_scanner is None:
        return jsonify({'log': [], 'matrix': {}, 'scanning': False})
    since = request.args.get('since', 0, type=int)
    total = claude_scanner._brain_total
    kept  = len(claude_scanner.brain_log)
    oldest_total = total - kept   # monotonic index of brain_log[0]

    if since > total or since < oldest_total:
        # Cursor ahead of server (restart) or older than buffer → send everything
        start_idx = 0
    else:
        start_idx = since - oldest_total

    log = claude_scanner.brain_log[start_idx:]
    return jsonify({
        'log': log,
        'total': total,
        'matrix': claude_scanner.scan_matrix,
        'scanning': claude_scanner._scanning,
    })


@app.route('/api/claude-paper-log')
def api_claude_paper_log():
    """Return all Claude paper trades with W/L status for the dashboard."""
    global claude_scanner
    if claude_scanner is None:
        return jsonify({'trades': [], 'summary': {}})
    trades = claude_scanner._load_paper_log()
    # Exclude illiquid/stale price trades (ask < 8c) — not fillable in practice
    valid  = [t for t in trades if not t.get('inflated')]
    trades_sorted = sorted(trades, key=lambda t: t.get('logged_at',''), reverse=True)
    wins   = [t for t in valid if t.get('outcome') == 'WIN']
    losses = [t for t in valid if t.get('outcome') == 'LOSS']
    pending = [t for t in valid if not t.get('resolved')]
    resolved = [t for t in valid if t.get('resolved')]
    total_pnl = sum(t.get('paper_pnl') or 0 for t in resolved)

    def _conv_stats(conv):
        ts = [t for t in valid if t.get('conviction') == conv]
        w  = sum(1 for t in ts if t.get('outcome') == 'WIN')
        l  = sum(1 for t in ts if t.get('outcome') == 'LOSS')
        pnl = sum(t.get('paper_pnl') or 0 for t in ts if t.get('resolved'))
        return {'wins': w, 'losses': l, 'total': len(ts),
                'win_rate': round(w / max(w+l, 1) * 100, 1),
                'pnl': round(pnl, 2)}

    # Per play-type breakdown
    _today_str = datetime.now(timezone.utc).strftime('%Y-%m-%d')
    # Picks writes naive local-time logged_at; need TZ conversion for the
    # today-UTC date check (otherwise today_pnl reads $0 between local-midnight
    # and UTC-midnight, e.g. 5pm-midnight PT). See /api/daily-pnl for the same fix.
    _local_tz = datetime.now().astimezone().tzinfo
    def _is_today_utc_picks(la):
        if not la: return False
        if la.endswith('+00:00') or la.endswith('Z'):
            return la.startswith(_today_str)
        try:
            dt = datetime.fromisoformat(la.replace('Z', '+00:00'))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=_local_tz)
            return dt.astimezone(timezone.utc).strftime('%Y-%m-%d') == _today_str
        except Exception:
            return la.startswith(_today_str)
    def _type_stats(pt):
        ts = [t for t in valid if t.get('play_type') == pt]
        w  = sum(1 for t in ts if t.get('outcome') == 'WIN')
        l  = sum(1 for t in ts if t.get('outcome') == 'LOSS')
        pnl = sum(t.get('paper_pnl') or 0 for t in ts if t.get('resolved'))
        calibrated = round(w / (w+l) * 100, 1) if (w+l) >= (claude_scanner.MIN_CALIBRATION_SAMPLES if claude_scanner else 15) else None
        # Confirmed-fill-only stats (real money, verified MATCHED/FILLED via CLOB poll)
        filled_ts = [t for t in ts if t.get('real_trade') and
                     t.get('fill_confirmed') is True and t.get('resolved')]
        fw = sum(1 for t in filled_ts if t.get('outcome') == 'WIN')
        fl = sum(1 for t in filled_ts if t.get('outcome') == 'LOSS')
        filled_pnl = round(sum(t.get('paper_pnl') or 0 for t in filled_ts), 2)
        # Today-only stats (full PnL: paper + filled, UTC day) — uses TZ-aware match
        today_ts = [t for t in ts if _is_today_utc_picks(t.get('logged_at') or '')
                    and t.get('outcome') in ('WIN', 'LOSS')]
        tw = sum(1 for t in today_ts if t.get('outcome') == 'WIN')
        today_pnl = round(sum(t.get('paper_pnl') or 0 for t in today_ts), 2)
        today_wr = round(tw / max(len(today_ts), 1) * 100, 1)
        return {'wins': w, 'losses': l, 'total': len(ts),
                'win_rate': round(w / max(w+l, 1) * 100, 1),
                'pnl': round(pnl, 2),
                'calibrated': calibrated,
                'calibrated_active': calibrated is not None,
                'filled_wins': fw, 'filled_losses': fl,
                'filled_total': len(filled_ts),
                'filled_pnl': filled_pnl,
                'filled_wr': round(fw / max(fw+fl, 1) * 100, 1) if (fw+fl) > 0 else None,
                'today_total': len(today_ts), 'today_wins': tw,
                'today_pnl': today_pnl, 'today_wr': today_wr}

    # Per-day × per-conviction breakdown
    def _day_stats():
        day_map: dict = {}
        for t in valid:
            la = t.get('logged_at') or ''
            if not la:
                continue
            # Convert naive Picks timestamps to UTC date (same fix as _type_stats)
            try:
                if la.endswith('+00:00') or la.endswith('Z'):
                    date_str = la[:10]
                else:
                    dt = datetime.fromisoformat(la.replace('Z', '+00:00'))
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=_local_tz)
                    date_str = dt.astimezone(timezone.utc).strftime('%Y-%m-%d')
            except Exception:
                date_str = la[:10]  # fallback to old behavior
            conv = t.get('conviction', 'MEDIUM')
            day_map.setdefault(date_str, {})
            day_map[date_str].setdefault(conv, {'wins': 0, 'losses': 0, 'pnl': 0.0, 'total': 0})
            day_map[date_str].setdefault('_all', {'wins': 0, 'losses': 0, 'pnl': 0.0, 'total': 0})
            for bucket in (day_map[date_str][conv], day_map[date_str]['_all']):
                bucket['total'] += 1
                if t.get('outcome') == 'WIN':
                    bucket['wins'] += 1
                elif t.get('outcome') == 'LOSS':
                    bucket['losses'] += 1
                bucket['pnl'] = round(bucket['pnl'] + (t.get('paper_pnl') or 0), 2)
        # Compute win_rate for each bucket and return sorted newest-first
        for day in day_map.values():
            for bucket in day.values():
                w, l = bucket['wins'], bucket['losses']
                bucket['win_rate'] = round(w / max(w + l, 1) * 100, 1)
        return dict(sorted(day_map.items(), reverse=True))

    # Confirmed-fill totals (only CLOB-verified fills)
    confirmed_all = [t for t in valid if t.get('fill_confirmed') is True and t.get('resolved')]
    confirmed_pnl = round(sum(t.get('paper_pnl') or 0 for t in confirmed_all), 2)
    confirmed_wins   = sum(1 for t in confirmed_all if t.get('outcome') == 'WIN')
    confirmed_losses = sum(1 for t in confirmed_all if t.get('outcome') == 'LOSS')
    pending_fill = sum(1 for t in valid if t.get('real_trade') and t.get('fill_confirmed') is None)

    summary = {
        'total': len(valid),
        'wins': len(wins),
        'losses': len(losses),
        'pending': len(pending),
        'win_rate': round(len(wins) / max(len(wins)+len(losses), 1) * 100, 1),
        'total_pnl': round(total_pnl, 2),
        'confirmed_pnl': confirmed_pnl,
        'confirmed_wins': confirmed_wins,
        'confirmed_losses': confirmed_losses,
        'pending_fill': pending_fill,
        'total_staked': round(sum(t.get('paper_stake', 5.0) for t in resolved), 2),
        'by_conviction': {c: _conv_stats(c) for c in ('EXTREME', 'STRONG', 'HIGH', 'MEDIUM')},
        'by_type': {pt: _type_stats(pt) for pt in ('TIME-LOCK','MOMENTUM','MISPRICED','MANIP','NEAR-CLOSE','VOL-SURGE')},
        'by_day': _day_stats(),
    }
    return jsonify({'trades': trades_sorted[:100], 'summary': summary})


STRATEGY_MODES_FILE = 'claude_strategy_modes.json'
PLAY_TYPES_LIST = ['TIME-LOCK', 'MOMENTUM', 'MISPRICED', 'MANIP', 'NEAR-CLOSE', 'VOL-SURGE']

def _load_modes_file():
    try:
        if os.path.exists(STRATEGY_MODES_FILE):
            with open(STRATEGY_MODES_FILE, 'r') as f:
                saved = json.load(f)
                for pt in PLAY_TYPES_LIST:
                    if pt not in saved:
                        saved[pt] = 'paper'
                return saved
    except Exception:
        pass
    return {pt: 'real' for pt in PLAY_TYPES_LIST}

def _save_modes_file(modes):
    try:
        with open(STRATEGY_MODES_FILE, 'w') as f:
            json.dump(modes, f, indent=2)
    except Exception as e:
        logger.warning(f'[MODES] Save error: {e}')

@app.route('/api/claude-picks-backtest-max')
def api_claude_picks_backtest_max():
    """
    MAX backtest for Claude Picks — mirrors /api/hft-backtest-max but on
    claude_paper_trades.json. Aggregates by play_type (where real_trade is
    set), and produces a cell-level (play_type × symbol × direction × ...)
    drill-down so the operator can see latent winners/bleeders.

    Recommendations:
      PROMOTE LIVE        — avg_pnl >= +$0.50/trade AND n >= 20
      QUARANTINE PAPER    — avg_pnl <= -$0.30/trade AND n >= 20
    Average-PnL-per-trade is the primary signal so it handles both
    high-WR-low-payout (e.g. TIME-LOCK) and low-WR-high-payout (MISPRICED)
    correctly without separate exempt-list logic.
    """
    import datetime as _dt
    try:
        path = os.path.join(os.path.dirname(__file__), 'claude_paper_trades.json')
        with open(path, 'r', encoding='utf-8') as f:
            trades = json.load(f)
    except Exception as e:
        return jsonify({'error': str(e), 'results': []})

    # Resolved subset
    resolved = []
    for t in trades:
        won  = t.get('won')
        outc = t.get('outcome')
        if won is None and outc not in ('WIN', 'LOSS'):
            continue
        correct = bool(won) if won is not None else (outc == 'WIN')
        pnl = t.get('pnl')
        if pnl is None:
            pnl = t.get('paper_pnl', 0)
        try:
            pnl = float(pnl or 0)
        except Exception:
            pnl = 0.0
        resolved.append({**t, '_correct': correct, '_pnl': pnl})
    if len(resolved) < 10:
        return jsonify({'error': 'Need at least 10 resolved Claude Picks trades',
                        'results': [], 'n_total': len(resolved)})

    # Current per-play-type live/paper setting
    try:
        with open(os.path.join(os.path.dirname(__file__), 'claude_strategy_modes.json'),
                  encoding='utf-8') as f:
            modes = json.load(f)
    except Exception:
        modes = {}
    cur_mode = {}
    for k, v in modes.items():
        if k.startswith('_'): continue
        rt = v.get('real_trade') if isinstance(v, dict) else v
        cur_mode[k] = rt

    # ── stats helper ─────────────────────────────────────────────────────────
    def _stats(subset):
        n = len(subset)
        wins = sum(1 for t in subset if t['_correct'])
        wr = wins / n if n else 0
        pnl = sum(t['_pnl'] for t in subset)
        avg = pnl / n if n else 0
        # Sharpe (per-trade std)
        if n > 1:
            mean = avg
            var = sum((t['_pnl'] - mean) ** 2 for t in subset) / n
            std = var ** 0.5
            sharpe = (mean / std) if std > 0 else 0.0
        else:
            sharpe = 0.0
        return {
            'n':         n,
            'wins':      wins,
            'wr':        round(wr * 100, 1),
            'total_pnl': round(pnl, 2),
            'avg_pnl':   round(avg, 3),
            'sharpe':    round(sharpe, 3),
        }

    # ── 1. Per-play_type aggregate (top-level recommendation target) ─────────
    by_play = {}
    for t in resolved:
        play = t.get('play_type') or t.get('strategy', '?')
        by_play.setdefault(play, []).append(t)
    play_type_stats = []
    for play, subset in sorted(by_play.items(), key=lambda kv: -len(kv[1])):
        s = _stats(subset)
        s['play_type'] = play
        s['current_mode'] = cur_mode.get(play, 'paper')
        # paper subset within
        paper = [t for t in subset if not t.get('real_trade')]
        live  = [t for t in subset if t.get('real_trade')]
        s['paper'] = _stats(paper) if paper else None
        s['live']  = _stats(live)  if live  else None
        play_type_stats.append(s)

    # ── 2. Per-(play_type, symbol, direction) cells ──────────────────────────
    cells = []
    by_cell = {}
    for t in resolved:
        play = t.get('play_type') or '?'
        sym  = (t.get('symbol') or '?').upper()
        dir_ = (t.get('direction') or '?').upper()
        by_cell.setdefault((play, sym, dir_), []).append(t)
    for (play, sym, dir_), subset in by_cell.items():
        if len(subset) < 10: continue
        s = _stats(subset)
        s.update({'play_type': play, 'symbol': sym, 'direction': dir_,
                  'combo': f'{play}+{sym}+{dir_}'})
        cells.append(s)
    cells.sort(key=lambda r: -r['total_pnl'])

    # ── 3. Recommendations at the play_type level ────────────────────────────
    recs_promote, recs_quarantine = [], []
    for s in play_type_stats:
        play = s['play_type']
        n = s['n']
        avg = s['avg_pnl']
        cur = cur_mode.get(play, 'paper')
        if n < 20: continue
        if avg >= 0.50 and cur != 'real':
            recs_promote.append({**s, 'recommendation':
                                 f"FLIP {play} -> real (avg ${avg:+.2f}/trade × n={n} = ${s['total_pnl']:+.2f})"})
        elif avg <= -0.30 and cur != 'paper':
            recs_quarantine.append({**s, 'recommendation':
                                    f"FLIP {play} -> paper (avg ${avg:+.2f}/trade × n={n} = ${s['total_pnl']:+.2f})"})
        elif cur == 'real' and avg < 0:
            recs_quarantine.append({**s, 'recommendation':
                                    f"WATCH {play} (currently live, avg ${avg:+.2f}/trade — consider paper if persists)"})

    # ── 4. Cell-level recommendations (within already-live play_types — strongest winners/bleeders) ─
    cell_recs_top, cell_recs_bleeders = [], []
    for c in cells:
        if c['n'] < 15: continue
        avg = c['avg_pnl']
        if avg >= 1.00:
            cell_recs_top.append({**c, 'note':
                                  f"{c['combo']}: avg ${avg:+.2f}/trade × n={c['n']} = ${c['total_pnl']:+.2f} (strong cell)"})
        elif avg <= -0.50:
            cell_recs_bleeders.append({**c, 'note':
                                       f"{c['combo']}: avg ${avg:+.2f}/trade × n={c['n']} = ${c['total_pnl']:+.2f} (bleeding cell)"})
    cell_recs_top.sort(key=lambda r: -r['avg_pnl'])
    cell_recs_bleeders.sort(key=lambda r: r['avg_pnl'])

    # FadeGiga hitrate gate values — for the CRYPTO-AUTO row to render inline tuning controls
    try:
        _hr_gate = {
            'min_n':   int(getattr(prediction_bot, 'HITRATE_LIVE_MIN_N', 20)),
            'min_pct': float(getattr(prediction_bot, 'HITRATE_LIVE_MIN_PCT', 60.0)),
        }
    except Exception:
        _hr_gate = {'min_n': 20, 'min_pct': 60.0}

    # 2026-05-22: RL-blocked cells report (mirrors HFT MAX). Aggregates claude_rl_blocked.json
    # by (play_type, symbol, direction). avg_pnl is counterfactual — what the trade WOULD have
    # made if the RL gate hadn't blocked it.
    _rl_blocked_cells = []
    try:
        _rlb_path = _resolve_state_path('claude_rl_blocked.json')
        if os.path.exists(_rlb_path):
            with open(_rlb_path, 'r', encoding='utf-8') as _f:
                _rlb = json.load(_f)
            _rlb_resolved = [e for e in _rlb
                             if e.get('resolved') and e.get('outcome') in ('WIN','LOSS')
                             and e.get('symbol') and e.get('direction')
                             and (e.get('play_type') or e.get('rl_system'))]
            _by_cell = {}
            for e in _rlb_resolved:
                play = e.get('play_type') or (e.get('rl_system','?').upper())
                k = (play, e['symbol'], e['direction'])
                _by_cell.setdefault(k, []).append(e)
            for (play, sym, d), subset in _by_cell.items():
                if len(subset) < 10: continue
                n = len(subset)
                wins = sum(1 for e in subset if e['outcome'] == 'WIN')
                cf_pnl = sum(float(e.get('shadow_pnl') or 0) for e in subset)
                avg_q = sum(float(e.get('rl_q') or 0) for e in subset) / n
                _rl_blocked_cells.append({
                    'play_type':  play,
                    'symbol':     sym,
                    'direction':  d,
                    'n':          n,
                    'wr':         round(wins / n * 100, 1),
                    'avg_pnl':    round(cf_pnl / n, 3),
                    'total_pnl':  round(cf_pnl, 2),
                    'avg_q':      round(avg_q, 3),
                })
            _rl_blocked_cells.sort(key=lambda c: -c['total_pnl'])
    except Exception as _rlb_err:
        logger.debug(f'[CLAUDE-MAX] rl_blocked aggregation error: {_rlb_err}')

    return jsonify({
        'mode':         'MAX',
        'n_total':      len(resolved),
        'n_play_types': len(play_type_stats),
        'n_cells':      len(cells),
        'play_types':   play_type_stats,
        'cells':        cells[:60],   # top 60 by total_pnl for table render
        'recommendations': {
            'play_type_promote':    recs_promote,
            'play_type_quarantine': recs_quarantine,
            'top_cells':            cell_recs_top[:8],
            'bleeder_cells':        cell_recs_bleeders[:8],
        },
        # Active cell overrides — for UI to render button states
        'cell_overrides':   modes.get('_cell_overrides', {}) or {},
        # FadeGiga hitrate gate — surfaced for the CRYPTO-AUTO row's inline tuner
        'hitrate_gate':     _hr_gate,
        # 2026-05-22: RL-blocked cells (no UNBLOCK button on Claude side yet — visibility only).
        'rl_blocked_cells': _rl_blocked_cells[:40],
    })


@app.route('/api/claude-strategy-modes', methods=['GET', 'POST'])
def api_claude_strategy_modes():
    """GET: return current real/paper mode per play type. POST: update one or all."""
    global claude_scanner
    if request.method == 'GET':
        if claude_scanner is not None:
            return jsonify({
                'modes': claude_scanner.strategy_modes,
                'play_types': claude_scanner.PLAY_TYPES,
                'conviction_threshold': claude_scanner.conviction_threshold,
                'conviction_bets': claude_scanner.conviction_bets,
                'conviction_levels': list(claude_scanner.conviction_levels) if claude_scanner.conviction_levels is not None else None,
            })
        modes_data = _load_modes_file()
        return jsonify({
            'modes': modes_data,
            'play_types': PLAY_TYPES_LIST,
            'conviction_threshold': modes_data.get('_conviction_threshold', 'HIGH'),
            'conviction_bets': modes_data.get('_conviction_bets', {'MEDIUM':1.0,'HIGH':3.0,'STRONG':5.0,'EXTREME':5.0}),
            'conviction_levels': modes_data.get('_conviction_levels'),
        })
    # POST — update mode
    data = request.get_json(force=True) or {}
    if claude_scanner is not None:
        modes = claude_scanner.strategy_modes
        save_fn = claude_scanner._save_strategy_modes
    else:
        modes = _load_modes_file()
        save_fn = lambda: _save_modes_file(modes)
    if 'modes' in data:
        for pt, mode in data['modes'].items():
            if pt in PLAY_TYPES_LIST and mode in ('real', 'paper'):
                modes[pt] = mode
    elif 'conviction_bets' in data:
        try:
            bets = data['conviction_bets']
            updated = {}
            for level in ('MEDIUM', 'HIGH', 'STRONG', 'EXTREME'):
                if level in bets:
                    updated[level] = max(1.0, min(200.0, float(bets[level])))
            modes.setdefault('_conviction_bets', {'MEDIUM':1.0,'HIGH':3.0,'STRONG':5.0,'EXTREME':5.0})
            modes['_conviction_bets'].update(updated)
            if claude_scanner is not None:
                claude_scanner.conviction_bets.update(updated)
                claude_scanner.claude_max_bet = max(claude_scanner.conviction_bets.values())
        except (ValueError, TypeError):
            return jsonify({'error': 'invalid conviction_bets'}), 400
    elif 'conviction_levels' in data:
        valid_levels = {'MEDIUM', 'HIGH', 'STRONG', 'EXTREME'}
        levels = [l for l in data['conviction_levels'] if l in valid_levels]
        modes['_conviction_levels'] = levels
        if claude_scanner is not None:
            claude_scanner.conviction_levels = set(levels)
    elif 'conviction_threshold' in data:
        thresh = data['conviction_threshold']
        if thresh in ('MEDIUM', 'HIGH', 'STRONG', 'EXTREME'):
            modes['_conviction_threshold'] = thresh
            if claude_scanner is not None:
                claude_scanner.conviction_threshold = thresh
        else:
            return jsonify({'error': 'invalid conviction_threshold'}), 400
    elif 'play_type' in data and 'mode' in data:
        pt   = data['play_type']
        mode = data['mode']
        if pt in PLAY_TYPES_LIST and mode in ('real', 'paper'):
            modes[pt] = mode
            if claude_scanner is not None:
                claude_scanner.strategy_modes[pt] = mode
        else:
            return jsonify({'error': 'invalid play_type or mode'}), 400
    save_fn()
    return jsonify({'modes': modes})


@app.route('/api/claude-cell-override', methods=['GET', 'POST', 'DELETE'])
def api_claude_cell_override():
    """Per-(play_type, symbol, direction) override management. Takes precedence
    over the play_type-level real/paper setting in claude_strategy_modes.json
    so the operator can quarantine specific bleeders without paper-ing the whole
    play_type, OR whitelist specific winners inside an otherwise-paper play_type.

    Storage: claude_strategy_modes.json `_cell_overrides` dict keyed by
    "PLAY|SYM|DIR" → 'real' | 'paper'.

    GET    — return current overrides dict.
    POST   — body: {play_type, symbol, direction, mode} where mode ∈ {real, paper}.
    DELETE — body: {play_type, symbol, direction}. Removes the override (cell
             reverts to its play_type-level mode).
    """
    global claude_scanner
    PLAY_TYPES = ('TIME-LOCK','MOMENTUM','MISPRICED','MANIP','NEAR-CLOSE','VOL-SURGE','CRYPTO-AUTO')
    SYMBOLS    = ('BTC','ETH','SOL','XRP','DOGE','HYPE','BNB')
    DIRECTIONS = ('UP','DOWN')

    if claude_scanner is not None:
        modes = claude_scanner.strategy_modes
        save_fn = claude_scanner._save_strategy_modes
    else:
        modes = _load_modes_file()
        save_fn = lambda: _save_modes_file(modes)

    overrides = modes.setdefault('_cell_overrides', {})

    if request.method == 'GET':
        return jsonify({'overrides': overrides})

    data = request.get_json(force=True) or {}
    play = data.get('play_type', '')
    sym  = (data.get('symbol', '') or '').upper()
    dir_ = (data.get('direction', '') or '').upper()
    if play not in PLAY_TYPES:
        return jsonify({'error': f'invalid play_type {play!r}'}), 400
    if sym not in SYMBOLS:
        return jsonify({'error': f'invalid symbol {sym!r}'}), 400
    if dir_ not in DIRECTIONS:
        return jsonify({'error': f'invalid direction {dir_!r}'}), 400
    key = f'{play}|{sym}|{dir_}'

    if request.method == 'DELETE':
        removed = overrides.pop(key, None)
        save_fn()
        return jsonify({'overrides': overrides, 'removed': key, 'previous': removed})

    # POST
    mode = data.get('mode', '')
    if mode not in ('real', 'paper'):
        return jsonify({'error': f'invalid mode {mode!r} — must be real|paper'}), 400
    # 2026-05-23: optional bypass_rl flag — when true, the per-play_type RL gate is
    # skipped for this cell. The Q-table still updates (learning continues).
    _bypass_rl = bool(data.get('bypass_rl', False))
    if _bypass_rl:
        overrides[key] = {'mode': mode, 'bypass_rl': True}
    else:
        overrides[key] = mode
    save_fn()
    return jsonify({'overrides': overrides, 'set': {key: overrides[key]}})


@app.route('/api/hft-cell-override', methods=['GET', 'POST', 'DELETE'])
def api_hft_cell_override():
    """Per-(symbol, direction, strategy) override management for HFT lab.
    Mirrors /api/claude-cell-override. Takes precedence over the
    dimension-level paper_symbols / paper_strategies / paper_directions lists
    in hft_settings.json — lets the operator whitelist a profitable cell
    inside an otherwise-papered symbol, or quarantine a single bleeding cell
    without papering the whole strategy.

    Storage: hft_settings.json `cell_overrides` dict keyed by
    "SYM|DIR|STRAT" → 'real' | 'paper'.

    GET    — return current overrides dict.
    POST   — body: {symbol, direction, strategy, mode} where mode ∈ {real, paper}.
    DELETE — body: {symbol, direction, strategy}. Removes the override (cell
             reverts to dimension-level behavior).
    """
    global hft_scanner
    # Symbols and directions follow the bot's standard set. Strategies are
    # whatever the HFT scanner emits — extendable; validate only the structural
    # shape, not a closed enum, so new strategies aren't blocked.
    SYMBOLS    = ('BTC','ETH','SOL','XRP','DOGE','HYPE','BNB')
    DIRECTIONS = ('UP','DOWN')

    if hft_scanner is None:
        return jsonify({'error': 'HFT scanner not initialized'}), 503

    overrides = hft_scanner.cell_overrides

    if request.method == 'GET':
        return jsonify({'overrides': overrides})

    data = request.get_json(force=True) or {}
    sym  = (data.get('symbol', '') or '').upper()
    dir_ = (data.get('direction', '') or '').upper()
    strat = (data.get('strategy', '') or '').upper()
    if sym not in SYMBOLS:
        return jsonify({'error': f'invalid symbol {sym!r}'}), 400
    if dir_ not in DIRECTIONS:
        return jsonify({'error': f'invalid direction {dir_!r}'}), 400
    if not strat or len(strat) > 64:
        return jsonify({'error': f'invalid strategy {strat!r}'}), 400
    key = f'{sym}|{dir_}|{strat}'

    if request.method == 'DELETE':
        removed = overrides.pop(key, None)
        hft_scanner._save_settings()
        return jsonify({'overrides': overrides, 'removed': key, 'previous': removed})

    # POST
    mode = data.get('mode', '')
    if mode not in ('real', 'paper'):
        return jsonify({'error': f'invalid mode {mode!r} — must be real|paper'}), 400
    # 2026-05-22: optional filters {hour, session, timeframe, price, secs}.
    # If supplied, the override mode only applies when ALL filters match the live signal context.
    # Each filter value may be a string or a list of allowed values.
    _filters = data.get('filters') or {}
    _ALLOWED_FILTER_KEYS = {'hour', 'session', 'timeframe', 'price', 'secs'}
    if _filters and not isinstance(_filters, dict):
        return jsonify({'error': 'filters must be an object'}), 400
    _clean_filters = {}
    for fk, fv in (_filters or {}).items():
        if fk not in _ALLOWED_FILTER_KEYS:
            return jsonify({'error': f'invalid filter key {fk!r}; allowed: {sorted(_ALLOWED_FILTER_KEYS)}'}), 400
        # Normalize: store as string or list-of-strings; reject non-string scalars.
        if isinstance(fv, (list, tuple)):
            _clean_filters[fk] = [str(x) for x in fv]
        elif isinstance(fv, str):
            _clean_filters[fk] = fv
        else:
            return jsonify({'error': f'filter {fk!r} must be string or list of strings'}), 400
    # 2026-05-22: bypass_rl — when True, this cell skips the RL gate check. The Q-table
    # still updates from outcomes (learning continues). Use to unblock cells the RL has
    # over-suppressed (positive counterfactual PnL in the RL-blocked report).
    _bypass_rl = bool(data.get('bypass_rl', False))
    if _clean_filters or _bypass_rl:
        _val = {'mode': mode, **_clean_filters}
        if _bypass_rl:
            _val['bypass_rl'] = True
        overrides[key] = _val
    else:
        overrides[key] = mode  # bare-string form for back-compat
    hft_scanner._save_settings()
    return jsonify({'overrides': overrides, 'set': {key: overrides[key]}})


@app.route('/api/hitrate-gate-config', methods=['GET', 'POST'])
def api_hitrate_gate_config():
    """Read or update the FadeGiga symbol-level hitrate gate thresholds at runtime.
    These control when a symbol qualifies for live trading (see _hitrate_allows_live
    around line 3596). Lowering the thresholds lets more FadeGiga AUTO-BUY signals
    go live — useful when the MAX backtest shows CRYPTO-AUTO (the paper-bucket
    label for gate-blocked signals) has positive paper EV.

    Bounded by 5 <= min_n <= 100 and 40.0 <= min_pct <= 80.0 to prevent footguns.

    GET  — return current values.
    POST — body: {min_n?, min_pct?, preset?}. preset='loosen' drops both by 5/5;
           preset='reset' restores defaults (20, 60.0).
    """
    global prediction_bot
    bot = prediction_bot
    if bot is None:
        return jsonify({'error': 'bot not initialized'}), 503

    if request.method == 'GET':
        return jsonify({
            'min_n':   int(bot.HITRATE_LIVE_MIN_N),
            'min_pct': float(bot.HITRATE_LIVE_MIN_PCT),
            'defaults': {'min_n': 20, 'min_pct': 60.0},
            'bounds':  {'min_n': [5, 100], 'min_pct': [40.0, 80.0]},
        })

    data = request.get_json(force=True) or {}
    cur_n   = int(bot.HITRATE_LIVE_MIN_N)
    cur_pct = float(bot.HITRATE_LIVE_MIN_PCT)
    preset  = data.get('preset')
    if preset == 'loosen':
        new_n   = max(5,   cur_n   - 5)
        new_pct = max(40.0, cur_pct - 5.0)
    elif preset == 'tighten':
        new_n   = min(100,  cur_n   + 5)
        new_pct = min(80.0, cur_pct + 5.0)
    elif preset == 'reset':
        new_n   = 20
        new_pct = 60.0
    else:
        try:
            new_n   = int(data.get('min_n',   cur_n))
            new_pct = float(data.get('min_pct', cur_pct))
        except (TypeError, ValueError):
            return jsonify({'error': 'invalid min_n/min_pct'}), 400
        # Bounds
        new_n   = max(5,   min(100,  new_n))
        new_pct = max(40.0, min(80.0, new_pct))

    bot.HITRATE_LIVE_MIN_N   = new_n
    bot.HITRATE_LIVE_MIN_PCT = new_pct
    try:
        bot.save_config()
    except Exception as e:
        logger.warning(f'[HR-GATE] save_config error: {e}')
    logger.info(f'[HR-GATE] thresholds updated: n>={new_n} wr>={new_pct}% (was n>={cur_n} wr>={cur_pct}%)')
    return jsonify({
        'min_n':   new_n,
        'min_pct': new_pct,
        'previous': {'min_n': cur_n, 'min_pct': cur_pct},
    })


@app.route('/api/claude-picks/buy', methods=['POST'])
def api_claude_picks_buy():
    """
    Direct token buy for Claude Picks (works for any Polymarket market,
    not just crypto updown).  Accepts JSON:
      { token_id, direction, title, ask, slug, condition_id, amount_usd (opt) }
    Places a FOK (Fill or Kill) market order at the ask and records the position for tracking.
    """
    global prediction_bot
    if not prediction_bot:
        return jsonify({'success': False, 'error': 'Bot not initialized'})
    data = request.get_json(force=True) or {}
    token_id    = data.get('token_id', '')
    direction   = data.get('direction', 'YES')
    title       = data.get('title', data.get('symbol', 'Event'))
    scan_ask    = float(data.get('ask', 0))   # price shown to user on picks page
    ask         = scan_ask                     # will be updated to live ask below
    slug        = data.get('slug', '')
    condition_id = data.get('condition_id', '')
    amount_usd  = float(data.get('amount_usd', 5.0))
    play_type   = (data.get('play_type') or '').upper()
    conviction  = (data.get('conviction') or 'MEDIUM').upper()

    if not token_id:
        return jsonify({'success': False, 'error': 'token_id is required'})
    if not prediction_bot.clob_client:
        return jsonify({'success': False, 'error': 'CLOB client not connected'})

    # 2026-05-21: server-side enforcement of UI slider cap (defense-in-depth).
    # The UI button computes amount from conviction_bets, but anyone hitting this
    # endpoint directly (custom client, replay, bug) could send any size. Cap
    # amount_usd against the configured slider for this conviction; for
    # NEAR-CLOSE / MANIP apply the same hard $3 cap the scanner uses.
    try:
        if claude_scanner is not None:
            _conv_bets = getattr(claude_scanner, 'conviction_bets', {}) or {}
            _slider_cap = float(_conv_bets.get(conviction,
                                               max(_conv_bets.values()) if _conv_bets else amount_usd))
        else:
            _slider_cap = amount_usd
        if play_type in ('NEAR-CLOSE', 'MANIP'):
            _effective_cap = min(_slider_cap, 3.0)
        else:
            _effective_cap = _slider_cap
        if amount_usd > _effective_cap + 1e-6:
            logger.warning(f"[CLAUDE-BUY] amount_usd ${amount_usd:.2f} exceeds cap "
                           f"${_effective_cap:.2f} (play_type={play_type} conv={conviction}) — capping")
            amount_usd = _effective_cap
    except Exception as _cap_err:
        logger.warning(f"[CLAUDE-BUY] cap check failed: {_cap_err} — using requested amount")

    # Fetch live ask for order placement — but keep scan_ask as the true entry price
    # (illiquid CLOB books often show 0.99 ask while Polymarket AMM fills at fair value)
    try:
        book = prediction_bot.clob_client.get_order_book(token_id)
        if book and hasattr(book, 'asks') and book.asks:
            live_ask = float(book.asks[0].price)
            logger.info(f"[CLAUDE-BUY] Live ask={live_ask:.4f} (scan ask={scan_ask:.4f}) for {token_id[:12]}")
            ask = live_ask
    except Exception as e:
        logger.warning(f"[CLAUDE-BUY] Could not fetch live ask, falling back to scan price: {e}")
        if not ask or ask <= 0:
            return jsonify({'success': False, 'error': 'No ask price available'})

    if not ask or ask <= 0:
        return jsonify({'success': False, 'error': 'Could not determine ask price'})

    # Round price to 2dp and size using maker-amount rules — same as diagnostic path
    rounded_price = prediction_bot.round_price(ask)
    size = amount_usd / rounded_price if rounded_price > 0 else amount_usd / ask
    size = prediction_bot.round_maker_size(rounded_price, size)
    size = prediction_bot._validate_size(size, rounded_price, title[:20])

    try:
        from py_clob_client_v2.clob_types import OrderArgs, OrderType
        ok, result, order_id = prediction_bot._safe_create_and_post(
            token_id=token_id,
            price=rounded_price,
            size=size,
            side='BUY',
            order_type=OrderType.GTC,
            symbol=title[:20]
        )
        if not ok:
            return jsonify({'success': False, 'error': str(result)})

        # Record in predictions for tracking
        sym_label = title[:20].upper()
        _now_local = datetime.now()
        # market_end_time — parsed from slug. Without this the CLAUDE-* expiry
        # resolver at line 6492 never marks the prediction EXPIRED.
        _market_end_iso = None
        try:
            import re as _re
            _m = _re.match(r'^[a-z]+-updown-(5m|15m)-(\d+)$', slug or '', _re.IGNORECASE)
            if _m:
                _tf_secs = 300 if _m.group(1).lower() == '5m' else 900
                _end_ts = int(_m.group(2)) + _tf_secs
                _market_end_iso = datetime.fromtimestamp(_end_ts, tz=timezone.utc).isoformat()
        except Exception:
            _market_end_iso = None
        pred_record = {
            'id': str(int(_now_local.timestamp() * 1000)),
            'timestamp': _now_local.isoformat(),
            'symbol': sym_label,
            'timeframe': data.get('timeframe', 'open'),
            'signal': 'BULLISH',
            'confidence': int(float(data.get('prob', 80))),
            'strategy': f'CLAUDE-{data.get("play_type","PICKS")}',
            'price': rounded_price,
            'size': size,
            'cost': round(size * rounded_price, 4),
            'order_id': order_id,
            'entry_price': scan_ask if scan_ask > 0 else rounded_price,
            'is_100_confidence': False,
            'outcome_checked': False,
            'was_correct': None,
            'final_price': None,
            'token_id': token_id,
            'condition_id': condition_id,
            'bought_outcome': direction.lower() if direction.lower() in ('up','down') else 'up',
            'current_yes_price': None,
            'current_no_price': None,
            'potential_profit': None,
            'signal_bar_cycle': 0,
            'title': title,
            'slug': slug,
            'market_end_time': _market_end_iso,
        }
        prediction_bot.predictions.append(pred_record)
        prediction_bot.save_predictions()
        entry_display = scan_ask if scan_ask > 0 else rounded_price
        logger.info(f"[CLAUDE-BUY] {sym_label} {direction} entry={entry_display:.4f} order_price={rounded_price:.4f} × {size:.2f} | order={order_id}")
        prediction_bot._tg_notify(
            f'CLAUDE PICK {direction}  <b>[{data.get("conviction","")}]</b>\n'
            f'<b>{sym_label}</b>  ${amount_usd:.2f} @ ${entry_display:.4f}\n'
            f'{data.get("play_type","PICK")}'
            f'{prediction_bot._pm_link(slug)}'
        )
        return jsonify({'success': True, 'order_id': order_id, 'size': round(size, 4), 'price': round(entry_display, 4)})
    except Exception as e:
        logger.error(f"[CLAUDE-BUY] Error: {e}")
        return jsonify({'success': False, 'error': str(e)})


@app.route('/api/algo-hitrates')
def get_algo_hitrates():
    """Return live hit rates per symbol+strategy+timeframe from bot_predictions."""
    pred_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'bot_predictions.json')
    result = {}
    preds = _load_json_cached(pred_file, default=None)
    if not isinstance(preds, list):
        return jsonify(result)
    try:
        resolved = [p for p in preds if p.get('outcome_checked')]
        from collections import defaultdict
        stats = defaultdict(lambda: {'w': 0, 't': 0})
        for p in resolved:
            sym   = (p.get('symbol') or '').upper()
            strat = p.get('strategy') or ''
            tf    = p.get('timeframe') or ''
            if not sym or not strat or not tf:
                continue
            key = f'{sym}|{strat}|{tf}'
            stats[key]['t'] += 1
            if p.get('was_correct'):
                stats[key]['w'] += 1
        for key, d in stats.items():
            sym, strat, tf = key.split('|', 2)
            wr = round(100 * d['w'] / d['t'], 1) if d['t'] else 0
            result.setdefault(sym, {}).setdefault(tf, {})[strat] = {
                'win_rate': wr,
                'wins':     d['w'],
                'total':    d['t'],
            }
    except Exception as e:
        logger.warning(f'[ALGO-HITRATES] {e}')
    return jsonify(result)


@app.route('/api/algo-assignments')
def get_algo_assignments():
    """Return built-in + custom algo assignments, best win rates per symbol, and saved algos list."""
    # Custom assignments from file (mtime-cached)
    custom = _load_json_cached(ALGO_ASSIGNMENTS_FILE, default={}) or {}
    if not isinstance(custom, dict):
        custom = {}

    # Win rates from last max backtest (mtime-cached)
    winrates = {}
    winners  = []
    bt_meta  = None
    bt_file  = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'max_backtest_results.json')
    bt_data  = _load_json_cached(bt_file, default=None)
    if bt_data:
        try:
            all_results = bt_data.get('all', [])
            winners     = bt_data.get('winners', [])
            ts          = bt_data.get('timestamp', '')
            bt_meta     = {
                'date': ts[:10] + ' ' + ts[11:19] if len(ts) > 10 else ts,
                'days': bt_data.get('days', '?'),
                'total_results': len(all_results),
                'winners': len(winners),
            }
            # Best result per symbol (winners only, sorted by WR desc)
            for r in sorted(winners, key=lambda x: (x.get('win_rate', 0), x.get('ev', 0)), reverse=True):
                sym = r.get('symbol')
                if sym and sym not in winrates:
                    winrates[sym] = {
                        'win_rate': r.get('win_rate', 0),
                        'algo_name': r.get('algo_name', ''),
                        'tf': r.get('tf', ''),
                        'total': r.get('total', 0),
                        'ev': r.get('ev', 0),
                    }
        except Exception as e:
            logger.warning(f"[ALGO-DISPLAY] Could not read backtest results: {e}")

    # Saved algos (mtime-cached)
    saved_algos = {}
    algos = _load_json_cached(ALGOS_FILE, default=None)
    if isinstance(algos, dict):
        saved_algos = {id_: {'name': a.get('name', id_), 'id': id_}
                       for id_, a in algos.items() if isinstance(a, dict) and a.get('code')}

    # Live hit rates per symbol+tf+algo from bot_predictions
    # Key by sub_strategy when set (matches algo chip names like DogeV1, GigaV35)
    # Falls back to strategy name
    hitrates = {}
    pred_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'bot_predictions.json')
    preds = _load_json_cached(pred_file, default=None)
    if isinstance(preds, list):
        try:
            from collections import defaultdict as _dd
            _stats = _dd(lambda: {'w': 0, 't': 0})
            for p in preds:
                if not p.get('outcome_checked'):
                    continue
                sym  = (p.get('symbol') or '').upper()
                tf   = p.get('timeframe') or ''
                sub  = p.get('sub_strategy') or ''
                strat = p.get('strategy') or ''
                # Use sub_strategy as key when available — maps directly to chip names
                name = sub if sub else strat
                if not sym or not name or not tf:
                    continue
                for k in [f'{sym}|{name}|{tf}']:
                    _stats[k]['t'] += 1
                    if p.get('was_correct'):
                        _stats[k]['w'] += 1
                # Also index by strategy name for fallback lookup
                if sub and strat and sub != strat:
                    k2 = f'{sym}|{strat}|{tf}'
                    _stats[k2]['t'] += 1
                    if p.get('was_correct'):
                        _stats[k2]['w'] += 1
            for k, d in _stats.items():
                sym, name, tf = k.split('|', 2)
                wr = round(100 * d['w'] / d['t'], 1) if d['t'] else 0
                hitrates.setdefault(sym, {}).setdefault(tf, {})[name] = {
                    'win_rate': wr, 'wins': d['w'], 'total': d['t'],
                }
        except Exception as _hr_err:
            logger.debug(f'[ALGO-DISPLAY] hitrates: {_hr_err}')

    # Build all_tfs: combined chip list per symbol across both timeframes.
    # Also include any sub_strategy that has fired (per hitrates) but isn't in
    # BUILTIN_ALGO_ASSIGNMENTS — handles fallback algos like BB-Extreme that
    # fire universally but were only listed for one symbol.
    all_tfs = {}
    all_syms = set(list(BUILTIN_ALGO_ASSIGNMENTS.keys()) + list(custom.keys()) + list(hitrates.keys()))
    for sym in all_syms:
        entries = []
        seen = set()  # (name, tf) dedupe
        for tf in ('15m', '5m'):
            for name in (BUILTIN_ALGO_ASSIGNMENTS.get(sym) or {}).get(tf) or []:
                entries.append({'name': name, 'tf': tf, 'type': 'builtin'})
                seen.add((name, tf))
            for name in (custom.get(sym) or {}).get(tf) or []:
                if (name, tf) not in seen:
                    entries.append({'name': name, 'tf': tf, 'type': 'custom'})
                    seen.add((name, tf))
            # Auto-extend: any algo with live hitrates but not yet listed
            for name in (hitrates.get(sym) or {}).get(tf) or {}:
                if (name, tf) not in seen and name and not name.startswith('CLAUDE-'):
                    entries.append({'name': name, 'tf': tf, 'type': 'builtin'})
                    seen.add((name, tf))
        all_tfs[sym] = entries

    return jsonify({
        'builtin':     BUILTIN_ALGO_ASSIGNMENTS,
        'custom':      custom,
        'all_tfs':     all_tfs,
        'winrates':    winrates,
        'winners':     winners,
        'saved_algos': saved_algos,
        'bt_meta':     bt_meta,
        'hitrates':    hitrates,
    })


@app.route('/api/algo-assignments/add', methods=['POST'])
def add_algo_assignment():
    """Add a custom algo assignment to a symbol+timeframe."""
    body    = request.json or {}
    symbol  = body.get('symbol', '').upper()
    tf      = body.get('tf', '15m')
    algo_id = body.get('algo_id', '')
    algo_name = body.get('algo_name', algo_id)

    if symbol not in ['BTC','ETH','SOL','XRP','DOGE','HYPE','BNB']:
        return jsonify({'success': False, 'error': 'Invalid symbol'})
    if tf not in ('15m', '5m'):
        return jsonify({'success': False, 'error': 'Invalid timeframe'})
    if not algo_id:
        return jsonify({'success': False, 'error': 'No algo selected'})

    custom = {}
    if os.path.exists(ALGO_ASSIGNMENTS_FILE):
        try:
            with open(ALGO_ASSIGNMENTS_FILE, 'r', encoding='utf-8') as f:
                custom = json.load(f)
        except Exception:
            custom = {}

    custom.setdefault(symbol, {}).setdefault(tf, [])
    if algo_name not in custom[symbol][tf]:
        custom[symbol][tf].append(algo_name)

    try:
        with open(ALGO_ASSIGNMENTS_FILE, 'w', encoding='utf-8') as f:
            json.dump(custom, f, indent=2, ensure_ascii=False)
        return jsonify({'success': True})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)})


@app.route('/api/algo-assignments/remove', methods=['POST'])
def remove_algo_assignment():
    """Remove a custom algo assignment from a symbol+timeframe."""
    body      = request.json or {}
    symbol    = body.get('symbol', '').upper()
    tf        = body.get('tf', '15m')
    algo_name = body.get('algo_name', '')

    if not os.path.exists(ALGO_ASSIGNMENTS_FILE):
        return jsonify({'success': False, 'error': 'No custom assignments file'})

    try:
        with open(ALGO_ASSIGNMENTS_FILE, 'r', encoding='utf-8') as f:
            custom = json.load(f)
        lst = custom.get(symbol, {}).get(tf, [])
        if algo_name in lst:
            lst.remove(algo_name)
        with open(ALGO_ASSIGNMENTS_FILE, 'w', encoding='utf-8') as f:
            json.dump(custom, f, indent=2, ensure_ascii=False)
        return jsonify({'success': True})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)})


