@app.route('/api/predict/<symbol>', methods=['POST'])
def predict(symbol):
    global prediction_bot
    if not prediction_bot:
        return jsonify({'error': 'Bot not initialized'})
    auto_trade  = request.json.get('auto_trade', False)
    force_trade = request.json.get('force_trade', False)
    timeframe   = request.json.get('timeframe', '15m')
    symbol = symbol.upper()

    if timeframe == '5m':
        # Use 5m analysis and 5m market
        try:
            candles = prediction_bot.data_fetcher.get_5min_candles(symbol, num_candles=300)
            if not candles:
                return jsonify({'success': False, 'error': 'No 5m candle data'})

            # Pick correct 5m analyzer
            if symbol == 'BNB':
                analysis = {'signal': 'NEUTRAL', 'confidence': 0, 'indicators': {}, 'reasons': ['No algo assigned'], 'chart_data': {}}
            elif symbol == 'BTC':
                analysis = prediction_bot.fade_giga_analyzer.analyze_doge_v1(candles, symbol)
            elif symbol == 'ETH':
                a = prediction_bot.eth_5m_analyzer.analyze(candles, symbol)
                if a['signal'] == 'NEUTRAL':
                    a = prediction_bot.eth_5m_sol_analyzer.analyze(candles, symbol)
                analysis = a
            elif symbol == 'SOL':
                a = prediction_bot.sol_5m_analyzer.analyze(candles, symbol)
                if a['signal'] == 'NEUTRAL':
                    a = prediction_bot.fade_giga_analyzer.analyze(candles, symbol)
                analysis = a
            else:
                analysis = prediction_bot.fade_giga_analyzer.analyze(candles, symbol)

            analysis['timeframe'] = '5m'

            # Find 5m market
            next_5m = prediction_bot.get_current_5min_timestamp() + 300
            market  = prediction_bot.find_5min_market(symbol, target_timestamp=next_5m)
            if not market and force_trade:
                return jsonify({'success': False, 'error': f'No 5m market found for {symbol}'})

            result = prediction_bot.place_prediction_fast(symbol, analysis, target_cycle=next_5m)
            return jsonify(result)
        except Exception as e:
            logger.error(f"5m predict error {symbol}: {e}")
            return jsonify({'success': False, 'error': str(e)})
    else:
        result = prediction_bot.place_prediction(symbol, auto_trade, force_trade)
        return jsonify(result)


