@app.route('/api/daily-pnl')
def api_daily_pnl():
    """Today's full PnL (paper + filled) across all 4 scanners.
    Used by dashboards to display a unified daily-PnL widget."""
    global hft_scanner, btc_ml_scanner, eth_ml_scanner, claude_scanner
    today = datetime.now(timezone.utc).strftime('%Y-%m-%d')
    out = {'date_utc': today, 'scanners': {}}
    total_pnl = 0.0
    total_n = 0

    def _scan_today(scanner, label):
        if scanner is None: return None
        # ClaudeScanner (Picks) doesn't keep _trades in memory — load from disk.
        if label == 'Picks':
            try:
                if hasattr(scanner, '_load_paper_log'):
                    trades = scanner._load_paper_log()
                else:
                    return None
            except Exception:
                return None
        else:
            try:
                with scanner._lock:
                    trades = list(scanner._trades)
            except Exception:
                return None
        # Date-match logic: HFT/BTC-ML/ETH-ML write UTC-aware ISO timestamps so
        # `.startswith(today_utc)` works directly. Picks writes NAIVE local-time
        # timestamps via datetime.now().isoformat() — those need to be parsed,
        # interpreted as local TZ, converted to UTC, and then date-compared.
        # Without this, between local-midnight and UTC-midnight (e.g. 5pm-midnight
        # PT) the Picks "today" bucket reads $0.
        _local_tz = datetime.now().astimezone().tzinfo
        def _is_today_utc(t):
            la = t.get('logged_at') or ''
            if not la: return False
            # Fast path — TZ-aware ISO already starts with UTC date string.
            if la.endswith('+00:00') or la.endswith('Z'):
                return la.startswith(today)
            try:
                dt = datetime.fromisoformat(la.replace('Z', '+00:00'))
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=_local_tz)  # naive -> local
                return dt.astimezone(timezone.utc).strftime('%Y-%m-%d') == today
            except Exception:
                return la.startswith(today)  # fall back to old behavior
        rs = [t for t in trades if t.get('resolved')
              and t.get('outcome') in ('WIN','LOSS')
              and _is_today_utc(t)]
        wins = sum(1 for t in rs if t.get('outcome') == 'WIN')
        pnl  = round(sum(t.get('pnl') or t.get('paper_pnl') or 0 for t in rs), 2)
        wr   = round(wins / max(len(rs), 1) * 100, 1)
        # Real-money split (live trades only)
        real = [t for t in rs if t.get('real_trade')]
        real_pnl = round(sum(t.get('pnl') or t.get('paper_pnl') or 0 for t in real), 2)
        return {'resolved': len(rs), 'wins': wins, 'wr': wr, 'pnl': pnl,
                'real_n': len(real), 'real_pnl': real_pnl}

    for label, scanner in (('HFT', hft_scanner), ('BTC-ML', btc_ml_scanner),
                            ('ETH-ML', eth_ml_scanner), ('Picks', claude_scanner)):
        s = _scan_today(scanner, label)
        if s is not None:
            out['scanners'][label] = s
            total_pnl += s['pnl']
            total_n   += s['resolved']

    out['total_pnl'] = round(total_pnl, 2)
    out['total_resolved'] = total_n
    return jsonify(out)


