@app.route('/api/redemptions/trigger', methods=['POST'])
def trigger_redemption():
    """Manually trigger pending redemptions immediately"""
    global prediction_bot
    if not prediction_bot:
        return jsonify({'error': 'Bot not initialized'})

    # Force check all pending redemptions now
    pending_before = len([r for r in prediction_bot.pending_redemptions if r['status'] == 'pending'])

    for redemption in prediction_bot.pending_redemptions:
        if redemption['status'] == 'pending':
            redemption['scheduled_time'] = datetime.now() - timedelta(minutes=1)  # Make it due now

    prediction_bot.check_pending_redemptions()

    pending_after = len([r for r in prediction_bot.pending_redemptions if r['status'] == 'pending'])
    processed = pending_before - pending_after

    return jsonify({
        'success': True,
        'message': f'Triggered {processed} redemption(s)',
        'processed': processed
    })


