@app.route('/api/open-positions', methods=['GET'])
def get_open_positions():
    """Get all open positions that can be sold"""
    global prediction_bot
    if not prediction_bot:
        return jsonify({'error': 'Bot not initialized'})

    open_positions = []
    for pred in prediction_bot.predictions:
        if not pred.get('outcome_checked', False) and pred.get('token_id'):
            entry_price = pred.get('price', 0)
            current_price = None
            bought_outcome = pred.get('bought_outcome', '').lower()

            if bought_outcome == 'up':
                current_price = pred.get('current_yes_price')
            else:
                current_price = pred.get('current_no_price')

            pnl_pct = ((current_price - entry_price) / entry_price) * 100 if current_price and entry_price > 0 else 0

            open_positions.append({
                'symbol': pred.get('symbol'),
                'signal': pred.get('signal'),
                'bought_outcome': pred.get('bought_outcome'),
                'entry_price': entry_price,
                'current_price': current_price,
                'pnl_pct': round(pnl_pct, 2),
                'size': pred.get('size'),
                'cost': pred.get('cost'),
                'token_id': pred.get('token_id'),
                'timestamp': pred.get('timestamp'),
                'market': pred.get('market')
            })

    return jsonify({'positions': open_positions})


@app.route('/api/stop-loss/status', methods=['GET'])
def get_stop_loss_status():
    """Get stop-loss status for all open positions"""
    global prediction_bot
    if not prediction_bot:
        return jsonify({'error': 'Bot not initialized'})

    positions_status = []
    for pred in prediction_bot.predictions:
        # Only include open positions (not yet resolved)
        if pred.get('outcome_checked', False):
            continue

        entry_price = pred.get('price', 0)
        current_price = None
        bought_outcome = pred.get('bought_outcome', '').lower()

        if bought_outcome == 'up':
            current_price = pred.get('current_yes_price')
        else:
            current_price = pred.get('current_no_price')

        if entry_price > 0 and current_price:
            pnl_pct = ((current_price - entry_price) / entry_price) * 100
            triggered = pnl_pct <= -prediction_bot.stop_loss_pct
        else:
            pnl_pct = 0
            triggered = False

        positions_status.append({
            'symbol': pred.get('symbol'),
            'signal': pred.get('signal'),
            'entry_price': entry_price,
            'current_price': current_price,
            'pnl_pct': round(pnl_pct, 2) if current_price else None,
            'stop_loss_triggered': triggered,
            'token_id': pred.get('token_id'),
            'size': pred.get('size'),
            'cost': pred.get('cost')
        })

    return jsonify({
        'enabled': prediction_bot.stop_loss_enabled,
        'stop_loss_pct': prediction_bot.stop_loss_pct,
        'positions': positions_status
    })


@app.route('/api/diagnose-buy/<symbol>', methods=['POST'])
def diagnose_buy(symbol):
    """Diagnostic $2 buy to test order placement for a symbol"""
    global prediction_bot
    if not prediction_bot:
        return jsonify({'success': False, 'error': 'Bot not initialized'})

    try:
        symbol = symbol.upper()
        if symbol not in ['BTC', 'ETH', 'SOL', 'XRP', 'DOGE', 'HYPE', 'BNB']:
            return jsonify({'success': False, 'error': f'Invalid symbol: {symbol}'})

        body = request.json or {}
        timeframe = body.get('timeframe', '15m')

        logger.info(f"[DIAGNOSE] Starting diagnostic $2 buy for {symbol} [{timeframe}]")

        if timeframe == '5m':
            # ── 5-minute path ──────────────────────────────────────────
            candles = prediction_bot.data_fetcher.get_5min_candles(symbol, num_candles=300)
            if not candles:
                return jsonify({'success': False, 'error': 'No 5m candle data available'})

            if symbol == 'BNB':
                analysis = {'signal': 'NEUTRAL', 'confidence': 0, 'indicators': {}, 'reasons': ['No algo assigned'], 'chart_data': {}}
            elif symbol == 'BTC':
                analysis = prediction_bot.fade_giga_analyzer.analyze_doge_v1(candles, symbol)
            elif symbol == 'ETH':
                a = prediction_bot.eth_5m_analyzer.analyze(candles, symbol)
                if a['signal'] == 'NEUTRAL':
                    a = prediction_bot.eth_5m_sol_analyzer.analyze(candles, symbol)
                analysis = a
            elif symbol == 'SOL':
                a = prediction_bot.sol_5m_analyzer.analyze(candles, symbol)
                if a['signal'] == 'NEUTRAL':
                    a = prediction_bot.fade_giga_analyzer.analyze(candles, symbol)
                analysis = a
            else:
                analysis = prediction_bot.fade_giga_analyzer.analyze(candles, symbol)

            analysis['timeframe'] = '5m'

            if analysis['signal'] == 'NEUTRAL':
                logger.info(f"[DIAGNOSE] Signal is NEUTRAL, forcing BULLISH for diagnostic test")
                analysis['signal'] = 'BULLISH'
                analysis['confidence'] = 60

            next_5m = prediction_bot.get_current_5min_timestamp() + 300
            original_size = prediction_bot.position_size_usd
            prediction_bot.position_size_usd = 2.0
            logger.info(f"[DIAGNOSE] Attempting $2 {analysis['signal']} 5m order for {symbol}")
            result = prediction_bot.place_prediction_fast(symbol, analysis, target_cycle=next_5m)
            prediction_bot.position_size_usd = original_size
        else:
            # ── 15-minute path ─────────────────────────────────────────
            data = prediction_bot.get_analysis(symbol)
            if 'error' in data:
                return jsonify({'success': False, 'error': data['error']})

            analysis = data['analysis']

            if analysis['signal'] == 'NEUTRAL':
                logger.info(f"[DIAGNOSE] Signal is NEUTRAL, forcing BULLISH for diagnostic test")
                analysis['signal'] = 'BULLISH'
                analysis['confidence'] = 60

            original_size = prediction_bot.position_size_usd
            prediction_bot.position_size_usd = 2.0
            logger.info(f"[DIAGNOSE] Attempting $2 {analysis['signal']} 15m order for {symbol}")
            result = prediction_bot.place_prediction(symbol, auto_trade=True, force_trade=True)
            prediction_bot.position_size_usd = original_size

        if result.get('success'):
            logger.info(f"[DIAGNOSE] Success! Order placed: {result.get('order_id')}")
            return jsonify({
                'success': True,
                'message': f'Diagnostic buy successful for {symbol} [{timeframe}]',
                'order_id': result.get('order_id'),
                'signal': analysis['signal'],
                'timeframe': timeframe,
                'price': result.get('analysis', {}).get('current_price'),
                'market': result.get('market')
            })
        else:
            error_msg = result.get('error') or result.get('message', 'Unknown error')
            logger.error(f"[DIAGNOSE] Failed: {error_msg}")
            return jsonify({'success': False, 'error': error_msg})

    except Exception as e:
        logger.error(f"[DIAGNOSE] Exception: {e}")
        return jsonify({'success': False, 'error': str(e)})


@app.route('/api/test-limit-buy/<symbol>', methods=['POST'])
def test_limit_buy(symbol):
    """Test LIMIT order at $0.50 per share for NEXT 15-min session"""
    global prediction_bot
    if not prediction_bot:
        return jsonify({'success': False, 'error': 'Bot not initialized'})

    try:
        symbol = symbol.upper()
        if symbol not in ['BTC', 'ETH', 'SOL', 'XRP', 'DOGE', 'HYPE', 'BNB']:
            return jsonify({'success': False, 'error': f'Invalid symbol: {symbol}'})

        body = request.json or {}
        timeframe = body.get('timeframe', '15m')

        logger.info(f"[TEST LIMIT] Starting test limit buy for {symbol} [{timeframe}] @ $0.50")

        from datetime import timezone, datetime as dt

        if timeframe == '5m':
            # ── 5-minute path ──────────────────────────────────────────
            candles = prediction_bot.data_fetcher.get_5min_candles(symbol, num_candles=300)
            if not candles:
                return jsonify({'success': False, 'error': 'No 5m candle data available'})

            if symbol == 'BNB':
                analysis = {'signal': 'NEUTRAL', 'confidence': 0, 'indicators': {}, 'reasons': ['No algo assigned'], 'chart_data': {}}
            elif symbol == 'BTC':
                analysis = prediction_bot.btc_5m_analyzer.analyze(candles, symbol)
            elif symbol == 'ETH':
                a = prediction_bot.eth_5m_analyzer.analyze(candles, symbol)
                if a['signal'] == 'NEUTRAL':
                    a = prediction_bot.eth_5m_sol_analyzer.analyze(candles, symbol)
                analysis = a
            elif symbol == 'SOL':
                a = prediction_bot.sol_5m_analyzer.analyze(candles, symbol)
                if a['signal'] == 'NEUTRAL':
                    a = prediction_bot.fade_giga_analyzer.analyze(candles, symbol)
                analysis = a
            else:
                analysis = prediction_bot.fade_giga_analyzer.analyze(candles, symbol)

            analysis['timeframe'] = '5m'
            next_cycle = prediction_bot.get_current_5min_timestamp() + 300
        else:
            # ── 15-minute path ─────────────────────────────────────────
            data = prediction_bot.get_analysis(symbol)
            if 'error' in data:
                return jsonify({'success': False, 'error': data['error']})
            analysis = data['analysis']
            next_cycle = prediction_bot.get_current_15min_timestamp() + (15 * 60)

        # Force a signal if neutral
        if analysis['signal'] == 'NEUTRAL':
            logger.info(f"[TEST LIMIT] Signal is NEUTRAL, forcing BULLISH")
            analysis['signal'] = 'BULLISH'

        # Force confidence to pass checks
        if analysis['confidence'] < 60:
            analysis['confidence'] = 60

        next_time = dt.fromtimestamp(next_cycle, tz=timezone.utc)
        logger.info(f"[TEST LIMIT] Targeting NEXT {timeframe} session: {next_cycle} ({next_time.strftime('%H:%M')} UTC)")

        # Calculate order amount ($5 worth at $0.50 per share = 10 shares)
        limit_price = 0.50
        test_amount = 5.0  # $5 test (minimum 5 shares required by Polymarket)
        shares = test_amount / limit_price  # 10 shares

        logger.info(f"[TEST LIMIT] Order: ${test_amount} @ ${limit_price}/share = {shares} shares")

        # Place limit order for NEXT cycle
        result = prediction_bot.place_limit_order(
            symbol=symbol,
            analysis=analysis,
            target_cycle=next_cycle,
            amount=test_amount,
            limit_price=limit_price
        )

        if result.get('success'):
            logger.info(f"[TEST LIMIT] Success! Limit order placed: {result.get('order_id')}")
            return jsonify({
                'success': True,
                'message': f'Test limit order placed for {symbol} [{timeframe}]',
                'order_id': result.get('order_id'),
                'signal': analysis['signal'],
                'timeframe': timeframe,
                'limit_price': limit_price,
                'amount': test_amount,
                'shares': shares,
                'target_time': next_time.strftime('%H:%M UTC'),
                'order_type': 'LIMIT_GTC'
            })
        else:
            error_msg = result.get('error') or result.get('message', 'Unknown error')
            logger.error(f"[TEST LIMIT] Failed: {error_msg}")
            return jsonify({
                'success': False,
                'error': error_msg
            })

    except Exception as e:
        logger.error(f"[TEST LIMIT] Exception: {e}")
        return jsonify({'success': False, 'error': str(e)})


@app.route('/api/env-debug')
def env_debug():
    try:
        def mask(v):
            if not v: return '(empty)'
            v = str(v)
            if v.upper().startswith('ENC:'): return f'ENC:... ({len(v)} chars - still encrypted!)'
            if len(v) < 8: return '(too short)'
            return v[:4] + '****' + v[-4:]

        pk_raw    = os.getenv('PRIVATE_KEY', '')
        wallet    = os.getenv('WALLET_ADDRESS', '')
        proxy     = os.getenv('POLYMARKET_PROXY_ADDRESS', '')
        master_pw = os.getenv('MASTER_PASSWORD', '')

        dk_status = 'not found'
        try:
            import decrypt_keys
            dk_status = f'found at {decrypt_keys.__file__}'
        except ImportError:
            dk_status = 'NOT FOUND - decrypt_keys.py missing from Desktop/main/'

        try:
            env_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'grok.env')
        except Exception:
            env_path = os.path.join(os.getcwd(), 'grok.env')
        salt_path = env_path.replace('.env', '.salt')

        pk_hex = pk_raw.strip()
        if pk_hex.lower().startswith('0x'): pk_hex = pk_hex[2:]
        hex_chars = sum(1 for c in pk_hex if c in '0123456789abcdefABCDEF')

        try:
            bot_live   = bool(prediction_bot and prediction_bot.wallet_live)
            clob_alive = bool(prediction_bot and prediction_bot.clob_client)
        except Exception:
            bot_live = clob_alive = False

        return jsonify({
            'env_file': {'path': env_path, 'exists': os.path.isfile(env_path),
                         'salt_exists': os.path.isfile(salt_path)},
            'decrypt_keys_module': {'status': dk_status},
            'credentials': {
                'MASTER_PASSWORD_set':      bool(master_pw),
                'PRIVATE_KEY':              mask(pk_raw),
                'PRIVATE_KEY_is_encrypted': pk_raw.strip().upper().startswith('ENC:'),
                'PRIVATE_KEY_hex_chars':    hex_chars,
                'PRIVATE_KEY_length_ok':    hex_chars == 64,
                'WALLET_ADDRESS':           mask(wallet),
                'WALLET_ADDRESS_set':       bool(wallet),
                'PROXY_ADDRESS':            mask(proxy),
                'PROXY_ADDRESS_set':        bool(proxy),
                'PROXY_equals_WALLET':      wallet.lower() == proxy.lower() if wallet and proxy else False,
            },
            'bot': {'wallet_live': bot_live, 'clob_client': clob_alive},
        })
    except Exception as e:
        return jsonify({'error': str(e), 'type': type(e).__name__})


@app.route('/api/test-trade', methods=['POST'])
def test_trade():
    global prediction_bot
    if not prediction_bot:
        return jsonify({'success': False, 'steps': [], 'error': 'Bot not initialized'})

    data       = request.json or {}
    symbol     = data.get('symbol', 'BTC').upper()
    side       = data.get('side', 'BULLISH')
    amount     = float(data.get('amount', 1.0))
    dry_run    = bool(data.get('dry_run', True))
    timeframe  = data.get('timeframe', '15m')
    order_type = data.get('order_type', 'MARKET')
    limit_price = float(data.get('limit_price', 0)) if data.get('limit_price') else None
    steps      = []

    def step(name, fn):
        try:
            result = fn()
            steps.append({'step': name, 'status': 'ok', 'detail': str(result)[:300]})
            return result
        except Exception as e:
            steps.append({'step': name, 'status': 'fail', 'detail': str(e)[:400]})
            return None

    bot = prediction_bot

    if not step('1. Wallet configured', lambda: (
        (_ for _ in ()).throw(Exception('wallet_live=False — MASTER_PASSWORD wrong or grok.env/salt missing'))
        if not bot.wallet_live else
        f'wallet={bot.wallet_address[:12]}...  proxy={bot.proxy_address[:12]}...'
    )): return jsonify({'success': False, 'steps': steps})

    if not step('2. CLOB client alive', lambda: (
        (_ for _ in ()).throw(Exception('clob_client is None'))
        if not bot.clob_client else
        f'CLOB ok = {bot.clob_client.get_ok()}'
    )): return jsonify({'success': False, 'steps': steps})

    if not step('3. API credentials', lambda: (
        bot._refresh_api_creds() or 'API creds refreshed OK'
    )): return jsonify({'success': False, 'steps': steps})

    usdc_bal = [amount]  # assume funded — proxy wallet balance not readable via CLOB API
    def chk_balance():
        details = []
        same = (not bot.proxy_address or
                bot.proxy_address.lower() == bot.wallet_address.lower())
        sig_type = 0 if same else 2

        # Approve USDC allowance so exchange can spend funds
        try:
            bot.clob_client.update_balance_allowance(
                BalanceAllowanceParams(asset_type=AssetType.COLLATERAL, signature_type=sig_type)
            )
            details.append(f'USDC allowance approved (sig_type={sig_type})')
        except Exception as e:
            details.append(f'Allowance approve: {str(e)[:100]}')

        # Try to read balance — proxy wallets often return 0 via CLOB API
        # but funds confirmed on-chain at proxy address
        try:
            params = BalanceAllowanceParams(asset_type=AssetType.COLLATERAL, signature_type=sig_type)
            info = bot.clob_client.get_balance_allowance(params)
            if info:
                raw_bal = float(info.get('balance', 0))
                raw_al  = float(info.get('allowance', 0))
                bal = raw_bal / 1e6 if raw_bal > 1000 else raw_bal
                al  = raw_al  / 1e6 if raw_al  > 1000 else raw_al
                if bal > 0:
                    usdc_bal[0] = bal
                details.append(f'CLOB balance=${bal:.4f} allowance=${al:.4f}')
            else:
                details.append('CLOB balance: no response (proxy wallet — balance tracked on-chain)')
        except Exception as e:
            details.append(f'Balance read: {str(e)[:80]}')

        return f'Proceeding with ${amount:.2f} order | ' + ' | '.join(details)
    step('4. USDC balance', chk_balance)
    # Always continue — funds confirmed on polygonscan

    market = [None]
    def chk_market():
        if timeframe == '5m':
            next_cycle = bot.get_current_5min_timestamp() + 300
            m = bot.find_5min_market(symbol, target_timestamp=next_cycle)
            if not m: raise Exception(f'No active 5m market found for {symbol} — 5m markets may not exist yet')
        else:
            next_cycle = bot.get_current_15min_timestamp() + 900
            m = bot.find_15min_market(symbol, target_timestamp=next_cycle)
            if not m: raise Exception(f'No active 15m market found for {symbol}')
        market[0] = m
        return f"[{timeframe}] slug={m.get('slug','?')}  outcomes={m.get('outcomes')}"
    if not step('5. Find market', chk_market): return jsonify({'success': False, 'steps': steps})

    token_id = [None]; target_outcome = [None]
    def chk_token():
        import json as _j
        m = market[0]
        outcomes  = m.get('outcomes', [])
        token_ids = m.get('clobTokenIds', [])
        if isinstance(outcomes,  str): outcomes  = _j.loads(outcomes)
        if isinstance(token_ids, str): token_ids = _j.loads(token_ids)
        want = 'Up' if side == 'BULLISH' else 'Down'
        for i, o in enumerate(outcomes):
            if o.lower() == want.lower():
                token_id[0] = token_ids[i]; target_outcome[0] = o
                return f'Matched "{o}" -> token {token_ids[i][:16]}...'
        raise Exception(f'Could not match "{want}" in {outcomes}')
    if not step('6. Match token ID', chk_token): return jsonify({'success': False, 'steps': steps})

    fill_price = [None]; fill_size = [None]
    def chk_book():
        book = bot.clob_client.get_order_book(token_id[0])
        if not book or not hasattr(book, 'asks') or not book.asks:
            raise Exception('No asks in order book — market illiquid or closed')
        tick     = bot.get_tick_size(token_id[0])
        best_ask = float(book.asks[0].price)

        if order_type == 'LIMIT' and limit_price:
            price      = bot.round_price(limit_price, tick)
            order_note = f'LIMIT @ ${price}'
        else:
            price      = bot.round_price(min(best_ask * 1.01, 0.99), tick)
            order_note = f'MARKET (ask=${best_ask:.4f})'

        size  = bot.round_size(amount / price)
        size  = bot.round_maker_size(price, size)
        size  = bot._validate_size(size, price, symbol)
        maker = round(price * size, 2)
        fill_price[0] = price; fill_size[0] = size
        return f'{order_note}  fill={price}  size={size:.4f}  maker=${maker:.2f}  tick={tick}'
    if not step('7. Order book & price', chk_book): return jsonify({'success': False, 'steps': steps})

    def chk_allowance():
        best_al = 0.0
        details = []
        for sig in [0, 2]:
            try:
                params = BalanceAllowanceParams(asset_type=AssetType.COLLATERAL, signature_type=sig)
                info = bot.clob_client.get_balance_allowance(params)
                if info:
                    raw = float(info.get('allowance', 0))
                    al = raw / 1e6 if raw / 1e6 > 0.001 else raw
                    details.append(f'sig{sig}: raw={raw} al=${al:.4f}')
                    if al > best_al:
                        best_al = al
            except Exception as e:
                details.append(f'sig{sig}: error={str(e)[:50]}')
        needed = fill_price[0] * fill_size[0]
        detail_str = ' | '.join(details)
        # If allowance is 0 but balance exists, try to update it automatically
        if best_al < needed:
            try:
                bot.clob_client.update_balance_allowance(
                    BalanceAllowanceParams(asset_type=AssetType.COLLATERAL, signature_type=0)
                )
                details.append('auto-approved allowance')
                best_al = needed + 1  # assume success
            except Exception as e:
                raise Exception(f'Allowance=${best_al:.4f} < needed=${needed:.4f}. Auto-approve failed: {e} | {detail_str}')
        return f'Allowance=${best_al:.4f} OK | {detail_str}'
    if not step('8. USDC allowance', chk_allowance): return jsonify({'success': False, 'steps': steps})

    signed_order = [None]; order_id = ['N/A']
    def chk_sign():
        bot._refresh_api_creds()
        args = OrderArgs(token_id=token_id[0], price=fill_price[0], size=fill_size[0], side='BUY')
        o = bot.clob_client.create_order(args)
        signed_order[0] = o; order_id[0] = getattr(o, 'orderID', 'N/A')
        # Extract the values dict which contains makerAmount/takerAmount
        try:
            inner = o.__dict__.get('order', o)
            if hasattr(inner, '__dict__'):
                vals = inner.__dict__.get('values', inner.__dict__)
            elif isinstance(inner, dict):
                vals = inner.get('values', inner)
            else:
                vals = {}
            if hasattr(vals, '__dict__'): vals = vals.__dict__
            ma = vals.get('makerAmount', '?')
            ta = vals.get('takerAmount', '?')
            # Also check top level
            if ma == '?': ma = getattr(o, 'makerAmount', '?')
            if ta == '?': ta = getattr(o, 'takerAmount', '?')
            return (f'makerAmount={ma} takerAmount={ta} | '
                    f'vals_keys={list(vals.keys()) if isinstance(vals,dict) else type(vals).__name__}')
        except Exception as ex:
            return f'err={ex}'
    if not step('9. Sign order', chk_sign): return jsonify({'success': False, 'steps': steps})

    if dry_run:
        steps.append({'step': '10. Post order', 'status': 'skipped',
                      'detail': 'dry_run=true — all signing passed, skipping submit'})
        return jsonify({'success': True, 'steps': steps, 'dry_run': True,
                        'would_buy': target_outcome[0], 'price': fill_price[0], 'size': fill_size[0]})

    def chk_post():
        if order_type == 'LIMIT':
            result = bot.clob_client.post_order(signed_order[0], OrderType.GTC)
            return f'LIMIT/GTC placed @ ${fill_price[0]}  result={str(result)[:200]}'
        else:
            try:
                result = bot.clob_client.post_order(signed_order[0], OrderType.FOK)
                if hasattr(result, 'status') and result.status == 'REJECTED':
                    raise Exception('FOK REJECTED')
                return f'MARKET/FOK filled  result={str(result)[:200]}'
            except Exception as fok_err:
                if 'REJECTED' in str(fok_err):
                    bot._refresh_api_creds()
                    args2 = OrderArgs(token_id=token_id[0], price=fill_price[0], size=fill_size[0], side='BUY')
                    signed2 = bot.clob_client.create_order(args2)
                    result2 = bot.clob_client.post_order(signed2, OrderType.GTC)
                    return f'GTC fallback  result={str(result2)[:200]}'
                raise
    if not step('10. Post order', chk_post): return jsonify({'success': False, 'steps': steps})

    return jsonify({'success': True, 'steps': steps, 'order_id': order_id[0],
                    'bought': target_outcome[0], 'price': fill_price[0],
                    'size': fill_size[0], 'cost': round(fill_price[0]*fill_size[0], 4)})


@app.route('/api/test-limit-order', methods=['POST'])
def test_limit_order():
    """Test a GTC limit order through the full signing pipeline."""
    global prediction_bot
    if not prediction_bot:
        return jsonify({'success': False, 'message': 'Bot not initialized'})

    data        = request.json or {}
    symbol      = data.get('symbol', 'BTC').upper()
    side        = data.get('side', 'BULLISH')
    limit_price = float(data.get('limit_price', 0.48))
    amount      = float(data.get('amount', 2.0))
    dry_run     = bool(data.get('dry_run', True))

    bot = prediction_bot
    if not bot.wallet_live or not bot.clob_client:
        return jsonify({'success': False, 'message': 'Wallet not configured'})

    try:
        # Refresh creds
        bot._refresh_api_creds()

        # Find market
        next_cycle = bot.get_current_15min_timestamp() + 900
        market = bot.find_15min_market(symbol, target_timestamp=next_cycle)
        if not market:
            return jsonify({'success': False, 'message': f'No active market found for {symbol}'})

        # Match token
        import json as _j
        outcomes  = market.get('outcomes', [])
        token_ids = market.get('clobTokenIds', [])
        if isinstance(outcomes,  str): outcomes  = _j.loads(outcomes)
        if isinstance(token_ids, str): token_ids = _j.loads(token_ids)

        want = 'Up' if side == 'BULLISH' else 'Down'
        token_id = None
        for i, o in enumerate(outcomes):
            if o.lower() == want.lower():
                token_id = token_ids[i]
                break
        if not token_id:
            return jsonify({'success': False, 'message': f'Could not match outcome "{want}" in {outcomes}'})

        # Validate and round price
        tick      = bot.get_tick_size(token_id)
        price     = bot.round_price(limit_price, tick)
        size      = bot.round_size(amount / price)
        size      = bot.round_maker_size(price, size)
        size      = bot._validate_size(size, price, symbol)
        cost      = round(price * size, 4)

        if dry_run:
            # Sign only — don't post
            args = OrderArgs(token_id=token_id, price=price, size=size, side='BUY')
            signed = bot.clob_client.create_order(args)
            oid = getattr(signed, 'orderID', 'N/A')
            return jsonify({
                'success': True, 'dry_run': True,
                'order_id': oid, 'price': price,
                'size': size, 'cost': cost,
                'market': market.get('slug', ''),
                'outcome': want
            })

        # Live — post as GTC
        ok, result, oid = bot._safe_create_and_post(
            token_id, price, size, 'BUY', OrderType.GTC, symbol
        )
        if not ok:
            return jsonify({'success': False, 'message': str(result)[:200]})

        status = getattr(result, 'status', str(result)[:100])
        return jsonify({
            'success': True, 'dry_run': False,
            'order_id': oid, 'price': price,
            'size': size, 'cost': cost,
            'status': status,
            'market': market.get('slug', ''),
            'outcome': want
        })

    except Exception as e:
        return jsonify({'success': False, 'message': str(e)[:300]})


# In-memory price cache — updated by background thread, served instantly
_price_cache = {'prices': {}, 'updated': 0}
_price_lock  = threading.Lock()

def _refresh_price_cache():
    """Background: fetch Yes/No prices + populate market cache for all symbols."""
    if not prediction_bot or not prediction_bot.clob_client:
        return
    import json as _j, time as _t
    from datetime import datetime, timezone
    prices = {}
    now = datetime.now(timezone.utc)
    base = int(now.timestamp())
    base_15 = (base // 900) * 900
    ts_candidates = [base_15, base_15 + 900, base_15 - 900, base_15 + 1800, base_15 - 1800]

    for symbol in prediction_bot.symbols:
        try:
            market = None
            # Check cache first for a valid open market
            if symbol in prediction_bot.market_cache:
                cached_m = prediction_bot.market_cache[symbol].get('data', {})
                end_date = cached_m.get('end_date', '')
                if end_date:
                    try:
                        end_dt = datetime.fromisoformat(end_date.replace('Z', '+00:00'))
                        if end_dt > now:
                            market = cached_m  # cached market still open
                    except Exception:
                        market = cached_m  # can't parse, use it anyway

            # Cache miss or expired — search for open market
            if not market:
                for ts in ts_candidates:
                    try:
                        fetched = prediction_bot.find_15min_market(symbol, target_timestamp=ts)
                        if not fetched:
                            continue
                        # Verify market is still open
                        end_date = fetched.get('end_date', '')
                        is_open = True
                        if end_date:
                            try:
                                end_dt = datetime.fromisoformat(end_date.replace('Z', '+00:00'))
                                is_open = end_dt > now
                            except Exception:
                                pass
                        if is_open:
                            prediction_bot.market_cache[symbol] = {
                                'data': fetched, 'timestamp': _t.time()
                            }
                            market = fetched
                            break
                        else:
                            logger.debug(f"[PRICES] {symbol} ts={ts} market closed ({end_date})")
                    except Exception:
                        continue

            if not market:
                logger.debug(f"[PRICES] {symbol}: no open market found")
                continue

            outcomes  = market.get('outcomes', [])
            token_ids = market.get('clobTokenIds', [])
            if isinstance(outcomes,  str): outcomes  = _j.loads(outcomes)
            if isinstance(token_ids, str): token_ids = _j.loads(token_ids)
            if len(token_ids) < 2 or len(outcomes) < 2:
                continue

            yes_token, no_token = _extract_tokens(market)
            if not yes_token or not no_token:
                continue

            def get_mid(token_id):
                """Live price = midpoint of best bid and best ask."""
                try:
                    book = prediction_bot.clob_client.get_order_book(token_id)
                    bids = getattr(book, 'bids', [])
                    asks = getattr(book, 'asks', [])
                    bid  = float(bids[0].price) if bids else None
                    ask  = float(asks[0].price) if asks else None
                    if bid and ask:
                        return round((bid + ask) / 2, 4)
                    return bid or ask
                except Exception:
                    return None

            yes_mid = get_mid(yes_token)
            no_mid  = get_mid(no_token)

            prices[symbol] = {
                'yes':     yes_mid,
                'no':      no_mid,
                'yes_pct': round((yes_mid or 0) * 100, 1),
                'no_pct':  round((no_mid  or 0) * 100, 1),
                'state':   'live',
            }


        except Exception as e:
            logger.debug(f"Price cache error {symbol}: {e}")

    with _price_lock:
        _price_cache['prices']  = prices
        _price_cache['updated'] = _t.time()

    if prices:
        socketio.emit('prices_update', {'prices': prices})
        logger.debug(f"[PRICES] Updated {len(prices)} symbols: {list(prices.keys())}")
    # Always emit token IDs so frontend can subscribe to all available symbols
    all_tokens = {}
    for symbol in prediction_bot.symbols:
        cached = prediction_bot.market_cache.get(symbol, {}).get('data')
        if cached:
            y, n = _extract_tokens(cached)
            if y or n:
                all_tokens[symbol] = {'yes': y, 'no': n}
    if all_tokens:
        socketio.emit('market_tokens_update', {'tokens': all_tokens})


def _price_refresh_loop():
    """Background thread: refresh prices every 10 seconds."""
    import time as _t
    while True:
        try:
            _refresh_price_cache()
        except Exception as e:
            logger.debug(f"[PRICES] Loop error: {e}")
        _t.sleep(10)

# Start background price thread
_price_thread = threading.Thread(target=_price_refresh_loop, daemon=True)
_price_thread.start()

@app.route('/api/prices')
def get_live_prices():
    """Return cached Yes/No prices — instant, never blocks."""
    import time as _t
    with _price_lock:
        prices  = dict(_price_cache['prices'])
        updated = _price_cache['updated']
    age = round(_t.time() - updated, 1) if updated else None
    return jsonify({'prices': prices, 'cache_age_seconds': age})


def _extract_tokens(market):
    """Extract yes/no token IDs from a market dict."""
    import json as _j
    if not market:
        return None, None
    outcomes  = market.get('outcomes', [])
    token_ids = market.get('clobTokenIds', [])
    if isinstance(outcomes,  str): outcomes  = _j.loads(outcomes)
    if isinstance(token_ids, str): token_ids = _j.loads(token_ids)
    yes_token = no_token = None
    for i, o in enumerate(outcomes):
        if o.lower() == 'up'   and i < len(token_ids): yes_token = token_ids[i]
        if o.lower() == 'down' and i < len(token_ids): no_token  = token_ids[i]
    return yes_token, no_token

@app.route('/api/market-tokens')
def market_tokens():
    """Return Yes/No token IDs from cache only — never blocks on HTTP calls."""
    global prediction_bot
    if not prediction_bot:
        return jsonify({'tokens': {}})
    tokens = {}
    for symbol in prediction_bot.symbols:
        try:
            # Cache only — no blocking HTTP calls in a request handler
            cached = prediction_bot.market_cache.get(symbol, {}).get('data')
            if not cached:
                continue
            yes_token, no_token = _extract_tokens(cached)
            if yes_token or no_token:
                tokens[symbol] = {'yes': yes_token, 'no': no_token}
        except Exception as e:
            logger.debug(f"market-tokens error {symbol}: {e}")
    return jsonify({'tokens': tokens})


ALGOS_FILE     = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'algos.json')
TV_ALERTS_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'tv_alerts.json')
SIGNALS_LOG    = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'signals_log.json')


def parse_pinescript_config(code: str) -> dict:
    """Extract a backtest-compatible config dict from PineScript input declarations."""
    import re
    cfg = {
        'percentile':     80.0,
        'min_body_pct':   0.10,
        'rsi_overbought': 60.0,
        'rsi_oversold':   40.0,
        'rsi_period':     7,
        'use_trend':      False,
        'use_wick':       False,
        'min_wick_ratio': 0.0,
        'cooldown_bars':  1,
    }
    float_pat = re.compile(r'input\.float\s*\(\s*([\d.]+)\s*,\s*"([^"]+)"', re.I)
    int_pat   = re.compile(r'input\.int\s*\(\s*(\d+)\s*,\s*"([^"]+)"', re.I)
    bool_pat  = re.compile(r'input\.bool\s*\(\s*(true|false)\s*,\s*"([^"]+)"', re.I)
    str_pat   = re.compile(r'input\.string\s*\(\s*"([^"]+)"\s*,\s*"([^"]+)"', re.I)

    for val, label in float_pat.findall(code):
        ll, v = label.lower(), float(val)
        if any(k in ll for k in ('giga percentile', 'percentile', 'giga pct')):
            cfg['percentile'] = v
        elif any(k in ll for k in ('min body', 'body %', 'body pct')):
            cfg['min_body_pct'] = v
        elif 'rsi' in ll and any(k in ll for k in ('overbought', 'threshold', 'ob')):
            cfg['rsi_overbought'] = v
        elif 'rsi' in ll and any(k in ll for k in ('oversold', 'os')):
            cfg['rsi_oversold'] = v
        elif any(k in ll for k in ('wick/body', 'wick ratio', 'wick / body', 'min wick')):
            cfg['min_wick_ratio'] = v
            if v > 0:
                cfg['use_wick'] = True

    for val, label in int_pat.findall(code):
        ll, v = label.lower(), int(val)
        if 'rsi' in ll and any(k in ll for k in ('length', 'period', 'len')):
            cfg['rsi_period'] = v
        elif any(k in ll for k in ('cooldown', 'cool down')):
            cfg['cooldown_bars'] = v

    for val, label in bool_pat.findall(code):
        ll, v = label.lower(), val.lower() == 'true'
        if 'wick' in ll:
            cfg['use_wick'] = v
        elif any(k in ll for k in ('trend', 'ema')):
            cfg['use_trend'] = v

    return cfg

@app.route('/api/algos', methods=['GET'])
def get_algos():
    """Load algorithms from algos.json (same folder as the script). Mtime-cached."""
    return jsonify(_load_json_cached(ALGOS_FILE, default={}) or {})

@app.route('/api/algos', methods=['POST'])
def save_algos():
    """Save algorithms to algos.json (same folder as the script)"""
    try:
        data = request.get_json()
        if not isinstance(data, dict):
            return jsonify({'success': False, 'error': 'Invalid data'})
        with open(ALGOS_FILE, 'w', encoding='utf-8') as f:
            json.dump(data, f, indent=2, ensure_ascii=False)
        logger.info(f"Algos saved: {len(data)} algorithms -> {ALGOS_FILE}")
        return jsonify({'success': True, 'count': len(data)})
    except Exception as e:
        logger.error(f"Error saving algos: {e}")
        return jsonify({'success': False, 'error': str(e)})


def _fetch_hl_candles_paginated(symbol: str, interval: str, num_candles: int) -> list:
    """Paginated Hyperliquid candle fetch — primary source for HYPE (not on Binance).
    Walks backwards in time in 500-candle chunks until num_candles is satisfied."""
    import time as _t
    interval_ms = {'15m': 15 * 60 * 1000, '5m': 5 * 60 * 1000}.get(interval, 15 * 60 * 1000)
    chunk_size  = 500
    chunk_ms    = chunk_size * interval_ms
    end_t       = int(_t.time() * 1000)
    target_start = end_t - (num_candles * interval_ms)
    all_c  = []
    cur_end = end_t
    while cur_end > target_start and len(all_c) < num_candles:
        cur_start = max(target_start, cur_end - chunk_ms)
        try:
            r = requests.post(
                'https://api.hyperliquid.xyz/info',
                json={'type': 'candleSnapshot', 'req': {
                    'coin': symbol, 'interval': interval,
                    'startTime': cur_start, 'endTime': cur_end
                }},
                timeout=15
            )
            if r.status_code == 200 and r.json():
                chunk = [{'timestamp': int(c['t']), 'open': float(c['o']), 'high': float(c['h']),
                          'low': float(c['l']), 'close': float(c['c']), 'volume': float(c['v'])}
                         for c in r.json() if isinstance(c, dict)]
                all_c  = chunk + all_c
                cur_end = cur_start - 1
                if len(r.json()) < chunk_size // 2:
                    break  # Hyperliquid has no more history
            else:
                break
        except Exception as e:
            logger.warning(f"[HL-FETCH] {symbol} {interval}: {e}")
            break
    return sorted(all_c, key=lambda x: x['timestamp'])


@app.route('/api/backtest/<symbol>')
def backtest_symbol(symbol):
    """Run DogeV1 + GigaV35 backtest on historical candles.
    Fetches up to 90 days (8640 candles) by paginating Binance API.
    Returns per-strategy stats matching the TradingView table."""
    import time as _t
    symbol = symbol.upper()
    if symbol not in ['BTC','ETH','SOL','XRP','DOGE','HYPE','BNB']:
        return jsonify({'error': 'Invalid symbol'})

    days = int(request.args.get('days', 90))
    num_candles = min(days * 96, 8640)  # 96 candles/day on 15m

    try:
        # HYPE is not on Binance — use Hyperliquid directly
        if symbol == 'HYPE':
            all_candles = _fetch_hl_candles_paginated('HYPE', '15m', num_candles)
        else:
            binance_map = {'BTC':'BTCUSDT','ETH':'ETHUSDT','SOL':'SOLUSDT',
                           'XRP':'XRPUSDT','DOGE':'DOGEUSDT','BNB':'BNBUSDT'}
            b_sym = binance_map.get(symbol)
            if not b_sym:
                return jsonify({'error': 'No data source for symbol'})

            all_candles = []
            end_time = int(_t.time() * 1000)
            remaining = num_candles

            while remaining > 0:
                batch = min(remaining, 1000)
                params = {
                    'symbol': b_sym, 'interval': '15m',
                    'limit': batch, 'endTime': end_time
                }
                r = requests.get('https://api.binance.com/api/v3/klines',
                               params=params, timeout=15)
                if r.status_code != 200 or not r.json():
                    break
                data = r.json()
                candles = [{'timestamp': c[0], 'open': float(c[1]), 'high': float(c[2]),
                            'low': float(c[3]), 'close': float(c[4]), 'volume': float(c[5])}
                           for c in data]
                all_candles = candles + all_candles
                end_time = data[0][0] - 1
                remaining -= len(candles)
                if len(candles) < batch:
                    break

        if len(all_candles) < 100:
            return jsonify({'error': f'Not enough data ({len(all_candles)} candles)'})

        logger.info(f"[BACKTEST] {symbol}: {len(all_candles)} candles fetched")

        def run_strategy(candles, cfg, strategy_name):
            """Simulate the Pine Script signal logic on historical candles."""
            import numpy as np
            results = []
            bars_since = 999

            for i in range(50, len(candles) - 1):
                window = candles[max(0, i-499):i+1]
                body_pcts = [abs(c['close']-c['open'])/c['open']*100 if c['open']>0 else 0
                             for c in window]

                giga_threshold = float(np.percentile(body_pcts, cfg['percentile']))
                last = candles[i]
                body_pct = body_pcts[-1]
                is_giga = body_pct >= giga_threshold and body_pct >= cfg['min_body_pct']
                is_green = last['close'] > last['open']
                is_red   = last['close'] < last['open']

                # RSI
                closes = [c['close'] for c in window]
                rsi = prediction_bot.fade_giga_analyzer.indicators.calculate_rsi(closes, 14)

                # EMA trend
                ema9  = prediction_bot.fade_giga_analyzer.indicators.calculate_ema(closes, 9)
                ema21 = prediction_bot.fade_giga_analyzer.indicators.calculate_ema(closes, 21)
                trend_bull = ema9[-1] > ema21[-1]
                trend_bear = ema9[-1] < ema21[-1]

                # Wick
                candle_range = last['high'] - last['low']
                upper_wick = last['high'] - max(last['open'], last['close'])
                lower_wick = min(last['open'], last['close']) - last['low']
                upper_wr = upper_wick / candle_range if candle_range > 0 else 0
                lower_wr = lower_wick / candle_range if candle_range > 0 else 0

                rsi_ok_bear = rsi >= cfg['rsi_overbought']
                rsi_ok_bull = rsi <= cfg['rsi_oversold']
                trend_ok_bear = trend_bull if cfg.get('use_trend') else True
                trend_ok_bull = trend_bear if cfg.get('use_trend') else True
                wick_ok_bear  = upper_wr >= cfg.get('min_wick_ratio',0) if cfg.get('use_wick') else True
                wick_ok_bull  = lower_wr >= cfg.get('min_wick_ratio',0) if cfg.get('use_wick') else True
                cooldown_ok   = bars_since >= cfg['cooldown_bars']

                signal = None
                if is_giga and cooldown_ok:
                    if is_green and rsi_ok_bear and trend_ok_bear and wick_ok_bear:
                        signal = 'BEAR'
                    elif is_red and rsi_ok_bull and trend_ok_bull and wick_ok_bull:
                        signal = 'BULL'

                if signal:
                    bars_since = 0
                    next_c = candles[i+1]
                    correct = (signal=='BEAR' and next_c['close'] < last['close']) or                               (signal=='BULL' and next_c['close'] > last['close'])
                    results.append({
                        'ts': last['timestamp'],
                        'signal': signal,
                        'correct': correct,
                        'entry': last['close'],
                        'exit':  next_c['close'],
                        'body_pct': round(body_pct, 3),
                        'rsi': round(rsi, 1)
                    })
                else:
                    bars_since += 1

            total  = len(results)
            wins   = sum(1 for r in results if r['correct'])
            losses = total - wins
            wr     = round(wins/total*100, 1) if total > 0 else 0
            ev     = round(wr/100*75 - (100-wr)/100*100, 2) if total > 0 else 0
            total_ret = wins*75 - losses*100

            # Streak
            streak = 0
            cur = 0
            for r in results:
                if r['correct']:
                    cur = cur+1 if cur > 0 else 1
                else:
                    cur = cur-1 if cur < 0 else -1
            streak = cur

            return {
                'strategy': strategy_name,
                'total': total, 'wins': wins, 'losses': losses,
                'win_rate': wr, 'ev': ev, 'total_return': total_ret,
                'streak': streak,
                'signals_per_day': round(total / max(days,1), 1),
                'signals': results[-20:]  # last 20 for display
            }

        stats = {}

        # Run GigaV35
        giga_cfg = prediction_bot.fade_giga_analyzer.ASSET_CONFIGS.get(symbol)
        if giga_cfg:
            stats['giga_v35'] = run_strategy(all_candles, giga_cfg, 'Giga V35')

        # Run DogeV1 for BTC/ETH
        doge_cfg = prediction_bot.fade_giga_analyzer.DOGE_V1_CONFIGS.get(symbol)
        if doge_cfg:
            stats['doge_v1'] = run_strategy(all_candles, doge_cfg, 'Doge V1')

        return jsonify({
            'symbol': symbol,
            'candles': len(all_candles),
            'days': days,
            'stats': stats
        })

    except Exception as e:
        logger.error(f"Backtest error {symbol}: {e}")
        return jsonify({'error': str(e)})


@app.route('/api/backtest-algo/<symbol>')
def backtest_algo(symbol):
    """Backtest a user-saved algo (parsed from PineScript) against historical candles."""
    import time as _t
    import numpy as np

    global prediction_bot
    if not prediction_bot:
        return jsonify({'error': 'Bot not initialized'})

    symbol = symbol.upper()
    if symbol not in ['BTC', 'ETH', 'SOL', 'XRP', 'DOGE', 'HYPE', 'BNB']:
        return jsonify({'error': 'Invalid symbol'})

    algo_id = request.args.get('algo_id', '')
    days    = int(request.args.get('days', 30))
    tf      = request.args.get('tf', '15m')

    # Load algo
    try:
        if not os.path.exists(ALGOS_FILE):
            return jsonify({'error': 'No algos saved yet'})
        with open(ALGOS_FILE, 'r', encoding='utf-8') as f:
            algos = json.load(f)
        algo = algos.get(algo_id)
        if not algo:
            return jsonify({'error': f'Algo not found: {algo_id}'})
    except Exception as e:
        return jsonify({'error': f'Could not load algo: {e}'})

    code = algo.get('code', '')
    cfg  = parse_pinescript_config(code)
    algo_name = algo.get('name', 'Custom Algo')

    interval = '5m' if tf == '5m' else '15m'
    candles_per_day = 288 if tf == '5m' else 96
    num_candles = min(days * candles_per_day, 8640)

    # HYPE is not on Binance — use Hyperliquid directly
    if symbol == 'HYPE':
        all_candles = _fetch_hl_candles_paginated('HYPE', interval, num_candles)
    else:
        binance_map = {'BTC':'BTCUSDT','ETH':'ETHUSDT','SOL':'SOLUSDT',
                       'XRP':'XRPUSDT','DOGE':'DOGEUSDT','BNB':'BNBUSDT'}
        b_sym = binance_map.get(symbol)
        all_candles = []
        end_time    = int(_t.time() * 1000)
        remaining   = num_candles
        try:
            while remaining > 0:
                batch  = min(remaining, 1000)
                params = {'symbol': b_sym, 'interval': interval, 'limit': batch, 'endTime': end_time}
                r = requests.get('https://api.binance.com/api/v3/klines', params=params, timeout=15)
                if r.status_code != 200 or not r.json():
                    break
                data = r.json()
                candles = [{'timestamp': c[0], 'open': float(c[1]), 'high': float(c[2]),
                            'low': float(c[3]), 'close': float(c[4]), 'volume': float(c[5])}
                           for c in data]
                all_candles = candles + all_candles
                end_time  = data[0][0] - 1
                remaining -= len(candles)
                if len(candles) < batch:
                    break
        except Exception as e:
            return jsonify({'error': f'Candle fetch failed: {e}'})

    if len(all_candles) < 100:
        return jsonify({'error': f'Not enough data ({len(all_candles)} candles)'})

    # Pre-compute indicators once across all candles (O(n) not O(n²))
    def run_algo(candles, cfg, name):
        n       = len(candles)
        closes  = np.array([c['close'] for c in candles])
        opens   = np.array([c['open']  for c in candles])
        highs   = np.array([c['high']  for c in candles])
        lows    = np.array([c['low']   for c in candles])

        # Body pct per bar
        body_pcts = np.where(opens > 0, np.abs(closes - opens) / opens * 100, 0.0)

        # RSI(14) — compute once over full series
        rsi_series = prediction_bot.fade_giga_analyzer.indicators.calculate_rsi(closes.tolist(), 14)
        if not isinstance(rsi_series, (list, np.ndarray)):
            rsi_series = [rsi_series] * n
        rsi_arr = np.array(rsi_series) if len(rsi_series) == n else np.full(n, rsi_series if isinstance(rsi_series, float) else 50.0)

        # EMA9 / EMA21 — compute once
        ema9_list  = prediction_bot.fade_giga_analyzer.indicators.calculate_ema(closes.tolist(), 9)
        ema21_list = prediction_bot.fade_giga_analyzer.indicators.calculate_ema(closes.tolist(), 21)
        ema9_arr   = np.array(ema9_list)  if len(ema9_list)  == n else np.full(n, closes[-1])
        ema21_arr  = np.array(ema21_list) if len(ema21_list) == n else np.full(n, closes[-1])

        results    = []
        bars_since = 999
        lookback   = 500

        for i in range(50, n - 1):
            # Rolling giga threshold (last `lookback` bars)
            window_bp = body_pcts[max(0, i - lookback):i + 1]
            giga_thr  = float(np.percentile(window_bp, cfg['percentile']))

            last      = candles[i]
            body_pct  = body_pcts[i]
            is_giga   = body_pct >= giga_thr and body_pct >= cfg['min_body_pct']
            is_green  = closes[i] > opens[i]
            is_red    = closes[i] < opens[i]

            rsi        = float(rsi_arr[i])
            trend_bull = ema9_arr[i] > ema21_arr[i]
            trend_bear = ema9_arr[i] < ema21_arr[i]

            c_range    = highs[i] - lows[i]
            upper_wick = highs[i] - max(opens[i], closes[i])
            lower_wick = min(opens[i], closes[i]) - lows[i]
            upper_wr   = float(upper_wick / c_range) if c_range > 0 else 0.0
            lower_wr   = float(lower_wick / c_range) if c_range > 0 else 0.0

            rsi_bear      = rsi >= cfg['rsi_overbought']
            rsi_bull      = rsi <= cfg['rsi_oversold']
            trend_bear_ok = trend_bull if cfg.get('use_trend') else True
            trend_bull_ok = trend_bear if cfg.get('use_trend') else True
            wick_bear_ok  = upper_wr >= cfg.get('min_wick_ratio', 0) if cfg.get('use_wick') else True
            wick_bull_ok  = lower_wr >= cfg.get('min_wick_ratio', 0) if cfg.get('use_wick') else True
            cooldown_ok   = bars_since >= cfg['cooldown_bars']

            signal = None
            if is_giga and cooldown_ok:
                if is_green and rsi_bear and trend_bear_ok and wick_bear_ok:
                    signal = 'BEAR'
                elif is_red and rsi_bull and trend_bull_ok and wick_bull_ok:
                    signal = 'BULL'

            if signal:
                bars_since = 0
                next_c  = candles[i + 1]
                correct = (signal == 'BEAR' and next_c['close'] < last['close']) or \
                          (signal == 'BULL' and next_c['close'] > last['close'])
                results.append({'ts': last['timestamp'], 'signal': signal, 'correct': correct,
                                'entry': last['close'], 'exit': next_c['close'],
                                'body_pct': round(float(body_pct), 3), 'rsi': round(rsi, 1)})
            else:
                bars_since += 1

        total  = len(results)
        wins   = sum(1 for r in results if r['correct'])
        losses = total - wins
        wr     = round(wins / total * 100, 1) if total > 0 else 0
        ev     = round(wr / 100 * 75 - (100 - wr) / 100 * 100, 2) if total > 0 else 0
        cur    = 0
        for r in results:
            cur = (cur + 1 if cur > 0 else 1) if r['correct'] else (cur - 1 if cur < 0 else -1)
        return {
            'strategy': name, 'total': total, 'wins': wins, 'losses': losses,
            'win_rate': wr, 'ev': ev, 'total_return': wins * 75 - losses * 100,
            'streak': cur, 'signals_per_day': round(total / max(days, 1), 1),
            'signals': results[-20:], 'parsed_cfg': cfg
        }

    try:
        result = run_algo(all_candles, cfg, algo_name)
    except Exception as e:
        logger.error(f"[BACKTEST-ALGO] run_algo error: {e}", exc_info=True)
        return jsonify({'error': f'Backtest failed: {str(e)}'})
    return jsonify({
        'symbol': symbol, 'candles': len(all_candles), 'days': days, 'tf': tf,
        'algo_name': algo_name, 'algo_desc': algo.get('desc', ''),
        'parsed_cfg': cfg,
        'stats': {algo_id: result}
    })


# ── MAX BACKTEST JOB ─────────────────────────────────────────────────
_max_bt_job = {
    'running': False, 'done': False, 'error': None,
    'progress': 0, 'total': 0, 'current': '',
    'results': [], 'winners': [], 'days': 30
}

def _run_max_backtest(days: int):
    """Background thread: test every algo × symbol × timeframe, log winners."""
    import time as _t
    import numpy as np

    global _max_bt_job
    _max_bt_job.update({'running': True, 'done': False, 'error': None,
                        'progress': 0, 'results': [], 'winners': [], 'days': days})

    SYMBOLS   = ['BTC', 'ETH', 'SOL', 'XRP', 'DOGE', 'HYPE', 'BNB']
    TIMEFRAMES = ['15m', '5m']
    BINANCE   = {'BTC':'BTCUSDT','ETH':'ETHUSDT','SOL':'SOLUSDT',
                 'XRP':'XRPUSDT','DOGE':'DOGEUSDT','BNB':'BNBUSDT'}  # HYPE handled via Hyperliquid
    MIN_SIGNALS = 10   # Ignore results with too few signals
    MIN_WR      = 58.0 # Win rate threshold to be a "winner"

    # Load algos
    try:
        with open(ALGOS_FILE, 'r', encoding='utf-8') as f:
            algos = json.load(f)
        if not algos:
            _max_bt_job['error'] = 'No algos saved'
            _max_bt_job['running'] = False
            return
    except Exception as e:
        _max_bt_job['error'] = f'Could not load algos: {e}'
        _max_bt_job['running'] = False
        return

    algo_list = list(algos.values())
    _max_bt_job['total'] = len(algo_list) * len(SYMBOLS) * len(TIMEFRAMES)

    # ── Step 1: fetch candles for each symbol×tf once ──────────────
    candle_cache = {}
    for sym in SYMBOLS:
        for tf in TIMEFRAMES:
            _max_bt_job['current'] = f'Fetching {sym} {tf} candles…'
            cpd = 288 if tf == '5m' else 96
            num = min(days * cpd, 8640)
            all_c = []

            if sym == 'HYPE':
                # HYPE is not on Binance — fetch from Hyperliquid
                try:
                    all_c = _fetch_hl_candles_paginated('HYPE', tf, num)
                except Exception as e:
                    logger.warning(f"[MAX-BT] HL candle fetch HYPE {tf}: {e}")
            else:
                b_sym = BINANCE[sym]
                end_t = int(_t.time() * 1000)
                rem   = num
                try:
                    while rem > 0:
                        batch  = min(rem, 1000)
                        r = requests.get('https://api.binance.com/api/v3/klines',
                                         params={'symbol': b_sym, 'interval': tf,
                                                 'limit': batch, 'endTime': end_t},
                                         timeout=15)
                        if r.status_code != 200 or not r.json():
                            break
                        data = r.json()
                        all_c = [{'timestamp': c[0], 'open': float(c[1]), 'high': float(c[2]),
                                  'low': float(c[3]), 'close': float(c[4]), 'volume': float(c[5])}
                                 for c in data] + all_c
                        end_t = data[0][0] - 1
                        rem  -= len(data)
                        if len(data) < batch:
                            break
                except Exception as e:
                    logger.warning(f"[MAX-BT] candle fetch {sym} {tf}: {e}")

            candle_cache[(sym, tf)] = all_c if len(all_c) >= 100 else []
            logger.info(f"[MAX-BT] Cached {sym} {tf}: {len(all_c)} candles")

    # ── Step 2: for each algo, run against every cached candle set ──
    def _wilder_rsi_arr(prices, period=7):
        """Vectorized Wilder's RSI returning one value per bar (same length as input)."""
        n = len(prices)
        rsi = np.full(n, 50.0)
        if n < period + 2:
            return rsi
        deltas = np.diff(prices)
        gains  = np.where(deltas > 0, deltas, 0.0)
        losses = np.where(deltas < 0, -deltas, 0.0)
        alpha  = 1.0 / period
        ag = np.zeros(n - 1)
        al = np.zeros(n - 1)
        ag[0] = gains[0]; al[0] = losses[0]
        for k in range(1, n - 1):
            ag[k] = alpha * gains[k] + (1 - alpha) * ag[k - 1]
            al[k] = alpha * losses[k] + (1 - alpha) * al[k - 1]
        safe_al = np.where(al > 0, al, np.nan)
        rs = np.where(al > 0, ag / safe_al, np.where(ag > 0, 1e9, 1.0))
        rsi[1:] = 100 - 100 / (1 + rs)
        return rsi

    def _ema_arr(prices, period):
        """EMA returning one value per bar."""
        n = len(prices)
        mult = 2.0 / (period + 1)
        out  = np.empty(n)
        out[0] = prices[0]
        for k in range(1, n):
            out[k] = prices[k] * mult + out[k - 1] * (1 - mult)
        return out

    def _run_one(candles, cfg, name, days_):
        n      = len(candles)
        closes = np.array([c['close'] for c in candles])
        opens  = np.array([c['open']  for c in candles])
        highs  = np.array([c['high']  for c in candles])
        lows   = np.array([c['low']   for c in candles])
        body_pcts = np.where(opens > 0, np.abs(closes - opens) / opens * 100, 0.0)

        rsi_period = int(cfg.get('rsi_period', 7))
        rsi_arr   = _wilder_rsi_arr(closes, rsi_period)
        ema9_arr  = _ema_arr(closes, 9)
        ema21_arr = _ema_arr(closes, 21)

        results = []; bars_since = 999
        for i in range(50, n - 1):
            wp       = body_pcts[max(0, i-500):i+1]
            giga_thr = float(np.percentile(wp, cfg['percentile']))
            bp       = body_pcts[i]
            is_giga  = bp >= giga_thr and bp >= cfg['min_body_pct']
            is_green = closes[i] > opens[i]
            is_red   = closes[i] < opens[i]
            rsi      = float(rsi_arr[i])
            tb       = ema9_arr[i] > ema21_arr[i]
            td       = ema9_arr[i] < ema21_arr[i]
            cr       = highs[i] - lows[i]
            uw       = float((highs[i] - max(opens[i], closes[i])) / cr) if cr > 0 else 0
            lw       = float((min(opens[i], closes[i]) - lows[i]) / cr) if cr > 0 else 0
            cooldown = bars_since >= cfg['cooldown_bars']
            use_t    = cfg.get('use_trend')
            use_w    = cfg.get('use_wick')
            mwr      = cfg.get('min_wick_ratio', 0)
            sig = None
            if is_giga and cooldown:
                if is_green and rsi >= cfg['rsi_overbought'] and (tb if use_t else True) and (uw >= mwr if use_w else True):
                    sig = 'BEAR'
                elif is_red and rsi <= cfg['rsi_oversold'] and (td if use_t else True) and (lw >= mwr if use_w else True):
                    sig = 'BULL'
            if sig:
                bars_since = 0
                nc = candles[i+1]
                ok = (sig=='BEAR' and nc['close'] < candles[i]['close']) or (sig=='BULL' and nc['close'] > candles[i]['close'])
                results.append({'correct': ok, 'signal': sig})
            else:
                bars_since += 1

        tot  = len(results)
        wins = sum(1 for r in results if r['correct'])
        wr   = round(wins/tot*100, 1) if tot > 0 else 0
        ev   = round(wr/100*75 - (100-wr)/100*100, 2) if tot > 0 else 0
        return {'total': tot, 'wins': wins, 'losses': tot-wins,
                'win_rate': wr, 'ev': ev,
                'signals_per_day': round(tot/max(days_,1),1)}

    # ── Indicator helpers ────────────────────────────────────────────────────
    def _stoch_arr(highs, lows, closes, period=14):
        """Stochastic %K — same as ta.stoch(close, high, low, period)."""
        n = len(closes)
        k = np.full(n, 50.0)
        for i in range(period - 1, n):
            lo = lows[i - period + 1:i + 1].min()
            hi = highs[i - period + 1:i + 1].max()
            k[i] = (closes[i] - lo) / (hi - lo) * 100 if hi > lo else 50.0
        return k

    def _sma_arr(prices, period):
        n = len(prices)
        out = np.full(n, prices[0])
        for i in range(period - 1, n):
            out[i] = prices[i - period + 1:i + 1].mean()
        return out

    def _std_arr(prices, period):
        n = len(prices)
        out = np.zeros(n)
        for i in range(period - 1, n):
            out[i] = prices[i - period + 1:i + 1].std(ddof=0)
        return out

    def _macd_hist_arr(closes):
        """MACD histogram: EMA12 - EMA26 - EMA9(EMA12-EMA26)."""
        ema12 = _ema_arr(closes, 12)
        ema26 = _ema_arr(closes, 26)
        macd  = ema12 - ema26
        sig   = _ema_arr(macd, 9)
        return macd - sig

    # ── Contrarian V8 engine (BTC/SOL/ETH/XRP Contrarian) ───────────────────
    def _parse_contrarian_v8(code):
        import re
        def _int(label, default):
            m = re.search(r'input\.int\s*\(\s*(\d+)\s*,\s*"' + re.escape(label) + r'"', code, re.I)
            return int(m.group(1)) if m else default
        def _bool(label, default):
            m = re.search(r'input\.bool\s*\((true|false)\s*,\s*"' + re.escape(label) + r'"', code, re.I)
            return (m.group(1).lower() == 'true') if m else default
        def _float_lit(pattern, default):
            m = re.search(pattern, code)
            return float(m.group(1)) if m else default
        return {
            'score_threshold':  _int('Score Threshold', 5),
            'rsi_ext_low':      _int('RSI Extreme Low', 20),
            'rsi_ext_high':     _int('RSI Extreme High', 80),
            'rsi_mod_low':      _int('RSI Moderate Low', 35),
            'rsi_mod_high':     _int('RSI Moderate High', 65),
            'stoch_os':         _int('Stoch Oversold', 20),
            'stoch_ob':         _int('Stoch Overbought', 80),
            'cooldown_bars':    _int('Cooldown Bars', 2),
            'use_macd':         _bool('Use MACD Filter', True),
            'use_contrarian':   _bool('Contrarian Mode (vs Trend)', True),
            'invert_signals':   _bool('INVERT Signals (Momentum Mode)', True) or _bool('INVERT Signals', False),
            'bb_mult':          _float_lit(r'bb_basis\s*\+\s*([\d.]+)\s*\*\s*bb_std', 2.0),
        }

    def _run_contrarian_v8(candles, cfg, name, days_):
        n      = len(candles)
        closes = np.array([c['close'] for c in candles])
        opens  = np.array([c['open']  for c in candles])
        highs  = np.array([c['high']  for c in candles])
        lows   = np.array([c['low']   for c in candles])

        rsi_arr   = _wilder_rsi_arr(closes, 14)
        ema21_arr = _ema_arr(closes, 21)
        ema50_arr = _ema_arr(closes, 50)
        stoch_arr = _stoch_arr(highs, lows, closes, 14)
        macd_hist = _macd_hist_arr(closes)
        sma20     = _sma_arr(closes, 20)
        std20     = _std_arr(closes, 20)
        bb_upper  = sma20 + cfg['bb_mult'] * std20
        bb_lower  = sma20 - cfg['bb_mult'] * std20

        sc  = cfg['score_threshold']
        results = []; bars_since = 999

        for i in range(50, n - 1):
            rsi  = rsi_arr[i];  rsi_prev = rsi_arr[i-1]
            stk  = stoch_arr[i]
            mh   = macd_hist[i]; mh_prev = macd_hist[i-1]
            cls  = closes[i];   opn = opens[i]
            clsp = closes[i-1]; opnp = opens[i-1]
            hi   = highs[i];    lo = lows[i]
            hip  = highs[i-1];  lop = lows[i-1]
            bbu  = bb_upper[i]; bbl = bb_lower[i]
            e21  = ema21_arr[i]; e50 = ema50_arr[i]

            body  = abs(cls - opn);  body_prev = abs(clsp - opnp)
            uw    = hi - max(opn, cls);  lw = min(opn, cls) - lo
            is_g  = cls > opn;  is_r = cls < opn
            pg    = clsp > opnp;  pr = clsp < opnp

            hammer = lw > 2*body and uw < 0.5*body and body > 0
            star   = uw > 2*body and lw < 0.5*body and body > 0
            bull_eng = pr and is_g and body > body_prev and opn <= clsp
            bear_eng = pg and is_r and body > body_prev and opn >= clsp

            macd_up = mh > mh_prev;  macd_dn = mh < mh_prev
            use_m = cfg['use_macd']

            # Bull exhaustion
            rsi_bull_ext = rsi < cfg['rsi_ext_low']
            rsi_bull_mod = rsi < cfg['rsi_mod_low'] and rsi > rsi_prev
            rsi_cond_b   = rsi_bull_ext or rsi_bull_mod
            osc_cond_b   = (stk < cfg['stoch_os']) or (cls <= bbl)
            macd_b       = (macd_up if use_m else True)
            bull_exh     = rsi_cond_b and osc_cond_b and macd_b

            # Bear exhaustion
            rsi_bear_ext = rsi > cfg['rsi_ext_high']
            rsi_bear_mod = rsi > cfg['rsi_mod_high'] and rsi < rsi_prev
            rsi_cond_r   = rsi_bear_ext or rsi_bear_mod
            osc_cond_r   = (stk > cfg['stoch_ob']) or (cls >= bbu)
            macd_r       = (macd_dn if use_m else True)
            bear_exh     = rsi_cond_r and osc_cond_r and macd_r

            bs = (3 if bull_exh else 0) + (2 if hammer else 0) + (2 if bull_eng else 0) + \
                 (1 if (rsi < 40 and (macd_up if use_m else True)) else 0) + \
                 (1 if stk < cfg['stoch_os'] else 0) + (1 if cls <= bbl else 0)
            rs = (3 if bear_exh else 0) + (2 if star else 0) + (2 if bear_eng else 0) + \
                 (1 if (rsi > 60 and (macd_dn if use_m else True)) else 0) + \
                 (1 if stk > cfg['stoch_ob'] else 0) + (1 if cls >= bbu else 0)

            bull_raw = bs >= sc;  bear_raw = rs >= sc
            trend_b = e21 > e50;  trend_r = e21 < e50
            use_c = cfg['use_contrarian']
            bull_f = (bull_raw and trend_r) if use_c else bull_raw
            bear_f = (bear_raw and trend_b) if use_c else bear_raw
            # conflict resolution
            bull_sig = bull_f and not (bear_f and rs > bs)
            bear_sig = bear_f and not (bull_f and bs >= rs)

            if bars_since < cfg['cooldown_bars']:
                bull_sig = False; bear_sig = False

            inv = cfg['invert_signals']
            final_bull = bear_sig if inv else bull_sig
            final_bear = bull_sig if inv else bear_sig

            if final_bull or final_bear:
                bars_since = 0
                nc = candles[i + 1]
                if final_bull:
                    ok = nc['close'] > closes[i]
                    results.append({'correct': ok})
                if final_bear:
                    ok = nc['close'] < closes[i]
                    results.append({'correct': ok})
            else:
                bars_since += 1

        tot  = len(results)
        wins = sum(1 for r in results if r['correct'])
        wr   = round(wins / tot * 100, 1) if tot > 0 else 0
        ev   = round(wr / 100 * 75 - (100 - wr) / 100 * 100, 2) if tot > 0 else 0
        return {'total': tot, 'wins': wins, 'losses': tot - wins,
                'win_rate': wr, 'ev': ev, 'signals_per_day': round(tot / max(days_, 1), 1)}

    # ── Exhaustion engine (BTC_Exhaustion_15m_Polymarket style) ─────────────
    def _parse_exhaustion(code):
        import re
        def _int(label, default):
            m = re.search(r'input\.int\s*\(\s*(\d+)\s*,\s*"' + re.escape(label) + r'"', code, re.I)
            return int(m.group(1)) if m else default
        def _float(label, default):
            m = re.search(r'input\.float\s*\(\s*([\d.]+)\s*,\s*"' + re.escape(label) + r'"', code, re.I)
            return float(m.group(1)) if m else default
        def _bool(label, default):
            m = re.search(r'input\.bool\s*\((true|false)\s*,\s*"' + re.escape(label) + r'"', code, re.I)
            return (m.group(1).lower() == 'true') if m else default
        return {
            'score_thresh':  _int('Score Threshold', 7),
            'rsi_period':    _int('RSI Period', 7),
            'rsi_extreme':   _int('RSI Extreme Level', 20),
            'rsi_moderate':  _int('RSI Moderate Level', 35),
            'stoch_thresh':  _int('Stoch OB/OS Level', 15),
            'bb_period':     _int('BB Period', 20),
            'bb_mult':       _float('BB Std Dev', 2.0),
            'use_wicks':     _bool('Use Wick Patterns (hammer/star)', True),
            'use_consec':    _bool('Use 3-Bar Consecutive Filter', True),
        }

    def _run_exhaustion(candles, cfg, name, days_):
        n      = len(candles)
        closes = np.array([c['close'] for c in candles])
        opens  = np.array([c['open']  for c in candles])
        highs  = np.array([c['high']  for c in candles])
        lows   = np.array([c['low']   for c in candles])

        rp  = cfg['rsi_period']
        bp  = cfg['bb_period']
        rsi_a = _wilder_rsi_arr(closes, rp)
        stk_a = _stoch_arr(highs, lows, closes, 14)
        std_a = _std_arr(closes, bp)
        sma_a = _sma_arr(closes, bp)
        bb_u  = sma_a + cfg['bb_mult'] * std_a
        bb_l  = sma_a - cfg['bb_mult'] * std_a

        sc = cfg['score_thresh']
        re_ = cfg['rsi_extreme']; rm = cfg['rsi_moderate']
        st  = cfg['stoch_thresh']
        results = []

        for i in range(50, n - 1):
            rsi  = rsi_a[i]; rsi_p = rsi_a[i-1]
            stk  = stk_a[i]
            stk3 = stk_a[max(0,i-2):i+1]
            std_k = stk_a[max(0,i-2):i+1].mean() if len(stk_a[max(0,i-2):i+1]) else stk
            cls  = closes[i]; opn = opens[i]
            body = abs(cls - opn)
            uw   = highs[i] - max(opn, cls)
            lw   = min(opn, cls) - lows[i]
            bs   = body if body > 0 else 1e-9

            three_dn = all(closes[max(0,i-j)] < closes[max(0,i-j-1)] for j in range(3))
            three_up = all(closes[max(0,i-j)] > closes[max(0,i-j-1)] for j in range(3))

            bull_s = 0; bear_s = 0
            # RSI (0-3)
            bull_s += 3 if rsi < re_ else (2 if rsi < rm else (1 if rsi < rm+5 and rsi > rsi_p else 0))
            bear_s += 3 if rsi > 100-re_ else (2 if rsi > 100-rm else (1 if rsi > 100-rm-5 and rsi < rsi_p else 0))
            # Stoch (0-3)
            stk_d = stk_a[max(0,i-2):i+1].mean()
            bull_s += 2 if stk < st else 0
            bull_s += 1 if stk < st and stk_d < st and stk > stk_d else 0
            bear_s += 2 if stk > 100-st else 0
            bear_s += 1 if stk > 100-st and stk_d > 100-st and stk < stk_d else 0
            # BB (0-2)
            bull_s += 2 if cls <= bb_l[i] else 0
            bear_s += 2 if cls >= bb_u[i] else 0
            # Consecutive (0-2)
            if cfg['use_consec']:
                bull_s += 2 if three_dn else 0
                bear_s += 2 if three_up else 0
            # Wicks (0-2)
            if cfg['use_wicks']:
                hammer = lw > 2*body and uw < 0.5*body and body > 0
                star   = uw > 2*body and lw < 0.5*body and body > 0
                bull_s += 2 if hammer else 0
                bear_s += 2 if star   else 0

            final_bull = bull_s >= sc and not (bear_s >= sc and bear_s > bull_s)
            final_bear = bear_s >= sc and not (bull_s >= sc and bull_s >= bear_s)

            if final_bull:
                ok = candles[i+1]['close'] > cls
                results.append({'correct': ok})
            if final_bear:
                ok = candles[i+1]['close'] < cls
                results.append({'correct': ok})

        tot  = len(results)
        wins = sum(1 for r in results if r['correct'])
        wr   = round(wins / tot * 100, 1) if tot > 0 else 0
        ev   = round(wr / 100 * 75 - (100 - wr) / 100 * 100, 2) if tot > 0 else 0
        return {'total': tot, 'wins': wins, 'losses': tot - wins,
                'win_rate': wr, 'ev': ev, 'signals_per_day': round(tot / max(days_, 1), 1)}

    # ── Momentum Reversal engine (BTC_MomentumReversal_15m_Polymarket) ───────
    def _parse_momentum_reversal(code):
        import re
        def _int(label, default):
            m = re.search(r'input\.int\s*\(\s*(\d+)\s*,\s*"' + re.escape(label) + r'"', code, re.I)
            return int(m.group(1)) if m else default
        def _float(label, default):
            m = re.search(r'input\.float\s*\(\s*([\d.]+)\s*,\s*"' + re.escape(label) + r'"', code, re.I)
            return float(m.group(1)) if m else default
        return {
            'rsi_period':   _int('RSI Period', 7),
            'rsi_ob':       _int('RSI Overbought Level', 60),
            'rsi_os':       _int('RSI Oversold Level', 40),
            'body_min':     _float('Min Body % of Price', 0.4),
            'range_pos_t':  _float('Range Position %', 85.0),
        }

    def _run_momentum_reversal(candles, cfg, name, days_):
        n      = len(candles)
        closes = np.array([c['close'] for c in candles])
        opens  = np.array([c['open']  for c in candles])
        highs  = np.array([c['high']  for c in candles])
        lows   = np.array([c['low']   for c in candles])

        rsi_a = _wilder_rsi_arr(closes, cfg['rsi_period'])
        results = []

        for i in range(10, n - 1):
            rsi = rsi_a[i]
            cls = closes[i]; opn = opens[i]
            body_pct = abs(cls - opn) / cls * 100 if cls > 0 else 0

            hi5 = highs[max(0, i-4):i+1].max()
            lo5 = lows[max(0, i-4):i+1].min()
            rng5 = hi5 - lo5
            range_pos = (cls - lo5) / rng5 * 100 if rng5 > 0 else 50.0

            four_up = (closes[i] > closes[i-1] > closes[i-2] > closes[i-3] > closes[i-4])
            four_dn = (closes[i] < closes[i-1] < closes[i-2] < closes[i-3] < closes[i-4])

            obought = rsi > cfg['rsi_ob'] and body_pct > cfg['body_min'] and range_pos > cfg['range_pos_t'] and four_up
            osold   = rsi < cfg['rsi_os'] and body_pct > cfg['body_min'] and range_pos < (100 - cfg['range_pos_t']) and four_dn

            if osold:   # predict UP
                ok = candles[i+1]['close'] > cls
                results.append({'correct': ok})
            if obought: # predict DOWN
                ok = candles[i+1]['close'] < cls
                results.append({'correct': ok})

        tot  = len(results)
        wins = sum(1 for r in results if r['correct'])
        wr   = round(wins / tot * 100, 1) if tot > 0 else 0
        ev   = round(wr / 100 * 75 - (100 - wr) / 100 * 100, 2) if tot > 0 else 0
        return {'total': tot, 'wins': wins, 'losses': tot - wins,
                'win_rate': wr, 'ev': ev, 'signals_per_day': round(tot / max(days_, 1), 1)}

    # ── Algo type detector ───────────────────────────────────────────────────
    def _detect_and_run(candles, code, name, days_):
        """Route to the right backtest engine based on Pine Script content."""
        if 'four_up' in code and 'four_dn' in code and 'range_pos' in code:
            cfg = _parse_momentum_reversal(code)
            return _run_momentum_reversal(candles, cfg, name, days_)
        elif 'score_threshold' in code and 'rsi_extreme_low' in code:
            cfg = _parse_contrarian_v8(code)
            return _run_contrarian_v8(candles, cfg, name, days_)
        elif 'score_thresh' in code and 'use_consec' in code:
            cfg = _parse_exhaustion(code)
            return _run_exhaustion(candles, cfg, name, days_)
        else:
            cfg = parse_pinescript_config(code)
            return _run_one(candles, cfg, name, days_)

    # ── Built-in strategy runner (bar-by-bar using class .analyze()) ──
    def _run_builtin(analyzer, candles, days_, sym_='TEST'):
        results = []
        n = len(candles)
        bars_since = 999
        for i in range(50, n - 1):
            window = candles[max(0, i - 299):i + 1]
            try:
                a = analyzer.analyze(window, sym_)
            except Exception:
                bars_since += 1
                continue
            if a['signal'] != 'NEUTRAL' and bars_since >= 2:
                nc  = candles[i + 1]
                sig = a['signal']
                ok  = (sig == 'BEARISH' and nc['close'] < candles[i]['close']) or \
                      (sig == 'BULLISH' and nc['close'] > candles[i]['close'])
                results.append({'correct': ok})
                bars_since = 0
            else:
                bars_since += 1
        tot  = len(results)
        wins = sum(1 for r in results if r['correct'])
        wr   = round(wins / tot * 100, 1) if tot > 0 else 0
        ev   = round(wr / 100 * 75 - (100 - wr) / 100 * 100, 2) if tot > 0 else 0
        return {'total': tot, 'wins': wins, 'losses': tot - wins,
                'win_rate': wr, 'ev': ev,
                'signals_per_day': round(tot / max(days_, 1), 1)}

    # DogeV1 wrapper: analyze_doge_v1 is a method, not a standalone class
    class _DogeV1BT:
        def __init__(self):
            self._giga = FadeGigaAnalyzer()
        def analyze(self, candles, symbol):
            return self._giga.analyze_doge_v1(candles, symbol)

    # (name, analyzer, id, valid_tfs, valid_syms)
    # valid_tfs  — only run against these timeframes
    # valid_syms — None = all symbols; list = restrict
    BUILTIN_STRATEGIES = [
        ('GigaV35',         FadeGigaAnalyzer(),              'builtin-gigav35',          ['15m'], None),
        ('DogeV1',          _DogeV1BT(),                     'builtin-dogev1',            ['15m'], ['BTC', 'ETH']),
        ('BTC5m-FadeGiga',  FadeGigaBTC5m(),                 'builtin-btc5m-fadegiga',   ['5m'],  None),
        ('ETH5m-QUALITY',   FadeGigaETH5m(mode='QUALITY'),  'builtin-eth5m-quality',    ['5m'],  None),
        ('ETH5m-HIGH_FREQ', FadeGigaETH5m(mode='HIGH_FREQ'),'builtin-eth5m-highfreq',   ['5m'],  None),
        ('SOL5m-BALANCED',  FadeGigaSOL5m(mode='BALANCED'), 'builtin-sol5m-balanced',   ['5m'],  None),
        ('SOL5m-SNIPER',    FadeGigaSOL5m(mode='SNIPER'),   'builtin-sol5m-sniper',     ['5m'],  None),
    ]

    # Count only valid combos for accurate progress tracking
    builtin_combos = sum(
        1 for (_, _, _, vtfs, vsyms) in BUILTIN_STRATEGIES
        for sym in SYMBOLS for tf in TIMEFRAMES
        if tf in vtfs and (vsyms is None or sym in vsyms)
    )
    _max_bt_job['total'] += builtin_combos

    all_results = []
    done = 0
    for algo in algo_list:
        algo_name = algo.get('name', 'Untitled')
        algo_id   = algo.get('id', '')
        code      = algo.get('code', '')
        for sym in SYMBOLS:
            for tf in TIMEFRAMES:
                _max_bt_job['current'] = f'{algo_name} · {sym} {tf}'
                candles = candle_cache.get((sym, tf), [])
                if candles:
                    try:
                        res = _detect_and_run(candles, code, algo_name, days)
                        row = {'algo_id': algo_id, 'algo_name': algo_name,
                               'symbol': sym, 'tf': tf, **res}
                        all_results.append(row)
                    except Exception as e:
                        logger.warning(f"[MAX-BT] {algo_name} {sym} {tf}: {e}")
                done += 1
                _max_bt_job['progress'] = done

    # ── Built-in strategy mode sweep ─────────────────────────────────
    for (strat_name, analyzer, strat_id, valid_tfs, valid_syms) in BUILTIN_STRATEGIES:
        for sym in SYMBOLS:
            for tf in TIMEFRAMES:
                if tf not in valid_tfs:
                    continue
                if valid_syms is not None and sym not in valid_syms:
                    continue
                _max_bt_job['current'] = f'{strat_name} · {sym} {tf}'
                candles = candle_cache.get((sym, tf), [])
                if candles:
                    try:
                        res = _run_builtin(analyzer, candles, days, sym)
                        all_results.append({
                            'algo_id': strat_id, 'algo_name': strat_name,
                            'symbol': sym, 'tf': tf, **res
                        })
                    except Exception as e:
                        logger.warning(f"[MAX-BT] {strat_name} {sym} {tf}: {e}")
                done += 1
                _max_bt_job['progress'] = done

    # Sort all results by win rate desc, EV desc
    all_results.sort(key=lambda x: (x['win_rate'], x['ev']), reverse=True)
    winners = [r for r in all_results
               if r['total'] >= MIN_SIGNALS and r['win_rate'] >= MIN_WR and r['ev'] > 0]

    # Log winners to file
    log_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'max_backtest_results.json')
    try:
        with open(log_path, 'w', encoding='utf-8') as f:
            json.dump({'days': days, 'timestamp': datetime.now().isoformat(),
                       'all': all_results, 'winners': winners}, f, indent=2)
        logger.info(f"[MAX-BT] Done. {len(winners)} winners logged to {log_path}")
    except Exception as e:
        logger.warning(f"[MAX-BT] Could not write results file: {e}")

    _max_bt_job.update({'running': False, 'done': True,
                        'results': all_results, 'winners': winners})


@app.route('/api/backtest-max', methods=['POST'])
def start_max_backtest():
    global _max_bt_job
    if _max_bt_job['running']:
        return jsonify({'error': 'Already running'})
    days = int(request.json.get('days', 30) if request.json else 30)
    t = threading.Thread(target=_run_max_backtest, args=(days,), daemon=True)
    t.start()
    return jsonify({'success': True, 'message': 'Max backtest started'})


