@app.route('/api/debug-eth5m')
def debug_eth5m():
    """Show why the last ETH 5m candle did/didn't fire a signal."""
    global prediction_bot
    if not prediction_bot:
        return jsonify({'error': 'Bot not initialized'})
    try:
        candles = prediction_bot.data_fetcher.get_5min_candles('ETH', num_candles=300)
        if not candles or len(candles) < 50:
            return jsonify({'error': 'Not enough candles'})

        cfg = prediction_bot.eth_5m_analyzer.CONFIGS[prediction_bot.eth_5m_analyzer.mode]
        closes  = [c['close'] for c in candles]
        opens   = [c['open']  for c in candles]
        highs   = [c['high']  for c in candles]
        lows    = [c['low']   for c in candles]
        volumes = [c.get('volume', 0) for c in candles]

        # Check last 5 closed candles (index -5 to -2, skip current forming bar at -1)
        bar_idx = int(request.args.get('bar', -2))  # default: last CLOSED candle
        last = candles[bar_idx]
        prev = candles[bar_idx - 1]

        body_pcts = [abs(c['close']-c['open'])/c['open']*100 if c['open']>0 else 0 for c in candles]
        # Use window up to this bar
        end_idx = len(candles) + bar_idx + 1 if bar_idx < 0 else bar_idx + 1
        window = body_pcts[max(0,end_idx-200):end_idx]
        giga_thresh = float(np.percentile(window, cfg['giga_pct'], method='lower'))

        body_pct   = body_pcts[bar_idx]
        is_green   = last['close'] > last['open']
        bar_range  = last['high'] - last['low']
        body_size  = abs(last['close'] - last['open'])
        upper_wick = last['high'] - max(last['open'], last['close'])
        close_pos  = (last['close'] - last['low']) / bar_range if bar_range > 0 else 0.5

        closes_to  = closes[:end_idx]
        volumes_to = volumes[:end_idx]
        rsi = prediction_bot.eth_5m_analyzer.indicators.calculate_rsi(closes_to, cfg['rsi_length'])

        vol_sma  = float(np.mean(volumes_to[-cfg['vol_len']:])) if len(volumes_to) >= cfg['vol_len'] else 0
        vol_ratio = volumes_to[-1] / vol_sma if vol_sma > 0 else 0

        highs_to = highs[:end_idx]; lows_to = lows[:end_idx]
        recent_high = max(highs_to[-20:])
        recent_low  = min(lows_to[-20:])
        rng20 = recent_high - recent_low
        near_top_val = ((last['close'] - recent_low) / rng20) if rng20 > 0 else 0

        wick_ratio_val = upper_wick / body_size if body_size > 0 else 0
        prev_green = prev['close'] > prev['open']
        
        from datetime import datetime, timezone
        bar_time = datetime.fromtimestamp(last['timestamp']/1000, tz=timezone.utc).strftime('%H:%M UTC')

        def b(v): return bool(v)  # ensure native bool
        checks = {
            'mode': prediction_bot.eth_5m_analyzer.mode,
            'last_candle': {
                'time': int(last['timestamp']), 'time_str': bar_time, 'bar_index': bar_idx,
                'open': round(last['open'],4), 'close': round(last['close'],4),
                'high': round(last['high'],4),  'low': round(last['low'],4),
                'volume': round(last.get('volume', 0),2)
            },
            'checks': {
                'is_giga':     {'pass': b(body_pct >= giga_thresh and body_pct >= cfg['min_body']),
                                'body_pct': round(body_pct,3), 'threshold': round(giga_thresh,3)},
                'is_green':    {'pass': b(is_green)},
                'rsi':         {'pass': b(rsi >= cfg['rsi_thresh']), 'value': round(rsi,1), 'needed': cfg['rsi_thresh']},
                'volume':      {'pass': b(vol_ratio >= cfg['vol_mult']), 'ratio': round(vol_ratio,2), 'needed': cfg['vol_mult']},
                'wick':        {'pass': b(wick_ratio_val >= cfg['wick_ratio']), 'value': round(wick_ratio_val,2), 'needed': cfg['wick_ratio']},
                'strong_close':{'pass': b(close_pos >= cfg['sc_thresh']), 'value': round(close_pos,3), 'needed': cfg['sc_thresh']},
                'near_top':    {'pass': b(near_top_val >= 0.80), 'value': round(near_top_val,3), 'needed': 0.80, 'used': b(cfg['use_near_top'])},
                'prev_green':  {'pass': b(prev_green), 'used': b(cfg['use_prev_green'])},
            },
            'would_fire': b(all([
                body_pct >= giga_thresh and body_pct >= cfg['min_body'],
                is_green, rsi >= cfg['rsi_thresh'],
                vol_ratio >= cfg['vol_mult'],
                wick_ratio_val >= cfg['wick_ratio'],
                close_pos >= cfg['sc_thresh'],
                near_top_val >= 0.80 if cfg['use_near_top'] else True,
                prev_green if cfg['use_prev_green'] else True,
            ]))
        }
        return jsonify(checks)
    except Exception as e:
        return jsonify({'error': str(e)})


