@app.route('/api/backtest-btc5m')
def backtest_btc5m():
    """Backtest BTC 5m Fade Giga v3 on real Binance data and return optimization results."""
    global prediction_bot
    if not prediction_bot:
        return jsonify({'error': 'Bot not initialized'})
    try:
        import time as _t
        days = int(request.args.get('days', 30))
        num_candles = min(days * 288, 8640)  # 288 5m candles/day

        # Fetch BTC 5m from Binance
        all_candles = []
        end_time = int(_t.time() * 1000)
        remaining = num_candles
        while remaining > 0:
            batch = min(remaining, 1000)
            r = requests.get('https://api.binance.com/api/v3/klines', timeout=15, params={
                'symbol':'BTCUSDC','interval':'5m','limit':batch,'endTime':end_time
            })
            if r.status_code != 200 or not r.json(): break
            data = r.json()
            candles = [{'timestamp':c[0],'open':float(c[1]),'high':float(c[2]),
                        'low':float(c[3]),'close':float(c[4]),'volume':float(c[5])} for c in data]
            all_candles = candles + all_candles
            end_time = data[0][0] - 1
            remaining -= len(candles)
            if len(candles) < batch: break

        if len(all_candles) < 100:
            return jsonify({'error': f'Only {len(all_candles)} candles'})

        cfg = prediction_bot.btc_5m_analyzer.CONFIG

        def run_backtest(candles, override=None):
            c = dict(cfg, **(override or {}))
            dn_res, up_res = [], []
            for i in range(50, len(candles)-1):
                body_pcts = [abs(x['close']-x['open'])/x['open']*100 if x['open']>0 else 0
                             for x in candles[max(0,i-199):i+1]]
                giga_thresh = float(np.percentile(body_pcts, c['giga_pct']))
                last = candles[i]
                body_pct = body_pcts[-1]
                is_green = last['close'] > last['open']
                is_red   = last['close'] < last['open']
                body_size = abs(last['close']-last['open'])
                up_wick = last['high'] - max(last['open'],last['close'])
                dn_wick = min(last['open'],last['close']) - last['low']
                is_giga = body_pct >= giga_thresh and body_pct >= c['min_body']
                closes = [x['close'] for x in candles[:i+1]]
                rsi = prediction_bot.btc_5m_analyzer.indicators.calculate_rsi(closes, c['rsi_length'])
                volumes = [x.get('volume',0) for x in candles[:i+1]]
                vol_sma = float(np.mean(volumes[-c['vol_len']:])) if len(volumes)>=c['vol_len'] else 0
                vol_ratio = volumes[-1]/vol_sma if vol_sma>0 else 0
                has_up_wick = (up_wick >= body_size*c['wick_ratio']) if body_size>0 else False
                has_dn_wick = (dn_wick >= body_size*c['wick_ratio']) if body_size>0 else False
                ema100 = prediction_bot.btc_5m_analyzer.indicators.calculate_ema(closes, c['trend_ema_len'])
                in_down = last['close'] < ema100[-1]
                dn_sig = is_giga and is_green and rsi>=c['rsi_ob'] and vol_ratio>=c['vol_mult'] and has_up_wick
                up_sig = c['enable_up'] and is_giga and is_red and rsi<=c['rsi_os'] and vol_ratio>=c['vol_mult'] and has_dn_wick and in_down
                nxt = candles[i+1]
                if dn_sig: dn_res.append(bool(nxt['close'] < last['close']))
                if up_sig: up_res.append(bool(nxt['close'] > last['close']))
            return dn_res, up_res

        # Run base config
        dn, up = run_backtest(all_candles)
        dn_wr = round(sum(dn)/len(dn)*100,1) if dn else 0
        up_wr = round(sum(up)/len(up)*100,1) if up else 0

        # Optimize wick ratio on first half
        half = all_candles[:len(all_candles)//2]
        wick_opts = []
        for wr in [0.3,0.4,0.5,0.6,0.7,0.8,1.0,1.2]:
            d, _ = run_backtest(half, {'wick_ratio':wr})
            if d: wick_opts.append({'wick_ratio':wr,'signals':len(d),'wr':round(sum(d)/len(d)*100,1)})

        # Optimize vol multiplier
        vol_opts = []
        for vm in [1.2,1.5,1.7,2.0,2.5,3.0]:
            d, _ = run_backtest(half, {'vol_mult':vm})
            if d: vol_opts.append({'vol_mult':vm,'signals':len(d),'wr':round(sum(d)/len(d)*100,1)})

        # Validate best params on second half (walk-forward)
        best_wick = max(wick_opts, key=lambda x: x['wr']*min(x['signals'],10)) if wick_opts else {'wick_ratio':0.6}
        best_vol  = max(vol_opts,  key=lambda x: x['wr']*min(x['signals'],10)) if vol_opts  else {'vol_mult':1.7}
        dn_wf, _ = run_backtest(all_candles[len(all_candles)//2:],
                                 {'wick_ratio':best_wick['wick_ratio'],'vol_mult':best_vol['vol_mult']})
        wf_wr = round(sum(dn_wf)/len(dn_wf)*100,1) if dn_wf else 0

        return jsonify({
            'candles': len(all_candles), 'days': days,
            'base': {'dn_wr': dn_wr, 'dn_signals': len(dn), 'up_wr': up_wr, 'up_signals': len(up)},
            'wick_optimization': wick_opts,
            'vol_optimization':  vol_opts,
            'best_params': {'wick_ratio': best_wick['wick_ratio'], 'vol_mult': best_vol['vol_mult']},
            'walkforward_wr': wf_wr, 'walkforward_signals': len(dn_wf)
        })
    except Exception as e:
        logger.error(f"BTC5m backtest error: {e}")
        return jsonify({'error': str(e)})


