@app.route('/api/backtest-5m/<symbol>')
def backtest_5m_symbol(symbol):
    """Backtest 5m strategies on historical candles — uses dedicated per-symbol analyzers."""
    import time as _t
    symbol = symbol.upper()
    if symbol not in ['BTC','ETH','SOL','XRP','DOGE','HYPE','BNB']:
        return jsonify({'error': 'Invalid symbol'})
    days = int(request.args.get('days', 30))
    num_candles = min(days * 288, 8640)  # 288 5m candles/day

    try:
        # HYPE is not on Binance — use Hyperliquid directly
        if symbol == 'HYPE':
            all_candles = _fetch_hl_candles_paginated('HYPE', '5m', num_candles)
        else:
            binance_map = {'BTC':'BTCUSDT','ETH':'ETHUSDT','SOL':'SOLUSDT',
                           'XRP':'XRPUSDT','DOGE':'DOGEUSDT','BNB':'BNBUSDT'}
            b_sym = binance_map.get(symbol)
            if not b_sym:
                return jsonify({'error': 'No data source for symbol'})

            all_candles = []
            end_time = int(_t.time() * 1000)
            remaining = num_candles
            while remaining > 0:
                batch = min(remaining, 1000)
                r = requests.get('https://api.binance.com/api/v3/klines', timeout=15, params={
                    'symbol': b_sym, 'interval': '5m', 'limit': batch, 'endTime': end_time
                })
                if r.status_code != 200 or not r.json(): break
                data = r.json()
                candles = [{'timestamp':c[0],'open':float(c[1]),'high':float(c[2]),
                            'low':float(c[3]),'close':float(c[4]),'volume':float(c[5])} for c in data]
                all_candles = candles + all_candles
                end_time = data[0][0] - 1
                remaining -= len(candles)
                if len(candles) < batch: break

        if len(all_candles) < 100:
            return jsonify({'error': f'Not enough data ({len(all_candles)} candles)'})

        logger.info(f"[BT5M] {symbol}: {len(all_candles)} candles")

        def run_strategy(candles, analyzer, strategy_name):
            results = []
            for i in range(50, len(candles)-1):
                window = candles[:i+1]
                data = analyzer.analyze(window, symbol)
                if data['signal'] != 'NEUTRAL':
                    nxt  = candles[i+1]
                    last = candles[i]
                    if data['signal'] == 'BEARISH':
                        correct = nxt['close'] < last['close']
                    else:
                        correct = nxt['close'] > last['close']
                    results.append({
                        'ts': last['timestamp'],
                        'signal': data['signal'],
                        'correct': correct,
                        'entry': last['close'],
                        'exit':  nxt['close'],
                        'rsi': data['indicators'].get('rsi', 0),
                    })
            total  = len(results)
            wins   = sum(1 for r in results if r['correct'])
            losses = total - wins
            wr     = round(wins/total*100, 1) if total > 0 else 0
            ev     = round(wr/100*75 - (100-wr)/100*100, 2) if total > 0 else 0
            total_ret = wins*75 - losses*100
            # Streak
            cur = 0
            for r in results:
                cur = (cur+1 if cur>=0 else 1) if r['correct'] else (cur-1 if cur<=0 else -1)
            return {
                'strategy': strategy_name, 'total': total, 'wins': wins, 'losses': losses,
                'win_rate': wr, 'ev': ev, 'total_return': total_ret,
                'streak': cur, 'signals_per_day': round(total/max(days,1),1),
                'signals': results[-20:]
            }

        stats = {}

        # Pick the right analyzer(s) per symbol
        if symbol == 'BTC':
            stats['btc_5m_v3'] = run_strategy(all_candles, prediction_bot.btc_5m_analyzer, 'BTC 5m v3')
        elif symbol == 'ETH':
            stats['eth_5m_hf'] = run_strategy(all_candles, prediction_bot.eth_5m_analyzer, 'ETH 5m HF')
            stats['sol_on_eth'] = run_strategy(all_candles, prediction_bot.eth_5m_sol_analyzer, f'SOL-strat on ETH ({prediction_bot.eth_5m_sol_analyzer.mode})')
        elif symbol == 'SOL':
            stats['sol_5m'] = run_strategy(all_candles, prediction_bot.sol_5m_analyzer, f'SOL 5m ({prediction_bot.sol_5m_analyzer.mode})')
        else:
            # Standard giga on 5m
            class _Wrapper:
                def analyze(self, c, s): return prediction_bot.fade_giga_analyzer.analyze(c, s)
            stats['giga_v35_5m'] = run_strategy(all_candles, _Wrapper(), 'Giga V35 (5m)')

        return jsonify({'symbol': symbol, 'candles': len(all_candles), 'days': days,
                       'timeframe': '5m', 'stats': stats})

    except Exception as e:
        logger.error(f"[BT5M] Error {symbol}: {e}")
        return jsonify({'error': str(e)})


# ── SIGNAL LOGGER ────────────────────────────────────────────────────────────
_signals_lock = threading.Lock()

def log_signal(symbol: str, timeframe: str, signal: str, confidence: int,
               strategy: str, sub_strategy: str, reasons: list, indicators: dict,
               slug: str = None, condition_id: str = None,
               direction: str = None, price: float = None):
    """Persist fired signals (BULLISH/BEARISH or non-NEUTRAL with conf>0) to signals_log.json.
    NEUTRAL signals are skipped — they were 99.4% of historical log noise.

    Captures full indicators dict (no whitelist) plus universal features
    (hour, session) and optional cross-reference fields (slug, condition_id, direction)
    so ML/RL can later join with outcomes from bot_predictions.json."""
    # Skip noise — only persist actually-fired signals
    if signal in (None, '', 'NEUTRAL') or not confidence:
        return
    _now = datetime.now(timezone.utc)
    hr = _now.hour
    session = ('ASIA' if 0 <= hr < 8 else 'US_OPEN' if 8 <= hr < 12
               else 'US_AFT' if 12 <= hr < 20 else 'OVERNIGHT')
    entry = {
        'timestamp': _now.isoformat(),
        'symbol': symbol,
        'timeframe': timeframe,
        'signal': signal,
        'confidence': confidence,
        'strategy': strategy,
        'sub_strategy': sub_strategy,
        'reasons': reasons[:8] if reasons else [],
        # Full indicators dict — preserves all features for ML training
        'indicators': dict(indicators) if indicators else {},
        # Universal features (cheap, useful for any ML model)
        'fill_hour': hr,
        'fill_session': session,
        # Optional cross-reference + outcome fields — populated when known
        'slug':         slug,
        'condition_id': condition_id,
        'direction':    direction,
        'price':        price,
        # Outcome fields — backwritten by check_outcomes() when resolution happens
        'outcome':   None,
        'won':       None,
        'paper_pnl': None,
        'resolved':  False,
    }
    try:
        with _signals_lock:
            logs = []
            if os.path.exists(SIGNALS_LOG):
                try:
                    with open(SIGNALS_LOG, 'r', encoding='utf-8') as f:
                        logs = json.load(f)
                except (json.JSONDecodeError, ValueError):
                    logger.warning("[SIGNAL-LOG] Corrupt file detected — resetting")
                    logs = []
            logs.append(entry)
            # 10k retention now that we skip NEUTRAL noise — gives much more ML training history
            logs = logs[-10000:]
            tmp = SIGNALS_LOG + '.tmp'
            with open(tmp, 'w', encoding='utf-8') as f:
                json.dump(logs, f, indent=2, default=str)
            os.replace(tmp, SIGNALS_LOG)
    except Exception as e:
        logger.warning(f"[SIGNAL-LOG] Could not write: {e}")


def link_outcome_to_signal(symbol: str, timeframe: str, strategy: str,
                           signal_direction: str, outcome: str, won: bool,
                           paper_pnl: float, prediction_ts: str = None,
                           match_window_seconds: int = 600):
    """Backwrite outcome onto the most recent matching signal entry.
    Match: same (symbol, timeframe, strategy, signal direction) within match_window seconds.
    Called from the prediction resolution path so ML can join features <-> outcomes."""
    try:
        with _signals_lock:
            if not os.path.exists(SIGNALS_LOG):
                return
            with open(SIGNALS_LOG, 'r', encoding='utf-8') as f:
                logs = json.load(f)
            from datetime import datetime as _dt, timezone as _tz
            try:
                target_ts = _dt.fromisoformat(prediction_ts.replace('Z','+00:00')) if prediction_ts else _dt.now(_tz.utc)
            except Exception:
                target_ts = _dt.now(_tz.utc)
            # Walk backwards (newest first) to find most recent unresolved match
            for e in reversed(logs):
                if e.get('resolved'):
                    continue
                if e.get('symbol') != symbol or e.get('timeframe') != timeframe:
                    continue
                if e.get('strategy') and strategy and not (
                    e.get('strategy') == strategy or e.get('sub_strategy') == strategy
                    or strategy.startswith(e.get('strategy',''))):
                    continue
                if signal_direction and e.get('signal') and e.get('signal') != signal_direction:
                    continue
                try:
                    sig_ts = _dt.fromisoformat(e['timestamp'].replace('Z','+00:00'))
                    if abs((target_ts - sig_ts).total_seconds()) > match_window_seconds:
                        continue
                except Exception:
                    continue
                # Match found — backwrite outcome
                e['outcome']   = outcome
                e['won']       = bool(won)
                e['paper_pnl'] = paper_pnl
                e['resolved']  = True
                break
            else:
                return  # no match
            tmp = SIGNALS_LOG + '.tmp'
            with open(tmp, 'w', encoding='utf-8') as f:
                json.dump(logs, f, indent=2, default=str)
            os.replace(tmp, SIGNALS_LOG)
    except Exception as e:
        logger.debug(f"[SIGNAL-LOG] Outcome link failed: {e}")


def _signal_outcome_resolver_loop():
    """Background thread: backfills outcomes for unresolved BULLISH/BEARISH signal log
    entries by checking actual price action at signal_ts + timeframe.

    Why this exists: the trade-driven link_outcome_to_signal() only fires when a paper
    trade resolves. Background scanner signals (Contrarian, FadeGiga, etc.) generate
    informational signals but don't drive trades, so their outcomes never got backwritten.
    Result: Contrarian had 206 entries / 0 resolved before this resolver was added.

    Resolution method: compare close at signal-bar to close at next bar of the same
    timeframe. BULLISH wins if next_close > signal_close; BEARISH wins if next_close <
    signal_close. Marks resolution_method='price_action_resolver' so downstream analysis
    can distinguish from trade-driven outcome linking."""
    import time as _t
    from datetime import datetime as _dt, timezone as _tz
    _t.sleep(120)  # let bot init + first scans
    while True:
        try:
            if not os.path.exists(SIGNALS_LOG) or not prediction_bot:
                _t.sleep(60); continue

            with _signals_lock:
                with open(SIGNALS_LOG, 'r', encoding='utf-8') as f:
                    logs = json.load(f)

            now = _dt.now(_tz.utc)
            updated = 0
            candle_cache = {}  # (symbol, tf) -> candles list

            for e in logs:
                if e.get('resolved'):
                    continue
                signal = e.get('signal', '')
                if signal not in ('BULLISH', 'BEARISH'):
                    continue
                try:
                    sig_ts = _dt.fromisoformat(e['timestamp'].replace('Z', '+00:00'))
                except Exception:
                    continue

                tf = e.get('timeframe', '5m')
                tf_secs = 300 if tf == '5m' else 900

                # Wait for window to fully close + 60s buffer for candle delivery
                if (now - sig_ts).total_seconds() < tf_secs + 60:
                    continue

                symbol = e.get('symbol', '')
                if not symbol:
                    continue

                key = (symbol, tf)
                if key not in candle_cache:
                    try:
                        if tf == '5m':
                            candle_cache[key] = prediction_bot.data_fetcher.get_5min_candles(
                                symbol, num_candles=50) or []
                        else:
                            candle_cache[key] = prediction_bot.data_fetcher.get_15min_candles(
                                symbol, num_candles=50) or []
                    except Exception:
                        candle_cache[key] = []

                candles = candle_cache[key]
                if len(candles) < 3:
                    continue

                target_ms = sig_ts.timestamp() * 1000
                sig_idx = None
                for i, c in enumerate(candles):
                    cts = c.get('timestamp') or c.get('time') or 0
                    if cts <= target_ms < cts + tf_secs * 1000:
                        sig_idx = i
                        break

                if sig_idx is None or sig_idx + 1 >= len(candles):
                    continue

                start_close = candles[sig_idx].get('close', 0)
                end_close = candles[sig_idx + 1].get('close', 0)
                if not start_close or not end_close:
                    continue

                if signal == 'BULLISH':
                    won = end_close > start_close
                else:  # BEARISH
                    won = end_close < start_close

                e['outcome'] = 'WIN' if won else 'LOSS'
                e['won'] = bool(won)
                e['paper_pnl'] = 0  # informational only — no paper trade
                e['resolved'] = True
                e['resolution_method'] = 'price_action_resolver'
                e['start_close'] = start_close
                e['end_close'] = end_close
                updated += 1

            if updated:
                with _signals_lock:
                    tmp = SIGNALS_LOG + '.tmp'
                    with open(tmp, 'w', encoding='utf-8') as f:
                        json.dump(logs, f, indent=2, default=str)
                    os.replace(tmp, SIGNALS_LOG)
                logger.info(f'[SIGNAL-RESOLVER] Backfilled {updated} outcome(s)')
        except Exception as ex:
            logger.warning(f'[SIGNAL-RESOLVER] error: {ex}')

        _t.sleep(60)


def _circuit_breaker_loop():
    """Auto-paper any strategy/symbol whose rolling WR drops below 57% over n>=20 trades.

    Why: protects real-money capital when a previously-edged strategy regresses to
    coin-flip territory due to regime change, model staleness, or other drift.

    Cadence: 5 min. Lookback: last 50 resolved trades per category.

    Actions per category:
      HFT per-symbol:    add to hft_scanner.paper_symbols (force trade -> paper)
      ML scanners:       set live_mode=False (BTC-ML, ETH-ML)
      Picks per play_type: log warning only (no auto-disable yet — too risky to
                          auto-mutate strategy_modes; surface for manual action)

    Threshold and lookback values can be tuned at the top of this function.
    """
    import time as _t
    from collections import defaultdict
    THRESHOLD_WR = 57.0
    MIN_SAMPLE   = 20
    LOOKBACK     = 50

    _t.sleep(600)  # 10-min init delay so newly-restarted bots have data
    while True:
        try:
            # === HFT per-symbol (WR check) ===
            if 'hft_scanner' in globals() and hft_scanner:
                try:
                    trades = list(hft_scanner._trades)[-500:]
                except Exception:
                    trades = []
                by_sym = defaultdict(list)
                by_dir = defaultdict(list)
                for t in trades:
                    if (t.get('outcome') or '').upper() in ('WIN', 'LOSS'):
                        by_sym[t.get('symbol', '?')].append(t)
                        by_dir[t.get('direction', '?')].append(t)

                changed = False
                for sym, ts in by_sym.items():
                    ts_recent = ts[-LOOKBACK:]
                    if len(ts_recent) < MIN_SAMPLE:
                        continue
                    wins = sum(1 for t in ts_recent if (t.get('outcome') or '').upper() == 'WIN')
                    wr = wins / len(ts_recent) * 100
                    # Per-symbol HFT auto-paper DISABLED per user 2026-05-10 — keep HFT live regardless of rolling WR.
                    if False and wr < THRESHOLD_WR and sym not in hft_scanner.paper_symbols:
                        hft_scanner.paper_symbols.add(sym)
                        logger.warning(
                            f'[CIRCUIT-BREAKER] HFT {sym} rolling WR={wr:.1f}% '
                            f'over n={len(ts_recent)} (< {THRESHOLD_WR}%) -> auto-PAPER')
                        changed = True

                # === HFT per-direction (PnL check — catches payoff-asymmetry bleeds) ===
                # WR-only check misses the case where 75% WR loses money because losses are
                # bigger than wins. Per the 4288-trade grid: HFT UP was -$961 at 74.9% WR.
                # PnL threshold is -$30 over last 100 (sym-agnostic) trades = clear bleed.
                THRESHOLD_PNL = -30.0
                DIR_LOOKBACK = 100
                for direction, ts in by_dir.items():
                    if direction not in ('UP', 'DOWN'):
                        continue
                    ts_recent = ts[-DIR_LOOKBACK:]
                    if len(ts_recent) < MIN_SAMPLE:
                        continue
                    pnl = sum(float(t.get('pnl') or t.get('paper_pnl') or 0) for t in ts_recent)
                    # Per-direction HFT auto-paper DISABLED per user 2026-05-10 — keep HFT live regardless of rolling PnL.
                    if False and pnl < THRESHOLD_PNL and direction not in hft_scanner.paper_directions:
                        hft_scanner.paper_directions.add(direction)
                        logger.warning(
                            f'[CIRCUIT-BREAKER] HFT direction={direction} rolling PnL=${pnl:+.2f} '
                            f'over n={len(ts_recent)} (< ${THRESHOLD_PNL}) -> auto-PAPER (all {direction} trades)')
                        changed = True

                if changed:
                    try:
                        hft_scanner._save_settings()
                    except Exception:
                        pass

            # === ML scanners (BTC-ML, ETH-ML) ===
            for scanner_var in ('btc_ml_scanner', 'eth_ml_scanner'):
                scanner = globals().get(scanner_var)
                if not scanner or not getattr(scanner, 'live_mode', False):
                    continue
                # 2026-05-17 protection_override: user can disable auto-flips to keep live_mode sticky.
                if getattr(scanner, 'protection_override', False):
                    continue
                try:
                    with scanner._lock:
                        trades = list(scanner._trades)
                except Exception:
                    trades = []
                # Real (live) trades only — paper-period trades must not trigger auto-paper.
                resolved = [t for t in trades[-2000:]
                            if t.get('real_trade')
                            and (t.get('outcome') or '').upper() in ('WIN', 'LOSS')]
                resolved = resolved[-LOOKBACK:]
                if len(resolved) < MIN_SAMPLE:
                    continue
                wins = sum(1 for t in resolved if (t.get('outcome') or '').upper() == 'WIN')
                wr = wins / len(resolved) * 100
                if wr < THRESHOLD_WR:
                    scanner.live_mode = False
                    try:
                        scanner._save_settings()
                    except Exception:
                        pass
                    logger.warning(
                        f'[CIRCUIT-BREAKER] {getattr(scanner,"_log","?")} rolling '
                        f'WR={wr:.1f}% over n={len(resolved)} (< {THRESHOLD_WR}%) '
                        f'-> live_mode=False (auto-PAPER)')

            # === Picks per play_type (warning only, no auto-disable) ===
            # 2026-05-17 protection_override: skip entire picks WR-warning block if user toggled
            # override on. This block is warning-only but it polluted Telegram each cycle.
            _picks_override = ('claude_scanner' in globals() and claude_scanner
                               and claude_scanner.strategy_modes.get('_protection_override', False))
            if 'claude_scanner' in globals() and claude_scanner and not _picks_override:
                try:
                    trades = claude_scanner._load_paper_log()
                except Exception:
                    trades = []
                # filter: real (live) trades only, entered (not blocked) + resolved.
                # Paper-trade WR drift should not trigger the breaker — user 2026-05-16.
                recent = [t for t in trades[-2000:]
                          if t.get('real_trade')
                          and not t.get('blocked_by')
                          and (t.get('outcome') or '').upper() in ('WIN', 'LOSS')]
                by_pt = defaultdict(list)
                for t in recent:
                    by_pt[t.get('play_type', '?')].append(t)
                for pt, ts in by_pt.items():
                    if 'MISPRICED' in pt.upper() or 'MANIP' in pt.upper():
                        continue  # profitable at low WR by design — matches _check_auto_disable exemption
                    ts_recent = ts[-LOOKBACK:]
                    if len(ts_recent) < MIN_SAMPLE:
                        continue
                    wins = sum(1 for t in ts_recent if (t.get('outcome') or '').upper() == 'WIN')
                    wr = wins / len(ts_recent) * 100
                    if wr < THRESHOLD_WR:
                        logger.warning(
                            f'[CIRCUIT-BREAKER] Picks play_type={pt} rolling '
                            f'WR={wr:.1f}% over n={len(ts_recent)} (< {THRESHOLD_WR}%) '
                            f'— consider disabling via strategy_modes')
        except Exception as ex:
            logger.warning(f'[CIRCUIT-BREAKER] loop error: {ex}')

        _t.sleep(300)  # 5-min cadence


@app.route('/api/signals-log')
def get_signals_log():
    """Return recent signal log entries."""
    limit = int(request.args.get('limit', 200))
    tf    = request.args.get('tf', '')
    sym   = request.args.get('symbol', '').upper()
    only_fired = request.args.get('fired', '0') == '1'
    try:
        if not os.path.exists(SIGNALS_LOG):
            return jsonify([])
        with _signals_lock:
            with open(SIGNALS_LOG, 'r', encoding='utf-8') as f:
                logs = json.load(f)
        if tf:
            logs = [l for l in logs if l.get('timeframe') == tf]
        if sym:
            logs = [l for l in logs if l.get('symbol') == sym]
        if only_fired:
            logs = [l for l in logs if l.get('signal') != 'NEUTRAL']
        return jsonify(logs[-limit:][::-1])  # newest first
    except Exception as e:
        return jsonify({'error': str(e)})


# ── SERVER-SIDE BACKGROUND SCANNER ───────────────────────────────────────────
def _background_scanner():
    """
    Runs continuously in a background thread, independent of any browser.

    Timing — fires in the LAST 35s of each bar so check_auto_buy windows are met:
      5m  bars: scans when secs_into_5m_bar  >= 265  (i.e. :04:25, :09:25, :14:25 …)
      15m bars: scans when secs_into_15m_bar >= 865  (i.e. :14:25, :29:25, :44:25 …)

    Each bar gets exactly ONE scan per cycle (tracked by bar ID to avoid re-firing).
    """
    import time as _t
    logger.info("[BG-SCAN] Background scanner started — fires in last 35s of each bar")

    fired_5m_bar  = -1   # bar ID (total 5m bars since epoch) that already fired
    fired_15m_bar = -1   # bar ID (total 15m bars since epoch) that already fired

    # Claude Picks scanner fire points (bar_id → set of 'open'/'close' already fired)
    cp_fired: Dict = {}  # {bar_id: set}

    last_tp_sl_ts = 0  # epoch seconds — Claude TP/SL fires every 2 min

    while True:
        try:
            if not prediction_bot:
                _t.sleep(5)
                continue

            now = datetime.now(timezone.utc)
            total_minutes = now.hour * 60 + now.minute
            secs = now.second

            secs_into_5m  = (now.minute % 5) * 60 + secs
            secs_into_15m = (now.minute % 15) * 60 + secs

            cur_5m_bar  = total_minutes // 5
            cur_15m_bar = total_minutes // 15

            # ── Claude Picks: fire at bar open (+5s) and bar close (−60s) ──
            if claude_scanner:
                def _cp_scan(label, bar_key):
                    if bar_key not in cp_fired:
                        cp_fired[bar_key] = set()
                    if label not in cp_fired[bar_key]:
                        cp_fired[bar_key].add(label)
                        # Keep dict small — only last 20 bars
                        if len(cp_fired) > 20:
                            oldest = min(cp_fired)
                            del cp_fired[oldest]
                        claude_scanner._cache_ts = 0  # force fresh scan
                        claude_scanner.scan()
                        logger.info(f'[CP-SCAN] {label} scan fired (bar {bar_key})')

                # 5m bar open: seconds 5–20
                if 5 <= secs_into_5m <= 20:
                    _cp_scan('5m-open', f'5m-{cur_5m_bar}')
                # 5m bar close: seconds 240–260 (60s before end)
                if 240 <= secs_into_5m <= 260:
                    _cp_scan('5m-close', f'5m-close-{cur_5m_bar}')
                # 15m bar open: seconds 5–20
                if 5 <= secs_into_15m <= 20:
                    _cp_scan('15m-open', f'15m-{cur_15m_bar}')
                # 15m bar close: seconds 840–860
                if 840 <= secs_into_15m <= 860:
                    _cp_scan('15m-close', f'15m-close-{cur_15m_bar}')

            # ── 5-minute scan: fire at second 265–299 of each bar ──────────
            if secs_into_5m >= 265 and cur_5m_bar != fired_5m_bar:
                fired_5m_bar = cur_5m_bar
                try:
                    logger.info(f"[BG-SCAN] 5m window @ {now.strftime('%H:%M:%S')} UTC ({300 - secs_into_5m}s left)")
                    results_5m = prediction_bot.scan_all_symbols_5m()
                    for sym, data in results_5m.items():
                        a   = data.get('analysis', {})
                        ind = a.get('indicators', {})
                        sig = a.get('signal', 'NEUTRAL')
                        log_signal(
                            symbol=sym, timeframe='5m', signal=sig,
                            confidence=a.get('confidence', 0),
                            strategy=ind.get('strategy', 'FadeGiga5m'),
                            sub_strategy=ind.get('sub_strategy', ''),
                            reasons=a.get('reasons', []),
                            indicators=ind,
                        )
                        if sig != 'NEUTRAL':
                            logger.info(f"[BG-SCAN] *** 5m SIGNAL: {sym} {sig} ***")
                            conf = a.get('confidence', 0)
                            strat = ind.get('sub_strategy') or ind.get('strategy', '')
                            prediction_bot._tg_notify(
                                f'SIGNAL 5m {sig}\n'
                                f'<b>{sym}</b>  {conf}%\n'
                                f'{strat}'
                            )
                except Exception as e:
                    logger.error(f"[BG-SCAN] 5m scan error: {e}")

            # ── 15-minute scan: fire at second 865–899 of each bar ─────────
            if secs_into_15m >= 865 and cur_15m_bar != fired_15m_bar:
                fired_15m_bar = cur_15m_bar
                try:
                    logger.info(f"[BG-SCAN] 15m window @ {now.strftime('%H:%M:%S')} UTC ({900 - secs_into_15m}s left)")
                    results_15m = prediction_bot.scan_all_symbols()
                    for sym, data in results_15m.items():
                        a   = data.get('analysis', {})
                        ind = a.get('indicators', {})
                        sig = a.get('signal', 'NEUTRAL')
                        log_signal(
                            symbol=sym, timeframe='15m', signal=sig,
                            confidence=a.get('confidence', 0),
                            strategy=ind.get('strategy', 'FadeGiga'),
                            sub_strategy=ind.get('sub_strategy', ''),
                            reasons=a.get('reasons', []),
                            indicators=ind,
                        )
                        if sig != 'NEUTRAL':
                            logger.info(f"[BG-SCAN] *** 15m SIGNAL: {sym} {sig} ***")
                            conf = a.get('confidence', 0)
                            strat = ind.get('sub_strategy') or ind.get('strategy', '')
                            prediction_bot._tg_notify(
                                f'SIGNAL 15m {sig}\n'
                                f'<b>{sym}</b>  {conf}%\n'
                                f'{strat}'
                            )
                except Exception as e:
                    logger.error(f"[BG-SCAN] 15m scan error: {e}")

            # ── Claude TP/SL: evaluate open Claude Picks positions every 10 min ──
            if now.timestamp() - last_tp_sl_ts >= 120:
                last_tp_sl_ts = now.timestamp()
                try:
                    prediction_bot._claude_tp_sl_check()
                except Exception as e:
                    logger.error(f"[BG-SCAN] Claude TP/SL error: {e}")

        except Exception as e:
            logger.error(f"[BG-SCAN] Outer loop error: {e}")

        _t.sleep(10)  # 10s poll — still catches the 35s window reliably


@app.route('/api/tg-send', methods=['POST'])
def tg_send():
    """Send a message to Telegram — used by Claude Code to reply to /cc messages."""
    try:
        data = request.get_json(force=True, silent=True) or {}
        msg = data.get('message', '')
        if not msg:
            return jsonify({'error': 'no message'}), 400
        prediction_bot._tg_notify(msg)
        return jsonify({'ok': True})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/tg-inbox', methods=['GET'])
def tg_inbox():
    """Return unread /cc messages from Telegram."""
    try:
        _inbox = 'tg_inbox.json'
        if not os.path.exists(_inbox):
            return jsonify([])
        # 2026-05-23 PR-7 follow-up: explicit utf-8 — phone messages routinely
        # contain non-ASCII (em-dashes, smart quotes, emoji). Default cp1252
        # on Windows would silently fail and the responder would never see
        # the inbox content.
        with open(_inbox, 'r', encoding='utf-8') as _fh:
            msgs = json.load(_fh)
        unread = [m for m in msgs if not m.get('read')]
        for m in msgs:
            m['read'] = True
        _tmp = _inbox + '.tmp'
        with open(_tmp, 'w', encoding='utf-8') as f:
            json.dump(msgs, f, indent=2, ensure_ascii=False)
        os.replace(_tmp, _inbox)
        return jsonify(unread)
    except Exception as e:
        return jsonify({'error': str(e)}), 500


@app.route('/api/restart', methods=['POST'])
def restart_server():
    """Restart the bot process in-place."""
    import threading
    def _do_restart():
        import time
        time.sleep(0.5)  # Let the response send first
        os.execv(sys.executable, [sys.executable] + sys.argv)
    threading.Thread(target=_do_restart, daemon=True).start()
    return jsonify({'success': True, 'message': 'Restarting...'})


@app.route('/api/weekend-mode')
def api_weekend_mode():
    """Show whether weekend mode is active and which state files are in use."""
    cfg    = _weekend_mode_config()
    active = _is_weekend_mode_now()
    cur_start, cur_end = _current_weekend_window()
    files = ['btc_ml_model.json', 'btc_ml_rl_state.json',
             'hft_rl_state.json', 'manip_rl_state.json',
             'claude_picks_rl_state.json']
    state_paths = {f: os.path.basename(_resolve_state_path(f)) for f in files}
    def _iso(ts):
        try: return datetime.fromtimestamp(float(ts), timezone.utc).isoformat()
        except Exception: return None
    return jsonify({
        'active':           active,
        'enabled':          bool(cfg.get('enabled')),
        'recurring':        bool(cfg.get('recurring')),
        'anchor_start_ts':  cfg.get('start_ts'),
        'anchor_end_ts':    cfg.get('end_ts'),
        'current_start_ts': cur_start,
        'current_end_ts':   cur_end,
        'current_start_iso': _iso(cur_start) if cur_start else None,
        'current_end_iso':   _iso(cur_end)   if cur_end   else None,
        'now_ts':           time.time(),
        'state_files':      state_paths,
        'note':             cfg.get('note', ''),
    })


if __name__ == '__main__':
    # Cleanup of orphan .tmp_* files from prior crashed/aborted writes.
    # Atomic-write pattern (write tmp_X, rename to target) leaves orphans on
    # process kill or rename collisions. Each is up to ~5MB; 196+ of them is
    # the symptom we observed pre-deployment.
    try:
        import glob as _glob, os as _os, time as _time
        _now = _time.time()
        _purged = 0
        _bytes  = 0
        for _orph in _glob.glob('*.json.tmp_*'):
            try:
                _age = _now - _os.path.getmtime(_orph)
                if _age > 300:   # only delete tmps older than 5 minutes
                    _bytes += _os.path.getsize(_orph)
                    _os.remove(_orph)
                    _purged += 1
            except OSError:
                pass
        if _purged:
            logger.info(f'[STARTUP] Cleaned {_purged} orphan .tmp_* files ({_bytes/1024:.0f} KB freed)')
    except Exception as _e:
        logger.warning(f'[STARTUP] Orphan cleanup error: {_e}')

    # Weekend mode watchdog must start BEFORE scanners so the active path
    # is established before any class loads its state file.
    _start_weekend_boundary_watchdog()
    if _is_weekend_mode_now():
        cfg = _weekend_mode_config()
        end_iso = datetime.fromtimestamp(cfg.get('end_ts', 0), timezone.utc).isoformat()
        logger.info(f'[WEEKEND] Starting in WEEKEND mode — ML/RL state segregated, ends {end_iso}')

    prediction_bot = PolymarketPredictionBot(position_size_usd=5.0)
    claude_scanner = ClaudePicksScanner(prediction_bot)
    hft_scanner    = HFTScanner(prediction_bot)
    btc_ml_scanner = BTCMLScanner('BTC', prediction_bot,
                                   clob_ws=hft_scanner._ws_feed if hft_scanner else None)
    eth_ml_scanner = BTCMLScanner('ETH', prediction_bot,
                                   clob_ws=hft_scanner._ws_feed if hft_scanner else None)
    # BTC-HERMES — Markov 5m persistence trader. Shares clob_ws + btc_ml_ref to avoid
    # duplicate WS/REST traffic. Phase 2b: paper-only (live_enter deferred to Phase 2c).
    btc_hermes_scanner = BTCHermesScanner(bot_ref=prediction_bot,
                                   clob_ws=hft_scanner._ws_feed if hft_scanner else None,
                                   btc_ml_ref=btc_ml_scanner)

    print("\n" + "="*70)
    print("POLYMARKET BOT - FIXED ORDER PLACEMENT")
    print("="*70)
    print("* Exact slug matching: {symbol}-updown-15m-{timestamp}")
    print("* Correct token ID matching by outcome name")
    print("* Order book price fetching")
    print("* Real-time monitoring for BTC/ETH/SOL/XRP")
    print("* Hit rate tracking for 100% confidence predictions")
    print("* Charts working correctly")
    print("Starting web server on http://localhost:5002")
    if prediction_bot and not prediction_bot.wallet_live:
        print("* View-only: add decrypted wallet keys to grok.env to enable trading")
    print("="*70 + "\n")

    # Start independent background scanner — runs even with browser closed
    _bg_thread = threading.Thread(target=_background_scanner, daemon=True, name='bg-scanner')
    _bg_thread.start()
    logger.info("[BG-SCAN] Background scanner thread launched")

    # Start paper-trade outcome checker — polls every 5 min regardless of browser
    def _paper_outcome_loop():
        import time as _t
        logger.info("[PAPER] Outcome checker started — polls every 5 min")
        while True:
            try:
                if claude_scanner:
                    claude_scanner.check_paper_outcomes()
                    claude_scanner._check_picks_fill_status()
                    claude_scanner.rl_shadow.check_outcomes()
            except Exception as e:
                logger.error(f"[PAPER] Outcome loop error: {e}")
            _t.sleep(300)  # every 5 minutes

    _paper_thread = threading.Thread(target=_paper_outcome_loop, daemon=True, name='paper-outcomes')
    _paper_thread.start()

    # Backfill outcomes for background-scanner signals (Contrarian, FadeGiga, etc.) which
    # do not drive paper trades and so were never getting their outcomes recorded.
    # Walks signals_log.json once a minute, resolves any unresolved BULLISH/BEARISH entry
    # whose timeframe window has closed, by comparing actual price action.
    _signal_resolver_thread = threading.Thread(
        target=_signal_outcome_resolver_loop, daemon=True, name='signal-resolver')
    _signal_resolver_thread.start()
    logger.info("[SIGNAL-RESOLVER] Background outcome resolver started — polls every 60s")

    # Auto-paper any strategy whose rolling WR drops below 57% over n>=20 trades.
    # Polls every 5 min. HFT per-symbol -> paper_symbols. ML scanners -> live_mode=False.
    # Picks logs warning only (manual action via strategy_modes).
    _circuit_breaker_thread = threading.Thread(
        target=_circuit_breaker_loop, daemon=True, name='circuit-breaker')
    _circuit_breaker_thread.start()
    logger.info("[CIRCUIT-BREAKER] WR-57%% auto-paper guard started — polls every 5 min")
    logger.info("[PAPER] Paper outcome checker thread launched")

    # Claude Picks continuous background scanner — runs every 60s regardless of browser
    def _claude_picks_loop():
        import time as _t
        logger.info("[PICKS-BG] Claude Picks background scanner started — 60s interval")
        _t.sleep(15)  # brief delay to let server fully init before first scan
        while True:
            try:
                if claude_scanner:
                    picks = claude_scanner.scan()
                    highs = sum(1 for p in picks if p.get('conviction') in ('HIGH','STRONG','EXTREME'))
                    if highs:
                        logger.info(f"[PICKS-BG] Scan complete — {len(picks)} picks ({highs} HIGH+)")
            except Exception as e:
                logger.error(f"[PICKS-BG] Scan error: {e}")
            _t.sleep(60)

    _picks_bg_thread = threading.Thread(target=_claude_picks_loop, daemon=True, name='picks-bg')
    _picks_bg_thread.start()
    logger.info("[PICKS-BG] Claude Picks background scanner launched")

    # HFT scanner loop — event-driven via CLOB WS + Binance WS callbacks, 1s max fallback
    def _hft_scan_loop():
        import time as _t
        logger.info("[HFT] Background scanner started — event-driven (1s fallback)")
        _t.sleep(10)  # let server fully init
        _outcome_tick = 0
        _last_scan = 0.0
        _min_interval = 0.3  # never scan faster than 300ms
        # Use the scanner-owned scan_event so external sources (Binance WS, CLOB WS) can wake the loop.
        if hft_scanner and hft_scanner._ws_feed:
            def _hft_price_cb(token_id, ask, bid):
                hft_scanner._clob_trigger_count += 1
                hft_scanner._scan_event.set()
            hft_scanner._ws_feed.register_price_callback(_hft_price_cb)
            logger.info("[HFT] Registered CLOB WS price callback — event-driven scanning active")
        # Bridge Binance WS triggers from BTC-ML's BinancePriceWS (already running for BTC).
        # When BTC moves, fire HFT scan BEFORE Polymarket repriced — race into the lag window.
        if hft_scanner and btc_ml_scanner and getattr(btc_ml_scanner, '_binance_ws', None):
            try:
                hft_scanner.register_binance_trigger(btc_ml_scanner._binance_ws)
            except Exception as _e:
                logger.warning(f"[HFT] Could not register Binance trigger: {_e}")
        # Multi-symbol Binance feed for SOL/XRP/BNB/ETH/DOGE — direct triggers per symbol.
        # HYPE excluded (Hyperliquid). One WS connection covers all 5 symbols.
        if hft_scanner:
            try:
                hft_scanner._binance_multi_ws = BinanceMultiAggTradeWS(
                    symbols=['SOLUSDT','XRPUSDT','BNBUSDT','ETHUSDT','DOGEUSDT'],
                    move_threshold=0.0005,  # 0.05% — tighter than BTC's 0.10%
                )
                hft_scanner.register_binance_multi_trigger(hft_scanner._binance_multi_ws)
            except Exception as _e:
                logger.warning(f"[HFT] Could not start multi-symbol Binance WS: {_e}")
        # Start background drawdown balance poller — replaces per-scan blocking CLOB HTTP call.
        if hft_scanner:
            try:
                hft_scanner.start_drawdown_poller()
            except Exception as _e:
                logger.warning(f"[HFT] Could not start drawdown poller: {_e}")
            # Start async save worker — moves ~78ms JSON serialization off trade entry hot path.
            try:
                hft_scanner.start_save_worker()
            except Exception as _e:
                logger.warning(f"[HFT] Could not start save worker: {_e}")
            # Start background market metadata refresher — saves ~300-500ms per scan
            # by removing 2× ThreadPoolExecutor Gamma probes from the hot path.
            try:
                hft_scanner.start_market_refresh()
            except Exception as _e:
                logger.warning(f"[HFT] Could not start market refresher: {_e}")
        while True:
            try:
                # Wait up to 1s for a WS price event; proceed on timeout too
                triggered = hft_scanner._scan_event.wait(timeout=1.0) if hft_scanner else False
                if hft_scanner:
                    hft_scanner._scan_event.clear()
                now = _t.time()
                if now - _last_scan < _min_interval:
                    continue
                _last_scan = now
                if hft_scanner:
                    hft_scanner.scan_once()
                    _outcome_tick += 1
                    if _outcome_tick >= 8:  # check outcomes every ~8 scans (~8s at 1s interval)
                        hft_scanner.check_outcomes()
                        # _check_fill_status makes many HTTP requests — run off-thread so scan loop never blocks
                        threading.Thread(target=hft_scanner._check_fill_status, daemon=True, name='hft-fill-check').start()
                        hft_scanner.rl_shadow.check_outcomes()
                        _xbot_clear_expired()  # prune stale cross-bot positions (safety valve)
                        _outcome_tick = 0
                    # Price path tracking + stale order repost on every scan
                    hft_scanner._track_price_path()
                    hft_scanner._repost_stale_orders()
            except Exception as e:
                logger.error(f"[HFT] Loop error: {e}")

    _hft_thread = threading.Thread(target=_hft_scan_loop, daemon=True, name='hft-scanner')
    _hft_thread.start()
    logger.info("[HFT] HFT scanner thread launched")

    # ML scanner loop factory — event-driven via Binance WS, 5s fallback.
    # Key edge: Binance price data arrives 100-500ms before Polymarket oracle reprices.
    # BinancePriceWS fires scan_event when price moves >= 0.10%, so we enter Polymarket
    # markets before market makers update their quotes. Used for both BTC-ML and ETH-ML.
    def _make_ml_scan_loop(scanner_ref_name: str, label: str):
        import time as _t
        def _loop():
            logger.info(f"[{label}] Background scanner started — event-driven via Binance WS (5s fallback)")
            _t.sleep(14)  # stagger after HFT thread starts
            _outcome_tick = 0
            _last_scan = 0.0
            _min_interval = 0.5  # never scan faster than 500ms
            while True:
                try:
                    scanner = globals().get(scanner_ref_name)
                    if scanner:
                        triggered = scanner._scan_event.wait(timeout=5.0)
                        now = _t.time()
                        if now - _last_scan < _min_interval:
                            continue
                        _last_scan = now
                        scanner.scan_once(triggered=triggered)
                        # TP/SL price-path tracking — runs every scan tick, self-gates on tp_sl_enabled
                        try:
                            scanner._track_price_path()
                        except Exception as _tpe:
                            logger.debug(f'[{label}-TPSL] track error: {_tpe}')
                        _outcome_tick += 1
                        if _outcome_tick >= 6:  # check outcomes every ~30s
                            scanner.check_outcomes()
                            # _check_fill_status makes per-trade CLOB calls — run off-thread
                            try:
                                threading.Thread(target=scanner._check_fill_status,
                                                 daemon=True, name=f'{label.lower()}-fill-check').start()
                            except Exception as _fe:
                                logger.debug(f'[{label}-FILL] spawn error: {_fe}')
                            try:
                                scanner.rl_shadow.check_outcomes()
                            except Exception as _se:
                                logger.debug(f'[{label}-SHADOW] check error: {_se}')
                            _outcome_tick = 0
                    else:
                        _t.sleep(5)
                except Exception as e:
                    logger.error(f"[{label}] Loop error: {e}")
                    _t.sleep(1)
        return _loop

    # Start async save workers for both ML scanners — ~60ms JSON serialization
    # moved off trade entry hot path. Mirrors HFT pattern.
    if btc_ml_scanner:
        try:
            btc_ml_scanner.start_save_worker()
        except Exception as _e:
            logger.warning(f"[BTC-ML] Could not start save worker: {_e}")
    if eth_ml_scanner:
        try:
            eth_ml_scanner.start_save_worker()
        except Exception as _e:
            logger.warning(f"[ETH-ML] Could not start save worker: {_e}")
    if btc_hermes_scanner:
        try:
            btc_hermes_scanner.start_save_worker()
        except Exception as _e:
            logger.warning(f"[BTC-HERMES] Could not start save worker: {_e}")

    _btc_ml_thread = threading.Thread(target=_make_ml_scan_loop('btc_ml_scanner', 'BTC-ML'),
                                       daemon=True, name='btc-ml-scanner')
    _btc_ml_thread.start()
    logger.info("[BTC-ML] BTC-ML scanner thread launched")

    _eth_ml_thread = threading.Thread(target=_make_ml_scan_loop('eth_ml_scanner', 'ETH-ML'),
                                       daemon=True, name='eth-ml-scanner')
    _eth_ml_thread.start()
    logger.info("[ETH-ML] ETH-ML scanner thread launched")

    # BTC-HERMES — reuses _make_ml_scan_loop factory. _track_price_path/_check_fill_status
    # are no-ops in Phase 2b (already try/except wrapped in factory). rl_shadow absent
    # but the factory's try/except handles that too (line 23486 in pre-patch numbering).
    _btc_hermes_thread = threading.Thread(target=_make_ml_scan_loop('btc_hermes_scanner', 'BTC-HERMES'),
                                       daemon=True, name='btc-hermes-scanner')
    _btc_hermes_thread.start()
    logger.info("[BTC-HERMES] BTC-HERMES scanner thread launched")

    # Start Telegram chat bot — polls for messages and responds via Claude
    if prediction_bot:
        prediction_bot.start_tg_chat()
        logger.info("[TG] Claude chat bot launched — @polyquantaibot ready")

    # /cc inbox responder — built-in daemon so it always runs with the bot
    def _tg_cc_loop():
        import time as _t, json as _j, urllib.request as _ur
        _INBOX   = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'tg_inbox.json')
        _API_URL = 'https://api.anthropic.com/v1/messages'
        _MODEL   = 'claude-sonnet-4-6'
        _POLL    = 20  # seconds
        logger.info("[TG-CC] /cc responder thread started")

        def _bot_context():
            lines = ['=== BTC ML BOT STATE ===']
            try:
                import urllib.request as _u
                def _get(path):
                    try:
                        return _j.loads(_u.urlopen(
                            _u.Request(f'http://localhost:5002{path}'), timeout=4).read())
                    except Exception:
                        return {}
                state  = _get('/api/btc-ml-state')
                trades = _get('/api/btc-ml-trades')
                tr = trades if isinstance(trades, list) else []
                resolved = [t for t in tr if t.get('resolved') and t.get('outcome') in ('WIN','LOSS')]
                wins     = [t for t in resolved if t.get('won')]
                pending  = [t for t in tr if not t.get('resolved')]
                pnl      = round(sum(t.get('pnl', 0) for t in resolved), 2)
                ml       = state.get('ml_model', {}) if isinstance(state, dict) else {}
                n_tr     = state.get('n_trained', 0) if isinstance(state, dict) else 0
                lp       = state.get('last_prediction', {}) if isinstance(state, dict) else {}
                lines.append(f'Resolved: {len(resolved)} | Wins: {len(wins)} | '
                             f'WR: {round(len(wins)/len(resolved)*100,1) if resolved else 0}% | PnL: ${pnl:+.2f}')
                lines.append(f'Pending: {len(pending)} | n_trained={n_tr} | acc={ml.get("accuracy","untrained")}')
                if lp:
                    ago = round(_t.time() - lp.get('ts', _t.time()), 0)
                    lines.append(f'Last scan: {ago}s ago | price={lp.get("price",0):.3f} '
                                 f'dir={lp.get("direction","?")} prob={lp.get("prob",0):.3f}')
                if resolved:
                    lines.append('Recent (last 5):')
                    for t in resolved[-5:]:
                        lines.append(f'  {str(t.get("logged_at",""))[:16]} {t.get("direction")} '
                                     f'{t.get("outcome")} pnl=${t.get("pnl",0):.2f}')
            except Exception as e:
                lines.append(f'Context error: {e}')
            return '\n'.join(lines)

        def _ask_claude(user_msg, context):
            key = os.environ.get('ANTHROPIC_API_KEY', '')
            if not key or key.startswith('ENC:'):
                return '(API key not available)'
            try:
                payload = _j.dumps({
                    'model': _MODEL, 'max_tokens': 500,
                    'system': ('You are monitoring a live Polymarket BTC ML trading bot. '
                               'Answer concisely with numbers. Under 300 chars when possible.\n\n' + context),
                    'messages': [{'role': 'user', 'content': user_msg}]
                }).encode()
                req = _ur.Request(_API_URL, data=payload, headers={
                    'x-api-key': key, 'anthropic-version': '2023-06-01',
                    'content-type': 'application/json'}, method='POST')
                resp = _j.loads(_ur.urlopen(req, timeout=20).read())
                return resp['content'][0]['text']
            except Exception as e:
                return f'Claude error: {e}'

        def _tg_send(text):
            try:
                body = _j.dumps({'message': text}).encode()
                req = _ur.Request('http://localhost:5002/api/tg-send', data=body,
                                  headers={'Content-Type': 'application/json'}, method='POST')
                _ur.urlopen(req, timeout=6)
            except Exception:
                pass

        while True:
            try:
                if os.path.exists(_INBOX):
                    with open(_INBOX) as _fh:
                        msgs = _j.load(_fh)
                    unread = [m for m in msgs if not m.get('read')]
                    if unread:
                        ctx = _bot_context()
                        for m in unread:
                            text = m.get('message', '')
                            logger.info(f"[TG-CC] Responding to: {text[:60]}")
                            reply = _ask_claude(text, ctx)
                            _tg_send(reply)
                            m['read'] = True
                            logger.info(f"[TG-CC] Sent: {reply[:80]}")
                        tmp = _INBOX + '.tmp_cc'
                        with open(tmp, 'w') as _fh:
                            _j.dump(msgs, _fh, indent=2)
                        os.replace(tmp, _INBOX)
            except Exception as e:
                logger.error(f"[TG-CC] Loop error: {e}")
            _t.sleep(_POLL)

    # Built-in /cc loop disabled — superseded by standalone tg_cc_responder.py which now
    # shells out to `claude -p` (Claude Code headless) for real tool access (Read/Bash/Edit)
    # instead of just the Claude API chatbot. Two pollers on same inbox would race.
    # Re-enable here only if you want a fast API-chatbot fallback running in-process.
    # _tg_cc_thread = threading.Thread(target=_tg_cc_loop, daemon=True, name='tg-cc-responder')
    # _tg_cc_thread.start()
    # logger.info("[TG-CC] /cc responder thread launched")
    logger.info("[TG-CC] In-process /cc loop DISABLED — standalone tg_cc_responder.py handles inbox")


    # Daily RL/ML snapshot daemon — boot-time + once-per-UTC-day to rl_ml_snapshots/<DATE>/
    _start_daily_snapshot_loop(retention_days=30)

    # use_reloader=False: avoid forking another worker process.
    # NOTE: do NOT pass threaded=True here — flask-socketio already passes it to app.run()
    # internally and adding our own causes "got multiple values for keyword argument 'threaded'".
    socketio.run(app, host=os.environ.get('BOT_HOST', '127.0.0.1'), port=5002, debug=False,
                 allow_unsafe_werkzeug=True, use_reloader=False)


# ── TRADINGVIEW WEBHOOK ───────────────────────────────────────────────────────
# TradingView alert message format (set this in the alert's Message box):
#   {"symbol":"ETH","signal":"BEARISH","strategy":"FadeGigaETH5m","timeframe":"5m","confidence":75}
# Webhook URL (in TradingView alert): http://YOUR_IP:5000/api/tv-alert
@app.route('/api/tv-alert', methods=['POST'])
def tv_alert_webhook():
    """Receive TradingView webhook alerts and optionally auto-trade."""
    global prediction_bot
    try:
        # Reject oversized payloads (max 64 KB)
        if request.content_length and request.content_length > 65536:
            return jsonify({'error': 'payload too large'}), 413

        body = request.get_json(force=True, silent=True) or {}
        # Also accept plain-text alerts (TV sometimes sends text)
        if not body:
            raw = request.data.decode('utf-8', errors='ignore').strip()
            if len(raw) > 65536:
                return jsonify({'error': 'payload too large'}), 413
            # Try to parse key=value or JSON-like
            try:
                import json as _j
                body = _j.loads(raw)
            except Exception:
                body = {'raw': raw[:500]}  # cap raw string stored in body

        symbol     = str(body.get('symbol', '')).upper().strip()[:20]  # cap field lengths
        signal     = str(body.get('signal', '')).upper().strip()   # BULLISH / BEARISH
        strategy   = str(body.get('strategy', 'TradingView'))
        timeframe  = str(body.get('timeframe', '15m'))
        confidence = int(body.get('confidence', 75))
        raw_msg    = body.get('raw', '')

        received_at = datetime.now(timezone.utc).isoformat()
        logger.info(f"[TV-ALERT] {symbol} {signal} | {strategy} {timeframe} | conf={confidence}% | raw={raw_msg}")

        # Persist to tv_alerts.json
        entry = {
            'timestamp': received_at,
            'symbol': symbol,
            'signal': signal,
            'strategy': strategy,
            'timeframe': timeframe,
            'confidence': confidence,
            'raw': raw_msg,
            'traded': False,
            'trade_result': None,
        }
        try:
            alerts = []
            if os.path.exists(TV_ALERTS_FILE):
                with open(TV_ALERTS_FILE, 'r', encoding='utf-8') as f:
                    alerts = json.load(f)
            alerts.append(entry)
            # Keep last 500
            alerts = alerts[-500:]
            with open(TV_ALERTS_FILE, 'w', encoding='utf-8') as f:
                json.dump(alerts, f, indent=2)
        except Exception as e:
            logger.warning(f"[TV-ALERT] Could not save alert: {e}")

        # Auto-trade if bot is live, symbol valid, signal valid
        trade_result = None
        if (prediction_bot and prediction_bot.wallet_live
                and symbol in ['BTC', 'ETH', 'SOL', 'XRP', 'DOGE', 'HYPE', 'BNB']
                and signal in ['BULLISH', 'BEARISH']
                and prediction_bot.auto_buy_enabled):

            analysis = {
                'signal': signal,
                'confidence': confidence,
                'indicators': {'strategy': strategy, 'sub_strategy': 'TVWebhook'},
                'reasons': [f'TradingView alert: {strategy} {timeframe}'],
                'current_price': 0,
                'timeframe': timeframe,
            }

            if timeframe == '5m':
                next_5m = prediction_bot.get_current_5min_timestamp() + 300
                trade_result = prediction_bot.place_prediction_fast(symbol, analysis, target_cycle=next_5m)
            else:
                trade_result = prediction_bot.place_prediction(symbol, auto_trade=True, force_trade=True)

            entry['traded'] = True
            entry['trade_result'] = trade_result
            logger.info(f"[TV-ALERT] Trade result: {trade_result}")

        return jsonify({'received': True, 'symbol': symbol, 'signal': signal,
                        'traded': entry['traded'], 'result': trade_result})

    except Exception as e:
        logger.error(f"[TV-ALERT] Webhook error: {e}")
        return jsonify({'received': False, 'error': str(e)}), 500


@app.route('/api/tv-alerts', methods=['GET'])
def get_tv_alerts():
    """Return logged TradingView alerts."""
    try:
        if os.path.exists(TV_ALERTS_FILE):
            with open(TV_ALERTS_FILE, 'r', encoding='utf-8') as f:
                alerts = json.load(f)
            return jsonify(alerts[-200:])  # last 200
        return jsonify([])
    except Exception as e:
        return jsonify({'error': str(e)})